We now embark in the quest for a set of properties ensuring that an $\restri{}$-local rule $A_{(-)}$ generates only consistent space-time diagrams.
We start with two properties.
The first one asks for timetags to only increase. 
The second one, akin to strong confluence or sequential independence in parallel graph transformations, states that a set of independent rule applications on a graph $G$ applied in any order should always lead to the same graph.
%
\begin{definition}[Time-increasing commutative local rules] A local rule $A_{(-)}$ is
\begin{itemize}
    \item \emph{time-increasing} 
    iff $\forall t.y \in V_G,\,\forall t'.y\in V_{A_x G},\;t \leq t'\text{, with }t<t' \textit{ if } y=x$;
    \item \emph{commutative} iff $\forall x,y \in \X(\Past( G)),\;A_x A_y (G) = A_y A_x (G)$.
\end{itemize}
\end{definition}
%
These properties place strong constraints on past vertices of a space-time diagram $\mathcal{M}_A(G)$: they entail weak consistency. Moreover each space-like cut is determined by its set of past elements.

\begin{restatable}{proposition}{weakconsistency}{\bf (Obtaining weak consistency).}\label{prop:weakconsistency}
    Let $A_{(-)}$ be a time-increasing commutative local rule. For all graphs $G$, $\mathcal{M}_A(G)$ is weakly consistent.
\end{restatable}
\withproofs{
\begin{proof}
    See Sec.\ref{proof : weak consistency}.
\end{proof}}

\begin{restatable}{proposition}{unicut}{\bf (Pasts determine space-like cuts)}\label{lemma : Unicity of space-time cuts}
    Let $A_{(-)}$ be a time-increasing commutative local rule. Let $G$ be a graph. Let $H,J\in \mathcal{M}_A(G)$. If $\Past(J) = \Past(H)$ then $J=H$.
\end{restatable}
\withproofs{
\begin{proof}
    See Sec.\ref{proof : unicut}.
\end{proof}}

