\section{Valid sequences and commutative local-rule}

We notice that a past vertex must remains so, hence the well-definiteness of commutativity. 
\begin{lemma}[Validity of commutativity]\label{lem:2valid}\label{cor:commutativity}
    Let $A$ be a (not necessarily commutative) local rule, $G$ be a graph and $x, y \in \X(\Past(G))$.
    The sequence $yx$ is valid in $G$. Moreover, if A is \emph{commutative}, $A_{xy}G=A_{yx}G$.
\end{lemma}
\begin{proof}
    As there exists no path to $y$ in $G$, the reachability condition of neighbourhood schemes implies that $y \notin \restr{x}{G}$.
    By $\restri{}$-locality $A_x$ cannot add any incoming edge to $y$ which implies $y\in \X(\Past(A_{x} G))$, i.e. $yx$ is valid as wanted.  
\end{proof}

\begin{lemma}[*-validity of commutativity]\label{lemma : right commuting of a past vertex}
    Let $A$ be a commutative local rule.
    Let $\alpha$ be a valid sequence in $G$.
    Let $x\in \X(\Past(G))$ such that $x\notin \alpha$.
    We have $x\alpha$ and $\alpha x$ are valid in $G$ and $A_{x\alpha}G=A_{\alpha x}G$.
\end{lemma}
\begin{proof}
    We proceed by induction on the size of $\alpha$.
    When $|\alpha| = 0$ it is immediate.
    Let us suppose $\alpha = y\beta$.
    By induction hypothesis, we known that (1) $x\beta$ is valid in $G$, (2) $\beta x$ is valid in $G$ and (3) $A_{x\beta}G=A_{\beta x}G$.
    By (1), we have $x\in \X(\Past(A_\beta G))$.
    Since $\alpha = y\beta$ is supposed to be valid, we also have $y \in \X(\Past(A_{\beta}G))$.
    But Lem. \ref{cor:commutativity} tells us that $xy$ and $yx$ are both valid in $A_\beta G$ and $A_{xy}(A_\beta G)=A_{yx}(A_\beta G)$.
    Thus $xy\beta$ and $yx\beta$ are valid in $G$ and $A_{xy\beta} G= A_{yx\beta} G = A_{y}(A_{x\beta} G)$.
    Combining this with (2) and (3) finishes the induction and the proof.
\end{proof}
The two-letters commutativity condition is equivalent the ability to permute all letters of a valid sequence.
\begin{lemma}[$*$-commutation]\label{lemma : *-commutation}
    Let $A_{(-)}$ be a commutative local rule. Let $\omega$ be a valid sequence in $G$ and $\omega'$ be a permutation of $\omega$ also valid in $G$. We have 
    $$A_\omega G = A_{\omega'} G$$
\end{lemma}

\begin{proof}
    Let us denote $\omega = x_{n} \dots x_2 x_1$.
    We prove by induction that for all $i \in \{0,\dots,n\}$,
    $$A_{\omega'} G = A_{\beta}A_{x_i\dots x_1}G,$$
    with $\beta$ a permutation of $x_{n} \dots x_{i+1}$.
    The case $i=0$ is verified with $\beta = \omega'$.
    When $i= j+1$ we have $A_{\omega'} G = A_{\beta}A_{x_j\dots x_1}G$.
    By validity of $\omega$, we know that $x_{j+1} \in \X(\Past(A_{x_j\dots x_1} G))$.
    Consider the decomposition $\beta = \beta''x_{j+1}\beta'$ with $x_{j+1} \notin \beta'$. Lem. \ref{lemma : right commuting of a past vertex} applied to $\beta'$ and $x_{j+1}$ in the graph $A_{x_j\dots x_1} G$ gives us $A_{\omega'} G = A_{\beta''\beta'}A_{x_{j+1}\dots x_1}G$ as needed to finish the induction.
\end{proof}

\section{Weak consistency}

For the next proof we will need a notation for the rightmost sequence subtraction. Let $\omega\in \mathcal{X}^*$ and $\alpha \in \mathcal{X}^*$. We define recursively $(\omega \setminus \alpha)\in \mathcal{X}^*$ as:
\begin{equation*}
    \omega \setminus \alpha =
    \begin{cases}
        \omega & \text{if } |\alpha| = 0, \\
        \omega''\omega' & \text{if } |\alpha| = 1, \omega = \omega''\alpha\omega', \text{ and } \alpha \notin \omega'\\
        (\omega \setminus x) \setminus \alpha' & \text{if } \alpha = \alpha' x \text{ and } x \in \mathcal{X}.
    \end{cases}
\end{equation*}
For example if $\mathcal{X} = \{0,\dots ,9\}$, $\omega = 22159892$ and $\omega' = 28542$ we have 
$\omega\setminus \omega' = 2199$.
This operation preserves validity. 
\begin{lemma}[Validity of sequence substraction]\label{lemma : validity of omega - omega'}
    Let $A_{(-)}$ be a commutative local rule. Let $\omega$ and $\omega'$ be valid sequences. Then the sequence $\omega \setminus \omega'$ is valid in $A_{\omega'}G$. 
\end{lemma}

\begin{proof}
    We proceed by induction on the size of $\omega'$.
    It is immediate when $\omega'$ is empty.
    When $\omega' = x \alpha$, the validity of $\omega'$ gives us that $x\in \X(\Past(A_\alpha G))$.
    The induction hypothesis is that $\omega \setminus \alpha$ is valid in $A_{\alpha}G$.
    Taking $\omega \setminus \alpha = \gamma\beta$ with $\beta$ the longest suffix of $\omega \setminus \alpha$ such that $x \notin \beta$, we have $\beta$ valid in $A_{\alpha}G$.

    We can use Lem. \ref{lemma : right commuting of a past vertex} on $\beta$ and $x$ in $A_\alpha G$ to get validity of $\beta$ in $A_{x \alpha}G$ and $A_{x \beta \alpha} G = A_{\beta x \alpha}G$.
    If $\gamma = \varepsilon$ we can conclude immediately.
    Otherwise we have $\gamma = \beta' x$.
    Since $\beta'$ is valid in $A_{x \beta \alpha} G $ it is also valid in $A_{ \beta x\alpha} G $. This finishes to prove validity of $\beta' \beta = \omega\setminus x\alpha$ in $A_{x \alpha} G$.
\end{proof}
Whilst confluence is not the primary aim of this paper, we obtain it as a corollary. 
\begin{corollary}[Confluence]\label{lemma : confluence}
    Let $A_{(-)}$ be a commutative local rule. Let $\omega$ and $\omega'$ be valid sequences. Then the sequences $\omega'\setminus \omega$ and $\omega \setminus \omega'$ are valid respectively in $A_\omega G$ and $A_{\omega'}G$. This enforces:
    $$A_{(\omega'\setminus \omega)}A_\omega G = A_{(\omega\setminus \omega')}A_{\omega'} G$$
\end{corollary}
\begin{proof}
    We get each validity by one application of Lem. \ref{lemma : validity of omega - omega'}. Then we get the equality by applying Lem. \ref{lemma : *-commutation}.
\end{proof}


In any space-time diagram ${\cal M}_A(G)$ for $A$ time-increasing commutative, the state of a past vertex is well-determined.  

\begin{lemma}[Common past vertices have been equally updated]\label{lemma : common past vertices}
    Let $A_{(-)}$ be a time-increasing commutative local rule. Let $\omega$ and $\omega'$ be valid sequences in $G$. If there exists $t.x \in \Past(A_\omega G) \cap \Past(A_{\omega'}G)$ then $\omega'$ contains as much $x$ as $\omega$. 
\end{lemma}

\begin{proof}
    We suppose without loss of generality that there is at least as much $x$ in $\omega'$ than in $\omega$. Then because $x\notin (\omega \setminus \omega')$ and $t.x\in \Past(A_{\omega'}G)$ we have $t.x\in \Past(A_{(\omega\setminus\omega')\omega'}G)$. Using Lem.~\ref{lemma : confluence} this implies $t.x\in \Past(A_{(\omega'\setminus\omega)\omega}G)$. Since $t.x\in \Past(A_\omega G)$ this implies by the time-increasing condition that $\omega' \setminus \omega$ does not contain any $x$.
\end{proof}


\weakconsistency*\label{proof : weak consistency}
\begin{proof}
    Let $\omega$ and $\omega'$ be valid sequences in $G$. Let $t.x \in \Past(A_\omega G)\cap \Past(A_{\omega'}G)$.
    Lem.~\ref{lemma : common past vertices} tells us that there is as much $x$ in $\omega'$ than in $\omega$.
    This means $x\notin (\omega \setminus \omega')$ and $x\notin (\omega' \setminus \omega)$.
    Then, using locality and Lem.~\ref{lemma : confluence}, we get the following equalities
     $$(A_{\omega'}G)_{t.x} = (A_{(\omega \setminus \omega') \omega'}G)_{t.x}=(A_{(\omega'\setminus \omega) \omega}G)_{t.x}= (A_{\omega}G)_{t.x}.$$
\end{proof}


Moreover, in any space-time diagram ${\cal M}_A(G)$ for $A$ time-increasing commutative, fixing set of past vertices fixes the entire space-like cut. 


\unicut*\label{proof : unicut}

\begin{proof}
    We consider two graphs $A_\omega G$ and $A_{\omega'}G$ such that $\Past(A_\omega G) = \Past(A_{\omega'}G)$. Let us prove by contradiction that $\omega \setminus \omega'$ is empty. We suppose it non empty and call $x$ its right-most letter. Then validity (coming from Lem.~\ref{lemma : confluence}) gives us $t.x\in \Past(A_{\omega'}G) = \Past(A_\omega G)$.
    By Lem.~\ref{lemma : common past vertices}, we have that $\omega$ and $\omega'$ contains as much $x$ as the other.
    So $\omega \setminus \omega'$ does not contain $x$, a contradiction.

    Thus we have $\omega \setminus \omega' = \emptyset$. Symmetrically $\omega'\setminus \omega = \emptyset$.
    Using Lem.~\ref{lemma : *-commutation} this proves $A_\omega G = A_{\omega'} G$.
\end{proof}





\section{Full consistency}

 The two hypotheses of Th.~\ref{Th : General Case Consistency} ($\restri{}$-locality and the port decreasing condition) handle only size $1$ valid sequences. In order to prove the theorem we first have to establish that the two hypotheses for any valid sequence. We start by extending the notion locality, to account not just for a single position, but valid sequences of them.
\begin{definition}[$*$-$\restri{}$-Locality]
    Consider a neighbourhood scheme $\restri{}$. An operator $A_{(-)}$ is said to be $\omega$-$\restri{}$-local iff, for all $G$ for which $\omega\in \Omega_G(A)$ we have
    $$A_\omega G = A_\omega (G_\restri{\omega}) \sqcup G_\crestri{\omega}.$$
    An operator said to be $\restri{}$-local iff this holds for any $\omega\in \Omega_G(A)$ such that $|\omega|=1$, we then say it is a local rule. It is said to be $*$-$\restri{}$-local if this holds for any $\omega\in \Omega_G(A)$. 
\end{definition}
Let us prove that any $\restri{}$-local operator for an extensive and monotonous neighbourhood scheme is also $*$-$\restri{}$-local.
\begin{lemma}[$\restri{}\subseteq X$-locality implies $X$-locality]\label{lemme : petit local implique grand local version générale}
    Consider an extensive neighbourhood scheme $\restri{}$, a graph $G$ and $\omega \in \mathcal{X}^*$, and any set $X\subseteq \mathcal{X}$ such that $\restr{\omega}{G}\subseteq X$. If $A_{(-)}$ is $\omega$-$\restri{}$-local then we have:
    $$A_\omega G = (A_\omega G_{X})\sqcup G_{\overline{X}}$$
\end{lemma}
\begin{proof}
In order to lighten the notations of this proof we temporarily write $\restri{}$ instead of $\restri{\omega}$.
By extensivity of $\restri{}$, $G_{\restr{}{G}}\sqsubseteq G_{X} \sqsubseteq G$ implies $\restr{}{G}=\restr{}{G_{X}}$.
\begin{align*}
    A_\omega G_{X}&= A_\omega G_{X{}\restr{}{G_{X}}}\sqcup G_{X{}\crestr{}{G_{X}}}\\
    &= A_\omega G_{X{}\restr{}{G}}\sqcup G_{X\crestr{}{G}}\textrm{ by extensivity}\\
    &= A_\omega G_{\restr{}{G}}\sqcup G_{X\cap\crestr{}{G}}\textrm{ since }\restr{}{G}\subseteq X\\
    A_\omega G_{X}\sqcup G_{\overline{X}}&=A_\omega G_{\restr{}{G}}\sqcup G_{X\cap\crestr{}{G}} \sqcup G_{\overline{X}}\\
    &=A_\omega G_{\restr{}{G}}\sqcup G_{X\cap\crestr{}{G}} \sqcup G_{\overline{X}\cap\crestr{}{G}} \textrm{ since } \overline{X}\subseteq\crestr{}{G}\\
    &=A_\omega G_{\restri{}(G)}\sqcup G_{\crestri{}(G)}\\
    &= A_\omega G
\end{align*}
\end{proof}



\begin{lemma}[$\restri{}$-locality implies $*$-$\restri{}$-locality]\label{lem:extloc}
    If an operator $A_{(-)}$ is $\restri{}$-local for a monotonous and extensive neighbourhood scheme $\restri{}$, then it is also $*$-$\restri{}$-local.
\end{lemma}
\begin{proof}
    By recurrence on the size of $\omega$. The base case $\omega=u$ is $\restri{}$-locality. Let $\omega = \beta \alpha$ with $\beta,\alpha$ non-empty. By monotony we have that for all $G$, $\restr{\alpha}{G}\subseteq \restr{\omega}{G}$. We can thus use Lem.~\ref{lemme : petit local implique grand local version générale} to get:  
\begin{align*}
A_\alpha G &= (A_\alpha G_{\restri{\omega}})\sqcup G_{\crestri{\omega}} \\
A_\beta A_\alpha G &= A_\beta ((A_\alpha G_{\restri{\omega}})\sqcup G_{\crestri{\omega}})
\end{align*}
By monotony we also have that $\restr{\beta}{A_\alpha G} \subseteq \restr{\omega}{G}$. We can thus use Lem.~\ref{lemme : petit local implique grand local version générale} again with $X = \restr{\omega}{G}$: 
\begin{align*}
A_\beta A_\alpha G &= \left(A_\beta \left(((A_\alpha G_{\restri{\omega}}) \sqcup G_{\crestri{\omega}})_{ \restr{\omega}{G}}\right)\right) \sqcup ((A_\alpha G_{\restri{\omega}})\sqcup G_{\crestri{\omega}})_{\overline{ \restri{\omega}}(G)} \\
&= \left(A_\beta \left(((A_\alpha G_{\restri{\omega}}) \phantom{ \sqcup G_{\crestri{\omega}}})_{ \restr{\omega}{G}}\right)\right) \sqcup (( \phantom{A_\alpha G_{\restri{\omega}}) \sqcup }G_{\crestri{\omega}})_{\overline{ \restri{\omega}}(G)}\textrm{ by 
Rk~\ref{rk:locality excludes borders}} \\
&=(A_\beta A_\alpha G_{\restri{\omega}}) \sqcup  G_{\crestri{\omega}}
\end{align*}
\end{proof}






In a similar manner we can define $*$-port decreasing operators, by considering any valid sequence $\omega$, i.e. applying $A_\omega$ instead of $A_u$ in definition~\ref{definition : Port Decreasing}. Let us show that any port decreasing operator for a monotonous neighbourhood scheme is also $*$-port decreasing.

\begin{remark}\label{Remark : Useful decomposition}

    The LHS of the port-decreasing condition (Def.~\ref{definition : Port Decreasing}) could have simply been written $\pof\E_G(\preci{\omega},x)$. The RHS however divides up into remainder originally private edges and new edges, i.e.
    $\pof\big((\E_{A_\omega G}(x)\cap\E_G(\preci{\omega},x))\, \uplus\, (\E_{A_\omega G}(x)\setminus\E_G(x))\big)$.\\
    Thus a way of understanding the port decreasing condition is the following: the subset of $\P_{A_u G}(x)$ containing  the remainder originally private ports and the new ports must be smaller than the originally private ports.
\end{remark}





\begin{restatable}{lemma}{omegaPD}{\bf (Port decreasing implies $*$-port decreasing)}\label{lemma : omega port decreasing} If $A_{(-)}$ is port decreasing for a monotonous neighbourhood scheme $\restri{}$, then $A_{(-)}$ is $*$-port decreasing for $\restri{}$.
\end{restatable}

\begin{proof}
    We show this by complete induction on the length of $\omega$.

    If $\omega$ contains only one letter it comes directly from Def.~\ref{definition : Port Decreasing}.

    Otherwise we write $\omega = \beta \alpha$ with $\beta$ and $\alpha$ non empty. We want to show that $A_\omega$ is port decreasing--- i.e. $$\Px{G_\preci{\omega}} > (\Px{A_\omega G}\cap \Px{G_\preci{\omega}})\cup (\Px{A_\omega G} 
 \setminus \Px{G}). $$
by supposing $A_\alpha$ and $A_\beta$ port-decreasing.

    We proceed in two steps, we will prove these inequalities:
%
    $$\pof(\E_G(x)\setminus\E_G(\cpreci{\omega},x)) > \pof(\E_{A_\alpha G}(x)\setminus\E_G(\cpreci{\omega},x)) >  \pof(\E_{A_\omega G}(x)\setminus\E_G(\cpreci{\omega},x)) $$

    We start by the left inequality. Using Rk~\ref{Remark : Useful decomposition}, the LHS is equal to $\E_G(\preci{\omega},x)$. Using $\restri{\alpha}\subseteq\restri{\omega}$ as stated by monotony, we decompose it according to privacy along $\alpha$.
%    
    $$\E_G(\preci{\omega},x) =\E_G(G_\preci{\alpha},x) \uplus {(\E_G(G_\preci{\omega})\setminus\E_G(G_\preci{\alpha},x))} $$


    Using Rk~\ref{Remark : Useful decomposition}, the RHS is equal to

    $$ (\E_{A_\alpha G}(x)\cap\E_G(\preci{\omega},x)) \uplus (\E_{A_\alpha G}(x) \setminus\E_G(x))   $$

    We also decompose the RHS according to privacy along $\alpha$, using the same formula, and obtain:

 \begin{align*}
 &\big(\E_{A_\alpha G}(x)\cap  (\E_G(\preci{\alpha},x) \uplus {(\E_G(\preci{\omega})\setminus\E_G(\preci{\alpha},x))})   \big) \uplus (\E_{A_\alpha G}(x) \setminus\E_G(x))\\
 &= (\E_{A_\alpha G}(x)\cap\E_G(\preci{\alpha},x)) \uplus \big(\E_{A_\alpha G}(x)\cap{(\E_G(\preci{\omega})\setminus\E_G(\preci{\alpha},x))}  \big) \uplus (\E_{A_\alpha G}(x) \setminus\E_G(x))\\
\end{align*}

The following inequality holds because one set is included in the other: 
$$\pof\left({(\E_G(\preci{\omega})\setminus\E_G(\preci{\alpha},x))}\right) \geq \pof \left(\E_{A_\alpha G}(x)\cap{(\E_G(\preci{\omega})\setminus\E_G(\preci{\alpha},x))}\right)$$
The remaining part of the LHS is also greater than the remaining part of the RHS
$$
\pof\left(\E_G(\preci{\alpha},x)\right)  > \pof\left(
(\E_{A_\alpha G}(x)\cap\E_G(\preci{\alpha},x)) \uplus (\E_{A_\alpha G}(x) \setminus\E_G(x)) \right)
$$
because this is the Rk~\ref{Remark : Useful decomposition} version of the $A_\alpha$ port-decreasing recurrence hypothesis. Since the order is monotonous, this implies that the LHS is greater than the RHS.

Secondly we prove the right inequality. First we notice 
$$\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)\setminus\E_G(\cpreci{\omega}(G),x)=E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x).$$
because by monotony $\preci{\beta}(A_\alpha G)\subseteq  \preci{\omega}(G)$, thus $\preci{\beta}(A_\alpha G)\setminus \cpreci{\omega}(G) = \preci{\beta}(A_\alpha G)$.



We can therefore decompose the LHS of the right inequality as 
\begin{align*}
   \E_{A_\alpha G}(x)\setminus\E_G(\cpreci{\omega},x) &=  (\E_{A_\alpha G}(\preci{\beta}(A_\alpha G)) 
 \setminus\E_G(\cpreci{\omega},x))\uplus (\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G))   \setminus\E_G(\cpreci{\omega},x) ) \\
 &= \E_{A_\alpha G}(\preci{\beta}(A_\alpha G))\uplus (\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G))   \setminus\E_G(\cpreci{\omega},x) ) 
\end{align*}
We now decompose the RHS:
\begin{align*}
 \E_{A_\omega G}(x)&=(\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(x)) \uplus ((\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x))  \\
 &=(\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)) \\
   &\uplus (\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G),x)) \\
   &\uplus (\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x)) \\
  \E_{A_\omega G}(x) \setminus \E_G(\cpreci{\omega},x) &=(\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)) \setminus \E_G(\cpreci{\omega},x)\\
   &\uplus (\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G),x)) \setminus \E_G(\cpreci{\omega},x)\\
   &\uplus (\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x))\setminus \E_G(\cpreci{\omega},x)\\
\E_{A_\omega G}(x) \setminus \E_G(\cpreci{\omega},x) &=E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)\\
   &\uplus (\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G),x)) \setminus \E_G(\cpreci{\omega},x)\\
   &\uplus (\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x))\setminus \E_G(\cpreci{\omega},x)\\
\end{align*}
 The following inequality holds because one set is included in the other:
 $$
\pof\left(\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G))   \setminus\E_G(\cpreci{\omega},x)\right)  > \pof\left((\E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\cpreci{\beta}(A_\alpha G),x)) \setminus \E_G(\cpreci{\omega},x)\right)
$$
Now by the Rk~\ref{Remark : Useful decomposition} version of the $A_\beta$ port-decreasing recurrence hypothesis: 
\begin{align*}
   \E_{A_\alpha G}(\preci{\beta}(A_\alpha G)) 
    >&\ \E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)\\
    &\uplus\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x)\\
    \geq&\ \E_{A_\omega G}(x)\cap\E_{A_\alpha G}(\preci{\beta}(A_\alpha G),x)\\
    &\uplus (\E_{A_\omega G}(x)\setminus\E_{A_\alpha G}(x))\setminus \E_G(\cpreci{\omega},x)
\end{align*}
Since the order is monotonous, this implies that the LHS is greater than the RHS.
\end{proof}


\begin{remark}\label{Remark : signification of strict inequality}
    If we have a strict inequality between two sets of ports $A$ and $A'$ for an inclusive order then the bigger set $A'$ necessarily contains at least one element which does not belong to $A$ i.e.:
    $$A>A' \Longrightarrow \exists p\in A,\ p\notin A  $$
    Indeed otherwise we would have $A\subseteq A'$ which would imply the contradiction $A \leq A'$.
\end{remark}

We are now ready to tackle the case of disjoint sequences of the main theorem. 
\begin{proposition}[Disjoint case]\label{Lemma : Consistency , Disjoint case, radius R}
    Let $\restri{}$ be a private extensive monotonous neighbourhood scheme.
    Let $A_{(-)}$ be a time-increasing and commutative $\restri{}$-local rule. Let $G$ be a graph. Let $\omega,\omega'\in \Omega_G(A)$. If $\omega\cap\omega'=\emptyset$ and $A_{(-)}$ is port decreasing, then $A_{\omega}G\ \varparallel\ A_{\omega'}G$.
\end{proposition}

\begin{proof}
    Let us show consistency around $u \in \V_{ A_{\omega'}G}\cap \V_{A_{\omega}G}$.

    First we notice that $u$ must be a vertex of $G$. Indeed, due to 
    Rk~\ref{rk:locality excludes borders}
    vertices of $A_{\omega}G$ are either vertices of $G$ or of the form $(t+\Delta t).x$ with $\Delta t>0$ and $t.x\in V_G$. If $u = (t+\Delta t).x$, then by $*$-$\restri{}$-locality (comming from Lem.~\ref{lem:extloc}) and again Rk~\ref{rk:locality excludes borders}, $x$ belongs to $\preci{\omega}(G)\cap \preci{\omega'}(G)$. This contradicts privacy of $\restri{}$.

    There are three cases:
    \begin{itemize}
        \item The neighbourhood of $u$ is not modified by $A_\omega$ and neither by $A_{\omega'}$, i.e. $( A_\omega G)_{u}= G_u = ( A_{\omega'} G)_{u}$. This immediately implies consistency.
        \item Case $( A_\omega G)_{u}^0\neq G_u$.  We start by decomposing $\E_G(u)$ according to $\omega$ and $\omega'$ privacy:
        $$\E_G(u) =\E_G(\preci{\omega},u) \uplus\E_G(\preci{\omega'},u) \uplus (\E_G\setminus \E_G(\preci{\omega}\cup\preci{\omega'},u) )).$$
        Indeed since $\restri{}$ is private we have $\preci{\omega}\cap \preci{\omega'} =\emptyset$, therefore this decomposition is a partition. Moreover by $*$-$\restri{}$-locality and Rk~\ref{rk:locality excludes borders}, $A_{\omega'}$ cannot modify the private edges of $\omega$:
        $$\E_G(\preci{\omega},u) \subseteq\E_{A_{\omega'}G}(u).$$
        Since $A_\omega$ is $*$-port-decreasing, the action of $A_{(-)}$ gives us the following equations:
          $$\pof(\E_G(u)\setminus\E_G(\cpreci{\omega},u)) > \pof(\E_{A_\omega G}(u)\setminus\E_G(\cpreci{\omega},u)) $$
        This implies by Rk~\ref{Remark : signification of strict inequality} the existence of a port $p\in \pof(\E_G(\preci{\omega},u))$ such that $p\notin \pof(\E_{A_\omega G}(u)\setminus\E_G(\cpreci{\omega},u))$. Since $A_{\omega'}$ cannot modify private edges of $\omega$ we also have $p\in \P_{A_{\omega'}G}(u)$ and since ports are never repeated $p\notin\E_G(\cpreci{\omega},u))$ thus $p\notin \pof \Em_{A_\omega G}(u)$.
        Since  $p\in \P_{A_{\omega'}G}(u)$ and $p\notin \pof \Em_{A_\omega G}(u)$ the sets differ: consistency is ensured by dismissal of its premise.
         \item Case $( A_{\omega'} G)_{u}\neq G_u$ is symmetrical.
    \end{itemize}
\end{proof}


\generalcase*\label{proof : General Case Consistency annex}


\begin{proof}
    Let $\omega$ and $\omega'$ be valid sequences in $G$. Let us prove that $A_{\omega}G\ \varparallel\ A_{\omega'}G$.

    We show this result by strong recurrence on the length of $\omega$ and $\omega'$. Let us suppose that this property holds for all words of size smaller or equal to $n$. Let $\omega$ and $\omega'$ be words of size at most $n+1$.

    If $\omega \cap \omega'=\emptyset$ the result follows from Lem.~\ref{Lemma : Consistency , Disjoint case, radius R}.

    Otherwise we call $x\in\omega\cap\omega'$, a position such that:
    $$\omega = \omega_2 x \omega_1 \text{ s.t. } x \notin \omega_1$$
    $$\omega' = \omega_2' x \omega_1' \text{ s.t. } x \notin \omega_1'$$
    $$\omega_1 \cap \omega_1'=\emptyset$$

    First we prove that $x\in \X(\Past(G))$. 
    If $x\notin \X(\Past(G))$ we would have by validity of $\omega$ that $x\in X (\Past(A_{\omega_1}G))\setminus \X(\Past(G))$ which implies that $G_x\neq (A_{\omega_1} G)_x$. 
    Since $A_{\omega_1}$ is $*$-$\restri{}$-port-decreasing, there exists $e=(u\!:a, t.x\!:b)\in\E_G(\preci{\omega_1},x)$. By privacy $\preci{\omega_1}\cap \restri{\omega'_1}=\emptyset$ and so $u\notin I_{G_{\restri{\omega_1'}}}$. Thus $e$ is at best a border edge in $G_{\restri{\omega_1'}}$. By locality and Rk~\ref{rk:locality excludes borders} this edge cannot be modified by $A_{\omega_1'}$. But by validity of $A_{\omega'}$, we have $x\in \X(\Past(A_{\omega'_1}G))$ meaning that $e$ was removed, a contradiction.


    Now we can apply Lem. \ref{lemma : right commuting of a past vertex} on $\omega_1$ and $x$ to get
    $$A_\omega G = A_{\omega_2}A_{\omega_1}A_xG.$$
    Similarly,
    $$A_{\omega'} G= A_{\omega_2'}A_{\omega_1'}A_xG$$
    which concludes the proof because we can apply the induction hypothesis on $A_x G$.
\end{proof}

