\subsection{Symmetric case} \label{ssec:symm}
Let $X \sim \mcN(0, \Sigma)$ be a zero-mean Gaussian random vector in $\R^d$ with covariance matrix $\Sigma,$  and let $X_1, \ldots, X_N$ be i.i.d. copies of $X$. Let $p$ be an even integer. Our goal is to estimate the  $p$-th  order moment tensor
\begin{align*}
    T :=  \E X^{\otimes p} := \E X \otimes \cdots \otimes X,
\end{align*}
which is the expectation of the $p$-fold tensor product of $X$.

A natural estimator is the sample moment estimator $\widehat{T}_S$, defined by
\[
\widehat{T}_S:=\frac{1}{N} \sum_{i=1}^N X_i^{\otimes p}.
\]
Entrywise, this corresponds to
\begin{align*}
\big(\widehat{T}_S\big)_{\ell_1, \ldots, \ell_p} 
:= \frac{1}{N} \sum_{i=1}^N X_{i, \ell_1} \cdots X_{i, \ell_p},
\end{align*}
where $X_{i, \ell}$ denotes the $\ell$-th coordinate of $X_i.$
Alternatively,
Isserlis's theorem \cite{isserlis1918formula} (also known as Wick's probability theorem \cite{wick1950evaluation}) provides an exact expression for Gaussian moment tensors in terms of second-order moments. Specifically, for any multi-index $(\ell_1,\dots, \ell_p),$
\begin{align*}
(\E X^{\otimes p})_{\ell_1, \dots, \ell_p} 
=
\E[X_{\ell_1} \cdots X_{\ell_p}] = 
\sum_{\pi \in \Pi^2_p} \prod_{(j,k) \in \pi} \Sigma_{\ell_j, \ell_k},
\end{align*}
where $\Pi^2_p$ is the set of all pairwise partitions of $\{1, \dots, p\}$. This motivates Isserlis’s estimator, which substitutes the sample covariance \begin{align*}
\hatSigma := \frac{1}{N} \sum_{i=1}^N X_i X_i^\top
\end{align*}
into the same expression.  The resulting estimator is given entrywise by 
\begin{align*}
\big(\widehat{T}_I\big)_{\ell_1, \ldots, \ell_p} := 
\sum_{\pi \in \Pi^2_p} \prod_{(j,k) \in \pi}
\hatSigma_{\ell_j, \ell_k}.
\end{align*}
Using the notion of induced likelihood \cite{zehna1966invariance},
the plug-in estimator $\widehat{T}_I$ can be interpreted as the maximum likelihood estimator of $T.$

Theorem \ref{thm:IsserlissBest} compares the performance of the two estimators, $\widehat{T}_{S}$ and $\widehat{T}_I$, under both the operator norm and the entrywise maximum norm.
\begin{theorem}\label{thm:IsserlissBest}
    Using the notation above, the following bounds hold:
    \smallskip

    \noindent    (i) Operator norm bounds:
    \begin{align*}
     \E \normn{\widehat{T}_S- T} 
     &\asymp_p \|\Sigma\|^{p/2} \bigg(\sqrt{\frac{r_2(\Sigma)}{N}}+\frac{r_2(\Sigma)^{p/2}}{N}\bigg),\\
     \E \normn{ \widehat{T}_I- T} 
     &\lesssim_p \|\Sigma\|^{p/2} \bigg(\sqrt{\frac{r_2(\Sigma)}{N}}+\bigg(\frac{r_2(\Sigma)}{N}\bigg)^{p/2}\bigg).
    \end{align*}
    \noindent    (ii) Entrywise maximum norm bounds:
    \begin{align*}
     \E \normn{ \widehat{T}_S- T
     }_{\max}
     &\asymp_p \|\Sigma\|_{\max}^{p/2}\bigg(\sqrt{\frac{r_{\max}(\Sigma)}{N}}+\frac{r_{\max}(\Sigma)^{p/2}}{N}\bigg),\\
     \E \normn{\widehat{T}_I - T 
     }_{\max}
     &\lesssim_p 
     \|\Sigma\|_{\max}^{p/2} \bigg(\sqrt{\frac{r_{\max}(\Sigma)}{N}}+\bigg(\frac{r_{\max}(\Sigma)}{N}\bigg)^{p/2}\bigg).
    \end{align*}
\end{theorem}
\begin{proof}

    \textit{(i) Operator norm bounds.} The sample moment estimator bound follows by \cite[Theorem 2.1]{al2025sharp} (see also \cite{abdalla2025dimension}). For $\widehat{T}_I$, by Corollary~\ref{coro:perturbation}, we have
    \begin{align*}
    \frac{\|\widehat{T}_I-T\|}{\|T\|}
    \le \frac{p}{2}\cdot\frac{\|\widehat{\Sigma}-\Sigma\|}{\|\Sigma\|} \bigg(1+\frac{\|\widehat{\Sigma}-\Sigma\|}{\|\Sigma\|}\bigg)^{p/2-1}
    \lesssim_p  
    \frac{\|\widehat{\Sigma}-\Sigma\|}{\|\Sigma\|}+\bigg(\frac{\|\widehat{\Sigma}-\Sigma\|}{\|\Sigma\|}\bigg)^{p/2}.
    \end{align*}
    Further, by \cite[Theorem 4]{koltchinskii2017concentration}, $\E \| \hatSigma - \Sigma\|/\|\Sigma\| \asymp \sqrt{\frac{r_2(\Sigma)}{N}} + \frac{r_2(\Sigma)}{N},$ which can be plugged into the expression in the previous display to give the result.

    \smallskip

   \noindent \textit{(ii) Entrywise maximum norm bounds.} For the sample moment estimator, the upper bound is a direct corollary of Theorem~\ref{thm:IsserlissBest_asymmetry}. The lower bound follows by an analogous argument to the one used in the proof of \cite[Theorem 2.1]{al2025sharp} and is omitted for brevity. For Isserlis's estimator, the bound follows from Corollary~\ref{coro:perturbation}.
\end{proof}

\begin{remark}
    Theorem~\ref{thm:IsserlissBest} shows that consistent estimation of $T$ using the sample moment estimator $\widehat{T}_{S}$ requires a sample size  $N\gg (r_2(\Sigma))^{p/2}$ under the operator norm, or $N\gg (r_{\max}(\Sigma))^{p/2}$ under the entrywise maximum norm. In contrast, consistency of Isserlis's estimator $\widehat{T}_I$ only requires sample size $N\gg r_2(\Sigma)$ or $N\gg r_{\max}(\Sigma)$, leading to a significant reduction in sample complexity.
\end{remark}


\begin{remark}
 \cite[Theorem 3]{munthe2025short} generalizes Isserlis's theorem to isotropic distributions. While beyond the scope of this work, we anticipate the advantage of Isserlis's estimators to extend to that setting. Numerical results in \cite{al2025covarianceB} support this claim.  
\end{remark}



