\subsection{Asymmetric case} \label{ssec:Asymm}

Let $p$ be an even integer, and let $X=(X^{(1)},\ldots,X^{(p)})\in \R^d$ be zero-mean Gaussian random vectors with covariance matrix $\Sigma$, where each block $X^{(k)}\in \R^{d_k}$ and $\sum_{k=1}^{p}d_k=:d$. For each $k\in \{1,\ldots,p\}$, denote the marginal covariance by $\Sigma^{(k)}:=\E X^{(k)}\otimes X^{(k)}$, and the cross-covariance by $\Sigma^{(j,k)}:=\E X^{(j)}\otimes X^{(k)}$.  Let $X_1,\ldots,X_N$ be i.i.d. copies of $X$, where $X_i=(X^{(1)}_i,\ldots,X^{(p)}_i)$. Our goal is to estimate the moment tensor 
\[
T:=\E X^{(1)}\otimes\cdots \otimes X^{(p)},
\]
formed by taking the tensor product over the blocks of $X$.

A natural estimator is the sample moment estimator, defined as
\[
\widehat{T}_S:=\frac{1}{N} \sum_{i=1}^N X_i^{(1)} \otimes \cdots \otimes X_i^{(p)}.
\]
Entrywise, this corresponds to
\begin{align*}
\big(\widehat{T}_S\big)_{\ell_1, \ldots, \ell_p} 
:= \frac{1}{N} \sum_{i=1}^N X^{(1)}_{i, \ell_1} \cdots X^{(p)}_{i, \ell_p},
\end{align*}
where $X^{(k)}_{i, \ell}$ denotes the $\ell$-th coordinate of $X^{(k)}_i.$

Alternatively, by Isserlis's theorem, for any multi-index $(\ell_1,\ldots,\ell_p)$,
\begin{align*}
\big(\E X^{(1)}\otimes\cdots \otimes X^{(p)}\big)_{\ell_1, \dots, \ell_p} =
\E[X^{(1)}_{\ell_1} \cdots X^{(p)}_{\ell_p}] = 
\sum_{\pi \in \Pi^2_p} \prod_{(j,k) \in \pi} \Sigma^{(j,k)}_{\ell_j, \ell_k},
\end{align*}
where $\Pi^2_p$ denotes the set of pairwise partitions of $\{1,\ldots,p\}$. This motivates Isserlis's estimator, which substitutes the sample covariances 
\[
\hatSigma^{(j,k)} := \frac{1}{N} \sum_{i=1}^N X^{(j)}_i (X^{(k)}_i)^\top
\]
into the same expression. The resulting estimator is given entrywise by
\begin{align*}
\big(\widehat{T}_I\big)_{\ell_1, \ldots, \ell_p} := 
\sum_{\pi \in \Pi^2_p} \prod_{(j,k) \in \pi}
\hatSigma^{(j,k)}_{\ell_j, \ell_k}.
\end{align*}

Theorem \ref{thm:IsserlissBest_asymmetry} compares the performance of the two estimators, $\widehat{T}_{S}$ and $\widehat{T}_I$, under both the operator norm and the entrywise maximum norm.

\begin{theorem}\label{thm:IsserlissBest_asymmetry} Using the notation above, the following bounds hold:
\smallskip

   \noindent (i) Operator norm bounds:  \begin{align*}
     \E \|\widehat{T}_S- T\|
     &\lesssim_p \bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|^{1 / 2}\bigg)\Bigg(\bigg(\frac{\sum_{k=1}^p r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+\frac{\prod_{k=1}^{p}(r_2(\Sigma^{(k)})+\log N)^{1/2}}{N}\Bigg),\\
     \E \|\widehat{T}_I- T \| 
     &\lesssim_p\bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|^{1 / 2}\bigg) \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{1/2},\ \ \text{if } \ N\ge \max_{1\le k\le p}r_2(\Sigma^{(k)}).
    \end{align*}
  \noindent    (ii) Entrywise maximum norm bounds:
  \begin{align*}
     \E \|\widehat{T}_S-T\|_{\max}
     &\lesssim_p \!\bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|_{\max}^{1 / 2}\bigg)\Bigg(\bigg(\frac{\sum_{k=1}^p r_{\max}(\Sigma^{(k)})}{N}\bigg)^{1/2}\! \!+\frac{\prod_{k=1}^{p}(r_{\max}(\Sigma^{(k)})+\log N)^{1/2}}{N}\Bigg),\\
     \E \| \widehat{T}_I-T\|_{\max} 
     &\lesssim_p\!\bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|_{\max}^{1 / 2}\bigg) \bigg(\frac{\max_{1\le k\le p}r_{\max}(\Sigma^{(k)})}{N}\bigg)^{1/2},\ \ \text{if } \ N\ge \max_{1\le k\le p}r_{\max}(\Sigma^{(k)}).
    \end{align*}
\end{theorem}

\begin{remark}
    The upper bounds on the deviation of sample moment estimator $\widehat{T}_{S}$ from its expectation are sharp under both the operator norm and entrywise maximum norm when the vectors $X^{(1)},\ldots, X^{(p)}$, together with their samples $(X^{(1)}_i)_{i=1}^{N},\ldots,(X^{(p)}_i)_{i=1}^N$, are mutually independent; see \cite[Theorem 2.1]{chen2025sharp} and Theorem \ref{thm:maximum_asymmetric}.  Consistent estimation of $T$ using the sample moment estimator $\widehat{T}_{S}$ requires a sample size satisfying  
    \[
    N\gg \prod_{k=1}^{p}(r_2(\Sigma^{(k)})+\log N)^{1/2} \quad \text{or} \quad   N\gg \prod_{k=1}^{p}(r_{\max}(\Sigma^{(k)})+\log N)^{1/2}
    \]
    under the operator norm and the entrywise maximum norm, respectively. In contrast, Isserlis's estimator $\widehat{T}_I$ only requires sample size
    \[
    N\gg \max_{1\le k\le p}r_{2}(\Sigma^{(k)}) \quad \text{or} \quad N\gg \max_{1\le k\le p}r_{\max}(\Sigma^{(k)})
    \]
   for consistency under the respective norms, leading to a significant reduction in sample complexity.
\end{remark}


\begin{proof}[Proof of Theorem \ref{thm:IsserlissBest_asymmetry}]

First, for the sample moment estimator $\widehat{T}_{S}$, the upper bound on its deviation from $T$ under the operator norm follows directly from \cite[Theorem 2.1]{chen2025sharp}, while the corresponding bound under the entrywise maximum norm is given by Theorem~\ref{thm:maximum_asymmetric} in this paper. It remains to analyze Isserlis's estimator $\widehat{T}_I$.


We apply the upper bound in Proposition~\ref{prop:perturbation}, which yields
  \[ 
  \|\widehat{T}_I-T\|\le \bigg(\prod_{k=1}^{p}\|\Sigma^{(k)}\|^{1/2}\bigg) (p-1)!! \cdot \frac{p}{2}\cdot \varepsilon_{*}(1+\varepsilon_{*})^{p/2-1},
\]
where
\[
\varepsilon_{*}:=\max_{j\ne k}\frac{\|\widehat{\Sigma}^{(j,k)}-\Sigma^{(j,k)}\|}{\big(\|\Sigma^{(j,j)}\| \|\Sigma^{(k,k)}\|\big)^{1/2}}.
\]

To control $\varepsilon_*$, we use the bound from \cite[Remark 2.1 and page 21]{chen2025sharp} for the sample cross-covariance. For $j,k\in \{1,\ldots,p\}$ and any $u\ge 0$, it holds with probability at least $1-\exp(-u^2)$ that
\[
\frac{\|\widehat{\Sigma}^{(j,k)}-\Sigma^{(j,k)}\|}{\big(\|\Sigma^{(j,j)}\|\|\Sigma^{(k,k)}\|\big)^{1/2}}\lesssim u\bigg(\frac{r_2(\Sigma^{(j)})+r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+u^2\frac{(r_2(\Sigma^{(j)})r_2(\Sigma^{(k)}))^{1/2}}{N}.
\]
Applying a union bound over all $j\ne k$ yields, with probability at least $1-p^2 \exp(-u^2)$,
\begin{align*}
\varepsilon_* &=\max_{j\ne k}\frac{\|\widehat{\Sigma}^{(j,k)}-\Sigma^{(j,k)}\|}{\big(\|\Sigma^{(j,j)}\|\|\Sigma^{(k,k)}\|\big)^{1/2}}\\
&\lesssim \max_{j\ne k} \left\{u\bigg(\frac{r_2(\Sigma^{(j)})+r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+u^2\frac{(r_2(\Sigma^{(j)})r_2(\Sigma^{(k)}))^{1/2}}{N}\right\}\\
&\lesssim u \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+u^2 \frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}.
\end{align*}
Substituting this bound into the inequality for $\|\widehat{T}_I-T\|$, we obtain, with probability at least $1-p^2 \exp(-u^2)$:
 \begin{align*}
  \|\widehat{T}_I-T\| &\le \bigg(\prod_{k=1}^{p}\|\Sigma^{(k)}\|^{1/2}\bigg) (p-1)!! \cdot \frac{p}{2}\cdot \varepsilon_{*}(1+\varepsilon_{*})^{p/2-1}\\
  &\lesssim_p \bigg(\prod_{k=1}^{p}\|\Sigma^{(k)}\|^{1/2}\bigg) (\varepsilon_*+\varepsilon_*^{p/2})\\
  &\lesssim_p \bigg(\prod_{k=1}^{p}\|\Sigma^{(k)}\|^{1/2}\bigg)\bigg(u \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+u^p \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{p/2}\bigg).
 \end{align*}
Integrating the tail bound yields the following expectation bound: \begin{align*}
 \E \|\widehat{T}_I-T\| &\lesssim_p\bigg(\prod_{k=1}^{p}\|\Sigma^{(k)}\|^{1/2}\bigg)\bigg( \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{1/2}+ \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{p/2}\bigg)\\
 &\asymp_p\bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|^{1 / 2}\bigg) \bigg(\frac{\max_{1\le k\le p}r_2(\Sigma^{(k)})}{N}\bigg)^{1/2},\quad \text{ if } \ N\ge \max_{1\le k\le p}r_2(\Sigma^{(k)}).
 \end{align*}
An analogous argument yields the corresponding bound under the entrywise maximum norm. This completes the proof.
\end{proof}


The following proposition is used in the proof of Theorem~\ref{thm:IsserlissBest_asymmetry}, and its proof is deferred to Section~\ref{sec:proposition_proof}.

\begin{proposition}\label{prop:perturbation} 

Let $p$ be an even integer, and let $X=(X^{(1)},\ldots,X^{(p)})$ and $Y=(Y^{(1)},\ldots,Y^{(p)})$ be zero-mean Gaussian random vectors in $\R^d$, where each $X^{(k)}, Y^{(k)}\in \R^{d_k}$ and $d=\sum_{k=1}^{p}d_k$. For $j, k\in \{1,\ldots,p\}$, denote the cross-covariance blocks by
\[
\Sigma^{(j,k)}_{X}=\E X^{(j)}\otimes X^{(k)}, \qquad \Sigma^{(j,k)}_{Y}=\E Y^{(j)}\otimes Y^{(k)}.
\] 
Let
\[
T_{X}:=\E X^{(1)}\otimes \cdots \otimes X^{(p)}, \qquad T_{Y}:=\E Y^{(1)}\otimes \cdots \otimes Y^{(p)},
\]
denote the moment tensors formed by taking tensor products over the blocks of $X$ and $Y$, respectively. 
Then,
    \[ \|T_{X}-T_{Y}\|\le \bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|^{1/2}\bigg) (p-1)!! \cdot \frac{p}{2}\cdot \varepsilon_{*}(1+\varepsilon_{*})^{p/2-1},
\]
where
\[
\varepsilon_{*}:=\max_{j\ne k}\frac{\|\Sigma^{(j,k)}_{X}-\Sigma^{(j,k)}_{Y}\|}{\big(\|\Sigma^{(j,j)}_{Y}\| \|\Sigma^{(k,k)}_{Y}\|\big)^{1/2}}.
\]
 For the entrywise maximum norm, it similarly holds that 
 \[ \|T_{X}-T_{Y}\|_{\max}\le \bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|_{\max}^{1/2}\bigg) (p-1)!! \cdot \frac{p}{2}\cdot \bar{\varepsilon}_{*}(1+\bar{\varepsilon}_{*})^{p/2-1},
\]
where
\[
\bar{\varepsilon}_{*}:=\max_{j\ne k}\frac{\|\Sigma^{(j,k)}_{X}-\Sigma^{(j,k)}_{Y}\|_{\max}}{\big(\|\Sigma^{(j,j)}_{Y}\|_{\max} \|\Sigma^{(k,k)}_{Y}\|_{\max}\big)^{1/2}}.
\]
\end{proposition}


\begin{corollary}\label{coro:perturbation} Let $X\sim \mcN(0,\Sigma_X)$ and $Y\sim \mcN(0,\Sigma_Y)$, and let $T_X:=\E X^{\otimes p}, T_Y:=\E Y^{\otimes p}$. Then,
    \[
 \frac{\|T_X-T_Y\|}{\|T_Y\|}\le \frac{p}{2}\cdot\frac{\|\Sigma_{X}-\Sigma_{Y}\|}{\|\Sigma_{Y}\|}\left(1+\frac{\|\Sigma_{X}-\Sigma_{Y}\|}{\|\Sigma_{Y}\|}\right)^{p/2-1}. 
\]
Similarly, under the entrywise maximum norm,
    \begin{align*}
        \frac{\|T_X-T_Y\|_{\max}}{\|T_Y\|_{\max}}\le \frac{p}{2}\cdot\frac{\|\Sigma_{X}-\Sigma_{Y}\|_{\max}}{\|\Sigma_{Y}\|_{\max}}\left(1+\frac{\|\Sigma_{X}-\Sigma_{Y}\|_{\max}}{\|\Sigma_{Y}\|_{\max}}\right)^{p/2-1}.
    \end{align*}
    \end{corollary}
    \begin{proof}[Proof of Corollary \ref{coro:perturbation}]
  Apply Proposition \ref{prop:perturbation} with $X^{(1)}=\cdots=X^{(p)}=:X$ and $Y^{(1)}=\cdots=Y^{(p)}=:Y$, so that $\Sigma_{X}^{(j,k)}=:\Sigma_{X}$ and  $\Sigma_{Y}^{(j,k)}=:\Sigma_{Y}$ for all $j,k\in \{1,\ldots,p\}$. The result then follows from computing the norm of the reference tensor:
        \[
       \| T_{Y}\|=\|\E Y^{\otimes p}\|=\sup_{v\in \mcS^{d}}\E \langle Y,v\rangle^p=(p-1)!! \cdot \|\Sigma_Y\|^{p/2},
        \]
     where the last equality uses the moment formula for centered Gaussian variables. The bound under the entrywise maximum norm follows analogously.       
    \end{proof}



\section{Proof of Proposition \ref{prop:perturbation}}\label{sec:proposition_proof}


\begin{proof}[Proof of Proposition \ref{prop:perturbation}]

For arbitrary vectors $v_{1},\ldots ,v_{p}\in \R^d$, we have
\begin{align*}
    &\langle T_{X}-T_{Y},v_1\otimes \cdots \otimes v_p \rangle
    =\left\langle \E X^{(1)}\otimes \cdots \otimes X^{(p)} - \E Y^{(1)}\otimes \cdots \otimes Y^{(p)},v_1\otimes \cdots \otimes v_p\right\rangle\\
    &=\E \prod_{k=1}^{p}\langle X^{(k)},v_k \rangle-\E \prod_{k=1}^{p}\langle Y^{(k)},v_k \rangle\\
    &\overset{\text{(i)}}{=} \sum_{\pi\in \Pi_p^2} \prod_{(j,k)\in \pi}\E \langle X^{(j)},v_j \rangle \langle X^{(k)},v_k \rangle-\sum_{\pi\in \Pi_p^2} \prod_{(j,k)\in \pi}\E \langle Y^{(j)},v_j \rangle \langle Y^{(k)},v_k \rangle\\
    &=\sum_{\pi\in \Pi_p^2}\bigg(\prod_{(j,k)\in \pi}\langle \Sigma^{(j,k)}_{X} v_j,v_k \rangle-\prod_{(j,k)\in \pi} \langle \Sigma^{(j,k)}_{Y} v_j,v_k \rangle \bigg).
\end{align*}
Here, (i) follows from Isserlis's theorem, and $\Pi_p^2$ denotes the set of pairwise partitions of $\{1,\ldots,p\}$. Denoting by  $\pi=(\pi(1),\ldots,\pi(p))$ a fixed ordering of the indices in the pairing $\pi$, and applying the telescoping identity
\[
a_1 \cdots a_{p/2}-b_1 \cdots b_{p/2}=\sum_{\ell=1}^{p/2} a_1 \cdots a_{\ell-1}\left(a_\ell-b_\ell\right) b_{\ell+1} \cdots b_{p/2},
\]
we obtain
\begin{align*}
&\langle T_{X} - T_{Y}, v_1 \otimes \cdots \otimes v_p \rangle
= \sum_{\pi\in \Pi_p^2}\bigg(\prod_{(j,k)\in \pi}\langle \Sigma^{(j,k)}_{X} v_j,v_k \rangle-\prod_{(j,k)\in \pi} \langle \Sigma^{(j,k)}_{Y} v_j,v_k \rangle \bigg)\\
&=\sum_{\pi \in \Pi_p^2} \sum_{\ell=1}^{p/2} \bigg(\prod_{s=1}^{\ell-1} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{X} v_{\pi(2s-1)}, v_{\pi(2s)} \rangle
\bigg) \\
&\times \!\langle (\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{X} - \Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{Y}) v_{\pi(2\ell - 1)}, v_{\pi(2\ell)} \rangle  \bigg( \prod_{s=\ell+1}^{p/2} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{Y} v_{\pi(2s-1)}, v_{\pi(2s)} \rangle\bigg).
\end{align*}

To bound the operator norm, we take the supremum over $v_1,\ldots,v_p\in\mcS^{d}$,
\begin{align*}
    &\|T_{X}-T_{Y}\| 
    =\sup_{v_1,\ldots,v_p\in \mcS^{d}} |\langle T_{X}- T_{Y},v_1\otimes \cdots \otimes v_p \rangle| \\
    & = \sup_{v_1,\ldots,v_p\in \mcS^{d}}\bigg|\sum_{\pi \in \Pi_p^2} \sum_{\ell=1}^{p/2} \bigg(\prod_{s=1}^{\ell-1} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{X} v_{\pi(2s-1)}, v_{\pi(2s)} \rangle
\bigg) \\
&\times \langle (\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{X} - \Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{Y}) v_{\pi(2\ell - 1)}, v_{\pi(2\ell)} \rangle  \times \bigg( \prod_{s=\ell+1}^{p/2} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{Y} v_{\pi(2s-1)}, v_{\pi(2s)} \bigg)\bigg|\\
 &\le\sum_{\pi\in \Pi_{p}^2}\sum_{\ell=1}^{p/2}  \Bigg[\sup_{v_1,\ldots,v_p\in \mcS^{d}} \bigg| \bigg(\prod_{s=1}^{\ell-1} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{X} v_{\pi(2s-1)}, v_{\pi(2s)} \rangle
\bigg) \\
&\times \langle (\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{X} - \Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{Y}) v_{\pi(2\ell - 1)}, v_{\pi(2\ell)} \rangle  \times \bigg( \prod_{s=\ell+1}^{p/2} \langle \Sigma^{(\pi(2s-1),\pi(2s))}_{Y} v_{\pi(2s-1)}, v_{\pi(2s)} \bigg)\bigg|\Bigg]\\
   & =\sum_{\pi\in \Pi_{p}^2}\sum_{\ell=1}^{p/2} \bigg(\prod_{s=1}^{\ell-1} \|\Sigma^{(\pi(2s-1),\pi(2s))}_{X}\|\bigg)\|\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{X}-\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{Y}\|\bigg(\prod_{s=\ell+1}^{p/2} \|\Sigma^{(\pi(2s-1),\pi(2s))}_{Y}\|\bigg) .
\end{align*} 

For $j,k\in \{1,\ldots,p\}$, we introduce the normalized deviation $\varepsilon^{(j,k)}:=\frac{\|\Sigma^{(j,k)}_{X}-\Sigma^{(j,k)}_{Y}\|}{\big(\|\Sigma^{(j,j)}_{Y}\| \|\Sigma^{(k,k)}_{Y}\|\big)^{1/2}} $
and define $\varepsilon_{*}:=\max_{j\ne k}\varepsilon^{(j,k)}$. Using the inequality $\|\Sigma^{(j,k)}_{Y}\|\le \|\Sigma^{(j,j)}_{Y}\|^{1/2}\|\Sigma^{(k,k)}_{Y}\|^{1/2}$, we obtain
\begin{align*}
    &\|T_{X}-T_{Y}\|\\
    &\le \sum_{\pi\in \Pi_{p}^2}\sum_{\ell=1}^{p/2} \bigg(\prod_{s=1}^{\ell-1} \|\Sigma^{(\pi(2s-1),\pi(2s))}_{X}\|\bigg)\|\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{X}-\Sigma^{(\pi(2\ell-1),\pi(2\ell))}_{Y}\|\bigg(\prod_{s=\ell+1}^{p/2} \|\Sigma^{(\pi(2s-1),\pi(2s))}_{Y}\|\bigg) \\
    &\le \sum_{\pi\in \Pi_{p}^2}\sum_{\ell=1}^{p/2} \Bigg[ \bigg(\prod_{s=1}^{\ell-1} \|\Sigma^{(\pi(2s-1),\pi(2s-1))}_{Y}\|^{1/2} \|\Sigma^{(\pi(2s),\pi(2s))}_{Y}\|^{1/2}\big(1+\varepsilon^{(\pi(2s-1),\pi(2s))}\big)\bigg)\\
    &\hspace{1cm}\times \bigg(\|\Sigma^{(\pi(2\ell-1),\pi(2\ell-1))}_Y\|^{1/2}\|\Sigma^{(\pi(2\ell),\pi(2\ell))}_Y\|^{1/2}\varepsilon^{(\pi(2\ell-1),\pi(2\ell))}\bigg)\\
    &\hspace{1cm}\times \bigg(\prod_{s=\ell+1}^{p/2} \|\Sigma^{(\pi(2s-1),\pi(2s-1))}_{Y}\|^{1/2}\|\Sigma^{(\pi(2s),\pi(2s))}_{Y}\|^{1/2}\bigg) \Bigg]\\
    &=\bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|^{1/2}\bigg)\sum_{\pi\in \Pi_{p}^2}\sum_{\ell=1}^{p/2}\varepsilon^{(\pi(2\ell-1),\pi(2\ell))}\prod_{s=1}^{\ell-1}\big(1+\varepsilon^{(\pi(2s-1),\pi(2s))}\big).\\
   \end{align*}
   Using the identity \[
\sum_{\ell=1}^{p/2}a_{\ell}\prod_{s=1}^{\ell-1}(1+a_s)=\prod_{\ell=1}^{p/2}(1+a_{\ell})-1,\]
we conclude
\begin{align*}
    \|T_{X}-T_{Y}\|&\le\bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|^{1/2}\bigg)\sum_{\pi\in \Pi_{p}^2}\bigg(\prod_{\ell=1}^{p/2}\big(1+\varepsilon^{(\pi(2\ell-1),\pi(2\ell))}\big)-1\bigg)\\
    &\le  \bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|^{1/2}\bigg) (p-1)!! \left((1+\varepsilon_{*})^{p/2}-1\right)\\
    & \le  \bigg(\prod_{k=1}^{p}\|\Sigma^{(k,k)}_{Y}\|^{1/2}\bigg) (p-1)!! \cdot \frac{p}{2}\cdot \varepsilon_{*}(1+\varepsilon_{*})^{p/2-1},
\end{align*}
where we used the inequality $(1+\varepsilon_*)^{p/2}-1\le \frac{p}{2}\cdot\varepsilon_{*}(1+\varepsilon_{*})^{p/2-1}$.

The bound under the entrywise maximum norm follows from an analogous argument, replacing the supremum over the unit sphere $\mcS^{d}$ with the supremum over the standard basis $\mcE=\{e_i\}_{i=1}^d$. 
This completes the proof.
\end{proof}

\section{Entrywise maximum norm bound for sample moment tensor}

\begin{theorem}\label{thm:maximum_asymmetric}
  For any integer $p\ge 2$ and $1 \leq k \leq p$, let $X^{(k)}, X_1^{(k)}, \ldots, X_N^{(k)}$ be i.i.d. zero-mean Gaussian random vectors in $\R^{d_k}$ with covariance matrix $\Sigma^{(k)}$. Then,
\[
\E \bigg\|\frac{1}{N} \sum_{i=1}^N X_i^{(1)} \otimes \cdots \otimes X_i^{(p)}-\E X^{(1)} \otimes \cdots \otimes X^{(p)}\bigg\|_{\max} \lesssim_p \bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|_{\max}^{1 / 2}\bigg)\mathscr{E}_N\big((\Sigma^{(k)})_{k=1}^p\big),
\]
where
\begin{align*}
\mathscr{E}_N\big((\Sigma^{(k)})_{k=1}^p\big):= \bigg(\frac{\sum_{k=1}^p r_{\max}(\Sigma^{(k)})}{N}\bigg)^{1/2}+\frac{1}{N}\prod_{k=1}^{p}\Big(r_{\max}(\Sigma^{(k)})+\log N\Big)^{1/2}.
\end{align*}
Moreover, the upper bound is sharp in the following two cases:
\begin{enumerate}
    \item \textit{Independent Components.} If $X^{(1)},\ldots, X^{(p)}, (X^{(1)}_i)_{i=1}^{N},\ldots,(X^{(p)}_i)_{i=1}^N$ are mutually independent, then
\[
\E \bigg\|\frac{1}{N} \sum_{i=1}^N X_i^{(1)} \otimes \cdots \otimes X_i^{(p)}-\E X^{(1)} \otimes \cdots \otimes X^{(p)}\bigg\|_{\max} \asymp_p\bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|_{\max}^{1 / 2}\bigg)\mathscr{E}_N\big((\Sigma^{(k)})_{k=1}^p\big).
\]
\item \textit{Identical Components.} If $X^{(1)}=\cdots = X^{(p)}=X$ and $X_i^{(1)}=\cdots = X_i^{(p)}=X_i \,$ for all $1\le i\le N$, $\Sigma^{(1)}=\cdots=\Sigma^{(p)}=\Sigma,$ then
\begin{align*}
\E \bigg\|\frac{1}{N}\sum_{i=1}^{N} X_i^{\otimes p}-\E X^{\otimes p}\bigg\|_{\max} &\asymp_p \|\Sigma\|_{\max}^{p/2} \bigg(\sqrt{\frac{r_{\max}(\Sigma)}{N}}+\frac{(r_{\max}(\Sigma)+\log N)^{p/2}}{N}\bigg).
\end{align*}
Furthermore, since $(\log N)^{p/2}/N\lesssim_p 1/\sqrt{N}$, this bound simplifies to
\[
\E \bigg\|\frac{1}{N}\sum_{i=1}^{N} X_i^{\otimes p}-\E X^{\otimes p}\bigg\|_{\max}  \asymp_p \|\Sigma\|_{\max}^{p/2} \bigg(\sqrt{\frac{r_{\max}(\Sigma)}{N}}+\frac{r_{\max}(\Sigma)^{p/2}}{N}\bigg).
\]
\end{enumerate}
\end{theorem}


\begin{remark}
The upper bound in Theorem \ref{thm:maximum_asymmetric} holds without requiring independence between the sequences $(X^{(k)}_i)_{i=1}^{N}$ and $(X^{(k')}_i)_{i=1}^{N}$ for $k\ne k'$; that is, no assumptions are made on the correlation structure across components.  Moreover, the upper bound in Theorem~\ref{thm:maximum_asymmetric} extends directly to sub-Gaussian settings. 
Dimension-dependent counterparts can also be derived by applying standard $\varepsilon$-net arguments in conjunction with the $\alpha$-sub-exponential concentration inequality of \cite{gotze2021concentration}.
\end{remark}
\begin{proof}[Proof of Theorem \ref{thm:maximum_asymmetric}]

\textit{Upper bound} 
By the definition of the entrywise maximum norm, we have
\begin{align*}
    &\E \bigg\|\frac{1}{N} \sum_{i=1}^N X_i^{(1)} \otimes \cdots \otimes X_i^{(p)}-\E X^{(1)} \otimes \cdots \otimes X^{(p)}\bigg\|_{\max}\\
    &=\E \max_{v_1,\dots, v_p \in \mcE} \bigg|\frac{1}{N}\sum_{i=1}^{N}\prod_{k=1}^{p}\langle X^{(k)}_i,v_k\rangle -\E \prod_{k=1}^{p} \langle X^{(k)}, v_k \rangle\bigg|,
\end{align*}
where $\mcE$ denotes the standard basis of $\R^d$. Let $\bar{\mcE}:=\mcE\cup -\mcE$, and define $\F^{(1)}=\cdots =\F^{(p)}:=\{\langle\cdot, v\rangle: v \in \bar{\mcE} \}$. Then the maximum can be upper bounded by
\[
\E \sup_{f^{(k)} \in \mathcal{F}^{(k)},1\le k\le p}\bigg|\frac{1}{N} \sum_{i=1}^N \prod_{k=1}^p f^{(k)} (X^{(k)}_i)-\mathbb{E} \prod_{k=1}^p f^{(k)} (X^{(k)})\bigg|.
\]
Applying \cite[Theorem 2.2]{chen2025sharp}, we obtain
\begin{align}\label{eq:aux1}
&\E \!\sup_{f^{(k)} \in \mathcal{F}^{(k)},1\le k\le p}\bigg|\frac{1}{N} \sum_{i=1}^N \prod_{k=1}^p f^{(k)} (X^{(k)}_i)-\mathbb{E} \prod_{k=1}^p f^{(k)} (X^{(k)})\bigg| \nonumber\\
&\lesssim_p  \bigg(\prod_{k=1}^{p} d_{\psi_2}(\F^{(k)})\bigg) \bigg(\frac{\sum_{k=1}^{p}\bar{\gamma}(\F^{(k)},\psi_2)}{\sqrt{N}}+\frac{\prod_{k=1}^{p}\big(\bar{\gamma}(\F^{(k)},\psi_2)+(\log N)^{1/2}\big)}{N}\bigg) ,
\end{align}
where $\bar{\gamma}(\F^{(k)},\psi_2):=\gamma(\F^{(k)},\psi_2)/d_{\psi_2}(\F^{(k)})$. Here, $\gamma(\F,\psi_2)$ denotes Talagrand's generic chaining complexity of the function class $\F$ \cite[Definition 2.7.3]{talagrand2022upper}, $d_{\psi_2}(\F) := \sup_{f \in \F}\|f\|_{\psi_2}$, and $\psi_2$ refers to the Orlicz norm with Orlicz function $\psi(x) = e^{x^2}-1,$ see e.g. \cite[Definition 2.5.6]{vershynin2018high}.

Since $X^{(k)}$ is Gaussian with covariance $\Sigma^{(k)}$, the $\psi_2$-norm of linear functionals is equivalent to the $L_2$-norm. Hence, \begin{align*}
d_{\psi_2}(\F^{(k)})=\sup_{f^{(k)}\in\mathcal{F}^{(k)}}\|f^{(k)}\|_{\psi_2}\asymp \sup_{f^{(k)}\in\mathcal{F}^{(k)}}\|f^{(k)}\|_{L_2}=\sup_{v\in\bar{\mcE}}\big(\E\langle X^{(k)},v\rangle^2\big)^{1/2}=\|\Sigma^{(k)}\|_{\max}^{1/2}.
\end{align*}
For the generic chaining term, note that the canonical metric on $\bar{\mcE}$  is given by
\[
d_{X^{(k)}}(u, v)
:= \big(\mathbb{E}(\langle X^{(k)}, u\rangle-\langle X^{(k)}, v\rangle)^2\big)^{1/2}=\langle u-v, \Sigma^{(k)} (u-v) \rangle^{1/2}
=\|\langle\cdot, u\rangle-\langle\cdot, v\rangle\|_{L_2(\mu^{(k)})},
\]
where $\mu^{(k)}$ is the law of $X^{(k)}$. By Talagrand's majorizing measure theorem \cite[Theorem 2.10.1]{talagrand2022upper},
\[
\gamma (\F^{(k)}, \psi_2)\asymp \gamma (\F^{(k)}, L_2)=\gamma(\bar{\mcE}, d_{X^{(k)}}) \asymp \mathbb{E} \sup _{u \in \bar{\mcE}}\langle X^{(k)}, u\rangle = \E \|X^{(k)}\|_{\infty}.
\]
We conclude that
 \[
 d_{\psi_2}(\F^{(k)}) \asymp \|\Sigma^{(k)}\|_{\max}^{1/2},\quad \gamma(\F^{(k)},\psi_2)\asymp \E \|X^{(k)}\|_{\infty},
 \]
 and therefore,
 \[
\E \bigg\|\frac{1}{N} \sum_{i=1}^N X_i^{(1)} \otimes \cdots \otimes X_i^{(p)}-\E X^{(1)} \otimes \cdots \otimes X^{(p)}\bigg\|_{\max} \lesssim_p \bigg(\prod_{k=1}^p\|\Sigma^{(k)}\|_{\max}^{1 / 2}\bigg)\mathscr{E}_N\big((\Sigma^{(k)})_{k=1}^p\big),
\]
where
\begin{align*}
\mathscr{E}_N\big((\Sigma^{(k)})_{k=1}^p\big):= \bigg(\frac{\sum_{k=1}^p r_{\max}(\Sigma^{(k)})}{N}\bigg)^{1/2}+\frac{1}{N}\prod_{k=1}^{p}\Big(r_{\max}(\Sigma^{(k)})+\log N\Big)^{1/2}
\end{align*}
and $r_{\max}(\Sigma^{(k)}) := \left( \E_{X^{(k)} \sim \mcN(0, \Sigma^{(k)})} \|X^{(k)}\|_\infty \right)^2/\|\Sigma^{(k)}\|_{\max}$.

\vspace{1em}
\textit{Lower bound}  The lower bounds follow from straightforward modifications of the argument in \cite[Proposition 3.1]{chen2025sharp} and \cite[Proposition 3.1]{al2025sharp}, respectively, by replacing the operator norm with the entrywise maximum norm. We omit the details for brevity.
\end{proof}



