\title{Geometry of Yang-Baxter matrix equations over finite fields} 
\def\shorttitle{Geometry of Yang-Baxter matrix equations over finite fields}

\author{Yin Chen}
\address{School of Mathematics and Physics, Key Laboratory of ECOFM of 
