\section{Introduction}
\setcounter{equation}{0}
\renewcommand{\theequation}
{1.\arabic{equation}}
\setcounter{theorem}{0}
\renewcommand{\thetheorem}
{1.\arabic{theorem}}

\noindent Let $\K$ be a field of any characteristic and $n\in\N^+$. Suppose that $M_n(\K)$ denotes the vector space of all $n\times n$ matrices over $\K$.  Given a matrix $A\in M_n(\K)$, the following equation 
\begin{equation}\tag{YBME}
\label{YBME}
XAX=AXA
\end{equation}
is called the \textit{Yang-Baxter matrix equation} with respect to $A$ over $\K$.  This matrix equation occupies a prominent place in both pure mathematics and mathematical physics, which originally stems from 
Yang’s work on the one-dimensional many-body problem in \cite{Yan67} and Baxter’s research in two-dimensional classical statistical mechanics in \cite{Bax72}, and its study has substantial ramifications in quantum groups, nonassociative algebras, and differential operator theory; see for example, \cite{CJdR10, Hiv00}, and \cite{BFP99}.


We write $\D_A(\K)$ for the affine variety of all  $n\times n$ matrix  solutions  to (\ref{YBME}). Apparently, if $A=0$, then $\D_A(\K)=M_n(\K)$. If $A\neq 0$, then  the zero matrix and the matrix $A$ both are solutions to (\ref{YBME}) and thus $|\D_A(\K)|\geqslant 2$. We say that a solution $X\in\D_A(\K)$ is \textit{nontrivial} if $X\neq 0$ and $X\neq A$. A central task in the study of \ref{YBME} is to characterize
the shape of a generic solution in $\D_A(\K)$ and to construct new nontrivial solutions within $\D_A(\K)$ for specific applications. 
There are extensive research conducted on this task in the characteristic zero case;  for recent developments over $\C$ or $\R$, see \cite{CCY19, Lu22, WWW24, GZ24}, and \cite{HM25}. In this article, we focus on the finite field case (i.e., $\K=\F_q$) and our primary objective is to explore the geometric structure of the affine variety $\D_A(\F_q)$ via capitalizing on 
a method from computational ideal theory.

Characterizing solutions of a matrix equation over finite fields and determining explicit formulas for their cardinalities 
have been a classical topic with a long history, dating back to the works of Carlitz and Hodges; see for example, \cite{Car73, Hod57, Hod58, Hod64}, and \cite{Hod66}. In contrast to the characteristic zero case, where $\D_A(\K)$ admits infinitely many nontrivial solutions, the finite field setting yields only finitely many solutions. This finiteness provides two notable advantages: it facilitates the explicit computation of the cardinality of $\D_A(\F_q)$, and it enables applications to various areas such as combinatorics, algebra, and the theory of combinatorial designs in statistics; see \cite{WZ01a} and \cite{WZ01b}.
In earlier work \cite{CZ23}, we used algebraic invariant theory to study the geometry of $\D_A(\F_q)$ when $A$ is a scalar matrix. This work has inspired several recent studies, including \cite{PDK22,CZ24, CR25} and \cite{Coh25}. The present article aims to extend this investigation to the case where $A$ ranges over all $2\times 2$-matrices. 

Throughout we assume that $\F_q$ denotes a finite field of order $q=p^s$ for some prime $p$ and $s\in\N^+$.
Given two matrices $A,B\in M_2(\F_q)$, we observe that if $A$ and $B$ are similar over $\F_q$, then $|\D_A(\F_q)|=|\D_B(\F_q)|$ and 
solutions in $\D_B(\F_q)$ can be obtained from elements in $\D_A(\F_q)$ via a conjugacy action; see Proposition \ref{prop2.1}
and Corollary \ref{coro2.2}.
This observation allows us to restrict our attention to  the affine variety $\D_A(\F_q)$, where $A$ denotes the rational canonical form of $B$. We will see below that that the rational canonical form $A$ must be one of the following four types:
\begin{equation}
\label{ }
\left\{A_1:=\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}, ~~A_2:=\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix},~~ A_3:=\begin{pmatrix}
   0   &  -b  \\
    1  &  a
\end{pmatrix}, ~~ A_4:=\begin{pmatrix}
   c   &  0  \\
    0  &  c
\end{pmatrix}\right\}
\end{equation}
where $a,b,c,c_1\neq c_2$ are elements in $\F_q$ and $x^2-ax+b$ is irreducible in $\F_q[x]$; see Proposition \ref{prop2.5}.  Note that the cardinality and geometry of $\D_{A_4}(\F_q)$ have been well understood, as shown in \cite{CZ23}. Thus, in this article, we mainly focus on the geometric structures and cardinalities for  $\D_{A_1}(\F_q), \D_{A_2}(\F_q)$, and $\D_{A_3}(\F_q)$.


The first main result can be summarized as follows.

\begin{thm}\label{mt1}
{\rm (1)} If exactly one of $\{c_1,c_2\}$ is zero, then $\D_{A_1}(\F_q)$ is a 2-dimensional affine variety consisting of two 2-dimensional irreducible components and one 1-dimensional irreducible component. In particular, $|\D_{A_1}(\F_q)|=2q^2$.

{\rm (2)} Assume that $c_1\neq c_2\in\F_q^\times$ and define $\updelta:=c_1^2  -c_1c_2+ c_2^2$. If $\updelta=0$, then 
$|\D_{A_1}(\F_q)|=2q+2$ and $\D_{A_1}(\F_q)$ is a 1-dimensional affine variety consisting of three isolated points and two 1-dimensional irreducible components. If $\updelta\neq0$, then 
$|\D_{A_1}(\F_q)|=q+3$ and $\D_{A_1}(\F_q)$ is a 1-dimensional affine variety consisting of four isolated points and one 1-dimensional irreducible component.
\end{thm}
\noindent The proof of Theorem \ref{mt1} can be given by together Propositions \ref{prop3.1}, \ref{prop3.2} and \ref{prop3.3}.


To understand the geometric structure of $\D_{A_2}(\F_q)$, our argument will be separated into two cases: $c=0$ and $c\neq 0$. The following theorem is our second major result, which could be proved by combining the proofs of Propositions \ref{prop4.1} and \ref{prop4.2}.

\begin{thm}\label{mt2}
{\rm (1)}  If $c=0$, then $\D_{A_2}(\F_q)$ is of cardinality $2q^2-q$ and is a 2-dimensional affine variety consisting of 
two 2-dimensional irreducible components. 

{\rm (2)} If $c\neq 0$, then $\D_{A_2}(\F_q)$  is a 1-dimensional affine variety consisting of two isolated points and 
one 1-dimensional irreducible component. In particular, $|\D_{A_2}(\F_q)|=q+2$.
\end{thm}


To state the third main result, we write 
\begin{equation}
\label{ }
\Delta:=a^2-4b
\end{equation}
for the discriminant of $x^2-ax+b$.  The following theorem demonstrates that for all odd characteristic cases, there are no nontrivial solutions in $\D_{A_3}(\F_q)$  provided that $\Delta= -b$.  

\begin{thm}\label{mt3}
Assume that $\cha(\F_q)\neq 2$. If $\Delta= -b$, then $|\D_{A_3}(\F_q)|=2$.
\end{thm}
\noindent We also propose a conjecture about the cardinality of $\D_{A_3}(\F_q)$ for the case $\Delta\neq -b$.

We organize this article as follows.  In Section \ref{sec2}, we provide some fundamental properties on matrix similarity and conjugacy actions that are helpful in understanding the geometry of $\D_{A}(\F_q)$ and its quotient spaces. In particular, we give a detailed discussion about rational canonical forms of $2\times 2$ matrices over $\F_q$. Sections \ref{sec3}, \ref{sec4}, and \ref{sec5} are devoted to proofs of Theorem \ref{mt1}, \ref{mt2}, and \ref{mt3}, respectively. In Section \ref{sec6}, we present some examples and explicit calculations for small primes $q$. Moreover, together with Remark \ref{rem6.4}, a conjecture on $|\D_{A_3}(\F_q)|$ (when $\Delta\neq -b$) was raised in this section. 



\vspace{2mm}
\noindent\textbf{Conventions.}  Throughout this article,  $\K$ denotes a field of any characteristic and $\F_q$ denotes a finite field of order $q$. We always assume that $A$ is a nonzero matrix over either $\K$ or $\F_q$. We write $R:=\F_q[x_{11},x_{12},x_{21},x_{22}]$ for the polynomial ring over $\F_q$ and  denote by $\ideal{S}$  the ideal of $R$ generated by a subset $S\subseteq R$. 



\section{General Properties} \label{sec2}
\setcounter{equation}{0}
\renewcommand{\theequation}
{2.\arabic{equation}}
\setcounter{theorem}{0}
\renewcommand{\thetheorem}
{2.\arabic{theorem}}

\noindent This preliminary section presents some basic properties on matrix similarity and conjugacy actions. These properties allow us to reduce the study of $\D_A(\K)$ to the case where $A$ denotes a rational canonical form over $\F_q$. A detailed discussion of rational canonical forms of size $2$ over $\F_q$ are also provided. 

We denote by $\GL_n(\K)$ the general linear group of degree $n$ over $\K$.

\begin{prop}\label{prop2.1}
Let $A$ and $B$ be two similar matrices of degree $n$ over $\K$. Then there exists a one-to-one correspondence between
$\D_A(\K)$ and $\D_B(\K)$.  
\end{prop}


\begin{proof}
Suppose that $B=P^{-1}AP$ for some $P\in\GL_n(\K)$. The map 
\begin{equation}\label{eq2.1}
\upvarphi_P: \D_A(\K)\ra\D_B(\K)
\end{equation}
defined by $X\mapsto P^{-1}XP$ for all $X\in \D_A(\K)$, is a bijective map.  The first fact we have to show is that
$\upvarphi_P(X)=P^{-1}XP\in\D_B(\K)$ for all $X\in \D_A(\K)$. In fact,  
\begin{eqnarray*}
(P^{-1}XP)B(P^{-1}XP)&=&P^{-1}X(PBP^{-1})XP=P^{-1}(XAX)P\\
&=&P^{-1}(AXA)P=(P^{-1}AP)(P^{-1}XP)(P^{-1}AP)\\
&=&B(P^{-1}XP)B.
\end{eqnarray*}
Hence, $P^{-1}XP\in\D_B(\K)$ for all $X\in \D_A(\K)$. Note that the map $\upvarphi_P$ is given by the conjugacy action, thus it is bijective. This completes the proof.
\end{proof}

\begin{coro} \label{coro2.2}
If $A$ and $B$ are similar over $\K$, then $|\D_A(\K)|=|\D_B(\K)|$.  
\end{coro}


Fix a matrix $A\in M_n(\K)$ and consider the conjugacy action of $\GL_n(\K)$ on $M_n(\K)$:
\begin{equation}\label{ }
(Q,Y)\mapsto QYQ^{-1}
\end{equation}
for all $Q\in \GL_n(\K)$ and $Y\in M_n(\K)$. In general,  $\D_A(\K)$ is not stable under this action of $\GL_n(\K)$. 
However, if we write $G_A$ for the stabilizer subgroup of $A$ in $\GL_n(\K)$, i.e.,
$$G_A:=\{Q\in \GL_n(\K)\mid QAQ^{-1}=A\},$$
then the following result shows that $\D_A(\K)$ is stable under the conjugacy action of $G_A$, extending \cite[Proposition 2.1]{CZ23}.


\begin{prop} \label{prop2.3}
For any $A\in M_n(\K)$, $\D_A(\K)$ is stable under the conjugacy action of $G_A$. 
\end{prop}

\begin{proof}
It suffices to show that $QXQ^{-1}\in \D_A(\K)$ for all $Q\in G_A$ and $X\in \D_A(\K)$. Since $QA=AQ$, it follows that
\begin{eqnarray*}
(QXQ^{-1})A(QXQ^{-1})& = & QXQ^{-1}(QA)XQ^{-1}\\
 & = & Q(XAX)Q^{-1}=Q(AXA)Q^{-1}\\
 &=&A(QXQ^{-1})A.
\end{eqnarray*}
Here, the last equation holds because $A$ and $Q^{-1}$ commute as well. 
\end{proof}


\begin{rem}{\rm
The geometry of a quotient space $\D_A(\K)\bslash G_A$ is not the main topic of this article. However, as we have seen in \cite{CZ23}, stabilizer subgroups and the stability of $\D_A(\K)$ would play a key role in understanding the geometric structure of $\D_A(\K)\bslash G_A$. 
\hbo}\end{rem}

The rest of this section is to explore all rational canonical forms of $2\times 2$ matrices over $\F_q$. 
Let us recap two fundamental facts in Linear Algebra that (1) two matrices are similar if and only if they have the same rational canonical form; (2) The rational canonical form of a matrix is determined by the minimal polynomial of this matrix. Thus,  to find all possible rational canonical forms in $M_2(\F_q)$, we need to consider characteristic polynomials and minimal polynomials of matrices. 

Suppose that $B\in M_2(\F_q)$ denotes an arbitrary matrix. We write $m_B(x)$ and $c_B(x)$ for the minimal polynomial and the characteristic polynomial of $B$ respectively. Note that  $m_B(x)$ and $c_B(x)$ both are monic polynomials of degree 2 in $\F_q[x]$. In particular, $m_B(x)$ divides $c_B(x)$. 

We may assume that $c_B(x)=x^2-ax+b$, where $a=\Tr(B)$ and $b=\det(B)$. We denote by $r_B$ the number of distinct  roots of $c_B(x)$ in $\F_q$. Clearly, $0\leqslant r_B\leqslant 2$.  Our arguments can be separated into the following three cases:



\textsc{Case 1}: $r_B=2$. We may assume that $c_B(x)$ has two distinct roots $c_1\neq c_2$ in $\F_q$. Then $c_B(x)=(x-c_1)(x-c_2)$ splits in $\F_q$ and $m_B(x)$ is equal to either $x-c_1$ or $x-c_2$. Thus the rational canonical form of $B$
is $$A_1=\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}$$
which means that $B$ is diagonalizable. 


\textsc{Case 2}: $r_B=1$. In this case, $c_B(x)=(x-c)^2$ must split in $\F_q$ and it has one repeated root $c$ in $\F_q$. There are two subcases: $m_B(x)=x-c$ and $m_B(x)=(x-c)^2$. For the first subcase, the rational canonical form of $B$
is $$A_4=\begin{pmatrix}
   c   &  0  \\
    0  &  c
\end{pmatrix}.$$
In the second subcase, the rational canonical form of $B$ will be a Jordan block of size 2:
$$A_2=\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix}.$$


\textsc{Case 3}: $r_B=0$. In this case, $c_B(x)$ is irreducible, and so $m_B(x)=c_B(x)=x^2-ax+b$. Thus the rational canonical form of $B$
is $$A_3=\begin{pmatrix}
   0   &  -b  \\
    1  &  a
\end{pmatrix}.$$


This also proves the following result. 

\begin{prop} \label{prop2.5}
The rational canonical form of a matrix $B\in M_2(\F_q)$ must be  one of the following four types:
\begin{equation}
\label{ }
\left\{\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix},  ~~\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix},~~ \begin{pmatrix}
   0   &  -b  \\
    1  &  a
\end{pmatrix},~~\begin{pmatrix}
   c   &  0  \\
    0  &  c
\end{pmatrix}\right\}
\end{equation}
where $a,b,c,c_1\neq c_2$ are elements in $\F_q$ and $x^2-ax+b$ is irreducible in $\F_q[x]$.
\end{prop}



\section{Geometry of $\D_{A_1}(\F_q)$} \label{sec3}
\setcounter{equation}{0}
\renewcommand{\theequation}
{3.\arabic{equation}}
\setcounter{theorem}{0}
\renewcommand{\thetheorem}
{3.\arabic{theorem}}

\noindent In this section, we deal with the situation of $A=A_1=\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}$
for two distinct elements $c_1$ and $c_2$ in $\F_q$. Our main goal  is to give a proof to Theorem \ref{mt1}. Precisely, we would like to study the irreducible components of $\D_{A_1}(\F_q)$ and determine the cardinality of $\D_{A_1}(\F_q)$. Note that
$c_1\neq c_2$, we may divide the proof  of Theorem \ref{mt1} into two cases: (1)  exactly one of $\{c_1,c_2\}$ is zero; (2) $c_1$ and $c_2$ both are nonzero. 


Let us begin with an arbitrary solution $X=\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\in\D_{A_1}(\F_q)$. Substituting $X$ to (\ref{YBME}) obtains 
$$XA_1X-A_1XA_1=\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}-\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\begin{pmatrix}
   c_1   &  0  \\
    0  &  c_2
\end{pmatrix}=0.$$
A direct computation shows that these $x_{ij}$ satisfy the following quadratic equations:
\begin{equation} \label{eq3.1}
\begin{aligned}
c_1x_{11}x_{12} -c_1c_2x_{12}  + c_2x_{12}x_{22}&=0 
&c_1x_{11}x_{21}  -c_1c_2x_{21} + c_2x_{21}x_{22}&=0 \\
 c_1x_{12}x_{21} + c_2x_{22}^2 -c_2^2x_{22}&=0 
 &c_1x_{11}^2 -c_1^2x_{11}  + c_2x_{12}x_{21}&=0.
\end{aligned}
\end{equation}

\subsection{Exactly one of $\{c_1,c_2\}$ is zero} 
For this case, without loss of generality, we may assume that $c_2=0$ and $c_1\neq 0$. Then the four equations in (\ref{eq3.1}) can be reduced to:
\begin{equation} \label{eq3.2}
\begin{aligned}
x_{11}x_{12}&=0 &x_{11}x_{21}&=0 \\
x_{12}x_{21}&=0 &x_{11}^2 -c_1x_{11}&=0.
\end{aligned}
\end{equation}

An elementary method can compute the cardinality of $\D_{A_1}(\F_q)$ in this case. 

\begin{prop}\label{prop3.1}
If exactly one of $\{c_1,c_2\}$ is zero, then $|\D_{A_1}(\F_q)|=2q^2$.
\end{prop}

\begin{proof}
If $x_{11}=0$, then it follows from (\ref{eq3.2}) that either $x_{12}=0$ or $x_{21}=0$. This provides two types of solutions in
$\D_{A_1}(\F_q)$:  
$$D_1:=\left\{\begin{pmatrix}
   0   & 0   \\
   a   &  b
\end{pmatrix}~\Big|~ a,b\in\F_q\right\}\textrm{ and }D_2:=\left\{\begin{pmatrix}
    0  &  a \\
     0 &  b
\end{pmatrix}~\Big|~ a,b\in\F_q\right\}$$
respectively. Clearly, $|D_1|=q^2$ and $|D_2\setminus D_1|=q(q-1)$. If $x_{11}\neq 0$, then (\ref{eq3.2}) implies that
$x_{12}=x_{21}=0$ and $x_{11}=c_1$. We obtain the third type of solution in $\D_{A_1}(\F_q)$ as follows:
$$D_3:=\left\{\begin{pmatrix}
    c_1  &  0  \\
    0  & a
\end{pmatrix}~\Big|~ a\in\F_q\right\}.$$
Note that $|D_3|=q$. Since $\D_{A_1}(\F_q)=D_1\cup D_2\cup D_3$ and $D_3\cap (D_2\cup D_1)=\emptyset$, we see that
$$|\D_{A_1}(\F_q)|=|D_1|+|D_2\setminus D_1|+|D_3\setminus(D_2\cup D_1)|=q^2+q(q-1)+q$$
which simplifies to $2q^2$, as desired.
\end{proof}


\begin{prop}\label{prop3.2}
Assume that exactly one of $\{c_1,c_2\}$ is zero. Then $\D_{A_1}(\F_q)$ is a 2-dimensional affine variety consisting of 
two 2-dimensional irreducible components and one 1-dimensional irreducible component. In particular, the vanishing ideal
of $\D_{A_1}(\F_q)$ is generated by $$\{x_{11}x_{12}, x_{11}x_{21}, x_{12}x_{21}, x_{11}^2 -c_1x_{11}\}.$$
\end{prop}

\begin{proof}
We will be working in the polynomial ring $R:=\F_q[x_{11},x_{12},x_{21},x_{22}]$. Suppose that $\p_1=\ideal{x_{11},x_{12}}$, $\p_2=\ideal{x_{11},x_{21}}$, and $\p_3=\ideal{x_{11}-c_1, x_{12},x_{21}}$.  Clearly, they are prime ideals in $R$ because $$R/\p_1\cong \F_q[x_{21},x_{22}],~ R/\p_2\cong \F_q[x_{12},x_{22}],~ R/\p_3\cong \F_q[x_{22}]$$ are integral domains. Moreover, $\p_1,\p_2$ and $\p_3$ are the vanishing ideals corresponding to $D_1,D_2$, and $D_3$ in Proposition \ref{prop3.1}, respectively. Thus each $D_i=V(\p_i)$ is irreducible and $$\D_{A_1}(\F_q)=D_1\cup D_2\cup D_3=V(\p_1)\cup V(\p_2)\cup V(\p_3).$$ Note that the Krull dimensions of $D_1$ and $D_2$ both are 2 and the Krull dimension of $D_3$ is 1. Hence,
the first statement follows. 


To show the second statement, let $J$ denote the ideal generated by 
$\{x_{11}x_{12}, x_{11}x_{21}, x_{12}x_{21}, x_{11}^2 -c_1x_{11}\}$ in $R$.  By (\ref{eq3.2}), we see that $\D_{A_1}(\F_q)=V(J)$ and so the vanishing ideal $I(\D_{A_1}(\F_q))=\sqrt{J}$. Thus, we only need to show that
$\sqrt{J}\subseteq J$. By \cite[Lemma 1.1.5]{Gec03}, we see that
$$\sqrt{J}=I(\D_{A_1}(\F_q))=I(V(\p_1)\cup V(\p_2)\cup V(\p_3))=I(V(\p_1\cap\p_2\cap\p_3))=I(V(\p_1\cdot\p_2\cdot\p_3))=\sqrt{\p_1\cdot\p_2\cdot\p_3}.$$
As all $\p_i$ are prime ideals, it follows that $\sqrt{\p_1\cdot\p_2\cdot\p_3}=\p_1\cdot\p_2\cdot\p_3$.
Thus, it suffices to show that
\begin{equation}
\label{ }
\p_1\cdot\p_2\cdot\p_3\subseteq J.
\end{equation}
By \cite[Proposition 6, page 191]{CLO15}, which asserts that the product of two ideals in a polynomial ring can be generated by the product of generators of the ideals, we see that the ideal $\p_1\cdot\p_2$ can be generated by
$\{x_{11}^2, x_{11}x_{12}, x_{11}x_{21}, x_{12}x_{21}\}$ and thus $\p_1\cdot\p_2\cdot\p_3$ can be generated by
all products $f\cdot g$, where $f\in \{x_{11}^2, x_{11}x_{12}, x_{11}x_{21}, x_{12}x_{21}\}$ and $g\in \{x_{11}-c_1, x_{12},x_{21}\}$. A direct calculation shows that in the quotient ring $R/J$, the classes of all such products $f\cdot g$ will be zero. Thus 
$\p_1\cdot\p_2\cdot\p_3$ is contained in $J$. This proves that $J$ is the vanishing ideal
of $\D_{A_1}(\F_q)$ and furthermore, $J=\sqrt{J}=\p_1\cap\p_2\cap\p_3$.
\end{proof}

Together Propositions \ref{prop3.1} and \ref{prop3.2} completes the proof of the first statement in Theorem \ref{mt1}.

\subsection{$c_1\neq c_2\in\F_q^\times$}
To give a proof to the second statement in Theorem \ref{mt1}, we define
$$\updelta:=c_1^2  -c_1c_2+ c_2^2.$$
The geometric structure of $\D_{A_1}(\F_q)$ differs depending on whether  $\updelta =0$ or $\updelta\neq0$.

\begin{prop}\label{prop3.3}
Let $c_1$ and $c_2$ be two distinct nonzero elements in $\F_q$. 
\begin{enumerate}
  \item Suppose that $\updelta=0$. Then $|\D_{A_1}(\F_q)|=2q+2$ and the variety $\D_{A_1}(\F_q)$ is a 1-dimensional affine variety consisting of three isolated points 
$$\left\{\begin{pmatrix}
     0 & 0   \\
    0  &  0
\end{pmatrix},\begin{pmatrix}
   c_1  &  0  \\
   0   & 0 
\end{pmatrix}, \begin{pmatrix}
   0   &  0  \\
   0   & c_2 
\end{pmatrix}\right\}$$
and two 1-dimensional irreducible components
$$E_1:=\left\{\begin{pmatrix}
     c_1 & 0   \\
      a& c_2 
\end{pmatrix}~\Big|~ a\in\F_q\right\}\textrm{ and } E_2:=\left\{\begin{pmatrix}
     c_1 & a   \\
      0& c_2 
\end{pmatrix}~\Big|~ a\in\F_q\right\}.$$
  \item Suppose that $\updelta\neq 0$. Then $|\D_{A_1}(\F_q)|=q+3$ and the variety $\D_{A_1}(\F_q)$ is also a 1-dimensional affine variety consisting of four isolated points 
$$\left\{\begin{pmatrix}
     0 & 0   \\
    0  &  0
\end{pmatrix},\begin{pmatrix}
   c_1  &  0  \\
   0   & 0 
\end{pmatrix},\begin{pmatrix}
   0   &  0  \\
   0   & c_2 
\end{pmatrix},\begin{pmatrix}
     c_1 & 0   \\
      0& c_2 
\end{pmatrix} \right\}$$
and one 1-dimensional irreducible component
$$E_3:=\left\{\begin{pmatrix}
     \frac{c_2^2}{c_2-c_1} & a   \\
      b& \frac{c_1^2}{c_1-c_2}
\end{pmatrix}~\Big|~ a,b\in\F_q^\times\textrm{ and }ab=-\frac{c_1c_2\cdot \updelta}{(c_1-c_2)^2}\right\}.$$
\end{enumerate}
\end{prop}

\begin{proof}
Our proof will be separated into two cases:  $x_{11}x_{12}=0$ and  $x_{11}x_{12}\neq0$.  

\textsc{Case 1}: Assume that $x_{11}x_{12}=0$. We proceed with the following three subcases: (1) $x_{11}=x_{12}=0$. In this subcase, the equations (\ref{eq3.1}) can be reduced to
\begin{eqnarray*}
-c_1x_{21} + x_{21}x_{22}= 0 &~~& x_{22}^2 -c_2x_{22} =0.
\end{eqnarray*}
By these two equations, we see that if $x_{22}=0$, then $x_{21}=0$ and we have $X=0.$ Moreover, if $x_{22}\neq 0$, then
$x_{22}=c_2$. Hence, $(c_2-c_1)x_{21}=0$,
which implies that $x_{21}=0$. This produces an isolated nonzero solution in $\D_{A_1}$:
$$X=\begin{pmatrix}
   0   &  0  \\
   0   & c_2 
\end{pmatrix}.$$
(2) $x_{11}=0$ and $x_{12}\neq 0$.  We may simplify (\ref{eq3.1}) as follows:
\begin{equation*} 
\begin{aligned}
 -c_1 + x_{22}&=0 & -c_1x_{21} + x_{21}x_{22}&= 0 \\
 c_1x_{12}x_{21} + c_2x_{22}^2 -c_2^2x_{22} &=0& x_{21}&=0.
\end{aligned}
\end{equation*}
Then $x_{22}=c_1$ and $c_2c_1^2=c_2^2c_1$. Since $c_1$ and $c_2$ both are nonzero, it follows that $c_1=c_2$, which contradicts with the original assumption that $c_1\neq c_2$. This means that
if $x_{11}=0$, then $x_{12}=0$. There are no new solutions obtained in this subcase. (3) $x_{11}\neq0$ and $x_{12}=0$.  We can reduce (\ref{eq3.1}) into the following equations:
\begin{eqnarray*}
c_1x_{11}x_{21}  -c_1c_2x_{21} + c_2x_{21}x_{22}=0 &~~
c_2x_{22}^2 -c_2^2x_{22} =0 &~~ c_1x_{11}^2 -c_1^2x_{11} =0.
\end{eqnarray*}
By the third and second equations, we see that $x_{11}=c_1$ and $x_{22}=c_2$ respectively. Substituting back to the first equation gives rise to:
\begin{equation}
\label{ }
c_1^2x_{21}  -c_1c_2x_{21} + c_2^2x_{21}=0.
\end{equation}
Recall that  $\updelta=c_1^2  -c_1c_2+ c_2^2.$
If $\updelta=0$, then $x_{21}$ is a free variable and 
$$X=\begin{pmatrix}
     c_1 & 0   \\
      a& c_2 
\end{pmatrix}\in E_1.$$
If $\updelta\neq0$, then $x_{21}=0$ and we obtain the following isolated solution: 
$$X=\begin{pmatrix}
     c_1 & 0   \\
      0& c_2 
\end{pmatrix}.$$

\textsc{Case 2}: Assume that $x_{11}x_{12}\neq 0$. In this case, the equations in (\ref{eq3.1}) can be reduced to
\begin{eqnarray}\label{eq3.5}
\begin{aligned}
c_1x_{11}-c_1c_2 + c_2x_{22}& =  0 \\
 c_1x_{12}x_{21} + c_2x_{22}^2 -c_2^2x_{22} &=0\\
   c_1x_{11}^2 -c_1^2x_{11}  + c_2x_{12}x_{21}&=0.
   \end{aligned}
\end{eqnarray}
(1) If $x_{21}=0$, then (\ref{eq3.5}) becomes
\begin{eqnarray*}
c_1x_{11}-c_1c_2 + c_2x_{22}= 0
&c_2x_{22}^2 -c_2^2x_{22} =0&
   c_1x_{11}^2 -c_1^2x_{11} =0.
\end{eqnarray*}
This implies that $x_{11}=c_1$ and $x_{22}=c_2$. Thus $\updelta=0$
and $x_{12}$ is a free variable. We obtain the second family $E_2$ of solutions: 
$$X=\begin{pmatrix}
     c_1 &  a  \\
     0 &  c_2
\end{pmatrix}.$$ 
(2) If $x_{21}\neq0$, then it follows from the first equation in (\ref{eq3.5}) that $c_2x_{22}=c_1c_2-c_1x_{11}.$
Together with the second and third equations in (\ref{eq3.5}), we may cancel the term involving $x_{12}x_{21}$ and derive
\begin{eqnarray*}
0&=&c_2^2x_{22}^2 -c_2^3x_{22}-   c_1^2x_{11}^2 +c_1^3x_{11} \\
&=&(c_1c_2-c_1x_{11})^2-c_2^2(c_1c_2-c_1x_{11})-   c_1^2x_{11}^2 +c_1^3x_{11}\\
&=&c_1^2c_2^2-2c_1^2c_2x_{11}+c_1^2x_{11}^2-c_1c_2^3+c_1c_2^2x_{11}-   c_1^2x_{11}^2 +c_1^3x_{11}\\
&=& (c_1^3-2c_1^2c_2+c_1c_2^2)x_{11}+(c_1^2c_2^2-c_1c_2^3).
\end{eqnarray*}
Hence,
$$x_{11}=\frac{c_1c_2^3-c_1^2c_2^2}{c_1^3-2c_1^2c_2+c_1c_2^2}=\frac{c_2^2(c_2-c_1)}{c_1^2-2c_1c_2+c_2^2}=\frac{c_2^2}{c_2-c_1}.$$
Moreover, 
$$x_{22}=c_2^{-1}(c_1c_2-c_1x_{11})=\frac{c_1^2}{c_1-c_2}$$
and it follows from the third equation in (\ref{eq3.5}) that
$$x_{12}x_{21}=-\frac{c_1c_2\cdot \updelta}{(c_1-c_2)^2}.$$
If $\updelta=0$, then there are no new solutions produced because of $x_{12}x_{21}=0$ and the solutions either belong to
$E_1$ or $E_2$. If $\updelta\neq 0$, then we obtain the third family of solutions:
$$X=\begin{pmatrix}
     \frac{c_2^2}{c_2-c_1} & a   \\
      b& \frac{c_1^2}{c_1-c_2}
\end{pmatrix}\in E_3$$ 
where $ab=-\frac{c_1c_2\cdot \updelta}{(c_1-c_2)^2}\neq 0$.

Summarizing these results, we conclude that when $\updelta=0$, the cardinality of $\D_{A_1}(\F_q)$ equals $2q+2$ and $\D_{A_1}(\F_q)$  consists of three isolated points and two 1-dimensional irreducible components $E_1$ and $E_2$; thus it is
a 1-dimensional affine variety. When $\updelta\neq0$, $|\D_{A_1}(\F_q)|=q+3$ and $\D_{A_1}(\F_q)$  consists of four isolated points and one 1-dimensional irreducible components $E_3$.  
\end{proof}

Together Propositions \ref{prop3.1}, \ref{prop3.2} and \ref{prop3.3}  completes the proof of Theorem \ref{mt1}.


\section{Geometry of $\D_{A_2}(\F_q)$} \label{sec4}
\setcounter{equation}{0}
\renewcommand{\theequation}
{4.\arabic{equation}}
\setcounter{theorem}{0}
\renewcommand{\thetheorem}
{4.\arabic{theorem}}

\noindent Throughout  this section, we always assume that $A_2=\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix}$
for some $c\in\F_q$. Consider a generic solution $X=\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\in\D_{A_2}(\F_q)$. It follows from (\ref{YBME}) that
$$XA_2X-A_2XA_2=\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix}\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}-\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix}\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\begin{pmatrix}
   c   &  1  \\
    0  &  c
\end{pmatrix}=0.$$
A straightforward calculation implies  that
\begin{equation} \label{eq4.1}
\begin{aligned}
-c^2x_{12} + cx_{11}x_{12} -cx_{11} + cx_{12}x_{22} -cx_{22} + x_{11}x_{22} -x_{21}&=0\\
    -c^2x_{11} + cx_{11}^2 + cx_{12}x_{21} -cx_{21} + x_{11}x_{21}&=0\\
    -c^2x_{21} + cx_{11}x_{21} + cx_{21}x_{22} + x_{21}^2&=0\\
    -c^2x_{22} + cx_{12}x_{21} -cx_{21} + cx_{22}^2 + x_{21}x_{22}&=0.
 \end{aligned}
\end{equation}
This section is devoted to giving a proof to Theorem \ref{mt2} and our argument will be divided into two cases: $c=0$ and $c\neq 0$.

\subsection{$c=0$}  
The following result provides a proof to the first statement in Theorem \ref{mt2}.

\begin{prop}\label{prop4.1}
If $c=0$, then $\D_{A_2}(\F_q)$ is of cardinality $2q^2-q$ and is a 2-dimensional affine variety consisting of 
two 2-dimensional irreducible components. 
\end{prop}

\begin{proof}
As $c=0$, the equations in (\ref{eq4.1}) become to
\begin{equation}
\label{eq4.2}
x_{11}x_{22} -x_{21}=0,~~\quad x_{11}x_{21}=0,~~\quad x_{21}^2=0,~~\quad x_{21}x_{22}=0.
\end{equation}
The fact that $x_{21}^2=0$ implies that $x_{21}=0$. Thus the second and the fourth equations in (\ref{eq4.2}) disappear.  
The first equation shows that either $x_{11}=0$ or $x_{22}=0$. If $x_{11}=0$, then $x_{22}$ and $x_{12}$ are two free variables and we obtain the first family of solutions in $\D_{A_2}(\F_q)$:
$$X=\begin{pmatrix}
      0& a   \\
     0 &  b
\end{pmatrix}.$$
If $x_{11}\neq 0$, then $x_{22}$ must be zero. Thus $x_{11}$ and $x_{12}$ are free variables and this gives us the second family of solutions in $\D_{A_2}(\F_q)$:
$$X=\begin{pmatrix}
      a& b \\
     0 &  0
\end{pmatrix}.$$ Here, $a,b$ are any elements in $\F_q$.  Clearly, the vanishing ideal of the first family is
$\p_1:=\ideal{x_{11}, x_{21}}$ and the vanishing ideal of the second family is $\p_2:=\ideal{x_{21}, x_{22}}$. Note that the two ideals both are prime, thus 
$$V(\p_1)=\left\{\begin{pmatrix}
      0& a   \\
     0 &  b
\end{pmatrix}~\Big|~ a,b\in \F_q\right\}\textrm{ and } V(\p_2)=\left\{\begin{pmatrix}
      a& b   \\
     0 &  0
\end{pmatrix}~\Big|~ a,b\in \F_q\right\}$$
both are 2-dimensional irreducible components of $\D_{A_2}(\F_q)$. Moreover, 
$$|\D_{A_2}(\F_q)|=|V(\p_1)\cup V(\p_2)|=|V(\p_1)|+|V(\p_2)|-|V(\p_1)\cap V(\p_2)|=q^2+q^2-q=2q^2-q$$
because $|V(\p_1)|=|V(\p_2)|=q^2$ and $|V(\p_1)\cap V(\p_2)|=q.$
\end{proof}


\subsection{$c\neq0$} 
In this subsection, we assume that $c\neq 0$. The following result proves the second statement in Theorem \ref{mt2}.

\begin{prop}\label{prop4.2}
If $c\neq 0$, then $\D_{A_2}(\F_q)$  is a 1-dimensional affine variety consisting of two isolated points and 
one 1-dimensional irreducible component. In particular, $|\D_{A_2}(\F_q)|=q+2$.
\end{prop}


\begin{proof}
Our argument will be separated into two subcases: $x_{21}=0$ and $x_{21}\neq0$. First of all, we assume that $x_{21}=0$. This assumption makes (\ref{eq4.1}) become
\begin{equation} \label{eq4.3}
\begin{aligned}
c^2x_{12} - cx_{11}x_{12} +cx_{11} - cx_{12}x_{22} + cx_{22} - x_{11}x_{22}&=0\\
    c^2x_{11} - cx_{11}^2 =0,~~\quad c^2x_{22}  - cx_{22}^2 &=0.
 \end{aligned}
\end{equation}
Note that $c\neq 0$, the last two equations in (\ref{eq4.3}) imply that $x_{11},x_{22}\in\{0,c\}$. Thus, we have four possibilities for the values of $x_{11}$ and $x_{22}$. If $(x_{11},x_{22})=(0,0)$, then substituting it to the first equation in  
(\ref{eq4.3}) gives $x_{12}=0$ and so we obtain the zero solution in $\D_{A_2}(\F_q)$.  If $(x_{11},x_{22})=(0,c)$ or $(x_{11},x_{22})=(c,0)$, then it follows from the first equation in (\ref{eq4.3}) that $c=0$, which is a contradiction. If $(x_{11},x_{22})=(c,c)$, then $x_{12}=1$ by (\ref{eq4.3}). Thus, the following matrix
$$X=\begin{pmatrix}
      c& 1   \\
     0 &  c
\end{pmatrix}=A_2$$
was revealed as a point in $\D_{A_2}(\F_q)$.

Now, let us assume that $x_{21}\neq0$. Dividing the third equation in (\ref{eq4.1}) by $x_{21}$, we see that
\begin{eqnarray} 
-c^2x_{12} + cx_{11}x_{12} -cx_{11} + cx_{12}x_{22} -cx_{22} + x_{11}x_{22} -x_{21}&=&0\label{eq4.4}\\
    -c^2x_{11} + cx_{11}^2 + cx_{12}x_{21} -cx_{21} + x_{11}x_{21}&=&0\label{eq4.5}\\
    -c^2+ cx_{11} + cx_{22} + x_{21}&=&0\label{eq4.6}\\
    -c^2x_{22} + cx_{12}x_{21} -cx_{21} + cx_{22}^2 + x_{21}x_{22}&=&0.\label{eq4.7}
\end{eqnarray}
Adding (\ref{eq4.6}) on (\ref{eq4.4}) obtains 
\begin{equation}
\label{eq4.8}
-c^2x_{12} + cx_{11}x_{12}  + cx_{12}x_{22}  + x_{11}x_{22}   -c^2  =0.
\end{equation}
It follows from (\ref{eq4.6}) that  $cx_{11} + cx_{22}=c^2-x_{21}$. Substituting this fact to (\ref{eq4.8}) gives
\begin{eqnarray*}
c^2&=&x_{11}x_{22}-c^2x_{12} + (cx_{11} + cx_{22})x_{12} \\
&=&x_{11}x_{22}-c^2x_{12} +(c^2-x_{21})x_{12}\\
&=&x_{11}x_{22}-x_{12}x_{21}.
\end{eqnarray*}
By (\ref{eq4.7}) and (\ref{eq4.5}) , we observe that $x_{12}x_{21}  =  cx_{22} +x_{21} - x_{22}^2 - c^{-1}x_{21}x_{22}$ and 
$x_{11}=c- c^{-1}x_{21} - x_{22}$. Thus
$c^2= x_{11}x_{22}-x_{12}x_{21}=(cx_{22}- c^{-1}x_{21}x_{22} - x_{22}^2)- (cx_{22} +x_{21} - x_{22}^2 - c^{-1}x_{21}x_{22})=-x_{21}$. This implies that
\begin{equation}
\label{ }
x_{21}=-c^2.
\end{equation}
Moreover, $x_{11}=c- c^{-1}x_{21} - x_{22}=c- c^{-1}(-c^2) - x_{22}=2c-x_{22}$. We substitute $x_{21}$ and $x_{11}$ back to (\ref{eq4.7}) and obtain 
\begin{equation}
\label{ }
 - c^2x_{12} +c^2 + x_{22}^2 -2cx_{22}=0,
\end{equation}
which means that $x_{12}=c^{-2}x_{22}^2 -2c^{-1}x_{22}+1.$ Hence, we deduce the following family of solutions in $\D_{A_2}(\F_q)$:
$$E:=\left\{\begin{pmatrix}
   2c-a   &  c^{-2}a^2 -2c^{-1}a+1  \\
 -c^2     &  a
\end{pmatrix} ~\Big|~ a\in\F_q\right\}.$$
Therefore, 
$$\D_{A_2}(\F_q)=\left\{\begin{pmatrix}
   0   &  0  \\
    0  & 0 
\end{pmatrix},\begin{pmatrix}
      c& 1   \\
     0 &  c
\end{pmatrix}\right\}\cup E$$
and $|\D_{A_2}(\F_q)|=q+2$. 

Note that the Krull dimension of $E$ is 1. To complete the proof, we need to prove that $E$ is an irreducible component of 
$\D_{A_2}(\F_q)$, i.e., the vanishing ideal of $E$ is a prime ideal in $R$. Let $\p$ be the ideal generated by
$\{x_{21}+c^2,x_{11}+x_{22}-2c, x_{12}-c^{-2}x_{22}^2 +2c^{-1}x_{22}-1 \}$ in $R$. Then the radical of $\p$ equals the vanishing ideal of $E$. Thus, it suffices to show that $\p$ is prime, which is equivalent to verifying that 
$R/\p$ is an integral domain. In fact, 
$$R/\p=\F_q[x_{11},x_{12},x_{21},x_{22}]/\ideal{x_{21}+c^2,x_{11}+x_{22}-2c, x_{12}-c^{-2}x_{22}^2 +2c^{-1}x_{22}-1}\cong \F_q[x_{22}]$$
is an integral domain. Hence, $\p$ is a prime ideal and $E$ is irreducible. 
\end{proof}


\begin{rem}{\rm 
Together Propositions \ref{prop4.1} and \ref{prop4.2}  completes the proof of Theorem \ref{mt2}.
\hbo}\end{rem}

\section{Geometry of $\D_{A_3}(\F_q)$} \label{sec5}
\setcounter{equation}{0}
\renewcommand{\theequation}
{5.\arabic{equation}}
\setcounter{theorem}{0}
\renewcommand{\thetheorem}
{5.\arabic{theorem}}

\noindent In this section, we assume that $\cha(\F_q)\neq 2$ and study the geometry of the affine variety $\D_{A_3}(\F_q)$, where $A_3=\begin{pmatrix}
   0   &  -b  \\
    1  &  a
\end{pmatrix}$
and $a,b\in\F_q$ such that $x^2-ax+b$ is irreducible in $\F_q[x]$. We write 
$$\Delta:=a^2-4b$$
for the discriminant of a quadratic function $x^2-ax+b$ over any field $\K$. 

The following lemma might be well-known  but
we include a proof to this result for the readers' convenience, because we were unable to find a suitable reference.

\begin{lem}\label{lem5.1}
If $\cha(\K)\neq 2$, then $x^2-ax+b$ irreducible if and only if $\Delta$ is a non-square in $\K$.
\end{lem}

\begin{proof}
$(\RA)$ Assume by the way of contradiction that there exists an element $c\in\K$ such that $\Delta=c^2$. Then $\frac{a+c}{2}$ and $\frac{a-c}{2}$ both belong to $\K$. Moreover, 
\begin{eqnarray*}
\left(x-\frac{a+c}{2}\right)\left(x-\frac{a-c}{2}\right)&=&x^2-\left(\frac{a+c}{2}+\frac{a-c}{2}\right)x+\frac{a+c}{2}\cdot\frac{a-c}{2} \\
&=&x^2-ax+\frac{a^2-\Delta}{4}\\
&=&x^2-ax+b
\end{eqnarray*}
which means that $x^2-ax+b$ is reducible over $\K$. This contradiction shows that if  $x^2-ax+b$ irreducible, then
$\Delta$ is a non-square in $\K$. 

$(\LA)$ Conversely, we assume that $x^2-ax+b$ is reducible, i.e., there are two elements
$r,s\in\K$ such that $x^2-ax+b=(x-r)(x-s)=x^2-(r+s)x+rs$. Thus
$a=r+s$ and $b=rs$. This implies that $\Delta=a^2-4b=(r+s)^2-4rs=(r-s)^2$ is a square element in $\K$. This contradiction shows that $x^2-ax+b$ is irreducible over $\K$.
\end{proof}

\begin{rem}{\rm 
By Lemma \ref{lem5.1}, we see that $b\neq 0$ because if $b=0$, then $\Delta=a^2$ is a square in $\F_q$. 
\hbo}\end{rem}

The main purpose of this section is to prove Theorem \ref{mt3}, in which we assume that 
\begin{equation}
\label{ }
\Delta= -b.
\end{equation}
Thus $a^2=3b$ and $a,b$ are not zero.


We begin with a generic solution $X=\begin{pmatrix}
   x_{11}   &  x_{12}  \\
    x_{21}  &  x_{22}
\end{pmatrix}\in\D_{A_3}(\F_q)$. Thus $XA_3X-A_3XA_3=0$
gives rise to the following equations:
\begin{equation} \label{eq5.2}
\begin{aligned}
ax_{12}x_{21} -bx_{11}x_{21} + bx_{22} + x_{11}x_{12}&=0\\
    ax_{21}x_{22} -ax_{22} -bx_{21}^2 + x_{11}x_{22} -x_{12} &=0\\
    abx_{22} + ax_{12}x_{22} -b^2x_{21} -bx_{11}x_{22} + x_{12}^2 &=0\\
    a^2x_{22} - abx_{21} +ax_{12} - ax_{22}^2 - bx_{11} +bx_{21}x_{22} - x_{12}x_{22}&=0.
 \end{aligned}
\end{equation}
Let us write $f_1,\dots,f_4$ for the quadratic functions corresponding to the  equations in (\ref{eq5.2}) and define 
$$J:=\ideal{f_1,\dots,f_4}.$$
We also define $\p_1$ to be the ideal generated by
$$\left\{g_1:=x_{11} + x_{22} - a, g_2:=x_{12} -bx_{21} +ax_{22} - b, g_3:=x_{21}^2 -\frac{a}{b}x_{21}x_{22} + x_{21} +\frac{1}{b}x_{22}^2 -\frac{a}{b}x_{22} + 1\right\}$$
and $\p_2$ to be the ideal generated by
$$\left\{h_1:=x_{11} + 2x_{22} -a, h_2:=x_{12} + ax_{22} -b, h_3:=x_{21} -\frac{a}{b}x_{22} + 1,
h_4:=x_{22}^2 -ax_{22} + b \right\}.$$
Moreover, we define $\p_3:=\ideal{x_{11},x_{12},x_{21},x_{22}}$.

\begin{lem}\label{lem5.3}
$\p_1,\p_2,\p_3$ are prime ideals.
\end{lem}

\begin{proof}
Clearly, $\p_3$ is prime because $R/\p_3\cong \F_q$ is a field and so an integral domain. To see that $\p_2$ is prime, we note that $R/\p_2\cong \F_q[x_{22}]/\ideal{h_4}$  and together with the fact that $h_4=x_{22}^2 -ax_{22} + b$ is irreducible, it follows that $\F_q[x_{22}]/\ideal{h_4}$ is an integral domain. Thus, $\p_2$ is also a prime ideal. To show that $\p_1$ is prime, we observe that $R/\p_1\cong \F_{q}[x_{21},x_{22}]/\ideal{g_3}$ and the latter can be embedded into the quotient ring
$\F_q(x_{22})[x_{21}]/\ideal{g_3}$. Thus, it suffices to show that $\F_q(x_{22})[x_{21}]/\ideal{g_3}$ is an integral domain. 
Now we may review 
$$g_3=x_{21}^2 -\left(\frac{a}{b}x_{22} -1\right)x_{21} +\left(\frac{1}{b}x_{22}^2 -\frac{a}{b}x_{22} + 1\right)$$
as a polynomial over the rational function field $\F_q(x_{22})$ in the variable $x_{21}$. Note that $\Delta=-b\neq 0$ and  $a^2=3b$. The discriminant of $g_3$ is
\begin{eqnarray*}
& & \left(\frac{a}{b}x_{22} -1\right)^2-4\left(\frac{1}{b}x_{22}^2 -\frac{a}{b}x_{22} + 1\right) \\
 & = & \frac{a^2}{b^2}x_{22}^2-  \frac{2a}{b}x_{22}+1-\frac{4}{b}x_{22}^2 +\frac{4a}{b}x_{22} -4\\
 &=&\frac{a^2-4b}{b^2}x_{22}^2+\frac{2a}{b}x_{22}-3\\
  &=&\frac{-b}{b^2}x_{22}^2+\frac{2a}{b}x_{22}-\frac{3b}{b}\\
  &=&-\frac{1}{b}(x_{22}^2-2ax_{22}+a^2)=\frac{(x_{22}-a)^2}{\Delta}.
\end{eqnarray*}
Since $\Delta$ is a non-square element, it follows that the discriminant of $g_3$ is also a non-square element. 
By Lemma \ref{lem5.1}, we see that $g_3$ is irreducible over $\F_q(x_{22})$. Hence, $\F_q(x_{22})[x_{21}]/\ideal{g_3}$ is an integral domain and so is  $R/\p_1$. This proves that $\p_1$ is also a prime ideal.
\end{proof}


\begin{lem}\label{lem5.4}
$\sqrt{J}=\p_1\cap\p_2\cap\p_3$.
\end{lem}

\begin{proof}
It is straightforward to verify that  $f_1,\dots,f_4$ belong to each $\p_i$. For instance, to see that $f_1\in\p_2$, we only need to check that $f_1\equiv 0$ modulo $\p_2$. In $R/\p_2$, 
$x_{11}\equiv a-2x_{22}, x_{12}\equiv b-ax_{22}$, and $x_{21}\equiv\frac{a}{b}x_{22} - 1$. Thus
\begin{eqnarray*}
f_1 & = & a(b-ax_{22})\left(\frac{a}{b}x_{22} - 1\right) -b(a-2x_{22})\left(\frac{a}{b}x_{22} - 1\right) + bx_{22} + (a-2x_{22})(b-ax_{22}) \\
 & \equiv & \left(a^2x_{22}-ab-\frac{a^3}{b}x_{22}^2+a^2x_{22}\right)-(a^2x_{22}-ab-2ax_{22}^2+ 2bx_{22})+ bx_{22}\\
 && +(ab-a^2x_{22}-2bx_{22}+2ax_{22}^2)\\
 &=&-\frac{3ab}{b}x_{22}^2+a^2x_{22}+2ax_{22}^2- 2bx_{22}+ bx_{22}+ab-a^2x_{22}-2bx_{22}+2ax_{22}^2\\
 &=&ax_{22}^2-a^2x_{22}+ab=a\cdot h_4
\end{eqnarray*}
which is equivalent to $0$ modulo $\p_2$. These direct verifications imply that $J\subseteq \p_1\cap\p_2\cap\p_3$. 
By Lemma \ref{lem5.3}, we have seen that all $\p_i$ are prime ideals. Thus $\sqrt{J}\subseteq \p_1\cap\p_2\cap\p_3$ and 
$V(\p_1\cap\p_2\cap\p_3)\subseteq V(\sqrt{J})$.
By \cite[Lemma 1.1.5]{Gec03}, we have
$$\sqrt{J}=I(V(\sqrt{J}))\subseteq I(V(\p_1\cap\p_2\cap\p_3))=I(V(\p_1\cdot\p_2\cdot\p_3))=\sqrt{\p_1\cdot\p_2\cdot\p_3}.$$
It follows from Lemma \ref{lem5.3} that $\sqrt{\p_1\cdot\p_2\cdot\p_3}=\p_1\cdot\p_2\cdot\p_3$. Thus, it suffices to show that $\p_1\cdot\p_2\cdot\p_3\subseteq J.$ By \cite[Proposition 6, page 191]{CLO15}, the set $\A:=\{g_k\cdot x_{ij}\mid 1\leqslant k\leqslant 3, 1\leqslant i,j\leqslant 2\}$ can generate $\p_1\cdot \p_3$ and the set $\B:=\{a\cdot h_i\mid a\in\A,1\leqslant i\leqslant 4\}$
could be a generating set of $\p_1\cdot\p_2\cdot\p_3$. 

To show that the class of each element in $\B$ in $R/J$ is zero, we need to show that each element in $\B$ belongs to $J$.
To do this, we may use a method of Gr\"{o}bner basis. Let us choose the lexicographic monomial ordering with $x_{11}>x_{12}>x_{21}>x_{22}$ for $R$. Note that $a^2=3b$ and $a,b$ are not zero. Using the Buchberger's algorithm (see for example, \cite[Algorithm 1.1.9]{DK15}), we may find a 
Gr\"{o}bner basis $\{s_1,s_2,\dots,s_6\}$ for $J$, where
\begin{eqnarray*}
s_1 & := & x_{11} + \frac{1}{b}x_{12}x_{22} - \frac{a}{b}x_{12} - x_{21}x_{22} + ax_{21} + \frac{a}{b}x_{22}^2 - \frac{a^2}{b}x22 \\
s_2 & := &  x_{12}^2 + ax_{12}x_{22} - bx_{12} - b^2x_{21}^2 + abx_{21}x_{22} - b^2x_{21}\\
s_3 & := & x_{12}x_{21} - \frac{a}{b}x_{12}x_{22} + x_{12} - \frac{2b}{a}x_{21}^2x_{22} + 2x_{21}x_{22}^2 + \frac{b}{a}x_{21}x_{22} -bx_{21} - \frac{2}{a}x_{22}^3 + \frac{b}{a}x_{22}\\
s_4 & := & x_{12}x_{22}^2 - ax_{12}x_{22} + bx_{12} + b^2x_{21}^2 - bx_{21}x_{22}^2 + ax_{22}^3 - a^2x_{22}^2 + abx_{22}\\
s_5 & := & x_{21}^3 - \frac{4}{a}x_{21}^2x_{22} + x_{21}^2 + \frac{2}{b}x_{21}x_{22}^2 - \frac{4}{a}x_{21}x_{22} + x_{21} - 
        \frac{1}{ab}x_{22}^3 + \frac{1}{b}x_{22}^2 - \frac{1}{a}x_{22}\\
s_6 & := &   x_{21}^2x_{22}^2 - ax_{21}^2x_{22} - \frac{a}{b}x_{21}x_{22}^3 + 4x_{21}x_{22}^2 - ax_{21}x_{22} + 
        \frac{1}{b}x_{22}^4 - \frac{2a}{b}x_{22}^3 + 4x_{22}^2 - ax_{22}.     
\end{eqnarray*}
By \cite[Algorithm 1.1.7]{DK15}, it suffices to verify that the normal form of each element in $\B$ with respect to 
$\{s_1,s_2,\dots,s_6\}$ is zero, which can be done by directly applying \cite[Algorithm 1.1.6]{DK15}.

Therefore, $\p_1\cdot\p_2\cdot\p_3$ is contained in $J$, and $\sqrt{J}=\p_1\cap\p_2\cap\p_3$.
\end{proof}

We are ready to complete the proof of Theorem \ref{mt3}. 


\begin{proof}[Proof of Theorem \ref{mt3}]
By Lemma \ref{lem5.4},  $\D_{A_3}(\F_q)=V(\sqrt{J})=V(\p_1\cap\p_2\cap\p_3)=V(\p_1)\cup V(\p_2)\cup V(\p_3).$ Clearly, $V(\p_3)=\{0\}$. Moreover, $V(\p_2)=\emptyset$. To see that, $x_{11},x_{12}$, and $x_{21}$ are all determined by $x_{22}$ via $h_1,f_2,f_3$ respectively, but $h_4=x_{22}^2 -ax_{22} + b$ is irreducible over $\F_q$, thus there are no $x_{22}\in\F_q$
such that $h_4=0$. In other words, $V(\p_2)=\emptyset$. 

Let us look at $V(\p_1)$. As $x_{11}$ and $x_{12}$ are determined by $x_{21}$ and $x_{22}$ via $g_1$ and $g_2$, we only need to focus on the equation $g_3=0$, i.e.,
\begin{equation}
\label{eq5.3}
x_{21}^2 -\left(\frac{a}{b}x_{22} -1\right)x_{21} +\left(\frac{1}{b}x_{22}^2 -\frac{a}{b}x_{22} + 1\right)=0.
\end{equation}
We have seen in Lemma \ref{lem5.3} that the discriminant of this equation is $\frac{(x_{22}-a)^2}{\Delta}$. Since $\Delta$
is a non-square element, it follows that (\ref{eq5.3}) has solutions if and only if $x_{22}=a$. Clearly, (\ref{eq5.3}) has at least one solution because $A_3\in V(\p_1)$.  Hence, $x_{22}=a$. Substituting back to (\ref{eq5.3}) obtains
$$x_{21}^2 -\left(\frac{a}{b}\cdot a -1\right)x_{21} +\left(\frac{1}{b}\cdot a^2 -\frac{a}{b}\cdot a + 1\right)=0.$$
Together with the assumption that $\Delta=-b$, this equation can be simplified as 
$$x_{21}^2-2x_{21}+1=(x_{21}-1)^2=0.$$
Hence, $x_{21}=1$. Using $g_1=g_2=0$, we deduce that $x_{11}=0$ and $x_{12}=-b$. This implies that
$V(\p_1)=\{A_3\}.$ Therefore, $\D_{A_3}(\F_q)=\{0,A_3\}$ and $|\D_{A_3}(\F_q)|=2$.
\end{proof}

\begin{rem}{\rm
In Section \ref{sec6} below, we will give a discussion and conjecture on the geometry of $\D_{A_3}(\F_q)$ when $\Delta\neq -b$. 
\hbo}\end{rem}



