\begin{abstract}
Let $\Lieg$ be a complex semisimple Lie algebra.
We define what it means for a finite dimensional representation of $\Lieg$
to be rectangular and completely classify faithful rectangular representations.
As an application, we obtain new $\lambda$-independence results 
on the algebraic monodromy groups of compatible systems of $\lambda$-adic Galois representations
of number fields.
\end{abstract}

{\tableofcontents}

\section{Introduction}
\subsection{Rectangular representations}\label{s1.1}
\subsubsection{}\label{s1.1.1} Let $\psi:\Lieg\to\End(V)$ be a finite dimensional representation of
a complex semisimple Lie algebra $\Lieg$. The following question
is of particular interest.\vspace{.08in}

\noindent \textbf{Q1}. If $\psi$ is faithful and $\Liet$ is a Cartan subalgebra of $\Lieg$, to 
what extent is $(\Lieg,\psi)$ determined by the restriction $\psi|_\Liet$ (i.e., the formal character)?
\vspace{.08in}

 When $\psi$ is irreducible, this question 
is completely answered by Larsen-Pink 
in the group-theoretic perspective \cite[Theorem 4]{LP90}.
Without assuming the irreducibility of $\psi$, it is proven 
that the number of $A_m$-factors of $\Lieg$ for $m\in\N\backslash\{1,2,3,4,5,7,8\}$ (resp. the parity of 
the number of $A_4$-factors of $\Lieg$) is determined by the formal character $\psi|_\Liet$ \cite[Theorems 2.14, 2.17]{Hui13},
where $A_m:=\mathfrak{sl}(m+1)$. Inspired by a recent work on type $A_1$ automorphic Galois representations \cite{HL24},
we study a  refinement  of the above  question; see Q2 below.

For $d\in\Z_{\geq 0}$, define $Z_d:=\{-d,-d+2,-d+4,\ldots,d-2,d\}\subset\Z$.
The size $|Z_d|$ is $d+1$.
Let $n$ be the rank of $\Lieg$.
The weight lattice $\Lambda_\Lieg$ of $\Lieg$ (with respect to $\Liet$) 
is a $\Z$-lattice of the $n$-dimensional real vector space $\Lambda_\Lieg\otimes\R$. 
The formal character $\psi|_\Liet$
corresponds to a multiset 
$\Xi$ of weights in $\Lambda_\Lieg\subset \Lambda_\Lieg\otimes\R$. 
We say that the representation $\psi:\Lieg\to\End(V)$ is \emph{rectangular} (Definition \ref{rectangle}) if
\begin{enumerate}
\item[(a)] every weight in $\Xi$ is of multiplicity one and
\item[(b)] there exist an $\R$-isomorphism $\iota:\Lambda_\Lieg\otimes\R\to\R^n$ and $d_1,\ldots,d_n\in\Z_{\geq 0}$ such that 
$$\iota(\Xi)=Z_{d_1}\times Z_{d_2}\times\cdots\times Z_{d_n}.$$
\end{enumerate}
Geometrically, (b) means that the weights $\Xi$ can be arranged into a rectangular shape in some coordinate system of $\Lambda_\Lieg\otimes\R$.
The \emph{set of lengths} of the rectangular representation $\psi$ is defined as the multiset 
$$\mathscr L_\psi:=\{|Z_{d_i}|=d_i+1:~ 1\leq i\leq n\}.$$
We say that the rectangular representation $\psi$ is \emph{hypercubic}  if $d_1=d_2=\cdots=d_n$.
In that case, %$\Xi$ can be made hypercubic in some coordinate system, and 
$d_1+1$ is called the \emph{length} of $\psi$.
All these terminologies and notation are well-defined and depend only on 
the formal character $\psi|_\Liet$ (see $\mathsection\mathsection\ref{s2.2}-\ref{s2.3}$).

Typical examples of rectangular representations are irreducible representations 
of $A_1\times\cdots\times A_1$. If $(\Lieg_1,\psi_1)$ and $(\Lieg_2,\psi_2)$
are rectangular with the set of lengths, respectively, equal to $\mathscr L_{\psi_1}$ and $\mathscr L_{\psi_2}$, 
then the \emph{external tensor product} $(\Lieg_1\times\Lieg_2,\psi_1\otimes\psi_2)$
is rectangular with the set of lengths  given by the disjoint union $\mathscr L_{\psi_1}\sqcup \mathscr L_{\psi_2}$. 
A rectangular representation $(\Lieg,\psi)$ is said 
to be \emph{indecomposable} if it is not equivalent to an external tensor product
of two rectangular representations as above. Below is a natural question.\\


\noindent \textbf{Q2}. Can one classify all faithful rectangular representations of complex semisimple Lie algebras? 


\subsubsection{}\label{s1.1.2} Adopt the conventions: $A_m=\mathfrak{sl}(m+1)$ ($m\geq 1)$, $B_m=\mathfrak{so}(2m+1)$ ($m\geq 1)$,
$C_m=\mathfrak{sp}(2m)$ ($m\geq 1)$, and $D_m=\mathfrak{so}(2m)$ ($m\geq 2)$ for classical complex 
Lie algebras. All of these are simple, except for $D_2=A_1\times A_1$. Note also the coincidence $A_1=B_1=C_1$, $B_2=C_2$, and $D_3=A_3$.
We present a complete answer to Q2.

\begin{thm}\label{main1}
Let $(\Lieg,\psi)$ be a faithful rectangular Lie algebra representation 
of a complex semisimple Lie algebra $\Lieg$. 
Fix a decomposition $\Lieg=\Lieg_1\times\Lieg_2\times\cdots\times \Lieg_k$, where
$\Lieg_1$ denotes the product of $A_1$-factors and $\Lieg_2,\ldots,\Lieg_k$ denote simple non-$A_1$ factors. 
Then the following assertions hold.
\begin{enumerate}
\item[(i)] There exist faithful rectangular representation $(\Lieg_1,\psi_1)$
and faithful indecomposable hypercubic representations $(\Lieg_i,\psi_i)$ for $2\leq i\leq k$ such that 
\begin{equation}\label{uni1}
(\Lieg,\psi)=\bigotimes_{i=1}^k(\Lieg_i,\psi_i)
\end{equation}
as an external tensor product.
\item[(ii)] The rectangular representation $\psi_1$ admits an external tensor product 
of indecomposable hypercubic representations
\begin{equation}\label{uni2}
(\Lieg_1,\psi_1)=\bigotimes_{j=1}^{s} (\Lieg_{1,j},\psi_{1,j})
\end{equation}
such that $\Lieg_1=\prod_{j=1}^s\Lieg_{1,j}$ is some decomposition
and each $\psi_{1,j}$ is one of the following.
\begin{enumerate}[(a)]
    \item $(A_1,\mathrm{Sym}^r(\mathrm{Std}))$, $r \in \N$.
    \item $(A_1, \mathrm{Sym}^{r_1}(\mathrm{Std}) \oplus \mathrm{Sym}^{r_2}(\mathrm{Std}))$, $r_1,r_2\in\Z_{\geq 0}$ and $|r_1-r_2|=1$.
	% $r_1\in\N$ is odd and $r_2=r_1\pm 1$ is even.
    \item $(A_1 \times A_1, (\mathrm{Std} \otimes \mathbb 1) \oplus (\mathbb 1 \otimes \mathrm{Std}))
		=(D_2,\mathrm{Spin})$.
\end{enumerate}
\item[(iii)] The hypercubic representation $\psi_i$ for $2\leq i\leq k$ is one of the following.
\begin{enumerate}[(a)]
		\item $(B_2, \mathrm{Std}\oplus \mathrm{Spin})$.
    \item $(B_m, \mathrm{Spin})$, $m \geq 2$.
		\item $(A_3,\mathrm{Std}\oplus\mathrm{Std}^{\vee})=(D_3,\mathrm{Spin})$.
    \item $(D_m, \mathrm{Spin})$, $m \geq 4$.
\end{enumerate}
\item[(iv)] The external tensor product \eqref{uni1} is unique.
\item[(v)] The external tensor product \eqref{uni2} is unique up to permutation
of the factors in the decomposition $\Lieg_1=\prod_{j=1}^s\Lieg_{1,j}$.
\end{enumerate}
\end{thm}

\begin{remark}
Here, $\mathrm{Std}$ (resp. $\mathrm{Spin}$) denotes the standard (resp. spin) representation,
and $\mathbb 1$ denotes the trivial (one-dimensional) representation. 
Note that $(A_1,\mathrm{Std})\otimes (A_1,\mathrm{Std})$, $(B_2,\mathrm{Spin})=(C_2,\mathrm{Std})$, 
and $(D_2,\mathrm{Spin})$ are all hypercubic with the same set of lengths $\{2,2\}$.
In Theorem \ref{main1}(iii), the hypercubic $(B_2, \mathrm{Std}\oplus \mathrm{Spin})$ has length $3$, while the rest (spin representations) have length $2$.
\end{remark}

The following corollaries are immediate.

\begin{cor}
If $\psi$ is a faithful rectangular representation of $\Lieg$,
then each simple factor of $\Lieg$ 
must be one of $A_1$, $A_3$, $B_m$ for $m\geq 2$, or $D_m$ for $m\geq 4$.
\end{cor}


\begin{cor}\label{cor_L at most 2 at most 3}
Let $\psi$ be a faithful rectangular representation of  $\Lieg$ with $\mathscr L_\psi$ the set of lengths.
\begin{enumerate}[(i)]
\item If $\mathscr L_\psi$ contains at most one $2$ and at most one $3$, then $\Lieg$
has only $A_1$-factors.
\item If every element of $\mathscr L_\psi$ is even, and 2 appears at most once in $\mathscr L_\psi$, then the representation decomposes as an external tensor product $$(\Lieg, \psi)=\bigotimes_{\ell\in\mathscr L_\psi} (A_1,\mathrm{Sym}^{\ell-1}(\mathrm{Std}))$$ and it is irreducible.
\end{enumerate}
\end{cor}

Let $\Psi:\bG\to\GL(V)$ be a finite dimensional complex representation of a complex reductive group $\bG$
and let $\psi: \mathrm{Lie}(\bG)\to\End(V)$ be the associated Lie algebra representation.
We say that $\Psi$ is rectangular (resp. hypercubic) if this is so for the restriction $\psi|_{\mathrm{Lie}(\bG)^{\ss}}$,
where $\mathrm{Lie}(\bG)^{\ss}$ is the semisimple part of $\mathrm{Lie}(\bG)$.
Then the set of lengths of $\Psi$ is defined to be the set of lengths of $\psi|_{\mathrm{Lie}(\bG)^{\ss}}$.

The classification results above are applied to deduce new  $\lambda$-independence results  on the
algebraic monodromy groups $\{\bG_\lambda\}$ of some compatible system $\{\rho_\lambda\}$
of Galois representations.

\subsection{Application to Galois representations}\label{s1.2}
\subsubsection{}\label{s1.2.1} Let $K$ be a number field, $\overline K$ be an algebraic closure of $K$, 
and $\Gal_K:=\Gal(\overline K/K)$ the absolute Galois group of $K$ (equipped with the profinite topology).
Let $E$ be another number field and $\Sigma_E$ be the set of finite places of $E$. 
For each finite place $\lambda\in\Sigma_E$, denote by $E_\lambda$ the $\lambda$-adic completion of $E$ and by $\overline E_\lambda$
an algebraic closure of $E_\lambda$.
An $\lambda$-adic representation of $K$ is a continuous group homomorphism
$$\rho_\lambda:\Gal_K\to\GL_n(\overline E_\lambda).$$
The \emph{algebraic monodromy group} of $\rho_\lambda$, denoted $\bG_\lambda$, is a closed 
subgroup of $\GL_{n,\overline E_\lambda}$ defined
as the Zariski closure of the Galois image $\rho_\lambda(\Gal_K)$ in $\GL_{n,\overline E_\lambda}$.
If $\rho_\lambda(\Gal_K)\subset\GL_n(E_\lambda)$, then $\bG_\lambda$
becomes an $E_\lambda$-subgroup of $\GL_{n,E_\lambda}$. 
If $\rho_\lambda$ is semisimple,
then $\bG_\lambda$ is reductive and $\bG_\lambda^{\der}:=[\bG_\lambda^\circ,\bG_\lambda^\circ]$ 
(the derived group of the identity component $\bG_\lambda^\circ$) is semisimple.
Fix an isomorphism $\iota_\lambda:\overline E_\lambda\simeq \C$ for each $\lambda\in\Sigma_E$.
We define $\bG_{\lambda,\C}:=\bG_\lambda\times_{\iota_\lambda}\C$
and $\bG_{\lambda,\C}^{\der}:=\bG_\lambda^{\der}\times_{\iota_\lambda}\C$.

Given a \emph{compatible system} (Definition \ref{csdef}) of semisimple $\lambda$-adic Galois representations
\begin{equation}\label{cs}
\{\rho_\lambda:\Gal_K\to\GL_n(\overline E_\lambda)\}_{\lambda\in\Sigma_E}
\end{equation}
 of $K$ defined over $E$, we are interested in the following question on the system of 
algebraic monodromy groups $\{\bG_\lambda\}_{\lambda\in\Sigma_E}$. \\

\noindent \textbf{Q3}. ($\lambda$-independence of $\bG_\lambda\subset\GL_{n,\overline E_\lambda}$)
\begin{enumerate}[(i)]
\item Is the conjugacy class of the complex reductive subgroup
$\bG_{\lambda,\C}\subset \GL_{n,\C}$
 independent of $\lambda\in\Sigma_E$?
\item Suppose $\rho_\lambda(\Gal_K)\subset\GL_n(E_\lambda)$ for each $\lambda\in\Sigma_E$.
Does there exist a reductive subgroup $\bG\subset\GL_{n,E}$ such that 
$\bG\times_E E_\lambda$ and $\bG_\lambda$ are conjugate in $\GL_{n,E_\lambda}$
for all $\lambda\in\Sigma_E$?
\end{enumerate}

When $\rho_\lambda$ is abelian for some $\lambda$, the answer to Q3(ii) is yes \cite{Ser98}.
When the compatible system is associated to the $\ell$-adic \'etale cohomology groups of degree $w$ of
a smooth projective variety $X/K$ (in this case $E=\Q$), the Mumford-Tate conjecture (see e.g., \cite[$\mathsection9$]{Ser94}) predicts 
a candidate for the identity component $\bG^\circ$ in Q3(ii), see e.g. \cite{LP95},\cite{Pi98} 
for positive results on some abelian varieties.
When $E=\Q$, Larsen-Pink  obtained various $\ell$-independence results of $\bG_\ell^\circ$ 
after restricting to some Dirichlet
density one set of rational primes $\ell\in\Sigma_\Q$ \cite{LP92}; the first author
studied Q3 under some type $A$ assumption on one $\bG_\ell$ \cite{Hui18}.
Assuming that Q3(i) holds, some criteria are given for constructing $\bG^\circ$ in Q3(ii)
in \cite{Hui25}.
If the compatible system is associated to some automorhpic representation of a totally real field $K$,
Q3(i) is studied under some group-theoretic assumptions  on some $\bG_\lambda$ (e.g. connected and of type $A_1$) \cite{HL24}.

Although Q3 is wide open, the following $\lambda$-independence results are known (see $\mathsection\ref{s3.5}$ for details).

\begin{enumerate}[(A)]
\item The component group $\bG_\lambda/\bG_\lambda^\circ$ is independent of $\lambda$ \cite{Ser81}.
\item The \emph{formal character} of the reductive subgroup $\bG_{\lambda,\C}\subset\GL_{n,\C}$ is independent 
of $\lambda$\footnote{If $\bT_{\lambda,\C}$ is a maximal torus of $\bG_{\lambda,\C}$, 
then the conjugacy class of $\bT_{\lambda,\C}$ in $\GL_{n,\C}$ is independent of $\lambda$.} \cite{Ser81}.
\item The \emph{formal bi-character} of the reductive subgroup $\bG_{\lambda,\C}\subset\GL_{n,\C}$ 
is independent of $\lambda$\footnote{If $\bT_{\lambda,\C}^{\ss}\subset\bT_{\lambda,\C}$ is a chain 
of tori such that $\bT_{\lambda,\C}$ is a maximal torus of $\bG_{\lambda,\C}$
and $\bT_{\lambda,\C}^{\ss}$ is a maximal torus of $\bG_{\lambda,\C}^{\der}$, 
then the conjugacy class of the chain in $\GL_{n,\C}$ is independent of $\lambda$.} \cite{Hui13}.
In particular, the formal character of the semisimple subgroup $\bG_{\lambda,\C}^{\der}\subset\GL_{n,\C}$ is independent of $\lambda$.
\end{enumerate}
We say that the compatible system \eqref{cs} is \emph{connected} if $\bG_\lambda$
is connected for some $\lambda$ (hence for all $\lambda$, by assertion (A)).
Via assertion (C), we can connect the $\lambda$-independence of $\bG_\lambda\hookrightarrow\GL_{n,\overline E_\lambda}$ with the terminologies  
in $\mathsection\ref{s1.1}$ on rectangular representations (that depend solely on the formal character of the semisimple part)
as follows.

\begin{enumerate}[(D)]
\item If the faithful representation $\bG_{\lambda,\C}\hookrightarrow\GL_{n,\C}$ is rectangular for one $\lambda$,
this is true for all $\lambda$. Moreover, the set of length of the rectangular $\bG_{\lambda,\C}\hookrightarrow\GL_{n,\C}$
is independent of $\lambda$.
\end{enumerate}

\noindent By (D), it makes sense to call the semisimple compatible system $\{\rho_\lambda\}$ \emph{rectangular} if  the faithful representation
$\bG_{\lambda,\C}\hookrightarrow\GL_{n,\C}$ is rectangular for some $\lambda$;
the \emph{set of lengths} $\mathscr L_\rho$ of the rectangular compatible system $\{\rho_\lambda\}$ is defined to be 
the set of lengths of $\bG_{\lambda,\C}\hookrightarrow\GL_{n,\C}$.

\subsubsection{}\label{s1.2.2} We now state our results on $\lambda$-independence of algebraic monodromy groups
for certain compatible systems, relating them to the classification results in $\mathsection\ref{s1.1.2}$.
First, as a direct consequence of Corollary \ref{cor_L at most 2 at most 3}(ii) and (C) above, we obtain a positive answer 
(on the identity components $\bG_{\lambda,\C}^\circ$) to question Q3(i) 
for certain rectangular compatible systems.

\begin{thm}\label{thm_main3}
    Let $K$ be a number field and $\{\rho_{\lambda}: \mathrm{Gal}_K \to \mathrm{GL}_n(\overline E_{\lambda})\}_{\lambda \in \Sigma_E}$ 
		be a compatible system of semisimple $\lambda$-adic representations of $K$ defined over a number field $E$. 
		Suppose the following conditions are satisfied.
    \begin{enumerate}[(a)]
				\item $\{\rho_{\lambda}\}$ is rectangular.
				\item The set of lengths $\mathscr L_\rho$ has only even numbers and at most one $2$.
    \end{enumerate}
		Then the algebraic monodromy group $\bG_{\lambda,\C}$ is of type $A_1$ (i.e., $\mathrm{Lie}(\bG_{\lambda,\C}^{\der})=A_1\times\cdots\times A_1$), 
		the identity component $\bG_{\lambda,\C}^\circ$ is irreducible on the ambient space 
		and its conjugacy class in $\mathrm{GL}_{n,\C}$ is independent of $\lambda$. 

