Now assume $K$ is totally real and $\rho_\lambda$ is $\GL_n(E_\lambda)$-valued for all $\lambda$.
By adopting the techniques in \cite{Hui23a,Hui23b},\cite{HL24} (combining various Galois theoretic
and representation theoretic results), we obtain the following $\lambda$-independence results.

\begin{thm}\label{thm_main2}
    Let $K$ be a totally real field and $\{\rho_{\lambda}: \mathrm{Gal}_K \to \mathrm{GL}_n(E_{\lambda})\}_{\lambda \in \Sigma_E}$ be a compatible system of semisimple $\lambda$-adic representations of $K$ defined over a number field $E$. 
		Suppose the following conditions are satisfied.
    \begin{enumerate}[(a)]
		\item $\{\rho_{\lambda}\}$ is strictly compatible and regular.
        \item $\{\rho_{\lambda}\}$ is connected.
        \item $\{\rho_{\lambda}\}$ is rectangular.
				\item  The set of lengths $\mathscr L_\rho$ has at most one $2$ and at most one $3$.
  %  If we assume either
   % \begin{enumerate}
     %   \item[\normalfont(c1)] A compatible system $\{\rho_{\lambda}\}_{\lambda}$ is regular, or
     %   \item[\normalfont(c2)] $K=\mathbb Q$ and every two-dimensional irreducible subrepresentation of the $\mathrm{GL}_2^r$-valued lift (Definition~\ref{def_GL2r lift}) of an irreducible subrepresentation of $\rho_{\lambda_0}$ is odd, 
    \end{enumerate}
    Then the algebraic monodromy group $\bG_{\lambda,\C}$ is of type $A_1$  
		and its conjugacy class in $\mathrm{GL}_{n,\C}$ is independent of $\lambda$.
\end{thm}

\begin{remark}\label{remark1.7}
Here are a few remarks about the conditions of the theorem.
Let $\pi$ be a regular algebraic, polarized, cuspidal automorphic representation of $\GL_n(\A_K)$,
where $K$ is totally real.
If the compatible system is associated to $\pi$ (see e.g., \cite{BLGGT14}),
then (a) holds. If, for some $\lambda$, the semisimple group $\bG_{\lambda,\C}^{\der}$
is of type $A_1$ and acts irreducibly on the ambient space, then (c) holds.
If (c) holds and the dimension $n$ is not divisible by $4$ and $9$, then obviously (d) holds.
Note that (b),(c),(d) and Corollary \ref{cor_L at most 2 at most 3}(i) imply that $\bG_{\lambda,\C}$ is connected and 
of type $A_1$ for all $\lambda$. Note that the representation $\bG_{\lambda,\C}\hto \mathrm{GL}_{n,\C}$ can be reducible.

\end{remark} 

\begin{cor}\label{cor1.8}
    Let $K$ be a totally real field and $\{\rho_{\lambda}: \mathrm{Gal}_K \to \mathrm{GL}_n(E_{\lambda})\}_{\lambda \in \Sigma_E}$ be a compatible system of semisimple $\lambda$-adic representations of $K$ defined over a number field $E$. 
		Suppose the following conditions are satisfied.
    \begin{enumerate}[(a)]
        \item $\{\rho_{\lambda}\}$ is strictly compatible and regular.
				%The representation $\rho_{\pi, \lambda_0}$ is irreducible. 
        \item $\{\rho_{\lambda}\}$ is connected.
				%The algebraic monodromy group $\bG_{\lambda_0,\overline E_{\lambda_0}}$ is connected and of type $A_1$.
        \item For some $\lambda_0$, $\bG_{\lambda_0,\C}^{\der}$ is of type $A_1$ and is irreducible on the ambient space.
				\item The set of lengths $\mathscr L_\rho$ has at most one $2$ and at most one $3$.
				%Both the number of basic factors $(\mathrm{SL}_{2},\mathrm{std})$ and the number of basic factors $(\mathrm{SL}_{2},\mathrm{Sym}^2)$ in the \textcolor[rgb]{1,0,0}{external} tensor decomposition of the tautological representation of $\bG_{\lambda_0,\overline E_{\lambda_0}}^{\mathrm{der}}$ are at most $1$.
    \end{enumerate}
    Then the following statements hold.
    \begin{enumerate}[(i)]
        \item The conjugacy class of $\bG_{\lambda,\C}$ in $\mathrm{GL}_{n,\C}$ is independent of $\lambda$.
        \item The representation $\rho_{\lambda}$ is absolutely irreducible for all $\lambda$.
		\item The residual representation of $\rho_{\lambda}$ is absolutely irreducible for almost all $\lambda$.
   \end{enumerate}
\end{cor}

\begin{remark}
When we replace \ref{cor1.8}(a) by the stronger condition that $\{\rho_\lambda\}$
is associated to the automorphic representation $\pi$ in Remark \ref{remark1.7}, 
this result is obtained previously in \cite[Theorem~1.1]{HL24}.
Therefore, Corollary \ref{cor1.8} can be viewed as 
a partial generalization of \cite[Theorem~1.1]{HL24} from automorphic compatible systems 
to regular strictly compatible systems.
\end{remark}



