\begin{prop}\label{Bnroot} 
The following assertions hold about the root system $\Phi_{B_n}$ of $B_n$.
\begin{enumerate}[(i)]
\item Any root $\alpha\in\Phi_{B_n}$ in \eqref{rootsys} has at most two non-zero coordinates.
\item If $\alpha\in \Phi_{B_n}$, then $-\alpha\in \Phi_{B_n}$ and the line spanned by $\alpha$ has exactly two roots. 
\item Suppose $n\geq 2$, and let $\alpha=\epsilon_1e_i+\epsilon_2e_j$ and $\beta=\epsilon_3 e_k+\epsilon_4 e_l$ 
be two linearly independent long roots in $\Phi_{B_n}$ (where 
$\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4\in\{\pm1\}$), 
$P$ be the plane spanned by $\{\alpha,\beta\}$,
and $d$ be the dimension of the space spanned by $\{e_i,e_j,e_k,e_l\}$. If $d=4$ (resp. $d=3$),
then $P$ has exactly $4$ (resp. $6$) roots and all of them are long.
\item If $n\geq 2$ and $P$ is a plane in $\R^n$ containing $8$ roots in $\Phi_{B_n}$,
then $P$ is standard and has exactly $8$ roots ($4$ long and $4$ short).
\item If $n\geq 3$ and $Q$ is a $3$-space in $\R^n$ containing $12$ long roots in $\Phi_{B_n}$,
then $Q$ is either standard or there exist a four dimensional standard subspace $U$ with 
basis $\{e_i,e_j,e_l,e_s\}$ and $\delta_1,\delta_2,\delta_3\in\{\pm 1\}$ such that $Q$ is the orthogonal complement of 
$v:=e_i+\delta_1 e_j+\delta_2e_l+\delta_3e_s$ in $U$.
\end{enumerate}
\end{prop}

\begin{proof}
The assertions (i),(ii),(iii) follow easily from \eqref{rootsys}.

For (iv), we pick two roots $\alpha,\beta$ that span $P$. If $P$ is not standard,
then the pair has either one long root or two long roots. In the first case, we may 
assume $\alpha=e_i$, $\beta= e_j+\epsilon e_k$, 
$\epsilon\in\{\pm1\}$ by (ii), and that $\{e_i,e_j,e_k\}$ spans a $3$-space.
Since $P$ contains $8$ roots, there exists a root $\gamma\in P$ not belonging to $\{\pm \alpha,\pm\beta\}$.
Hence, $\gamma= a\alpha +b\beta$ for some non-zero $a,b\in\R$ but this contradicts (i).
The second case is impossible by (iii) and the assumption that $P$ contains $8$ roots. 
Therefore, we conclude that $P$ is standard and has exactly $8$ roots.

For (v), we pick three long roots $\alpha= e_i+\epsilon_1 e_j,
\beta= e_k+\epsilon_2 e_l,\gamma= e_r+\epsilon_3 e_s$ that span $Q$ by (ii),
where $\epsilon_1,\epsilon_2,\epsilon_3\in\{\pm1\}$.
Let $d$ be the dimension of the space spanned by $\{e_i,e_j,e_k,e_l,e_r,e_s\}$
and $P_{\alpha,\beta}$, $P_{\alpha,\gamma}$, $P_{\beta,\gamma}$ 
be the planes spanned by respectively $\{\alpha,\beta\}$, $\{\alpha,\gamma\}$, and $\{\beta,\gamma\}$.
If $d=5$ (resp. $6$), it follows from linear independence of $\{\alpha,\beta,\gamma\}$ and (i) that 
every root in $Q$ belongs to $P_{\alpha,\beta}\cup P_{\alpha,\gamma}\cup P_{\beta,\gamma}$,
and then (iii) implies that $Q$ has exactly $8$ (resp. $6$) roots. But this is absurd.
If $d=3$, then $Q$ is standard. Now suppose $d=4$. 
If $P_{\alpha,\beta}$ is standard, then $\{i,j\}=\{k,l\}$, $\{i,j\}\cap \{r,s\}=\emptyset$, and (iii) implies that 
$Q$ has exactly $6$ long roots, which is absurd.
Hence, all planes $P_{\alpha,\beta}$, $P_{\alpha,\gamma}$, $P_{\beta,\gamma}$ are not standard.
Without loss of generality, we assume $\{i,j\}\cap \{k,l\}=\{k\}$ 
and $\{i,j\}\cap \{r,s\}=\{r\}$. Then $Q$ is the orthogonal complement of 
$U$ (spanned by $\{e_i,e_j,e_l,e_s\}$) of some $v=e_i+\delta_1 e_j+\delta_2e_l+\delta_3e_s$.
\end{proof}

\begin{remark}
The orthogonal complement of $v=e_i+\delta_1 e_j+\delta_2e_l+\delta_3e_s$ in $U$ in (v) above contains exactly $12$ (long) roots.
\end{remark}

\begin{prop}\label{BnWeyl} 
Let $W_{B_n}$ denote the Weyl group of $B_n$.
\begin{enumerate}[(i)]
\item Let $\mathbb{H}_n:=[-1,1]^n\subset\R^n$ be the standard $n$-dimensional hypercube. 
Then $W_{B_n}$ is 
equal to $\{\phi\in O(\R^n):~\phi~\text{preserves}~\mathbb{H}_n\}$ and satisfies
$$0\to (\Z/2\Z)^n\to W_{B_n}\to S_n\to 0,$$
a (split) short exact sequence of groups where $S_n$ is the symmetric group of $n$ elements.
\item Any reflection $\sigma\in W_{B_n}$ is induced from a root $\alpha\in B_n$, i.e., the $-1$-eigenspace of $\sigma$ is spanned by $\alpha$.
\end{enumerate}
\end{prop}

\begin{proof}
The assertion (i) is well-known (see e.g., \cite[$\mathsection$~12.1]{Hum78}), and
(ii) follows from \cite[Proposition~1.14]{Hum90}.
\end{proof}

\subsection{Rectangular and hypercubic subsets}\label{s2.2}

\begin{defi}\label{rectangle}
For $d\in\Z_{\geq 0}$, define $Z_d:=\{-d,-d+2,-d+4,...,d-2,d\}\subset\Z$.
Let $V_\R$ be an $n$-dimensional real vector space.
\begin{enumerate}[(1)]
\item A subset $\Xi\subset V_\R$ is said to be 
\emph{rectangular} if there is an $\R$-isomorphism $\iota:V_\R\to \R^n$ such that 
$\iota(\Xi)=Z_{d_1}\times Z_{d_2}\times\cdots\times Z_{d_n}$
for some $(d_1,d_2,...,d_n)\in\Z_{\geq0}^n$. In this case, we say that 
$\Xi$ is isomorphic to $Z_{d_1}\times Z_{d_2}\times\cdots\times Z_{d_n}$ and the multiset 
$$\mathscr L_\Xi:=\{\ell_i:=|Z_{d_i}|=d_i+1:~1\leq i\leq n\}$$ 
is called the \emph{set of lengths}\footnote{This notation is well-defined by Proposition \ref{matching} below} of $\Xi$. 
\item If moreover $d_1=d_2=\cdots=d_n$, then $\Xi$ is said to be \emph{hypercubic}
and $\ell=d_1+1$ is called the \emph{length} of $\Xi$.
\end{enumerate}
\end{defi}

By definition, we have $|\Xi|=\prod_{i=1}^n \ell_i$.

\begin{prop}\label{matching}
Let $0\leq d_1\leq d_2\leq \cdots \leq d_n$ and $0\leq d_1'\leq d_2'\leq \cdots \leq d_n'$ be integers.
Suppose $\phi:\R^n\to\R^n$ is an isomorphism taking
$\Xi= Z_{d_1}\times\cdots\times Z_{d_n}$ to $\Xi'= Z_{d_1'}\times\cdots\times Z_{d_n'}$.
The following assertions hold.
\begin{enumerate}[(i)]
\item The numbers of zeros in the multisets $\{d_1,...,d_n\}$ and $\{d_1',...,d_n'\}$ are equal.
\item For all $1\leq i\leq n$, one has $d_i=d_i'$.
\item If $d_1,d_1'>0$, then $\phi(e_i)=\pm e_j$ where $d_i=d_j'$. 
\end{enumerate}
\end{prop}

\begin{proof}
Since the sum of the number of zeros in $\{d_1,...,d_n\}$ (resp. $\{d_1',...,d_n'\}$) 
and the dimension of $\mathrm{Span}\Xi$ (resp. $\mathrm{Span}\Xi'$) is equal to $n$,
the assertion (i) follows from $\mathrm{Span}\Xi\simeq \mathrm{Span}\Xi'$.

For (ii), we may assume $d_1,d_1'>0$ by (i). For a subset $S\subset\R^n$, define $m(S):=\{\frac{s_1+s_2}{2}:~ s_1,s_2\in S\}$ as the set
of mid-points. If $\phi:\R^n\to\R^n$ is an isomorphism, then $\phi(m(S))=m(\phi(S))$.
Define $M_d:=m(Z_{d})=\{x\in\Z: ~-d\leq x\leq d\}$ for $d\in\N$ and note that 
\begin{itemize}
\item $m(\Xi)=m(Z_{d_1})\times m(Z_{d_2})\times\cdots\times m(Z_{d_n})=M_{d_1}\times M_{d_2}\times\cdots\times M_{d_n}$, 
\item $\phi(M_{d_1}\times M_{d_2}\times\cdots\times M_{d_n})=M_{d_1'}\times M_{d_2'}\times\cdots\times M_{d_n'}$, and
\item $\pi_i(m(\Xi))\subset m(\Xi)$, where $\pi_i:\R^n\to\R$ denotes the projection to the $i$th coordinate.
\end{itemize}

Let $0<k_1<k_2<\cdots< k_r$ and $n_1,n_2,...,n_r$ be positive integers such that 
\begin{equation}\label{product1}
m(\Xi)=M_{d_1}\times M_{d_2}\times\cdots\times M_{d_n}= M_{k_1}^{n_1}\times M_{k_2}^{n_2}\times 
\cdots\times M_{k_r}^{n_r}.
\end{equation}

Let $0<\ell_1<\ell_2<\cdots< \ell_s$ and $m_1,m_2,...,m_s$ be positive integers such that 
\begin{equation}\label{product2}
m(\Xi')=M_{d_1'}\times M_{d_2'}\times\cdots\times M_{d_n'}= M_{\ell_1}^{m_1}\times M_{\ell_2}^{m_2}\times \cdots\times M_{\ell_s}^{m_s}.
\end{equation}

\begin{lemma}\label{lem_phi zero first part}
In equations \eqref{product1} and \eqref{product2}, $k_r=\ell_s$ and $n_r=m_s$.
Moreover, 
\begin{equation}\label{equalpart}
\phi(0_{\R^{n-n_r}}\times M_{k_r}^{n_r})=0_{\R^{n-m_s}}\times M_{\ell_s}^{m_s}.
\end{equation}
\end{lemma}

\begin{proof}
Consider a standard basis vector $e_i$ in $0_{\R^{n-n_r}}\times M_{k_r}^{n_r}$.
Then
\begin{equation}\label{nonzero}
\phi(e_i),\phi(k_r e_i)\hspace{.1in} \text{are non-zero in}\hspace{.1in} M_{\ell_1}^{m_1}\times M_{\ell_2}^{m_2}\times \cdots\times M_{\ell_s}^{m_s}.
\end{equation}
It follows that 
$k_r\leq \ell_s$ and thus $k_r=\ell_s$ by symmetry.
Since $\ell_1,...,\ell_{s-1}<\ell_s=k_r$, the assertion \eqref{nonzero}
implies that $\phi(e_i)\in 0_{\R^{n-m_s}}\times M_{\ell_s}^{m_s}$
and thus $\phi(0_{\R^{n-n_r}}\times M_{k_r}^{n_r})\subset 0_{\R^{n-m_s}}\times M_{\ell_s}^{m_s}$.
We obtain \eqref{equalpart} by symmetry and $n_r=m_s$.
\end{proof}

\begin{lemma}\label{lem_phi zero second part}
In equations \eqref{product1} and \eqref{product2}, one has
\begin{equation}\label{equalpart2}
\phi(M_{k_1}^{n_1}\times \cdots\times M_{k_{r-1}}^{n_{r-1}}\times 0_{\R^{n_r}})=M_{\ell_1}^{m_1}\times 
\cdots\times M_{\ell_{s-1}}^{m_{s-1}}\times 0_{\R^{m_s}}.
\end{equation}
\end{lemma}

\begin{proof}
Suppose $v\in M_{k_1}^{n_1}\times \cdots\times M_{k_{r-1}}^{n_{r-1}}\times 0_{\R^{n_r}}$. If $\phi(v)$ in \eqref{product2} is not contained in the right-hand side of \eqref{equalpart2},
then \eqref{equalpart} implies that
there exists $v'\in 0_{\R^{n-n_r}}\times M_{k_r}^{n_r}$ such that $\phi(v+v')$ lies outside \eqref{product2},
which is absurd. We obtain \eqref{equalpart2} by symmetry.
\end{proof}

Since Lemma~\ref{lem_phi zero first part} and \ref{lem_phi zero second part} imply that the two direct products in \eqref{product1} and \eqref{product2} are identical
and $\phi$ preserves each component,
we obtain the assertion (ii) and it suffices to consider $\Xi=\Xi'=L_d^n$ for (iii).

We would like to check that $\phi$ preserves $\{\pm e_i:~1\leq i\leq n\}\subset M_d^n$.
The case $n=1$ is trivial, so assume $n \geq 2$. 
Since $de_i\in M_d^n$, we obtain $d\phi(e_i)=\phi(de_i)\in M_d^n\subset\Z^n$.
Thus, if  $\phi(de_i)=(x_1,x_2,...,x_n)\in\Z^n$ then
\begin{itemize}
\item $|x_\ell|\in\{0,d\}$ for all $1\leq \ell\leq n$ and
\item not all $x_\ell$ is zero.
\end{itemize}
Suppose there are two coordinates $x_\ell$ with absolute value $d$. By pigeon-hole principle,
there exists $e_j\neq e_i$ such that the absolute value 
of some coordinate of $de_i\pm de_j$ is $2d$. But this contradicts that $\phi(de_i\pm de_j)\subset M_d^n$.
\end{proof}

\begin{defi}
Let $0< d_1<d_2<\cdots <d_r$ and $n_1,n_2,...,n_r$ be positive integers, where $r\in\N$.
Let $n:=n_1+n_2+\cdots+ n_r$ and define the automorphism groups
$$\Omega_i:=\{\phi\in\GL_{n_i}(\R):~\phi~\text{preserves}~Z_{d_i}^{n_i}\subset\R^{n_i}\}$$ for $1\leq i\leq r$
and 
$$\Omega:=\{\phi\in\GL_n(\R):~\phi~\text{preserves}~ Z_{d_1}^{n_1}\times Z_{d_2}^{n_2} \times\cdots\times
Z_{d_r}^{n_r}\subset\R^n\}.$$
\end{defi}

\begin{cor}\label{auto}
Under the standard Euclidean metric on $\R^n$, 
there are natural identifications 
\begin{enumerate}[(i)]
\item $\Omega_i=W_{B_{n_i}}$ for all $i$ and
\item $\Omega=\Omega_1\times\Omega_2\times\cdots\times\Omega_r$.
\end{enumerate}
In particular, $\Omega$ is orthogonal.
\end{cor}

\begin{proof}
Since $\Omega_i$ has $2^{n_i} n_i!$ elements and preserves $\mathbb{H}_{n_i}$ the hypercube by 
Proposition \ref{matching}(iii), the assertion (i) holds by Proposition \ref{BnWeyl}(i).
The assertion (ii) follows from Proposition \ref{matching}(iii).
\end{proof}

\subsection{Rectangular and hypercubic representations}\label{s2.3}

Let $\Lieg$ be a complex semisimple Lie algebra of rank $n$. Fix a Cartan subalgebra $\Liet$ of $\Lieg$ and 
denote by $\Lambda_\Lieg$ the weight lattice of $\Lieg$ with respect to $\Liet$, regarded as a rank $n$ lattice in $\Lambda_\Lieg\otimes\R\cong\R^n$. 


\begin{defi}\label{rectrepn}
A Lie algebra homomorphism $\psi:\Lieg\to\End(V)$ of the semisimple Lie algebra $\Lieg$ is determined
by its \emph{formal character} $\psi|_\Liet$, which corresponds to a multiset $\Xi$ of weights in $\Lambda_\Lieg$.
We identity the formal character with the multiset $\Xi$.
\begin{enumerate}[(1)]
\item We say that $\psi$ is \emph{rectangular} (resp. \emph{hypercubic}) if 
 each weight of $\Xi$ is of multiplicity one and
the subset $\Xi\subset\Lambda_\Lieg\otimes\R$ is rectangular (resp. hypercubic). 
\item In this case, 
we say that the weights in $\Xi$ are rectangular (resp. hypercubic) and we 
define the \emph{set of lengths} $\mathscr L_\psi$ of $\psi$ to be $\mathscr L_\Xi$ 
(resp. the \emph{length} of $\psi$ to be the length of $\Xi$).
\item A rectangular representation $(\Lieg,\psi)$ is said to be \emph{decomposable}
if there exist rectangular representations $(\Lieg_1,\psi_1)$ and $(\Lieg_2,\psi_2)$
such that $\Lieg=\Lieg_1\times\Lieg_2$ and $\psi\simeq\psi_1\otimes\psi_2$ as an external tensor product.
If such decomposition does not exist, we say that $(\Lieg,\psi)$ is \emph{indecomposable}.
\end{enumerate}
\end{defi}



\begin{remark}
If $\psi$ above is faithful and rectangular, then the lengths of $\Xi$ are at least $2$ because 
$\Xi$ spans $\Lambda_\Lieg\otimes\R$.
\end{remark}

\begin{example}\label{example}
Here are some indecomposable hypercubic representations.
\begin{enumerate}[(1)]
\item The one-dimensional trivial representation is hypercubic of length $1$.
\item Any irreducible representation of $A_1$.
\item The direct sum $V_1\oplus V_2$ of two irreducible representations of $A_1$ whose dimensions differ by $1$.
\item (\cite[$\mathsection20$]{FH91}) The spin representation $\mathrm{Spin}$ of $B_n$ for $n\in\N$ (resp. $D_n$ for $n\in\N_{\geq 2}$)
is of dimension $2^n$. It 
is hypercubic of length $2$ with formal character $\Xi$ equal to
$$\{(\pm 1/2,\pm 1/2,...,\pm 1/2)\in\R^n\}$$
if the root system is identified with \eqref{rootsys}. Note that $(B_n,\mathrm{Spin})$ is irreducible
and $(D_n,\mathrm{Spin})=(D_n,\mathrm{Spin}^+\oplus \mathrm{Spin}^-)$ is the sum 
of two irreducible half-spin representations.
\item The direct sum $\mathrm{Std}\oplus\mathrm{Spin}$ representation of $B_2$ is hypercubic of length $3$
with formal character $\Xi$ equal to 
$$\{(\pm 1,0),(0,\pm 1), (0,0)\}\cup \{(\pm 1/2,\pm 1/2)\}\subset\R^2$$
if the root system is identified with \eqref{rootsys}. Note that the restriction of such representation
to the subalgebra $A_1\times A_1\subset B_2$ 
is the external tensor product $(A_1, \mathrm{Std}\oplus \mathbb 1)\otimes (A_1, \mathrm{Std}\oplus \mathbb 1)$.
\end{enumerate}
\end{example}

\begin{remark}
Theorem \ref{main1} asserts that any faithful rectangular representation of a semisimple Lie algebra
is the external tensor product of these indecomposable hypercubic representations in a unique way.
\end{remark}

\subsection{Reduction to the hypercubic case}\label{s2.4}
Let $I$ be a finite index set. For each $i \in I$, let $\Lieg_i$ be a complex semisimple Lie algebra with  corresponding weight lattice $\Lambda_{\Lieg_i}$ (with respect to a Cartan subalgebra $\Liet_i$) and Weyl group $W_{\Lieg_i}$. 
The weight lattice $\Lambda_\Lieg$ of the product 
$\Lieg:=\prod_{i\in I}\Lieg_i$ (with respect to Cartan subalgebra $\prod_{i\in I}\Liet_i$) is identified as
$\bigoplus_{i\in I}\Lambda_{\Lieg_i}$. The following lemmas are well-known.

\begin{lemma}\label{wk1}
The action of the Weyl group $W_{\Lieg}$ of $\Lieg$ on $\Lambda_{\Lieg}\otimes\R$ 
is identified as the action of $\prod_{i\in I}W_{\Lieg_i}$ on 
$\bigoplus_{i\in I}(\Lambda_{\Lieg_i}\otimes\R)$.
If $\Lieg_i$ is simple, then the action of $W_{\Lieg_i}$ on $\Lambda_{\Lieg_i}\otimes\R$
is irreducible and non-trivial.
\end{lemma}

\begin{lemma}\label{wk2}
Suppose $\Lambda_{\Lieg}\otimes\R$ 
is equipped with a positive definite metric $||\cdot||$ such that $W_{\Lieg}$ is orthogonal.
The following assertions hold.
\begin{enumerate}[(i)]
\item The direct sum decomposition 
$\Lambda_{\Lieg}\otimes\R=\bigoplus_{i\in I}(\Lambda_{\Lieg_i}\otimes\R)$
is orthogonal.
\item If $\Lieg_i$ is a simple, the restriction of $||\cdot||$ to the subspace $\Lambda_{\Lieg_i}\otimes\R$
is, up to a positive scalar, induced from the Killing form of $\Lieg_i$.
\end{enumerate}
\end{lemma}

The following general result is crucial to decomposing representations.

\begin{prop}\label{decompose}
Let $\Lieg_1,\Lieg_2$ be semisimple Lie algebras and 
$\psi: \Lieg_1\times\Lieg_2\to \End(V)$ be a representation such that the formal character 
$\Xi\subset \Lambda_{\Lieg_1\times\Lieg_2}=\Lambda_{\Lieg_1}\oplus\Lambda_{\Lieg_2}$ 
is a direct product of multisets:
\begin{equation}\label{dp}
\Xi=\Xi_1\times\Xi_2:=\{(w_1,w_2)\in\Lambda_{\Lieg_1}\oplus\Lambda_{\Lieg_2}:~ w_1\in\Xi_1,~w_2\in\Xi_2\},
\end{equation}
where $\Xi_1$ (resp. $\Xi_2$) is a finite multiset in $\Lambda_{\Lieg_1}$ (resp. $\Lambda_{\Lieg_2}$).
Then there exist representations $\psi_i:\Lieg_i\to\End(V_i)$ with formal character $\Xi_i$ for $i=1,2$
such that $\psi$ is isomorphic to 
\begin{equation*}\label{tensor}
\psi_1\otimes\psi_2:\Lieg_1\times\Lieg_2\to\End(V_1\otimes V_2).
\end{equation*}
\end{prop}

\begin{proof}
Pick a Weyl chamber $C_i$ for $\Lambda_{\Lieg_i}\otimes\R$ and 
we define $w_i\in \Lambda_{\Lieg_i}$ to be dominant if $w_i\in C_i$, $i=1,2$. 
The product $C_1\times C_2$ is a Weyl chamber for $\Lambda_{\Lieg_i}\otimes\R$
and we define $(w_1,w_2)\in\Lambda_{\Lieg_2\times\Lieg_2}$ to be dominant if $(w_1,w_2)\in C_1\times C_2$.
Hence, $(w_1,w_2)$ is dominant if and only if $w_i$ is dominant for $i=1,2$.

We proceed by induction on the size $k$ of the multiset $\Xi$. It is obvious for $k=1$.
In general, let $(w_1,w_2)\in\Xi$ be a highest weight, corresponding to an irreducible 
subrepresentation $U$ of $V$ by the theorem of highest weight. 
Then $w_i$ is a highest weight in $\Xi_i$ for $i=1,2$ by \eqref{dp}, and
we obtain $U\simeq U_1\otimes U_2$ where 
$U_i$ is the irreducible representation of $\Lieg_{i}$ corresponding to $w_i$ for $i=1,2$.
Let $\Xi_{U_i}$ be the formal character of $U_i$.
If $\Xi_{U_1}=\Xi_1$ or $\Xi_{U_2}=\Xi_2$, then the 
formal character $\Xi'$ of $V- U$ is the direct product $\Xi_1\times (\Xi_2\backslash \Xi_{U_2})$ 
or $(\Xi_1\backslash \Xi_{U_1})\times \Xi_2$ respectively
and we are done by the induction hypothesis.
Otherwise, we pick a highest weight $w_2'\in \Xi_2\backslash \Xi_{U_2}$ so 
that $(w_1,w_2')\in \Xi'$ is highest, corresponding to 
the irreducible subrepresentation $U'\simeq U_1\otimes U_2'$ of $V-U$
(where $U_2'$ is the irreducible representation of $\Lieg_2$ corresponding to $w_2'$).

If $\Xi_2=\Xi_{U_2}\cup \Xi_{U_2'}$ (multiset union), then the formal character $\Xi''$
of $V-U-U'$ is the direct product $(\Xi_1\backslash \Xi_{U_1})\times \Xi_2$ and we are done by induction hypothesis.
Otherwise, we can find a highest weight $w_2''$ in $\Xi_2\backslash (\Xi_{U_2}\cup \Xi_{U_2'})$
corresponding to the irreducible representation $U_2''$ such that $U_1\otimes U_2''$ is an irreducible 
subrepresentation of $V-U-U'$. Ultimately, we find (by an inductive argument and $\Xi_2$ finite) 
a representation $V_2=U_2\oplus U_2'\oplus U_2''\oplus\cdots$
of $\Lieg_2$ with formal character $\Xi_2$ such that the formal character of $V-U_1\otimes V_2$ is
the direct product $(\Xi_1\backslash \Xi_{U_1})\times \Xi_2$. We are done by the induction hypothesis.
\end{proof}

The following result enables us to reduce the problem to the hypercubic
case.

\begin{prop}\label{reduction1}
Let $\Lieg$ be a complex semisimple Lie algebra
and $(\Lieg,\psi)$ be a faithful rectangular representation with formal character 
$\Xi\subset\Lambda_\Lieg\otimes\R$ isomorphic to 
\begin{equation}\label{normal}
Z_{d_1}^{n_1}\times Z_{d_2}^{n_2} \times\cdots\times Z_{d_r}^{n_r}\subset \R^n,
\end{equation}
where $0<d_1<d_2<\cdots< d_r$ and $n_1,n_2,...,n_r$ are positive integers, and 
$n=n_1+n_2+\cdots+n_r$.
Then $\Lieg=\prod_{1\leq i\leq r}\Lieg_i$ is a product of semisimple Lie algebras $\Lieg_i$
and $\psi=\bigotimes_{1\leq i\leq r}\psi_i$ is the external tensor product of the faithful hypercubic 
representations $(\Lieg_i,\psi_i)$ with formal characters  $\Xi_i\subset \Lambda_{\Lieg_i}\otimes\R$ isomorphic
to $Z_{d_i}^{n_i}\subset\R^{n_i}$.
\end{prop}

\begin{proof}
Write $\Lieg=\prod_{j\in J}\Lieq_j$ as a product of simple Lie algebras.
Without loss of generality, suppose $\Xi\subset\Lambda_\Lieg\otimes\R$ is equal to \eqref{normal}
and equip $\R^n$ as the standard Euclidean metric. Since $W_{\Lieg}$ preserves the formal 
character $\Xi$, the Weyl group $W_{\Lieg}\subset \Omega$ is orthogonal by Corollary \ref{auto}.
For each $1\leq i\leq r$, define the $n_i$-dimensional subspace
$$Y_i:=\text{Span}_\R\{e_j:~ n_1+\cdots+n_{i-1}< j\leq n_1+\cdots+n_{i-1}+n_i\}.$$
It follows that $Y_i$ is a $W_\Lieg$-subrepresentation of $\mathbb R^n$ (resp. $W_{\Lieq_j}$ for $j\in J$) 
by Corollary \ref{auto}(ii). As $\Lieq_j$ is simple, $\Lambda_{\Lieq_j}\otimes\R$
is a subspace of a unique $Y_i$ by Lemma \ref{wk1}. Therefore, $J$ is
partitioned into $J_1\cup J_2\cup \cdots \cup J_r$ such that 
$Y_i=\bigoplus_{j\in J_i} (\Lambda_{\Lieq_j}\otimes\R)$ (by dimension consideration).
Let $\Lieg_i=\prod_{j\in J_i}\Lieq_j$ for $1\leq i\leq r$. Since $\R^n=Y_1\oplus Y_2\oplus\cdots\oplus Y_r$
and $Y_i$ is standard subspace for all $i$, 
we obtain $\Xi_i:=Z_{d_i}^{n_i}\subset\Lambda_{\Lieg_i}\subset \Lambda_{\Lieg_i}\otimes\R=Y_i$ for all $i$.
Therefore, we are done by applying Proposition \ref{decompose}.
\end{proof}


\subsection{Extracting $A_1$-factors and excluding $A_2$, $A_r$ ($r\geq 4$), and exceptional factors}\label{s2.5}
Let $\psi:\Lieg\to\End(V)$ be a faithful hypercubic representation 
of a semisimple Lie algebra $\Lieg$ and suppose the formal character $\Xi\subset\Lambda_{\Lieg}\otimes\R$ 
is equal to $Z_d^n\subset\R^n$ (Euclidean space).

\begin{prop}\label{extract}
If $\Lieg=\Lieg_1\times\Lieg_2$ where $\Lieg_1$ is a product of $A_1$-factors and $\Lieg_2$ has no $A_1$-factor,
then the following assertions hold.
\begin{enumerate}[(i)]
\item $\Lambda_{\Lieg_1}\otimes\R$ and $\Lambda_{\Lieg_2}\otimes\R$ are standard in $\R^n$.
\item There exist faithful hypercubic representations $\psi_1:\Lieg_1\to\End(V_1)$ and $\psi_2:\Lieg_2\to \End(V_2)$
such that $\psi=\psi_1\otimes\psi_2$.
\item Moreover, $\Lieg_1=\prod_{1\leq j\leq s}\Lieg_{1,j}$ and 
$\psi_1=\bigotimes_{1\leq j\leq s}\psi_{1,j}$ is the external tensor product of the faithful hypercubic 
representations of $\Lieg_{1,j}$ for $1\leq j\leq s$, 
where each $\Lieg_{1,j}$ is either $A_1$ or $A_1\times A_1$.
\end{enumerate}
\end{prop}

\begin{proof}
We prove (i),(ii),(iii) simultaneously by induction on $n$. It is obviously true when $n=1$.
Suppose $\Lieg=A_1\times\Lieg'$ and let $\sigma$ be the reflection in $W_{A_1}\subset W_{\Lieg}$.
Since $W_{\Lieg}$ preserves $Z_d^n$ and thus the hypercube $\mathbb{H}_n$,
it is a subgroup of $W_{B_n}$ (the automorphism group of $\mathbb{H}_n$) by Proposition \ref{BnWeyl}(i).
Then Proposition \ref{BnWeyl}(ii) asserts that $\sigma$ is induced from a root $\alpha$ of $B_n$.
We consider two cases.

If $\alpha$ is a short root, then $\Lambda_{A_1}\otimes \R$ and thus $\Lambda_{\Lieg'}\otimes \R$ (by Lemma \ref{wk2}(i)) are standard subspaces of $\R^n$. By Proposition \ref{decompose},
$\psi$ is the external tensor product of a representation of $A_1$ and a (hypercubic) representation 
$\psi'$ of $\Lieg'$.
The result follows from the induction hypothesis on $\psi'$.


If $\alpha$ is a long root, then $W_{\Lieg'}$ preserves the fixed part
$\mathbb{H}_n^\sigma$ 
of the hypercube under $\sigma$ by Lemmas \ref{wk1} and \ref{wk2}.
Suppose the long root $\alpha=e_1+e_2$ without loss of generality. Then 
\begin{equation}\label{fixpt}
\mathbb{H}_n^\sigma=\{(x_1,x_2)\in\R^2:~ x_1+x_2=0,~|x_1|,|x_2|\leq 1\}\times \mathbb{H}_{n-2}=:L\times \mathbb{H}_{n-2}.
\end{equation}
Since the line segment $L$ has length $2\sqrt{2}$ different from $2$ (length of a side of $\mathbb{H}_{n-2}$),
$W_{\Lieg'}$ preserves each factor in \eqref{fixpt}. Thus, $\text{Span}_\R L$ is a
one-dimensional subrepresentation of $W_{\Lieg'}$.  
By Lemma \ref{wk2}(i) and dimension consideration, we obtain $\Lieg'=A_1\times\Lieg''$
and $W_{A_1}$ acts non-trivially on the line.
It follows that $\Lambda_{A_1\times A_1}\otimes\R=\text{Span}_\R\{e_1,e_2\}$
and $\Lambda_{\Lieg''}\otimes\R= \text{Span}_\R\{e_i: ~i>2\}$
are standard subspaces of $\R^n$.
By Proposition \ref{decompose},
$\psi$ is the external tensor product of a hypercubic representation of $A_1\times A_1$ and a hypercubic representation 
$\psi''$ of $\Lieg''$.
We are done by induction hypothesis on $\psi''$.
\end{proof}

Given a simple Lie algebra $\Lieg$, we list some equal-rank subalgebra $\Lieg'\leq \Lieg$ (using \cite[Table 5]{GOV94}):
\begin{enumerate}
\item $A_1^{r}\leq B_{r}$ for $r\geq 2$.
\item $A_1^r\leq C_r$ for $r\geq 3$.
\item $A_1^{2(r-1)}\times A_3\leq D_{2r+1}$ for $r\geq 1$.
\item $A_1^{2r}\leq D_{2r}$ for $r\geq 2$.
\item $A_2\times A_2\times A_2\leq E_6$, 
\item $A_7\leq E_7$, 
\item $A_8\leq E_8$,
\item $A_2\times A_2\leq F_4$,
\item $A_2\leq G_2$.
\end{enumerate}

\begin{prop}\label{exclude}
Let $\Lieq$ be a simple factor of $\Lieg$. Then $\Lieq$ cannot be of 
type $A_2$, $A_r$ for any $r\geq 4$, and exceptional type.
\end{prop}

\begin{proof}
If $\Lieg'$ is a semisimple subalgebra of $\Lieg$ of equal-rank, then $\psi|_{\Lieg'}$ is also rectangular.
Hence, we may assume each simple factor of $\Lieg$ is of type $A$ by the list above.
By Proposition \ref{extract}, we may further assume that $\Lieg$ has no $A_1$-factor.
To prove the result, it suffices show that $\Lieg$ has only $A_3$-factors.

Write $\Lieg=A_3^r\times \Lieq_1\times\cdots\Lieq_k$ where each $\Lieq_i$ is equal to $A_{n_i}$ 
such that $n_i\in \{2\}\cup\N_{\geq 4}$.
It follows from Lemma \ref{wk1} and Corollary \ref{auto} that 
$$S_3^r\times \prod_{i=1}^k S_{n_i+1}\leq S_4^r\times \prod_{i=1}^k S_{n_i+1}
=W_{A_3}^r\times\prod_{i=1}^k W_{\Lieq_i}=W_\Lieg\subset \Omega=W_{B_n}.$$
Since the symmetric group $S_m$ does not have non-trivial normal $2$-subgroup 
for $m\in\{3\}\cup\N_{\geq 5}$, the homomorphism (via the inclusions above and Proposition \ref{BnWeyl}(i))
$$S_3^r\times \prod_{i=1}^k S_{n_i+1}\hookrightarrow W_{B_n}\to S_n$$
is injective. Since the rank of $\Lieg$ is $n=3r+n_1+\cdots+n_k$, 
we obtain a contradiction by Proposition \ref{symgp}.
Therefore, $\Lieg$ has only $A_3$-factors.
\end{proof}

\begin{prop}\label{symgp}
Let $i: S_{n_1}\times S_{n_2}\times\cdots\times S_{n_k}\to S_n$ be an injective homomorphism such that 
$n_i>1$ for all $1\leq i\leq k$. Then $n_1+n_2+\cdots+n_k\leq n$.
\end{prop}

\begin{proof}
For a finite group $G$, let $\mu(G)$ denote the smallest positive integer $m$ such that there exists an injective homomorphism $G \hookrightarrow S_m$. Wright \cite{Wri75} proved that
$$\mu(S_{n_1}\times S_{n_2}\times\cdots\times S_{n_k})=\sum_{i=1}^k \mu(S_{n_i})=\sum_{i=1}^k n_i,$$
which completes the proof.
\end{proof}

\subsection{Proof of Theorem \ref{main1}(i)}\label{s2.6}
By Propositions \ref{reduction1}, \ref{extract}(ii) and \ref{exclude},
 we may assume that $\psi$ is hypercubic 
and $$\Lieg=\Lieq_1\times\Lieq_2\times\cdots\times\Lieq_k$$ is a product 
of simple Lie algebras such that $\Lieq_i$ is of type 
$B_m$ ($m\geq 2$) or $C_m$ ($m\geq 3$) or $D_m$ ($m\geq 3$ and $D_3=A_3$).
Suppose $\Xi\subset\Lambda_\Lieg\otimes\R$ is equal to $Z_d^n\subset\R^n$.
By Proposition \ref{decompose}, it suffices to show that 
each subspace $\Lambda_{\Lieq_i}\otimes\R\subset\R^n$
is standard.

Let $\Lieq$ be a simple factor of $\Lieg$. Then $W_{\Lieq}$ is a subgroup of $W_{\Lieg}\subset \Omega=W_{B_n}$
by Lemma \ref{wk1} and Corollary \ref{auto}. For a reflection $\sigma\in W_{\Lieq}$, denote the line 
of $-1$-eigenspace of $\sigma$ by $L_{\sigma}\subset\R^n$. We record the following observations.

\begin{lemma}\label{observe}
The following assertions hold for the subspace $\Lambda_{\Lieq}\otimes\R\subset\R^n$.
\begin{enumerate}[(i)]
\item The subspace $\Lambda_{\Lieq}\otimes\R$ 
is spanned by $\{L_\sigma:~\sigma~\text{is a reflection in }W_{\Lieq}\}$.
\item The subspace $\Lambda_{\Lieq}\otimes\R$ 
is spanned by some roots in $\Phi_{B_n}\subset\R^n$ in \eqref{rootsys}.
\end{enumerate}
\end{lemma}

\begin{proof}
The first assertion is obvious, and the second follows from the first assertion and Proposition \ref{BnWeyl}(ii).
\end{proof}

If $\Lieq$ is of type $B_m$ ($m\geq 2$) or $C_m$ ($m\geq 3$), 
then Lemmas \ref{wk2}(ii), \ref{observe}(i), and \eqref{rootsys} 
imply that $\Lambda_{\Lieq}\otimes\R$ is spanned by 
certain planes $P$ such that each $P$ contains four distinct lines $L_\sigma$ 
(coming from the configuration of $B_2$-root system). 
Since the four lines correspond to eight roots of $B_n$ by Proposition \ref{BnWeyl}(ii), 
such $P$ is standard by Proposition \ref{Bnroot}(iv) and thus
$\Lambda_{\Lieq}\otimes\R$ is standard by Lemma \ref{std}.

Now, we suppose $\Lieq$ is of type $D_m$ ($m\geq 3$) and it suffices to show that $\Lambda_{\Lieq}\otimes\R$ is standard. Note the following equal-rank subalgebras $\Lieq'\subset\Lieq$ where $m$ is either $2r+1$ or $2r$.
\begin{enumerate}[(1)]
\item $A_1^{2(r-1)}\times A_3\leq D_{2r+1}$ for $r\geq 1$.
\item $A_1^{2r}\leq D_{2r}$ for $r\geq 2$.
\end{enumerate}
Let $\Lieg'$ be the equal-rank subalgebra of $\Lieg$ obtained by 
restricting the simple factor %$\Lieg$ to $\Lieg'$ simple factor 
$\Lieq$ of $\Lieg$ to $\Lieq'$
and letting all other factors remain unchanged.
Since the restriction $\psi|_{\Lieg'}$ is hypercubic and all the type $A_1$ factors
come from $\Lieg'$, Proposition \ref{extract}(i) implies
that $\Lambda_{A_1^{2(r-1)}}\otimes\R$ if $m=2r+1$ (resp. $\Lambda_{A_1^{2r}}\otimes\R$ if $m=2r$)
is standard. Since $\Lambda_{\Lieq}\otimes\R=\Lambda_{\Lieq'}\otimes\R$ in $\R^n$,
it is standard if we can show that $\Lambda_{A_3}\otimes\R$ is standard.

It remains to consider the case $\Lieq_1=D_3=A_3$.
Lemmas \ref{wk2}(ii), \ref{observe}(i), and \eqref{rootsys} 
imply that $Q:=\Lambda_{\Lieq_1}\otimes\R$ is a $3$-space spanned by six distinct lines $L_\sigma$ 
such that the angle between any two distinct lines is either $90^\circ$ or $60^\circ/120^\circ$.
The six lines contain $12$ roots $\alpha$ of $B_n$ by Proposition \ref{BnWeyl}(ii).
If $\alpha\in L_\sigma$ is a short root, then the angle between $L_\sigma$
and any other of the five lines $L_{\sigma'}$ is a multiple of $45^\circ$ by \eqref{rootsys}.
It follows that $L_\sigma$ is perpendicular to $L_{\sigma'}$ as $60^\circ/120^\circ$
is not a multiple of $45^\circ$. Since $Q$ is a $3$-space, ten roots of $B_n$ lie on the plane
spanned by the five lines,
which is absurd (Proposition \ref{Bnroot}(iv)). 
Hence, the twelve roots $\alpha$ are all long roots of $B_n$.
If $Q$ is not standard, it follows from
Proposition \ref{Bnroot}(v) that there exist a standard $4$-space $U$ spanned by $\{e_i,e_j,e_l,e_s\}$
and $v=e_i+\delta_1e_j+\delta_2e_l+\delta_3e_s$ ($\delta_1,\delta_2,\delta_3\in\{\pm1\}$) such that $Q\subset U$ is the orthogonal complement of $v$ in $U$.
Then Lemma \ref{wk2}(i) implies that 
$$\mathrm{Span}_\R\{e_t:~1\leq t\leq n,~t\notin\{i,j,l,s\}\}\oplus \R v
=(\Lambda_{\Lieq_2}\otimes\R)\oplus\cdots\oplus(\Lambda_{\Lieq_k}\otimes\R).$$
But this equation is impossible by Lemma \ref{observe}(ii), Proposition \ref{Bnroot}(i),
and the fact that $v$ has four non-zero coordinates.
We conclude that $Q$ is standard.
\qed

\subsection{Proof of Theorem \ref{main1}(ii)}\label{s2.7}
By Propositions \ref{reduction1} and \ref{extract}(iii), the rectangular representation $\psi_1$ 
of $\Lieg_1$ is the external tensor product $\bigotimes_{j=1}^{s} \psi_{1,j}$
of the hypercubic representations $\psi_{1,j}$ of $\Lieg_{1,j}$,
where $\Lieg_{1,j}$ is either $A_1$ or $A_1\times A_1$.
If $\Lieg_{1,j}=A_1$, then Theorem \ref{main1}(iia,iib) are the only possibilities
since formal character $\Xi_{1,j}$ of $\psi_{1,j}$ is rectangular and each weight is of multiplicity one.

Next, suppose $\Lieg_{1,j}=A_1\times A_1$ and $\psi_{1,j}$ is not the external tensor product of
two rectangular representations (otherwise, we reduce to previous case).
Let $\Z^2\subset\R^2=\Lambda_{A_1\times A_1}\otimes\R$ 
be the weight lattice of $A_1\times A_1$ so that $\Z\times\{0\}$
(resp. $\{0\}\times \Z$) corresponds to the weight lattice of the first (resp. second) $A_1$.
If $d+1$ (at least $2$) is the length of the faithful hypercubic $\psi_{1,j}$, then 
the formal character is equal to %(Figure 2)
\begin{equation}\label{sq}
\{(x,y)\in\Z^2:~|x|+|y|\leq d~~\text{and}~~ x+y\equiv d~(\text{mod}~2)\}.
\end{equation}

\begin{figure}[h]
\ctikzfig{fig3}
\caption{\eqref{sq} for $d=4$}
\end{figure}

Suppose $\Z_{\geq 0}^2$ is the set of dominant weights.
It follows that $(0,d),(1,d-1),(2,d-2),....,(d,0)$ are highest weights of \eqref{sq}
and thus 
$$\bigoplus_{0\leq i\leq d} (A_1, \mathrm{Sym}^i(\mathrm{Std}))\otimes (A_1, \mathrm{Sym}^{d-i}(\mathrm{Std}))$$
is a subrepresentation of $\psi_{1,j}$. We then obtain
$$(d+1)^2= \sum_{0\leq i\leq d} (d+1)\leq \sum_{0\leq i\leq d} (i+1)(d-i+1) \leq |\Xi_{1,j}|=(d+1)^2,$$
which implies $d+1=(i+1)(d-i+1)$ for all $i$. By putting $i=1$, we obtain $d=1$ and 
$(A_1 \times A_1, \psi_{1,j})=(A_1 \times A_1, (\mathrm{Std} \otimes \mathbb 1) \oplus (\mathbb 1 \otimes \mathrm{Std}))$.\qed

\subsection{Proof of Theorem \ref{main1}(iii)}\label{s2.8}
\subsubsection{}
By Theorem \ref{main1}(i) and Proposition \ref{exclude}, 
it suffices to classify hypercubic representations $\psi$ of simple Lie algebra $\Lieq$,
where $\Lieq$ is $A_3$, or $B_n$ ($n\geq 2$), or $C_n$ ($n\geq 3$), or $D_n$ ($n\geq 4$).
Note that a hypercubic representation $\psi$ is \emph{weight multiplicity-free}, 
i.e., every weight has multiplicity one. 
We present the classification of irreducible weight multiplicity-free representations of simple Lie algebras, as given by Howe.



\begin{theorem}\cite[Theorem~4.6.3]{How92}\label{thm_WMF}
    The non-trivial irreducible weight multiplicity-free representations 
		of a simple Lie algebra are those on the following lists.
    \begin{enumerate}
        \item[$A_n$:] \begin{enumerate}[(i)]
				\item the alternating powers $\bigwedge^m(\C^{n+1})$ of the standard representation, and
				\item the symmetric powers $\mathrm{Sym}^m(\C^{n+1})$ and $\mathrm{Sym}^m(\C^{n+1})^\vee$
				of the standard representation and its dual.
				\end{enumerate}
        \item[$B_n$:] \begin{enumerate}[(i)]
				\item the standard representation on $\C^{2n+1}$, and
				\item the spin representation $\mathrm{Spin}$.
				\end{enumerate}
				\item[$C_n$:] \begin{enumerate}[(i)]
				\item the standard representation on $\C^{2n}$, and
				\item if $n=2$ or $3$, the last fundamental representation, on $\bigwedge_{\mathrm{prim}}^2(\C^4)$
				and $\bigwedge_{\mathrm{prim}}^3(\C^6)$ respectively (of dimensions $5$ and $14$).
				\end{enumerate}
				\item[$D_n$:] \begin{enumerate}[(i)]
				\item the standard representation on $\C^{2n}$, and
				\item the two half-spin representations $\mathrm{Spin}^+$ and $\mathrm{Spin}^-$.
				\end{enumerate}
       \item[$E$:] \begin{enumerate}[(i)]
				\item the two $27$-dimensional representations of $E_6$,  and
				\item the $56$-dimensional representation of $E_7$.
				\end{enumerate}
				\item[$G$:] \begin{enumerate}[(i)]
				\item the $7$-dimensional representation of $G_2$.
				\end{enumerate}
    \end{enumerate}
		There are no non-trivial weight multiplicity-free representations for $E_8$ and $F_4$.
\end{theorem}

\subsubsection{}
We begin by classifying the hypercubic representations for $A_3$. 
The weight lattice of $A_3$ is generated by the weights of the standard representation $\C^4$,
which are four vectors $f_1,f_2,f_3,f_4\in \R^3$ (Euclidean space) 
satisfying $f_1+f_2+f_3+f_4=0$. They can be seen as four vertices of the cube $[-1/2,1/2]^3\subset\R^3$. (Figure 3).

\begin{figure}[h]
\ctikzfig{fig4.1}
\caption{$f_1,f_2,f_3,f_4$ in $[-1/2,1/2]^3$}
\end{figure}

\begin{lemma}\label{lem_lattice line lemma}
    Suppose $\Xi=Z_{d_1}\times Z_{d_2}\times\cdots\times Z_{d_n}\subset \R^n$ is rectangular and $L_1, \ldots,L_r \subset \R^n$ 
		are $r$ affine lines (not necessarily passing through the origin) that satisfy the conditions below.
    \begin{enumerate}[(a)]
        \item $\min_{1\leq i\leq r} |L_i \cap \Xi|=m$,
        \item For any $1\leq j\leq n$, there exists $k \in\{1,2,\ldots,n\}$ such that $\pi_j(L_k)=\mathbb R$, where $\pi_j:\R^n\to\R$ denotes projection to the $j$th component.
    \end{enumerate} Then, $|\Xi| \geq m^n$.
\end{lemma}

\begin{proof}
   One has from $\pi_{1}(L_{i_{1}}), \ldots, \pi_{n}(L_{i_n}) =\mathbb R$ for some indices $1 \leq i_{1}, \ldots, i_n \leq r$ that
    \begin{align*}
        |Z_{d_j}|=|\pi_j(L_{i_j}) \cap \pi_j(\Xi)| \geq |\pi_j(L_{i_j} \cap \Xi)|=|L_{i_j} \cap \Xi| \geq m, \quad 1 \leq j \leq n,
    \end{align*}
    and consequently $|\Xi|\geq \prod_{1\leq j\leq n} |Z_{d_j}|\geq m^n$.
\end{proof}

\begin{prop}\label{lem_rectangular A_3}
    The only faithful hypercubic representation $V$ of $A_3$ is $\mathrm{Std} \oplus \mathrm{Std}^{\vee}$.
\end{prop}

\begin{proof}
Let $\Xi\subset\R^3$ be the formal character of $V$ that is hypercubic of length $\ell\geq 2$.
    By Theorem~\ref{thm_WMF}, if $V$ is hypercubic, then each irreducible factor $W$ of $V$ is of multiplicity one and is equal to $\mathrm{Sym}^m(\mathrm{Std})$, or $\mathrm{Sym}^m(\mathrm{Std}^{\vee})$, or $\bigwedge^2(\mathrm{Std})$, or the trivial representation $\mathbb 1$. These irreducible representations can be classified as follows: Let $k$ be a non-negative integer.
    \begin{enumerate}
        \item $\mathrm{Sym}^{4k}(\mathrm{Std})$ and $\mathrm{Sym}^{4k}(\mathrm{Std}^{\vee})$ has weight $0$, 
				as $0=k(f_1+f_2+f_3+f_4)$.
        \item $\mathrm{Sym}^{4k+1}(\mathrm{Std})$ and $\mathrm{Sym}^{4k+3}(\mathrm{Std}^{\vee})$ has weight $w_1:=f_1$, as $f_1=f_1+k(f_1+f_2+f_3+f_4)=-f_2-f_3-f_4-k(f_1+f_2+f_3+f_4)$.
        \item $\mathrm{Sym}^{4k+2}(\mathrm{Std})$, $\mathrm{Sym}^{4k+2}(\mathrm{Std}^{\vee})$ and $\bigwedge^2(\mathrm{Std})$ has weight $w_2:=f_1+f_2$, as $f_1+f_2=f_1+f_2+k(f_1+f_2+f_3+f_4)=-f_3-f_4-k(f_1+f_2+f_3+f_4)$.
        \item $\mathrm{Sym}^{4k+3}(\mathrm{Std})$ and $\mathrm{Sym}^{4k+1}(\mathrm{Std}^{\vee})$ has weight $w_3:=f_1+f_2+f_3$, as $f_1+f_2+f_3=f_1+f_2+f_3+k(f_1+f_2+f_3+f_4)=-f_4-k(f_1+f_2+f_3+f_4)$.
    \end{enumerate}

		 Since $V$ is hypercubic, $w\in\Xi$ if and only if $-w\in \Xi$ and thus $V$ is self-dual.
		Hence, if $\mathrm{Sym}^{4k+2}(\mathrm{Std})$ (or $\mathrm{Sym}^{4k+2}(\mathrm{Std}^{\vee})$)
		is an irreducible factor of $V$ then the weight $w_2$ has multiplicity at least $2$ in $\Xi$
		which is absurd.
		Similarly, $\mathrm{Sym}^{4k}(\mathrm{Std})$ (or $\mathrm{Sym}^{4k}(\mathrm{Std}^{\vee})$) for $k>0$
		cannot be an irreducible factor of $V$.
		By the facts that $V$ is self-dual and weight multiplicity-free, and the above classification,
 $V$ is one of the following cases, where $m\in\N$ is congruent to $1$ or $3$ modulo $4$.
    \begin{enumerate}
		\item $V=\mathrm{Sym}^{m}(\mathrm{Std}) \oplus \mathrm{Sym}^{m}(\mathrm{Std}^{\vee}) \oplus \bigwedge^2(\mathrm{Std})\oplus \mathbb 1$.
        \item $V=\mathrm{Sym}^{m}(\mathrm{Std}) \oplus \mathrm{Sym}^{m}(\mathrm{Std}^{\vee})\oplus \bigwedge^2(\mathrm{Std})$.
        \item $V=\mathrm{Sym}^{m}(\mathrm{Std}) \oplus \mathrm{Sym}^{m}(\mathrm{Std}^{\vee})\oplus \mathbb 1$.
        \item $V=\mathrm{Sym}^{m}(\mathrm{Std}) \oplus \mathrm{Sym}^{m}(\mathrm{Std}^{\vee})$.
        \item $V=\bigwedge^2(\mathrm{Std})\oplus \mathbb 1$.
        \item $V=\bigwedge^2(\mathrm{Std})$.
    \end{enumerate}
    Among these types of representations, the last two representations  $\bigwedge^2(\mathrm{Std})\oplus \mathbb 1$ and $\bigwedge^2(\mathrm{Std})$ are $7$- and $6$-dimensional, respectively, and thus are not hypercubic.

    Suppose that $V=\mathrm{Sym}^{m}(\mathrm{Std}) \oplus \mathrm{Sym}^{m}(\mathrm{Std}^{\vee}) \oplus U$ 
		is one of the first four cases. Let $L_i\subset\R^3$ be the affine line containing
    \begin{align}\label{pts}
        \{mf_4,(m-1)f_4+f_i,\ldots,f_4+(m-1)f_i,mf_i\}.
    \end{align}
		These are some weights coming from $\mathrm{Sym}^{m}(\mathrm{Std})$
    for $i=1,2,3$. Since \eqref{pts} is a subset of $\Xi$, we obtain 
		\begin{equation}\label{estimate}
		|L_i\cap \Xi|\geq (m+1)\hspace{.1in} \text{for} \hspace{.1in}i=1,2,3.
		\end{equation}
		Suppose $\Xi=Z_{d_1}\times Z_{d_2} \times Z_{d_3}\subset\R^3$ up to a change of coordinates.
		Since the three lines $L_1,L_2,L_3$ all pass through $mf_4$ and are not coplanar in $\R^3$, 
		the condition \ref{lem_lattice line lemma}(b) is satisfied and 
		we obtain $|\Xi|\geq (m+1)^3$ by \eqref{estimate} and the lemma.
	Hence, we obtain
    \begin{align*}
		\begin{split}
        \dim V=2\binom{m+3}{3}+\dim U=\frac{1}{3}(m+1)(m+2)(m+3)+\dim U\geq (m+1)^3,
				\end{split}
    \end{align*}
		equivalent to
		$$\frac{(m+1)(2m+3)(m-1)}{3}\leq \dim U.$$
		As $\dim U\in\{0,1,6,7\}$ and $m\in\N$ is congruent $1$ or $3$ modulo $4$,
		the only solution is $m=1$ which 
		implies $\dim V\in\{8,9,14,15\}$.
		Since $V$ is a faithful hypercubic representation of $A_3$, the dimension is given by $\dim V=\ell^3$ for some positive integer $\ell \geq 2$
		and the only possibility is $8=2^3$. 
In this case, $V=\mathrm{Std} \oplus \mathrm{Std}^{\vee}$ and the  formal character is given by
		$$\Xi=\{\pm f_1,\pm f_2, \pm f_3, \pm f_4\}=\{(\pm 1/2,\pm 1/2,\pm 1/2)\} \subset \mathbb R^3,$$
    which is hypercubic.
\end{proof}

\subsubsection{}
As $D_3$ and $A_3$ are isomorphic, it remains to classify faithful hypercubic representations $V$ of 
   $B_n$ $(n \geq 2)$, $C_n$ $(n \geq 3)$, and $D_n$ $(n \geq 4)$.

 Firstly, consider $B_n$ for $n\geq 2$. 
		Since $V$ is weight multiplicity-free, it follows from Theorem~\ref{thm_WMF}
		that 
		$$V=\delta_1\mathbb 1  \oplus \delta_2 \mathrm{Std}  \oplus \delta_3\mathrm{Spin}$$ 
		for $\delta_1,\delta_2,\delta_3 \in \{0,1\}$. If $n>2$, then we have
    \begin{align*}
        \dim(V) \leq \dim(\mathbb 1)+\dim(\mathrm{Std})+\dim(\mathrm{Spin})=2+2n+2^n<3^n,
    \end{align*}
    so $\dim(V)=2^n$. Consequently, $V$ is either $\mathrm{Spin}$, or $n=3$ and $V=\mathrm{Std}\oplus \mathbb 1$. But the latter one is not hypercubic (and in fact not even weight multiplicity-free), so $V=\mathrm{Spin}$ is the unique hypercubic representation in this case. If $n=2$, then there is an exceptional hypercubic representation $\mathrm{Std}\oplus \mathrm{Spin}$ (see Example \ref{example}), and one can readily derive that this exceptional representation and the spin representation are the only hypercubic representations of $B_2$.



    Secondly, consider $C_n$ for $n\geq 3$. If $n>3$, then 
		$V$ is either $\mathrm{Std}$ or $\mathrm{Std}\oplus\mathbb 1$ by weight multiplicity-free of $V$ and
		Theorem~\ref{thm_WMF}. But both cases are not hypercubic.
When $n=3$, we obtain similarly that  
$$V=\delta_1\mathbb 1\oplus \delta_2\mathrm{Std} \oplus   \delta_3 U$$ 
for $\delta_1,\delta_2,\delta_3 \in \{0,1\}$, where $U=\bigwedge_{\mathrm{prim}}^3(\C^6)$ in Theorem \ref{thm_WMF}. 
As $\dim \mathbb 1 =1$, $\dim \mathrm{Std}=6$, and $\dim U=14$, it is impossible that $\dim V=\ell^3$ for any integer $\ell \geq 2$. Therefore, there is no hypercubic representations of $C_n$ for $n\geq 3$.


    Lastly, consider $D_n$ for $n \geq 4$. As above, one obtains $V=\delta_1\mathbb 1\oplus \delta_2\mathrm{Std}\oplus \delta_3\mathrm{Spin}^+\oplus \delta_4\mathrm{Spin}^-$ for $\delta_1,\delta_2,\delta_3,\delta_4 \in \{0,1\}$ and thus
    \begin{align*}
        \dim V \leq \dim(\mathbb 1)+\dim(\mathrm{Std})+\dim(\mathrm{Spin}^+)+\dim(\mathrm{Spin}^-)
				=1+2n+2^n<3^n.
    \end{align*}
  Therefore, we have $\dim(V)=2^n$ and consequently $V=\mathrm{Spin}$ is the unique hypercubic representation of $D_n$.

\subsection{Proofs of Theorem \ref{main1}(iv),(v)}\label{s2.9}
We handle the uniqueness assertions in Theorem \ref{main1}.
By the external tensor product \eqref{uni1},
the restriction $\psi|_{\Lieg_i}$ is the direct sum of some copies of $\psi_i$.
It follows from 
 the classification in Theorem \ref{main1}(iii)(a)--(d) that $\psi_i$ is determined by $\psi|_{\Lieg_i}$.
Therefore, we obtain Theorem \ref{main1}(iv).
For Theorem \ref{main1}(v), suppose 
\begin{equation}\label{uni3}
(\Lieg_1,\psi_1)=\bigotimes_{j'=1}^{s'} (\Lieg_{1,j'},\psi_{1,j'})
\end{equation}
is another external tensor product of indecomposable faithful hypercubic representations,
where $\Lieg_1=\prod_{j'=1}^{s'} \Lieg_{1,j'}$ is some decomposition.
We now compare \eqref{uni2} with \eqref{uni3}.

\begin{lemma}\label{coincide}
The two sets of factors 
$F_1=\{\Lieg_{1,j}:~ 1\leq j\leq s\}$
and $F_1'=\{\Lieg_{1,j'}:~ 1\leq j'\leq s'\}$ of $\Lieg_1$ coincide.
\end{lemma}

\begin{proof}
Let $V_1$ be the ambient space of $\psi_1$ and $W_{1,j}$ be the maximal subspace of $V_1$ such that $\Lieg_{1,j}$ acts trivially.
Here, $\Lieg_{1,j}$ is either $A_1$ or $A_1\times A_1$ by Theorem \ref{main1}(ii).

Suppose first $\Lieg_{1,j}=A_1$. 
By the tensor product decomposition \eqref{uni2} and Theorem \ref{main1}(ii)(a),(b), we obtain
$\dim W_{1,j}<(\dim V_1)/2.$
If $\Lieg_{1,j}$ is a factor of some $\Lieg_{1,j'}=A_1\times A_1$,
then $\dim W_{1,j}=(\dim V_1)/2$ by \eqref{uni3} and Theorem \ref{main1}(ii)(c), which is absurd.
Hence, the simple factors in $F_1$ and $F_1'$ coincide.

Next, we suppose $\Lieg_{1,j}=A_1\times A_1$. In this case, we have $\dim W_{1,j}=0$ by the tensor product decomposition \eqref{uni2} and Theorem \ref{main1}(ii)(c).
If $\Lieg_{1,j}\notin F_1'$, then there exist two distinct non-simple factors $\Lieg_{1,j'}$ and $\Lieg_{1,j''}$
in $F_1'$ that intersect $\Lieg_{1,j}$ non-trivially, since the simple factors in $F_1$ and $F_1'$ coincide.
This implies that
$\dim W_{1,j}\neq 0$ by \eqref{uni3} and Theorem \ref{main1}(ii)(c), which is absurd.
Therefore, we conclude that $F_1$ and $F_1'$ coincide.
\end{proof}

Lemma \ref{coincide} induces 
a bijective correspondence $j\leftrightarrow j'$ so that 
$\Lieg_{1,j}=\Lieg_{1,j'}$ in $\Lieg_1$. Then Theorem \ref{main1}(ii) implies that
$$\text{direct sum of some copies of }\psi_{1,j}=\psi_1|_{\Lieg_{1,j}}=\psi_1|_{\Lieg_{1,j'}}=\text{direct sum of some copies of }\psi_{1,j'}$$
and we obtain $\psi_{1,j}=\psi_{1,j'}$ from the classification in Theorem \ref{main1}(ii)(a)--(c).


\section{$\lambda$-independence of algebraic monodromy groups}

\subsection{Notation and terminologies}\label{s3.1}
We collect the notation and terminologies that will be used frequently.
\begin{itemize}
    \item $K$ (resp. $E$): a number field.
		\item $\Sigma_K$ (resp. $\Sigma_E$): the set of finite places of $K$ (resp. $E$).
    \item $v$ (resp. $\lambda$): an element of $\Sigma_K$ (resp. $\Sigma_E$).
    \item $p$ (resp. $\ell$): the residue characteristic of $v$ (resp. $\lambda$).
		\item $S_\ell$: the set of places in $\Sigma_K$ that divide the rational prime $\ell$.
		\item $\overline K$: an algebraic closure of $K$.
		\item $E_{\lambda}$ and $\F_\lambda$: the $\lambda$-adic completion of $E$ and the residue field of $E_\lambda$.
    \item $\overline E_{\lambda}$ (resp. $\overline \F_\lambda$): an algebraic closure of $E_{\lambda}$ (resp. $\F_\lambda$).
    \item $\Gal_K$: the absolute Galois group $\Gal(\overline K/K)$ equipped with the profinite topology.
    %\item $\mathrm{Frob}_v$: the Frobenius element at $v$ in $\Gal_K$,
		\item $\rho_\lambda:\Gal_K\to\GL_n(\overline E_\lambda)$: an \emph{$\lambda$-adic representation} of $K$, i.e., a continuous group homomorphism.
		\item $\bar\rho_\lambda^{\ss}:\Gal_K\to\GL_n(\overline \F_\lambda)$: the \emph{residue representation} of $\rho_\lambda$, i.e., 
		the semisimplification of the reduction modulo $\lambda$ of $\rho_\lambda$.
		\item $\bG_\lambda$ or $\bG_{\rho_\lambda}$: the \emph{algebraic monodromy group} of $\rho_\lambda$, i.e., the Zariski closure 
		of the Galois image $\rho_\lambda(\Gal_K)$ in $\GL_{n,\overline E_\lambda}$.
		\item $\iota_\lambda: \overline E_\lambda\to \C$: a field isomorphism for each $\lambda\in\Sigma_E$.
		\item $\bG_{\lambda,\C}$ (resp. $\bG_{\rho_\lambda,\C}$): the base change $\bG_\lambda\times_{\iota_\lambda}\C$ 
		(resp. $\bG_{\rho_\lambda}\times_{\iota_\lambda}\C$).
		\item $\bG^\circ$: the identity component of a linear algebraic group $\bG$.
		\item $\bG^{\der}$: the derived group $[\bG^\circ,\bG^\circ]$ of the identity component of $\bG$.
		\item $\epsilon_\ell$ (resp. $\bar\epsilon_\ell$): the $\ell$-adic (resp. mod $\ell$) cyclotomic character.
		\item A semisimple $\lambda$-adic representation $\sigma_\lambda$ is \emph{of type $A$} (resp. \emph{of type $A_1$}) 
if the semisimple part
$\mathrm{Lie}(\bG_{\sigma_\lambda,\C})^{\ss}$ has only type $A$ (resp. type $A_1$) factors.
This includes the case where the semisimple part is zero.
    \item $\mathbb{G}_m$ and $\mathbb{G}_a$: $\mathrm{Spec}(F[x,1/x])$ and $\mathrm{Spec}(F[x])$ for some field $F$.
    %\item $G^{\mathrm{der}}$: the derived subgroup of a reductive group $G$.
    %\item $\bG_{\rho}$: the algebraic monodromy group of a representation $\rho$.
    %\item $\bG_{\rho,F'}:=\bG_{\rho} \times_F F'$, where $\bG_{\rho}$ is the algebraic monodromy group of $\rho$ over a base field $F$ and $F'/F$ is a field extension.
\end{itemize}

\subsection{Compatible system of Galois representations}\label{s3.2}
We mainly follow \cite[$\mathsection5$]{BLGGT14} and \cite[$\mathsection1$]{PT15}.
%We introduce a notion of compatible system and some results which we will use. A continuous homomorphism
%\begin{align*}
  %  \rho_{\lambda}: \mathrm{Gal}_K \longrightarrow \mathrm{GL}_n(\overline E_{\lambda})
%\end{align*}
%is called a $\ell$-adic Galois representation of $K$ (we use the term `$\ell$-adic' instead of `$\lambda$-adic' due to the conventional reason).

\begin{defi}\label{csdef}
    A family of ($n$-dimensional) $\lambda$-adic Galois representations indexed by $\Sigma_E$,
    \begin{align*}
        \{\rho_{\lambda}: \Gal_K \longrightarrow \mathrm{GL}_n(\overline E_{\lambda})\}_{\lambda\in\Sigma_E},
    \end{align*}
    is called a  {\it compatible system of $K$ defined over $E$} (or \emph{$E$-rational compatible system}) 
		if there exist a finite set of places $S \subset \Sigma_K$ and a polynomial $\Phi_v(T)\in E[T]$ for each $v\in\Sigma_K\backslash S$ such that
		the following conditions hold.
    \begin{enumerate}
        \item[(a)] For each $\lambda\in\Sigma_E$, the representation $\rho_{\lambda}$ is unramified 
				at every $v\in \Sigma_K\backslash (S\cup S_\ell)$. 
        \item[(b)] For each $\lambda\in\Sigma_E$ and $v\in \Sigma_K\backslash (S\cup S_\ell)$,  
				the characteristic polynomial of $\rho_{\lambda}(\mathrm{Frob}_v)$ satisfies
        \begin{align*}\label{Frobpoly}
            \det(\rho_{\lambda}(\mathrm{Frob}_v)-T\cdot \mathrm{id})=\Phi_v(T) \in E[T].
        \end{align*}
    \end{enumerate}
		The compatible system $\{\rho_\lambda\}$ is said to be \emph{semisimple} if each $\rho_\lambda$ is semisimple.
\end{defi}


\begin{defi}\label{wcsdef}
    A semisimple $E$-rational compatible system $\{\rho_{\lambda} : \mathrm{Gal}_{K} \to \mathrm{GL}_n(\overline{E}_{\lambda})\}_{\lambda\in\Sigma_E}$ 
		is called a \emph{weakly compatible system} if the following conditions are satisfied.
    \begin{enumerate}
        \item[(a)] For each $\lambda\in\Sigma_E$ and $v\in S_\ell$, 
the local representation $\rho_{\lambda}|_{\Gal_{K_v}}$ is de Rham and is further crystalline if $v \not\in S$.
        \item[(b)] For each embedding $\tau: K\hookrightarrow \overline E$, there is a multiset of $n$ integers $\mathrm{HT}_\tau$
				such that $\mathrm{HT}_{i\circ\tau}(\rho_{\lambda})=\mathrm{HT}_{\tau}$ 
				for any $\lambda$ and any $i:\overline E\hookrightarrow \overline E_\lambda$ over $E$.
    \end{enumerate}
    A weakly compatible system is called a \emph{strictly compatible system} if an extra condition holds.
    \begin{enumerate}
        \item[(c)] For $\lambda\in\Sigma_E$ and $v\notin S_\ell$, 
				the semisimplified Weil-Deligne representation $\iota \mathrm{WD}(\rho_{\lambda}|_{\mathrm{Gal}_{K_v}})^{F-ss}$ is independent of $\lambda$
				and $\iota:\overline{E}_\lambda\stackrel{\cong}{\rightarrow} \C$.
    \end{enumerate}
\end{defi}


\begin{defi}\label{regdef}
    An $\lambda$-adic representation $\rho_{\lambda} : \mathrm{Gal}_{K} \to \mathrm{GL}_n(\overline{E}_{\lambda})$ is said to be \emph{regular} if it is unramified almost everywhere, $\rho_\lambda$ is de Rham at any $v$ above $\ell$,
and $\mathrm{HT}_\tau(\rho_\lambda)$ consists of $n$ distinct numbers for any embedding $\tau: K \hto \overline E_\lambda$.

		A weakly compatible system $\{\rho_{\lambda}: \mathrm{Gal}_K \to \mathrm{GL}_n(\overline E_{\lambda})\}_{\lambda}$ is said to be \emph{regular} if some (and hence all) $\rho_{\lambda}$ is regular. 
\end{defi}

If $K$ is totally real or CM field and $\pi$ is a regular algebraic, polarized, cuspidal automorphic representation of $\mathrm{GL}_n(\mathbb A_K)$, then one can attach a regular, $E$-rational, strictly compatible system $\{\rho_{\pi,\lambda}: \mathrm{Gal}_K \to \mathrm{GL}_n(\overline E_{\lambda})\}_{\lambda}$ for some $E$ (cf. \cite[$\mathsection~2.1$]{BLGGT14} and the references therein). We call the Galois representation $\rho_{\pi,\lambda}$
(resp. compatible system  $\{\rho_{\pi,\lambda}\}$) \emph{automorphic}.

\subsection{Potential automorphy of Galois representations}\label{s3.3}
Given an $\ell$-adic Galois representation $\rho_{\ell}:\mathrm{Gal}_K \to \mathrm{GL}_n(\overline{\mathbb Q}_{\ell})$, 
one can ask whether $\rho_\ell$ is automorphic (and thus part of a compatible system). 
We shall rely on the following potential automorphy results when $K$ is totally real.

\begin{thm}{\cite[Theorem C]{BLGGT14}}\label{thm_BLGGT14 Thm C}
    Let $K$ be a totally real field, $\ell \geq 2(n+1)$ be a rational prime, and
    \begin{align*}
        \rho_{\ell}:\mathrm{Gal}_K \to \mathrm{GL}_n(\overline{\mathbb Q}_{\ell})
    \end{align*}
    be an $\ell$-adic Galois representation of $K$. %We denote by $\overline{\rho}^{\ss}_\ell$ the semisimplification of the reduction of $\rho_\ell$. 
		Suppose the following conditions are satisfied.
    \begin{enumerate}[(1)]
        \item (Unramified almost everywhere) $\rho_{\ell}$ is unramified at all but finitely many primes.
        \item (Odd essential self-duality) Either $\rho_{\ell}$ maps to $\mathrm{GSp}_n$ with totally odd multiplier or it maps to $\mathrm{GO}_n$ with totally even multiplier.
        \item (Potential diagonalizability and regularity) $\rho_{\ell}$ is potentially diagonalizable (and hence potentially crystalline) at each prime $v$ of $K$ above $\ell$ and for each embedding $\tau : K \to \overline{\mathbb Q}_{\ell}$ it has $n$ distinct  $\tau$-Hodge-Tate numbers.
        \item (Irreducibility) $\overline{\rho}_{\ell}^{\mathrm{ss}}|_{\mathrm{Gal}_{K(\zeta_{\ell})}}$ is irreducible, where $\zeta_{\ell}:=e^{2\pi i/\ell}$ the primitive $\ell$th root of unity.
    \end{enumerate}
    Then we can find a finite Galois totally real extension $K'/K$ such that $\rho_{\ell}|_{\mathrm{Gal}_{K'}}$ is attached to a regular algebraic polarized cuspidal automorphic representation of $\mathrm{GL}_n(\mathbb A_{K'})$. Moreover, $\rho_{\ell}$ is part of a strictly compatible system of $K$.
\end{thm}

By combining Theorem \ref{thm_BLGGT14 Thm C} with some big image results (see $\mathsection\ref{s3.4}$),
we have the following potential automorphy result on certain regular three-dimensional subrepresentations 
in a ($\GL_n(E_\lambda)$-valued) strictly compatible system.

\begin{prop}{\cite[Proposition 2.12(b)]{Hui23b}}\label{prop_SO3 potential automorphy}
    Let $K$ be a totally real field and 
		$$\{\rho_{\lambda}:\mathrm{Gal}_{K} \to \mathrm{GL}_n(E_{\lambda})\}_{\lambda}$$ 
		be a $E$-rational strictly compatible system. 
		For almost all $\lambda\in\Sigma_E$, if $\sigma_{\lambda}$ is a regular three-dimensional subrepresentation of $\rho_{\lambda} \otimes \overline{E}_{\lambda}$ such that the derived subgroup $\bG_{\sigma_{\lambda}}^{\mathrm{der}}$ of its algebraic monodromy group is $\mathrm{SO}_3$ (as a group embedded in $\mathrm{GL_3}$), then there is a finite Galois totally real extension $K'/K$ such that $\sigma_{\lambda}|_{\mathrm{Gal}_{K'}}$ is attached to a regular algebraic polarized cuspidal automorphic representation of $\mathrm{GL}_3(\mathbb A_{K'})$. Moreover, such $\sigma_{\lambda}$ is a part of a strictly compatible system of $K$.
\end{prop}

\subsection{Big image results of Galois subrepresentations}\label{s3.4}
We present some big image results 
for type $A$ Galois subrepresentations in 
certain ($\GL_n(E_\lambda)$-valued) semisimple compatible system.

\begin{thm}\cite[Theorem 1.2, Theorem 3.12(v)]{Hui23a}\label{big}
Let  $\{\rho_\lambda:\Gal_K\to\GL_n(E_\lambda)\}$
be a semisimple compatible system of a number field $K$. 
Suppose there exist some integers $N_1,N_2\geq 0$ and finite extension $K'/K$ such that the following conditions hold. 
\begin{enumerate}[(a)]
\item (Bounded tame inertia weights): for almost all $\lambda$ 
and each finite place $v$ of $K$ above $\ell$, 
the tame inertia weights of the local representation 
$(\bar\rho_{\lambda}^{\ss}\otimes\bar\epsilon_\ell^{N_1})|_{\Gal_{K_v}}$ belong to $[0,N_2]$.
\item (Potential semistability): for almost all $\lambda$ and each finite place $w$ of $K'$ not above $\ell$,
the semisimplification of the local representation $\bar\rho_{\lambda}^{\ss}|_{\Gal_{K_{w}'}}$ is unramified.
\end{enumerate}
For almost all $\lambda\in\Sigma_E$, the following assertions hold.
\begin{enumerate}[(i)]
\item  If $\sigma_\lambda$ is a type $A$ irreducible subrepresentation
of $\rho_\lambda\otimes\overline E_\lambda$, then the residual representation $\bar\sigma_\lambda^{\ss}$ is also irreducible.
\item If $\sigma_\lambda$ is a type $A$ Lie-irreducible subrepresentation
of $\rho_\lambda\otimes\overline E_\lambda$, then the restriction $\bar\sigma_\lambda^{\ss}|_{\Gal_{K^{ab}}}$ is also irreducible,
where $K^{ab}$ is the maximal abelian extension of $K$.
\end{enumerate}
\end{thm}

\begin{prop}\cite[Proposition 2.11]{Hui23b}\label{cond}
Let $\{\rho_\lambda:\Gal_K\to\GL_n(E_\lambda)\}$ be a $E$-rational 
strictly compatible system of a number field $K$.
Then $\{\rho_\lambda\}$ satisfies the conditions \ref{big}(a),(b) 
for some integers $N_1,N_2\geq 0$ and finite extension $K'/K$.
\end{prop}

\subsection{$\lambda$-independence of formal bi-character}\label{s3.5}
Let $F$ be an algebraically closed field of characteristic zero and $\bG\subset\GL_{n,F}$
a reductive subgroup. Denote by $\bT$ a maximal torus of $\bG$. 
Then  the intersection $\bT^{\ss}:=\bG^{\der}\cap \bT$ is a maximal torus of the semisimple group $\bG^{\der}$.
The following definition is independent of the choice of the maximal torus $\bT$.

\begin{defi}\label{formchar}
Let $\bG\subset\GL_{n,F}$ be a reductive subgroup.
    \begin{enumerate}[(1)]
\item The \emph{formal character} of $\bG$ is defined as the conjugacy class of the torus $\bT$ 
in $\mathrm{GL}_{n, F}$.
\item The \emph{formal bi-character} of $\bG$ is defined as the conjugacy class of 
the chain of subtori $\bT^{\ss}\subset\bT$ in $\mathrm{GL}_{n, F}$.
    \end{enumerate}
\end{defi}

Suppose that $\bG_1$ and $\bG_2$ are reductive subgroups of respectively 
$\mathrm{GL}_{n,F_1}$ and $\mathrm{GL}_{n,F_2}$, where $F_1$ and $F_2$ are algebraically closed fields of characteristic zero.
Embed $F_1$ and $F_2$ into an algebraically closed field $F$.
We say that the formal characters (resp. formal bi-characters) of $\bG_1$ and $\bG_2$ are \emph{the same}
if this is true for the base change $\bG_{1,F}$ and $\bG_{2,F}$ in $\GL_{n,F}$.
This definition is independent of the choice of the over-field $F$.

