%\end{theorem}

\begin{remark}\label{remconn}
For a compatible system $\{\rho_\lambda\}$ with algebraic monodromy groups $\{\bG_\lambda\}$,
the semisimplification $\{\rho_\lambda^{\ss}\}$ is a semisimple compatible system with algebraic monodromy groups $\{\bG_\lambda/\bU_\lambda\}$,
where $\bU_\lambda$ is the unipotent radical of $\bG_\lambda$. Since $\bU_\lambda$ is always connected,
it follows that $\bG_\lambda/\bG_\lambda^\circ$ is independent of $\lambda$ by Theorem \ref{thm_formal bi-char indep}(i).
\end{remark}


A compatible system $\{\rho_\lambda\}$ 
is said to be \emph{connected} if the algebraic monodromy group $\bG_\lambda$ is connected for some $\lambda$, equivalently, 
for all $\lambda$ by Remark \ref{remconn}. For any compatible system $\{\rho_\lambda\}$ (of $K$), there exists
a finite extension $L/K$ such that the restriction $\{\rho_\lambda|_{\Gal_L}\}$ is connected.

\subsection{A refinement of Theorem \ref{thm_formal bi-char indep}(ii),(iii)}\label{s3.6}
In this subsection, we refine Theorem \ref{thm_formal bi-char indep}(ii),(iii) 
by utilizing the method in \cite[$\mathsection3$]{Hui13}.
Suppose that for each $1\leq i \leq k$, $\{\rho_\lambda^{(i)}:\Gal_K\to\GL_{n_i}(\overline E_\lambda)\}$ 
is a semisimple $E$-rational compatible system of $K$.
Consider the semisimple $E$-rational compatible system
\begin{equation}\label{bigcs}
\{\hat\rho_\lambda:=\bigoplus_{i=1}^k \rho_\lambda^{(i)}:\Gal_K\to \prod_{i=1}^k \GL_{n_i}(\overline E_\lambda)\}
\end{equation}
given by direct sum and let 
$$\{\hat\bG_\lambda\subset \prod_{i=1}^k \GL_{n_i,\overline E_\lambda}\}$$
be the system of algebraic monodromy groups. For all $\lambda\in\Sigma_E$, let
$$\hat\bT_\lambda^{\ss}\subset\hat\bT_\lambda$$ 
be a chain of subtori in $\prod_{i=1}^k \GL_{n_i,\overline E_\lambda}$ 
where $\hat\bT_\lambda$ is a maximal torus of $\hat\bG_\lambda$
and $\hat\bT_\lambda^{\ss}$ is a maximal torus of $\hat\bG_\lambda^{\der}$.

\begin{thm}\label{refine} 
After the base change $\iota_\lambda:\overline E_\lambda\stackrel{\simeq}{\rightarrow}\C$ for all $\lambda\in\Sigma_E$,
\begin{enumerate}[(i)]
\item the conjugacy class of subtorus $\hat\bT_{\lambda,\C}$ in $\prod_{i=1}^k \GL_{n_i,\C}$ is independent of $\lambda$;
\item the conjugacy class of the chain $\hat\bT_{\lambda,\C}^{\ss}\subset\hat\bT_{\lambda,\C}$ in 
$\prod_{i=1}^k \GL_{n_i,\C}$ is independent of $\lambda$.
\end{enumerate}
\end{thm}

\begin{proof}
We may assume that \eqref{bigcs} is connected by taking a finite extension of $K$
and the chain $\hat\bT_{\lambda,\C}^{\ss}\subset\hat\bT_{\lambda,\C}$
is contained in the diagonal $\prod_{i=1}^k \mathbb{G}_m^{n_i}$ of $\prod_{i=1}^k \GL_{n_i,\C}$
by conjugation.

(i). The idea (as in \cite{Ser81}) is to look at the morphism 
$$\mathrm{Char}:=\prod_{i=1}^k \mathrm{Char}^{(i)}: \prod_{i=1}^k \GL_{n_i,\C}\to \prod_{i=1}^k (\mathbb{G}_a^{n_i-1}\times\mathbb{G}_m)$$
where $\mathrm{Char}^{(i)}(A)=(a_1,...,a_{n_i})$ if $A\in \GL_{n_i}(\C)$ 
and $\det(A-T\cdot \mathrm{id})=\sum_{j=0}^{n_i} a_j T^{n_i-j}$.
By the compatibility conditions \ref{csdef}(a),(b) and Chebotarev's density theorem, 
$\mathrm{Char}(\hat\bG_{\lambda,\C})$ is independent of $\lambda$.
Since $\hat\bT_{\lambda,\C}$ is a maximal torus of the connected $\hat\bG_{\lambda,\C}$,
it follows that $\mathrm{Char}(\hat\bT_{\lambda,\C})=\mathrm{Char}(\hat\bG_{\lambda,\C})$
is independent of $\lambda$. Together with the facts that 
$\hat\bT_{\lambda,\C}\subset \prod_{i=1}^k \mathbb{G}_m^{n_i}$ (the diagonal) 
is a closed irreducible subvariety
and the restriction $\mathrm{Char}|_{\prod_{i=1}^k \mathbb{G}_m^{n_i}}$ is a finite morphism,
we obtain assertion (i).

(ii). This part follows closely the idea behind \cite[Theorem 3.19]{Hui13}. 
Let $\mathfrak{m}$ be a modulus of $K$ and $S_\mathfrak{m}$ be the 
Serre group\footnote{The Serre group $S_\mathfrak{m}$ is a diagonalizable group defined over $\Q$ and its dimension depends
only on $K$, i.e., independent of $\mathfrak m$.} of $K$ with respect $\mathfrak{m}$. 
Associated to $S_\mathfrak{m}$ a family of abelian $\ell$-adic representations
$$\{\alpha_\ell:\Gal_K\to S_\mathfrak{m}(\Q_\ell)\}_{\ell\in\Sigma_\Q}$$
such that for any $E$-morphism $\phi:S_{\mathfrak{m},E}\to \GL_{m,E}$, the composition 
$$\{\phi_\lambda: \Gal_K\stackrel{\alpha_\ell}{\rightarrow}S_\mathfrak{m}(E_\lambda)
\stackrel{\phi\otimes_E E_\lambda}{\longrightarrow}\GL_m(E_\lambda)\subset\GL_m(\overline E_\lambda)\}_{\lambda\in\Sigma_E}$$
is an abelian semisimple $E$-rational compatible system \cite[Chapter II]{Ser98}.

Assume $\phi$ is now faithful. 
Consider the semisimple compatible system $\{\hat\rho_\lambda\oplus\phi_\lambda\}$ (a direct 
sum of $k+1$ compatible systems) and let 
$$\{\widetilde\bG_\lambda\subset (\prod_{i=1}^k \GL_{n_i,\overline E_\lambda})\times\GL_{m,\overline E_\lambda}\}$$
be the system of algebraic monodromy groups. 
For all $\lambda$, let $\widetilde\bT_\lambda$ 
be a subtori in $(\prod_{i=1}^k \GL_{n_i,\overline E_\lambda})\times\GL_{m,\overline E_\lambda}$ 
such that $\widetilde\bT_\lambda$ is a maximal torus of $\widetilde\bG_\lambda$.
It follows from assertion (i) that 
\begin{equation}\label{words}
\text{the conjugacy class of $\widetilde\bT_{\lambda,\C}$
in $(\prod_{i=1}^k \GL_{n_i,\C})\times\GL_{m,\C}$ is independent of $\lambda$}.
\end{equation}
Let $\pi_1$ (resp. $\pi_2$) be the projection map of $(\prod_{i=1}^k \GL_{n_i,\C})\times\GL_{m,\C}$
to the first $k$ factors (resp. to the last factor).
According to \cite[Remark 3.22]{Hui13} and the proof of \cite[Theorem 3.19]{Hui13}, the chain
\begin{equation}\label{refinechain}
\mathrm{Ker}(\pi_2|_{\widetilde\bT_{\lambda,\C}})^\circ\subset \pi_1(\widetilde\bT_{\lambda,\C})
\end{equation}
is the formal bi-character of $\pi_1(\widetilde\bG_{\lambda,\C})=\hat\bG_{\lambda,\C}$ for all $\lambda$.
By \eqref{words}, the conjugacy class of \eqref{refinechain} in $\prod_{i=1}^k \GL_{n_i,\C}$
is independent of $\lambda$.
\end{proof}

Suppose $k=2$ in \eqref{bigcs} and denote by $\pi_1:\GL_{n_1,\overline E_\lambda}\times\GL_{n_2,\overline E_\lambda}\to \GL_{n_1,\overline E_\lambda}$
the projection to the first factor.

\begin{cor}\label{oneiso}
If $\pi_1:\hat\bG_{\lambda_0}\to \pi_1(\hat\bG_{\lambda_0})$ is an isomorphism for some $\lambda_0$, then the surjection
\begin{equation}\label{proj1}
\pi_1:\hat\bG_{\lambda}\to \pi_1(\hat\bG_{\lambda})
\end{equation}
 is an isomorphism for all $\lambda$.
\end{cor}

\begin{proof}
First, note that $\pi_1(\hat\bG_{\lambda})$ is the algebraic monodromy group of $\rho_\lambda^{(1)}$ for all $\lambda$.
Then the condition that \eqref{proj1} is an isomorphism at $\lambda_0$ and 
Theorem \ref{thm_formal bi-char indep}(i),(ii) imply that the ranks (resp. numbers of components) of $\hat\bG_{\lambda}$ 
and $\pi_1(\hat\bG_{\lambda})$ are equal for each $\lambda$.
Thus, the kernel $\bC_\lambda$ of the surjection \eqref{proj1} is a finite normal subgroup of $\hat\bG_{\lambda}^\circ$ for each $\lambda$.
We obtain that $\bC_\lambda\subset \hat\bT_{\lambda}$ (a maximal torus of $\hat\bG_{\lambda}$) for each $\lambda$.
Since the restriction of \eqref{proj1} to $\hat\bT_{\lambda}$ is injective at $\lambda=\lambda_0$, 
this is also true for all $\lambda$ by Theorem \ref{refine}(i).
Therefore,  $\bC_\lambda$ is trivial for all $\lambda$.
\end{proof}

\subsection{Invariance of roots and $\lambda$-independence}\label{s3.7}
Suppose $\{\rho_\lambda:\Gal_K\to\GL_n(\overline E_\lambda)\}$ is 
a connected semisimple $E$-rational compatible system with algebraic monodromy groups $\{\bG_\lambda\}$. 
After the base change $\iota_\lambda:\overline E_\lambda\stackrel{\simeq}{\rightarrow}\C$
for all $\lambda\in\Sigma_E$, we obtain a system of complex connected
reductive subgroups 
$$\{\bG_{\lambda,\C}\subset\GL_{n,\C}\}.$$
Up to $\GL_{n,\C}$-conjugation, there exists a chain of subtori
\begin{equation}\label{commonchain}
\bT_\C^{\ss}\subset\bT_\C
\end{equation}
in $\GL_{n,\C}$ such that $\bT_\C$ is a maximal torus of $\bG_{\lambda,\C}$ for all $\lambda$
and $\bT_\C^{\ss}$ is a maximal torus of $\bG_{\lambda,\C}^{\der}$ for all $\lambda$
by Theorem \ref{thm_formal bi-char indep}(iii). 
We give a crucial criterion, called the \emph{invariance of roots}, 
for the connected reductive subgroups $\{\bG_{\lambda,\C}\}$ to be conjugate in $\GL_{n,\C}$.
Denote by $\X(\bT_\C^{\ss}):=\mathrm{Hom}(\bT_\C^{\ss},\mathbb{G}_m)$ the character group of $\bT_\C^{\ss}$.




\begin{prop}\label{invroot}\cite[Corollary 3.9]{Hui18}
For two primes $\lambda_1$ and $\lambda_2\in \Sigma_E$,
let $\Phi_1\subset \X(\bT_\C^{\ss})$ and $\Phi_2\subset \X(\bT_\C^{\ss})$ be the root systems
of the semisimple groups $\bG_{\lambda_1,\C}^{\der}$ and $\bG_{\lambda_2,\C}^{\der}$
with respect to the common maximal torus $\bT_\C^{\ss}$ in \eqref{commonchain}.
If $\Phi_1=\Phi_2$, then $\bG_{\lambda_1,\C}$ and $\bG_{\lambda_2,\C}$
are conjugate in $\GL_{n,\C}$. 
\end{prop}

The main strategy for Theorem \ref{thm_main2}
is to construct some auxiliary compatible system $\{\phi_\lambda\}$
so that the invariance of roots criterion is fulfilled.

\begin{prop}\label{strategy}
Let $\{\rho_\lambda:\Gal_K\to\GL_n(\overline E_\lambda)\}$ be
a connected semisimple $E$-rational compatible system with algebraic monodromy groups $\{\bG_\lambda\subset\GL_{n,\overline E_\lambda}\}$. 
Let $\{\phi_\lambda:\Gal_K\to\GL_m(\overline E_\lambda)\}$ be a semisimple $E$-rational compatible system 
and consider the compatible system $\{\rho_\lambda\oplus\phi_\lambda\}$ with 
algebraic monodromy groups $\{\hat\bG_\lambda\subset\GL_{n,\overline E_\lambda}\times \GL_{m,\overline E_\lambda}\}$.
Let $\pi_1$ (resp. $\pi_2$) be the projection map of $\GL_{n,\overline E_\lambda}\times \GL_{m,\overline E_\lambda}$
to the first (resp. second) factor.
Suppose the following conditions hold.
\begin{enumerate}[(a)]
\item For all $\lambda$ (equivalently, for some $\lambda$), the first projection $\pi_1: \hat\bG_\lambda\to \bG_\lambda$ is an isomorphism.
\item For all $\lambda$, the composition $\bG_\lambda\stackrel{\pi_1^{-1}}{\longrightarrow}\hat\bG_\lambda\stackrel{\pi_2}{\rightarrow}\GL_{m,\overline E_\lambda}$ is the adjoint representation on the semisimple part $\mathrm{Lie}(\bG_\lambda^{\der})$,
where $\pi_1^{-1}$ means the inverse of the isomorphism in (a).
\end{enumerate}
After the base change $\overline E_\lambda\simeq \C$, 
the conjugacy class of $\bG_{\lambda,\C}$ in $\GL_{n,\C}$ is independent of $\lambda$.
\end{prop}

\begin{proof}
In the condition (a), Corollary \ref{oneiso} implies that the assertion
``$\pi_1: \hat\bG_\lambda\to \bG_\lambda$ is an isomorphism'' is independent of $\lambda$.

Up to $\GL_{n,\C}\times \GL_{m,\C}$-conjugation, there exists a chain of subtori
$$\hat\bT_{\C}^{\ss}\subset\hat\bT_{\C}$$
in $\GL_{n,\C}\times \GL_{m,\C}$ such that $\hat\bT_{\C}$ (resp. $\hat\bT_{\C}^{\ss}$)
is a maximal torus of $\hat\bG_{\lambda,\C}$ (resp. $\hat\bG_{\lambda,\C}^{\der}$) for all $\lambda$ by Theorem \ref{refine}(ii). 
Then we may take the chain \eqref{commonchain} as
$$\pi_1(\hat\bT_{\C}^{\ss})\subset\pi_1(\hat\bT_{\C}).$$
By (b), the root system of $\bG_{\lambda,\C}^{\der}$ with respect to $\pi_1(\hat\bT_{\C}^{\ss})$
is given by the weights of
$$\pi_1(\hat\bT_{\C}^{\ss})\stackrel{\pi_1^{-1}}{\longrightarrow} \hat\bT_{\C}^{\ss}\stackrel{\pi_2}{\longrightarrow}\GL_{m,\C},$$
which is independent of $\lambda$. Therefore, the conjugacy class of $\bG_{\lambda,\C}$ in $\GL_{n,\C}$ is independent of $\lambda$ 
by Proposition \ref{invroot}.
\end{proof}


\subsection{Hodge-Tate lift}\label{s3.8}
Let $F$ be a finite field extension of $\Q_\ell$ and $\bH$ a linear algebraic group defined over 
$\overline{\mathbb Q}_{\ell}$ in this subsection. 
An $\ell$-adic representation $\rho: \mathrm{Gal}_{F} \to \bH(\overline{\mathbb Q}_{\ell})$ is said to be \emph{Hodge-Tate} 
if for any representation $\bH \to \mathrm{GL}_{k,\overline{\mathbb Q}_{\ell}}$, the composition
$$\mathrm{Gal}_{F} \stackrel{\rho}{\rightarrow} \bH(\overline{\mathbb Q}_{\ell}) \to \mathrm{GL}_k(\overline{\mathbb Q}_{\ell})$$ 
is a Hodge-Tate representation.

\begin{prop}{\cite[Corollary 3.2.12]{Pat19}}\label{prop_Hodge-Tate lift}
    Let $\bH' \rightarrow \bH$ be a surjection of $\overline\Q_\ell$-linear algebraic groups with the central torus kernel 
		and $\rho: \mathrm{Gal}_{F} \to \bH(\overline{\mathbb Q}_{\ell})$ be a Hodge-Tate representation of $F$. Then there exists a Hodge-Tate lift $\tilde{\rho}:\mathrm{Gal}_{F} \to \bH'(\overline{\mathbb Q}_{\ell})$ so that the following diagram commutes.
    \begin{equation*}\label{liftdiagram}
		\begin{tikzcd}
	& {\bH'(\overline{\mathbb Q}_{\ell})} \\
	{\mathrm{Gal}_{F}} & {\bH(\overline{\mathbb Q}_{\ell})}
	\arrow[two heads, from=1-2, to=2-2]
	\arrow["{\tilde{\rho}}", dashed, from=2-1, to=1-2]
	\arrow["\rho"', from=2-1, to=2-2]
\end{tikzcd}
\end{equation*}
\end{prop}

