\subsection{Proof of Theorem~\ref{thm_main2}}\label{s3.9}
\subsubsection{}
Now $K$ is totally real. Since $\rho_\lambda$ is $\GL_n(E_\lambda)$-valued,
the algebraic monodromy group $\bG_\lambda$ is defined over $E_\lambda$. 
To prove Theorem ~\ref{thm_main2}, it suffices (by Proposition \ref{strategy}) 
to construct some compatible system $\{\phi_\lambda\}$ (see \eqref{aux}) so that the conditions \ref{strategy}(a),(b) hold (enlarging $E$ if necessary).
This will be achieved by the potential automorphy result, Proposition \ref{prop_SO3 potential automorphy}.

Let $r\in\N$ be the rank of $\bG_\lambda^{\der}$ (independent of $\lambda$ by Theorem \ref{thm_formal bi-char indep}(iii)).
The conditions \ref{thm_main2}(c),(d) and Corollary \ref{cor_L at most 2 at most 3}(i)
imply that the semisimple Lie algebra $\mathrm{Lie}(\bG_{\lambda,\overline E_\lambda}^{\der})$ is 
of type $A_1$ for all $\lambda$. 
Since the $3r$-dimensional $\mathrm{Lie}(\bG_\lambda^{\der})$ is  
acted on by $\bG_\lambda$ (via adjoint action) and also by $\Gal_K$, we obtain a semisimple $\lambda$-adic representation
\begin{equation*}\label{adjoint}
\psi_\lambda:\Gal_K\to\GL_{3r}(E_\lambda)
\end{equation*}
such that $\psi_\lambda\otimes \overline E_\lambda$ is the direct sum of 
$r$ representations $\psi_{\lambda,i}:\Gal_K\to\GL_3(\overline E_\lambda)$ for $1\leq i\leq r$,
where each $\psi_{\lambda,i}$ corresponds to a simple ($A_1$-) factor of $\mathrm{Lie}(\bG_{\lambda,\overline E_\lambda}^{\der})$.
Since $\bG_\lambda$ is connected by the condition \ref{thm_main2}(b), the algebraic monodromy group $\bG_{\psi_{\lambda,i}}$
 (resp. $\bG_{\psi_\lambda\otimes\overline E_\lambda}$)
is isomorphic to $\SO_{3}$ (resp. $\SO_{3}^r$) for all $i$.



\begin{prop}\label{propregular}
For each $1\leq i\leq r$, the three dimensional representation $\psi_{\lambda,i}$ is regular.
\end{prop}

\begin{proof}
Since $\{\rho_\lambda\}$
is strictly compatible by the condition \ref{thm_main2}(a), the system $\{\rho_\lambda\otimes\rho_\lambda^\vee\}$
is also strictly compatible. 
As $\psi_\lambda$ is a subrepresentation of $\rho_\lambda\otimes\rho_\lambda^\vee$,
it is de Rham at places $v$ above $\ell$.
It remains to show that $\psi_{\lambda,i}|_{\Gal_{K_v}}$ has distinct
$\tau$-Hodge-Tate numbers for any embedding $\tau: K_v\to \overline E_\lambda$ (see Definition \ref{regdef}).

Take $F:=K_v$ and $\overline E_\lambda\simeq \overline \Q_\ell$ a field isomorphism.
For each non-abelian irreducible subrepresentation $\rho_0$ of $\rho_\lambda\otimes\overline E_\lambda$,
the restriction 
\begin{equation}\label{restrictF}
\rho_0:\Gal_F\to\GL_k(\overline \Q_\ell)
\end{equation}
has distinct $\tau$-Hodge-Tate numbers 
by the condition \ref{thm_main2}(a). Moreover, \eqref{restrictF} 
satisfies the conditions \ref{prop_GL2r lift}(a)--(d) with $\bH:=\bG_{\rho_0}\mathbb{G}_m$, where $\mathbb{G}_m$
denotes the homothety of $\GL_{k,\overline\Q_\ell}$. Hence, we obtain $f_1,...,f_{r_0}$ by Proposition \ref{prop_GL2r lift},
where $r_0\in\N$ is the semisimple rank of $\bG_{\rho_0}$.

Since $\psi_{\lambda,i}$ is a simple $A_1$-factor of $\psi_\lambda\otimes\overline\Q_\ell=\mathrm{Lie}(\bG_{\lambda,\overline\Q_\ell}^{\der})$, 
there exists an irreducible $\rho_0$ (as above) such that $\psi_{\lambda,i}$ is injective via the natural $\Gal_F$-equivariant morphism
$$\mathrm{Lie}(\bG_{\lambda,\overline\Q_\ell}^{\der})\to\mathrm{Lie}(\bG_{\rho_0}^{\der})=\mathrm{Lie}(\bH^{\der})\simeq \mathrm{Lie}(\bH'^{\der}),$$
where the first arrow comes from $\rho_0$-projection and the last isomorphism holds because the kernel of $\bH'\twoheadrightarrow\bH$ 
is a central torus by Proposition \ref{prop_GL2r lift}. Hence, we find some $f_j:\Gal_F\to\GL_2(\overline\Q_\ell)$ 
such that the restriction
\begin{equation}\label{ad0}
\psi_{\lambda,i}|_{\Gal_{F}}\simeq \mathrm{ad}^0(f_j)
\end{equation}
as $\Gal_F$-representations, where $\mathrm{ad}^0(f_j)$ denotes
the trace zero part of $f_j\otimes f_j^\vee=\End(f_j)$.
Since the $\tau$-Hodge-Tate numbers of $f_j$ are distinct by Proposition \ref{prop_GL2r lift},
the same holds for $\psi_{\lambda,i}|_{\Gal_{F}}$ by \eqref{ad0}.
\end{proof}

\subsubsection{}
Now $\psi_{\lambda,i}$ is regular and $\bG_{\psi_{\lambda,i}}=\SO_3\subset\GL_3$ for all $\lambda\in\Sigma_E$ and $1\leq i\leq r$.
Then Proposition \ref{prop_SO3 potential automorphy} 
(on the $E$-rational strictly compatible system $\{\rho_\lambda\otimes\rho_\lambda^\vee\}$) 
implies the existence of a prime $\lambda_0\in\Sigma_E$ such that $\psi_{\lambda_0,i}$ 
is potentially automorphic and is part of a semisimple $E$-rational strictly compatible system 
$\{\phi_{i,\lambda}\}$ for all $1\leq i\leq r$ (by enlarging $E$ if necessary).
Therefore,  we obtain a $3r$-dimensional semisimple $E$-rational compatible system
\begin{equation}\label{aux}
\{\phi_\lambda:=\bigoplus_{i=1}^r \phi_{i,\lambda}:\Gal_K\to \prod_{i=1}^r \GL_3(\overline E_\lambda)\}_{\lambda\in\Sigma_E}
\end{equation}
of the totally real $K$ such that $\phi_{\lambda_0}=\psi_{\lambda_0}$. 

\begin{prop}\label{auxgp}
For all $\lambda$, the algebraic monodromy group $\bG_{\phi_{\lambda}}$ of $\phi_\lambda$ is $\SO_3^r\subset \GL_3^r$.
\end{prop}

\begin{proof}
Note that the assertion holds at $\lambda_0$. In particular,
the algebraic monodromy group of $\phi_{i,\lambda_0}$ satisfies
\begin{equation}\label{so3}
\bG_{\phi_{i,\lambda_0}}=\SO_3\subset\GL_3
\end{equation} 
for every $i$.
As Proposition \ref{prop_SO3 potential automorphy} asserts that 
the restriction 
$\{\phi_{i,\lambda}|_{\Gal_{K_i}}\}$ is automorphic for 
some totally real extension $K_i/K$, 
the algebraic monodromy group of $\phi_{i,\lambda}|_{\Gal_{K_i}}$
is independent of $\lambda$ (see \cite[Proposition 4.16(iii)]{Hui23a}),
which must be $\SO_3\subset\GL_3$ by \eqref{so3}. By \eqref{so3} again and Theorem \ref{thm_formal bi-char indep},
we obtain
\begin{equation*}\label{so3'}
\bG_{\phi_{i,\lambda}}=\SO_3\subset\GL_3
\end{equation*} 
for all $\lambda$ and $i$, which implies that 
\begin{equation}\label{so3''}
\bG_{\phi_{\lambda}}\subset \SO_3^r
\end{equation} 
in $\GL_3^r$ for all $\lambda$. Since \eqref{so3''} is an equality at $\lambda_0$,
it follows from Theorem \ref{thm_formal bi-char indep} that \eqref{so3''} is an equality for all $\lambda$.
We are done.
\end{proof}

\subsubsection{}
With $\{\phi_\lambda\}$ at hand, we are in the setting of Proposition \ref{strategy}.
To complete the proof of Theorem \ref{thm_main2}, 
it remains to verify the conditions \ref{strategy}(a),(b).
The algebraic monodromy group $\hat\bG_\lambda$ of $\rho_\lambda\oplus\phi_\lambda$ 
is contained in the product $\bG_\lambda\times\bG_{\phi_\lambda}\subset\GL_n\times \GL_{3r}$. 
Let $\pi_1$ and $\pi_2$ be respectively, the projection to the first and second factor.
Since $\phi_{\lambda_0}$ is given by the adjoint action on $\mathrm{Lie}(\bG_{\lambda_0}^{\der})$, the
condition \ref{strategy}(a) holds (at $\lambda=\lambda_0$). 
%Hence, the ranks (resp. semisimple ranks) of $\bG_\lambda$ and $\hat\bG_\lambda$ are equal for all $\lambda$ by Theorem \ref{thm_formal bi-char indep}. It follows that the kernel 
%\begin{equation}\label{kernelpi1}
%\mathrm{Ker}(\pi_1:\hat\bG_\lambda\to\bG_\lambda)
%\end{equation}
%is finite and normal in $\hat\bG_\lambda$. Since $\pi_2:\hat\bG_\lambda\to\bG_{\phi_\lambda} $ is surjective, \eqref{kernelpi1} is a finite normal subgroup of $\{1\}\times \bG_{\phi_\lambda}$. Since $\bG_{\phi_\lambda}=\SO_3^r$ (Proposition \ref{auxgp}) is an adjoint group, \eqref{kernelpi1} must be trivial and thus thecondition \ref{strategy}(a) holds for all $\lambda$.
Since the image of 
\begin{equation}\label{compo}
\bG_\lambda\stackrel{\pi_1^{-1}}{\longrightarrow}\hat\bG_\lambda\stackrel{\pi_2}{\rightarrow}\GL_{3r,\overline E_\lambda}
\end{equation}
is $\SO_3^r\subset\GL_3^r$ (Proposition \ref{auxgp}) and $r$ is the semisimple rank of $\bG_\lambda$, \eqref{compo} can only be 
the adjoint representation on the semisimple part $\mathrm{Lie}(\bG_{\lambda}^{\der})$, i.e., 
the condition \ref{strategy}(b) holds for all $\lambda$.

