The paper is organized as follows.  In Section \ref{sec: Preliminary}, we show some properties on the operator $L$. In particular, we show that the function $|x-x_0|^{\beta}$ (where $\beta\leq \alpha$) is a strict subsolution to \eqref{fractional infinity Lap}; this will be fundamental in our later analysis. In section \ref{sec:viscosity}, we introduce the notion of viscosity (sub/super) solution to \eqref{Frac Inf Lap Eq} and show in Proposition \ref{comparison principle} the comparison principle. Moreover, we will prove a stability result on subsolutions. We also develop a Perron's Method argument in Section \ref{sec:Perron}
%, and prove regularity results of viscosity subsolutions, 
and prove the following existence and regularity results. 
\begin{theorem}\label{thm:Main 1}
    Assume $f:\mathbb{R} \mapsto \mathbb{R}$ is continuous and monotone and the boundary datum $g$ is $\beta-$H\"older for some \,$0<\beta<\alpha$. Then, the following fractional infinity Laplacian problem:
$$\begin{cases} L[u]=f(u) &\qquad in \,\,\,\,\,\Omega\\ u=g &\qquad on\,\,\,\,\, \partial \Omega\end{cases},$$
    has a solution $u$. Moreover, $u \in C^{0,\beta}(\overline{\Omega})$.
\end{theorem}
We note that the solution constructed in the proof of Theorem \ref{thm:Main 1} is non-negative when both $f$ and $g$ are non-negative; this will allow us to introduce the obstacle problem in Section \ref{sec:obstacle} and show the following second main result of the paper.
\begin{theorem}\label{Th1.2}
    Assume $f$ is nonnegative, continuous and monotone on $[0,\infty)$ and \,$g \in C^{0,\beta}(\partial\Omega)$ non negative with \,$0<\beta<\alpha$. Then, there exists a nonnegative $\beta-$H\"older solution $u$ to the following obstacle fractional infinity Laplacian problem:
$$\begin{cases} L[u]=f(u) &\qquad in \,\,\,\,\,\{u>0\}\\ u=g &\qquad on\,\,\,\,\, \partial \Omega\end{cases}.$$
 %   has a solution $u$. Moreover, $u \in C^{0,\beta}(\overline{\Omega})$.
\end{theorem}
The main idea of the proof of Theorem \ref{Th1.2} is to approximate the function $f$ with a sequence of non-decreasing continuous functions and use the result of Section \ref{sec:viscosity} to obtain a sequence of solutions to \eqref{Frac Inf Lap Eq} converging to a solution for the obstacle problem \ref{Frac Inf Lap Eq Obstacle} with boundary data $g$.


\section{Preliminaries}\label{sec: Preliminary}
 In this section, we introduce some properties of the fractional infinity Laplacian operator $L$ that we will use later in our paper. First of all, we
define the following intermediary operators
$$L^+[u]=\sup_{y\in \overline{\Omega},\,y\neq x}  \dfrac{u(y)-u(x)}{|y-x|^{\alpha}}\qquad\qquad \mbox{and}\qquad\qquad L^-[u]=\inf_{y\in \overline{ \Omega},\,y\neq x} \dfrac{u(y)-u(x)}{|y-x|^{\alpha}}.$$\\
Recalling the definition of the operator $L$, we clearly have $L[u]=L^+[u]+L^-[u]$.

We start by the following simple lemma that we use frequently in the sequel (we give the proof just for the sake of completeness).
\begin{lemma}\label{metric} Fix $\alpha\in (0,1)$. Then, for all $x,\,y\in \mathbb R^n$, we have the $\alpha-$triangle inequality: 
$$|x+y|^{\alpha}\leq |x|^{\alpha}+|y|^{\alpha}.$$ 
In addition, the equality holds if and only if we either have $x=0$ or $y=0$.
\end{lemma}

\begin{proof}
Let $a,\,b>0$. For any $r\geq 0$, we define the function  $h(r)=(r+b)^\alpha-r^\alpha-b^\alpha.$ 
Notice that 
    $$h'(r)=\alpha\left[(r+b)^{\alpha-1}-r^{\alpha-1}\right]<0.$$
Hence, we infer that $h$ is strictly decreasing on $[0,\infty)$ and so, one has the following inequality:
\begin{equation} \label{ineQuality}
h(a)=(a+b)^{\alpha}-a^\alpha-b^{\alpha}<h(0)=0.
\end{equation}
%Deducing hence that for $a,\,b>0$, we have the inequality:
%$$(a+b)^{\alpha}<a^{\alpha}+b^{\alpha}.$$
For $x,\,y\in \mathbb R^n$ non zero, we get from \eqref{ineQuality} with $a=|x|$, $b=|y|$ and using the classical triangle inequality, that
$$|x+y|^{\alpha}\leq (|x|+|y|)^{\alpha}<|x|^{\alpha}+|y|^{\alpha}.$$
Finally, we note that equality follows immediately when $x=0$ or $y=0$. $\qedhere$
%$${\color{red}{h(a)=(a+b)^\alpha-a^\alpha-b^\alpha\leq h(0)=0.}}$$

%Assume we have equality for some $a>0$ and $b> 0$, then $h(a)=0=h(0)$ which implies that 
\end{proof}

Fix $x_0\in \overline{\Omega}$. Then, we define the barrier function $\psi_{\beta,x_0}(x)=|x-x_0|^\beta$. First, we calculate $L[\psi_{\beta,x_0}]$ when $0<\beta<\alpha$. We note that $\psi_{\beta,x_0}$ will be used later in Section \ref{sec:Perron} to construct sub/supersolutions as well as to show $\beta-$H\"older regularity on solutions.

\begin{proposition}\label{prop:alpha>beta}
Assume $0<\beta<\alpha\leq 1$, $x_0\in \overline{\Omega}$ and $\psi_{\beta,x_0}(x)=|x-x_0|^{\beta}$. Then, for every $x\in \Omega\setminus\{x_0\}$, we have
\begin{equation}\label{equ:estimate beta<alpha}
L [\psi_{\beta,x_0}](x)\leq |x-x_0|^{\beta-\alpha}\left(\dfrac{r_{\star}^{\beta}-1}{(r_{\star}-1)^\alpha}-1\right)<0,\end{equation}
where $r_{\ast}>\dfrac{1-\beta}{\alpha-\beta}$ is the unique solution in $(1,\infty)$ to the following equation:
$$(\alpha-\beta)\,r^{\beta}+\beta\, r^{\beta-1}-\alpha=0.$$
%In particular, $L[\psi_{x_0}](x)<0$ for every $x\in \Omega\setminus \{x_0\}$.
\end{proposition}
\begin{proof}
First, it is clear that
\begin{equation} \label{est on L-}
L^-[\psi_{\beta,x_0}](x)\leq \dfrac{\psi_{\beta,x_0}(x_0)-\psi_{\beta,x_0}(x)}{|x_0-x|^{\alpha}}=-|x-x_0|^{\beta-\alpha}.
\end{equation}
On the other hand,
%\begin{align*} 
 \begin{align*} L^+[\psi_{\beta,x_0}](x) 
  %=\sup_{y\in \overline{\Omega},\,y\neq x}\dfrac{\psi_{x_0}(y)-\psi_{x_0}(x)}{|y-x|^{\alpha}}
  &=\sup_{y\in \overline{\Omega},\, y\neq x}\dfrac{|y-x_0|^{\beta}-|x-x_0|^{\beta}}{|y-x|^{\alpha}}=\sup_{y\in \overline{\Omega},\,|y-x_0|> |x-x_0|}\dfrac{|y-x_0|^{\beta}-|x-x_0|^{\beta}}{|y-x|^{\alpha}}\\
  &\leq \sup_{y\in \overline{\Omega},\, |y-x_0|> |x-x_0|}\dfrac{|y-x_0|^{\beta}-|x-x_0|^{\beta}}{(|y-x_0|-|x-x_0|)^{\alpha}}= |x-x_0|^{\beta-\alpha}\sup_{y\in \overline{\Omega},\, |y-x_0|> |x-x_0|}\dfrac{\left(\dfrac{|y-x_0|}{|x-x_0|}\right)^{\beta}-1}{\left(\dfrac{|y-x_0|}{|x-x_0|}-1\right)^{\alpha}}.
  \end{align*}
  Hence
\begin{equation} \label{est on L+}
  L^+[\psi_{\beta,x_0}](x)\leq |x-x_0|^{\beta-\alpha}\sup_{1<r<\frac{\diam(\Omega)}{|x-x_0|}} \Psi(r),
  \end{equation}
%\leq |x-x_0|^{\beta-\alpha}\sup_{r>1}\Psi(r).$$
%\end{align*}
where 
$\Psi(r):=\dfrac{r^{\beta}-1}{(r-1)^{\alpha}}$. We note that $\lim_{r\to 1^+} \Psi(r)=\begin{cases} 0 \quad & \,\,\mbox{if}\,\,\,\alpha<1\\ \beta & \,\,\mbox{if}\,\,\, \alpha=1\end{cases}$ and $\lim_{r\to \infty}\Psi(r)=0$. Moreover, one has
$$\Psi'(r)=\dfrac{\beta r^{\beta-1}(r-1)^{\alpha}-\alpha(r-1)^{\alpha-1}(r^{\beta}-1)}{(r-1)^{2\alpha}}=\dfrac{\beta r^{\beta-1}(r-1)-\alpha (r^{\beta}-1)}{(r-1)^{\alpha+1}}=\dfrac{(\beta-\alpha)r^{\beta}-\beta r^{\beta-1}+\alpha}{(r-1)^{\alpha+1}}.$$
Now, set \,$p(r)=(\beta-\alpha)r^{\beta}-\beta r^{\beta-1}+\alpha.$ 
Notice that $p(1)=0$,\, $\lim_{r\to \infty} p(r)=-\infty$, and we have
$$p'(r)=\beta(\beta-\alpha)r^{\beta-1}-\beta(\beta-1)r^{\beta-2}=\beta r^{\beta-2}[(\beta-\alpha)r-(\beta-1)].$$
Let $r_0=\dfrac{1-\beta}{\alpha-\beta}$ be the unique root of $p^\prime(r)=0$. From above we deduce that $p$ has a unique root $r_\star >r_0$ such that $$\sup_{r>1}\Psi(r)=\Psi(r_{\star}).$$
Combining the estimates \eqref{est on L-} on $L^-$ and \eqref{est on L+} on $L^+$ , we conclude \eqref{equ:estimate beta<alpha}. But, from Lemma \ref{metric}, we have
$$r_\star^\beta< (r_{\star}-1)^{\beta}+1\leq (r_{\star}-1)^{\alpha}+1.$$
Hence, 
%for $\beta<\alpha$ and $x\in \overline{\Omega}$,
we have \,$L[\psi_{\beta,x_0}](x)<0$. $\qedhere$
\end{proof}

We now give an estimate on $L [\psi_{\beta,x_0}]$ but in the case when $\beta=\alpha$. This will be used in Section \ref{sec:obstacle} to show $\alpha-$H\"older regularity on solutions to the obstacle problem \eqref{Frac Inf Lap Eq Obstacle}.
