$$L[\psi_{\alpha.x_0}](x) \leq -1+\dfrac{ \left(\dfrac{\diam(\Omega)}{|x-x_0|}\right)^\alpha-1}{\left(\dfrac{\diam (\Omega)}{|x-x_0|}-1\right)^{\alpha}}<0,\qquad \mbox{for all}\,\,\,x \neq x_0.$$
\end{proposition}
\begin{proof}
