Let $u$ be a viscosity solution on   $\Omega$. Since $L$ is a non-local operator, then it is not clear whether or not $u$ will be always a solution on a subset of $\Omega$. In the following proposition, we will show that this is true provided we remove only one point. 


\begin{proposition} \label{subsolution on domain minus point}
Fix \,$x_0 \in \Omega$. Assume that \,$u$\, is a subsolution of $L[u]=f(u)$ on \,$\Omega$, then \,$u$\, is also a subsolution on \,$\Omega\setminus\{x_0\}$.
\end{proposition}

\begin{proof}
Let $\varphi\in C^1(\Omega\setminus \{x_0\})\cap C(\overline \Omega)$ such that $u\leq \varphi$ on $\overline{\Omega}$ with equality at some $x_1\in \Omega\setminus \{x_0\}$.
From Lemma \ref{lem:delta perturbation}, for $\delta>0$ $\varphi_{\delta}(x)=\varphi(x)+\delta |x-x_1|^2\in C^1(\Omega\setminus \{x_0\})\cap C(\overline \Omega)$ such that $u< \varphi_{\delta}$ for every $x\in \overline{\Omega}\setminus \{x_1\}$ with equality at $x_1$, and
$L[\varphi_{\delta}](x_1)\to L[\varphi](x_1)$ as $\delta\to 0$.

Fix $\delta>0$. We have $x_0\neq x_1$, let $\varepsilon_0>0$ be such that $\overline{B(x_0,\varepsilon_0)}\subseteq \Omega$ and not containing $x_1$. We construct a sequence $\varphi_n\in C^1(\Omega)$ converging uniformly to $\varphi_{\delta}$ in $\overline{B(x_0,\varepsilon_0)}$ and such that $\varphi_n= \varphi_{\delta}$ on $\Omega\setminus B(x_0,\varepsilon_0)$. We have $u<\varphi_{\delta}$ in $\overline{B(x_0,\varepsilon_0)}$ then for $n$ sufficiently large $u<\varphi_n$ in $\overline{B(x_0,\varepsilon_0)}$ and so $u<\varphi_n$ in $\overline{\Omega}\setminus\{x_1\}$ with equality at $x_1$. Since $u$ is a subsolution on $\Omega$, then
$$-L[\varphi_n](x_1)+f(\varphi_n(x_1))\leq 0.$$
But, we have that outside $\overline{B(x_0,\varepsilon_0)}$, $\varphi_n=\varphi_{\delta}$ and so, $\varphi_n(x_1)=\varphi_\delta(x_1)=\varphi(x_1)$. Therefore, one has
$$\sup_{y\in \overline{\Omega}\setminus \overline{B(x_0,\varepsilon_0)},\,y\neq x_1} \dfrac{\varphi_n(y)-\varphi_n(x_1)}{|y-x_1|^{\alpha}}=\sup_{y\in \overline{\Omega}\setminus \overline{B(x_0,\varepsilon_0)},\,y\neq x_1} \dfrac{\varphi_{\delta}(y)-\varphi_{\delta}(x_1)}{|y-x_1|^{\alpha}}.$$ 
Now, by uniform convergence of $\varphi_n$ and since $x_1 \notin \overline{B(x_0,\varepsilon_0)}$, then we have the following:
$$\lim_{n\to \infty} \sup_{y\in \overline{B(x_0,\varepsilon_0)}} \dfrac{\varphi_n(y)-\varphi_n(x_1)}{|y-x_1|^{\alpha}}= \sup_{y\in \overline{B(x_0,\varepsilon_0)}} \dfrac{\varphi_{\delta}(y)-\varphi_{\delta}(x_1)}{|y-x_1|^{\alpha}},$$
and similarly for the infimum.
Hence, we get that $\lim_{n\to \infty} L[\varphi_n](x_1)=L[\varphi_{\delta}](x_1),$
and so 
$$-L[\varphi_\delta](x_1)+f(\varphi_\delta(x_1)) \leq 0.$$
But, $\delta>0$ is arbitrary and $\varphi_\delta(x_1)=\varphi(x_1)$ so letting $\delta\to 0^+$, we infer that $-L[\varphi](x_1)+f(\varphi(x_1))\leq 0$, concluding that $u$ is a subsolution on $\Omega\setminus \{x_0\}$. $\qedhere$
\end{proof}

We next show a comparison principle when $f$ is non-decreasing which will help later in proving our H\"older estimates. 
\begin{proposition} \label{comparison principle}
Assume that $f$ is non-decreasing.
    Let $u$ be a subsolution (resp. supersolution) of $L[u]=f(u)$ and $v$ be a strict supersolution (resp. subsolution) such that $u \leq v$\, (resp. $u \geq v$) on \,$\partial \Omega$\, and \,$v \in C^1(\Omega) \cap C(\overline{\Omega})$. Then, $u < v$\, (resp. $u>v$) in $\Omega$.  
\end{proposition}
\begin{proof}
    Assume this is not the case, i.e. there is a point $x^\star \in \Omega$ such that $u(x^\star)- v(x^\star)=\max\limits_{x \in \Omega} [u(x)-v(x)]:=M\geq 0$. Note that the maximum is attained since $u$ is upper semicontinuous and $v$ is continuous on $\overline \Omega$. We clearly have $u \leq v + M$\, on \,$\overline{\Omega}$ with $u(x^\star)=v(x^\star)+M$. Since $u$ is a subsolution and $v \in C^1(\Omega) \cap C(\overline{\Omega})$, then we must have 
    $$-L[v+M](x^\star) +f(v(x^\star)+M) \leq 0.$$
    Yet, \,$f$\, is non-decreasing. Hence, we get that
     $$-L[v](x^\star) +f(v(x^\star)) \leq 0.$$
     But, this contradicts the fact that $v$ is a strict supersolution which concludes the proof.
\end{proof}
