\subsection{Perron's Method}\label{sec:Perron} The aim of this subsection is to construct a viscosity solution to \eqref{Frac Inf Lap Eq} by applying the Perron's method. First, we start by constructing a sub/supersolution.
%in such a way that $u^- \leq u^+$ on $\Omega$ with $u^-=u^+=g$ on $\partial\Omega$.   
%applying the Perron’s method
\begin{lemma} \label{Existence of subsupersolutions}
Assume $f$ is non-decreasing and continuous, and $g \in C^{0,\beta}(\partial\Omega)$ for some $\beta>0$. Then, there exist a subsolution $u^-$ and a supersolution $u^+$ to \eqref{Frac Inf Lap Eq} such that $u^- \leq u^+$ on \,$\overline{\Omega}$\, and \,$u^-=u^+=g$\, on \,$\partial\Omega$.
   % The space of subsolution and supersolutions to \eqref{system} is not empty.
\end{lemma}

\begin{proof}
Assume without loss of generality that $\beta<\alpha$. We define
$$u^-(x)=\sup\{g(x_0)-C\, \psi_{\beta,x_0}(x),\,x_0 \in \partial\Omega\},\qquad \mbox{for all}\,\,\,x \in \overline{\Omega},$$
where we recall that $\psi_{\beta,x_0}(x)=|x-x_0|^\beta$ and the constant $C>0$ is to be chosen sufficiently large. For every $x_0 \in \partial\Omega$, thanks to the monotonicity of $f$, we see that
$$-L[g(x_0)-C\, \psi_{\beta,x_0}](x)+f(g(x_0)-C\, \psi_{\beta,x_0}(x))\leq C \,L[\psi_{\beta,x_0}](x)+f(||g||_\infty).$$
%Assume without loss of generality that $\beta<\alpha.$
Recalling Proposition \ref{prop:alpha>beta}, we have 
$$
L [\psi_{\beta,x_0}](x)\leq |x-x_0|^{\beta-\alpha}\left(\dfrac{r_{\star}^{\beta}-1}{(r_{\star}-1)^\alpha}-1\right) \leq \diam(\Omega)^{\beta-\alpha}\left(\dfrac{r_{\star}^{\beta}-1}{(r_{\star}-1)^\alpha}-1\right).$$
Hence,
$$-L[g(x_0)-C\, \psi_{\beta,x_0}]+f(g(x_0)-C\, \psi_{\beta,x_0})\leq C \,\diam(\Omega)^{\beta-\alpha}\left(\dfrac{r_{\star}^{\beta}-1}{(r_{\star}-1)^\alpha}-1\right)+f(||g||_\infty) \leq 0$$
as soon as
$$C\geq \frac{\mbox{diam}(\Omega)^{\alpha-\beta}\,f(||g||_\infty)}{\bigg[1-\dfrac{r_{\star}^{\beta}-1}{(r_{\star}-1)^\alpha}\bigg]}.$$
Moreover, it is clear that $u^- \in C^{0,\beta}({\Omega})$. Thanks to Proposition \ref{stability}, this yields that $u^-$ is a subsolution. On the other hand, it is clear that 
$$u^-(x_0) \geq g(x_0)-C\, \psi_{\beta,x_0}(x_0) = g(x_0),\qquad\mbox{for all}\,\,\,x_0 \in \partial\Omega.$$
Thanks to the $\beta-$H\"older regularity of $g$ on $\partial\Omega$, we have the following estimate for $C\geq [g]_{\alpha,\partial \Omega}$
$$g(x_0)-C\, \psi_{\beta,x_0}(x) \leq g(x),\qquad\mbox{for all}\,\,\,x_0 \in \partial\Omega.$$
Hence,
$$u^-(x) \leq g(x),\qquad \mbox{for all}\,\,\,x \in \partial\Omega.$$
Consequently, $u^-=g$\, on \,$\partial\Omega$. 

Now, we define 
$$u^+(x)=\min\{g(x_0)+C\, \psi_{\beta,x_0}(x),\,x_0 \in \partial\Omega\}\qquad \mbox{for all}\,\,\,x \in \overline{\Omega}.$$
%Clearly, $u^+ \geq 0$\, on \,$\overline{\Omega}$. 
%Moreover, o
One has
$$-L[g(x_0)+C\, \psi_{\beta,x_0}]+f(g(x_0)+C\, \psi_{\beta,x_0})\geq -C \,L[\psi_{\beta,x_0}] +f(-||g||_\infty) \geq 0$$
provided that $C$ is large enough.
%$$C \geq \frac{-f(-||g||_\infty)\,[\mbox{diam}(\Omega)]^{\alpha-\beta}}{1-\Psi(r_\star)}.$$
Hence, thanks to Remark \ref{rmk:stability super}, $u^+ \in C^{0,\beta}({\Omega})$ is a viscosity supersolution. In addition, $u^+=g$\, on \,$\partial\Omega$. 

Finally, let us check that $u^- \leq u^+$\, on \,$\overline{\Omega}$. For \,$x_0,\,x_1\in \partial\Omega$, we have from Lemma \ref{metric} that
$$g(x_0) -g(x_1) \leq C |x_1-x_0|^\beta \leq C(|x-x_0|^\beta +|x-x_1|^\beta),\qquad \mbox{for every}\,\,\,x \in \overline{\Omega}.$$
%as soon as {\color{red}{$C \geq [g]_{\alpha,\partial\Omega}$}}.
Fix $x \in \overline{\Omega}$. Hence, one has
$$g(x_0)-C\, \psi_{\beta,x_0}(x) \leq g(x_1)+C\, \psi_{\beta,x_1}(x),\qquad \mbox{for every}\,\,\,\,x_1 \in \partial\Omega.$$
Thus, 
$$g(x_0)-C\, \psi_{\beta,x_0}(x) \leq \min\{g(x_1)+C\, \psi_{\beta,x_1}(x),\,\,x_1 \in \partial\Omega\}=u^+(x),\qquad\mbox{for every}\,\,\,x_0 \in \partial\Omega.$$
Consequently, we get that 
$$u^-(x)=\sup\{g(x_0)-C\, \psi_{\beta,x_0}(x),\,\,x_0 \in \partial\Omega\} \leq u^+(x) \qquad \mbox{on}\,\,\,\overline{\Omega}. $$
Yet, this concludes the proof. $\qedhere$
%Without loss of generality, we may assyme that $0\in \partial \Omega$. Now, let $c$ be a large constant that will be chosen later. Set $u^+(x)=|x|^{\beta} +c$. From \cite[Lemma 8.1]{Chambole} and the definition of $L$, one has $Lu^+\leq 0\leq f(u)$. Assume $c \geq ||g||_\infty$, so we have $u^+(x) \geq g(x)$ for every $x\in \partial \Omega$. 
%This is possible since $g\geq 0$. 
%Hence $u^+$ is a supersolution to \eqref{system}.
