We are now ready to prove Theorem \ref{thm:Main 1}. We first show the regularity of subsolutions and then prove the existence result.
\begin{proposition} \label{beta Holder regularity}
%Fix \,$\beta <\alpha$.
Assume $f$ is non-decreasing.  If $u$ is a bounded continuous viscosity subsolution of \eqref{Frac Inf Lap Eq}, then
% Any viscosity solution $u$ of \eqref{system} 
$u$ is locally $\beta-$H\"olderian, for any $\beta <\alpha$. More precisely, we have
  $$[u]_{C^{0,\beta}(\omega)} \leq \max\bigg\{\frac{2||u||_\infty}{\dist(\omega,\partial\Omega)^\beta},\frac{[\mbox{diam}(\Omega)]^{\alpha-\beta}\,[f(-||u||_\infty)]_-}{1-\Psi(r_\star)}\bigg\},\qquad\mbox{for every}\,\,\,w \subset\subset \Omega,$$
 where using the notation of Proposition \ref{prop:alpha>beta}
  $$\Psi(r_\star)=\dfrac{r_\star^{\beta}-1}{(r_\star-1)^{\alpha}}<1.$$
  In addition, assume that $g \in C^{0,\beta}(\partial\Omega)$, if $u$ is a continuous viscosity solution of \eqref{Frac Inf Lap Eq} with $u=g$ on $\partial\Omega$, 
then $u$ is $\beta-$H\"olderian in $\overline{\Omega}$, and we have the following estimate:
     $$||u||_{C^{0,\beta}(\overline\Omega)} \leq C\bigg(\alpha,\,\beta,\,\mbox{diam}(\Omega),\,||g||_{C^{0,\beta}(\partial\Omega)},\,[ f(\pm||g||_\infty)]_\pm,\,[f(-||u||_\infty)]_-\bigg).$$
     \end{proposition}
  \begin{proof}
%Without loss of generality, assume that \,$u$\, is a viscosity solution.
Fix $x_0 \in \omega \subset\subset \Omega$. Thanks to Proposition \ref{subsolution on domain minus point}, $u$ is a viscosity subsolution of \eqref{Frac Inf Lap Eq} on $\Omega\backslash\{x_0\}$. Now, we define 
    $$v(x)=u(x_0)+C|x-x_0|^\beta.$$
    Recalling Proposition \ref{prop:alpha>beta}, $v$ is a strict supersolution on $\Omega\backslash\{x_0\}$ since 
    $$-L[u(x_0)+C|x-x_0|^\beta]+f(u(x_0)+C|x-x_0|^\beta) \geq -C L[|x-x_0|^\beta] + f(-||u||_\infty)>0$$
as soon as $C\geq \frac{[\mbox{diam}(\Omega)]^{\alpha-\beta}\,[f(-||u||_\infty)]_-}{1-\Psi(r_\star)}$.
    %where the first inequality comes from the fact that $f \geq 0$ on $\mathbb{R}$. 
    Moreover, one has $v(x_0)=u(x_0)$, and for every $x\in \partial \Omega$, we have
    $$u(x) -v(x)=u(x)-u(x_0)-C|x-x_0|^\beta \leq 2||u||_\infty -C \,\dist(\omega,\partial\Omega)^\beta \leq 0 $$
    as soon as we choose the constant $C \geq 2||u||_\infty/\dist(\omega,\partial\Omega)^\beta$. Thanks to the comparison principle in Proposition \ref{comparison principle}, we infer that $u <v$ in $\Omega\backslash\{x_0\}$ and so, we have
    $$u(x) \leq u(x_0)+C|x-x_0|^\beta\qquad\mbox{for all}\,\,\,\,x \in \omega.$$
    Interchanging the role of $x_0$ and $x$, we get that
    $$|u(x)-u(x_0)| \leq C|x-x_0|^\beta.$$
    This shows that $u \in C^{0,\beta} (\omega)$.

Now, let us show the second statement. Assume $g \in C^{0,\beta}(\partial\Omega)$. Fix $x_0 \in \partial\Omega$. Then, we set the function 
    $$w^+(x)=g(x_0)+C\,|x-x_0|^\beta,$$
    where $C \geq [g]_{\beta,\partial\Omega}$.
    Since $g \in C^{0,\beta}(\partial\Omega)$ and $u=g$ on $\partial\Omega$, then we have for every $x \in \partial\Omega$ the following inequality:
    $$u(x)=g(x)\leq g(x_0)+C\,|x-x_0|^\beta=w^+(x).$$
    Moreover, one can show that $w^+$ is a strict supersolution provided that $C$ is large enough. Indeed,
\begin{align*}
-L[w^+]+f(w^+)&=-C\,L[\psi_{\beta,x_0}]+f(g(x_0)+C\,|x-x_0|^\beta)\geq C |x-x_0|^{\beta-\alpha}[1-\Psi(r_\star)] +f(-||g||_\infty) > 0
    \end{align*}
    provided that $$C\geq  \frac{\diam(\Omega)^{\alpha-\beta}\,[f(-||g||_\infty)]_-}{1-\Psi(r_\star)}.$$
    Thanks again to the comparison principle in Proposition \ref{comparison principle}, we get that \,$u <w^+$\, in $\Omega$. Therefore, one has
    $$u(x) \leq g(x_0)+C\,|x-x_0|^\beta,\qquad\mbox{for all}\,\,\,x \in \overline{\Omega}.$$
    In the same way, we set  $$w^-(x)=g(x_0)-C\,|x-x_0|^\beta,$$
    where $C>0$ is a large constant that we will choose later. We claim that $w^-$ is a strict subsolution. In fact, we have the following:
    $$ -L[w^-]+f(w^-)=C\,L[\psi_{\beta,x_0}]+f(g(x_0)-C\,|x-x_0|^\beta)
    \leq C |x-x_0|^{\beta-\alpha}[\Psi(r_\star) -1] + f(||g||_\infty) < 0$$
    provided that $$C\geq  \frac{\diam(\Omega)^{\alpha-\beta}\,[f(||g||_\infty)]_+}{1-\Psi(r_\star)}.$$
    \\
    On the other hand, assuming that the constant $C \geq [g]_{\beta,\partial\Omega}$ then we get thanks to the H\"older regularity of $g$ that 
     $$u(x)=g(x) \geq w^-(x)=g(x_0)-C\,|x-x_0|^\beta,\qquad\mbox{for all}\,\,\,x \in \partial{\Omega}.$$
     Hence,
     $$u(x) \geq w^-(x),\qquad\mbox{for all}\,\,\,x \in \overline{\Omega}.$$
     Consequently,
     $$w^-(x) \leq u(x) \leq w^+(x),\qquad\mbox{for all}\,\,\,x \in \overline{\Omega}.$$
     Yet, $u(x_0)=g(x_0)$. Then, 
      $$|u(x)-u(x_0)| \leq C\,|x-x_0|^\beta,\qquad\mbox{for all}\,\,\,x \in \overline{\Omega}. $$
    \end{proof}
%Assume that $g \in C^{0,\beta}(\partial\Omega)$ with $0<\beta <\alpha$. 
%If $u$ is a viscosity solution of \eqref{system} with $u=g$ on $\partial\Omega$, t
%Then, $u$ is $\beta-$H\"olderian and, we have the following estimate:
 %    $$||u||_{C^{0,\beta}(\Omega)} \leq C\bigg( ||g||_{C^{0,\beta}(\partial\Omega)},\frac{ \,\,[\mbox{diam}(\Omega)]^{\alpha-\beta}}{1-\Psi(r_\star)}\,f(||g||_\infty)\bigg).$$
  %   \\
  %  Finally, if \,$g \in C^{0,\alpha}(\partial\Omega)$\, then \,$u$\, is \,$\alpha-$H\"olderian at any point \,$x_0 \in \partial\Omega$\, where \,$g(x_0)=0$.
%     where $M=\max\{f(||g||_\infty),f(-||g||_\infty)\}$
Now, we are ready to prove our existence result.
\begin{theorem} \label{existence of a solution}
Under the assumptions that $f$ is non-decreasing, continuous and $g \in C^{0,\beta}(\partial\Omega)$ for some $\beta>0$, there exists a viscosity solution $u$ to
    Problem \eqref{Frac Inf Lap Eq}.
    %Moreover, $u \in C^{0,\beta}(\Omega)$ and we have the following estimate:
    %$$||u||_{C^{0,\beta}(\Omega)} \leq ||g||_{C^{0,\beta}(\partial\Omega)} +\frac{\,\,[\mbox{diam}(\Omega)]^{\alpha-\beta}}{1-\Psi(r_\star)}\,f(||g||_\infty).$$
\end{theorem}
\begin{proof}
Without loss of generality, we assume that $\beta<\alpha$. Set 
$$S=\bigg\{w \in C(\overline{\Omega}) \,\,\,\mbox{is a subsolution}\,:\,\,u^- \leq w \leq u^+\,\,\,\mbox{on}\,\,\,\overline{\Omega}\bigg\}.$$
First, we note that \,$S \neq \emptyset$\, since the subsolution $u^-$ constructed in Lemma \ref{Existence of subsupersolutions} belongs to $S$. Then, we define the function 
$$u=\sup_{w \in S} w.$$
%Thanks to Proposition 
%{\color{blue} We need limsup here, to make it upper semicontinuous.}
%\ref{Holder regularity} and since
For any $w \in S$, we clearly have  $$||w||_\infty \leq \max\{||u^+||_\infty,||u^-||_\infty\}:=\Lambda.$$
Then, by Proposition \ref{beta Holder regularity}, one has
 $$[w]_{C^{0,\beta}(\omega)} \leq \max\bigg\{\frac{2\Lambda}{\dist(\omega,\partial\Omega)^\beta},\frac{[\mbox{diam}(\Omega)]^{\alpha-\beta}\,[f(-\Lambda)]_-}{1-\Psi(r_\star)}\bigg\},\qquad\mbox{for every}\,\,\,w \subset\subset \Omega.$$\\
Hence, we infer that $u$ is locally $\beta-$H\"older. In particular, $u$ is continuous in $\Omega$. From Proposition \ref{stability}, this implies that $u$ is a subsolution of \eqref{Frac Inf Lap Eq} with $u=g$ on $\partial\Omega$.

Let us show that $u$ is also a supersolution, so that it will be a viscosity solution. Assume that this is not the case, i.e. there is a point $x_0 \in \Omega$ and a function $\varphi \in C^1(\Omega) \cap C(\overline{\Omega})$ such that $u \geq \varphi$ on $\overline{\Omega}$ with $u(x_0)=\varphi(x_0)$ and 
\begin{equation} \label{3.2.1}
-L[\varphi](x_0) +f(\varphi(x_0))<0.
\end{equation}
%Thanks to Remark \ref{rmk: strict}, 
We recall that we may assume $x_0$ to be the unique minimum of $u-\varphi$. Indeed, for $\delta>0$ small enough, set $\varphi_{\delta}(x)=\varphi(x)-\delta |x-x_0|^2$. Hence, we clearly have $\varphi_\delta \leq \varphi \leq u$ on $\overline{\Omega}$ with $\varphi_\delta(x_0)=\varphi(x_0)=u(x_0)$. Moreover, by Lemma \ref{lem:delta perturbation}, we have 
$$-L[\varphi_\delta](x_0) +f(\varphi_\delta(x_0)) \leq -L[\varphi](x_0)+C\delta +f(\varphi(x_0)) <0,$$
as soon as $\delta>0$ is sufficiently small. 

Now, we claim that $u(x_0)<u^+(x_0)$. Suppose it is not the case, i.e. we have \,$u(x_0)=u^+(x_0)$. Hence, we infer that $\varphi \leq u \leq u^+$ on $\overline{\Omega}$ with $u^+(x_0)=\varphi(x_0)$, and having $u^+$ is a viscosity supersolution, then 
$$-L[\varphi](x_0) +f(\varphi(x_0)) \geq 0,$$
which is a contradiction. 

Since $u^+$, $\varphi$ are continuous on $\Omega$, $\varphi(x_0)=u(x_0)<u^+(x_0)$, $\varphi \leq u \leq u^+$ and $x_0$ is the unique minimum of $u-\varphi$, then there will be a small constant $\zeta_0>0$ such that $\varphi+\zeta \leq u^+$ on $\overline{\Omega}$, for all $0<\zeta \leq \zeta_0$.
%in a neighborhood $B(x_0,\varepsilon_0)$\, of \,$x_0$; where $\varepsilon_0>0$ is small enough.
We set 
$$u_\zeta=\max\{u\,,\,\varphi + \zeta\}.$$
We shall prove that $u_\zeta \in S$, for $\zeta>0$ small enough. In this case, since $u \geq u_\zeta$ on $\overline{\Omega}$, one has in particular at $x=x_0$ that 
$$ u(x_0) \geq u_\zeta(x_0)=\varphi(x_0)+\zeta=u(x_0)+\zeta,$$
which is clearly a contradiction as $\zeta>0$. Hence, it remains to prove the claim that $u_\zeta \in S$. First, it is clear that $u^- \leq u \leq  u_\zeta \leq u^+$. Let us show that $u_\zeta$ is a subsolution. Assume it is not the case, so there exists a point  $x_\zeta \in \Omega$ and a function $\varphi_\zeta \in C^1(\Omega) \cap C(\overline{\Omega})$ such that \,$u_\zeta \leq \varphi_\zeta$\, on \,$\overline{\Omega}$\, and \,$u_\zeta(x_\zeta)=\varphi_\zeta(x_\zeta)$ with 
\begin{equation} \label{3.2.2}
 -L[\varphi_\zeta](x_\zeta)+f(\varphi_\zeta(x_\zeta))>0.
 \end{equation}
Here, we have two possibilities: either \,$u_\zeta(x_\zeta)=u(x_\zeta)$ or $u_\zeta(x_\zeta)=\varphi(x_\zeta)+\zeta$. If \,$u_\zeta(x_\zeta)=u(x_\zeta)$ for some $\zeta$, then we have $u(x_\zeta)=\varphi_\zeta(x_\zeta)$ and $u \leq u_\zeta \leq \varphi_\zeta$. But $u$ is a subsolution, then we must have  
$$ -L[\varphi_\zeta](x_\zeta)+f(\varphi_\zeta(x_\zeta)) \leq 0,$$
which is a contradiction. 

The remaining case is when $u_\zeta(x_\zeta)=\varphi(x_\zeta)+\zeta$ for all $\zeta$ small, so $\varphi_\zeta(x_\zeta)=\varphi(x_\zeta) +\zeta$. Since $\varphi+\zeta \leq u_\zeta \leq \varphi_\zeta$, then one has
$$ \varphi \leq \varphi_\zeta -\zeta \qquad \mbox{on}\,\,\,\,\,\overline{\Omega}.$$
Hence, we have 
$$L[\varphi](x_\zeta) \leq L[\varphi_\zeta-\zeta](x_\zeta)= L[\varphi_\zeta](x_\zeta).$$
In particular, we get that
$$- L[\varphi_\zeta](x_\zeta) +f(\varphi(x_\zeta))\leq -L[\varphi](x_\zeta) + f(\varphi(x_\zeta)).$$
Consequently, 
\begin{equation} \label{3.2.3}
[- L[\varphi_\zeta](x_\zeta)+f(\varphi_\zeta(x_\zeta)) ]+[f(\varphi(x_\zeta))-f(\varphi_\zeta(x_\zeta))]\leq -L[\varphi](x_\zeta) + f(\varphi(x_\zeta)).
\end{equation}\\
Recalling \eqref{3.2.2}, \eqref{3.2.3} yields to
\begin{equation} \label{3.2.4}
f(\varphi(x_\zeta))-f(\varphi_\zeta(x_\zeta))\leq -L[\varphi](x_\zeta) + f(\varphi(x_\zeta)).
\end{equation}
However, we claim that the sequence of points $x_\zeta$ converges to $x_0$. Otherwise, it means that up to a subsequence $x_\zeta \rightarrow x^\star \neq x_0$. But, we have 
$$u(x_\zeta) \leq u_\zeta(x_\zeta) = \varphi(x_\zeta) +\zeta,\,\,\,\mbox{for all}\,\,\,\zeta.$$
Letting $\zeta \to 0^+$, we infer that $u(x^\star) \leq \varphi(x^\star)$. Hence, $u(x^\star)=\varphi(x^\star)$ and $x^\star$ is a minimum point of $u- \varphi$. Yet, $x_0$ is the unique minimum point for $u- \varphi$ and so, $x^\star=x_0$. Yet, this is also a contradiction. So, our claim is proved. 

Passing to the limit in \eqref{3.2.4}, we get
$$0 \leq  -L[\varphi](x_0) + f(\varphi(x_0)).$$
But, this contradicts \eqref{3.2.1}. Hence, this concludes the proof that $u_\zeta \in S$. 
\end{proof}


We finish this section by the following observation that we will use when dealing with the obstacle problem.
