%it converges uniformly to $g$ on $\partial\Omega$. %Moreover, $g_\varepsilon$ shares the same $\beta-$H\"older norm with $g$ since we have $||g_\varepsilon|| \leq ||g||$ and,
%$$|g_\varepsilon(x)-g_\varepsilon(y)| =\bigg|\int \eta_\varepsilon(z) g(x-z) \,\mathrm{d}z - \int \eta_\varepsilon(z) g(y-z) \,\mathrm{d}z\bigg|=\bigg|\int \eta_\varepsilon(z) [g(x-z)-g(y-z)] \,\mathrm{d}z\bigg|$$
%$$ \leq \int \eta_\varepsilon(z) |g(x-z)-g(y-z)| \,\mathrm{d}z \leq [g]_{C^{0,\beta}(\partial\Omega)}\,|x-y|^\beta.$$
For every $\varepsilon >0$, by Proposition \ref{existence of a solution}, we know that there exists a solution $u_\varepsilon$ to Problem \eqref{Frac Inf Lap Eq} with \,$u_\varepsilon=g$\, on \,$\partial\Omega$. Recalling Remark \ref{Remark 2}, we may assume that $u_\varepsilon>0$ on $\Omega$. In addition, by Proposition \ref{beta Holder regularity}, we have that
 $$||u_\varepsilon||_{C^{0,\beta}(\overline\Omega)}  \leq C\bigg(\alpha,\,\beta,\,\mbox{diam}(\Omega),\,||g||_{C^{0,\beta}(\partial\Omega)},\,f(||g||_\infty)\bigg)
 %C\bigg( ||g||_{C^{0,\beta}(\partial\Omega)},\frac{ \,\,[\mbox{diam}(\Omega)]^{\alpha-\beta}}{1-\Psi(r_\star)}\,f(||g||_\infty)\bigg)
 ,$$
 for $\varepsilon>0$ small enough. %Yet, it is clear that $f_\varepsilon(||g||_\infty) \leq $
%$$||u_\varepsilon||_{C^{0,\alpha}(\omega)} \leq \frac{2||g||_{\infty}}{\dist(\omega,\partial\Omega)^\alpha}.$$
%+\frac{\,\,[\mbox{diam}(\Omega)]^{\alpha-\beta}}{1-\Psi(r_\star)}\,f(||g||_\infty).$$
Hence, $(u_\varepsilon)_\varepsilon$ is bounded in $C^{0,\beta}(\overline\Omega)$. Therefore, up to a subsequence, $u_\varepsilon \rightarrow u$ 
 uniformly in \,$C^{0,\beta}(\overline\Omega)$\, and \,$u \geq 0$\, on \,$\overline{\Omega}$.

We will show  that $u$ is a viscosity subsolution to \eqref{N system with obstacle} (the fact that $u$ is a supersolution can be treated similarly). Therefore, $u$ will be a viscosity solution for Problem \eqref{N system with obstacle} with boundary datum $u=g$. Assume by contradiction that $u$ is not a subsolution then there exists $x_0\in\{u>0\}$ and a function $\varphi \in C(\overline{\Omega}) \cap C^1(\Omega)$ such that $u \leq \varphi$ on $\overline{\Omega}$ with $u(x_0)=\varphi(x_0)$ but
$$-L[\varphi](x_0) +f(\varphi(x_0)) > 0.$$
%We recall that one can assume $x_0$ to be the unique maximum point of $u- \varphi$.
 Thanks to the uniform convergence of $u_\varepsilon$ to $u$, one can find a sequence $\varphi_\varepsilon$ converging uniformly to $\varphi$ such that $\varphi_\varepsilon \in C(\overline{\Omega}) \cap C^1(\Omega)$, \,$u_\varepsilon
\leq \varphi_\varepsilon$\, on \,$\overline{\Omega}$\, and $u_\varepsilon(x_\varepsilon)=\varphi_\varepsilon(x_\varepsilon)$, where $x_\varepsilon \to x_0$ when $\varepsilon \to 0$. Since $u_\varepsilon$ is a viscosity solution, then 
\begin{equation} \label{5.0.1}
-L[\varphi_\varepsilon](x_\varepsilon) +f_\varepsilon(\varphi_\varepsilon(x_\varepsilon))\leq 0.
\end{equation}
%On the one side, we have 
%$$-L[\varphi_\varepsilon](x_\varepsilon)=-L[\varphi](x_\varepsilon) +L[\varphi](x_\varepsilon) -L[\varphi_\varepsilon](x_\varepsilon).$$
Yet, 
$$L[\varphi_\varepsilon](x_\varepsilon)=\sup_{y\in \bar \Omega,\,y\neq x_\varepsilon} \dfrac{\varphi_\varepsilon(y)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}}+\inf_{y\in \bar \Omega,\,y\neq x_\varepsilon} \dfrac{\varphi_\varepsilon(y)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}}.$$
We claim that 
$$|L[\varphi_\varepsilon](x_\varepsilon) -L[\varphi](x_\varepsilon)|\leq C ||\varphi_\varepsilon -\varphi||_\infty^{1-\alpha}.$$
We will show this inequality for $L^+$ (the proof for $L^-$ will be similar and so, it will be omitted). First, one has
$$\dfrac{\varphi_\varepsilon(y)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}}=\dfrac{\varphi(y)-\varphi(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}} +\dfrac{\varphi_\varepsilon(y)-\varphi(y) +\varphi(x_\varepsilon)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}}.$$
But, it is clear that
$$ \dfrac{\varphi_\varepsilon(y)-\varphi(y) +\varphi(x_\varepsilon)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}} \leq 2\, 
\min\bigg\{\dfrac{||\varphi_\varepsilon-\varphi||_\infty}{|y-x_\varepsilon|^{\alpha}},C\,|y-x_\varepsilon|^{1-\alpha}\bigg\},
$$
where $C<\infty$ is a uniform constant such that $\mbox{Lip}(\varphi_\varepsilon),\,\mbox{Lip}(\varphi) \leq C$ on $\overline{B(x_0,\delta)}$, for $\delta>0$ small enough.
%$0<\delta<\dist(x_0,\partial\Omega)$.
Then, we get that
$$ \dfrac{\varphi_\varepsilon(y)-\varphi(y) +\varphi(x_\varepsilon)-\varphi_\varepsilon(x_\varepsilon)}{|y-x_\varepsilon|^{\alpha}} \leq C\, 
\min\bigg\{\dfrac{||\varphi_\varepsilon-\varphi||_\infty}{|y-x_\varepsilon|^{\alpha}},\,|y-x_\varepsilon|^{1-\alpha}\bigg\}\leq C ||\varphi_\varepsilon-\varphi||_\infty^{1-\alpha}.
$$
On the other hand, it is clear that $\varphi_\varepsilon(x_\varepsilon) \rightarrow \varphi(x_0)>0$ and so, $f_\varepsilon(\varphi_\varepsilon(x_\varepsilon))=f(\varphi_\varepsilon(x_\varepsilon)) \rightarrow f(\varphi(x_0))$. Hence, thanks to Lemma \ref{lem:continuity} and passing to the limit when $\varepsilon \to 0$ in \eqref{5.0.1}, we infer that 
$$-L[\varphi](x_0) +f(\varphi(x_0))\leq 0,$$
which contradicts our main assumption.

Finally, following the same argument in Proposition \ref{beta Holder regularity} and using the fact that $f=0$ on $\mathbb R^-$ and Propositon \ref{alpha=beta}, we get that $u_{\epsilon}$ are locally $\alpha-$H\"older continuous uniformly in $\epsilon$, then letting $\epsilon\to 0$ we get that $u$ is locally H\"older continuous. 
%the local $\alpha-$H\"older regularity of $u_\varepsilon$ follows exactly as in the proof of  Proposition and the fact that $f=0$ on $\mathbb{R}^-$, and letting $\epsilon\to 0$ imply that $u$ is locally $\alpha-$H\"older continuous.
