    \centering
    \begin{tikzcd}
    &
        \begin{tabular}{c}
             Strong Detection  \\
              ($\mathbb{P}$ vs $\mathbb{Q}$)
        \end{tabular}
    & \\
    \begin{tabular}{c}
             Exact Recovery  \\
              (in $\mathbb{P}$)
    \end{tabular}
        \arrow{ur}{}
        & &
