b&: y^{2} - \left(t +1 1\right) y x  -t y= x^{3} + t x^{2}\,,\\
c&: y^{2} - \left(3 t - 1\right) y x + 3 t^{2} x^{2} + 2 t^{3} y = x^{3}+ 3 t^{4} x - t^{6}\,,\\
d&: y^{2} - \left(4 t - 1\right) y x + 2 t^{2} x^{2} = x^{3} - 4 t^{4} x - (8t^2 - 8 t + 1)t^4\,,\\
e&: \left(16 t - 1\right) y^{2} - \left(16 t - 1\right) y x -t y = \left(16 t - 1\right) x^{3}  +t x^{2}\,,\\
f&:  y^{2} - \left(3 t - 1\right) y x + 9 t^{3} y = x^{3} - t^3 (6 t-1) \left(9 t^2-3 t+1\right)\,,\\
