i&: \left(64 t - 1\right) y^{2} = \left(64 t - 1\right) x^{3} - \left(48 t - 3\right) x -16 t - 2\,,\\
j&: \left(432 t - 1\right) y^{2}  = \left(432 t - 1\right) x^{3} - \left(1296 t - 3\right) x +864 t + 2\,.
 \end{aligned}
