     \caption{{Histogram of the optimal window sizes, $L$, for constructing the auxiliary variance series for  each return series $\tilde{r}_i(t)$. The mean value of this distribution is close to $L = 14$.}}
     \label{fig:M_hist}
 \end{figure}

 \begin{figure}
