\section{The Meijer $G$-function}\label{meijer G appendix}

The Meijer $G$-function is defined by its Mellin transform \cite{beals2013meijer}:
\be\label{Mtransform}
{\cal M}[G;s]=\frac{\prod_{j=1}^m\Gamma
(s+b_j)\prod_{j=1}^n\Gamma (1-s-a_j)}{\prod_{j=m+1}^q\Gamma
(1-s-b_j)\prod_{j=n+1}^p\Gamma (s+a_j)},
\ee
where
\be 
{\cal M}[f;s] \equiv \int_0^\infty dx  x^{s-1}f(x).
\ee 
The standard notation is
\be 
G(x)=G_{p,q}^{m,n}\left( 
\begin{array}{l}
\boldsymbol{a} \\ 
\boldsymbol{b}
\end{array}
\bigg | x\right) \label{Univariate-Mellin-G},
\ee 
where $\boldsymbol{a}=(a_1,\ldots ,a_p)$ and $\boldsymbol{b}=(b_1,\ldots ,b_q)$. {When one of the indexes $\{m,n,p,q\}$ is zero in Eq.~\eqref{Univariate-Mellin-G}, the corresponding product of gamma functions in the Mellin transform in (\ref{Mtransform}) is not present  and so  we  leave a blank slot, denoted by the symbol $-$ in the respective parameter entry of the $G$-function.}

A few useful properties of the Meijer $G$-functions, {which help to perform some of the calculations indicated in the main text},  are listed below.
\begin{itemize}
    \item {\it Argument inversion:}
    \be\label{argumentinversion}
    G_{p,q}^{m,n}\left( 
\begin{array}{l}
\boldsymbol{a} \\ 
\boldsymbol{b}
\end{array}
\bigg | \frac{1}{x}\right)= 
G_{q,p}^{n,m}\left( 
\begin{array}{l}
{\bf 1} - \boldsymbol{b} \\ 
{\bf 1} - \boldsymbol{a}
\end{array}
\bigg | x\right).
    \ee

\item {\it Power absorption:}
\be\label{powerabsorption}
x^{\sigma} G_{p,q}^{m,n}\left( 
\begin{array}{l}
\boldsymbol{a} \\ 
\boldsymbol{b}
\end{array}
\bigg | x\right)= 
G_{p,q}^{m,n}\left( 
\begin{array}{l}
\sigma{\bf 1} + \boldsymbol{a} \\ 
\sigma{\bf 1} + \boldsymbol{b}
\end{array}
\bigg | x\right),
\ee
\item {\it {Convolution theorem:}}
\ba\label{convolution}
    && \int_{0}^{\infty} 
    G_{n,m}^{m,n}\left( 
    \begin{array}{l}
        \boldsymbol{a} \\ 
        \boldsymbol{b}
    \end{array}
    \bigg | \xi x\right) 
    G_{t,r}^{r,t}\left( 
    \begin{array}{l}
        \boldsymbol{c} \\ 
        \boldsymbol{d}
    \end{array}
    \bigg | \eta x\right) dx \nonumber \\
    && \; = \frac{1}{\eta} G_{n + r,m + t}^{m + t,n + r}\left( 
    \begin{array}{l}
        (\boldsymbol{a}, -\boldsymbol{d}) \\ 
        (\boldsymbol{b}, -\boldsymbol{c})
    \end{array}
    \bigg | \frac{\xi}{\eta} \right). \label{convolution1}
\ea
\end{itemize}

{The last  property above is particularly useful when computing integrals involving $G$-functions, since it  shows that the integral of the product of two $G$-functions is also a $G$-function \cite{debnath2016integral}.}


\section{Properties of the Meijer $\bar G$-function of matrix argument}

\label{appendixproperties}

{The Meijer $\bar{G}$-function of matrix argument  was defined in  the main text in terms of its matrix Mellin transform, see Eqs.~(\ref{eq:MbarG}) and (\ref{MTransformMatrix}), which we reproduce here for convenience:
\be\label{M}
\begin{split}
M[\bar{G};s] = \ &\frac{\prod_{j=1}^m\Gamma_p
(s+b_j)}{\prod_{j=m+1}^q\Gamma_p
((1+p)/2-s-b_j)} \\ &\times\frac{\prod_{j=1}^n\Gamma_p ((1+p)/2-s-a_j)}{\prod_{j=n+1}^p\Gamma_p (s+a_j)}.
\end{split}
\ee
where 
\be 
M[f;s] \equiv \int_{X>0} dX |X|^{s-(p+1)/2}f(X),
\ee 
with $X$ being a $p\times p$ real, symmetric, positive definite matrix and $\Gamma_p$ is the multivariate version of the gamma function; see Eq.~(\ref{multivariategamma}).
}


{Here we prove two basic properties of the $\bar{G}$ function of matrix argument which are used in the main text.
\begin{itemize}
    \item {\bf Argument inversion}:
\end{itemize}
\be \label{matrixargumentinversion}
\bar{G}_{p,q}^{m,n}\left( 
\begin{array}{l}
\boldsymbol{a} \\ 
\boldsymbol{b}
\end{array}
\bigg | X^{-1}\right) =
\bar{G}_{q,p}^{n,m}\left( 
\begin{array}{l}
\frac{1+p}{2}\boldsymbol{1}-\boldsymbol{b} \\ 
\frac{1+p}{2}\boldsymbol{1}-\boldsymbol{a}
\end{array}
\bigg | X\right)
\ee 
{\it Proof:}
Starting from 
\be 
M[\bar{G};s] \equiv \int_{X>0} dX |X|^{s-(p+1)/2}\bar{G}(X),
\ee 
and making the change of variable $X = Y^{-1}$, so that $dX = |Y|^{-p-1} dY$, we obtain
\be 
M[\bar{G};s] \equiv \int_{Y>0} dY |Y|^{-s-(p+1)/2}\bar{G}(Y^{-1}).
\ee 
From the definition of (\ref{M}), we obtain after some manipulation:
\ba
M[\bar{G};s]=&\frac{\prod_{j=1}^m\Gamma_p
(s+b_j)}{\prod_{j=m+1}^q\Gamma_p
((1+p)/2-s-b_j)} \nonumber \\ 
&\times\frac{\prod_{j=1}^n\Gamma_p ((1+p)/2-s-a_j)}{\prod_{j=n+1}^p\Gamma_p (s+a_j)} \nonumber \\ 
=&\frac{\prod_{j=1}^n\Gamma_p (-s+(1+p)/2-a_j)}{\prod_{j=n+1}^p\Gamma_p (s+a_j)}\\ &\times \frac{\prod_{j=1}^m\Gamma_p
(s+b_j)}{\prod_{j=m+1}^q\Gamma_p
(-s+(1+p)/2-b_j)} \nonumber\\
=&\frac{\prod_{j=1}^n\Gamma_p (-s+(1+p)/2-a_j)}{\prod_{j=n+1}^p\Gamma_p ((1+p)/2+s+a_j-(1+p)/2)} \nonumber 
\\ &\times\frac{\prod_{j=1}^m\Gamma_p
((1+p)/2+ s+b_j - (1+p)/2)}{\prod_{j=m+1}^q\Gamma_p
(-s+(1+p)/2-b_j)} \nonumber.
\ea
Comparing the previous two equations, we  see that $\bar{G}(Y^{-1})$ satisfies the Mellin matrix transform for the variable $-s$, after making the correspondence $a_j \rightarrow (1+p)/2 - b_j$ and $b_j \rightarrow (1+p)/2 - a_j$ and $m \leftrightarrow n$, $q \leftrightarrow p$, from which  (\ref{matrixargumentinversion}) follows.
}

{
\begin{itemize}
    \item {\bf Power Absorption:}
\end{itemize}
\be \label{matrixpowerabsorption}
|X|^{\sigma}\bar{G}_{p,q}^{m,n}\left( 
\begin{array}{l}
\boldsymbol{a} \\ 
\boldsymbol{b}
\end{array}
\bigg | X\right) =
\bar{G}_{p,q}^{m,n}\left( 
\begin{array}{l}
\sigma\boldsymbol{1}+\boldsymbol{a} \\ 
\sigma\boldsymbol{1}+\boldsymbol{b}
\end{array}
\bigg | X\right)
\ee 
}
{
{\it Proof:}
The Mellin matrix transform of $|X|^{\sigma}G(X)$ can be worked out similarly using the definition of the matrix-argument Meijer $G$-function:
\ba
M[\bar{G};s] &= \int_{X>0} dX |X|^{s-(p+1)/2} |X|^{\sigma} \bar{G}(X)\cr
&= \int_{X>0} dX |X|^{s+\sigma-(p+1)/2} \bar{G}(X)
\ea 
The expression above is simply the Mellin transform on the variable $s + \sigma$, where $\sigma$ can be absorbed by $a_i$ and $b_j$ using the definition:
\be
\begin{split}
M[|X|^{\sigma} \bar{G}; s]=&\frac{\prod_{j=1}^m\Gamma_p
(s+(\sigma+b_j))}{\prod_{j=m+1}^q\Gamma_p
((1+p)/2-s-(\sigma+b_j))}\\ \times&\frac{\prod_{j=1}^n\Gamma_p ((1+p)/2-s-(\sigma+a_j))}{\prod_{j=n+1}^p\Gamma_p (s+\sigma+a_j)} 
\end{split}
\label{eq:MXsigma}
\ee
that is, letting $a_i \rightarrow a_i + \sigma$ and $b_i \rightarrow b_i + \sigma$. From (\ref{eq:MXsigma}) one then obtains (\ref{matrixpowerabsorption}).
}

\section{Color Flavor Transformation Proof}
\label{appendixA}
\subsection{Gamma-CFT}
Let us first start with the integral 
\ba \label{defGpIntegral}
    G_p(\nu, A, {\bf r})&\equiv\frac{1}{\Gamma_p(\nu)} \displaystyle \int_{X>0} dX |X|^{\nu - (p+1)/2} \nonumber
    \\ \times& \exp(-\text{Tr} X -{\bf r}^\top A^{1/2} X A^{1/2}{\bf r})
\ea
where $A$ and $X$ are p $\times$ p real symmetric positive definite matrices $\text{Re}(\nu) > (p+1)/2$. Writing ${\bf r}^\top A^{1/2} X A^{1/2}{\bf r} = \text{Tr}(A^{1/2} {\bf r}\;{\bf r}^\top A^{1/2} X)$ we obtain \cite{mathai1997jacobians}
\begin{equation}
    G_{p}(\nu, A, {\bf r}) = |\mathbb{1}_{p}+A^{1/2} {\bf r}\;{\bf r}^\top A^{1/2} |^{-\nu} ,
\end{equation}
where $\mathbb{1}_{p}$ is a $p \times p$ identity matrix.
Using the Weinstein–Aronszajn identity \cite{pozrikidis2014introduction},
\begin{equation}\label{defG1Integral}
\begin{split}
    G_{p}(\nu, A, {\bf r}) &= |\mathbb{1}_{p}+A^{1/2} {\bf r}\;(A^{1/2} {\bf r})^\top |^{-\nu} \\
    &= (1 + {\bf r}^\top A {\bf r} )^{-\nu} \\
    &= \frac{1}{\Gamma(\nu)}\int_0^\infty dx\; x^{\nu - 1} \exp(-x-x{\bf r}^\top A {\bf r})\\
    &= G_1(\nu, A, {\bf r})
\end{split}
\end{equation}

We can conclude that the value of $G_p$ is independent of the matrix dimension. It makes easier to substitute all integrals defined in Eq.~(\ref{defGpIntegral}) by their univariate versions $G_1$.


\subsection{Meijer-Wishart CFT} \label{Meijer-Wishart CFT subsection}
Let us consider in this section that $f(\Sigma_i|\Sigma_{i-1})$ is the Wishart distribution in Eq.~(\ref{wishartdistribution}). The Meijer $\bar{G}$-function with matrix argument can be written as:
\begin{equation}
\begin{split}
    &\frac{1}{\Gamma_p({\bf \boldsymbol{\beta}})} \overline{G}^{N, 0}_{0, N} \left( 
    \begin{array}{c}
    - \\
    \boldsymbol{\beta} - \frac{p+1}{2}{\bf 1}
    \end{array} \middle \vert X
    \right)\\& = \int d\Sigma_1 ... d\Sigma_{N-1} f(X|\Sigma_{N-1})...f(\Sigma_1|\mathbb{1} \omega)
\end{split}
\end{equation}
Let us start with the integral we want to work out
\begin{align}
    \label{Ik}
    \mathcal{M}G_{p, N}(A, \boldsymbol{\beta}, {\bf r}) &\equiv \nonumber \\\frac{1}{\Gamma_p({\bf \boldsymbol{\beta}})} \int &dX \exp(-{\bf r}^\top A^{1/2} X A^{1/2} {\bf r} )\\ \times &\overline{G}^{N, 0}_{0, N} \left( 
    \begin{array}{c}
    - \\
    \boldsymbol{\beta} - \frac{p+1}{2}{\bf 1}
    \end{array} \middle \vert X
    \right) \nonumber \\
    =\int d\Sigma_1 ... d\Sigma_{N-1} &f(\Sigma_{N-1}|\Sigma_{N-2})...f(\Sigma_1|\mathbb{1}\omega) \label{MGcompound}\\
\times \int dX &\exp (- {\bf r}^\top A^{1/2} X A^{1/2} {\bf r}) \; f(X|\Sigma_{N-1}).\nonumber
\end{align}
The integral in $dX$ in last equality above can be developed using 
\begin{equation}
\begin{split}
  &\int dX \exp (- {\bf r}^\top A^{1/2} X A^{1/2} {\bf r}) \; f(X|\Sigma_{N-1}) \\
  = &\frac{|\beta_N \Sigma_{N-1}^{-1}|^{\beta_N}}{\Gamma(\beta_N)} \int dX |X|^{\beta_N - (p+1)/2} \\ &\times \exp(-\beta_N\text{Tr}(X \Sigma_{N-1}^{-1})-{\bf r}^\top A^{1/2} X A^{1/2} {\bf r})
\end{split}
\end{equation}
performing a change of variables $X = \Sigma_{N-1}^{1/2} Y \Sigma_{N-1}^{1/2}/\beta_N$, we can use the Gamma-CFT in Eq.~(\ref{defG1Integral}),
\begin{equation*}
    \begin{split}
         = &\frac{1}{{\Gamma_p(\beta_N)}}\int dY |Y|^{\beta_N - (p+1)/2} \\ & \times \exp(-\text{Tr}Y- {\bf r}^\top A^{1/2} \Sigma_{N-1}^{1/2} Y \Sigma_{N-1}^{1/2} A^{1/2} {\bf r}/\beta_N) \\
         = &\frac{1}{{\Gamma(\beta_N)}} \int dy\; y^{\beta_N - 1} \\
         &\times \exp(-y -y{\bf r}^\top A^{1/2} \Sigma_{N-1} A^{1/2}{\bf r}/\beta_N ) \\
         = &\frac{\beta_N^{\beta_N}}{{\Gamma(\beta_N)}}\int dx\; x^{\beta_N - 1} \\
         &\times \exp(-x\beta_N  -x{\bf r}^\top A^{1/2} \Sigma_{N-1} A^{1/2}{\bf r} ) ,
    \end{split}
\end{equation*}
where in the last equality we made $y = x\beta_N$. Putting the result above back in Eq.~(\ref{MGcompound}) and rearranging the integral ordering, we obtain
\begin{equation}
\begin{split}
    &\mathcal{M}G_{p, N}(A, \boldsymbol{\beta}, {\bf r}) = \\
    &\frac{\beta_N^{\beta_N}}{{\Gamma(\beta_N)}}\int dx\; x^{\beta_N - 1} \exp(-x\beta_N) \\
    \times&\int d\Sigma_1 ... d\Sigma_{N-2} f(\Sigma_{N-2}|\Sigma_{N-3})...f(\Sigma_1|\mathbb{1}\omega) \\
\times & \int d\Sigma_{N-1}\exp(-{\bf r}^\top A^{1/2} \Sigma_{N-1} A^{1/2}{\bf r}/x ) \; f(\Sigma_{N-1}|\Sigma_{N-2}).\nonumber
\end{split}
\end{equation}

The whole expression above has the same form of integral $dX$ as in Eq.~(\ref{Ik}). Repeating the procedure described above until we run out of matrix integrals we obtain
\begin{equation}
    \begin{split}
        &\mathcal{M}G_{p, N}(B, \boldsymbol{\beta}, {\bf r}) = \frac{\beta_N^{\beta_N} ... \beta_1^{\beta_1}}{{\Gamma\left(\boldsymbol{\beta}\right)}}\\ &\times \int dxx^{\beta_N - 1}  
     \exp(-x\beta_N) \prod_{i=1}^{N-1} \int d\varepsilon_{i}\varepsilon_{i}^{\beta_i - 1}  
     \exp(-\varepsilon_{i} \beta_i) \\ 
     &\times \exp(-\omega{\bf r}^\top A {\bf r}x\varepsilon_{N-1}...\varepsilon_1)
    \end{split}
\end{equation}
After performing the change of variables $\varepsilon_i = \epsilon_{i}/\epsilon_{i-1}$, where $\varepsilon_N = x$ and $\epsilon_0 = \omega$ and rearranging the integrals in $d\epsilon_i$ we obtain the Meijer $G$-function with scalar arguments.
\begin{equation} \label{Meijer-Wishart CFT}
    \begin{split}
        \mathcal{M}G_{p, N} (A, \boldsymbol{\beta}, {\bf r}) &=
        \frac{1}{\Gamma(\boldsymbol{\beta})}
        \int dx \exp(-x{\bf r}^\top A {\bf r}) \\&\times \; G^{N, 0}_{0, N} \left( 
    \begin{array}{c}
   -\\
    \boldsymbol{\beta} - {\bf 1}
    \end{array} \middle \vert x 
    \right) = \mathcal{M} G_{1, N} (A, \boldsymbol{\beta}, {\bf r})
    \end{split}
\end{equation}
In Eqs.~(\ref{CFTWishart1}) and (\ref{CFTWishart2}), it is enough to make $B = \Sigma_0\sqrt{2\omega}$.

From Eq.~(\ref{Meijer-Wishart CFT}), making a changing of variables $X = Y^{-1}$, so that $dX = |Y|^{-p-1} dY$ in the multivariate integral and $x = y^{-1}$, so that $dx = -y^{-2} dy$ and making $\boldsymbol{\beta} \rightarrow \boldsymbol{\beta} + \frac{3}{2} \boldsymbol{1}$ we obtain
\begin{align}
    \frac{1}{\Gamma_p({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})} \int &dY |Y|^{-p-1} \exp(-{\bf r}^\top A^{1/2} Y^{-1} A^{1/2} {\bf r} ) \nonumber \\ \times &\; \overline{G}^{N, 0}_{0, N} \left( 
    \begin{array}{c}
    - \\
    {\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1} - \frac{p+1}{2}{\bf 1}
    \end{array} \middle \vert Y^{-1}
    \right) \nonumber \\ =\frac{1}{\Gamma({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})}
        \int &dy y^{-2} \exp(-{\bf r}^\top A {\bf r}/y) \nonumber \\ \times &\; G^{N, 0}_{0, N} \left( 
    \begin{array}{c}
   - \\
    {\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1} - {\bf 1}
    \end{array} \middle \vert y^{-1} 
    \right) \nonumber
\end{align}
By using argument inversion in Eqs.~(\ref{argumentinversion}) and  (\ref{matrixargumentinversion}), we obtain
\begin{align}
    \frac{1}{\Gamma_p({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})} \int &dY |Y|^{-p-1} \exp(-{\bf r}^\top A^{1/2} Y^{-1} A^{1/2} {\bf r} ) \nonumber \\ \times &\; \overline{G}^{0, N}_{N, 0} \left( 
    \begin{array}{c}
    -{\bf \boldsymbol{\beta}} - \frac{3}{2}\boldsymbol{1} + (p+1){\bf 1} \\
    -
    \end{array} \middle \vert Y
    \right) \nonumber \\ =\frac{1}{\Gamma({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})}
        \int &dy y^{-2} \exp(-{\bf r}^\top A {\bf r}/y) \nonumber \\ \times &\; G^{0, N}_{N, 0} \left( 
    \begin{array}{c}
   -{\bf \boldsymbol{\beta}} + \frac{1}{2}\boldsymbol{1}\\
    -
    \end{array} \middle \vert y 
    \right) \nonumber
\end{align}
and using power absorption in Eqs.~(\ref{powerabsorption}) and (\ref{matrixpowerabsorption}) 
\begin{equation}\label{Meijer-Inverse Wishart CFT}
\begin{split}
    \frac{1}{\Gamma_p({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})} \int &dY |Y|^{-1/2} \exp(-{\bf r}^\top A^{1/2} Y^{-1} A^{1/2} {\bf r} ) \\ \times &\; \overline{G}^{0, N}_{N, 0} \left( 
    \begin{array}{c}
    -{\bf \boldsymbol{\beta}} - \boldsymbol{1} \\
    -
    \end{array} \middle \vert Y
    \right) \\ =\frac{1}{\Gamma({\bf \boldsymbol{\beta}} + \frac{3}{2}\boldsymbol{1})}
        \int &dy y^{-1/2} \exp(-{\bf r}^\top A {\bf r}/y)  \\ \times &\; G^{0, N}_{N, 0} \left( 
    \begin{array}{c}
   -{\bf \boldsymbol{\beta}} - \boldsymbol{1}\\
    -
    \end{array} \middle \vert y 
    \right) 
\end{split}
\end{equation}
In order to obtain Eq.~(\ref{CFTInverse2}) we need to make $A = (\sqrt{2\omega}\Sigma_0)^{-1}$ and multiply both sides by $1/\Gamma_p (\boldsymbol{\beta} + \boldsymbol{1})$ and the definition in Eq.~(\ref{multivariategamma}).

