\begin{proposition}\label{p-ir}
There exists a mechanism that is both maximal and IR. 
\end{proposition}

\begin{proof}
For an IKEP instance $I= \langle G, \V, \Gamma\rangle$, the mechanism selects a maximum national $\Gamma$-cycle packing $\C$ of $G$ and then extends $\C$ to a maximal $\Gamma$-cycle packing $\C'$ of $G$ by exhaustively adding (international) $\Gamma$-cycles that are vertex-disjoint from the already selected $\Gamma$-cycles.
\end{proof}

Let $I= \langle G, \V, \Gamma\rangle $ be an IKEP instance.
Recall that a $\Gamma$-cycle  in $G$ is international if it has at least one international arc and that else it is national.
Let $c_{{\tt nat}}$ and $c_{{\tt int}}$ denote the length of a largest national $\Gamma$-cycle and the length of a largest international $\Gamma$-cycle, respectively, in a graph $G$ in an IKEP instance. Note that $c_{{\tt nat}} \leq \max\{\natv_i\; |\; 1\leq i\leq n\}$ and that 
$c_{{\tt int}}\leq \intv$.

We now observe the following lower bound for the approximation ratio of IR mechanisms. As can be seen from the proof of Proposition~\ref{p-alpha1}, this lower bound even holds for near-perfect IKEP instances; here, an IKEP instance is {\it near-perfect} if $G$ has a {\it near-perfect} $\Gamma$-cycle packing ${\mathcal C}$, that is, there exists exactly one vertex in $G$ that belongs to no cycle in ${\mathcal C}$.

\begin{proposition}\label{p-alpha1}
No IR mechanism can provide an $\alpha$-approximation ratio with $\alpha\leq (1-\epsilon)c_{{\tt int}}$, for any $\epsilon>0$.
\end{proposition}

\begin{proof}
We construct an IKEP instance $I= \langle G, \V, \Gamma\rangle$ as follows. Let $C=\langle u_1,u_2, \cdots, u_r\rangle$, for some $r\geq 2$,  be a national cycle with only vertices from $V_1$. For $i\in \{1,\ldots,r-1\}$, let $D_i$ be an international cycle of length $\intv \geq 2$ intersecting with $C$ in $u_i$ only. Assume $C$, $D_1,\ldots,D_{r-1}$ are all $\Gamma$-cycles. See also Figure~\ref{fig:IRalpha}.
Note that $c_{{\tt nat}}=r$.  Every IR mechanism $\mech$ must pick $C$, so $\mbox{SW}(\mech(I))=c_{{\tt nat}}$, but ${\tt opt}(I)=(c_{{\tt nat}}-1)\cdot c_{{\tt int}}$. Hence, $\mech$ has an $\alpha$-approximation ratio with $\alpha \geq \frac{c_{{\tt nat}}-1}{c_{{\tt nat}}}\cdot c_{{\tt int}} > (1-\epsilon)c_{{\tt int}}$ for any $\epsilon>0$ if $c_{{\tt nat}}$ is chosen large enough.
\end{proof}

We now show that IC mechanisms may need to return the empty set as the $\Gamma$-cycle packing for an IKEP instance~$I$. As a consequence, IC mechanisms cannot be maximal (or efficient) either. 

\begin{proposition}\label{p-ic}
There exists no mechanism that is both nonempty and IC. 
\end{proposition}
\begin{proof}
We construct an IKEP instance $I= \langle G, \V, \Gamma\rangle$ as follows. Let $V_1=\{u_1,\ldots,u_6\}$ and $V_2=\{v_1,\ldots,v_5\}$. Let $G$ consist of two cycles $C=\langle u_1,u_2,u_3,u_4,v_1,v_2\rangle$ and $D=\langle u_1,v_3,u_5,v_4,u_6,v_5\rangle$ that both contain only vertex $u_1$. We assume $\intv=6$, $\segv=(4,2)$ and $\sv=(3,3)$, so both $C$ and $D$ are $\Gamma$-cycles. See also Figure~\ref{fig:emptyIC}.
Note that $\D_I=\{\emptyset, \{C\}, \{D\}\}$.

Let $\mech$ be a nonempty IC mechanism that selects $C$ with probability $p$ and that selects $D$ with probability $q$. As $\mech$ is nonempty, $p+q=1$. First assume $p<1$. We observe that $U_1(\mech(I))=p\cdot u_1(\{C\}) + q \cdot u_1(\{D\})=4p+3q = 4p + 3(1-p) = p+3<4$. However, if country~$1$ misreports its segment number as 
$\sv_1'=1$ (or as $\sv_1'=2$), then $\mech$ will return $C$ and country~1 has expected utility~$4$.
As $\mech$ is IC, this means that $p=1$ and thus $q=0$. We now have $U_2(\mech(I))=p\cdot u_2(\{C\}) + q \cdot u_2(\{D\}) = 2$. However, if country~$2$ misreports its segment size as $\segv_2'=1$, then $\mech$ will return $D$ and country~2 has expected utility~$3$, a contradiction.
\end{proof}

Let $I= \langle G, \V, \Gamma\rangle $ be an IKEP instance. 
The {\it international cycle degree} $d(C)$ of $C$ is the number of international $\Gamma$-cycles in $G$ that share at least one vertex with $C$.
So, the two international $\Gamma$-cycles in the proof of Proposition~\ref{p-ic} both have international cycle degree~$2$, as each of them shares a vertex with itself and the other one. We let $d^*$ be the maximum international cycle degree over all international $\Gamma$-cycles of $G$. 
We can now show a lower bound for the approximation ratio of IC mechanisms.

\begin{theorem}\label{t-alpha2}
No IC mechanism can provide an $\alpha$-approximation ratio with $\alpha \leq (1-\epsilon)d^*$, for any $\epsilon>0$.
\end{theorem}

\begin{proof}
We construct an IKEP instance $I= \langle G, \V, \Gamma\rangle$ as follows. Let $\N=\{1,\ldots,n+1\}$.
Let $L$ be an arbitrarily large integer. Let $\intv=1+L+2(n-1)=L-1+2n$; $\segv=\{L\}^{n+1}$; and $\sv=\{2\}^{n+1}$.

Let $G$ consist of $n$ international $\Gamma$-cycles $C_1,\ldots,C_n$, which all have exactly one vertex~$x\in V_{n+1}$ in common.
Cycle $C_1$ consists of $x$, followed by $L$ consecutive vertices from country~$1$, followed by an $(n-1)$-sequence of one vertex from countries $2,\ldots,n$, respectively, followed by another $(n-1)$-sequence of one vertex from countries $2,\ldots,n$, respectively. For $i\in \{2,\ldots,n\}$, cycle $C_i$ is constructed in the same way except that every vertex of country~$1$ is replaced by a vertex from country~$i$, and vice versa. So, each $C_i$ has length $1+L+2(n-1)$. See also Figure~\ref{f-alpha2}.
We note that $d^*=n$, and moreover that each $C_i$ is indeed a $\Gamma$-cycle. Hence, $\D_I=\{\emptyset,\{C_1\},\dots,\{C_n\}\}$.

Consider an arbitrary mechanism $\mech$ with probability distribution $p$ on $\D_I$. For $i\in \{1,\ldots,n\}$, let $p_i=p(\{C_1\})$. 
We may assume without loss of generality that $p_1 \leq \frac{1}{n}$.
This means that the expected utility for country~1 is at most 
$$p_1L+(1-p_1)\cdot 2=p_1(L-2)+2 \leq \frac{L-2}{n}+2 = \frac{L-2+2n}{n},$$
where the last inequality follows from the fact that $L$ is large, so $L>2$ holds. Now suppose country~1 misreports its segment number as $\sv_1'= 1$. Let $\Gamma'$ be the new set of country-specific parameters. Now $C_1$ is the only $\Gamma'$-cycle, as $C_2,\ldots,C_n$ all have two $V_1$-segments. Let $q$ be the probability that $C_1$ is selected by $\mech$ for $I'= \langle G, \V, \Gamma'\rangle$.  To ensure IC, we must have $qL \leq \frac{L-2+2n}{n}$, so $q \leq \frac{L-2+2n}{Ln}$. Hence, $\mech$ has an $\alpha$-approximation ratio with 
$$\alpha \geq \frac{{\tt opt}(I')}{\mbox{SW}(\mech(I'))} = \frac{|C_1|}{q|C_1|} = \frac{1}{q} \geq \frac{Ln}{L-2+2n} = \frac{n}{\frac{2n-2}{L} + 1}>(1-\epsilon)d^*,$$
for any $\epsilon>0$ if $L > > n$ is chosen large enough.
\end{proof}

