\subsection{Proofs of the Lemmas in Table~\ref{tab:dicho}}\label{app:Lems}


We first recall the problem that we are going to show is \NP-complete for various sets of country-specific parameters $\Gamma$.

\decisionprob{{\sc Perfect $\Gamma$-Cycle Packing}}{an $n$-partitioned graph $(G,\V)$.}{does $G$ have a perfect $\Gamma$-cycle packing?}


\noindent
We next establish that {\sc Perfect $\Gamma$-Cycle Packing} is a member of \NP.

\begin{lemma}\label{lem:member}
     {\sc Perfect $\Gamma$-Cycle Packing} is in \NP. 
\end{lemma}

\begin{proof}
    Consider an arbitrary instance of {\sc Perfect $\Gamma$-Cycle Packing} and a certificate  $\mathcal{C}$. We can verify if $\C$ is indeed a perfect $\Gamma$-cycle packing by checking in polynomial time if each $v \in V$ appears exactly once in $\C$ and if each $C\in \C$ is a $\Gamma$-cycle.
\end{proof}

\noindent
 We now recall the two \NP-complete problems from which we will reduce. The first is {\sc Perfect $3$-Dimensional Matching} ({\sc P3DM})~\cite{karp1972}. 



\decisionprob{{\sc Perfect $3$-Dimensional Matching} ({\sc P3DM})}{three sets of elements $X, Y,$ $Z$ and a set of triples $T\subseteq X \times Y \times Z$.  }{is there a perfect matching $M \subseteq T$ such that for each $u\in X \cup Y \cup Z$, there exists exactly one $t \in M$ with $u \in t$? }


\noindent
The second is {\sc Perfect $4$-Dimensional Matching} ({\sc P4DM}). Recall that a simple reduction from {\sc P3DM} shows that {\sc P4DM} is also \NP-complete. 


\noindent
\decisionprob{{\sc Perfect $4$-Dimensional Matching} ({\sc P4DM})}{four sets of elements $W,X, Y, Z$ and a set of quadruples $T\subseteq W\times X \times Y \times Z$.  }{is there a perfect matching $M \subseteq T$ such that for each $u\in W \cup X \cup Y \cup Z$, there exists exactly one $t \in M$ with
$u \in t$? }



Given an $n$-partitioned graph $(G,\V)$ and a tuple $\Gamma$ of country-specific parameters, we let $\gcyc$ denote the set of $\Gamma$-cycles in $(G,\V)$.  We are now ready to prove the lemmas from Table~\ref{tab:dicho}.

\begin{lemma}\label{lem:n=2l=2k=inftyAnycs}
For a set of country-specific parameters $\Gamma= (n, \emph{\intv}, \emph{\natv},\emph{\segv}, \emph{\sv})$ with 
$n \geq 2$,  
$\emph{\intv}=2$, 
$\emph{\sv}_i \in \mathbb{N}_{\geq 1}\cup\{\infty\}$ for all $i\in \N$,
$\emph{\segv}_i\in \mathbb{N}_{\geq 1}\cup\{\infty\}$  for all $i\in \N$,
$\emph{\natv}_j \in \mathbb{N}_{\geq 3}\cup\{\infty\}$ some $j\in\N$, and
$\emph{\segv}_i\in \mathbb{N}_{\geq 0}\cup\{\infty\}$ for all $i\in \N\setminus \{j\}$,
{\sc Perfect $\Gamma$-Cycle Packing} is \NP-complete.
\end{lemma}
\begin{proof}
