\[
\begin{array}{l}
\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle,  
\langle x, x_{i,1}^{m+1} \rangle, 
\langle y, y_{i,1}^{m-1}, y_{i,1}^m \rangle, 
\langle z, z_{i,1}^{m+1} \rangle, 
\langle w_{i,1}^0, x_{i,1}^1, x_{i,1}^2, y_{i,1}^0, z_{i,1}^1, z_{i,1}^2 \rangle, 
\langle w_{i,3}^{m}, w_{i,2}^{m} \rangle, \\
\langle w_{i,1}^q, w_{i,2}^{q}, w_{i,3}^{q} \rangle, 
\langle x_{i,3}^{1}, x_{i,2}^{1} \rangle, 
\langle x_{i,1}^p, x_{i,2}^{p},
x_{i,3}^{p} \rangle,
\langle y_{i,3}^{m}, y_{i,2}^{m} \rangle, 
\langle y_{i,1}^q, y_{i,2}^{q}, y_{i,3}^{q} \rangle 
\langle z_{i,3}^{1}, z_{i,2}^{1} \rangle, 
\langle z_{i,1}^p, z_{i,2}^{p},
z_{i,3}^{p} \rangle\in C, 
\end{array}
\]
for $ q \in \{1,\ldots, m-2\} \text{ and } p \in \{3, \ldots, m\}$. Thus, all the nodes within the gadget are covered by some $\Gamma$-cycle.  If a quadruple $t_i=(w,x,y,z)$ is not chosen in $M$, then the following cycles are added to $\C$:
\[
\begin{array}{c}
\langle w_{i,1}^0, w_{i,1}^1, \cdots, w_{i,1}^{m-1} \rangle, 
\langle x_{i,1}^2, \cdots, x_{i,1}^m, x_{i,1}^{m+1} \rangle, 
\langle y_{i,1}^0, y_{i,1}^1, \cdots, y_{i,1}^{m-1} \rangle,  
\langle z_{i,1}^2, \cdots, z_{i,1}^m, z_{i,1}^{m+1} \rangle, 
\langle w_{i,3}^{q}, w_{i,2}^q \rangle, \\
\langle w_{i,1}^m, w_{i,2}^{m}, w_{i,3}^{m} \rangle, 
\langle x_{i,3}^{p}, x_{i,2}^{p} \rangle, 
\langle x_{i,1}^1, x_{i,2}^{1},
x_{i,3}^{1} \rangle,
\langle y_{i,3}^{q}, y_{i,2}^{q} \rangle, 
\langle y_{i,1}^m y_{i,2}^{m}, y_{i,3}^{m} \rangle 
\langle z_{i,3}^{p}, z_{i,2}^{p} \rangle, 
\langle z_{i,1}^1, z_{i,2}^{1},
z_{i,3}^{1} \rangle\in \C,
\end{array}
\]
 for $ q \in \{1,\ldots, m-2\} \text{ and } p \in \{3, \ldots, m\}$. In this second case, observe that all of the gadget's vertices have been selected in some cycle, apart from $w$, $x$, $y$, and $z$.  As $M$ is a perfect matching, every vertex $u \in W\cup X \cup Y\cup Z$ will be covered by some gadget exactly once. Therefore, all vertices are covered by a cycle in $\gcyc$ and instance $\J$ has a perfect $\Gamma$-cycle packing.


Conversely, suppose there is a perfect $\Gamma$-cycle packing $\C$ of instance $\J$. We construct a perfect matching $M$ in {\sc P4DM} instance $\I$ as follows. First, recall that no $\Gamma$-cycle contains edges from different gadgets. Hence, each cycle in $\C$ belongs to a single gadget, and we argue about the cycles of gadget $t_i$ that are selected in perfect $\Gamma$-cycle packing $\C$ via the following two cases:
\begin{enumerate}
    \item Suppose $\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle\in \C$. It is clear that $\langle w_{i,3}^{m}, w_{i,2}^m\rangle\in \C$ and $\langle  w_{i,1}^q, w_{i,2}^q, w_{i,3}^{q}\rangle\in \C$ must be selected in the perfect $\Gamma$-cycle packing $\C$ for each $q\in[1, m-2]$. For $w_{i,1}^0$ to be  covered, then $\langle w_{i,1}^0, x_{i,1}^1, x_{i,1}^2, y_{i,1}^0, z_{i,1}^1, z_{i,1}^2 \rangle\in \C$ and thus,  $\langle x_{i,3}^{1}, x_{i,2}^{1}\rangle, \langle z_{i,3}, z_{i,2}^{1}\rangle\in \C$. 
    In turn, $\langle x_{i,1}^q, x_{i,2}^{q}, x_{i,3}^{q}\rangle$, $\langle y_{i,1}^p, y_{i,2}^{p}, y_{i,3}^{p}\rangle$, $ \langle z_{i,1}^q, z_{i,2}^{q}, z_{i,3}^{q}\rangle, \in \C$ for vertices $x_{i,1}^p, y_{i,1}^q, z_{i,1}^p$ to be covered, for $q\in[1, m-2]$ and $p\in [3,m]$. 
    Then, for $x_{i,1}^{m+1}$, $y_{i,1}^{m-1}$, and $z_{i,1}^{m+1}$ to be covered, $\langle x, x_{i,1}^{m+1} \rangle, \langle y, y_{i,1}^{m-1}, y_{i,1}^m \rangle, \langle z, z_{i,1}^{m+1} \rangle \in \C$. Finally $\langle y_{i,3}^{m}, y_{i,2}^{m}\rangle\in \C$. Therefore, any perfect $\Gamma$-cycle packing $\C$ containing $\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle$  must lead to $w,x,y,$ and $z$ must all be selected by the gadget corresponding to $t_i$. 



    \item Suppose $\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle\notin \C$. Then for $w_{i,1}^{m}$ to be selected, $\langle w_{i,1}^m, w_{i,2}^m,w_{i,3}^{m}\rangle\in\C$. Similarly, for $w_{i,1}^{m-1}$ to be selected, $\langle w_{i,1}^0, w_{i,1}^1, \cdots, w_{i,1}^{m-1} \rangle\in \C$, and then $\langle w_{i,2}^q,w_{i,3}^{q}\rangle\in\C$ for $q\in [1,m-2]$ such that there are no vertices connected to a $w$ vertex that is left uncovered. 
    As $w_{i,1}^0$ has already been selected, $\C$ must contain $\langle x_{i,1}^1, x_{i,2}^{1}, x_{i,3}^{1} \rangle, \langle z_{i,1}^1, z_{i,2}^{1}, z_{i,3}^{1} \rangle\in \C$ to cover $z_{i,1}^{1}$ and $x_{i,1}^{1}$. Moreover, to cover $y_{i,1}^0$,  $x_{i,1}^2$ and $z_{i,1}^2$,  the following cycles must be selected $\langle x_{i,1}^2, \cdots, x_{i,1}^m, x_{i,1}^{m+1} \rangle, \langle y_{i,1}^0, y_{i,1}^1, \cdots, y_{i,1}^{m-1} \rangle$, $\langle z_{i,1}^2, \cdots, z_{i,1}^m, z_{i,1}^m \rangle\in \C$. In turn, $\langle x_{i,2}^p, x_{i,3}^p\rangle, \langle y_{i,2}^q, y_{i,3}^{q} \rangle, \langle z_{i,2}^{p}, z_{i,3}^{p}\rangle \in \C$, to ensure that the remaining vertices connected to the middle cycles are selected, for $q\in [1,m-2]$ and $p\in [3,m]$. Finally, $\langle y_{i,1}^m,y_{i,2}^{m}, y_{i,3}^{m}\rangle$ must be selected in $\C$. 
    Therefore, we see that when $\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle\notin \C$ and vertex $w$ is not covered by the gadget corresponding to $t_i$, then none of the vertices $w,x,y$, and $z$ are covered by $t_i$. 
\end{enumerate}




Therefore, for each $t_i \in T$ it must be the case that either:
\[
\begin{array}{c}\{
\langle w, w_{i,1}^{m-1}, w_{i,1}^m \rangle,  
\langle x, x_{i,1}^{m+1} \rangle, 
\langle y, y_{i,1}^{m-1}, y_{i,1}^m \rangle, 
\langle z, z_{i,1}^{m+1} \rangle, 
\langle w_{i,1}^0, x_{i,1}^1, x_{i,1}^2, y_{i,1}^0, z_{i,1}^1, z_{i,1}^2 \rangle, 
\langle w_{i,3}^{m}, w_{i,2}^{m} \rangle,\\
\langle w_{i,1}^q, w_{i,2}^{q}, w_{i,3}^{q} \rangle,
\langle x_{i,3}^{1}, x_{i,2}^{1} \rangle, 
\langle x_{i,1}^p, x_{i,2}^{p},
x_{i,3}^{p} \rangle,
\langle y_{i,3}^{m}, y_{i,2}^{m} \rangle, 
\langle y_{i,1}^q, y_{i,2}^{q}, y_{i,3}^{q} \rangle 
\langle z_{i,3}^{1}, z_{i,2}^{1} \rangle, 
\langle z_{i,1}^p, z_{i,2}^{p},
z_{i,3}^{p} \rangle
\}\subseteq \C\\
\end{array}\]
 \[\begin{array}{c}\{\text{or }\{\langle w_{i,1}^0, w_{i,1}^1, {\ldots}, w_{i,1}^{m-1} \rangle, 
\langle x_{i,1}^2, {\ldots}, x_{i,1}^m, x_{i,1}^{m+1} \rangle, 
\langle y_{i,1}^0, y_{i,1}^1, {\ldots}, y_{i,1}^{m-1} \rangle,  
\langle z_{i,1}^2, {\ldots}, z_{i,1}^m, z_{i,1}^{m+1} \rangle, 
\langle w_{i,3}^{q}, w_{i,2}^q \rangle,\\ 
\langle w_{i,1}^m, w_{i,2}^{m}, w_{i,3}^{m} \rangle, 
\langle x_{i,3}^{p}, x_{i,2}^{p} \rangle, 
\langle x_{i,1}^1, x_{i,2}^{1},
x_{i,3}^{1} \rangle,
\langle y_{i,3}^{q}, y_{i,2}^{q} \rangle, 
\langle y_{i,1}^m y_{i,2}^{m}, y_{i,3}^{m} \rangle 
\langle z_{i,3}^{p}, z_{i,2}^{p} \rangle, 
\langle z_{i,1}^1, z_{i,2}^{1},
z_{i,3}^{1} \rangle
\} \subseteq \C.
\end{array}
\]
In the former case, we add $t_i$ to $M$. Finally, $M$ is a perfect matching in $\I$ because $\C$ is a perfect $\Gamma$-cycle packing in $\J$, and in view of points~$(1)$ and ~$(2)$ above.


Therefore, {\sc Perfect $\Gamma$-Cycle Packing} is \NP-complete when $n \geq 2$,  $\intv=\infty$,  for all $i\in\N$, $\natv_i\in \mathbb{N}_{\geq 0}\cup\{\infty\},    \sv_i\in \mathbb{N}_{\geq 2}\cup\{\infty\}$, $\sv=\{\infty\}^n$, and for some $j \in \N$ $\segv_j\in \mathbb{N}_{\geq 2}\cup\{\infty\}$ with the remaining $j'\in\N\backslash\{j\}$ with $\segv_j\in \mathbb{N}_{\geq 1}\cup\{\infty\}$. 
\end{proof}

\begin{lemma}\label{lem:l=inftyc=inftys=1,infty}
    For a set of country-specific parameters $\Gamma= (n, \emph{\intv}, \emph{\natv},\emph{\segv}, \emph{\sv})$ with 
    $n \geq 2$,  
    $\emph{\intv}=\infty$, 
    $\emph{\natv}_i \in \mathbb{N}_{\geq 0}\cup\{\infty\}$ for all $i\in\N$,
    $\emph{\sv}_j\in \mathbb{N}$ for some $j\in \N$, and 
    $\emph{\sv}_i\in\mathbb{N}_{\geq 1}\cup\{\infty\}$ for all $i\in \N\backslash\{j\}$,
    $\emph{\segv}_i=\infty$ for all $i\in \N$,
    {\sc Perfect $\Gamma$-Cycle Packing} is \NP-complete.
\end{lemma}


\begin{proof}
