	\arrow["{t_A}", from=1-1, to=1-2]
	\arrow["{\eta_A}", from=1-2, to=1-3]
\end{tikzcd}\]
with $\T(A) \in \tort$ and $\F(A) \in \torf$.
\end{itemize}
\end{defi}

As proved in [\cite{Facchini2}, Proposition 3.1], such a $\zeros$-exact sequence is unique up to isomorphisms.

