    \[\begin{tikzcd}
    	D & C \\
    	A & B
    	\arrow["g", from=1-1, to=1-2]
    	\arrow["q"', shift right, from=1-1, to=2-1]
    	\arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
    	\arrow["p"', shift right, from=1-2, to=2-2]
    	\arrow["t"', shift right, from=2-1, to=1-1]
