\] The following is an elementary property.
\end{nothing}

\begin{lem}
\label{etilde}
    Let \( G \) be a group. For a normal subgroup \( K \) of \( G \) contained in the Frattini subgroup of \( G \), and \( \kappa \in K^* \), we have
    \begin{equation}
        \label{tildetimesipot}
        \tildeeKk = \widetilde{e_G^G}\cdot e_{(K,\kappa)}^G = e_{(K,\kappa)}^G \cdot\widetilde{e_G^G}.
    \end{equation}
