\begin{proof}
    By expanding $\widetilde{e_G^G}$ the product can be written as 
    \begin{eqnarray*}
        \tildeeKk = \widetilde{e_G^G} \frac{1}{|G|}\sum_{\substack{X\leq G}}|X|\mu(X,G) \Big [ \frac{G\times G}{\Delta_K(G),\phi_{\kappa}}\Big] \Big [ \frac{G\times G}{\Delta(X),1}\Big]
    \\
        = \widetilde{e_G^G} \frac{1}{|G|}\sum_{X\leq G}|X|\mu(X,G) \Big [ \frac{G\times G}{\Delta_K(G) * \Delta(X),\phi_{\kappa}}\Big].
