    \begin{enumerate}[(a)]
    \item  \begin{align*}
        \varphi_{K,\kappa}^G = \widetilde{e_G^G}\left(\sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G} (K,L) e_{(L,\lambda)}^G\right) \\
        = \left(\sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G} (K,L) e_{(L,\lambda)}^G\right)\widetilde{e_G^G}.
    \end{align*}
    \item In particular
    \begin{equation}
        \label{varphiexplicitly}
        \varphi_{K,\kappa}^G = \frac{1}{|G|}\sum_{\substack{\Phi(G) \leq X\leq G\\ (K,\kappa)\leq (L,\lambda)\in \calM_{\Phi(G)}^G}} |X| \mu(X,G)\mu_{\unlhd G} (K,L) \Ind_X^G e_{(L,\lambda)}^X \Res_X^G.
    \end{equation}
    Here $e_{(L,\lambda)}^X$ denotes the idempotent $\Res^G_Xe_{(L,\lambda)}^G\Ind_X^G$.
    \item Let $f:G\rightarrow H$ be a group isomorphism. Then
    \[
      \varphi_{K,\kappa}^G \Iso(f) = \Iso(f) \varphi_{f(K),\kappa \circ f^{-1} }^H. 
    \]
    \item Let $p$ be a prime number. Suppose that $P$ is a finite $p$-group and $(K, \kappa)\in\calM_P^*$. Then
    \[
        \varphi_{K,\kappa}^P = \widetilde{e_P^P} \left( \sum_{\substack{(K,\kappa) \leq (L,\lambda) \in \calM_{\Phi(P)}^{P} \\ L/K \leq \Omega_1 Z(P/K)}} \mu(1, L/K)\, e_{(L,\lambda)}^P \right),
    \]
    where $\Omega_1 Z(P/K)$ denotes the largest elementary abelian central subgroup of $P/K$, and $\mu$ is the Möbius function of the poset of subgroups of $L/K$.
    \end{enumerate}
\end{prop}

\begin{proof} (a) Follows directly from Lemma \ref{etilde}.

\smallskip

\noindent (b) Note that $\mu(X,G) = 0$ unless $X\geq \Phi(G)$. In this case, $X\geq \Phi(G)\geq L$, and in particular $L\leq X$. Then 
    \[
        \Big [ \frac{G\times G}{\Delta(X),1}\Big] e_{(L,\lambda)}^G =   \Big [ \frac{G\times G}{\Delta_L(X), \phi_{\lambda}}\Big] = \Ind_X^G e_{(L,\lambda)}^X\Res_X^G.
    \]

\smallskip

\noindent (c)  To prove this assertion we calculate
    \[
        \Iso(f)\varphi_{K,\kappa}^G \Iso(f^{-1}).
    \]
    Expanding the product and the following calculations give the result as follows.
    \begin{eqnarray*}
        & &\Iso(f)\varphi_{K,\kappa}^G \Iso(f^{-1})=\\
        &=&\Iso(f)\widetilde{e_G^G}\Iso(f^{-1})\Iso(f) \sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(K,L) e_{(L,\lambda)}^G \Iso(f^{-1}) \\
        &=& \widetilde{e_H^H} \sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(K,L) \Iso(f) e_{(L,\lambda)}^G \Iso(f^{-1}) \\
        &=& \widetilde{e_H^H} \sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(K,L)e_{(f(L),\lambda \circ f^{-1})}^H \\
        &=& \widetilde{e_H^H} \sum_{(K,\kappa)\leq  (L,\lambda)\in \calM_{\Phi(G)}^G} \mu_{\unlhd H}(f(K),f(L))e_{(f(L),\lambda \circ f^{-1})}^H \\
        &=& \varphi_{f(K),\kappa \circ f^{-1}}^H
    \end{eqnarray*}
\smallskip
\noindent (d)  Note that if $\kappa \in K^*$ is a faithful character, then $K$ is a central and cyclic subgroup of $P$. Moreover, we have
    \[
        \mu_{\unlhd P}(K,L) = \mu_{\unlhd P/K}(1,L/K).
    \]
    By the argument in \cite[Lemma 6.2.10]{biset functor}, it follows that $\mu_{\unlhd P/K}(1,L/K) = 0$ unless $L/K$ is a central elementary abelian subgroup of $P/K$. In this case, we also have
    \[
        \mu_{\unlhd P/K}(1,L/K) = \mu(1,L/K)= (-1)^r p^{\binom{r}{2}},
    \]
  where $r = \operatorname{rank}(L/K)$.
\end{proof}

\begin{coro}
\label{elementarytimesphi}
Let $G$ be a finite group, and $(K,\kappa)\in \calM_{\Phi(G)}^G$. Then
    \begin{enumerate} [a)]
        \item $\Res_H^G \varphi_{K,\kappa}^G = 0$ and $\varphi_{K,\kappa}^G \Ind_H^G = 0$ for all proper subgroups $H$ of $G$.
        \item $\Def_{G/M}^G \varphi_{K,\kappa}^G = 0$ and $\varphi_{K,\kappa}^G\Inf_{G/M}^G = 0$ whenever $M\cap \Phi(G) \not \leq K$ or $M\cap K\not \leq \ker \kappa$.
%        \item \Large\textbf{We need to find additional results here!}
    \end{enumerate}
\end{coro}
\begin{proof} We follow Bouc's proof of \cite[Corollary 3.7]{double}. (a) This follows directly from Section \ref{elemopontilde}.

\smallskip

\noindent (b) By transitivity of deflation, we can write:
        \[
        \Def_{G/M}^G = \Def_{G/M}^{G/(M\cap \Phi(G))} \Def_{G/(M\cap \Phi(G))}^G.
        \]
        Thus, it suffices to show that $\Def_{G/(M\cap \Phi(G))}^G \varphi_{K,\kappa}^G = 0$. Assuming now that $M \leq \Phi(G)$, we compute:
        \begin{eqnarray*}
            \Def_{G/M}^G \varphi_{K,\kappa}^G &=& \Def_{G/M}^G \left(\sum_{\substack{(K,\kappa)\leq (L,\lambda)\in \calM_{\Phi(G)}^G}} \mu_{\unlhd G} (K,L) e_{(L,\lambda)}^G  \right)\widetilde{e_G^G} \\
            &=& \left(\sum_{\substack{(K,\kappa)\leq (L,\lambda)\in \calM_{\Phi(G)}^G}} \mu_{\unlhd G} (K,L) \Big ( \Def_{G/M}^G e_{(L,\lambda)}^G \Big ) \right)\widetilde{e_G^G}.
        \end{eqnarray*}

        If $M\cap K \not\leq \widehat{K}$, then by the poset structure on $\calM_{\Phi(G)}^G$, we have $M\cap L \not\leq \widehat{L}$ for all $(L,\lambda) \geq (K,\kappa)$. Consequently, all terms in the sum vanish. Now suppose instead that $M\cap K \leq \widehat{K}$, in which case some terms might be nonzero. Then we rewrite:
        \begin{eqnarray*}
            & &\Def_{G/M}^G \varphi_{K,\kappa}^G=\\
            &=& \left(\sum_{\substack{(K,\kappa)\leq (L,\lambda)\in \calM_{\Phi(G)}^{G}\\ L\cap M\leq \widehat{L}}} \mu_{\unlhd G} (K,L) e_{(LM/M,\bar{\lambda})}^{G/M}  \Def_{G/M}^G  \right)\widetilde{e_G^G} \\
            &=& \sum_{\substack{(KM,\kappa') \leq (T,\tau) \in \calM_{\Phi(G)}^G\\ M\leq \widehat{T}}}
            \left(\sum_{\substack{(K,\kappa)\leq (L,\lambda)\in \calM_{\Phi(G)}^G\\ LM=T}} \mu_{\unlhd G} (K,L) \right) e_{(T/M,\bar{\tau})}^{G/M}\Def_{G/M}^G\widetilde{e_G^G}.
        \end{eqnarray*}
        Here, we define $\kappa' \colon KM \to \CC^{\times}$ by $\kappa'(km) = \kappa(k)$. By construction, we also have $\tau|_L = \lambda$, ensuring that for each $L \geq K$ such that $LM = T$, there exists a unique $\lambda$. Finally, the coefficient of $e_{(T/M,\bar{\tau})}^{G/M}$ in the above expression is zero unless $KM = K$, which is equivalent to $M \leq K$ by the properties of the Möbius function. This concludes the proof.
\end{proof}


\begin{theorem}
\label{phiortogonal} 
The set of elements $\{\varphi_{K, \kappa}^G \}$, indexed by $\calM_{\Phi(G)}^{G}$, forms a complete set of orthogonal idempotents in the algebra $\calE(G)$. That is, 

\begin{enumerate}
    \item   $\varphi_{K,\kappa}^G \cdot \varphi_{L,\lambda}^G = \delta_{(K,\kappa), (L,\lambda)}
                \varphi_{K,\kappa}^G$
    \item $\sum_{(K,\kappa)}\varphi_{K,\kappa}^G = \tildeeG$
\end{enumerate} 
\end{theorem}

\begin{proof} %Observe that $e_{(1,1)} = 1 \in B_k^{\CC^{\times}}(G, G)$. 
Utilizing the results established in Section~\ref{eKtimeseL} and Lemma~\ref{etilde}, we evaluate the following expression:
        \begin{equation} \label{Ydeltaproduct}
            \tildeeKk\cdot \widetilde{e_{(L,\lambda)}^G} = \widetilde{e_{G}^G} \cdot e_{(K,\kappa)}^G \cdot e_{(L,\lambda)}^G \cdot \widetilde{e_G^G} = \begin{cases}
               \widetilde{e_{(KL,\kappa\lambda)}^G}, & \text{if } \kappa\mid_{K\cap L} = \lambda\mid_{K\cap L},\\ 0, & \text{otherwise}.
            \end{cases}
        \end{equation}
       Then by Möbius inversion, it follows that
        \begin{equation} \label{Ydeltaassumphi}
            \tildeeKk = \sum_{(K,\kappa) \leq (L,\lambda) \in \calM_{\Phi(G)}^G} \varphi_{L,\lambda}^G.
        \end{equation}
        Additionally, by setting $(K,\kappa) = (1,1)$ in (\ref{Ydeltaassumphi}), we obtain
        \begin{equation*}
            \widetilde{e_G^G} = \sum_{(L,\lambda) \in \calM_{\Phi(G)}^G} \varphi_{L,\lambda}^G.
        \end{equation*}
        The proof proceeds by showing that for all $(K,\kappa), (L,\lambda) \in \calM_{\Phi(G)}^G$,
        \begin{equation}
        \label{Ytimesphi}
            \tildeeKk\cdot \varphi_{L,\lambda}^G = \varphi_{L,\lambda}^G \cdot \tildeeKk = \begin{cases}
                \varphi_{L,\lambda}^G, & \text{if } (K,\kappa) \leq (L,\lambda),\\
                0, & \text{otherwise},
            \end{cases}
        \end{equation}
        and
        \begin{equation*}
            \varphi_{K,\kappa}^G \cdot \varphi_{L,\lambda}^G = \begin{cases}
                \varphi_{K,\kappa}^G, & \text{if } (K,\kappa) = (L,\lambda),\\
                0, & \text{otherwise}.
            \end{cases}
        \end{equation*}
        The details follow arguments similar to those in \cite[Proposition 4.4]{fibered biset}. First, observe that if $(K,\kappa) \leq (L,\lambda)$, then
\begin{eqnarray*}
    \tildeeKk \cdot \varphi_{L,\lambda}^G &=& \tildeeKk \left(\sum_{(L,\lambda)\leq (N,\eta)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(L,N) \widetilde{e_{(N,\eta)}^G}\right)\\
    &=& \sum_{(L,\lambda)\leq (N,\eta)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(L,N) \tildeeKk \cdot \widetilde{e_{(N,\eta)}^G}\\
    &=& \sum_{(L,\lambda)\leq (N,\eta)\in \calM_{\Phi(G)}^G} \mu_{\unlhd G}(L,N) \widetilde{e_{(N,\eta)}^G} = \varphi_{L,\lambda}^G
\end{eqnarray*}
by equation (\ref{Ydeltaproduct}). Additionally, note that $\tildeeKk$ and $\varphi_{L,\lambda}^G$ commute since $\tildeeKk$ and $\widetilde{e_{(N,\eta)}^G}$ commute for all $(N,\eta) \geq (L,\lambda)$. Next, we establish the remaining statement of the proposition using induction on $d := d(K,\kappa) + d(L,\lambda)$, where $d(K,\kappa)$ is defined as the maximum $n \in \mathbb{N}_0$ such that there exists a chain $(K,\kappa) = (K_0,\kappa_0) < \cdots < (K_n,\kappa_n)$ in $\calM_{\Phi(G)}^G$. If $d = 0$, then $(K,\kappa)$ and $(L,\lambda)$ are maximal in $\calM_{\Phi(G)}^G$. Consequently, we have $\varphi_{K,\kappa}^G = \tildeeKk$ and $\varphi_{L,\lambda}^G = \widetilde{e_{(L,\lambda)}^G}$. It remains to demonstrate that $\tildeeKk \cdot \widetilde{e_{(L,\lambda)}^G} = 0$ for $(K,\kappa) \neq (L,\lambda)$. Assuming otherwise, equation (\ref{Ydeltaproduct}) implies that $\kappa\mid_{K\cap L} = \lambda\mid_{K\cap L}$ and that there exists a pair $(KL,\kappa\lambda) \in \calM_{\Phi(G)}^G$ with $(K,\kappa) \leq (KL,\kappa\lambda) \geq (L,\lambda)$. Given that $(K,\kappa)$ and $(L,\lambda)$ are maximal in $\calM_{\Phi(G)}^G$, we deduce $(K,\kappa) = (KL,\kappa\lambda) = (L,\lambda)$. Now, suppose $d > 0$ and that the proposition holds for smaller values of $d$. We first establish that if $\varphi_{K,\kappa}^G \varphi_{L,\lambda}^G \neq 0$, then $(K,\kappa) = (L,\lambda)$. Indeed, expanding $\varphi_{K,\kappa}^G$ and $\varphi_{L,\lambda}^G$ according to equation (\ref{phiKkappa}) and using equation (\ref{Ydeltaproduct}) yields:
\begin{equation*}
    \varphi_{K,\kappa}^G \cdot \varphi_{L,\lambda}^G \in \bigoplus_{(KL,\kappa\lambda) \leq (M,\mu) \in \calM_{\Phi(G)}^G}\widetilde{e_{(M,\mu)}^G}.
\end{equation*}
This implies that $\widetilde{e^G_{(KL,\kappa\lambda)}}\cdot \varphi_{K,\kappa}^G\cdot \varphi_{L,\lambda}^G = \varphi_{K,\kappa}^G\cdot \varphi_{L,\lambda}^G$ by equation (\ref{Ydeltaproduct}). Assuming $(K,\kappa) \neq (L,\lambda)$, we have $(K,\kappa) < (K L, \kappa \lambda)$ or $(L,\lambda) < (K L, \kappa \lambda)$. By induction, we obtain either $\widetilde{e_{(KL,\kappa\lambda)}^G}\cdot \varphi_{K,\kappa}^G = 0$ or $\widetilde{e_{KL,\kappa\lambda}^G}\cdot \varphi_{L,\lambda}^G = 0$. In either case, we reach a contradiction, concluding that $(K,\kappa) = (L,\lambda)$. Next, assuming $(K,\kappa) = (L,\lambda)$, we use induction and the previous result to conclude:
\begin{equation*}
    \tildeeKk = (\tildeeKk)^2 = \left( \sum_{(K,\kappa) \leq (K',\kappa') \in \calM_{\Phi(G)}^G} \varphi_{K',\kappa'}^G \right)^2.
\end{equation*}
Expanding this sum and comparing it with equation (\ref{Ydeltaassumphi}) yields $\varphi_{K,\kappa}^G \cdot\varphi_{K,\kappa}^G = \varphi_{K,\kappa}^G$, proving idempotency. Finally, from equation (\ref{Ydeltaassumphi}), we derive:
\begin{equation*}
    \tildeeKk\cdot \varphi_{L,\lambda}^G = \sum_{(K,\kappa) \leq (K',\kappa') \in \calM_{\Phi(G)}^G} \varphi_{K',\kappa'}^G\cdot \varphi_{L,\lambda}^G.
\end{equation*}
Using induction and previously established results, the sum evaluates to $\varphi_{L,\lambda}^G$ if $(K,\kappa) \leq (L,\lambda)$ and 0 otherwise.
\end{proof}

\begin{theorem}\label{phiortogonal2}
Let $(K,\kappa)\in \calM_{\Phi(G)}^G$ and $H$ be a finite group.
        \begin{enumerate}[a)]
            \item If $(U,\upsilon) \in \calM_{G\times H}$, then $\varphi_{K,\kappa}^G \Big[ \frac{G\times H}{U,\upsilon}\Big] = 0$ unless $p_1(U) = G$ and $k_1(U)\cap \Phi(G) \leq K$ and $\kappa\mid_{k_1(U)\cap K}=\upsilon_1\mid_{k_1(U)\cap K}$.
            \item If $(U',\upsilon') \in \calM_{H\times G}$, then $\Big[ \frac{H\times G}{U',\upsilon'}\Big] \varphi_{K,\kappa}^G = 0$ unless $p_2(U') = G$ and $k_2(U')\cap \Phi(G) \leq K$ and $\kappa\mid_{k_2(U')\cap K}=\upsilon'_2\mid_{k_2(U')\cap K}$.
        \end{enumerate}

\end{theorem}

\begin{proof} We prove part (a).  Part (b) follows similarly. First, we expand the product as
\begin{eqnarray*}
\varphi_{K,\kappa}^G\left[\frac{G \times H}{U, \upsilon}\right]
& = &
\widetilde{e_G^G} \left( \sum_{(K, \kappa) \leq (L, \lambda) \in \calM_{\Phi(G)}^{G}} \mu_{\unlhd G}(K, L) \, e_{(L, \lambda)}^G \right) \left[\frac{G \times H}{U, \upsilon}\right] \\
& = &
\widetilde{e_G^G} \left( \sum_{\substack{(K, \kappa) \leq (L, \lambda) \in \calM_{\Phi(G)}^{G} \\
\lambda|_{L \cap p_1(U)} = \upsilon_1|_{L \cap p_1(U)}}}
\mu_{\unlhd G}(K, L) \left[\frac{G \times H}{(L \times 1)U, \lambda \cdot \upsilon}\right] \right),
\end{eqnarray*}
where \(\lambda \cdot \upsilon((l,1)u) := \lambda(l)\, \upsilon(u)\). Let \(M := k_1(U) \cap \Phi(G)\). We claim that
\[
(L \times 1)U = (LM \times 1)U.
\]

The inclusion \((L \times 1)U \subseteq (LM \times 1)U\) is immediate. For the reverse inclusion, let \(x \in (LM \times 1)U\), so that \(x = (lm, 1)(u_1, u_2)\) for some \(l \in L\), \(m \in M\), and \((u_1, u_2) \in U\). Since \(m \in M = k_1(U) \cap \Phi(G)\), we have \((m, 1) \in U\). Hence,
\[
x = (l, 1)(m, 1)(u_1, u_2) = (l, 1)(mu_1, u_2) \in (L \times 1)U,
\]
which establishes the claimed equality.

Assume now that the above sum is nonzero. Then there exists an element \((T, \tau)\) such that the coefficient of the basis element corresponding to \(((T \times 1)U, \tau \cdot \upsilon)\) in the sum is nonzero. Moreover, \(((T \times 1)U, \tau \cdot \upsilon)\) is of the form \(((LM \times 1)U, \lambda \cdot \upsilon)\) for some \((K, \kappa) \leq (L, \lambda) \in \calM_{\Phi(G)}^{G}\). In particular, the coefficient of the corresponding element
\[
\left[\frac{G \times H}{(T \times 1)U, \tau \cdot \upsilon}\right]
\]
in the sum is given by
\[
\sum_{\substack{(K, \kappa) \leq (L, \lambda) \in \calM_{\Phi(G)}^{G} \\ LM = T}} \mu_{\unlhd G}(K, L).
\]
Note that if \(K \leq L \unlhd \Phi(G)\) and \((LM \times 1)U = (T \times 1)U\), then there exists a unique \(\lambda \in L^*\) such that
\[
((LM \times 1)U, \lambda \cdot \upsilon) = ((T \times 1)U, \tau \cdot \upsilon),
\]
since \((\tau \cdot \upsilon)|_L = \tau|_L = \lambda\). Then by properties of the Möbius function, we have \(KM \leq K\), which implies \(M \leq K\). For the final condition, we note that it arises from the Mackey formula for the product of fibered bisets. To establish the result, it suffices to show that if
\begin{equation*}
    \kappa\mid_{k_1(U)\cap K} \neq \upsilon_1\mid_{k_1(U)\cap K},
\end{equation*}
then for any pair $(K,\kappa) \leq (L,\lambda) \in \calM_{\Phi(G)}^G$, we have
\begin{equation*}
    \lambda\mid_{k_1(U)\cap L} \neq \upsilon_1\mid_{k_1(U)\cap L}.
\end{equation*}
Consequently, all terms in the sum vanish, implying that the product is zero. To see why this holds, assume there exists a pair $(L,\lambda)$ such that
\begin{equation*}
    \lambda\mid_{k_1(U)\cap L} = \upsilon_1\mid_{k_1(U)\cap L}.
\end{equation*}
By the poset structure, it follows that
\begin{equation*}
    \lambda\mid_{k_1(U)\cap K} = \kappa\mid_{k_1(U)\cap K} \neq \upsilon_1\mid_{k_1(U)\cap K}.
\end{equation*}
However, since $k_1(U) \cap K \leq k_1(U) \cap L$, we must have
\begin{equation*}
    \lambda\mid_{k_1(U)\cap K} = \upsilon_1\mid_{k_1(U)\cap K},
\end{equation*}
which contradicts our assumption. This completes the proof of part (a).
\end{proof}
\begin{remarki}
  The conditions in Theorem \ref{phiortogonal2} imply in particular that \( \widehat{k_1(U)} \cap \Phi(G) \leq \widehat{K} \) and \(\widehat{k_1(U)} \cap K \leq \widehat{K}\), where hats denote the kernels of the respective characters. This will be useful in verifying vanishing or orthogonality conditions later.
\end{remarki}
\begin{prop}
    Let $G$ be a group with order invertible in $k$ and let $(K,\kappa)\in \calM_{\Phi(G)}^G$ and 
    let $(U,\upsilon)\in \calM_{G\times G}$ such that $U$ is a covering subgroup of $G\times G$. Then
        \begin{eqnarray*}
            \varphi_{K,\kappa}^G\cdot Y_{U,\upsilon} = \sum_{\substack{(K,\kappa) \leq (L,\lambda)\in \calM_{\Phi(G)}^G\\ \lambda\mid_{L\cap k_1(U)} = \upsilon_1\mid_{L\cap k_1(U)} }} \mu_{\unlhd G}(K,L)Y_{(L\times 1)U,\lambda\cdot \upsilon},
        \end{eqnarray*}
        %where $\lambda\cdot \upsilon((l,1)u):=\lambda(l)\upsilon(u)$ for $l\in L$ and $u\in U$. 
        This product is non-zero if and only if $k_1(U)\cap \Phi(G) =K$ and $\kappa\mid_{K\cap k_1(U)} = \upsilon_1\mid_{K\cap k_1(U)}$. Similar result holds for the left multiplication.
%        \begin{equation*}
 %            Y_{U,\upsilon} \varphi_{K,\kappa}^G = \sum_{\substack{(K,\kappa) \leq (L,\lambda)\in \calM_{\Phi(G)}^G\\ \lambda\mid_{L\cap k_2(U)} = \upsilon_2\mid_{L\cap k_2(U)} }} \mu_{\unlhd G}(K,L)Y_{(1\times L)U,\lambda\cdot \upsilon},
  %      \end{equation*}
   %     and $Y_{U,\upsilon} \varphi_{K,\kappa}^G \not = 0$ if and only if $k_2(U)\cap \Phi(G) = K$ and $\upsilon_2\mid_{K\cap k_2(U)} = \kappa\mid_{K\cap k_2(U)}$.
\end{prop}
\begin{proof}
These conditions follow directly from Theorem~\ref{phiortogonal}. To demonstrate that they are sufficient for the product to be nonzero, we examine the coefficient of \( Y_{U,\upsilon} \) in the sum. Observe that \( Y_{U,\upsilon} = Y_{(L \times 1)U,\, \lambda \cdot \upsilon} \) if and only if \( (U, \upsilon) \) is conjugate to \( ((L \times 1)U,\, \lambda \cdot \upsilon) \). This implies that \( L \) is contained in the subgroup chain
    \[
        k_1((L \times \1)U) \leq k_1(U),
    \]
    leading to the relation
    \[
        K \leq L \leq k_1(U) \cap \Phi(G) \leq K,
    \]
    which forces \( L = K \). Consequently, the coefficient of \( Y_{U,\upsilon} \) in \( \varphi_{K,\kappa} Y_{U,\upsilon} \) is equal to $\1$, confirming that \( \varphi_{K,\kappa} Y_{U,\upsilon} \neq 0 \). The second claim of the first part can be established by a similar argument.
\end{proof}
\begin{coro}
    The elements $\varphi_{K,\kappa}^G Y_{U,\upsilon}$ %(resp. $Y_{U,\upsilon} \varphi_{K,\kappa}^G$), 
    as $(U,\upsilon)$ ranges over a set of representatives of the conjugacy classes of elements in $\mathcal{M}_{G \times G}$ with $U$ covering, which satisfies the conditions
\[
k_1(U) \cap \Phi(G) = K \quad \text{and} \quad \kappa|_{K \cap k_1(U)} = \upsilon_1|_{K \cap k_1(U)}
\]
%respectively
%\[
%k_2(U) \cap \Phi(G) = K \quad \text{and} \quad \kappa|_{K \cap k_2(U)} = \upsilon_1|_{K \cap k_2(U)},
%\]
form a $k$-basis of the right ideal $\varphi_{K,\kappa}^G \mathcal{E}(G)$ %(resp. the left ideal $\mathcal{E}(G) \varphi_{K,\kappa}^G$) 
of $\mathcal{E}(G)$. Similar basis exists for the corresponding left ideal.
\end{coro}
\begin{proof}
   Since the coefficient of \( Y_{U,\upsilon} \) in the product $\varphi_{K,\kappa}^G Y_{U,\upsilon}$ is equal to ${\bf 1}$  when \( k_1(U) \cap \Phi(G) = K \) and \( \kappa\big|_{K \cap k_1(U)} = \upsilon_1\big|_{K \cap k_1(U)} \), the set of elements \( \varphi_{K,\kappa}^G Y_{U,\upsilon} \) forms a \( k \)-basis of \( \varphi_{K,\kappa}^G \mathcal{E}(G) \), see Section~\ref{basis}. 
\end{proof}

\section{Idempotents of double $\CC^{\times}$-fibered Burnside algebras}
Throughout this section let $G$ be a finite group and let $k$ be  a commutative ring in which $|G|$ is invertible. In this section, we define a set of orthogonal idempotent elements in the $\CC^{\times}$-fibered Burnside algebra $B_k^{\CC^{\times}}(G,G)$ which sum to the identity element. Consequently, we demonstrate that the evaluation of a $\CC^{\times}$-fibered biset functor at $G$ decomposes as a direct sum of $k$-modules, indexed by the minimal sections $(T, S)$ of $G$ and by specific elements of the poset $\calM_{\Phi(T/S)}^{T/S}$. Here, a \emph{minimal} section $(T,S)$ of $G$ is a section with $S \unlhd \Phi(T)$.

\begin{defi} 
Let $(T,S)$ be a section of $G$ % We use the notations
%\[
%\Indinf_{T/S}^G := \Ind_T^G\Inf_{T/S}^T \quad \text{and} \quad \Defres_{T/S}^G := \Def_{T/S}^T\Res_T^G.
%\]
and let $(K,\kappa) \in \calM_{T/S}^{*}$. Define:
\begin{eqnarray*}
u_{T,S,K,\kappa}^{G} = \Indinf^G_{T/S} \varphi_{K,\kappa}^{T/S}\in B^{\CC^{\times}}_k(G,T/S),\\
v_{T,S,K,\kappa}^{G} = \varphi_{K,\kappa}^{T/S} \Defres^G_{T/S}\in B^{\CC^{\times}}_k(T/S,G).
\end{eqnarray*}
Note that 
\[
u_{T,S,K,\kappa}^{G} = (v_{T,S,K,\kappa}^{G})^{op}.
\]
These elements will be used as partial idempotents in 
$B_k^\ctimes(G,G)$, projecting onto fibered components associated to certain triples $(T/S,K,\kappa)$.
\end{defi}
%since $(\varphi_{K,\kappa}^{T/S})^{op} = \varphi_{K,\kappa}^{T/S}$ and $(\Indinf^G_{T/S})^{op} = \Defres^G_{T/S}$.
%\end{remarki}
\begin{nothing}
The group  \( \Aut(G) \) acts on %the pairs \( (K, \kappa) \in 
\(\calM_{\Phi(G)}^{G} \) via
\[
\psi \cdot (K, \kappa) = (\psi(K), \kappa \circ \psi^{-1}),
\]
where \( \psi \in \Aut(G), (K, \kappa) \in \calM_{\Phi(G)}^{G} \). Since $\Inn(G)$ acts trivially on the elements of $\calM_{\Phi(G)}^G$, the above action descents to an action of $\Out(G)$. Let 
\([K,\kappa]_{\Out(G)}\) denote the corresponding orbit. Usually we omit the index $\Out(G)$ and simply write $[K, \kappa] := [K, \kappa]_{\Out(G)}$ whenever it is clear from the context. %Specifically, this orbit consists of all pairs \( (L, \lambda) \in \calM_{\Phi(G)}^{G} \) satisfying the condition
%\[
%(L, \lambda) = (\psi(K), \kappa \circ \psi^{-1})
%\]
%for some automorphism \( \psi \in \Out(G) \).
We denote a complete set of orbit representatives of $\calM_{\Phi(G)}^G$ by $[\calM_{\Phi(G)}^G]$. Similarly we have the subset $[\calM_G^*]$ of representatives for pairs with faithful characters.
\end{nothing}

\begin{nothing}
For $(K,\kappa)\in [\calM_{\Phi(G)}^G]$, set
\[
\varphi_{[K,\kappa]}^G := \sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K',\kappa'}^G
\]
%which is an idempotent in the algebra $\calE(G)$.
and similarly for a minimal section $(T, S)$ and  $(K,\kappa)\in [\calM_{\Phi(T/S)}^{T/S}]$, set
\[
u_{T,S,[K,\kappa]}^G := \sum_{(K',\kappa')\in [K,\kappa]} u_{T,S,K'\kappa'}^G
\quad \text{and}\quad
v_{T,S,[K,\kappa]}^G := \sum_{(K',\kappa')\in [K,\kappa]} v_{T,S,K'\kappa'}^G.
\]
\end{nothing}

\begin{theorem}
\label{uvorthogonal}
Let $(T, S), (T', S')$ be minimal sections of $G$. Also let $(K,\kappa)\in [\calM_{T/S}^{*}]$ and  $(K',\kappa')\in [\calM_{T'/S'}^{*}]$. Then
\begin{enumerate}[a)]
\item $v_{T',S',[K',\kappa']}^G \cdot u_{T,S,[K,\kappa]}^G =0$
unless $(T,S) =_G (T',S')$ and $[K,\kappa] = [K',\kappa']$.
\item When $(T, S) = (T', S')$ then
\begin{eqnarray*}
v_{T,S,[K,\kappa]}^{G}\cdot u_{T,S,[K,\kappa]}^{G} 
&=& \varphi_{[K,\kappa]}^{T/S} \left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right)\\
&=& \left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right) \varphi_{[K,\kappa]}^{T/S}.
\end{eqnarray*}
Here $N_G(T, S) = N_G(T) \cap N_G(S)$, and $c_g$ is the conjugation by $g$ on $T/S$.
\end{enumerate}
\end{theorem}

\begin{proof} (a) Suppose that $v_{T',S',[K',\kappa']}^G u_{T,S,[K,\kappa]}^G \neq 0$. Then there exist a pair $(K_2,\kappa_2) \in [K,\kappa]$ and $(K_1,\kappa_1) \in [K',\kappa']$ such that \(v_{T',S',K_1,\kappa_1}^G u_{T,S,K_2,\kappa_2}^G\not = 0\). By definition and by the Mackey formula we have the expression
\begin{align*}
v_{T',S',K_1,\kappa_1}^G u_{T,S,K_2,\kappa_2}^G &= \varphi_{K_1,\kappa_1}^{T'/S'} \Defres^G_{T'/S'} \Indinf^G_{T/S} \varphi_{K_2,\kappa_2}^{T/S} \\
&= \varphi_{K_1,\kappa_1}^{T'/S'} \left( \sum_{g\in T'\setminus G /T} \Big[\frac{T'/S'\times T/S}{U_g,1}\Big]\right) \varphi_{K_2,\kappa_2}^{T/S},
\end{align*}
where $U_g = \{(t'S',tS) \in (T'/S') \times (T/S) \mid t'gt^{-1} \in S'gS\}$. In particular, the projections satisfy $p_1(U_g) = ({}^gT \cap T')S'/S'$ and $p_2(U_g) = (T'^g \cap T)S/S$. Notably, $p_1(U_g) = T'/S'$ if and only if ${}^gT \cap T' = T'$, as $S' \leq \Phi(T')$. Similarly, $p_2(U_g) = T/S$ if and only if $T'^g \cap T = T$. By Theorem~\ref{phiortogonal2}, it follows that
\[
\varphi_{K_1,\kappa_1}^{T'/S'} \left( \sum_{g\in T'\setminus G /T} \Big[\frac{T'/S'\times T/S}{U_g,1}\Big]\right) \varphi_{K_2,\kappa_2}^{T/S} = 0,
\]
unless $T' = {}^gT$. Now assume that $T' = {}^gT$, for some $g\in G$. Then we have $k_1(U_g) = ({}^gS \cap T')S'/S' = {}^gSS'/S'$ and $k_2(U_g) = (S'^g \cap T)S/S = S'^gS/S$. Moreover, since ${}^gS \leq {}^g\Phi(T) = \Phi(T')$ and $S'^g \leq \Phi(T'^g) = \Phi(T)$, it follows that ${}^gSS'/S'$ is contained in $k_1(U_g) \cap (\Phi(T')/S') = k_1(U_g) \cap \Phi(T'/S')$. Similarly, $S'^gS/S$ is contained in $k_2(U_g) \cap (\Phi(T)/S) = k_2(U_g) \cap \Phi(T/S)$. By Theorem \ref{phiortogonal2}, the product
\[
\varphi_{K_1,\kappa_1}^{T'/S'} \left( \sum_{g\in T'\setminus G /T} \Big[\frac{(T'/S')\times (T/S)}{U_g,1}\Big]\right) \varphi_{K_2,\kappa_2}^{T/S}
\]
is equal to zero unless $k_1(U_g) \cap \Phi(T'/S') \leq K_1$, $\kappa_1\mid_{k_1(U_g)\cap K_1}=
1$
and $k_2(U_g) \cap \Phi(T/S) \leq K_2$ and $\kappa_2\mid_{k_2(U_g)\cap K_2}= 1$. But as the $\kappa_1$ and $\kappa_2$ are faithful characters we must have $k_1(U_g) \cap \Phi(T'/S')=k_2(U_g)\cap \Phi(T/S)=
1$. This implies that $S'^g \leq S \leq S'^g$, proving that the pairs $(T, S)$ and $(T', S')$ must be conjugate. Assuming that $(T,S)$ and $(T',S')$ are conjugate, the above product simplifies to
\[
\sum_{g\in N_G(T,S)/T} \left( \varphi_{K_1,\kappa_1}^{T/S} \Big[\frac{T/S\times T/S}{U_g,1}\Big] \varphi_{K_2,\kappa_2}^{T/S} \right) = \sum_{g\in N_G(T,S)/T} \left( \varphi_{K_1,\kappa_1}^{T/S} \Iso(c_g) \varphi_{K_2,\kappa_2}^{T/S} \right).
\]
By Proposition \ref{phikappaiso}, part (c), it follows that
\begin{align*}
\sum_{g\in N_G(T,S)/T} \left( \varphi_{K_1,\kappa_1}^{T/S} \Iso(c_g) \varphi_{K_2,\kappa_2}^{T/S} \right) &= \sum_{g\in N_G(T,S)/T} \left(\Iso(c_g) \varphi_{K_1^g,\kappa_1\circ c_{g^{-1}}}^{T/S} \varphi_{K_2,\kappa_2}^{T/S}\right)= 0,
\end{align*}
unless $(K_2,\kappa_2) = (K_1^g,\kappa_1\circ c_{g^{-1}})$ due to the orthogonality of these elements. Consequently, the proof is complete as it follows that $[K,\kappa] = [K_2,\kappa_2] = [K_1^g,\kappa_1\circ c_{g^{-1}}] = [K_1,\kappa_1]=[K',\kappa']$.

\noindent (b) From the calculations in the first part we can expand the product as
{\allowdisplaybreaks
\begin{eqnarray*}
& &v_{T,S,[K,\kappa]}^{G}\cdot u_{T,S,[K,\kappa]}^{G}=\\
&=& \left ( \sum_{(K',\kappa')\in [K,\kappa]} v_{T,S,K'\kappa'}^G \right ) \left( \sum_{(K'',\kappa'')\in [K,\kappa]} u_{T,S,K''\kappa''}^G\right)\\
&=&
\sum_{(K',\kappa')\in [K,\kappa]} \left( \sum_{(K'',\kappa'')\in [K,\kappa]} v_{T,S,K'\kappa'}^G \cdot u_{T,S,K''\kappa''}^G\right) \\ 
&=&
\sum_{\substack{(K',\kappa')\in [K,\kappa]\\ (K'',\kappa'')\in [K,\kappa]}} \left( \varphi_{K',\kappa'}^{T/S} \left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right)\varphi_{K'',\kappa''}^{T/S}\right)\\ 
&=&
\left( \sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K',\kappa'}^{T/S} \right) \left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right) \left (\sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K'',\kappa''}^{T/S}\right)\\ 
&=&
\left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right) \left( \sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K',\kappa'}^{T/S} \right) \left (\sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K'',\kappa''}^{T/S}\right)\\ 
&=&
\left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right) \left( \sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K',\kappa'}^{T/S} \right) \\ &=& \left( \sum_{(K',\kappa')\in [K,\kappa]} \varphi_{K',\kappa'}^{T/S} \right)\left( \sum_{g \in N_G(T, S)/T} \text{Iso}(c_g) \right).
\end{eqnarray*}}
\end{proof}

\begin{defi}
Let $(T,S)$ be a minimal section of $G$ and $(K,\kappa)\in \calM_{T/S}^{*}$. Define
\begin{align*}
\epsilon_{T,S,[K,\kappa]}^G := \frac{1}{|N_G(T,S):T|}\cdot u_{T,S,[K,\kappa]}^G\cdot v_{T,S,[K,\kappa]}^G \in B_k^{\CC^{\times}}(G, G).
\end{align*}
These idempotents are orthogonal and sum to the identity, as we shall prove below. First expand as follows.
\begin{eqnarray*}
&&\epsilon_{T, S, [K, \kappa]}^G=\\
&=& \frac{1}{|N_G(T, S) : T|}
\cdot \left( \sum_{(K', \kappa')} \Indinf^G_{T/S} \varphi_{K', \kappa'}^{T/S} \right)
\left( \sum_{(K'', \kappa'')} \varphi_{K'', \kappa''}^{T/S} \Defres^G_{T/S} \right) \\
&=& \frac{1}{|N_G(T, S) : T|}
\cdot \sum_{\substack{(K', \kappa'), (K'', \kappa'') \in [K, \kappa]}}
\Indinf^G_{T/S} \varphi_{K', \kappa'}^{T/S}\cdot \varphi_{K'', \kappa''}^{T/S} \Defres^G_{T/S} \\
&=& \frac{1}{|N_G(T, S) : T|}
\cdot \sum_{(K', \kappa') \in [K, \kappa]}
\Indinf^G_{T/S} \varphi_{K', \kappa'}^{T/S} \Defres^G_{T/S} \\
&=& \frac{1}{|N_G(T, S) : T|}
\cdot \Indinf^G_{T/S} \varphi_{[K, \kappa]}^{T/S} \Defres^G_{T/S}.
\end{eqnarray*}
\end{defi}

\begin{theorem}
The set
\[
\{ \epsilon_{T,S,[K,\kappa]}^G \big| (T,S) \in [\Pi(G)], (K,\kappa) \in [\calM_{G}^* ]\}
\]
 is a system of orthogonal idempotents in $B_k^{\CC^{\times}}(G,G)$ summing up to the identity.
\end{theorem}
\begin{proof}
The orthogonality of the elements $\epsilon_{T,S,[K,\kappa]}^G$ follow simply by Theorem \ref{uvorthogonal}. Moreover,
\begin{eqnarray*}
&& \sum_{\substack{(T,S)\in [\Pi(G)]\\(K,\kappa)\in [\calM_{T/S}^{*}]}}\epsilon_{T,S,[K,\kappa]}^G=\\
&=&\sum_{\substack{(T,S)\in [\Pi(G)] \\(K,\kappa)\in [\calM_{T/S}^{*}]}} \frac{1}{|N_G(T,S):T|} \Indinf_{T/S}^G \varphi_{[K,\kappa]}^{T/S}\Defres_{T/S}^G\\
&=&\sum_{(T,S)\in \Pi(G)} \left(\sum_{\substack{(K,\kappa)\in \calM_{T/S}^{*}}} \frac{1}{|G:T|} \Indinf_{T/S}^G \varphi_{K,\kappa}^{T/S}\Defres_{T/S}^G\right).
\end{eqnarray*}
Fix $T\leq G$ and sum over $S$ to obtain
\begin{eqnarray*}
&&\sum_{\substack{S\unlhd T, S\leq \Phi(T)\\(K,\kappa)\in \calM_{T/S}^{*}}} \Indinf_{T/S}^G \varphi_{K,\kappa}^{T/S}\Defres_{T/S}^G\\
&=&\Ind_T^G\left(\sum_{\substack{S\unlhd T, S\leq \Phi(T)\\(K,\kappa)\in \calM_{T/S}^{*}}} \Inf_{T/S}^T \varphi_{K,\kappa}^{T/S}\Def_{T/S}^T\right) 
\Res_T^G.
\end{eqnarray*}
Observe that there exists a bijection between the set \(\calM_{\Phi(T)}^{T}\) and the set of triples \((S, K, \kappa)\) satisfying the following properties:
\[
S \unlhd T,\quad S \subseteq \Phi(T), \quad \text{and} \quad (K, \kappa) \in \calM_{T/S}^{*}.
\]
This correspondence is given by mapping each \((L, \lambda) \in \calM_{\Phi(T)}^{T}\) to the triple \((\widehat{L}, L / \widehat{L}, \bar{\lambda})\), where \(\widehat{L} = \ker(\lambda)\), and \(\bar{\lambda}(l\widehat{L}) = \lambda(l)\) for all \(l \in L\). Hence by Proposition \ref{infphidef} the above equation becomes
\begin{align*}
\Ind_T^G \left(\sum_{\substack{(L,\lambda)\in \calM_{\Phi(T)}^{T}}} \varphi_{L,\lambda}^{T}\right)\Res_T^G= \Ind_T^G \widetilde{e_T^T} \Res_T^G = |N_G(T):T|\widetilde{e_T^G}.
\end{align*}
Therefore we get
\begin{align*}
%\sum_{(T,S)\in [\Pi(G)]}\left(
\sum_{\substack{(T,S)\in [\Pi(G)]\\(K,\kappa)\in [\calM_{T/S}^{*}]}}\epsilon_{T,S,[K,\kappa]}^G 
%\right)
=
\sum_{T\leq G} \frac{|N_G(T):T|}{|G:T|} \widetilde{e_T^G} = \sum_{T\le_G G} \widetilde{e_T^G} = \Big [ \frac{G\times G}{\Delta(G),1} \Big].
\end{align*}
\end{proof}

\begin{nothing}
Having constructed a complete set of mutually orthogonal idempotents in \(\CC^\times\)-fibered Burnside algebra $B_k^{\CC^{\times}}(G,G)$, we are now equipped to describe a powerful structural decomposition of the evaluations of $\CC^{\times}$-fibered biset functors on finite groups. Let us consider such a functor \(F\) defined over a field \(k\), and fix a finite group \(G\) for which \(|G| \in k^\times\).

The fundamental result presented here is a canonical decomposition of the module \(F(G)\), which reveals its internal structure in terms of simpler, well-understood constituents. Specifically, \(F(G)\) can be expressed as a direct sum of components indexed by conjugacy classes of minimal sections \((T,S)\) of \(G\), and by equivalence classes \([K,\kappa]\), where \(K\) is a normal subgroup of the quotient \(T/S\) contained in its Frattini subgroup and \(\kappa\) is a faithful character of \(K\). This decomposition is realized via the isomorphism
\[
F(G) \cong \bigoplus_{(T,S) \in [\Pi(G)]} \bigoplus_{(K,\kappa) \in [\mathcal{M}_{T/S}^*]} \left( \varphi_{[K,\kappa]}^{T/S} F(T/S) \right)^{N_G(T,S)/T}.
\]

This decomposition is made explicit by two mutually inverse maps. The forward map, denoted \(V\), sends an element \(w \in F(G)\) to the tuple of its components in the above direct sum:
\[
V(w) = \left( \frac{1}{|N_G(T,S) : T|} \cdot v_{T,S,[K,\kappa]}^G \cdot w \right)_{(T,S,[K,\kappa])}.
\]
Each of these components belongs to the space \(\left( \varphi_{[K,\kappa]}^{T/S} F(T/S) \right)^{N_G(T,S)/T}\), and we must verify this invariance. To do so, fix \((T,S,[K,\kappa])\) and consider any \(g \in N_G(T,S)\). Since \(g\) normalizes both \(T\) and \(S\), the conjugation map \(c_g\) preserves the section \((T,S)\) up to conjugacy and the orbit \([K,\kappa]\) is preserved under conjugation. Thus conjugation by \(g\) maps the idempotent \(v_{T,S,[K,\kappa]}^G\) to $\Iso(c_g)(v_{T,S,[K,\kappa]}^G) = v_{T, S, [K,\kappa]}^G \Iso(c_g)$. Moreover, the map \( \Iso(c_g):F(G)\to F(G) \) is an inner automorphism hence the identity map for $g\in G$ and we conclude that \(v_{T,S,[K,\kappa]}^G \cdot w\) is indeed fixed by the action of \(N_G(T,S)/T\).
The inverse map \(U\) reconstructs an element of \(F(G)\) from its projections in the summands:
\[
U\left( (w_{T,S, (K,\kappa)})_{(T,S, (K,\kappa))} \right) = \sum_{(T,S),[K,\kappa]} u_{T,S,[K,\kappa]}^G \cdot w_{T,S,[K,\kappa]}.
\]

We now verify that \(U \circ V = \mathrm{id}_{F(G)}\). For any \(w \in F(G)\), we compute
\[
U(V(w)) = \sum_{(T,S),[K,\kappa]} \frac{1}{|N_G(T,S) : T|} \cdot u_{T,S,[K,\kappa]}^G \cdot v_{T,S,[K,\kappa]}^G \cdot w.
\]
The sum over all \(u \cdot v\) terms recovers the identity map on \(F(G)\), since the elements \(\epsilon_{T,S,[K,\kappa]}^G \) form a complete set of orthogonal idempotents. Hence \(U(V(w)) = w\) for all \(w\). To establish the reverse identity \(V \circ U = \mathrm{id}\), consider a tuple \((w_{T,S, (K,\kappa)})_{(T,S, (K,\kappa))}\) in the direct sum. Then
\begin{eqnarray*}
&&VU\left( (w_{T,S, (K,\kappa)})_{(T,S, (K,\kappa))} \right)\\
&=&\left( \frac{1}{|N_G(T,S):T|} v_{T,S,[K,\kappa]}^G \sum_{(T',S'),[K',\kappa']} u_{T',S',[K',\kappa']}^G w_{T',S',[K',\kappa']} \right)_{(T,S,[K,\kappa])}.
\end{eqnarray*}
Now, due to the orthogonality relation
\[
v_{T,S,[K,\kappa]}^G \cdot u_{T',S',[K',\kappa']}^G = \delta_{(T,S,[K,\kappa]),(T',S',[K',\kappa'])} \cdot \sum_{g \in N_G(T,S)/T} \Iso(c_g),
\]
we find that all cross-terms vanish, and what remains is
\[
VU\left( w_{T,S,[K,\kappa]} \right) = \left( \frac{1}{|N_G(T,S):T|} \sum_{g \in N_G(T,S)/T} \Iso(c_g)(w_{T,S,[K,\kappa]}) \right)_{(T,S,[K,\kappa])}.
\]
Because each \(w_{T,S,[K,\kappa]}\) is \(N_G(T,S)/T\)-invariant by construction, this averaging yields the original element. Therefore, \(VU = \mathrm{id}\), completing the verification.

As a consequence, each element \(w \in F(G)\) admits the decomposition
\[
w = \sum_{(T,S),[K,\kappa]} \epsilon_{T,S,[K,\kappa]}^G \cdot w.
\]
\end{nothing}

\begin{theorem}
    Let $F$ be a fibered biset functor and $G$ be a  finite group. There exists a decomposition 
\[
F(G) \cong \bigoplus_{(T,S) \in [\Pi(G)]} \bigoplus_{(K,\kappa) \in [\mathcal{M}_{T/S}^*]} \left( \varphi_{[K,\kappa]}^{T/S} F(T/S) \right)^{N_G(T,S)/T}.
\]
Here, $[\Pi(G)]$ denotes a set of representatives of the conjugacy classes of minimal sections of $G$, i.e., sections \(S\unlhd T\leq G\) with \(S \leq \Phi(T)\), and $[\mathcal{M}_{T/S}^*]$ denotes a set of orbit representatives $[K,\kappa]$ under the action of $\Out(T/S)$, where $K$ is a normal subgroup of $T/S$ contained in its Frattini subgroup, and $\kappa$ is a faithful character of $K$.

\end{theorem}

\section{Decomposing $\calF_{p,k}^{\ctimes}$, when $p\in k^{\times}$}
\label{Decomposing}
Let $k$ be a commutative unitary ring, and let $p \in k^{\times}$ be a fixed prime. In this section, we restrict to attention to the category of $\CC^{\times}$-fibered bisets on finite $p$-groups. The goal of this section is to decompose the category of $\ctimes$-fibered $p$-biset functors via idempotents defined earlier. This is a fibered version of Bouc's results Theorem 7.4 and Corollary 7.5 in \cite{double}. We begin by defining atoric $p$-groups.

\begin{defi}[Bouc]
   A finite \(p\)-group \(P\) is called \emph{atoric} if the following equivalent conditions hold.
   \begin{enumerate}
       \item \(P\) does not admit any decomposition \(P = E\times Q\), where \(E\) is a non-trivial elementary abelian group.
       \item For any non-trivial normal subgroup $N$ of \(P\), one has \(N\cap\Phi(P)\not = 1\).
       \item \(\Omega_1Z(P)\le \Phi(P)\).
   \end{enumerate}
\end{defi}

We denote by $\calA t_p$ the class of \textit{atoric} $p$-groups and by $[\calA t_p]$ a set of representatives of isomorphism classes in $\calA t_p$. 

Let $P$ be a finite $p$-group. As in \cite[Section 6]{double}, we denote the greatest atoric quotient of $P$ by $P^@$. By Proposition 6.4 of \cite{double}, there is a maximal normal subgroup $N$ of $P$ with the property that $N\cap \Phi(P)=1$ such that $P^@ = P/N$. We call $P^@$ the \emph{atoric part} of $P$. For further properties of atoric $p$-groups, we refer to Section~6 of \cite{double}. 

The following theorem refines a fundamental result of Bouc to the fibered setting, where the effect of the subgroup $K$ is made clear in an essential way. As in \cite{double}, this refinement plays a central role in establishing the decomposition theorem we prove below.

\begin{theorem}\label{thm:nonzeroatoric}
Let \( P \) and \( Q \) be finite \( p \)-groups, and let \( (T,S) \) and \( (V,U) \) be minimal sections of \( P \) and \( Q \), respectively. Suppose that 
\[
(K/S,\kappa) \in \calM_{T/S}^{*} \quad \text{and} \quad (L/U,\lambda) \in \calM_{V/U}^{*}.
\]
Then 
\[
\epsilon_{V,U,[L/U,\lambda]}^Q \cdot B_{k}^{\CC^{\times}}(Q,P) \cdot \epsilon_{T,S,[K/S,\kappa]}^P \neq \{0\} \, \text{implies that}\, (V/L)^@ \cong (T/K)^@. 
\]
\end{theorem}


\begin{proof}
Suppose that 
\[
\epsilon_{V,U,[L/U,\lambda]}^Q\cdot  B_{k}^{\CC^{\times}}(Q,P)\cdot  \epsilon_{T,S,[K/S,\kappa]}^P \neq \{0\},
\]
then there exists \( a\in B_{k}^{\mathbb{C}}(Q,P) \) such that \(\epsilon_{V,U,[L/U,\lambda]}^Q\cdot  a\cdot \epsilon_{T,S,[K/S,\kappa]}^P \not = 0\) and thus
\[
    \Indinf^Q_{V/U}\varphi_{[L/U,\lambda]}^{V/U}\Defres^Q_{V/U} \cdot a \cdot \Indinf^P_{T/S}\varphi_{[K/S,\kappa]}^{T/S}\Defres^P_{T/S} \neq 0.
\]
Thus, there exist \( (L'/U,\lambda')\in [L/U,\lambda] \) and \( (K'/S,\kappa')\in [K/S,\kappa] \) such that
\[
    \Indinf_{V/U}^Q \varphi_{L'/U,\lambda'}^{V/U}\Defres_{V/U}^Q \cdot a \cdot \Indinf_{T/S}^P\varphi_{K'/S,\kappa'}^{T/S}\Defres_{T/S}^P\neq 0. 
\]
In particular, the element 
\[
b=\Defres_{V/U}^Q \cdot a \cdot \Indinf_{T/S}^P
\] 
of \( B_{k}^{\CC^{\times}}(V/U,T/S) \) satisfies 
\[
\varphi_{L'/U,\lambda'}^{V/U} \cdot b \cdot \varphi_{K'/S,\kappa'}^{T/S} \neq 0.
\] 
This implies that there exists an element \( (N,\eta)\in \calM_{V/U\times T/S} \) such that
\begin{equation*}
    \varphi_{L'/U,\lambda'}^{V/U} \cdot \Big[\frac{(V/U)\times (T/S)}{N,\eta}\Big] \cdot \varphi_{K'/S,\kappa'}^{T/S} \neq 0.
\end{equation*}
Then, by Theorem~\ref{phiortogonal2}, the group $N$ must be covering in $(V/U) \times (T/S)$, and we must have
\[
    k_1(N) \cap \Phi(V/U) \leq L'/U \quad \text{and} \quad k_2(N) \cap \Phi(T/S) \leq K'/S.
\]
Hence, we obtain
\begin{eqnarray*}
    \frac{k_1(N)(L'/U)}{L'/U} \cap \Phi\left(\frac{V/U}{L'/U}\right)
    &=& \frac{k_1(N)(L'/U)}{L'/U} \cap \frac{\Phi(V/U)}{L'/U}=\\
    &=& \frac{k_1(N)(L'/U) \cap \Phi(V/U)}{L'/U}
    = \frac{L'/U}{L'/U},
\end{eqnarray*}
since $L'/U \in \Phi(V/U)$. Similarly, we also have
\[
    \frac{k_2(N)(K'/S)}{K'/S} \cap \Phi\left(\frac{T/S}{K'/S}\right) = \1.
\]
Therefore, by \cite[Proposition~6.6]{double}, it follows that
\[
    (V/L)^@ \cong \left(\frac{V/U}{L/U}\right)^@ \cong \left(\frac{V/U}{L'/U}\right)^@
    \cong \left(\frac{\frac{V/U}{L'/U}}{\frac{k_1(N)(L'/U)}{L'/U}}\right)^@
    \cong \left(\frac{V/U}{k_1(N)(L'/U)}\right)^@.
\]
By analogous reasoning on the right-hand side, we also have
\[
    (T/K)^@ \cong \left(\frac{T/S}{k_2(N)(K'/S)}\right)^@.
\]
For the above product to be nonzero, we must also have
\[
    e_{(L'/U,\lambda')}^{V/U} \cdot \left[\frac{(V/U)\times (T/S)}{N,\eta}\right] \cdot e_{(K'/S,\kappa')}^{T/S} \neq 0.
\]
This follows from the definitions of $\varphi_{L'/U,\lambda'}^{V/U}$, $\varphi_{K'/S,\kappa'}^{T/S}$, and (\ref{eKtimeseL}). Moreover, by \cite[Proposition~4.2]{fibered biset}, we can compute the left and right invariants of this nonzero element. In particular,
\[
    e_{(L'/U,\lambda')}^{V/U} \cdot \left[\frac{(V/U)\times (T/S)}{N,\eta}\right] \cdot e_{(K'/S,\kappa')}^{T/S}
    = \left[\frac{(V/U)\times (T/S)}{N((L'/U)\times (K'/S)),\, \lambda' \cdot \eta \cdot \kappa'}\right],
\]
where
\begin{align*}
    p_1\big(N((L'/U)\times (K'/S))\big) &= V/U, \\
    p_2\big(N((L'/U)\times (K'/S))\big) &= T/S, \\
    k_1\big(N((L'/U)\times (K'/S))\big) &= k_1(N)(L'/U), \\
    k_2\big(N((L'/U)\times (K'/S))\big) &= k_2(N)(K'/S).
\end{align*}
Hence, we obtain the isomorphism
\[
    \frac{V/U}{k_1(N)(L'/U)} \cong \frac{T/S}{k_2(N)(K'/S)}.
\]
Combining this with the previous observations yields the desired isomorphism:
\[
    (V/L)^@ \cong (T/K)^@.
\]
\end{proof}

