\begin{nothing}
These properties lead to the decomposition of the category $\mathcal F_{p, k}^{\mathbb C^\times}$. Indeed, let $F$ be a $\ctimes$-fibered $p$-biset functor and $M$ be an atoric $p$-group.
As $P$ runs over all finite $p$-groups, the family $c_M^P\in B_k^{\CC^{\times}}(P,P)$ of idempotents defines a natural transformation 
\[
c_{M, F}: F\to F \, \text{given by}\, c_{M, F}(P)(w) = c_M^P\cdot w \, \text{for each}\, w\in F(P).
\]
%that is, an endomorphism in $\End_{\mathcal F_{p, k}^{\mathbb C^\times}}(F)$. 
Moreover if $F'$ is also a $\ctimes$-fibered biset functor, then for any natural transformation $\theta: F\to F'$ %of $\ctimes$-fibered $p$-biset functors, 
we have $$c_{M, F'}\circ \theta = \theta\circ c_{M, F}.$$ In particular $c_{M, ?}$ is an idempotent in the center of the category $\mathcal F_{p, k}^{\mathbb C^\times}$. Following Bouc, we denote this idempotent by $\widehat{c}_M$ and call it the \emph{Bouc's idempotent at $M$}. By the above properties of Bouc's idempotents, it is straightforward to show that as $M$ runs over all atoric $p$-groups up to isomorphism, we get a decomposition of the identity functor of the category $\mathcal F_{p, k}^{\mathbb C^\times}$ into a sum of orthogonal idempotents
\[
\id_{\mathcal F_{p, k}^{\mathbb C^\times}} = \sum_{M\in [\calA t_p]}\widehat{c}_M
\]
Now writing $\widehat{c}_MF$ for the image of $c_{M, F}$, we obtain a canonical decomposition 
\[
F \cong \bigoplus_{M\in[\calA t_p]} \widehat{c}_MF
\]
for any $\ctimes$-fibered $p$-biset functor $F$. This decomposition is natural in $F$ and $\widehat{c}_MF$ inherits its functor structure from $F$.

This is exactly the fibered $p$-biset functor version of Bouc's decomposition of $p$-biset functors. We state the final result as a theorem for future reference.
\end{nothing}
\begin{theorem}[Block decomposition of $\mathcal{F}_{p,k}^{\mathbb{C}^\times}$]
\label{thm:block-decomposition}
Let $p$ be a prime number such that $p \in k^\times$. For each atoric $p$-group $M \in [\mathrm{At}_p]$, define the full subcategory
\[
\widehat{c}_M\mathcal{F}_{p,k}^{\mathbb{C}^\times} := \left\{ F \in \mathcal{F}_{p,k}^{\mathbb{C}^\times} \,\middle|\, \widehat{c}_M F = F \right\},
\]
consisting of those functors on which $\widehat{c}_M$ acts trivially. Then:

\begin{enumerate}[(1)]
    \item Each category $\widehat{c}_M\mathcal{F}_{p,k}^{\mathbb{C}^\times}$ is an abelian subcategory of $\mathcal{F}_{p,k}^{\mathbb{C}^\times}$, closed under taking subfunctors, quotients, and extensions.

    \item The family of orthogonal idempotents $\{ \widehat{c}_M \}_{M \in [\mathrm{At}_p]}$ induces an equivalence of categories
    \[
    \mathcal{F}_{p,k}^{\mathbb{C}^\times} \cong \prod_{M \in [\mathrm{At}_p]} \widehat{c}_M\mathcal{F}_{p,k}^{\mathbb{C}^\times},
    \]
    via the functor
    \[
    F \mapsto \left( \widehat{c}_M F \right)_{M \in [\mathrm{At}_p]}.
    \]

    \item Each functor $F \in \mathcal{F}_{p,k}^{\mathbb{C}^\times}$ admits a canonical decomposition
    \[
    F = \bigoplus_{M \in [\mathrm{At}_p]} \widehat{c}_M F.
    \]
\end{enumerate}
\end{theorem}

\begin{nothing}
    Having the above decomposition, a natural direction is to describe the blocks $\widehat{c}_M\calF_{p,k}^\ctimes$ for arbitrary atoric $p$-groups more explicitly. In \cite{double}, Bouc obtained detailed results on the structure of these blocks in a very elegant way. Although one might attempt to generalize his ideas to the case of fibered $p$-biset functors, we decided not to go in this direction since the results are expected to be much more complicated compared to the case of $p$-biset functors. While a complete classification of the fibered blocks is expected to be far more involved than in the unfibered case, we turn our attention to a coarser but structurally useful invariant: the vertex of an indecomposable functor.
    We shall apply this to obtain further results about fibered $p$-biset functors when we regard them as biset functors.
\end{nothing}

\begin{defi}
    Let $F$ be an indecomposable $\CC^{\times}$-fibered $p$-biset functor over $k$. The unique atoric $p$-group $M\in [\calA t_p]$ such that $F=\widehat{c}_MF$ is called the \textit{vertex} of $F$. 

    This terminology is in parallel to the theory of vertices for indecomposable $p$-biset functors in the sense of Bouc \cite{double}.
\end{defi}
\begin{remarki}
\label{rem:vertex-ext}
Let $F$ and $F'$ be indecomposable objects in $\mathcal{F}_{p,k}^{\mathbb{C}^\times}$ with distinct vertices $M, N \in [\calA t_p]$. Then the extension groups between them vanish:
\[
\operatorname{Ext}^\ast_{\mathcal{F}_{p,k}^{\mathbb{C}^\times}}(F, F') = 0.
\]
This follows from the fact that $\mathcal{F}_{p,k}^{\mathbb{C}^\times}$ decomposes as a direct product of blocks $\widehat{c}_M \mathcal{F}_{p,k}^{\mathbb{C}^\times}$ for $M\in [\calA t_p]$.%, and each such block is an abelian subcategory.

\smallskip

Furthermore, we emphasize that the vertex of a functor does not necessarily coincide with a minimal group for the functor. The following theorem explores this relationship.
\end{remarki}

\begin{theorem}\label{thm:vertexindec}
Let $F$ be an indecomposable $\mathbb{C}^\times$-fibered $p$-biset functor over $k$ with vertex $M \in [\mathrm{At}_p]$, and suppose $P$ is a minimal group for $F$. Then there exists a normal subgroup $K \unlhd P$ such that
\[
K \leq \Phi(P) \cap Z(P), \quad \text{and} \quad M \cong (P/K)^@.
\]
\end{theorem}
\begin{proof}
Since $F = \widehat{c}_M F$, there must exist a summand $\epsilon^P_{T,S,[K/S,\kappa]}$ of $c_M^P$ such that
\[
\epsilon^P_{T,S,[K/S,\kappa]} \cdot F(P) \neq 0,
\]
for some minimal section $(T,S)$ of $P$ and a pair $(K/S, \kappa) \in [M^\ast_{T/S}]$ with $(T/K)^@ \cong M$.
By the definition of $\epsilon^P_{T,S,[K/S,\kappa]}$, we have
\[
\epsilon_{T, S, [K, \kappa]}^P = X\circ \Defres^P_{T/S} 
\] for a fibered $(P, T/S)$-biset $X$. Since $P$ is minimal for $F$, this composition is nonzero only if $T/S \cong P$, hence $T = P$ and $S = 1$. Thus we obtain $$(P/K)^@\cong M.$$ Since $\kappa$ is a faithful character of $K$, it follows that $K$ is a central cyclic subgroup of $P$, and by its choice, it is contained in $\Phi(P)$. Hence the result.
\end{proof}
\begin{nothing}
    As an application of this theorem, we may determine vertices of simple $\ctimes$-fibered biset functors over $\CC$. By Theorem 9.2 of \cite{fibered biset}, these functors are parameterized by quadruples $(P, K, \kappa, [V])$ where $P$ is a finite $p$-group, $K\unlhd P$ is a cyclic normal subgroup of $P$ contained in $Z(P)\cap P'$ and $\kappa$ is a faithful character of $K$. The module $V$ is a simple module over the group algebra $\CC\Gamma_{(P, K,\kappa)}$. Here $\Gamma_{(P, K, \kappa)}$ is a finite group associated to the given triple, as in Section 6 of \cite{fibered biset}. The corresponding simple functor is denoted by $S_{(P, K, \kappa, [V])}$. 
\end{nothing}

\begin{theorem} \label{thm:vertexsimple}
The vertex of the simple $\CC^{\times}$-fibered $p$-biset functor $S_{(P,K,\kappa,V)}$ is $(P/K)^@$.
\end{theorem}
\begin{proof}
Since $S=S_{(P, K, \kappa, [V])}$ is indecomposable and $P$ is minimal for $S$, by Theorem \ref{thm:vertexindec}, the vertex of $S$ is $(P/N)^@$ for some normal subgroup $N$ of $P$ contained in $Z(P)\cap \Phi(P)$. We claim that $N$ can be chosen as $K$. 

By the construction of $S$ given in \cite{fibered biset}, we have that
\[
f_{(K,\kappa)}^P\cdot S(P)\not=0
\]
where 
\[
f_{(K,\kappa)}^P = \sum_{(K, \kappa)\le (K', \kappa')\in\calM_P^P}\mu_{\unlhd P}(K, K')e_{K', \kappa'}^P
\]
is an idempotent of $B_k^{\CC^{\times}}(P,P)$. See \cite[Section 4]{fibered biset} for details.
On the other hand, setting $M=(P/N)^@$, we must have
\[
c_M^PS(P) = S(P).
\]
As above, this implies that there exists a pair $(N', \eta)$ such that $(P/N')^@ \cong M$ and
\[
\epsilon_{P, 1, [N', \eta]}^PS(P) \not= 0
\]
Without loss of generality we put $N = N'$. By definition,
\[
\epsilon_{P, 1, [N, \eta]}^P = \varphi_{[N,\eta]}^P
\]
hence we must have 
\[
\varphi_{N, \eta}^P S(P)\not= 0.
\]
This implies that $\varphi_{N, \eta}^P\cdot f_{(K, \kappa)}^P\not=0$. Hence
\[
0\not= \varphi_{N, \eta}^P\cdot f_{(K, \kappa)}^P = \sum_{(N,\eta)\le (N', \eta')\in\calM_{\Phi(P)}^{P}} \mu_{\unlhd P}(N, N')\widetilde{e_P^P}\cdot e_{N', \eta'}^P\cdot f_{K, \kappa}^P
\]
By \cite[Proposition 5.6]{fibered biset}, we get that
$(N',\eta')\le(K,\kappa)$, which in particular implies that $N\le K$.

On the other hand, we have
\[
0\not= \varphi_{N, \eta}^P\cdot f_{(K, \kappa)}^P = \sum_{(K, \kappa)\le (K', \kappa')\in\calM_P^P}\mu_{\unlhd P}(K, K')\varphi_{N, \eta}^P\cdot e_{(K', \kappa')}^P
\]
In particular, $\varphi_{N, \eta}^P\cdot e_{(K', \kappa')}^P$ must be non-zero for some $(K', \kappa')$. By 
Theorem \ref{phiortogonal}, we must have $K'\cap\Phi(P)\le N$. But $K\le K'\cap \Phi(P)$, hence we obtain $K\le N$. Together with the previous paragraph, we get $N=K$, as required.

\end{proof}

\begin{coro}
Let $S = S_{(P, K, \kappa, [V])}$ and $S' =S_{(Q, L, \lambda, [W])}$ be simple $\ctimes$-fibered $p$-biset functors.
 %Let $P$ and $Q$ be finite $p$-groups. Let $(K,\kappa)\in \calM_{\Phi(P)}^{P}$ and $(L,\lambda)\in \calM_{\Phi(Q)}^{Q}$. Let $V$ and $W$ be irreducible $k\Gamma_{(P,K,\kappa)}$ and $k\Gamma_{(Q,L,\lambda)}$-modules respectively. 
 If $(P/K)^@\not \cong (Q/L)^@$, then $\Ext^*_{\calF_{p,k}}(S, S')=\{0\}$. 
\end{coro}

