\begin{theorem}
    Let $k$ be a field of characteristic different from $p$, and $M$ be an atoric $p$-group. Define
\[
\mathcal{F}_{p,k}^{\mathbb{C}^\times}[M] := \left\{ F \in \mathcal{F}_{p,k}^{\mathbb{C}^\times} \,\middle|\, \text{all composition factors of } F \text{ have vertex } M \right\}.
\]

    \begin{enumerate}
        \item For any $\ctimes$-fibered $p$-biset functor $F$, the subfunctor $\widehat{c}_MF$ is the greatest subfunctor of $F$ which belongs to $F_{p,k}^\ctimes[M]$.
        \item In particular the equality  $$\widehat{c}_M\calF_{p,k}^\ctimes=\calF_{p,k}^\ctimes[M]$$ holds.
    \end{enumerate}
