\subsection{Baker–Campbell–Hausdorff formula}

We will need the following lemma.

\begin{lem}\label{lem: normal form}
    There exists absolute constants $\beta_0<1$ and $ \constE\label{C:normalform}\ge1$ depending only on the dimension of $G$ so that the following holds. Let $0<\beta\le \beta_0$ and $w_1,w_2\in B_\mathfrak r(0,\beta)$. There are $h\in H$ and $w\in\mathfrak r$ which satisfy
    $$.5\|w_1-w_2\|\le \|w\|\le 2\|w_1-w_2\|\text{ and } \|h-I\|\le \ref{C:normalform}\beta \|w\|$$
    so that $\exp(w_1)\exp(-w_2)=h\exp(w)$.
\end{lem}

\begin{proof}
    By the open mapping theorem, there exists $\beta_0=\beta_0(\dim(G))\ll 1$ such that the map $B_{\Lie(H)}(0,\beta_0)\times B_{\mathfrak r}(0,\beta_0)\to G$ given by $(v_1,v_2)\mapsto \exp (v_1) \exp(v_2)$ is a diffeomorphism onto its image.

    Let $0<\beta\le \beta_0$ and $w_1,w_2\in B_\mathfrak r(0,\beta)$. By the Baker–Campbell–Hausdorff formula (and potentially making $\beta_0$ smaller) and using that $[w_2,w_1]=0 + [w_2-w_1,w_1]$, there exists $w'\in \Lie(G)$ with $\|w'\|\ll\beta\|w_1-w_2\|$ such that 
    $$\exp(w_1)\exp(-w_2)=\exp(w_1-w_2 + w').$$

     Again, by Baker–Campbell–Hausdorff formula  and potentially making $\beta_0$ smaller, there exists $(v_1,v_2)\in B_{\Lie(H)}(0,\beta_0)\times B_{\mathfrak r}(0,\beta_0)$ and $v'\in \Lie(G)$ with $\|v'\|\ll\|v_1\|\|v_2\|$ such that 
    \begin{equation}\label{eqn: liealgebraequality}
        \exp(w_1-w_2 + w') =\exp(v_1)\exp(v_2) = \exp(v_1+v_2 + v')
    \end{equation}
    where the implied constant is absolute.
    We claim $h=\exp(v_1)$ and $w = v_2$ satisfy the claims in the lemma.



    By our choice of $\beta_0$ and Equation \ref{eqn: liealgebraequality}, we have
        \begin{equation}\label{eqn: liealgebraequality2}
        w_1-w_2+w' = v_1+v_2 + v'
        \end{equation}
and since we are working with the max norm with respect to $\Lie(H)$ and $\mathfrak r$ and they are orthogonal subspaces then $w_1,w_2,v_2\in\mathfrak r$ imply that $$\|v_1\|\ll\|w'\|+\|v'\|\ll \beta\|w_1-w_2\| + \|v_1\|\|v_2\|\ll \beta\|w_1-w_2\| + \beta_0\|v_1\|.$$
This gives $\|v_1\|\ll (1-\beta_0)^{-1}\beta \|w_1-w_2\|\ll \beta \|w_1-w_2\|$.

Now using Equation \ref{eqn: liealgebraequality2}, we have $v_2 -(w_1-w_2)= -v_1 -v' +w' $ and  $\|w'\|\ll \beta\|w_1-w_2\|$, $\|v_1\|\ll \beta \|w_1-w_2\|$, and $\|v'\|\ll \beta\|v_1\|\ll \beta^2\|w_1-w_2\|$. Thus, 
 $$|\|v_2\| -\|w_1-w_2\||\le \|v_2 -(w_1-w_2)\|\ll \beta \|w_1-w_2\|$$
 and so $$(1-\beta)\|w_1-w_2\|\le \|v_2\|\le (1+\beta)\|w_1-w_2\|.$$

 By making $\beta_0$ potentially smaller, we have the desired inequality for $v_2\in\mathfrak r$. In particular,  $\beta_0\le 1/2$.

 Lastly, we note, that by using the previous bound on $\|v_2\|$ and that $\beta\le1/2$, we have $\|v_1\|\ll \beta \|w_1-w_2\|\ll\frac{\beta}{1-\beta} \|v_2\|\ll2 \beta \|v_2\|$ and we denote the implicit constant by $C'$. Note we chose $h=\exp(v_1)$. Then,  
 $$\|h-I\| \le \sum_{k=1}^\infty \|v_1\|^k /k!\ll \beta \|v_2\|e^{2C'}$$ 
 and by taking $\ref{C:normalform} = e^{2C'}$ we are done.


\end{proof}

Lastly, choose $\beta_1<\beta_0$ such that for all $\beta<\beta_1$ we have
\begin{equation}\label{eqn:changingballs}
    B_{\ref{C:changeinballs}^{-1}\beta} ^G\subseteq \{g\in G:\|g-I\|<\beta\}\subset B_{\ref{C:changeinballs}\beta} ^G
\end{equation}
for some absolute $\constE\label{C:changeinballs}=\ref{C:changeinballs}(\dim(G)).$ We remark that $\|g-I\|\asymp d_G(e,g)$ where the implicit constant depends on $\dim(G)$.

