\section{Linear algebra lemma}

In this section, we prove a linear algebra lemma that shows that on average the action of expanding horospheres increase the length of vectors in $\mathfrak r$. This behavior is well studied see e.g. Shah \cite{MR1403756}, however, we reprove this to guarantee certain exponents are large enough for later sections. See also Eskin-- Margulis--Mozes \cite{MR1609447} where they prove a similar qualitative result for expanding circles and demonstrate that in dimensions larger than three the exponent $\delta$ can be close to two.

\begin{lem}\label{Lem:LA1}
    Suppose $1/2<\delta<1$, $Z(r_1,\c,r_2)\ne 0$, and $t>0$. Then
    $$\int_{B^U_1}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta}\ll e^{t(-1+\delta)}\|Z(r_1,\c,r_2)\|^{-\delta}.$$
\end{lem}



We will frequently use the following inequality that estimates the measure of a sub-level set of a polynomial. Such estimates have seen many applications in dynamics, notably in Dani--Margulis \cite{MR1237827} and Kleinbock--Margulis \cite{MR1652916} where they were called $(C,\alpha)$-good functions. In fact, such estimates go back to Remez \cite{Remez}. Below we use the formulation of Katz \cite{katz}, Corollary 4.2 of the Remez inequality.


\begin{prop}[Remez' Inequality]\label{Remez}
Let $B\subset \mathbb R^n$ be a non-empty convex subset and $f:B\to\mathbb R ^m$ be a polynomial of degree $d$. For any $\varepsilon>0$, one has
$$\big|\{x\in B: \|f\|<\varepsilon\}\big|\le 4n\left(\frac{\varepsilon}{\sup_{x\in B}\|f(x)\|}\right)^{1/d}|B|$$
   where $|\cdot|$ denotes the Lebesgue measure on $\mathbb R^n$. 
\end{prop}


Recall from Equation \eqref{eqn:Adjointaction}, the adjoint action on $\mathfrak r$ acts via
$$    \Ad(a_tu_\s)Z(r_1,\c,r_2)=Z(e^t(r_1+\s\cdot \c+r_2\|\s\|^2/2),\c+r_2\s,e^{-t}r_2)
$$


\begin{proof}[Proof of Lemma \ref{Lem:LA1}]
    Without loss of generality, we suppose that $Z(r_1,\c,r_2)$ has norm 1.

\begin{itemize}
\item

Consider $|r_2|\ge 1/1000$.

We compute $$\int_{B_1 ^U}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta}$$ by breaking it into 
$$D_1 = \{\s\in B_1 ^U:e^t(r_1+\s \cdot\c+r_2\|\s\|^2/2))<e^{-t}/1000\}$$ and the compliment $D_2$. 

On $D_1$ our integral becomes
$$\int_{D_1}\frac{d\s}{(e^{-t}|r_2|)^\delta}\le \frac{m(D_1)}{e^{-\delta t}/1000^\delta}.$$
Proposition \ref{Remez} says $|D_1|\ll e^{-t}$ and so 

$$\int_{D_1}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta}\ll e^{t(-1+\delta)}.$$


For the integral on $D_2$, we consider the regions $$J_k=\{\s\in B_1 ^U:e^{-2t+k}\le|r_1+\s \cdot\c+r_2\|\s\|^2/2)|<e^{-2t+k+1}\}.$$ Then, by utilizing the lower bounds on the max imposed by the region $J_k$ and Proposition \ref{Remez} we get
\begin{align*}
\int_{D_2}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta} &= \sum_{k=0} ^\infty\int_{D_2\cap J_k}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta} \\
&\le \sum_{k=0} ^\infty\frac{|J_k\cap D_2|}{(e^{t}e^{-2t+k})^\delta} \\
&\le  \sum_{k=0} ^\infty\frac{e^{(-2t+k+1)/2}}{(e^{-t+k})^\delta} \ll e^{t(-1+\delta)}\sum_{k=0} ^\infty e^{k((1/2)-\delta)}\\
&\ll e^{t(-1+\delta)}.
\end{align*}






\item

Consider $|r_2|\le 1/1000$.

Notice here that we never need to consider the third term $e^{-t}r_2$ because the upper bound on $r_2$. Indeed, it is always beaten by the first term (so long as $r_1+\s \c+r_2\|\s\|^2/2\ne 0$).

Assume that $\|\c\|<1/100$ i.e. is very small. Then, since $r_2$ is also small, then we must have $r_1=1$ by our condition on the max norm of $Z(r_1,\c,r_2)$. Hence, $r_1+\s \c+r_2\|\s\|^2/2$, even in the worst case of $r_2$ and $\c$ being small, is at least 1/10. This is independent of $\s$.

In particular, $\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\| = r_1+\s \c+r_2\|\s\|^2/2>e^t/10$ and so

$$\int_{B_1 ^U}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta}\le e^{-\delta t}10^\delta\ll e^{t(-1+\delta)}$$
 for $\delta>1/2$.

 Lastly, assume $\|\c\|\ge 1/100$. Then
 $$1/100\le \|\c\|\le \|\c+r_2\s\|+|r_2|\le\|\c+r_2\s\|+1/1000$$
yields that the middle term has the bound $\|\c+r_2\s\|\ge1/200 $. This is independent of $\s\in B_1 ^U$.

Consider $D_1 = \{\s:e^t(r_1+\s \c+r_2\|\s\|^2/2))<1/200\}$ and the compliment $D_2$.

On $D_1$ our integral becomes
$$\int_{D_1}\frac{d\s}{(\|\c+r_2\s\|)^\delta}\le \frac{|D_1|}{200^\delta}.$$
Proposition \ref{Remez} says $|D_1|\ll e^{-t/2}$ and so 

$$\int_{D_1}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta}\ll e^{t(-1+\delta)}$$
whenever $\delta>1/2.$


For the integral on $D_2$, we consider the regions $$J_k=\{\s:e^{-t+k}\le|r_1+\s \c+r_2\|\s\|^2/2)|<e^{-t+k+1}\}.$$ Then, by utilizing the lower bounds on the max imposed by the region $J_k$ and Proposition \ref{Remez} we get
\begin{align*}
\int_{D_2}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta} &= \sum_{k=0} ^\infty\int_{D_2\cap J_k}\frac{d\s}{\|\Ad(a_tu_\s)Z(r_1,\c,r_2)\|^\delta} \\
&\le \sum_{k=0} ^\infty\frac{|J_k\cap D_2|}{(e^te^{-t+k})^\delta} \\
&\le \sum_{k=0} ^\infty\frac{e^{(-t+k+1)/2}}{(e^{k})^\delta} \ll e^{-t/2}\sum_{k=0} ^\infty e^{k((1/2)-\delta)}\\
&\ll e^{t(-1+\delta)}
\end{align*}
whenever $\delta>1/2$.
\end{itemize}
\end{proof}

We will need to extend this to all vectors in $Ge_1$. This follows as in Lemma 5.12 of Mohammadi-Oh \cite{MR4556221} using the fact that vectors in $Ge_1$ are projectively far from the $H$-invariant line $\mathbb Re_n$.  

\begin{lem}\label{Lem:Lowerbound}
    For any vector $v\in Ge_1$, $\|v\|\ll\|v_1\|$, where $v_1$ is the projection of $v$ to $(\mathbb R e_{n}) ^\perp$ where the implied constant is absolute.
\end{lem}
\begin{proof}
    The proof is the same as in Lemma 5.12 by replacing $e_3$ with $e_n$.
\end{proof}

We can now extend our linear algebra to $Ge_1$ which corresponds to the thin parts of $X$.

\begin{lem}\label{Lem:LA}
    Suppose $1/2<\delta<1$, $v\in Ge_1$, and $t>0$. Then
    $$\int_{B^U_1}\frac{d\s}{\|a_tu_\s v\|^\delta}\ll e^{t(-1+\delta)}\|v\|^{-\delta}.$$
\end{lem}

\begin{proof}
    We can write any $v\in Ge_1\subset \mathbb R^{n+1}$ as $v=v_1+ce_n$ where $v_1\in (\mathbb R e_{n}) ^\perp$ and $c\in\mathbb R$. Then since $e_n$ is $H$-invariant, we have $a_tu_\s v= a_tu_\s v_1 + c e_n$ for any $t\in \mathbb R$ and $\s\in B_1 ^U$. Then
$$ \int_{B_1 ^U}\frac{d\s}{\|a_t u_\s v\|^\delta}= \int_{B_1 ^U}\frac{d\s}{(\| a_t u_\s v_1\|^2+c^2)^{\delta/2} }
        \le\int_{B_1 ^U}\frac{d\s}{\| a_t u_\s v_1\|^\delta}
        \ll e^{t(-1+\delta)}\|v_1\|^{-\delta}$$
    where the last comparison comes from Lemma \ref{Lem:LA1}. By Lemma \ref{Lem:Lowerbound} we have  $\|v_1\|\gg \|v\|$, which gives the desired inequality.
\end{proof}

Additionally, we need the following corollary that discretizes the previous lemma.

\begin{cor}\label{Cor:LA}
    For any $\delta\in(1/2,1)$, there exists $m_\delta>0$ such that for any $v\in Ge_1\setminus\{0\}$, we have
    $$\int_{B^U _1}\frac{d\s}{\|a_{m_\delta}u_\s v\|^\delta}\le e^{-1}\sigma^{-2} \|v\|^{-\delta}.$$
\end{cor}
\begin{proof}
    Choose $m_\delta>0$ such that $Ce^{m_\delta(-1+\delta)}=e^{-1}/\sigma^2$  where $C$ is the implicit constant from Lemma \ref{Lem:LA} and $\sigma$ is the factor from Proposition \ref{Prop:comparison}. Then, by Lemma \ref{Lem:LA}, we have 
    $$\int_{B^U _1}\frac{d\s}{\|a_{m_\delta}u_\s v\|^\delta}\le e^{-1}\sigma^{-2} \|v\|^{-\delta}.$$

    We note that $m_\delta\to\infty$ as $\delta\to1.$
\end{proof}


\begin{cor}\label{Cor:LAInj}
    For any $\delta\in(1/2,1)$ $x\in X$ we have
$$\int_{B_1 ^U} \inj(a_{m_\delta}u_\s y)^{-\delta} d\s \le e^{-1}\inj(y)^{-\delta} + O(1)$$
where the implicit constant depends only on $X$.
\end{cor}
\begin{proof}
    If $a_{m_\delta}u_\s y\in X_{\eta_X}$, then the injectivity radius is bounded below by an absolute constant and so  $ \inj(a_{m_\delta}u_\s y)^{-\delta}$ is bounded above by an absolute constant.

    Otherwise, $a_{m_\delta}u_\s y = a_{m_\delta}u_\s g\Gamma\in X- X_{\eta_X}$ and hence there exists some $v\in Ge_1\setminus\{0\}$ with $h(a_{m_\delta}u_\s y) = \|a_{m_\delta}u_\s v\|^{-\delta}$ and, by Proposition \ref{Prop:comparison}, this is comparable to $\inj(a_{m_\delta}u_\s y)^{-\delta}$.

    Hence, by combining the above and using Corollary \ref{Cor:LA}, we deduce
    \begin{align*}\int_{B_1 ^U} \inj(a_{m_\delta}u_\s y)^{-\delta} d\s &\le\sigma \int h(a_{m_\delta}u_\s y)^\delta d\s =\int_{B_1 ^U}\|a_{m_\delta}u_\s v\|^{-\delta}d\s\\
    &=\sigma^{-1}e^{-1}\|v\|^{-\delta}  \le e^{-1}\inj(y)^{-\delta} .
    \end{align*}

    Hence, in general, we have $$\inj(a_{m_\delta}u_\s y)^{-\delta} d\s \le e^{-1}\inj(y)^{-\delta} + O(1)$$

\end{proof}

