\section{Quantitative non-divergence and a return lemma}

In this section we use the linearization from the previous section to prove a quantitative non-divergence result.

\begin{lem}\label{lem:returnrepresentation}
    Let $\eta>0$ and let $B\subseteq B^U _1$ be a ball of Lebesgue measure at least $\eta$ and $v\in\mathbb R^{n+1}$. There exists $\constE\label{C:returnrepresentation}=\ref{C:returnrepresentation}(\dim(G))$ so that for $\rho>0$ and $v\in G e_1$ we have
    $$|\{\s\in B:\|a_tu_\s v\|\le e^t\eta^2\|v\|\rho^2\}|\le \ref{C:returnrepresentation} \rho |B|.$$
\end{lem}

\begin{proof}
    We note that $\rho$ is chosen to be small compared to absolute constants.

    Write $v= v_1+c_ve_n$ where $c_v\in \mathbb R$ and $v_1\in e_n^\perp$. Note $Q_0(e_1)=0$ and so for any $g\in G$, we have $Q_0(ge_1)=0$ and, in particular, $Q(v)=0.$ By Lemma $\ref{Lem:Lowerbound}$, we have $\|v_1\|\ge c\|v\|$ for some absolute constant $c\in(0,1).$ Note for $h\in H$, $hv=ce_{n}+hv_1$ and recall that we can identify $e_n^\perp$ with $\mathfrak r$ by Equation \ref{eqn:  compliment isomorphism} and so we can refer to $v_1$ as $Z=Z(r_1,\c,r_2)\in\mathfrak r$. 
    By Shah \cite{MR1403756}, the polynomial function $\xi_\s(Z)$ (see Equation \ref{eqn:xi_s}) satisfies
    $$\sup_{\s\in B}|\xi_\s(Z)|\ge 16k\eta^2\|Z\|$$
    for some absolute $k>0.$

    Let
    $$B(Z,\alpha)=\{\s\in B:|\xi_\s(Z)|\le k\alpha \eta^2\|Z\|\}$$

    By Proposition \ref{Remez}, $|B(Z,\alpha)|\le n \alpha^{1/2}|B|$.



    Now let $\alpha = c^{-1}k^{-1}\rho^2$ where we choose $\rho$ shortly.  Then we conclude $$|B(v_1,\alpha)|\le n\alpha^{1/2}|B|=nc^{-1/2}\rho|B|.$$

    Now we choose $\rho$ so that $\alpha\le 1$ and $nc^{-1/2}\rho<1.$

    Let $\s \in B -B(v_1,
    \alpha)$ so that
    $$|\xi_\s(v_1)|\ge kc^{-1}\eta^2\rho^2\|v_1\|.$$

    Then by noting that $a_t$ expands the first term of $v_1 = Z(r_1,\c,r_2)$ by $e^t$, we see
    \begin{align*}
        e^t\eta^2\rho^2\|v\|&\le e^tc^{-1}\eta^2\rho^2\|v_1\|\\
        &\le e^t|\xi_\s(v_1)|\\
&        \le\|a_tu_\s v_1\|\le \|a_tu_\s v\|
    \end{align*}

    so that the claim holds by taking $\ref{C:returnrepresentation}=nk^{-1}c^{-1/2}$.
\end{proof}

This allows us to show that points return to the thick part after using $U$ to move them into a general position where they can be expanded by the diagonal. 

\begin{prop} \label{prop:nondiv}
    There exists $\constE\label{C:nondiv}=\ref{C:nondiv}(\dim(G), \ref{C:returnrepresentation})\ge1$ with the following property. Let $0<\alpha<1$, $0<\eta\le1$, and $x\in X$. Let $B\subseteq B^U _1$ be ball with Lebesgue measure at least $\eta$. Then 
    $$|\{\s\in B:\inj(a_t u_\s x)<\alpha^2\}|<\ref{C:nondiv}\alpha
    |B|$$
    so long as $t\ge |\log(\eta^2\inj(x))|+\ref{C:nondiv}$.
\end{prop}
\begin{proof}
    Let $x=g\Gamma\in X$. Let $\gamma\in\Gamma$ and $1\le i\le q$. 
    By Proposition \ref{Prop:comparison}, it suffices to work with the height function. By Proposition \ref{lem:returnrepresentation}, 
    \begin{equation}\label{eqn: prop3.3conseq}
    |\{\s\in B:\|a_tu_s g\gamma v_i\|\le e^t\eta^2\rho^2\|g\gamma v_i\|\}|\le \ref{C:returnrepresentation}\rho|B|    
    \end{equation}
for every $\rho\in(0,1)$. Let $\rho_0=.1\ref{C:returnrepresentation}^{-1}$. We will use the value $\rho=\rho_0$ in Equation \eqref{eqn: prop3.3conseq}. As such, by the above and Proposition \ref{Prop:comparison},  there exists some $\s\in B$ so that 
$$\|a_tu_\s g\gamma v_i\|\ge e^t\eta^2\rho_0^2\|g\gamma v_i\|\ge e^t \eta^2\rho_0 ^2\sigma^{-1}\inj(x).$$

  Now let $t\ge |\log(\eta^2\inj(x))|+\ref{C:nondiv}$  so the previous equation simplifies to
$$\|a_tu_\s g\gamma v_i\|\ge e^{\ref{C:nondiv}}\rho_0^2\sigma^{-1}.$$
This implies that for  $\ref{C:nondiv}\ge \max\{\ln(\sigma),4n\rho_0 ^{-1}\}$  we have
$$\|a_tu_\s g\gamma v_i\|\ge \rho_0^2$$
and so $\sup_{\s\in B}h(a_tu_\s x)^{1/2}\le \rho_0^{-1}$.


Then by Proposition \ref{Remez} and our choice of $\ref{C:nondiv}$ we have,
    $$|\{\s\in B:\inj(a_t u_\s x)<\alpha^2\}|<4n\rho_0 ^{-1}\alpha
    |B|\le \ref{C:nondiv}\alpha|B|.$$\end{proof}
As a corollary, we can guarantee returns to the thick part. See also Mohammadi-Oh \cite{MR4556221} for the case $G=\SO(3,1)$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{cor}\label{cor:returnlemma}
    There exists $\eta_X\in(0,1)$ depending on $X$ so that the following holds. For every $x\in X$, there exists $\s\in B_1 ^U$ so that $a_tu_\s\in X_{\eta_X}$ where $t=|\log(\inj(x))|+\ref{C:nondiv}.$

\end{cor}
\begin{proof}
 Apply the previous proposition with $B=B_1 ^U$, $\eta=1$,  and $\alpha\le.01\ref{C:nondiv}^{-1}$. Then, by potentially making $\eta_X\le \alpha^2$ we have
 $$|\{s\in B:a_tu_\s x \in X_{\eta_X}\}|\ge.99|B|.$$
\end{proof}



