\section{Sheets and Margulis functions}



In this section, we consider constructions that will eventually allow us to get one-dimensional energy as in Proposition \ref{prop:input}. Similar ideas were used in Mohammadi-Oh \cite{MR4556221} and  Lindenstrauss--Mohammadi \cite{MR4549089} for $\SL(2,\mathbb C)$ and $\SL(2,\mathbb R)\times \SL(2,\mathbb R)$ and \cite{SS22} for certain semisimple Lie groups. While $\SO(n,1)$ falls under the framework of \cite{SS22}, we have a concrete application in mind and so we need a strengthening of certain constants that appear in \cite{SS22}. As such, we include certain proofs from \cite{SS22} for completeness.



%%%%%%%%%%%%%%%%%%%%%%%sheets
\begin{remark}In this remark we collect a few constants that will be useful in the following arguments. 

By shrinking $\eta_X$ potentially, we have that since the exponential map $\Lie(G)\to G$ is a local diffeomorphism, there exists some absolute constant $\sigma_0>1$ so that for all $w\in B ^{\Lie(G)} _{\eta_X} (0)$ and $x\in X$,
$$\sigma_0 ^{-1}\|w\|\le d(x,\exp(w)x)\le \sigma_0 \|w\|.$$

Since $B_1 ^U$ is compact, there exists some absolute constant $\sigma_U>1$ such that $\|\Ad(u)v\|\le\sigma_U\|v\|$ for all $v\in \Lie(G)$ and $u\in B_1 ^U$.
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{defn} \label{def: sheets}

Let $\varepsilon\in(0,1)$. Recall the decomposition $\Lie(G)=\Lie(H)\oplus \mathfrak r$. For $Y$ a closed $H$-orbit and $x\in X$, define
$$I_Y(x,\varepsilon)=\{w\in\mathfrak{r}:0<\|w\|<\varepsilon \inj(x), \exp(w)x\in Y\}.$$

We will work with $I_Y(x):=I_Y(x,\varepsilon_0)$ where $\varepsilon_0:=\min\{e^{-\kappa\sigma_U-\ref{C:nondiv}}\eta_X,\frac{\sigma_0 ^{-1}}{2},\frac{\beta_0}{2}\}$ and $\kappa$ satisfies $\sigma_Ue^{-\kappa \sigma_U}<\frac{\sigma_0 ^{-1}}{2}$.
\end{defn}

The following proposition, which is essentially Proposition 25 of \cite{SS22} applied to $G=\SO(n,1)$, shows that the number of nearby sheets is controlled by the volume of $Y$. We include the proof for completeness. See also Lemma 9.2 of Lindenstrauss--Mohammadi \cite{MR4549089} and Lemma 8.13 of Mohammadi-Oh \cite{MR4556221} for special cases.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lem}\label{Lem:SheetsBound}
    There exists an absolute constant $\constE\label{C:sheets}$ such that $$\#I_Y(x)\le \ref{C:sheets}\vol(Y)$$ for every $x\in X.$
\end{lem}

\begin{proof}


We first get a preliminary bound for points $\{x\in X|\inj(x)>Q\}$.

Let $\varepsilon>0$ and $w\in I_Y(x,\varepsilon)$. Then, 
$$d(x,\exp(w)x)\le \sigma_0 \|w\|\le \sigma_0 \varepsilon_0\inj(x)<\frac{1}{2}\inj(x)$$
for any $\varepsilon<\frac{\sigma_0 ^{-1}}{2}$. Hence, $\inj(\exp(w)x)\ge \frac{\inj(x)}{4}$ and so the balls 
$$(B_Y(\exp(w)x,\inj(x)/4))_{w\in I_Y(x)}$$
are disjoint by using that we have a local product structure at small enough scales. Thus,
$$\#I_Y(x,\varepsilon)\cdot \vol(B_H(e,\inj(x)/4))\le \vol(\sqcup_{w\in I_Y(x)} B_Y(\exp(w)x,\inj(x)/4))\le \vol (Y).$$
We obtain,
\begin{align*}
    \#I_Y(x,\varepsilon)&\le \vol(B_H(e,\inj(x)/4))^{-1}\cdot\vol(Y)\\
    &= 4^{\dim(H)}\inj(x)^{-\dim(H)}\cdot\vol(Y)
\end{align*} 
 In particular, by choosing $Q$ small enough we have $X_{\eta_X}\subset \{x\in X|\inj(x)>Q\}$ and so for any $x\in X_{\eta_X}$, we have that the injectivity radius is bounded from below and we obtain the preliminary bound on the number of sheets,
\begin{equation}\label{SheetsonCpt}
    \#I_Y(x,\varepsilon)\ll \vol(Y)
\end{equation}
for any $\varepsilon<\frac{\sigma_0 ^{-1}}{2}$.

Suppose $x\in X-X_{\eta_X}$. By the Return Lemma (Corollary \ref{cor:returnlemma}), we have some $\mathbf{s}\in B_1 ^U$ such that $a_tu_{\mathbf{s}}x\in X_{\eta_X}$ where $t=|\log(\inj(x))|+\ref{C:nondiv}$. Hence, for all $\|w\|<\varepsilon_0\inj(x)$ we have
$$\|\Ad(a_t u_{\mathbf{s}})w\|\le\sigma_U e^{t}\|w\|=\sigma_Ue^{\ref{C:nondiv}}\inj(x)^{-1}\|w\|\le\sigma_Ue^{-\kappa \sigma_U}\inj(a_tu_{\mathbf{s}}x)$$
where we have used $\varepsilon_0\le e^{-\kappa\sigma_U-\ref{C:nondiv}}\eta_X\le e^{-\kappa\sigma_U-\ref{C:nondiv}}\inj(a_tu_{\mathbf{s}}x).$
Since $\kappa$ satisfies $\sigma_Ue^{-\kappa \sigma_U}<\frac{\sigma_0 ^{-1}}{2}$ and we have $Y$ is invariant under $H$, then we have shown for any $w\in I(x)$, that $\Ad(a_tu_{\mathbf{s}})w\in I(a_tu_{\mathbf{s}}x,\varepsilon)$ for some $\varepsilon<\frac{\sigma_0 ^{-1}}{2}$.

In particular, the map $w\mapsto a_tu_{\mathbf{s}}w$ from $I(x)$ to $I(a_tu_{\mathbf{s}}x,\varepsilon)$ is injective for some $\varepsilon<\frac{\sigma_0 ^{-1}}{2}$. Hence, for any $x\in X-X_{\eta_X}$
$$\#I(x)\le \#I (a_tu_{\mathbf{s}}x,\varepsilon)\ll \vol(Y)$$
where the last inequality is from Equation (\ref{SheetsonCpt}) and the fact that $a_tu_{\mathbf{s}}x\in X_{\eta_X}$. We define $\ref{C:sheets}$ to be the max of the implicit constant from this last equation and the implicit constant from Equation \ref{SheetsonCpt}.
\end{proof}

%%%%%%%%%%%%%%%Margulis function %%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{defn}
    Let $\delta\in(0,1)$ and define $f_Y:Y\to [0,\infty)$

$$f_Y(y)=\begin{cases}\sum_{v\in I_Y(y)}\|v\|^{-\delta}&\text{if }I_Y(y)\ne\emptyset\\
\inj(y)^{-\delta} &\text{otherwise}
\end{cases}$$
\end{defn}

We will need the following log continuity of $f_Y$ on the compact part. See also Proposition 36 of \cite{SS22}.

\begin{prop}\label{rmk:logctyofMF}
    The function $f_Y$ is log continuous on the compact part $X_\eta$. That is, for any $K\subset G$ and $y\in Y\cap X_\eta$, there exists $\sigma_f=\sigma_f(K,X_\eta)\ge1$ such that
    \begin{equation}\label{eqn:logctyofMF}
        \sigma_f ^{-1}f_Y(y)\le f(ky)\le \sigma_f f_Y(y)
    \end{equation}



\end{prop}

\begin{proof}

 Since $K\subset G$ is compact, there exists $R_K\ge1$ so that 
 $$R_K ^{-1}\|v\|\le\|\Ad(k)v\|\le R_K \|v\|$$
 for every $k\in K$ and $v\in Ge_1\setminus\{0\}$.
Let $\delta\in(1/2,1)$ and $y\in Y$. 

Let $\varepsilon= R_K ^{-1}\varepsilon_0\inj(y)$.

Note that if $I_Y(ky)$ is empty, then, $f_Y(k y)=\inj(k y)^{-\delta}$.

If $I_Y$ is not-empty, then for any $k\in K$,
$$f_Y(k y) = \sum_{v\in I_Y(k y),\|v\|<\varepsilon}\|v\|^{-\delta} + \sum_{v\in I_Y(k y),\|v\|\ge \varepsilon}\|v\|^{-\delta}.$$
Focusing on the second term, we have by Lemma \ref{Lem:SheetsBound},
$$\sum_{v\in I_Y(k y),\|v\|\ge \varepsilon}\|v\|^{-\delta}\le \ref{C:sheets}R_K^\delta\varepsilon_0 ^{-\delta}\inj(y)^{-\delta}\vol(Y) \ll_K \inj(k y)^{-\delta}\vol(Y)$$
where we have used the log continuity of $\inj$ in the last line and ``$\ll_K$" indicates an implicit constant that depends on $K$. 

Focusing on first term of the sum, we note that for any $v\in I_Y(k y)$ with $\|v\|<\varepsilon$ we have $\|\Ad(k) v\|<R_K\varepsilon=\varepsilon_0\inj(y)$ and so $k^{-1}v\in I_Y(y)$. Thus, setting $v'=k^{-1}v$, we have
$$\sum_{v\in I_Y(k y),\|v\|<\varepsilon}\|v\|^{-\delta} \le \sum_{v'\in I_Y( y)}\|k v'\|^{-\delta}.$$

    We now have a bound of the form
    $$    f_Y(k y)\le \sum_{v'\in I_Y( y)}\|\Ad(k) v'\|^{-\delta} + O_K(\inj(ky)^{-\delta}\max\{\vol(Y),1\})$$
    where the implicit constant only depends on $K$ and $\ref{C:sheets}$. In fact, there is a uniform lower bound on how small the volume of a closed orbit can be (Lemma 37 of \cite{SS22}) and so we may assume the second term is of the form $O_K(\inj(k y)^{-\delta}\vol(Y))$.
    We obtain
    \begin{equation}\label{eqn:bound on MF before avg}
        f_Y(k y)\le \sum_{v'\in I_Y( y)}\|\Ad(k) v'\|^{-\delta} + O_K(\inj(ky)^{-\delta}\vol(Y))
    \end{equation}    
    This, combined with $f_Y\ge1$, bound on $\|\Ad(k)v\|$, and log-continuity of $\inj$ (see Remark \ref{Rem:LogCty}) yield
    $$ f_Y(k y)\le \left(R_K ^\delta  + O_K(\inj(y)^{-\delta}\vol(Y)\right)f_Y(y)$$
    where we have absorbed the constant from log-continuity of $\inj$ into $O_K$.

    By using that $y\in X_\eta$, the proof is finished for the upper bound. The lower bound is similar.
\end{proof}

We will use a bound on the integral of $f_Y$ to obtain coarse dimension one in the next section. While the constant appearing in the following theorem depends on $\delta$, we remark that we will fix a $\delta$ close to 1 in the proof of the main results.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{thm}\label{thm:VolBound}
    There exists a  constant $\constE\label{C:integrable}=\ref{C:integrable}(\delta,\ref{C:sheets})>0$ such that
    $$\int_Y f_Y(y)\,d\mu_Y(y)\le \ref{C:integrable}\vol(Y).$$  
\end{thm}


\begin{proof}

We first begin by showing $f_Y$ satisfies a Margulis inequality (see Equation~\eqref{eqn:iterateMI2}). 

Let $K$ denote the compact subset $ \{(a_{m_\delta}u_\s) ^{\pm1}:\s\in B_1 ^U\}$ and note there exists some $R=R(\delta)\ge 1$ with $\|\Ad(k)v\|\le R_\delta\|v\|$ for any $v\in Ge_1\setminus\{0\}$ and $k\in K$ . We note that $R_\delta\to\infty$ as $\delta\to1$. 

Let $\delta\in(1/2,1)$ and $y\in Y$. 

Then, letting $k=a_{m_\delta}u_\s$ and using Equation \ref{eqn:bound on MF before avg} we obtain
\begin{equation}\label{eqn preint}
    f_Y(a_{m_\delta}u_\s y)\le \sum_{v'\in I_Y( y)}\|\Ad(a_{m_\delta}u_\s) v'\|^{-\delta} + O_\delta(\inj(a_{m_\delta}u_\s y)^{-\delta}\vol(Y))
\end{equation}        
Denote by $A$ the integral operator defined by $$A(\varphi)(y)=\int_{B_1 ^U}\varphi(a_{m_\delta}u_\s y)d\s.$$
Integrating Equation \ref{eqn preint} over $B_1 ^U$ and applying Corollary \ref{Cor:LA}, we obtain
\begin{equation}\label{Eqn:MargulisInequality}
    A( f_Y( y))\le e^{-1}f_Y(y)+O(A(\inj(y)^{-\delta})\vol(Y))
\end{equation}
  and the implicit constant depends only on $K=K(\delta)$ and $\ref{C:sheets}$. By iterating this operator we deduce
 \begin{equation}\label{eqn:iterateMI}
     A^{(n)}(f_Y)(y)\le e^{-n}f_Y(y)+E_1\vol(Y)\sum_{j=1}^n e^{j-n}A^{(j)}(\inj(y)^{-\delta})
 \end{equation}
 where $E_1$ depends only on $K=K(\delta)$ and $\ref{C:sheets}$.  By iterating Corollary \ref{Cor:LAInj}, we have $$A^{(n)}(\inj^{-\delta}(y))\le e^{-n}\inj^{-\delta}(y)+B$$
  where $B$ depends only on $X$. Combining this with Equation~\eqref{eqn:iterateMI}, we deduce
   \begin{equation}\label{eqn:iterateMI2}
     A^{(n)}(f_Y)(y)< e^{-n}f_Y(y)+E_1\vol(Y)n e^{-n}\inj(y)^{-\delta} + 2BE_1\vol(Y)
 \end{equation}

That inequalities such as the above imply integrability is now standard, see e.g.  Lemma 11.1 of \cite{MR3418528}, Proposition 40 of \cite{SS22}, or Lemma 7.3 of Mohammadi-Oh  \cite{MR4556221}. We include a short proof for completeness. 

 Equation \eqref{eqn:iterateMI2} implies, $$\limsup_nA^{(n)}(f_Y)(y)\le 1+2E_1\vol(Y)B.$$
 Note that the operator norm of $A$ is bounded. This together with the fact that $(H,\mu_Y)$ is mixing implies that $\mu_Y$ is ergodic with respect to the operator $A$. Thus, by the Chacon-Ornstien theorem, for every $\varphi\in L^1(Y,\mu_Y)$ and $\mu_Y$-a.e. $y\in Y$, we have $\frac{1}{N+1}\sum_{n=0}^NA^{(n)}(\varphi)(y)\to\int \varphi d\mu_Y$. 

 For every $k\in\mathbb N$, let $\varphi_k:=\min\{k,f_Y\}$. There exists a full measure set $Y_0$ so that for every $y\in Y_0$ and every $k$, there exists some $N_{k,y}$ so that if $N\ge N_{n,y}$, then $\frac{1}{N+1}\sum_{n=0}^NA^{(n)}(\varphi_k)(y)\ge.5\int\varphi_kd\mu_Y$.

 Let $y\in Y_0$. Then the above estimate and the bound on the $\limsup A^{(n)}$ imply that $
 \int \varphi_k d\mu_Y\le 2(1+2E_1\vol(Y)B)$ for all $k$. Hence, by the monotone convergence theorem, we conclude $$\int f_Yd\mu_Y\le 2(1+2E_1\vol(Y)B).$$
 This implies a bound of the form $\ref{C:integrable}\vol(Y)$ for some $\ref{C:integrable}=\ref{C:integrable}(\delta,\ref{C:sheets}).$



