\begin{proof}[Proof of Theorem \ref{thm:ProjSO(n,1)}]\label{sec:proof proj}
First note that replacing $F$ by $\frac{1}{b_1}F$, we may assume $b_1=1$.  

Recall from~\S\ref{Preliminaries} that we may identify $\mathfrak r$ with 
\[
\R^{n}=\{(r_1,\c, r_2): r_i\in \R, \c\in\R^{n-2}\},
\]
and that $U=\{u_{\bf s}: \s\in\R^{n-2}\}$. Moreover, by~\eqref{eqn:xi_s}, if we let $Z=Z(r_1,\c,r_2)$, then
\begin{equation}\label{eqn:xi_s'}
\xi_{\s}(Z)=\left(\Ad(u_\s)Z(r_1,\c,r_2)\right)^+:=(r_1+\s\cdot \c+r_2\|\s\|^2/2)
\end{equation}
Therefore, Theorem \ref{thm: main finitary} is applicable with $L(\s)=\s$ and $q(\s)=\frac{1}{2}\|s\|^2$. 

We may assume $b$'s are dyadic numbers, in particular, we put $b_0=2^{-k_0}$. 
Fix some $0<\varepsilon<\delta/100$, and let $k_1$ be so that 
\begin{equation}\label{eqn:choose ell1}
\hat C\varepsilon^{-A} \sum_{k=k_1}^{\infty} 2^{-\varepsilon k/10}< 0.01\bigl|B_1^U\bigr|
\end{equation}

Apply Theorem \ref{thm: main finitary} with $b=2^{k}$ for $k_1\leq k\leq k_0$  
Let $B=\bigcap_{k=k_1}^{k_0} B_{2^{-k}}$. 
Then Theorem~\ref{thm: main finitary} and~\eqref{eqn:choose ell1} imply that $|B_1^U\setminus B|\leq 0.01|B_1^U|$.

For every $u_{\bf s}\in B$, let $F_{\bf s}=\bigcap_{k=k_1}^{k_0}F_{2^{-k},{\bf s}}$.
Then by Theorem~\ref{thm: main finitary} and and~\eqref{eqn:choose ell1}, we have $\#(F\setminus F_{\bf s})\leq 0.01\cdot (\#F)$.
Moreover, for all $Z\in F_{\bf s}$ and all $k_1\leq k\leq k_0$
we have
\[
\#\{Z'\in F_{\bf s}: |\xi_{\bf s}(Z')-\xi_{\bf s}(Z)|\leq 2^{-\ell}\})\leq \hat C C  2^{-\varepsilon k_0}\cdot  2^{\delta k}\cdot (\# F).
\]

This implies Theorem \ref{thm:ProjSO(n,1)} with $B$, $F_{\bf s}$, and $C_{\varepsilon}=\hat C C 2^{1+k_2}$ --- note that since $0\leq\delta\leq 1$ and we have included the factor $2^{1+k_2}$ in the definition of $C_{\varepsilon}$, the above holds for all scales $b\geq 2^{-k_0}$ as claimed in the theorem. 
\end{proof} 
