\subsection{Proof of  Theorem~\ref{thm: MarstrandProj}}

In this section we prove Theorem~\ref{thm: MarstrandProj} to help motivate the statement and proof of Theorem~\ref{thm: main finitary}.

%It will be more convenient to work with $B:=\{{\bf s}\in\mathbb R^{n-2}: 1/2\leq \|{\bf s}\|\leq 1\}$. 
%The statement in Theorem~\ref{thm: main finitary} regarding $\{{\bf s}\in\mathbb R^{n-2}: \|{\bf s}\|\leq 1\}$ 
%follows from this as the estimate

We begin with an elementary lemma. For every $\s\in\R^{n-2}$, define 
\begin{equation}\label{eqn: def fs}
f_\s=f_{L,q,\s}:\R^n\to\R^3\quad\text{by}\quad f_\s(r_1,\c, r_2)= \Bigl(r_1, \c \cdot L(\s), r_2q(\s) \Bigr),
\end{equation}
where $L$ is a bijection of $\mathbb R^{n-2}$ and $q$ is a positive definite quadratic form on $\mathbb R^{n-2}$.


\begin{lem}\label{lem: transversality of ft}
There exists $\eta_0=\eta_0(q, L)\leq 0.01$ so that the following holds. 
Let $\ell\in\mathbb N$ and let $0<\eta<2^{-2\ell}\eta_0$. 
Then for all $Z, Z'\in\R^n$ satisfying $\norm{Z-Z'}=1$, we have   
\[
\absolute{\{\s\in \mathsf {Cyl}_\ell: \norm{f_\s(Z)-f_\s(Z')}\leq \eta\}}\ll \eta \absolute{\mathsf {Cyl}_\ell}
\]
where $\mathsf {Cyl}_\ell=\{\s\in\R^{n-2}: 2^{-\ell}\leq \norm{\s}\leq 2^{-\ell+1}\}$ and the implied constant depends on $L$ and $q$.
\end{lem}

\begin{proof}
    Let us write $Z=(r_1,\c, r_2)$ and $Z'=(r'_1,\c', r_2')$. Let us denote the set in the lemma by $S$. 
    If $S\neq \emptyset$, then there exists some $\s\in \mathsf {Cyl}_\ell$ so that 
    \[
    \norm{\Bigl(r_1-r'_1, (\c-\c')\cdot L(\s), (r_2-r'_2)q(\s)\Bigr)}\leq \eta.
    \]
    Thus $\absolute{r_1-r_1'}, \absolute{r_2-r_2'}q(\s)\leq \eta$. 
    Since $\s\in\mathsf {Cyl}_\ell$, we have $q(\s)\gg 2^{-2\ell}$, $\min_{\norm{\s}=1} \absolute{q(\s)}$. 
    These and $\norm{Z-Z'}=1$, thus imply
    \[
    \norm{\c-\c'}\gg 1.
    \]

    Altogether, either $S=\emptyset$ in which case the proof is complete, or we may assume $\norm{\c-\c'}\gg1$ and
    \[
    S\subset \{\s\in \mathsf {Cyl}_\ell: \norm{(\c-\c')\cdot L(\s)}\leq \eta\}.
    \]
    Since $\norm{\c-\c'}\gg 1$ and $\eta<2^{-2\ell}\eta_0$, the measure of the set on the right side of the above is $\ll\eta\absolute{\mathsf {Cyl}_\ell}$, where the implied constant depends on $L$ and $q$. 

    The proof is complete. 
\end{proof}


Recall, from Kaufman \cite{MR248779}, that the $\delta$-dimensional energy of a probability measure $\nu$ on $\R^d$ is defined by 
\[
\eng_\delta(\nu)=\iint\frac{\diff\!\nu(Z)\diff\!\nu(Z')}{\|Z-Z'\|^\delta}
\]
We also recall that that the supremum over all Borel probability measures $\nu$ on a set $A$ of the above quantity returns that $\delta$-capacity of $A$. Furthermore, the supremum over positive $\delta$-capacities yields the Hausdorff dimension of $A$.


\begin{lem}\label{lem: ft dim preserving}
 Let $0<\delta<1$. Let $\nu$ be a probability measure supported on $B_{\R^n}(0,1)$ which satisfies 
 \[
 \eng_\delta(\nu)\leq C
 \]
 for some $C\geq 1$. Then for every $\ell\in\mathbb N$ and all $R>0$, we have 
 \[
 \absolute{\{\s\in\mathsf{Cyl}_\ell: \eng_\delta(f_\s\mu)>R\}}\leq C'/R
 \]
 where $C'\ll \frac{2^{2\ell}C}{1-\delta}$. In particular, $\eng_\delta(f_\s\nu)<\infty$ for (Lebesgue) a.e.\ $\s$. 
\end{lem}

\begin{proof}
We recall the standard argument which is based on Lemma~\ref{lem: transversality of ft}. 
Since $\ell$ is fixed, we write $\mathsf{Cyl}$ for $\mathsf{Cyl}_\ell$.

Put $\nu_\s=f_\s\nu$. Using the definition of 
$\delta$-dimensional energy and Fubini's theorem, we have 
\begin{align*}
    \int_{\mathsf{Cyl}}\eng_\delta(\nu_\s)\diff\!\s&= \int_{\mathsf{Cyl}}\int_{\R^n}\int_{\R^n}\frac{\diff\!\nu(Z)\diff\!\nu(Z')}{\norm{f_\s(Z)-f_\s(Z')}^\delta}\diff\!\s\\
    &=\int_{\R^n}\int_{\R^n}\int_{\mathsf{Cyl}}\frac{\diff\!\s}{\norm{f_\s(Z)-f_\s(Z')}^\delta} \diff\!\nu(Z)\diff\!\nu(Z')
\end{align*}
Renormalizing with the factor $\norm{Z-Z'}^{\delta}$, we conclude that
\begin{equation}\label{eq: int energy mut}
\int_{\mathsf{Cyl}}\eng_\delta(\nu_\s)\diff\!\s=\int_{\R^n}\int_{\R^n}\int_{\mathsf{Cyl}}\frac{\diff\!\s}{\norm{\frac{f_\s(Z)-f_\s(Z')}{\norm{Z-Z'}}}^\delta}
\frac{\diff\!\nu(Z)\diff\!\nu(Z')}{\norm{Z-Z'}^\delta}.
\end{equation}
Since $\delta<1$, applying Lemma~\ref{lem: transversality of ft}, we conclude that
\[
\int_{\mathsf{Cyl}}  \norm{\frac{f_\s(Z)-f_\s(Z')}{\norm{Z-Z'}}}^{-\delta}\diff\!\s\ll \frac{2^{2\ell}}{1-\delta}.
\]
This,~\eqref{eq: int energy mut}, and $\eng_\delta(\nu)\leq C$ imply that   
\[
\int_B\eng_\delta(\nu_\s)\diff\!\s\ll2^{2\ell}\frac{\eng_\delta(\nu)}{1-\delta}\ll\frac{2^{2\ell}C}{1-\delta}.
\]
The claim in the lemma follows from this and the Chebyshev's inequality. 
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm: MarstrandProj}]
Let $s\in\R$ and $\s\in\R^{n-2}$. Then 
\begin{equation}\label{eq: decomp pi t}
\begin{aligned}
    \pi_{s\s}(r_1,\c, r_2)&=r_1+\c\cdot L(s\s)+r_2q(s\s)\\
    &=(1, s, s^2)\cdot f_\s(r_1,\c, r_2). 
\end{aligned}
\end{equation}

Let $\ell\in\mathbb N$ be arbitrary. Let $\cpct\subset B_{\R^n}(0,1)$ be a compact subset, and let  $\kappa=\min(1,\hdim \cpct)$. Let $0<\delta<\kappa$. 
By Frostman's lemma, there exists a probability measure $\nu$ supported on $\cpct$ and satisfying the following   
\[
\nu(B(Z, b))\leq  b^\delta \quad\text{for all $Z\in \cpct$}.
\]
Then by Lemma~\ref{lem: ft dim preserving}, applied with $\nu$, 
there exists a conull subset $\Xi_\delta\subset\mathsf{Cyl}_\ell$ so that  $\hdim(f_\s(\cpct))\geq \delta$ for all $\s \in\Xi_\delta$. Applying this with $\delta_n=\kappa-\frac{1}{n}$ for all $n\in\N$, we obtain a conull subset $\Xi\subset\mathsf{Cyl}_\ell$ so that 
\[
\hdim(f_\s(\cpct))\geq \kappa,\quad\text{for all $\s \in\Xi$.}
\]

Let $\s\in\Xi$, and set $\cpct_\s=f_\s(\cpct)$. Then by~\cite[Thm.\ 1.3]{PYZ}, see also~\cite{GGW}, for a.e.\ $s\in\R$, we have 
\[
\Bigl\{x_1+x_2s+x_3s^2: (x_1, x_2, x_3)\in \cpct_\s\Bigr\}\subset \R
\]
has dimension $\kappa$. This and~\eqref{eq: decomp pi t} complete the proof.  
\end{proof}



\subsection{Proof of Theorem~\ref{thm: main finitary}}\label{sec: proof of finitary}


In this subsection we turn to the proof of Theorem~\ref{thm: main finitary}. The proof is a discretized version of the argument we used to prove Theorem~\ref{thm: MarstrandProj}.

In what follows, it is more convenient to work with the uniform measure rather than the counting measure. 
Let  $\unm$ be the uniform measure on $F$. 
Our standing assumption is that for some $0< \delta\leq 1$ and some $C\geq 1$, we have  
\begin{equation}\label{eq: dimension alpha}
\unm(B_{\R^n}(Z,  b))\leq C b^\delta\qquad\text{for all $Z\in F$ and all $ b\geq  b_0$}.
\end{equation}

For a finitely supported probability measure $\nu$ on $\R^d$, define  
\[
\hat\eng_{\delta,\nu}:\R^d\to\R\quad\text{by}\quad \hat\eng_{\delta,\nu}(Z)=\int \norm{Z-Z'}_+^{-\delta}\diff\!\nu(Z')
\]
where $\norm{Z-Z'}_+=\max\Bigl(\norm{Z-Z'}, b_0\Bigr)$ for all $Z,Z'\in\R^d$ --- this definition is motivated by the fact that we are only concerned with scales $\geq  b_0$, 

\medskip

We recall the following standard lemma. 

\begin{lem}\label{lem: truncated energy}
    Let $\nu$ be a finitely supported probability measure on $\R^d$. Assume that for some $Z\in \R^d$ we have 
    \[
    \hat\eng_{\delta,\nu}(Z)\leq R.
    \]
    Then for all $ b\geq b_0$, we have 
    \[
    \nu(B_{\R^d}(Z, b))\leq R b^{\delta}.  
    \]
\end{lem}

\begin{proof}
We include the proof for completeness. 
Let $ b\geq  b_0$, then  
\begin{align*}
     b^{-\delta}\nu(B_{\R^d}(Z, b))&\leq \int_{B_{\R^d}(Z, b)}\norm{Z-Z'}_+^{-\delta}\diff\!\nu(Z')\\
    &\leq \int \norm{Z-Z'}_+^{-\delta}\diff\!\nu(Z')=\hat\eng_{\delta,\nu}(Z)\leq R,
\end{align*}
as it was claimed. 
\end{proof}

Fix some $0<\varepsilon<\delta/100$ for the rest of the argument. 
Recall from Theorem~\ref{thm: main finitary}, that for every $b\geq b_0$ we seek $B_b\subset B_{\mathbb R^{n-2}}(0,1)$ with $|B_{\mathbb R^{n-2}}(0,1)\setminus B_b|\ll\varepsilon^{-A} b^{\varepsilon/10}$. Thus we may replace $B_{\mathbb R^{n-2}}(0,1)$, with 
\begin{equation}\label{eq: define B}
B:=\{\s\in\R^{n-2}: b_0^{\varepsilon/8}\leq \|s\|\leq 1\}. 
\end{equation}

Moreover, since our estimates are allowed to depend on $\varepsilon$ polynomially, we will assume $b_0$ is small enough compare to $\varepsilon$.

For every $\s\in B_{\mathbb R^{n-2}}(0,1)$, let $\unm_\s=f_\s\unm$ 
where $f_\s:\R^n\to\R$ is as in~\eqref{eqn: def fs}. That is,
\begin{equation*}
f_\s(r_1,\c, r_2)= \Bigl(r_1, \c \cdot L(\s), r_2q(\s) \Bigr),
\end{equation*}
where $L$ and $q$ are as in the statement of the theorem, and we use the coordinates $\R^{n}=\{(r_1,\c, r_2): r_i\in\R, \c\in\R^{n-2}\}$.  

\begin{lem}\label{lem: ave trun egy proj}
    For every $Z\in F$,  we have 
    \[
    \int_B\hat\eng_{\delta,\unm_\s}(f_\s Z)\diff\!\s\ll Cb_0^{\varepsilon/2}
    \]
    where the implied constant depends on $L$ and $q$. 
\end{lem}

\begin{proof}
    Let $Z\in F$. By the definitions, we have 
    \[
    \int_B\hat\eng_{\delta,\unm_\s}(f_\s Z)\diff\!\s= \int_B\int \norm{f_\s Z-f_\s Z'}_+^{-\delta}\diff\!\unm(Z')\diff\!\s.
    \]
   Renormalizing with $\norm{Z-Z'}_+^{-\delta}$ and using Fubini's theorem, we have 
   \[
   \int_B\hat\eng_{\delta,\unm_\s}(f_\s Z)\diff\!\s=\int \int_B\frac{1}{\frac{\norm{f_\s Z-f_\s Z'}_+^\delta}{\norm{Z-Z'}_+^\delta}}\diff\!\s \norm{Z-Z'}_+^{-\delta}\diff\!\unm(Z').
   \]
  Without loss of generality, we will assume $b_0=2^{-k_0}$ for some $k_0\in\N$. For every $0\leq k\leq k_0-1$, let 
 \[
 F_k(Z)=\{Z'\in F: 2^{-k-1}< \norm{Z-Z'}\leq 2^{-k}\},
 \]
 and let $F_{k_0}(Z)=\{Z'\in F: \norm{Z-Z'}\leq 2^{-k_0}\}$. 

 For all $Z'\in F_{k_0}$, we have $1\leq \frac{\norm{f_\s Z-f_\s Z'}_+}{\norm{Z-Z'}_+}\ll_{L,q} 1$. Thus, 
   \begin{equation}\label{eq: contribution of Fk0}
   \int_{F_{k_0}}\int_B\frac{1}{\frac{\norm{f_\s Z-f_\s Z'}_+^\delta}{\norm{Z-Z'}_+^\delta}}\diff\!\s \norm{Z-Z'}_+^{-\delta}\diff\!\unm(Z')\ll \unm(F_{k_0})2^{k_0\delta}\ll C. 
   \end{equation}
   We now turn to the contribution of $F_k$ to the above integral for $k< k_0$. 
   If $Z'\in F_k$, for some $k<k_0$, then $\norm{Z-Z'}_+=\norm{Z-Z'}$ and we have 
   \begin{multline}\label{eq: contribution of Fk}
   \int_{F_{k}}\int_B\frac{1}{\frac{\norm{f_\s Z-f_\s Z'}_+^\delta}{\norm{Z-Z'}_+^\delta}}\diff\!\s \norm{Z-Z'}_+^{-\delta}\diff\!\unm(Z')=\\ 
   \int_{F_{k}}\int_B\frac{1}{\frac{\norm{f_\s Z-f_\s Z'}_+^\delta}{\norm{Z-Z'}^\delta}}\diff\!\s \norm{Z-Z'}^{-\delta}\diff\!\unm(Z'). 
   \end{multline}
   By Lemma~\ref{lem: transversality of ft} and the definition of $B$ in~\eqref{eq: define B}, we have 
   \[
   \int_B\frac{1}{\frac{\norm{f_\s Z-f_\s Z'}_+^\delta}{\norm{Z-Z'}^\delta}}\diff\!\s \leq \int_B\frac{1}{\norm{\frac{f_\s Z-f_\s Z'}{\norm{Z-Z'}}}^\delta}\diff\!\s\ll 2^{\varepsilon k_0/4}=b_0^{-\varepsilon/4}
   \]
   where the implied constant depends on $L$ and $q$. Thus 
   \[
   \eqref{eq: contribution of Fk}\ll 2^{-\varepsilon k_0/4}\unm(F_k)2^{k\delta}\ll C2^{-\varepsilon k_0/4}
   \]
   This and~\eqref{eq: contribution of Fk0} imply that 
   \[
   \int_B\hat\eng_{\delta,\unm_\s}(f_\s(Z))\diff\!\s\ll Ck_02^{-\varepsilon k_0/4}\leq C2^{-\varepsilon k_0/2}=Cb_0^{-\varepsilon/2}
   \]
   as we claimed. 
\end{proof}

\begin{prop}\label{prop: ft preserves dim}
    There exists $B'\subset B$ with 
    \[
    \absolute{B\setminus B'}\leq b_0^{\varepsilon}
    \]
    so that the following holds. For every $\s\in B'$, there exists $F_{\s}\subset F$ with 
    \[
    \unm(F\setminus F_\s)\leq  b_0^{\varepsilon}
    \]
    so that for every $Z\in F_\s$ and every $ b\geq  b_0$ we have 
    \[
    \unm_\s\Bigl(B_{\R^3}(f_\s(Z),  b)\Bigr)\ll b_0^{-3\varepsilon}\cdot  b^{\delta}
    \]
    where the implied constant depends on $C$. 
\end{prop}

\begin{proof}
  The proof is based on Lemma~\ref{lem: ave trun egy proj} and Chebychev's inequality as we now explicate. 

%  First note that we may assume $ b_0$ is small enough (polynomially in $\varepsilon$) so that 
%  \[
%   b_0^{-\varepsilon/10}>\absolute{\log b_0}
%  \]
%  otherwise the statement follows trivially. 

  By Lemma~\ref{lem: ave trun egy proj}, we have 
  \begin{equation*}
\int_B\hat\eng_{\delta,\unm_\s}(f_\s(Z))\diff\!\s\leq C'b_0^{-\varepsilon/2}.
  \end{equation*}
  where $C'\ll_{L,q} C$. 

  Averaging the above with respect to $\unm$, and using Fubini's theorem we have 
  \begin{equation*}
  \int_B\int\hat\eng_{\delta,\unm_\s}(f_\s(Z))\diff\!\unm(Z)\diff\!\s\leq C'b_0^{-\varepsilon/2}.
  \end{equation*}
  Let $B'=\{\s\in B: \int\hat\eng_{\delta,\unm_\s}(f_\s(Z))\diff\!\unm(Z)<C' b_0^{-2\varepsilon}\}$.
  Then by the above equation and Chebychev's inequality we have 
  \[
  \unm(B\setminus B')\leq  b_0^{\varepsilon}.
  \] 
  Let now $\s\in B'$, then 
  \begin{equation}\label{eq: int of energy for good t}
  \int\hat\eng_{\delta,\unm_\s}(f_\s(Z))\diff\!\unm(Z)\leq C' b_0^{-2\varepsilon}.
  \end{equation}
  Set 
  \[
  F_\s=\{Z\in F: \hat\eng_{\delta,\unm_\s}(f_\s(Z))< C' b_0^{-3\varepsilon}\}
  \]
  Then~\eqref{eq: int of energy for good t} and Chebychev's inequality again imply that $\unm(F\setminus F_\s)\leq  b_0^{\varepsilon}$.

  Altogether, for every $\s\in B'$ and $Z\in F_\s$, we have 
  \[
  \hat\eng_{\delta,\unm_\s}(f_{\s}(Z))=\int\norm{f_\s(Z)-f_\s(Z')}_+^{-\delta}\diff\!\unm_\s(Z')\leq C' b_0^{-3\varepsilon}
  \]
This and Lemma~\ref{lem: truncated energy} imply that for every $\s\in B'$ and $Z\in F_\s$, we have
\[
\unm_\s\Bigl(B_{\R^3}(f_\s(Z), b)\Bigr)\leq C' b_0^{-3\varepsilon}\cdot  b^\delta \quad\text{for all $ b\geq  b_0$}.
\]
The proof is complete. 
\end{proof}



We now turn to the proof of Theorem~\ref{thm: main finitary}. 
\begin{proof}[Proof of Theorem~\ref{thm: main finitary}]

We will use the following observation: for all $s\in\R$ and $\s\in\R^{n-2}$, we have  
\begin{equation}\label{eq: decomp pi t'}
\begin{aligned}
    \pi_{s\s}(r_1,\c, r_2)&=r_1+\c\cdot L(s\s)+r_2q(s\s)\\
    &=(1, s, s^2)\cdot f_\s(r_1,\c, r_2). 
\end{aligned}
\end{equation} 

Apply Proposition~\ref{prop: ft preserves dim} with $\varepsilon$ as in the statement of Theorem~\ref{thm: main finitary}. 
Let $B'\subset B$ be as in that proposition, and for every $\s\in B'$, let $F_{\s}$ be as in that proposition. 
Then we have 
\begin{equation}\label{eq: lem ave trun egy proj use}
\unm_\s\Bigl(B_{\R^3}(f_\s(Z), b)\Bigr)\leq C' b_0^{-3\varepsilon}\cdot b^\delta\quad\text{for all $Z\in F_\s$ and $ b\geq b_0$}.
\end{equation}

Let $K_\s= f_\s(F_\s)\subset \R^3$ and let $\rho_\s$ be the restriction of $\unm_t$ to $K_\s$ normalized to be a probability measure. Then~\eqref{eq: lem ave trun egy proj use} and the fact that $\unm(F\setminus F_{\s})\leq  b_0^{\varepsilon}$ imply that   
\begin{equation*}
\rho_\s\Bigl(B_{\R^3}(Y, b)\Bigr)\leq 2C'  b_0^{-3\varepsilon}\cdot b^\delta\quad\text{for all $Y\in K_\s$ and $ b\geq b_0$}.
\end{equation*}
This in particular implies that $K_\s$ and  $\rho_\s$ satisfy the conditions in~\cite[Thm.~B]{MR4549089}, see also \cite{PYZ} and \cite[Thm.\ 2.1]{GGW}. Apply~\cite[Thm.~B]{MR4549089} with $\varepsilon$; thus, there there exists $J_{ b,\s}\subset [0,2]$ with 
\[
\absolute{[0,2]\setminus J_{ b,\s}}\leq \bar C \varepsilon^{-A} b^{\varepsilon}
\]
and for all $s\in J_{ b,\s}$ there is a subset $K_{ b, \s, s}\subset K_{\s}$ with 
\[
\rho_\s(K_{\s}\setminus K_{ b, \s, s}) \leq \bar C\varepsilon^{-A} b^{\varepsilon}
\]
so that for all $Y\in K_{ b, \s, s}$, we have 
\[
\rho_\s\Bigl(\{Y'\in K_\s: \absolute{(1,s,s^2)\cdot (Y-Y')}\leq  b\}\Bigr)\leq \bar C b_0^{-3\varepsilon} \cdot b^{\delta-7\varepsilon};
\]

In view of the definition of $\rho_\s$ and~\eqref{eq: decomp pi t'}, we have the following. For every $\s\in B'$ 
and $s\in J_{ b,\s}$, put $F_{ b, s\s}=F\cap f^{-1}_\s(K_{ b, \s, s})$. Then 
\[
\#(F\setminus F_{ b, s\s})\leq  10\bar C\varepsilon^{-A} b^{\varepsilon}\cdot (\#F),
\]
and for every $Z\in F_{ b, s\s}$, we have 
\begin{equation}\label{eq: F b st}
\#\{Z'\in F_{ b, s\s}: \absolute{\pi_{s\s}(Z)-\pi_{s\s}(Z')}\leq  b\}\Bigr)\leq \bar C b_0^{-3\varepsilon} 
 b^{\delta- 7\varepsilon}. 
\end{equation}

We now use this to complete the proof. Indeed, let $B_ b\subset B$ be the set of $\s\in  B$ 
for which the following holds: there exists $F_{ b, \s}\subset F$ with
\[
\#(F\setminus F_{ b, \s})\leq 100\bar C\varepsilon^{-A} b^{\varepsilon}\cdot (\#F)
\] 
so that for all $Z\in F_{ b, \s}$ we have
\[
\#\{Z'\in F_{ b, \s}: \absolute{\pi_{\s}(Z)-\pi_{\s}(Z')}\leq  b\}\Bigr)\leq \bar C b_0^{-10\varepsilon} 
 b^{\delta}. 
\]
Then~\eqref{eq: F b st} implies that for every $\s'\in B'$ and $s\in J_{ b,\s'}$, we have $s\s'\in B_ b$, so long as $s\s'\in B$. In particular, we conclude that 
\[
\absolute{B\setminus B_ b}\ll \varepsilon^{-A} b^{\varepsilon}.
\] 
Since $b\geq b_0$, this and the definition of $B$, see~\eqref{eq: define B} imply that 
\[
\absolute{B_{\mathbb R^{n-2}}(0,1)\setminus B_ b}\ll \varepsilon^{-A} b^{\varepsilon/10}.
\] 
The proof is complete. 
\end{proof}


