We begin with an elementary lemma. For every $\s\in\R^{n-2}$, define 
\begin{equation}
f_\s=f_{L,q,\s}:\R^n\to\R^3\quad\text{by}\quad f_\s(r_1,\c, r_2)= \Bigl(r_1, \c \cdot L(\s), r_2q(\s) \Bigr),
\end{equation}
where $L$ is a bijection of $\mathbb R^{n-2}$ and $q$ is a positive definite quadratic form on $\mathbb R^{n-2}$.



\begin{lem}\label{lem: transversality of ft}
There exists $\eta_0=\eta_0(q, L)\leq 0.01$ so that the following holds. 
Let $\ell\in\mathbb N$ and let $0<\eta<2^{-2\ell}\eta_0$. 
Then for all $Z, Z'\in\R^n$ satisfying $\norm{Z-Z'}=1$, we have   
\[
\absolute{\{\s\in \mathsf {Cyl}_\ell: \norm{f_\s(Z)-f_\s(Z')}\leq \eta\}}\ll \eta \absolute{\mathsf {Cyl}_\ell}
\]
where $\mathsf {Cyl}_\ell=\{\s\in\R^{n-2}: 2^{-\ell}\leq \norm{\s}\leq 2^{-\ell+1}\}$ and the implied constant depends on $L$ and $q$.
\end{lem}

\begin{proof}
    Let us write $Z=(r_1,\c, r_2)$ and $Z'=(r'_1,\c', r_2')$. Let us denote the set in the lemma by $S$. 
    If $S\neq \emptyset$, then there exists some $\s\in \mathsf {Cyl}_\ell$ so that 
    \[
    \norm{\Bigl(r_1-r'_1, (\c-\c')\cdot L(\s), (r_2-r'_2)q(\s)\Bigr)}\leq \eta.
    \]
    Thus $\absolute{r_1-r_1'}, \absolute{r_2-r_2'}q(\s)\leq \eta$. 
    Since $\s\in\mathsf {Cyl}_\ell$, we have $q(\s)\gg 2^{-2\ell}$, $\min_{\norm{\s}=1} \absolute{q(\s)}$. 
    These and $\norm{Z-Z'}=1$, thus imply
    \[
    \norm{\c-\c'}\gg 1.
    \]

    Altogether, either $S=\emptyset$ in which case the proof is complete, or we may assume $\norm{\c-\c'}\gg1$ and
    \[
    S\subset \{\s\in \mathsf {Cyl}_\ell: \norm{(\c-\c')\cdot L(\s)}\leq \eta\}.
    \]
    Since $\norm{\c-\c'}\gg 1$ and $\eta<2^{-2\ell}\eta_0$, the measure of the set on the right side of the above is $\ll\eta\absolute{\mathsf {Cyl}_\ell}$, where the implied constant depends on $L$ and $q$. 

    The proof is complete. 
\end{proof}


In what follows, it is more convenient to work with the uniform measure rather than the counting measure. 
Let  $\unm$ be the uniform measure on $F$. 
Our standing assumption is that for some $0< \delta\leq 1$ and some $C\geq 1$, we have  
\begin{equation}\label{eq: dimension alpha}
