\begin{thm}\label{thm: MarstrandProj}
    Let $K\subset \R^n$ be a compact subset. Then for almost every $\s\in\R^{n-2}$ (with respect to the Lebesgue measure), we have 
    $$
    \hdim(\pi_\s(K))=\min(1,\hdim K)
    $$
\end{thm}

The following theorem can be thought of as a finitary version of Theorem \ref{thm: MarstrandProj}.


\begin{thm}\label{thm: main finitary}
    Let $0<\delta\leq 1$, and let  $0< b_0\leq1$. 
Let $F\subset B_{\R^n}(0,1)$ be a finite set satisfying the following: 
\[
\#(B_{\R^n}(X,  b)\cap F)\leq C\cdot  b^\delta\cdot (\# F)\quad\text{for all $X\in F$ and all $ b\geq  b_0$}
\]
where $C\geq 1$. 


\textcolor{blue}{the lower bound on $\|s\|$ is 1, can you modify the proof so that 0 is the lower bound:}Let $0<\varepsilon<\delta/100$.
For every $ b\geq  b_0$, there exists a subset 
$B_{ b}\subset B:=\{\s\in\R^{n-2}: 1\leq \norm{\s}\leq 2\}$ 
with 
\[
|B\setminus B_{ b}|\ll \varepsilon^{-A} b^{\varepsilon}
\]
so that the following holds. 
Let ${\bf s}\in B_{ b}$, then there exists $F_{ b,{\bf s}}\subset F$ with 
\[
\#(F\setminus F_{ b,{\bf s}})\ll  \varepsilon^{-A} b^{\varepsilon}\cdot (\# F)
\]
such that for all $X\in F_{ b,{\bf s}}$, we have 
\[
\#\Bigl(\{X'\in F_{ b, \s}: |\pi_{\bf s}(X')-\pi_{\bf s}(X)|\leq  b\}\Bigr)\ll C  b_0^{-10\varepsilon}\cdot  b^{\delta}\cdot (\# F),
\] 
where $A$ is absolute and the implied constants depend on $L$ and $q$. 
\end{thm}

Clearly the above theorem implies Theorem \ref{thm:ProjSO(n,1)} by taking $L$ to be the identity map, $q(\s)=\frac{1}{2}\|s\|^2$, and (in view of Proposition \ref{prop:input} and Remark \ref{rem:coarsedim} ) $b_0 = \vol(Y)^{-1}$ .

 The remainder of the section is to prove the above theorems. The most difficult case of the above theorems is arguably the case $n=3$, which was studied in~\cite{kenmki2017marstrandtype, PYZ} using fundamental works of Wolff and Schlag~\cite{Wolff, Schlag} --- see also~\cite{GGW} for a different approach to a more general problem in the same vein. Indeed when $n>3$, it is plausible that one may deduce the Theorem~\ref{thm: main finitary} using techniques of~\cite{SchPr} more directly; we, however, take a slightly different route which is a hybrid of these two methods.  


 Recall that the classical Marstrand projection theorem states that for a compact subset $K\subset\R^n$ and for a.e.\ $\v\in\mathbb S^{n-1}$
\begin{equation}\label{eq: Marstrand}
\hdim{\rm p}_{\v}(K)=\min(1,\hdim K),      
\end{equation}

where ${\rm p}_\v(X)=X\cdot \v$ is the orthogonal projection in the direction of $\v$. Analogous statements hold more generally for orthogonal projection into a.e.\ $m$-dimensional subspace, with respect to the Lebesgue measure on ${\rm Gr}(m, n)$.  

The question of obtaining similar results as in~\eqref{eq: Marstrand} where $\v$ is confined to a proper Borel subset $B\subset \mathbb S^{n-1}$ has also been much studied, e.g., by Mattila, Falconer, Bourgain and others. Note, however, that without further restrictions on $B$,~\eqref{eq: Marstrand} fails: e.g., if 
\[
B=\{(\cos t, \sin t, 0): 0\leq t\leq 2\pi\}
\] 
is the great circle in $\mathbb S^2$ and $K$ is the $z$-axis, then ${\rm p}_\v(K)=0$ for every $\v\in B$. 

It was conjectured by F\"assler and Orponen~\cite{FaOr} that these are essentially the only type of obstructions; more precisely, they conjecture that if $\gamma:[0,1]\to\mathbb S^2$ is a curve so that for all $\{\gamma(t),\gamma'(t),\gamma''(t)\}$ span $\R^3$ for all $t$, then for a.e.\ $t\in[0,1]$, 
\[
\hdim{\rm p}_{\gamma(t)}(K)=\min(1,\hdim K).
\]
This conjecture was recently proved by~\cite{PYZ}; see also the earlier work \cite{kenmki2017marstrandtype} which relies on similar techniques as~\cite{PYZ}, and the more recent work \cite{GGW} which uses different techniques --- a major difficulty here is the failure of transversality in sense of~\cite{SchPr}. 


Theorem~\ref{thm: MarstrandProj} can be proved using the finitary version Theorem~\ref{thm: main finitary}. However, 
for the convenience of the reader, we present a self contained proof of Theorem~\ref{thm: MarstrandProj}. This will also help explain the main idea of the proof of Theorem~\ref{thm: main finitary}. 

\medskip

For every $\s\in\R^{n-2}$, define 
\begin{equation}
f_\s=f_{L,q,\s}:\R^n\to\R^3\quad\text{by}\quad f_\s(r_1,\c, r_2)= \Bigl(r_1, \c \cdot L(\s), r_2q(\s) \Bigr),
\end{equation}
where $L$ is a bijection of $\mathbb R^{n-2}$ and $q$ is a positive definite quadratic form on $\mathbb R^{n-2}$.



\begin{lem}\label{lem: transversality of ft}
There exists $\varepsilon_0=\varepsilon_0(q, L)\leq 0.01$ so that the following holds. 
Let $0<\varepsilon<\varepsilon_0$. 
Let $X, X'\in\R^n$ satisfy that $\norm{X-X'}=1$. Then   
\[
\absolute{\{\s\in B: \norm{f_\s(X)-f_\s(X')}\leq \varepsilon\}}\ll \varepsilon
\]
where $B=\{\s\in\R^{n-2}: 1\leq \norm{\s}\leq 2\}$ and the implied constant depend on $L$ and $q$.    
\end{lem}

\begin{proof}
    Let us write $X=(r_1,\c, r_2)$ and $X'=(r'_1,\c', r_2')$. Let us denote the set in the lemma by $S$. 
    If $S\neq \emptyset$, then there exists some $\s\in B$ so that 
    \[
    \norm{\Bigl(r_1-r'_1, (\c-\c')\cdot L(\s), (r_2-r'_2)q(\s)\Bigr)}\leq \varepsilon.
    \]
    Thus $\absolute{r_1-r_1'}, \absolute{r_2-r_2'}q(\s)\leq \varepsilon\leq 1/10$. This and $\norm{X-X'}=1$ imply 
    \[
    \norm{\c-\c'}\gg 1
    \]
    where the implied constant depends on $\min_{\norm{\s}=1} \absolute{q(\s)}$. 

    Altogether, either $S=\emptyset$ in which case the proof is complete, or we may assume $\norm{\c-\c'}\gg1$ and
    \[
    S\subset \{\s\in B: \norm{(\c-\c')\cdot L(\s)}\leq \varepsilon\}.
    \]
    Since $\norm{\c-\c'}\gg 1$, the measure of the set on the right side of the above is $\ll\varepsilon$, where the implied constant depends on $L$ and $q$. 

    The proof is complete. 
\end{proof}

Given a compactly supported probability measure $\mu$ on $\R^d$, we let 
\[
\eng_\delta(\mu)=\iint\frac{\diff\!\mu(X)\diff\!\mu(X')}{\|X-X'\|^\delta}
\]
denote the $\delta$-dimensional energy of $\mu$. We recall that that the supremum over all Borel probability measures $\mu$ on a set $A$ of the above quantity returns that $\delta$-capacity of $A$. Furthermore, the supremum over positive $\delta$-capacities yields the Hausdorff dimension of $A$.

\textcolor{blue}{the lower bound on $\|s\|$ is 1, can you modify the proof so that 0 is the lower bound:}\begin{lem}\label{lem: ft dim preserving}
 Let $0<\delta<1$. Let $\mu$ be a probability measure supported on $B_{\R^n}(0,1)$ which satisfies 
 \[
 \eng_\delta(\mu)\leq C
 \]
 for some $C\geq 1$. 
 Then for every $R>0$, we have 
 \[
 \absolute{\{\s\in\R^{n-2}: 1\leq \norm{\s}\leq 2, \eng_\delta(f_\s\mu)>R\}}\leq C'/R
 \]
 where $C'\ll \frac{C}{1-\delta}$. In particular, $\eng_\delta(f_\s\mu)<\infty$ for (Lebesgue) a.e.\ $\s$. 
\end{lem}

\begin{proof}
We recall the standard argument which is based on Lemma~\ref{lem: transversality of ft}. Let $B=\{\s\in\R^{n-2}: 1\leq \norm{\s}\leq 2\}$.

Put $\mu_\s=f_\s\mu$. Using the definition of 
$\delta$-dimensional energy and Fubini's theorem, we have 
\begin{align*}
    \int_B\eng_\delta(\mu_\s)\diff\!\s&= \int_B\int_{\R^n}\int_{\R^n}\frac{\diff\!\mu(X)\diff\!\mu(X')}{\norm{f_\s(X)-f_\s(X')}^\delta}\diff\!\s\\
    &=\int_{\R^n}\int_{\R^n}\int_B\frac{\diff\!\s}{\norm{f_\s(X)-f_\s(X')}^\delta} \diff\!\mu(X)\diff\!\mu(X')
\end{align*}
Renormalizing with the factor $\norm{X-X'}^{\delta}$, we conclude that
\begin{equation}\label{eq: int energy mut}
\int_B\eng_\delta(\mu_\s)\diff\!\s=\int_{\R^n}\int_{\R^n}\int_B\frac{\diff\!\s}{\norm{\frac{f_\s(X)-f_\s(X')}{\norm{X-X'}}}^\delta}
\frac{\diff\!\mu(X)\diff\!\mu(X')}{\norm{X-X'}^\delta}.
\end{equation}
Since $\delta<1$, applying Lemma~\ref{lem: transversality of ft}, we conclude that
\[
\int_B  \norm{\frac{f_\s(X)-f_\s(X')}{\norm{X-X'}}}^{-\delta}\diff\!\s\ll \frac{1}{1-\delta}.
\]
This,~\eqref{eq: int energy mut}, and $\eng_\delta(\mu)\leq C$ imply that   
\[
\int_B\eng_\delta(\mu_\s)\diff\!\s\ll\frac{\eng_\delta(\mu)}{1-\delta}\ll\frac{C}{1-\delta}.
\]
The claim in the lemma follows from this and the Chebyshev's inequality. 
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm: MarstrandProj}]
Let $s\in\R$ and $\s\in\R^{n-2}$. Then 
\begin{equation}\label{eq: decomp pi t}
\begin{aligned}
    \pi_{s\s}(r_1,\c, r_2)&=r_1+\c\cdot L(s\s)+r_2q(s\s)\\
    &=(1, s, s^2)\cdot f_\s(r_1,\c, r_2). 
\end{aligned}
\end{equation}


Let $K\subset B_{\R^n}(0,1)$ be a compact subset, and let  $\kappa=\min(1,\hdim K)$. Let $0<\delta<\kappa$. 
By Frostman's lemma, there exists a probability measure $\mu$ supported on $K$ and satisfying the following   
\[
\mu(B(X, b))\leq  b^\delta \quad\text{for all $X\in K$}.
\]
Then by Lemma~\ref{lem: ft dim preserving}, applied with $\mu$, there exists a conull subset $\Xi_\delta\subset\R^{n-2}$ so that  
$\hdim(f_\s(K))\geq \delta$ for all $\s \in\Xi_\delta$. Applying this with $\delta_n=\kappa-\frac{1}{n}$ for all $n\in\N$, we obtain a conull subset $\Xi\subset\R^{n-2}$ so that 
\[
\hdim(f_\s(K))\geq \kappa,\quad\text{for all $\s \in\Xi$.}
\]

Let $\s\in\Xi$, and set $K_\s=f_\s(K)$. Then by~\cite[Thm.\ 1.3]{PYZ}, see also~\cite{GGW}, for a.e.\ $s\in\R$, we have 
\[
\Bigl\{x_1+x_2s+x_3s^2: (x_1, x_2, x_3)\in K_\s\Bigr\}\subset \R
\]
has dimension $\kappa$. This and~\eqref{eq: decomp pi t} complete the proof.  
\end{proof}



We now turn to the proof of Theorem~\ref{thm: main finitary}, the argument is a discretized version of the argument in Theorem~\ref{thm: MarstrandProj} as we now explicate. 

Let $F\subset\R^n$ be a finite, and let  $\mu$ be the uniform measure on $F$. Our standing assumption is that for some $0< \delta\leq 1$ and some $C\geq 1$, we have  
\begin{equation}\label{eq: dimension alpha}
\mu(B_{\R^n}(X,  b))\leq C b^\delta\qquad\text{for all $X\in F$ and all $ b\geq  b_0$}.
\end{equation}

Without loss of generality, we will assume $ b_0=2^{-k_0}$ for some $k_0\in\N$; we will also assume that $\diam(F)\leq 1$. 

For a finitely supported probability measure $\rho$ on $\R^d$, define  
\[
\eng_{\delta,\rho}^+:\R^d\to\R\quad\text{by}\quad \hat\eng_{\delta,\rho}(X)=\int \norm{X-X'}_+^{-\delta}\diff\!\rho(X')
\]
where $\norm{X-X'}_+=\max\Bigl(\norm{X-X'}, b_0\Bigr)$ for all $X,X'\in\R^d$ --- this definition is motivated by the fact that we are only concerned with scales $\geq  b_0$, 

\medskip

We recall the following standard lemma. 

\begin{lem}\label{lem: truncated energy}
    Let $\rho$ be a finitely supported probability measure on $\R^d$. Assume that for some $X\in \R^d$ we have 
    \[
    \hat\eng_{\delta,\rho}(X)\leq R.
    \]
    Then for all $ b\geq b_0$, we have 
    \[
    \rho(B_{\R^d}(X, b))\leq R b^{\delta}.  
    \]
\end{lem}

\begin{proof}
We include the proof for completeness. 
Let $ b\geq  b_0$, then  
\begin{align*}
     b^{-\delta}\rho(B_{\R^d}(X, b))&\leq \int_{B_{\R^d}(X, b)}\norm{X-X'}_+^{-\delta}\diff\!\rho(X')\\
    &\leq \int \norm{X-X'}_+^{-\delta}\diff\!\rho(X')=\hat\eng_{\delta,\rho}(X)\leq R,
\end{align*}
as it was claimed. 
\end{proof}

Recall our notation $B=\{\s\in\R^{n-2}: 1\leq \s\leq 2\}$. For every $\s\in B$, let $\mu_\s=f_\s\mu$ 
where $f_\s:\R^n\to\R$ is defined as
\begin{equation*}
f(r_1,\c, r_2)= \Bigl(r_1, \c \cdot L(\s), r_2q(\s) \Bigr),
\end{equation*}
where $L$ is a bijection of $\mathbb R^{n-2}$ and $q$ is a positive definite quadratic form on $\mathbb R^{n-2}$. Recall we use the coordinates $\R^{n}=\{(r_1,\c, r_2): r_i\in\R, \c\in\R^{n-2}\}$.

\begin{lem}\label{lem: ave trun egy proj}
    For every $X\in F$,  
    \[
    \int_B\hat\eng_{\delta,\mu_\s}(f_\s X)\diff\!\s\ll C\absolute{\log_2( b_0)}
    \]
    where the implied constant is absolute. 
\end{lem}

\begin{proof}
    Let $X\in F$. By the definitions, we have 
    \[
    \int_B\hat\eng_{\delta,\mu_\s}(f_\s X)\diff\!\s= \int_B\int \norm{f_\s X-f_\s X'}_+^{-\delta}\diff\!\mu(X')\diff\!\s.
    \]
   Renormalizing with $\norm{X-X'}_+^{-\delta}$ and using Fubini's theorem, we have 
   \[
   \int_B\hat\eng_{\delta,\mu_\s}(f_\s X)\diff\!\s=\int \int_B\frac{1}{\frac{\norm{f_\s X-f_\s X'}_+^\delta}{\norm{X-X'}_+^\delta}}\diff\!\s \norm{X-X'}_+^{-\delta}\diff\!\mu(X').
   \]
  For every $0\leq k\leq k_0-1$, let 
 \[
 F_k(X)=\{X'\in F: 2^{-k-1}< \norm{X-X'}\leq 2^{-k}\},
 \]
 and let $F_{k_0}(X)=\{X'\in F: \norm{X-X'}\leq 2^{-k_0}\}$. 

 For all $X'\in F_{k_0}$, we have $1\leq \frac{\norm{f_\s X-f_\s X'}_+}{\norm{X-X'}_+}\leq 10$. Thus, 
   \begin{equation}\label{eq: contribution of Fk0}
   \int_{F_{k_0}}\int_B\frac{1}{\frac{\norm{f_\s X-f_\s X'}_+^\delta}{\norm{X-X'}_+^\delta}}\diff\!\s \norm{X-X'}_+^{-\delta}\diff\!\mu(X')\ll \mu(F_{k_0})2^{k_0\delta}\ll C. 
   \end{equation}
   We now turn to the contribution of $F_k$ to the above integral for $k< k_0$. 
   If $X'\in F_k$, for some $k<k_0$, then $\norm{X-X'}_+=\norm{X-X'}$ and we have 
   \textcolor{red}{fix multiline}
   \begin{multline}\label{eq: contribution of Fk}
   \int_{F_{k}}\int_B\frac{1}{\frac{\norm{f_\s X-f_\s X'}_+^\delta}{\norm{X-X'}_+^\delta}}\diff\!\s \norm{X-X'}_+^{-\delta}\diff\!\mu(X')= 
   \int_{F_{k}}\int_B\frac{1}{\frac{\norm{f_\s X-f_\s X'}_+^\delta}{\norm{X-X'}^\delta}}\diff\!\s \norm{X-X'}^{-\delta}\diff\!\mu(X'). 
   \end{multline}
   By Lemma~\ref{lem: transversality of ft}, we have 
   \[
   \int_B\frac{1}{\frac{\norm{f_\s X-f_\s X'}_+^\delta}{\norm{X-X'}^\delta}}\diff\!\s \leq \int_B\frac{1}{\norm{\frac{f_\s X-f_\s X'}{\norm{X-X'}}}^\delta}\diff\!\s\ll 1
   \]
   where the implied constant is absolute. Thus 
   \[
   \eqref{eq: contribution of Fk}\ll \mu(F_k)2^{k\delta}\ll C
   \]
   This and~\eqref{eq: contribution of Fk0} imply that 
   \[
   \int_B\hat\eng_{\delta,\mu_\s}(f_\s(X))\diff\!\s\ll Ck_0=C\absolute{\log_2( b_0)}
   \]
   as we claimed. 
\end{proof}

\begin{prop}\label{prop: ft preserves dim}
Let $0<\varepsilon<1$. 
    There exists $B'\subset B$ with 
    \[
    \absolute{B\setminus B'}\leq \varepsilon^{-A'} b_0^{\varepsilon}
    \]
    so that the following holds. For every $\s\in B'$, there exists $F_{\s}\subset F$ with 
    \[
    \mu(F\setminus F_\s)\leq \varepsilon^{-A'} b_0^{\varepsilon}
    \]
    so that for every $X\in F_\s$ and every $ b\geq  b_0$ we have 
    \[
    \mu_\s\Bigl(B_{\R^3}(f_\s(X),  b)\Bigr)\ll \varepsilon^{-A'} b_0^{-3\varepsilon}\cdot  b^{\delta}
    \]
    where $A'$ is absolute and the implied constant depends on $C$. 
\end{prop}

\begin{proof}
  The proof is based on Lemma~\ref{lem: ave trun egy proj} and Chebychev's inequality as we now explicate. First note that we may assume $ b_0$ is small enough (polynomially in $\varepsilon$) so that 
  \[
   b_0^{-\varepsilon/10}>\absolute{\log b_0}
  \]
  otherwise the statement follows trivially. 

  By Lemma~\ref{lem: ave trun egy proj}, we have 
  \begin{equation*}
\int_B\hat\eng_{\delta,\mu_\s}(f_\s(X))\diff\!\s\leq C'\absolute{\log_2( b_0)}.
  \end{equation*}
  where $C'\ll C$. Averaging the above with respect to $\mu$, and using Fubini's theorem we have 
  \begin{equation*}
  \int_B\int\hat\eng_{\delta,\mu_\s}(f_\s(X))\diff\!\mu(X)\diff\!\s\leq C'\absolute{\log_2( b_0)}.
  \end{equation*}
  Let $B'=\{\s\in B: \int\hat\eng_{\delta,\mu_\s}(f_\s(X))\diff\!\mu(X)<C' b_0^{-2\varepsilon}\}$.
  Then by the above equation and Chebychev's inequality we have 
  \[
  \mu(B\setminus B')\leq  b_0^{\varepsilon}.
  \] 
  Let now $\s\in B'$, then 
  \begin{equation}\label{eq: int of energy for good t}
  \int\hat\eng_{\delta,\mu_\s}(f_\s(X))\diff\!\mu(X)\leq C' b_0^{-2\varepsilon}.
  \end{equation}
  For every $\s\in B'$, set 
  \[
  F_\s=\{X\in F: \hat\eng_{\delta,\mu_\s}(f_\s(X))< C' b_0^{-3\varepsilon}\}
  \]
  Then~\eqref{eq: int of energy for good t} and Chebychev's inequality again imply that $\mu(F\setminus F_\s)\leq  b_0^{\varepsilon}$.

  Altogether, for every $\s\in B'$ and $X\in F_\s$, we have 
  \[
  \hat\eng_{\delta,\mu_\s}(f_{\s}(X))=\int\norm{f_\s(X)-f_\s(X')}_+^{-\delta}\diff\!\mu_\s(X')\leq C' b_0^{-3\varepsilon}
  \]
This and Lemma~\ref{lem: truncated energy} imply that for every $\s\in B'$ and $X\in F_\s$, we have
\[
\mu_\s\Bigl(B_{\R^3}(f_\s(X), b)\Bigr)\leq C' b_0^{-3\varepsilon}\cdot  b^\delta \quad\text{for all $ b\geq  b_0$}.
\]
The proof is complete. 
\end{proof}


\subsection{Proof of Theorem~\ref{thm: main finitary}}
We now turn to the proof of Theorem~\ref{thm: main finitary}. As it was done in the proof of Theorem~\ref{thm: MarstrandProj}, we will use the following observation: for all $s\in\R$ and $\s\in\R^{n-2}$, we have  
\begin{equation}\label{eq: decomp pi t'}
\begin{aligned}
    \pi_{s\s}(r_1,\c, r_2)&=r_1+\c\cdot L(s\s)+r_2q(s\s)\\
    &=(1, s, s^2)\cdot f_\s(r_1,\c, r_2). 
\end{aligned}
\end{equation} 

Apply Proposition~\ref{prop: ft preserves dim} with $\varepsilon$ as in the statement of Theorem~\ref{thm: main finitary}. 
Let $B'\subset B$ be as in that proposition, and for every $\s\in B'$, let $F_{\s}$ be as in that proposition. 
Then we have 
\begin{equation}\label{eq: lem ave trun egy proj use}
\mu_\s\Bigl(B_{\R^3}(f_\s(X), b)\Bigr)\leq C' \varepsilon^{-A'} b_0^{-3\varepsilon}\cdot b^\delta\quad\text{for all $X\in F_\s$ and $ b\geq b_0$}.
\end{equation}

Let $K_\s= f_\s(F_\s)\subset \R^3$ and let $\rho_\s$ be the restriction of $\mu_t$ to $K_\s$ normalized to be a probability measure. Then~\eqref{eq: lem ave trun egy proj use} and the fact that $\mu(F\setminus F_{\s})\leq  b_0^{\varepsilon}$ imply that   
\begin{equation*}
\rho_\s\Bigl(B_{\R^3}(Y, b)\Bigr)\leq 2C' \varepsilon^{-A'} b_0^{-3\varepsilon}\cdot b^\delta\quad\text{for all $Y\in K_\s$ and $ b\geq b_0$}.
\end{equation*}
This in particular implies that $K_\s$ and  $\rho_\s$ satisfy the conditions in~\cite[Thm.~B]{MR4549089}, see also \cite{PYZ} and \cite[Thm.\ 2.1]{GGW}. Apply~\cite[Thm.~B]{MR4549089} with $\varepsilon$; thus, there there exists $J_{ b,\s}\subset [0,2]$ with 
\[
\absolute{[0,2]\setminus J_{ b,\s}}\leq \hat C \varepsilon^{-D} b^{\varepsilon}
\]
and for all $s\in J_{ b,\s}$ there is a subset $K_{ b, \s, s}\subset K_{\s}$ with 
\[
\rho_\s(K_{\s}\setminus K_{ b, \s, s}) \leq \hat C\varepsilon^{-D} b^{\varepsilon}
\]
so that for all $Y\in K_{ b, \s, s}$, we have 
\[
\rho_\s\Bigl(\{Y'\in K_\s: \absolute{(1,s,s^2)\cdot (Y-Y')}\leq  b\}\Bigr)\leq \hat C \varepsilon^{-D} b_0^{-3\varepsilon} \cdot b^{\delta- 7\varepsilon};
\]

Let $A=\max\{A', D\}$.
In view of the definition of $\rho_\s$ and~\eqref{eq: decomp pi t'}, we have the following. For every $\s\in B'$ 
and $s\in J_{ b,\s}$, put $F_{ b, s\s}=F\cap f^{-1}_\s(K_{ b, \s, s})$. Then 
\[
\#(F\setminus F_{ b, s\s})\leq  10\hat C\varepsilon^{-A} b^{\varepsilon}\cdot (\#F),
\]
and for every $X\in F_{ b, s\s}$, we have 
\begin{equation}\label{eq: F b st}
\#\{X'\in F_{ b, s\s}: \absolute{\pi_{s\s}(X)-\pi_{s\s}(X')}\leq  b\}\Bigr)\leq \hat C \varepsilon^{-A} b_0^{-3\varepsilon} 
 b^{\delta- 7\varepsilon}. 
\end{equation}

This finishes the proof. Indeed, let $B_ b\subset B$ be the set of $\s\in  B$ 
for which there exists $F_{ b, \s}\subset F$ with
\[
\#(F\setminus F_{ b, \s})\leq 100\hat C\varepsilon^{-D} b^{\varepsilon}\cdot (\#F)
\] 
so that for all $X\in F_{ b, \s}$ we have
\[
\#\{X'\in F_{ b, \s}: \absolute{\pi_{\s}(X)-\pi_{\s}(X')}\leq  b\}\Bigr)\leq \hat C \varepsilon^{-A} b_0^{-10\varepsilon} 
 b^{\delta}. 
\]
Then~\eqref{eq: F b st} implies that for every $\s'\in B'$ and $s\in J_{ b,\s'}$, we have $s\s'\in B_ b$, so long as $s\s'\in B$. In particular, we conclude that 
\[
\absolute{B\setminus B_ b}\ll \varepsilon^{-A} b^{\varepsilon}
\] 
as we aimed to prove.
