    Then there exists $I\subset [0,1]$, some $b_1>0$ with 
    \begin{equation}\label{eqn: size of b1}
        (\#F)^{-\frac{n-\delta+(2+n)\varepsilon}{n-\delta +(3+n)\varepsilon}}\le b_1\le (\#F)^{-\varepsilon},
    \end{equation}
    and some $y_2\in X_{2\eta}\cap Y $ so that both of the following hold true:
    \begin{enumerate}
        \item The set $I$ supports a probability measure $\rho$ which satisfies
        $$\rho(J)\le C_\varepsilon (b_0/b_1)^{-\varepsilon}\cdot|J|^{\delta - (3+n)\varepsilon}$$
        for all intervals $J$ of size $|J|\ge\frac{b_0}{b_1}$ where $b_0=(\#F)^{-1}$ and where $C_\varepsilon$ depends on absolute constants, $\varepsilon$, and $n$.
        \item There is an absolute constant $C$, so that for all $r\in I$, we have
        $$v_ry_2\in B_{Cb_1} ^G Y.$$        
    \end{enumerate}
\end{prop}

\begin{proof}
By Equation \ref{eqn:sizeoforbits}, we assume throughout the proof that 
$$        (\#F)^{-\varepsilon}\le \frac{e^{-\ref{C:nondiv}}}{10^5\ref{C:changeinballs}}\eta^{3}$$

By Proposition \ref{prop:input}, there exists $y_0\in Y$  and a finite subset $F\subset B_\mathfrak{r}(0,1)$ that satisfies Equation (\ref{Prop2Inequality}) and so that $\exp(w)y_0\in Y$ for all $w\in F$. In particular, by our choice of $F$, we have $\|w\|\le\beta_0$ for all $w\in F$. Moreover, 
    Equation \eqref{Prop2Inequality} allows us apply Lemma \ref{lem:Localize}. Choose $w_0\in F$, $b_1>0$, and $F'\subset B_\mathfrak r(w_0,b_1)\cap F$ as in Lemma \ref{lem:Localize} where 
    \begin{equation}\label{eqn: bound on b1}
        (\# F)^{-\frac{n-\delta+(2+n)\varepsilon}{n-\delta+(3+n)\varepsilon}}\le b_1\le  (\# F)^{-\varepsilon}.
    \end{equation}
    By using a pigeonhole argument, we may replace $w_0$ with a different point in $F$  (at the cost of potentially increasing $C'$) and assume that $F'\subset B_\mathfrak r (w_0,b_1/2\dim(G)\ref{C:normalform})\cap F$.
Now, due to Lemma \ref{lem: normal form}, for each $w'\in F'$, there exists $h\in H$ and $w\in \mathfrak{r}$ so that
    \begin{equation}\label{eqn: conditions normal form}
        \begin{split}
        h\exp(w) = \exp(w')\exp(-w_0),\\
        \|h-I\|\le \frac{b_1 \eta^2}{\dim(G)},\text{ and}\\
        \|w\|\le \frac{b_1 }{\ref{C:normalform}\dim(G)}. \end{split}
    \end{equation}

    Set 
    \begin{equation}\label{eqn: recentered fiber}
        E=\{w\in\mathfrak{r}: \exists h\in H, w'\in F' \text{ so that }h,w,w_0,w' \text{ satisfy}~\eqref{eqn: conditions normal form}\}
    \end{equation}

    We claim that $E$ has dimension inherited from $F'$ but with a larger multiplicative constant i.e. that
    \begin{equation}\label{eqn: E has dimension}
        \frac{\#(E\cap B(w,b))}{\#E}\le \hat C (b/b_1)^{\delta - (3+n)\varepsilon}
    \end{equation}
    for all $w\in\mathfrak{r}$ and $b\ge (\#F)^{-1}$ where $\hat C\le 2C'$. This is just a consequence of the fact that the map $f:B_\mathfrak{r}(0,\beta_0/2)\to B_\mathfrak{r}(0,\beta_0)$ defined by $f(w')=w$ where $$h\exp(w)=\exp(w')\exp(w_0)$$ is a diffeomorphism (see Lemma \ref{lem: normal form}). In particular, $D_{w'}(f^{\pm1})$ is invertible for all $w'\in B_\mathfrak{r}(0,\beta_0/2)$ and so $\#f(E)=\#E$ and 
    $$\#\left(B_\mathfrak{r}(\bar w,\varrho)\cap f(E)\right)\le \#\left(B_\mathfrak{r}(f^{-1}(\bar w),2\varrho)\cap E\right)$$
    for all $\varrho\le\beta_0/2$ which implies the claim.


    Let $y_1:=\exp(w_0)y_0$ and let $w'\in F'$. Then there exists $h$ and $w$ that satisfy ~\eqref{eqn: conditions normal form} and we have
    \begin{equation}\label{eqn: calcu}
     h\exp(w)y_1 =\exp(w')\exp(-w_0)\exp(w_0)y_0= \exp(w')y_0\in Y  
    \end{equation}
    by construction of $F$ and using that $w'\in F$.

    Moreover, we need the following lemma that allows us to assume the size of certain elements cannot get too small. We postpone the proof until the proposition is proved.
    \begin{lem}\label{lem:expanding part not too small}
        There exists $\s\in B_1 ^U$ and a subset $$\bar E\subset \Ad(u_\s)E\cap \{w\in B_\mathfrak{r}(0,1):|w|^+\ge10^{-3}\|w\|\}$$
        so that $\#\bar E\ge\#E/4$ where $Z\mapsto Z^+$ is the projection onto the expanding direction of $a_t$.
    \end{lem}

   Due to this lemma, we replace $y_1$ by $u_\s y_1$ for some $\s\in B_1^U$ and $E$ by a subset $\bar E$ with $\#\bar E\ge\#E/4$ (which we continue to denote by $E$) to ensure that 
   \begin{equation}\label{eqn: lower bound on expanding direction}
       E\subset  \{w\in B_\mathfrak{r}(0,1):|w^+|\ge10^{-3}\|w\|\}.
   \end{equation}
    Note that \eqref{eqn: E has dimension} holds for the new $E$ with $4\hat C$, but we will suppress the factor 4.

    \textbf{Estimates on the size of elements}

    Let $t=|\log(b_1)|$. By \eqref{eqn: calcu}, since $a_tu_\s\in H$, we have 
    \begin{equation}\label{eqn: calculation2}
        a_tu_\mathbf{s}h\exp(w)y_1\in Y
    \end{equation}
    and for every $\mathbf{s}\in B_1 ^U$ and $w\in E$, we have, by Equation~\eqref{eqn:Adjointaction},
    \begin{equation}\label{eqn: expanding translate of lie alg}
        \|\Ad(a_tu_\s)w\|\le \frac{1}{b_1}\|\Ad(u_\s)w\|\le\frac{3}{b_1}\|w\|\le \frac{3}{\dim(G)\ref{C:normalform}}\le 1.
    \end{equation}
    Additionally, we note that $(a_tu_
    \s)h(a_tu_\s)^{-1}\in H$.


    Now, thanks to Equation~\eqref{eqn: lower bound on expanding direction}, if $\|\s\|\le 10^{-4}$, then the reverse triangle inequality yields
    $$|(\Ad(u_\s)w)^+|=|r_1+\s\cdot\c+r_2\|\s\|^2/2|\ge|r_1|-|\s\cdot\c+r_2\|\s\|^2/2|\ge (10^{-3}-2\cdot10^{-4})\|w\|\ge 10^{-4}\|w\|.$$     
    In particular, for $10^{-5}\le\|\s\|\le 10^{-4}$, the upper bound for $\|w\|$ above, shows we have that the contracting direction of $\Ad(a_tu_\s)w$ satisfies $\le e^{-2t}10^4 \|(\Ad(a_tu_\s)w)^+\|$ and the neutral satisfies $\le 2\cdot10^4e^{-t}\|(\Ad(a_tu_\s)w)^+\|$. 



    In conclusion, we have  for $\|\s\|\le 10^{-4}$, 
    $$a_tu_\s h\exp(w).y_1  = (a_tu_
    \s)h(a_tu_\s)^{-1}\cdot g\cdot \exp(Z((\Ad(a_tu_\s)w)^+,\mathbf{0},0).a_tu_\s y_1
    $$
    where, due to the Baker--Campbell--Hausdorff formula and Equation~\eqref{eqn: expanding translate of lie alg}, $g\in G$ satisfies
    \begin{equation}
        \|g-I\|\le 4\cdot 10^4 b_1
    \end{equation}
    with an absolute implied constant.  Indeed, $[(\Ad(a_tu_\s)w),-(\Ad(a_tu_\s)w)^+]=[(\Ad(a_tu_\s)w)-(\Ad(a_tu_\s)w)^+,-(\Ad(a_tu_\s)w)^+]$ and we have shown a few paragraphs before that the contracting and neutral directions of $(\Ad(a_tu_\s)w)$ have size less than $2\cdot10^4 b_1$. 


    Hence, by Equation \ref{eqn:changingballs}, we  have $g\in B_{\ref{C:changeinballs}4\cdot10^4b_1} ^G$.


    As such
    \begin{equation}\label{eqn:expanding close to Y}
        \exp(Z((\Ad(a_tu_\s)w)^+,\mathbf{0},0).a_tu_\s y_1\in B^G _{Cb_1} Y
    \end{equation}
    where $C=\ref{C:changeinballs}4\cdot10^4$ is an absolute constant.  


     We now choose a particular $s$ to define the set $I$. Recall that by our choice of $t=|\log(b_1)|$ and that 
     $$b_1\le         (\#F)^{-\varepsilon}\le \frac{e^{-\ref{C:nondiv}}}{10^5\ref{C:changeinballs}}\eta^{3}.
$$
In particular, $t$ is sufficiently large that we may apply Proposition \ref{prop:nondiv} to the point $y_1$ and $B=\{\s\in B_1^U:10^{-5}\le\|s\|\le10^{-4}\}$, $\eta= \min\{|B|,\alpha^2\}$, and $\alpha\le.1\ref{C:nondiv}^{-1}$ to deduce that
$$B'':=\{\s\in J: a_tu_\s y_1 \in X_\eta\}$$
has $|B''|>.9|B|$.



Now apply Theorem \ref{thm:ProjSO(n,1)} to $E\subseteq B_\mathfrak r (0,b/b_1)$ (see Equation \eqref{eqn: recentered fiber} and \eqref{eqn: lower bound on expanding direction}), $B=\{\s\in B_1^U:10^{-5}\le\|s\|\le10^{-4}\}$, coarse dimension $\delta-(3+n)\varepsilon$ and $\varepsilon\le\frac{\delta}{2(3+n)}$ to get some $B'\subset B_1 ^U$ with $|B'|\ge .99|B|$. 

Fix some $\s\in B'\cap B''$. Put $y_2:=a_tu_\s y_1$. By definition of $B''$ we have $y_2\in X_\eta$ and, by Equation \ref{eqn:expanding close to Y}, we have
$$\exp(e^t Z((\Ad(u_\s)w)^+,\mathbf 0,0))y_2\in B^G _{Cb_1}Y.$$

Define $I:=\{e^t\xi_\s(w):w\in E_{\s} \}$. We claim the proposition holds with $y_2$, $I$, and $b_1$.

By construction we have the claimed bound from Equation \ref{eqn: size of b1} on $b_1$ and item (2) follows from Equation \ref{eqn:expanding close to Y}. As such, it only remains to prove item (1). 

Let $\mathfrak{b} \ge e^t(\#F)^{-1}$ and $b_0=(\#F)^{-1}$.


Let $\rho$ be defined as
$$\rho(A)=\frac{\#\{w\in E_{\s}:e^t\xi_\s(w)\in A\}}{\# E_{\s}}$$
for $A$ an interval.
That is, $\rho$ is the pushforward of the normalized counting measure on $E_\s$ under the map $w\mapsto e^t\xi_\s(w)$.

Let $w\in E_\s$ and $r=e^t\xi_\s(w)$. By Theorem \ref{thm:ProjSO(n,1)} and the fact that for every $\mathfrak{b}\ge e^t(\#F)^{-1}$ we have
$\#E_\s\ge .9(\#E)$, we conclude
\begin{align}\label{eqn:measure on remaining horosphere}
    \rho(\{r'\in I:|r-r'|\le \mathfrak{b}\})&=\frac{\#(\{w'\in E_\s:|\xi_\s(w')-\xi_\s(w)|\le e^{-t}\mathfrak{b}\}}{\#E_\s}\\\nonumber&\le C_\varepsilon(b_0/b_1)^{-\varepsilon}(e^{-t}\mathfrak{b}/b_1)^{\delta - (3+n)\varepsilon}\\\nonumber&\le C_\varepsilon (b_0/b_1)^{-\varepsilon}\mathfrak{b}^{\delta - (3+n)\varepsilon}
\end{align}
where $C_\varepsilon$ depends on $\hat C$ from Equation \ref{eqn: E has dimension}, $\varepsilon$, and $n.$

This estimate finishes item (1) and thus concludes the proof.    
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:expanding part not too small}]
    Throughout we assume $w$ has coordinates $(r_1,\c,r_2)$.

If $\{w\in E: w^+\ge 10^{-3}\|w\|\}$ has more than $\#E/4$ elements, then done with $\s=\mathbf 0$. Else we assume that $\#\{w\in E: w^+\ge 10^{-3}\|w\|\}<\#E/4$ and so $.75\#E\le \#\hat E$ where $\hat E:=\{w\in E: w^+\le 10^{-3}\|w\| \}$.

Case 1: $\#\{w\in \hat E: \|\c\|\ge.1\|w\|\}\ge\#E/4$.
Then, there is at least one coordinate in $\c$, say $c_i$, with $|c_i|\ge.1\|w\|$. Let $\s$ be the zero vector except in the $i$th entry. Then
\begin{align*}
    .1|s_i|\|w\|&\le |c_is_i|=\|\c\cdot\s\|\\
    &\le |r_1+\c\cdot\s+r_2\|s\|^2/2|+|r_1|+|r_2|\|\s\|^2/2\\
    &\le |r_1+\c\cdot\s+r_2\|s\|^2/2|+\|w\|10^{-3}+\|w\||s_i|^2/2
\end{align*}
and so for $s_i=.1$, we get $$.004\|w\|\le|r_1+\c\cdot\s+r_2\|s\|^2/2|.$$
Indeed, $(.1|s_i|-10^{-3}-|s_i|^2/2|)\|w\|\le |r_1+\c\cdot\s+r_2\|s\|^2/2|$

Case 2: If $\#\{w\in \hat E: \|\c\|\ge.1\|w\|\}<\#E/4$, then $.5\#E<\{w\in\hat E:\|\c\|\le .1\|w\|\}$. In this case we have $\|w\|=|r_2|$ and using a similar argument as in case 1 with $\s$ zero everywhere except in a coordinate where $\|c\|$ is attained in which case $s_i$ is $.75$ gives the desired conclusion.
\end{proof}

