\section{Appendix: Effective equidistribution over measures of large dimension}\label{section: Appendix A}
In the appendix we prove a slightly more general version of Theorem \ref{thm:VenkateshSO(n,1)} so that it can be utilized outside of this paper. That is, we show that, in the context of simple Lie groups, we have equidistribution in the presence of measures on subgroups that behave horospherically and that are almost full. 
\begin{thm}\label{thm:Appendix}
    Let $G$ be a simple Lie group with finite center, $\Gamma$ a lattice of $G$, and $X=G/\Gamma$. Let $X_\eta=\{x\in X:\inj(x)\ge\eta\}$. Suppose
    $\mathbb R^d \simeq N\subset G$ is a unipotent subgroup equipped with the Euclidean inner product and we have a subgroup $U \simeq \mathbb R^k$ for $k\ge1$. Set $V=U^\perp$ and let $A=\{a_t:t\in \mathbb R\}$ be a 1-parameter subgroup of $G$ satisfying $$a_tn_\mathbf{z}a_{-t}=n_{e^t\mathbf{z}}.$$ 
    Let $[0,1]^d$ denote $\{u_\mathbf{s}v_{\mathbf {r}}\in N:(\mathbf{s},\mathbf{r})\in[0,1]^k\times[0,1]^{d-k}\}$.
    Assume the following holds
    \begin{itemize}
        \item (Effective equidistribution of the unstable foliation) There exists $\constK\label{K:effec}=\ref{K:effec}(\Gamma,\kappa_X)$ and $L>0$ such that the following holds. Let $0<\eta<1$, $t>0$, and $x\in X_\eta$. Then for every $f\in C_c^\infty(X)+\mathbb C \cdot1$,
        $$\left|\int_{[0,1]^d}f(a_tn_\mathbf{z}x)dm_N(\mathbf{z})-\int_X f(x)dm_X(x)\right|\ll \mathcal S(f)e^{-\ref{K:effec} t}\eta^{-L}$$
        where $m_N$ is the Haar measure on $N$ normalized so that $[0,1]^d$ has measure 1, and the implicit constants are all absolute.
        \item Let $\rho$ be a probability measure on $[0,1]^{d-k}\subseteq \mathbb R^{d-k}\simeq V$ satisfying 
        $$\rho(B(\mathbf{r},b))\le Cb^{\delta}$$
        for some $b>0$.
    \end{itemize}
    Then, there exists $\kappa=\kappa(\kappa_X)$ and $\varepsilon=\varepsilon(\kappa_X)$ such that if $\delta>d-k-\varepsilon$, then for $|\log(b)/4|\le t\le |\log(b)/2|$ we have
    $$\left|\int_{[0,1]^{d-k}}\int_{[0,1]^k}f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)d\mathbf{s}d\rho(\mathbf{r})-\int_Xf(x)dm_X(x)\right|\ll C^{1/2}S(f)e^{-\kappa t}\eta^{-L/2}.$$ Here $\kappa_X$ comes from the decay of correlations in $X$, see Proposition \ref{Cor:Decay of Cor}. 
\end{thm}

Notice that the theorem needs effective equidistribution with respect to the Haar measure on $N$ as an assumption. When $N$ is the horospherical subgroup of a 1-parameter diagonalizable element, then effective equidistribution of expanding unipotents with respect to the Haar measure on the unstable foliation is known by \cite{MR1359098} Proposition 2.4.8. See also \cite{MR4277274} for effective equidistribution of expanding translates in more general homogeneous spaces. Also related are the results of \cite{MR3556973} and \cite{MR4372213}  where they prove effective equidistirbution results of expanding curves contained in $G$ and products of $G$. A version of Theorem \ref{thm:Appendix} in the setting of Teichm\"{u}ller dynamics can be found in \cite{S23}.

Thus, Theorem \ref{thm:VenkateshSO(n,1)} is a special case of Theorem \ref{thm:Appendix}.

\begin{proof}[Proof of Theorem \ref{thm:VenkateshSO(n,1)}]
Apply Theorem \ref{thm:Appendix} to $G=\SO^\circ(n,1)$ and $N$ the horospherical subgroup of $a_t = \text{diag}(e^{t},\ldots,e^{-t})$ and note that the existence of the required probability measure follows from Proposition \ref{prop:prop2} and $[0,1]^{n-2}\subset  [-1,1]^{n-2}\simeq B_1^U$.
\end{proof}




Before beginning the proof of Theorem \ref{thm:Appendix}  we record a result that we need on the decay of correlations.

\begin{prop}\label{Cor:Decay of Cor}(Corollary 2.4.4 of \cite{MR1359098})
    Let $d$ be a fixed right $G$-invariant metric on $G$. There exists a positive constant $\kappa_X$ on $X=G/\Gamma$ so that
    $$\left|\int \varphi(gx)\psi(x)\,dm_X-\int_X\varphi\,dm_X \int_X\psi\,dm_X\right|\ll e^{-\kappa_Xd (e,g)}\mathcal S(\varphi)\mathcal S(\psi)$$
    for every $f\in C_c ^\infty(X)+\mathbb C \cdot1$.
\end{prop}

The Sobolev norm is assumed to dominate $\|\cdot\|_\infty$ and the Lipschitz norm $\|\cdot\|_\textrm{Lip}$. Additionally, $\mathcal S(f\circ g)\ll\|g\|^\star \mathcal S(f)$ where the implied constants are absolute.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}[Proof of Theorem \ref{thm:Appendix}]
 By choosing $N\in\mathbb N$ so that $\frac{1}{N}\le b<\frac{1}{N-1}$, we suppose that $b=1/N$.   Additionally, we assume $f$ is Lipshitz since we can always approximate by such function. Lastly, we let $\delta>d-k-\varepsilon$ for $\varepsilon$ that we will optimize later.

 For a vector $\mathbf{k}\in\{0,\ldots, N-1\}^d$, define the $b$-ball $I_\mathbf{k}$ set of directions one can move in $[0,1]^{d-k}\subset \mathbb R^{d-k}\simeq V $ by
$$I_\mathbf{k}=\{v_{\mathbf{r}}:\mathbf{r}=(r_j),r_j\in [k_jb,(k_j+1)b)^{d-k}, \text{ for each }j\}.$$
Define $c_\mathbf{k}=\rho(I_\mathbf{k})$. Notice that since the $b$-balls $(I_\mathbf{k})_{\mathbf{k} \in\{0,\ldots, N-1\}^d}$ are disjoint and their union is $[0,1]^{d-k}$  that $\sum_{\mathbf{k} \in\{0,\ldots, N-1\}^d}c_\mathbf{k}=1$. 

For each $\mathbf{k} \in\{0,\ldots, N-1\}^d$, let
$$B_\mathbf{k} =\left\{u_{\mathbf{s}}v_{\mathbf{r}}:\mathbf{s}\in [0,1]^k,\mathbf{r}=(r_j),r_j\in\left(k_jb,k_jb+\frac{b}{4}\right)\text{ for each }j=1,\ldots, d-k \right\}$$
denote a thickening to the full unstable leaf.
The sets $B_\mathbf{k}$ continue to be disjoint for different indices $\mathbf{k}$. Then,
\begin{align*}
    \int_{[0,1]^{d-k}}\int_{[0,1]^k} f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)\,d\mathbf{s}\,d\rho(\mathbf{r}) &=\sum_\mathbf{k}\int_{I_\mathbf{k}}\int_{{[0,1]^k}} f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)\,d\mathbf{s}\,d\rho(\mathbf{r})     %\\&=\sum_\mathbf{k}\int_{\mathbf{r}\in[0,b)^{d-k}}\int_{[0,1]^k}f(a_t u_{\mathbf{s}}v_{b\mathbf{\mathbf{k}+\mathbf{r}}}x )\,d\mathbf{s}\,d\rho(\mathbf{r}) .
\end{align*}

Thus,
\begin{align*}
    &\left|\int_{[0,1]^{d-k}}\int_{[0,1]^{k}} f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)\,d\mathbf{s}\,d\rho(\mathbf{r}) - \sum_\mathbf{k}c_{\mathbf{k}}\int_{[0,1]^{k}}f(a_t u_{\mathbf{s}}v_{b\mathbf{k}}x)\,d\mathbf{s}\right|\\
    = &\sum_\mathbf{k}\int_{I_\mathbf{k}}\int_{[0,1]^{k}}\left|f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x) - f(a_t u_{\mathbf{s}}v_{b\mathbf{k}}x)\right|\,d\mathbf{s}\,d\rho(\mathbf{r}).
\end{align*}

We now compare the difference between $f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)$ and $ f(a_t u_{\mathbf{s}}v_{b\mathbf{k}}x)$ by recalling that we assume $f$ is a Lipschitz function.  We have $\|\mathbf{r}-
b\mathbf{k}\|\le b$ for $\mathbf{r}\in [0,b)^{d-k}$ and $t\le |\log(b)|/2$ by assumption and so 
\begin{align*}
\left|f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x) - f(a_t u_{\mathbf{s}}v_{b\mathbf{k}}x)\right|&\le \mathcal S(f\circ a_t u_{\mathbf{s}})\textrm{d}(v_{\mathbf{r}}x,v_{b\mathbf{k}}x)\\
&\ll \mathcal S(f) e^{t} \|\mathbf{r}-
b\mathbf{k}\|\\
&\le \mathcal S(f)b^{-1/2} b = \mathcal S(f) b^{1/2}.
\end{align*}
Thus, we obtain
\begin{align*}
 &\left|\int_{[0,1]^{d-k}}\int_{[0,1]^{k}} f(a_t u_{\mathbf{s}}v_{\mathbf{r}}x)\,d\mathbf{s}\,d\rho(\mathbf{r}) - \sum_\mathbf{k}c_{\mathbf{k}}\int_{[0,1]^{d}}f(a_t u_{\mathbf{s}}v_{b\mathbf{k}}x)\,d\mathbf{s}\right|\\
\\&\ll \sum_\mathbf{k}\int_{I_\mathbf{k}}\int_{[0,1]^{k}}\mathcal S(f) b^{1/2}\,d\mathbf{s}\,d\rho(\mathbf{r})=\mathcal S (f)b^{1/2}
\end{align*}
and so it suffices to understand the behavior of $f$ on the discrete points $b\mathbf{k} .$
Let 
$$\varphi =  \left(\frac{b}{4}\right)^{-(d-k)}\sum_{\mathbf{k}}  c_\mathbf{k}\mathbb{1}_{B_\mathbf{k}}$$
where the constant in front reflects the reciprocal of the volume of $B_\mathbf{k}$.

Thus, by our dimension bound on $\rho$ and the disjointness of $B_{\mathbf{k}}$, we have the following pointwise bound \begin{align*}
|\varphi|&\le 4^{d-k}b^{-(d-k)}\sum_{\mathbf{k}}c_{\mathbf{k}}\mathbb{1}_{B_\mathbf{k}}<C4^{d-k}b^{-(d-k)}b^{\delta}\mathbb{1}_{\cup_\mathbf{k} B_\mathbf{k}}\\
&<C4^{d-k}b^{-(d-k)}b^{d-k-\varepsilon}\mathbb{1}_{\cup_\mathbf{k} B_\mathbf{k}}\le C4^{d-k} b^{-\varepsilon}
\end{align*}

We have, by noting that $\,d\mathbf{z} = \,d\mathbf{r}\,d\mathbf{s}$,
\begin{align*}
  &\left|\sum_\mathbf{k}c_{\mathbf{k}}\int_{[0,1]^k} f(a_tu_{\mathbf{s}}v_{b\mathbf{k}})\,d\mathbf{s}-\int_{N}\varphi(n(\mathbf{z}))f(a_t n(\mathbf{z}))\,d\mathbf{z}\right|\le\\
  &\sum_\mathbf{k}4^{d-k}b^{k-d}\cdot c_{\mathbf{k}} \int_{B_\mathbf{k}}\left|f(a_tu_{\mathbf{s}}v_{b\mathbf{k}})-f(a_t n(\mathbf{z(\mathbf{s},\mathbf{r})}))\right|\,d\mathbf{r}\,d\mathbf{s}\\
    &\ll \mathcal S (f) b^{1/2}
\end{align*}
where on the last line we bounded the difference of functions by $\mathcal S(f)b^{1/2}$ and we used that $\sum_{\mathbf{k} }c_\mathbf{k}=1$.

Thus, it suffices to study the thickening $\int_{N}\varphi(n(\mathbf{z}))f(a_t n(\mathbf{z}))\,d\mathbf{z}$. Now, we introduce an extra average in single direction of the $U$-foliation. Consider the vector $(s,0,\ldots,0)$ for $s\in [0,\tau]$, where $\tau$ is a small parameter that we will specify later. By abuse of notation, we denote the vector $(s,0,\ldots,0)$ by $s$. Consider,
$$A = \frac{1}{\tau} \int_{[0,\tau]} \int_{N}\varphi(n(\mathbf{z}))f(a_tu_{s} n(\mathbf{z}))\,d\mathbf{z}\,ds.$$

We will eventually show that $\int_{N}\varphi(n(\mathbf{z}))f(a_t n(\mathbf{z}))\,d\mathbf{z}$ is comparable to $A$. To see this, notice that $m_U\left(u_{s}B_\mathbf{k}\triangle B_\mathbf{k}\right)\ll \tau m_U(B_\mathbf{k})$ since, $U\simeq\mathbb R^{k}$ and abelian groups have the Folner property. Hence,
\begin{align*}
    \left|\int_{N}\varphi(n(\mathbf{z}))f(a_tu_{s}n(\mathbf{z})x)\,d\mathbf{z}-\int_{N}\varphi(n(\mathbf{z}))f(a_tn(\mathbf{z})x)\,d\mathbf{z}\right|&\le \sum_{\mathbf{k}}c_{\mathbf{k}} \int_{u_{s}B_{\mathbf{k}}\triangle B_{\mathbf{k}}}|f(a_tn(\mathbf{z})x)|\,d\mathbf{z}\\
    &\ll \sum_{\mathbf{k}} c_{\mathbf{k}} \tau m_U(B_\mathbf{k})\|f\|_\infty\\
    &\ll \mathcal S(f) \tau.
\end{align*}
Integrating the above over $[0,\tau]$ and multiplying the above by $1/\tau$ yields
\begin{equation}\label{approx}
\left|\int_{N}\varphi(n(\mathbf{z}))f(a_tn(\mathbf{z})x)\,d\mathbf{z} - A\right|\ll \mathcal S(f)\tau\end{equation}

We choose $\tau$ to be of the form $e^{(\frac{1}{l}-2)t}$ for $l\ge 2.$ Then, by equation (\ref{approx}) and noting that $|\log(b)/4|\le t$ we have 
$$\left|\int_{N}\varphi(n(\mathbf{z}))f(a_t n(\mathbf{z}))\,d\mathbf{z} - A\right|\ll \mathcal S(f)b^{1/8},$$
and, as such, we have reduced our analysis to that of $A$.


By the Cauchy-Schwarz inequality, we have
$$|A|^2\le\int_{N} \left(\frac{1}{\tau}\int_{[0,\tau]} f(a_tu_{s} n(\mathbf{z}))\,ds\right)^2\varphi(n(\mathbf{z}))\,d\mathbf{z}.$$

Now that all the terms we are dealing with are non-negative, by utilizing the upper bound on $\varphi$ we deduce
\begin{align}\label{ineq: main}
|A|^2 &\le \frac{C4^{d-k}b^{-\varepsilon}}{\tau^2} \int_0 ^\tau \int_0 ^\tau\int_{[0,1]} \hat f_{s_1,s_2}(a_tn(\mathbf{z})x)\,d\mathbf{z}\,ds_1\,ds_2
\end{align}

where $\hat f_{s_1,s_2}(y)=f(a_t u_{s_1}a_{-t}y)f(a_tu_{s_2}a_{-t}y)$.

Observe that
$$\mathcal S(\hat f_{s_1,s_2})\le (e^{t}\tau)^\star\mathcal S(f)^2=e^{\frac{\star}{l}t}\mathcal S(f)^2.$$

By the above and by choosing a fixed $l'$  large enough so that $l =2\star l'\ref{K:effec}^{-1} \ge 2$, we have
$\mathcal S(\hat f_{s_1,s_2})\le e^{\ref{K:effec}t/2}\mathcal S(f)^2.$

Combining this observation and by our assumption on the effective equidistribution of the unstable foliation we deduce
$$
\int_{[0,1]^d} \hat f_{s_1,s_2}(a_tn(\mathbf{z})x)\,d\mathbf{z}\ll \int_X \hat f_{s_1,s_2}\,dm_X+e^{-\ref{K:effec}t/2}\mathcal S(f)^2\eta^{-L}.
$$

Combining the above with Equation (\ref{ineq: main}) yields
\begin{equation}\label{ineq: two terms}
    |A|^2\ll\frac{1}{\tau^2}\int_0 ^\tau \int_0 ^\tau \bigg(Cb ^{-\varepsilon}\int_X \hat f_{s_1,s_2}\,dm_X+Cb ^{-\varepsilon}e^{-\ref{K:effec}t/2}\mathcal S(f)^2\eta^{-L}\bigg)\,ds_1\,ds_2.
\end{equation}

Now we analyze the first term on the right of inequality (\ref{ineq: two terms}). We do this by splitting the integral over $[0,\tau]^2$ into two regions; one where $|s_1-s_2|>e^{-t}e^{t/2l}$ and so we can take advantage of the decay of correlations (Corollary \ref{Cor:Decay of Cor}) and one where $|s_1-s_2|<e^{-t}e^{t/2l}$ where we use that the region is of small measure. 

When $|s_1-s_2|>e^{-t}e^{t/2l}$, then by the decay of correlations Proposition \ref{Cor:Decay of Cor}  applied to the simple Lie group $G$, and observing that $d(e,u_{e^{t}(s_1-s_2)})\ge e^{t}|s_1-s_2|>e^{t/2l}>\frac{t}{2l}$ , we have
\begin{align*}
\int_X \hat f_{s_1,s_2}( x)\,dm_X &\ll e^{-\kappa_ X e^{2t}|s_1-s_2|} \mathcal S(f)^2\\
 &\le e^{-\kappa_ X \frac{t}{2l}} \mathcal S(f)^2.
\end{align*}
Thus, after integrating over $[0,\tau]^2$ and dividing by $\tau^2$, we have the following bound on the first term on the right of (\ref{ineq: two terms}) of
$$Cb ^{-\varepsilon}\int_X \hat f_{s_1,s_2}( x)\,dm_ X\ll Cb^{-\varepsilon}e^{-\kappa_X \frac{t}{2l}} \mathcal S(f)^2$$
whenever $|s_1-s_2|>e^{-t}e^{\frac{t}{2l}}.$ 

%%%%%%%%%%%%%%%%%%%%%

Finally, we consider the region close to the diagonal ($|s_1-s_2|<e^{-t}e^{t/2l}=\tau e^{-t/2l}$). Notice this region has area $2\tau^2e^{-t/2l}.$ By invariance of $m_ X$ and using that the $\|\cdot\|_\infty$ is dominated by $\mathcal S(\cdot)$ we obtain
$$\int_X\hat f_{s_1,s_2}( x) \,dm_ X =\int_X f(u_{e^{2t}(s_1-s_2)} x)f( x)\,dm_ X\le 2\tau^2e^{-t/2l}\|f\|_\infty ^2\le 2\tau^2e^{-t/2l}\mathcal S(f)^2.$$
Integrating over the region $|s_1-s_2|<e^{-t}e^{t/2l}$ and dividing everything by $\tau^2$ we get that the first term of the right side of inequality (\ref{ineq: two terms}) is smaller than
$$\ll \frac{1}{\tau^2}\mathcal S(f)^2\cdot 2\tau^2e^{-t/2l}\ll \mathcal S(f)^2\cdot e^{-t/2l}.$$
In total, we get this estimate of the right side of inequality (\ref{ineq: two terms}),
\begin{align*}
    |A|^2&\ll C\eta^{-L}\mathcal S(f)^2b^{-\varepsilon }\left(e^{-\kappa_Xt/2l}+e^{-t/2l}+ e^{-\ref{K:effec}t/2}\right)\\&\ll C
    \eta^{-L}\mathcal S(f)^2b^{-\varepsilon }e^{-\kappa_X t/2l}.
\end{align*}

We recall that we have $l=2\star \ell'\ref{K:effec}^{-1}$ and $e^{-4t}\le b$.  By choosing $$ \varepsilon\le \frac{\kappa_X \ref{K:effec}}{128\ell'}$$  we get 
$$|A|^2\ll  C\mathcal S(f)^2 \eta^{-L}e^{-t\kappa_X \ref{K:effec}/32l'}$$
and this finishes the proof after noting that $\ref{K:effec}=O(\kappa_X)$.
\end{proof}
