\title{Four-body physics in low-dimensional bosons with three-body interaction}
\author{V.~Polkanov\footnote{e-mail: cogersum92@gmail.com}}	
\author{O.~Hryhorchak\footnote{e-mail: hrorest@gmail.com}}
