    \begin{center}
    \includegraphics[width=1\columnwidth]{figures/sm_sqrt_iswap.pdf}
    \end{center}
    \caption{{\bf $\boldsymbol{\sqrt{\rm iSWAP}}$ gate decomposition.}
    The $\sqrt{\rm iSWAP}$ gate is decomposed into six Qiskit $U$ gates and two CZ gates, which can be realized in our experiment conveniently.
    }
