    \includegraphics[width=0.9\linewidth]{Figures/PSUcombined.pdf}
    \caption{ Noise power spectral density of different power rails produced by the power regulation stage measured using a Rohde $\&$ Schwartz (R$\&$S) FPL1007, +20\,V (blue), +8\,V (red), +5\,V (yellow), +3\,V (violet), -1\,V (green) for an input voltage of +26\,V.}
    \label{PSUcharac}
\end{figure}

\begin{figure}[htbp]
