\section{Observables}
\label{s.observables}

Our analysis considers a set of spin-dependent observables that can be described theoretically using collinear factorization in the framework of fixed order perturbative QCD. 
For each observable we utilize short-distance partonic cross sections computed at next-to-leading order (NLO) accuracy in the strong coupling, $\alpha_s$, as described in the following subsections.
Recent studies~\cite{Borsa:2024mss, Cruz-Martinez:2025ahf} showed that effects from higher orders, such as next-to-next-to-leading order, are surprisingly small.


% ..............................................................................
\subsection{Polarized inclusive DIS}
\label{ss.pidis}

The classical observables measured in polarized lepton DIS from a target $T$, $\vec \ell\,\, \vec T \to \ell\, X$, where $T$ represents a proton $p$, deuteron $d$, or $^3$He nucleus, are the longitudinal and transverse double-spin asymmetries~\cite{Sato:2016tuz},
%
\begin{subequations}
\begin{eqnarray}
A_{\parallel} &=& \frac{\sigma^{\uparrow\Uparrow} - \sigma^{\downarrow\Uparrow}}{\sigma^{\downarrow\Uparrow} + \sigma^{\uparrow\Uparrow}}\, ,
\\
A_{\perp} &=& \frac{\sigma^{\uparrow\Rightarrow} - \sigma^{\downarrow\Rightarrow}} {\sigma^{\downarrow\Rightarrow} + \sigma^{\uparrow\Rightarrow}},
\end{eqnarray}
\end{subequations}
%
where the superscript $\uparrow$ ($\downarrow$) on the cross section $\sigma$ denotes the spin of the lepton along (opposite to) the beam direction, $\Uparrow$ denotes the spin of the target nucleon along the beam direction, and $\Rightarrow$ represents the spin of the target perpendicular to the beam direction. 
%
The cross sections are functions of the standard DIS Lorentz invariant kinematic variables, namely, Bjorken $x$, lepton inelasticity $y$, and the variable $\gamma^2$, defined as
%
\begin{equation}
x = \frac{Q^2}{2 P \cdot q}\, , ~~~~~~
\\
y = \frac{P \cdot q}{P \cdot k}\, , ~~~~~~
\\
\gamma^2 = \frac{4 M^2 x^2}{Q^2}\, ,
\label{e.kinematic}
\end{equation}
%
where $k$, $P$ and $q$ are the four-momenta of the incident lepton, target nucleon (of mass $M$), and exchanged virtual photon, respectively, with $Q^2 \equiv -q^2$.
In terms of these variables, the longitudinal and transverse spin asymmetries can be written as
%
\begin{subequations}
\begin{eqnarray}
A_{\parallel} &=& D\, \pqty{A_1 + \eta A_2}\, ,
\\
A_{\perp} &=& d\, \pqty{A_2 - \zeta A_1}\, ,
\label{e.AparAperp}
\end{eqnarray}
\end{subequations}
%
where the kinematic prefactors are given by
%
\begin{subequations}
\begin{eqnarray}
D &=& \frac{y\, \pqty{2-y} \pqty{2 + \gamma^2 y}} {2 (1+\gamma)^2 y^2 + \big[ 4 \pqty{1-y} - \gamma^2 y^2 \big] \pqty{1+R}}\, , 
\label{e.D}
\\
d &= & \frac{\sqrt{4(1-y) - \gamma^2 y^2}}{2-y} D\, ,
\\
\eta &=& \gamma \frac{4 \pqty{1-y} - \gamma^2 y^2}{\pqty{2-y} \pqty{2 + \gamma^2 y}}\, ,
\\
\zeta &=& \gamma \frac{2-y}{2 + \gamma^2 y}\, .
\end{eqnarray}
\end{subequations}
%
The virtual photoproduction asymmetries $A_1$ and $A_2$ can be written in terms of ratios of the spin-dependent $g_1$ and $g_2$ and spin-averaged $F_1$ structure functions,
%
\begin{subequations}
\begin{eqnarray}
A_1 &=& \frac{( g_1 - \gamma^2 g_2 )}{F_1}\, , \\
A_2 &=& \frac{\gamma ( g_1 + g_2 )}{F_1}\, .
\label{e.A}
\end{eqnarray}
\end{subequations}
%
At large $Q^2$ the $A_1$ asymmetry is dominated by the $g_1$ structure function, while the $A_2$ asymmetry depends on the sum $g_1+g_2$, which is sometimes referred to as the transverse spin structure function, $g_T \equiv g_1+g_2$.
Measurements of $A_2$ are therefore crucial for determining the $g_2$ structure function.
In Eq.~(\ref{e.D}) $R$ is the ratio of longitudinal to transverse photoproduction cross sections, and is related to the unpolarized $F_1$ and $F_2$ structure functions by
%
\begin{equation}
R = \frac{\rho^2 F_2 - 2x F_1}{2x F_1}\, ,
\label{e.R}
\end{equation}
%
where 
%
\begin{equation}
\rho^2 = 1 + \gamma^2\, . %\frac{4 M^2 x^2}{Q^2}\, .
\label{e.rho}
\end{equation}
%
Each of the polarized and unpolarized structure functions is a function of two variables, typically taken to be the Bjorken variable $x$ and four-momentum transfer squared $Q^2$.


Applying QCD collinear factorization, the spin-dependent $g_1$ structure function can be written, up to ${\cal O}(M^2/Q^2)$ power corrections, in terms of the LT spin-dependent quark ($\Delta q$) and gluon ($\Delta g$) PDFs,
%
\begin{eqnarray}
g_1^{\mbox{\tiny \rm LT}}(x,Q^2) 
&=& \frac12 \sum_q e_q^2 
\big[ \Delta C_q^{\mbox{\tiny \rm DIS}} \otimes \Delta q^+ 
   + 2\Delta C_g^{\mbox{\tiny \rm DIS}} \otimes \Delta g 
\big](x,Q^2)\, ,
\label{e.g1LT}
\end{eqnarray}
%
where $\Delta q^+ \equiv \Delta q + \Delta \bar{q}$, and the sum runs over all quark flavors $q$.
Here the symbol $\otimes$ denotes the convolution integral,
%
\begin{equation}
\big[ \Delta C_f^{\mbox{\tiny \rm DIS}} \otimes \Delta f \big](x,Q^2)
\equiv \int_x^1 \frac{\diff \xi}{\xi}\,
\Delta C_f^{\mbox{\tiny \rm DIS}}(\xi,Q^2)\, \Delta f \Big( \frac{x}{\xi},Q^2 \Big)\, ,
\label{e.convolution}
\end{equation}
%
and we have chosen the renormalization and factorization scales for the DIS process to be $\mu^2 = Q^2$.
%
The perturbatively calculable polarized DIS hard scattering coefficients, $\Delta C_f^{\mbox{\tiny \rm DIS}}$ ($f = q$, $g$), are expanded to NLO in the strong coupling $\alpha_s$,
%
\begin{eqnarray}
\Delta C_f^{\mbox{\tiny \rm DIS}} 
= \Delta C_f^{\mbox{\tiny \rm DIS(0)}} 
+ \frac{\alpha_s}{4 \pi} \Delta C_f^{\mbox{\tiny \rm DIS(1)}}
+ \mathcal{O}(\alpha_s^2)\, ,
\end{eqnarray}
%
with the coefficient functions taken from Ref.~\cite{Floratos:1981hs}.
%
Note that at leading order in $\alpha_s$ the hard scattering coefficient $\Delta C_f^{\mbox{\tiny \rm DIS(0)}}(\xi,Q^2) \propto \delta(1-\xi)$, and the Bjorken scaling variable $x$ in Eq.~(\ref{e.kinematic}) coincides with the parton momentum fraction, while at NLO and beyond these are different.
At leading twist, the $g_2$ structure function can be related to $g_1$ through the Wandzura-Wilczek relation~\cite{Wandzura:1977qf},
%
\begin{eqnarray}
g_2^{\mbox{\tiny \rm LT}}(x,Q^2)
= -g_1^{\mbox{\tiny \rm LT}}(x,Q^2) 
+ \int_x^1 \frac{\diff z}{z} g_1^{\mbox{\tiny \rm LT}}(z,Q^2)\, .
\label{e.WW}
\end{eqnarray}


For analysis of DIS data at relatively small values of $Q^2 \gtrsim m_c^2$ and invariant mass squared of the unobserved hadronic system $X$,
%
\begin{eqnarray}
W^2 = (P+q)^2 = M^2 + \frac{(1-x)}{x} Q^2\, ,
\label{e.W2}
\end{eqnarray}
%
power corrections of the type ${\cal O}(M^2/Q^2)$ may not be negligible for some lower energy datasets. Typically a cut in $W^2$ needs to be made to ensure that the theoretical framework is able to accommodate the data.
It is well known that one can extend the reach of a perturbative QCD description of DIS data by taking into account the kinematical target mass corrections (TMCs)~\cite{Jimenez-Delgado:2013boa, Sato:2016tuz, Schienbein:2007gr}, which can be applied to the polarized structure functions to incorporate $M^2/Q^2$ corrections.
These corrections scale with the Nachtmann variable $\xn$, where \cite{Nachtmann:1973mr, Greenberg:1971lpf}
%
\begin{eqnarray}
\xn = \frac{2x}{1+\rho}\, .
\end{eqnarray}
%
In the collinear factorization framework, the $g_1$ and $g_2$ structure functions, including TMCs, can be written as
%
\begin{subequations}
\begin{eqnarray}
g_1^{\mbox{\tiny \rm TMC}}(x,Q^2)
&=& \frac{1}{\rho^2} 
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2)
 +  \frac{2(\rho-1)}{\rho^2} \int_{\xn}^1 \frac{\diff z}{z} 
    g_1^{\mbox{\tiny \rm LT}}(z,Q^2)\, ,
\label{e.CFtmc1}
\\
g_2^{\mbox{\tiny \rm TMC}}(x,Q^2) 
&=& -\frac{1}{\rho^2} 
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2) 
+  \frac{2}{(1+\rho) \rho^2} \int_{\xn}^1 \frac{\diff z}{z} 
    g_1^{\mbox{\tiny \rm LT}}(z,Q^2)\, .
\label{e.CFtmc2}
\end{eqnarray}
\label{e.CFtmc}%
\end{subequations}
%
In the limit $M^2/Q^2 \to 0$, one has $\rho \to 1$ and $\xn \to x$, and the LT results in Eqs.~(\ref{e.g1LT}) and (\ref{e.WW}) are recovered,
    $g_{1,2}^{\mbox{\tiny \rm TMC}}(x,Q^2) \to 
     g_{1,2}^{\mbox{\tiny \rm LT}}(x,Q^2)$.
Note that the lower limit of the integral from the Wandzura-Wilczek relation, \eref{e.WW}, is now $\xn$ rather than $x$.
A derivation of Eqs.~(\ref{e.CFtmc}) is given in Appendix~\ref{a.TMC-CF}.


Alternative TMC prescriptions have also been used in the literature~\cite{Wandzura:1977qf, Matsuda:1979ad, Piccione:1997zh, Blumlein:1998nv, Accardi:2008pc}, the most common of which is that based on the operator product expansion, along the lines of the unpolarized TMC prescription of Georgi and Politzer~\cite{Georgi:1976ve}.
This prescription was used in the early JAM spin PDF analysis of inclusive DIS data at low $Q^2$~\cite{Sato:2016tuz}.
For consistency with the application of collinear factorization across other processes considered beyond inclusive DIS, such as those in the current analysis, we will utilize the TMC results for the collinear factorization given in Eqs.~(\ref{e.CFtmc}).


One immediate consequence of Eqs.~(\ref{e.CFtmc}), as in other TMC approaches, is that for nonzero $M^2/Q^2$, as $x \to 1$ one has $\xn < 1$, and hence a nonzero structure function at $x = 1$.
The fact that the TMC structure functions do not vanish as $x \to 1$ is known as the ``threshold problem" \cite{Georgi:1976ve, DeRujula:1976baf, DeRujula:1976ih} and has been discussed in the literature~\cite{Bitar:1978cj, Steffens:2006ds, Schienbein:2007gr, Steffens:2012jx}.
This problem is only relevant in the nucleon resonance region, well below values of $W^2$ where perturbative QCD is applicable, so in practice it will not be relevant for this analysis.


From phenomenological analyses it is also well established~\cite{Jimenez-Delgado:2013boa, Sato:2016tuz, Owens:2012bv, Accardi:2016qay, Melnitchouk:2005zr} that in the region where TMCs play a role, namely at low $Q^2$ and high $x$, other power corrections, such as those associated with higher twists, or multi-parton correlations, also need to be considered.
These are implemented in the standard manner by adding a phenomenological higher twist (HT) term.
For the $g_1$ structure function the HT contribution is power suppressed relative to the leading term, Eq.~(\ref{e.CFtmc1}), while for the $g_2$ structure function the HT correction to the LT term (\ref{e.CFtmc2}) is of the same order in $Q^2$~\cite{Jaffe:1990qh, Anselmino:1994gn},
%
\begin{eqnarray}
g_1^{\mbox{\tiny \rm HT}} 
= \frac{c^{\mbox{\tiny \rm HT}}_1}{Q^2}\, ,
\qquad
&&
g_2^{\mbox{\tiny \rm HT}} 
= c^{\mbox{\tiny \rm HT}}_2,
\label{e.g12HT}
\end{eqnarray}
%
with the shapes of the $x$-dependent functions 
    $c_{1,2}^{\mbox{\tiny \rm HT}} \equiv c_{1,2}^{\mbox{\tiny \rm HT}}(x)$
inferred from experimental data.
%
The total spin-dependent structure functions in our framework are given by the sum of the LT and HT contributions,
%
\begin{align}
g_{i} = g_{i}^{\mbox{\tiny \rm TMC}} + g_{i}^{\mbox{\tiny \rm HT}}\, ,
\qquad i=1,2.
\end{align}
%
In our numerical analysis both the parameter sets describing the LT and HT functions will be extracted from data.


For inclusive polarized DIS, our datasets include scattering from protons, as well as deuterium and $^3$He nuclei.
For nuclear targets, the structure functions are computed taking into account the wave functions of the nucleons in the polarized nuclei.
It was shown in earlier studies that this can be written in the form of a generalized convolution~\cite{Melnitchouk:1994tx, Kulagin:1994cj, Piller:1995mf, Kulagin:2007ph, Kulagin:2008fm, Jimenez-Delgado:2013boa},
%
\begin{eqnarray}
g_i^A(x,Q^2)
&=& \sum_N \big[ \Delta f_{ij}^{N/A} \otimes g_j^N \big](x,Q^2), \qquad
(i,j = 1,2), 
\label{e.giA}
\end{eqnarray}
%
where the spin-dependent smearing functions $\Delta f_{ij}^{N/A}$ are functions of the light-cone momentum fraction $y_N = p_N \cdot q / P_A \cdot q$ of the nucleus carried by the interacting nucleon, and the finite-$Q^2$ parameter $\gamma$.
The nuclear smearing effects are known to become important at large values of $x$~\cite{Kulagin:2007ph, Kulagin:2008fm, Jimenez-Delgado:2013boa}, but for $x \ll 1$ one may approximate the nuclear structure functions in terms of effective polarizations, 
%
$\int \dd{y_N}\, \Delta f_{ij}^{N/A}(y_N,\gamma) = \delta_{ij}\, {\cal P}_{N/A}\, \delta(1-y_N)$.
%
In this effective polarization approximation, the nuclear effects are independent of $x$.
In practice, however, since we include data in the high-$x$ region, our calculations are performed using the full convolution in Eq.~(\ref{e.giA}), with the polarized smearing functions normalized to the effective polarizations ${\cal P}_{N/A}$, as discussed in Refs.~\cite{Kulagin:2007ph, Kulagin:2008fm}.


Integrating the structure functions over $x$, we can define their lowest moments as
%
\begin{eqnarray}
\Gamma_i(Q^2) &=& \int_0^1 \dd{x} g_i(x,Q^2), \qquad i=1,2.
\end{eqnarray}
%
For the $g_1$ structure function of the proton, the lowest moment can be written, including ${\cal O}(\alpha_s)$ corrections, in terms of axial vector charges as
%
\begin{eqnarray}
\Gamma_1^{\mbox{\tiny \rm LT}}(Q^2)
&=& \bigg( 1 - \frac{\alpha_s(Q^2)}{\pi} \bigg) 
\bigg(
  \frac{1}{12}\, g_A + \frac{1}{36}\, a_8 + \frac{1}{9}\, \Delta\Sigma
\bigg),
\label{e.Gamma1LT}
\end{eqnarray}
%
where 
%
\begin{subequations}
\label{e.axialcharges}
\begin{eqnarray}
g_A &=& \int_0^1 \dd{x} [\Delta u^+ - \Delta d^+](x,Q^2), 
\label{e.axialcharges.gA}\\
a_8 &=& \int_0^1 \dd{x} [\Delta u^+ + \Delta d^+ - 2 \Delta s^+](x,Q^2), \\
\Delta\Sigma &=& \int_0^1 \dd{x} \sum_q \Delta q^+(x,Q^2),
\end{eqnarray}
\end{subequations}%
%
are the quark triplet, octet, and singlet axial charges, respectively.
Note that both $g_A$ and $a_8$ are scale invariant, while $\Delta\Sigma = \Delta\Sigma(Q^2)$ explicitly depends on the scale $Q^2$.
For the PDFs in the neutron, we use charge symmetry~\cite{Londergan:2009kj} to relate these to those in the proton, with the interchange $u \leftrightarrow d$.


For the lowest moment of the $g_2$ structure function, in the LT approximation $\Gamma_2^{\mbox{\tiny \rm LT}}$ satisfies the Burkhardt-Cottingham (BC) sum rule~\cite{Burkhardt:1970ti},
%
\begin{eqnarray}
\Gamma_2^{\mbox{\tiny \rm LT}}(Q^2) &=& 0.
\label{e.BCSR}
\end{eqnarray}
%
Phenomenologically, violation of the BC sum rule would suggest the presence of power corrections to $g_2$.
An additional combination of the spin structure functions which also directly reveals power corrections is the $d_2$ matrix element, defined in terms of the $x^2$-weighted moments of $g_1$ and $g_2$,
%
\begin{eqnarray}
d_2(Q^2) &=& \int_0^1 \dd{x} x^2\, \big[ 2 g_1(x,Q^2) + 3 g_2(x,Q^2) \big].
\label{e.d2}
\end{eqnarray}
%
From the Wandzura-Wilczek relation (\ref{e.WW}), one can immediately see that the LT part of this combination vanishes, $d_2^{\mbox{\tiny \rm LT}} = 0$, so that nonzero values can only arise from power corrections associated with target mass effects or higher twist contributions.
These contributions can be related to matrix elements describing the nucleon's color polarizability~\cite{Ji:1993sv, Stein:1994zk, Stein:1995si} or the transverse color force~\cite{Burkardt:2008ps} acting on quarks. 


