\section{Target mass corrections in collinear factorization}
\label{a.TMC-CF}

Following the derivation by Moffat {\it et al.}~\cite{Moffat:2019qll} of the unpolarized $F_1$ and $F_2$ structure functions at finite values of $M^2/Q^2$, in this appendix we outline the steps in the corresponding derivation of the spin-dependent structure functions $g_1$ and $g_2$ in the presence of hadron masses.
As usual, we define the Nachtmann scaling variable as
%
\begin{equation}
\xn = \frac{2x}{1+\rho},
\qquad \rho^2 = 1 + \frac{4x^2 M^2}{Q^2}\, .
\end{equation}
%
Neglecting lepton masses, the hadronic tensor for polarized DIS in the one-photon exchange approximation is given by
%
\begin{eqnarray}
W_{\mu\nu} 
&=& i \epsilon_{\mu \nu \alpha \beta} \frac{q^{\alpha}}{P \cdot q} 
\bigg[ S^{\beta}\, g_1(x,Q^2) 
    + \Big( S^{\beta} - \frac{S \cdot q}{P \cdot q} P^{\beta} \Big)\, g_2(x,Q^2) 
\bigg],
\label{e.hadrontensorCF}
\end{eqnarray}
%
where the structure functions $g_1$ and $g_2$ contain all $M^2/Q^2$ target mass corrections.


In the Breit frame the four-momenta of the target nucleon $P = (P^+, P^-, \bm{P}_\perp)$ and virtual photon $q = (q^+, q^-, \bm{q}_\perp)$ can be written in light-front coordinates as
%
\begin{eqnarray}
P &=& \bigg( \frac{Q}{\sqrt{2} \xn}, \frac{\xn M^2}{\sqrt{2} Q}, \bm{0}_{\perp} \bigg),
\qquad
% \\
q = \bigg( \!-\frac{Q}{\sqrt{2}}, \frac{Q}{\sqrt{2}}, \bm{0}_{\perp} \bigg),
\label{e.breitPq}
\end{eqnarray}
%
respectively.
The covariant spin vector $S$ is given by
%
\begin{eqnarray}
S = M\, \bigg( \lambda \frac{P^+}{M}, -\lambda \frac{M}{2 P^+}, \bm{S}_{\perp} \bigg),
\label{e.covariantS}
\end{eqnarray}
%
and satisfies the relations $P \cdot S$ = 0 and $S^2 = -M^2$.
%
In the massless target limit, $M \to 0$, the ``$-$'' components of $P$ and $S$ vanish, and we can define ``massless'' four-vectors $\widetilde{P}$ and $\widetilde{S}$ by
%
\begin{eqnarray}
\widetilde{P} = \bigg( \frac{Q}{\sqrt{2} \xn}, 0, \bm{0}_{\perp} \bigg),
~~~~~~
\widetilde{S} = M \bigg( \lambda \frac{P^+}{M}, 0, \bm{S}_{\perp} \bigg),
\label{e.MTA_PS}
\end{eqnarray}
%
keeping the transverse component of the spin vector.


With this notation one can write the hadronic tensor as
%
\begin{eqnarray}
W_{\mu \nu}
= i \epsilon_{\mu \nu \alpha \beta} \frac{q^{\alpha}}{\widetilde{P} \cdot q}
\bigg[ \widetilde{S}^{\beta}\, \widetilde{g}_1(x,Q^2) 
    + \Big( \widetilde{S}^{\beta} - \frac{\widetilde{S} \cdot q}{\widetilde{P}
        \cdot q} \widetilde{P}^{\beta}  
      \Big)\, \widetilde{g}_2(x,Q^2)
\bigg],
\label{e.hadrontensortilde}
\end{eqnarray}
%
where the structure functions $\widetilde{g}_{1,2}$ do not contain the $M^2/Q^2$ corrections, in contrast to those in \eref{e.hadrontensorCF}.  
The hadronic tensors in \eref{e.hadrontensorCF} and \eref{e.hadrontensortilde} must be equal, as they are simply the same object expressed in terms of two choices of basis tensors.


Using the relations
%
\begin{subequations}
\begin{eqnarray}
\widetilde{P}^{\mu} 
&=& \frac{1}{Q^2 + \xn^2 M^2} \big( Q^2 P^{\mu} - \xn M^2 q^{\mu} \big),
\\
\widetilde{S}^{\mu} 
&=& S^{\mu} + \lambda \frac{\xn M^2}{Q^2 + \xn^2 M^2} \big( \xn P^{\mu} + q^{\mu} \big),
\label{e.PSrelations}
\end{eqnarray}
\end{subequations}
%
one can then write
%
\begin{subequations}
\begin{eqnarray}
i \epsilon_{\mu \nu \alpha \beta} \frac{q^{\alpha}}{\widetilde{P} \cdot q} \widetilde{S}^{\beta} &=& i \epsilon_{\mu \nu \alpha \beta} \frac{q^{\alpha}}{P \cdot q} 
\bigg[ \frac{(Q^2 - \xn^2 M^2)(Q^2 + 3 \xn^2 M^2)}{(Q^2 + \xn^2 M^2)^2} 
S^{\beta}
\notag\\
& & \hspace*{2cm} -\, \frac{\xn^2 M^2}{Q^2} \frac{(Q^2 - \xn^2 M^2)^2}{(Q^2 + \xn^2 M^2)^2} 
\Big( 
S^{\beta} - \frac{S \cdot q}{P \cdot q} P^{\beta}   
\Big) 
\bigg],
\label{e.CFrelation1}
\end{eqnarray}
%
and
%
\begin{eqnarray}
i \epsilon_{\mu \nu \alpha \beta} \frac{q^{\alpha}}{\widetilde{P} \cdot q} 
\big(
\widetilde{S}^{\beta} 
- \frac{\widetilde{S} \cdot q}{\widetilde{P} \cdot q} \widetilde{P}^{\beta}
\big)
&=& 
i \epsilon_{\mu \nu \alpha \beta}
\frac{q^{\alpha}}{P \cdot q} 
\bigg[ 4\xn^2 M^2 \frac{Q^2 - \xn^2 M^2}{(Q^2 + \xn^2 M^2)^2} 
S^{\beta}
\notag\\
%
& & \hspace*{1cm} +\, \frac{(Q^2 - \xn^2 M^2)^3}{Q^2(Q^2 + \xn^2 M^2)^2} 
\Big( 
S^{\beta} - \frac{S \cdot q}{P \cdot q} P^{\beta}   
\Big) 
\bigg].
\label{e.CFrelation2}
\end{eqnarray}
\end{subequations}
%
Substituting Eqs.~(\ref{e.CFrelation1}) and (\ref{e.CFrelation2}) into \eref{e.hadrontensortilde} and comparing the tensor structures to \eref{e.hadrontensorCF} leads to the relations
%
\begin{subequations}
\begin{eqnarray}
g_1(x,Q^2) 
&=& \frac{(Q^2 - \xn^2 M^2)(Q^2 + 3 \xn^2 M^2)}{(Q^2 + \xn^2 M^2)^2}\, 
    \widetilde{g}_1(x,Q^2) 
 +  4 \xn^2 M^2 \frac{(Q^2 - \xn^2 M^2)}{(Q^2 + \xn^2 M^2)^2}\, 
    \widetilde{g}_2(x,Q^2),
\notag\\
& &
\\
g_2(x,Q^2) 
&=& - \frac{\xn^2}{Q^2} \frac{(Q^2 - \xn^2 M^2)^2}{(Q^2 + \xn^2 M^2)^2}\,
    \widetilde{g}_1(x,Q^2)
 +  \frac{(Q^2 - \xn^2 M^2)^3}{Q^2(Q^2 + \xn^2 M^2)^2}\, 
    \widetilde{g}_2(x,Q^2),
\end{eqnarray}
\end{subequations}
%
which can be rewritten in terms of $\rho$ as
%
\begin{subequations}
\begin{eqnarray}
g_1(x,Q^2)  
&=& \frac{2\rho -1}{\rho^2}\, \widetilde{g}_1(x,Q^2) 
 +  \frac{2(\rho -1)}{\rho^2}\, \widetilde{g}_2(x,Q^2),
\label{e.g1CFrelation1}
\\
g_2(x,Q^2)  
&=& \frac{1-\rho}{(1+\rho)\rho^2}\, \widetilde{g}_1(x,Q^2) 
 +  \frac{2}{(1+\rho)\rho^2}\, \widetilde{g}_2(x,Q^2).
\label{e.g2CFrelation2}
\end{eqnarray}
\end{subequations}
%
Equations~(\ref{e.g1CFrelation1}) and (\ref{e.g2CFrelation2}) then represent the general, model-independent relation between the massless limit structure functions and those evaluated at finite values of $M^2/Q^2$, without any kinematical or dynamical approximations. 


Within the standard collinear factorization framework~\cite{Collins:2011zzd}, in the LT approximation the structure functions can be written in factorized form in terms of PDFs and hard coefficient functions~(\ref{e.g1LT}), but with the lower limit of integration in the convolution integral~(\ref{e.convolution}) equal to the Nachtmann scaling variable $\xn$.
Namely, without making any massless target approximations, in collinear factorization one has
%
\begin{subequations}
\begin{eqnarray}
\widetilde g_1(x,Q^2) \to g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2),
\\
\widetilde g_2(x,Q^2) \to g_2^{\mbox{\tiny \rm LT}}(\xn,Q^2).
\end{eqnarray}
\end{subequations}
%
Using the Wandzura-Wilczek relation is to write $g_2^{\mbox{\tiny \rm LT}}$ in terms of $g_1^{\mbox{\tiny \rm LT}}$~\cite{Wandzura:1977qf} then leads to
%
\begin{subequations}
\begin{eqnarray}
g_1^{\mbox{\tiny \rm TMC}} (x,Q^2)
&=& \frac{2\rho - 1}{\rho^2}\,
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2) 
  + \frac{2(\rho -1)}{\rho^2}
    \Big( -g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2)
        + \int_{\xn}^1 \frac{\diff z}{z} g_1^{\mbox{\tiny \rm LT}}(z,Q^2)
    \Big),
\notag\\
& &
\\
\!\!\!g_2^{\mbox{\tiny \rm TMC}}(x,Q^2)
&=& \frac{1-\rho}{(1+\rho)\rho^2}\, 
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2) 
 +  \frac{2}{(1+\rho)\rho^2}\, 
    \Big( -g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2)
        + \int_{\xn}^1 \frac{\diff z}{z} 
    g_1^{\mbox{\tiny \rm LT}}(z,Q^2)
    \Big).
\notag\\
& &
\end{eqnarray}
\end{subequations}
%
After simplifying, we obtain
%
\begin{subequations}
\begin{eqnarray}
g_1^{\mbox{\tiny \rm TMC}}(x,Q^2) 
&=& \frac{1}{\rho^2} 
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2) 
 +  \frac{2(\rho-1)}{\rho^2} \int_{\xn}^1 \frac{\diff z}{z} 
    g_1^{\mbox{\tiny \rm LT}}(z,Q^2), 
\\
g_2^{\mbox{\tiny \rm TMC}}(x,Q^2) 
&=& -\frac{1}{\rho^2} 
    g_1^{\mbox{\tiny \rm LT}}(\xn,Q^2) 
 +  \frac{2}{(1+\rho) \rho^2} \int_{\xn}^1 \frac{\diff z}{z} 
    g_1^{\mbox{\tiny \rm LT}}(z,Q^2),
\end{eqnarray}
\end{subequations}
%
as in Eqs.~(\ref{e.CFtmc}).


