\subsection{Products}    

Multiproducts of Floer complexes are required to achieve an $A_{_{\infty}}$-structure on the Floer cohomology. Consider intersections  

\begin{equation}  
p_{_i}\ \in \ L_{_{i-1}}\cap L_{_i}\ \ \ \ , \ \ \ \ q\ \in \ L_{_o}\ \cap \ L_{_k} \ \ \ \ , i=1, ... ,k,      
\end{equation}  
and choose $k+1$ fixed points on the boundary of $D^{^2}$. Let $\hat{\cal M}\left(p_{_1},...,p_{_k},q;[u],J\right)$ be the moduli space of pseudoholomorphic curves  

\begin{equation}  
u:\ D^{^2}\ \longrightarrow\ M  
\end{equation}  
of finite energy is the homotopy class 

\begin{equation}  
[u]\ \in \ \pi_{_2}\left(M, \bigcup_{_{i=0}}^{^k}L_{_i}\right).  
\end{equation}  




For example, for $k=2$, there are 3 Lagrangians and 3 intesection points. The Maslov index, in this case, reads  

\begin{equation}  
\text{Ind}([u])\ =\ \text{deg}(q)-\sum_{_{i=1}}^{^k}\text{deg}\left(p_{_i}\right)  
\end{equation}

\begin{equation}  
\begin{aligned}
\Rightarrow\ \ \ \text{dim}{\cal M}\ &=\ \text{dim}\hat{\cal M}\ +\ (k+1)-3\\
&=\ \text{Ind}([u])+k-2.  
\end{aligned}  
\end{equation}

\subsubsection*{Multi-product operation}  

\begin{equation}  
\mu_{_k}:\ CF\left(L_{_{k-1}}, L_{_k}\right)\ \otimes\ ...\ \otimes\ CF\left(L_{_0}, L_{_1}\right)\ \longrightarrow\ CF\left(L_{_0}, L_{_k}\right)  
\end{equation}
are $\Lambda$-linear maps defined as follows  

\begin{equation}  
\mu_{_k}\left(p_{_k},...,p_{_1}\right)\ =\ \sum_{_{q\in\ \chi(L_{_o},L_{_k})}}\left(n.{\cal M}\left(p_{_1},...,p_{_k},q;[u],J\right)\right)\ T^{^{\omega([u])}}\ q.  
\end{equation}

\subsection{$A_{_{\infty}}$-categories}  

Multilinear maps $\mu_{_k}$ of degree $2-k$ 

\begin{equation}  
\mu_{_k}:\ \text{Hom}_{_{\cal A}}\left(A_{_{k-1}},A_{_k}\right)\ \otimes\ ...\ \otimes\ \text{Hom}_{_{\cal A}}\left(A_{_0},A_{_1}\right)\ \longrightarrow\ \text{Hom}_{_{\cal A}}\left(A_{_0},A_{_k}\right)\ [2-k],    
\end{equation}
satisfying the $A_{_{\infty}}$ relations  

\begin{equation}  
\sum_{_{l=1}}^{^k}\sum_{_{j=0}}^{^{k-l}}\ (-1)^{^{\sigma}}\mu_{_{k+1-l}}\left(f_{_1},...f_{_{j+l+1}},\mu_{_l}\left(f_{_{j+l}},...,f_{_{j+1}}\right), f_{_j}, ..., f_{_1}\right)\ =\ 0,    
\end{equation}  
where   

\begin{equation}  
\sigma\ =\ j+\text{deg}\left(f_{_1}\right)+...+\text{deg}\left(f_{_j}\right)\ \ \ \ , \ \ \ \ f_{_i}\ \in\ \text{Hom}_{_{\cal A}}\left(A_{_{i-1}}, A_{_i}\right)\ \ \ \ \text{for}\ \ i=1,..., k.   
\end{equation}


\subsection{Graded Lagrangian submanifolds}  
$\mathbb{Z}$-grading of Floer complex. 

In order to give a $\mathbb{Z}$-grading of the generators of teh floer complex, we need some extra data of the Lagrangian manifolds $L_{_o}, L_{_1}$: a choice of the graded lift of the canonical section of the Lagrangian submanifold defines a \emph{graded Lagrangian submanifold}.  

Two conditions need to be met to ensure the existence of such lifts:  
\begin{enumerate}  


\item The 1$^{^{st}}$ Chern class of $M$ must be 2-torsion, namely 

\begin{equation}  
2c_{_1}(TM)\ =\ 0.  
\end{equation}

\item  The Maslov class of $L_{_i}$, 

\begin{equation}  
\mu_{_{L_{_i}}}\ \in\ H^{^1}\left(L_{_i},\mathbb{Z}\right)  
\end{equation}  
must be 0 for $i=0,1$.   

\medskip 


\underline{Some preliminary material}  

\medskip 

Denoting by LGr$(TM)$ the Lagrangian Grassmann of $M$, i.e. the fiber of LGr$(TM)$ is the Lagrangian Grassmannian of $T_{_p}M$, to construct the \emph{grading structure} of Lagrangian submanifolds, we need to construct a map  

\begin{equation}
    \Omega:\ \text{LGr}(TM)\ \rightarrow\ S^{^1},    
\end{equation}
corresponding to the existence of the following commutative diagram 


\begin{figure}[ht!]  
\begin{center} 
\includegraphics[scale=0.8]{LGr.pdf} 
\end{center} 
\end{figure}

\end{enumerate} 

LGr$(n)$ denotes the \emph{Lagrangian Grassmannian}, consisting of all Lagrangian subspaces of $\left(\mathbb{R}^{^{2n}},\omega_{_o}\right)$, where $\omega_{_o}$ is the standard symplecting form of $\mathbb{R}^{^2n}$.   

Let $\Theta$ denote a nowhere vanishing section of $\left(\Lambda^{^n}_{_{\mathbb{C}}}T^{^*}M\right)^{^{\otimes 2}}$. For any Lagrangian subspace         

\begin{equation}   
L_{_p}\ \in\ \text{LGr}\left(T_{_p}M\right)  
\end{equation}  
define  

\begin{equation}   
\Omega\left(L_{_p}\right)\ \overset{def.}{=}\ \frac{\Theta\left(v_{_1}, ...,v_{_n},v_{_n}\right)}{\bigg|\Theta\left(v_{_1}, ...,v_{_n},v_{_n}\right)\bigg|} , 
\end{equation}
with $\{v_{_i}\}$ denoting a real basis of $L_{_p}$. $\Omega$ is independent w.r.t. $\{v_{_i}\}$, and is a fiberwise det$^{^2}$-map, also referred to as the \emph{Calabi-Yau form}.  

Defining the phase square map as    

\begin{equation}  
\varphi_{_L}\ \overset{def.}{=}\ \Omega\circ s_{_L}:\ L\ \rightarrow\ S^{^1}  
\end{equation}
where $s_{_L}(p)\ T_{_p}L\ \in\ \text{LGr}(T_{_p}M)$, a \emph{grading} of the Lagrangian submanifold $L$ is defined by a choice of the lifting of the phase square map through the standard covering  

\begin{equation} 
e^{^{2\pi it}}:\ \mathbb{R}\ \longrightarrow\ S^{^1}  \
\end{equation}  
namely a choice of $\varphi_{_L}$ in the following commutative diagram   



\begin{figure}[ht!]  
\begin{center} 
\includegraphics[scale=0.8]{graded.pdf} 
\end{center} 
\end{figure}   


A graded Lagrangian submanifold is therefore defined by a pair  

\begin{equation}  
\tilde L\ \overset{def.}{=}\ \left(L,\tilde\varphi_{_L}\right).  
\end{equation}   

Let   

\begin{equation}   
\tilde{\text{LGr}}(TM)\ \longrightarrow\ \text{LGr}(TM)    
\end{equation}  
be the pullback covering space of $\mathbb{R}\rightarrow S^{^1}$ through $\Omega$. By the isomorphism 

\begin{equation}  
\text{det}^{^2}_{_*}:\ \pi_{_1}\left(U(n)/O(n)\right)\ \rightarrow\ \pi_{_1}(S^{^1})  
\end{equation}   
and that $\Omega$ is fiberwisely equivalent to det$^{^2}$, the pullback bundle $\tilde{\text{LGr}}(TM)$ is a fiberwise universal covering of LGr$(TM)$. 
Let 

\begin{equation}  
\tilde{\Omega}:\ \tilde{\text{LGr}}(TM)\ \rightarrow\ \mathbb{R}  
\end{equation} 
be the unique lifting of $\Omega$ via the covering maps.  

There is a 1-to-1 correspondence between the lifting sections $\tilde{\varphi}_{_L}\equiv\tilde{\Omega}\circ\tilde{s}_{_L}$, implying a grading of $L$ can be equivalently defined as a choice of the lifting conical section $\tilde{\varphi}_{_L}$. To tell whether such a lifting exists, we need  to introduce the notion of the Maslov class.  

The Maslov class, $\mu_{_L}$, of a Lagrangian submanifold $L$ is defined to be the first $\mathbb{Z}$-coefficient cohomology class of $L$ corresponding to the homotopy class of the phase square map $\varphi_{_L}$, namely  


\begin{equation}  
\mu_{_L}\ =\ \left[\varphi_{_L}\right]\ \in\ \left[L,S^{^1}\right]\ \simeq\ \text{Hom}\left(\pi_{_1}(L),\mathbb{Z}\right)\ \simeq\ H^{^1}(L,\mathbb{Z}).  \end{equation}   

The Maslov class is the obstruction to lifting $\varphi_{_L}$ through the standard covering $\mathbb{R}\rightarrow\mathbb{Z}$,meaning the existence of such a lifting is equivalent to $\left[\varphi_{_L}\right]=0$.

Hence, under the conditions   

\begin{equation}  
2c_{_1}(TM)\ =\ 0\ \ \  \ \  \ \ , \ \ \  \ \  \ \ \mu_{_L}\ =\ 0   ,   
\end{equation}
we can equip $L$ with a grading. For every connected component of $L$, the choices of the grading are in 1-to-1 correspondence to $\mathbb{Z}$. 

The $\mathbb{Z}$-grading of the Floer complex between two graded Lagrangians, $\tilde L_{_0}, \tilde L_{_1}$, is defined as follows. Given $p\in\tilde L_{_0}\cap\tilde L_{_1}$, 

\begin{equation}   
p\ \in \ CF\left(\tilde L_{_0}, \tilde L_{_1}\right),  
\end{equation}
choose a path from $\tilde s_{_{L_{_0}}}$ to $\tilde s_{_{L_{_1}}}$ in $\tilde{\text{LGr}}\left(T_{_p}M\right)$, and then projecting to $\text{LGr}\left(T_{_p}M\right)$.

The homotopy class of the projected path does not rely on the choice of the path in the fiberwise universal covering space $\tilde{\text{LGr}}\left(T_{_p}M\right)$. 
Concatenating this projected path with the canonical short path from $T_{_p}L_{_1}$ to $T_{_p}L_{_0}$ to get a loop in LGr$\left(T_{_p}M\right)$. Then, the degree of $p$ is defined to be the Maslov index of the loop.  The Maslov index is therefore obtained as the change in degree of two intersections


\begin{equation}   
\text{ind}([u])\ = \ \text{deg}(q)\ -\ \text{deg}(p).  \end{equation}  

In particular, the Floer differential, $\partial$, is of degree 1. Altogether, this provides the definition of the chain complex of the Floer complex $CF\left(\tilde{L}_{_0},\tilde{L}_{_1}\right)$, leading to the Floer cohomology  

\begin{equation}  
HF\left(\tilde{L}_{_0},\tilde{L}_{_1}\right)\ \overset{def.}{=}\ H^{^{\bullet}}\left(CF\left(\tilde{L}_{_0},\tilde{L}_{_1}\right), \partial\right). 
\end{equation}


\subsubsection{Fukaya category (the complete version)}  

\underline{Lagrangian branes}  

Let $\left(M,\phi_{_M}\right)$ be a symplectic manifold with $2c_{_1}(M)=0$, equipped with a compatible almost complex structure $I_{_M}$. Choose a quadratic complex volume form, $\eta_{_M}^{^2}$, i.e. a nowhere vanishing zero section of the bicanonical bundle  

\begin{equation}  
K_{_M}^{^2}\ =\ \lambda_{_{\mathbb{C}}}^{^{\text{top}}}(TM)^{^{\otimes-2}}.     
\end{equation}

Let 


\begin{equation}  
\alpha_{_M}:\ \text{Gr}(TM)\ \rightarrow\ S^{^1}  
\end{equation}  
be the associated squared phase map. A Lagrangian brane is a triple  

\begin{equation}  
\tilde L\ \overset{def.}{=}\ \left(L,\tilde \alpha,\tilde P\right)  
\end{equation}   
consisting of a Lagrangian submanifold $L\subset M$ and a brane structure $\left(\tilde \alpha, \tilde P\right)$ on the sub-bundle 

\begin{equation}  
TL\ \subset\ TM|_{_L}.       
\end{equation}

Concretely, this consists of a function 

\begin{equation}  
\tilde\alpha:\ L\ \rightarrow\ \mathbb{R}  
\end{equation}  
such that 

\begin{equation}  
\exp\left(2\pi i\tilde \alpha(x)\right)\ =\ \alpha_{_M}\left(TL_{_x}\right)  
\end{equation}
defines the grading of $L$, together with a Pin structure, $\tilde P$ for $TL$. The Maslov class, namely the obstruction to the existence of a grading, $\mu_{_L}\in H^{^1}(L)$, maps to the relative 1$^{st}$ Chern class $2c_{_1}(M,L)$ under the boundary map  

\begin{equation}   
H^{^1}(L)\ \rightarrow\ H^{^2}(M,L)  
\end{equation}  



\section{Categories of coherent sheaves} 

\subsection*{Finite generation, finite presentation and coherence}  

Prior to getting to sheaves, it is instructive to discuss some finiteness properties for modules over a commutative ring $R$. An $R$-module\footnote{$R$ is \emph{Noetherian} if every ideal is finitely-generated, implying a submodule of a finitely-generated module is finitely-generated. If $R$ is not Noetherian, then finite-generation is too weak, in which case we need to introduce a stronger notion.}, $M$, is finitely-generated, or of finite type, if there is a finite set $\{m_{_1},...,m_{_n}\}\ \subset\ M$, such that every element of $M$ is an $R$-linear combination of the $m_{_i}$'s. This is equivalent to having a surjective $R$-module homomorphism, $R^{^n}\ \rightarrow\ M$, where the $i^{^{th}}$-standard basis vector maps to $m_{_i}$.     

\medskip    

\underline{Lemma}  

\medskip 

The following are equivalent:  

\begin{enumerate} 

\item   There exists an exact sequence  

\begin{equation}  \mathbb{R^{^a}}\ \rightarrow\ R^{^b}\ \rightarrow\ M\ \rightarrow\ 0  
\end{equation}   

\item  $M$ is finitely-generated and the kernel of any surjection $R^{^n}\rightarrow M$ is finitely-generated.

\end{enumerate}  

$M$ is said to be \emph{coherent} if it is finitely-generated and all its finitely-generated modules are finitely-presented. In particular, $M$ is finitely presented. Over a Noetherian ring, coherence, finite presentation and finite generation are equivalent, however, this is not true in general.  Furthermore, coherence is \emph{stable} when going to submodules.  

\medskip 


\underline{Theorem}  

\medskip  

Let     

\begin{equation}   
0\ \longrightarrow\ M_{_1}\ \longrightarrow\ M_{_2}\ \longrightarrow\ M_{_3}\ \longrightarrow\ 0  
\end{equation}  
be an exact sequence. If any two of the $M_{_i}$'s are coherent, then so too is the third. 


\subsection{Coherent sheaves}  

Let $(X,R)$ be a ringed space. An $R$-module, $M$, is said to be \emph{coherent} if: 

\begin{itemize}  

\item For any point $x\in X$ there exists an open neighbourhood, $U$, such that $M(U)$ is finitely generated.  In such instance, $M$ is said to be of \emph{finite type}.    

\item  If for any open set $U\subset X$ and morphism 

\begin{equation}  
R\bigg|_{_U}^{^n}\ \longrightarrow\ M\bigg|_{_U},       
\end{equation}   
with finite-type kernel.

\end{itemize}   

We now turn to some basic examples. Let $X\subset \mathbb{A}_{_k}^{^n}$ be an affine variety with coordinate ring  

\begin{equation}  
R\ =\ {\cal O}(X)\ \simeq\ \mathbb{k}\left[x_{_1},...,x_{_n}\right]\bigg/ I(X).  
\end{equation}  

Given an $R$-module, $M$, let  

\begin{equation}  
\overline{M}(U)\ =\ M\ \otimes_{_R}\ {\cal O}_{_X}(R).  
\end{equation}   

This defines an ${\cal O}_{_X}$-module. We have 

\begin{equation}  
\overline{M}(D(f))\ =\ M\left[1/f\right]. 
\end{equation}    

Since the rings  

\begin{equation}  
R\left[1/f\right]\ =\ {\cal O}(D(f))   
\end{equation}      
are Noetherian, if $M$ is finitely-generated, then $\overline M$ is coherent.  

The operation   

\begin{equation}  
M\ \mapsto\ \overline M  
\end{equation}  
induces an equivalence of all $R$-modules and the category of quasicoherent ${\cal O}_{_X}$-modules.   

The equivalence is exact, namely it takes exact sequences to exact sequences. Let $Y\subset X$ be a subvariety. Then, we have an exact sequence of finitely-generated modules  

\begin{equation}  
0\ \longrightarrow\ I\ \longrightarrow\ {\cal O}(X)\ =\ R\ \longrightarrow\ {\cal O}(Y)\ \longrightarrow\ 0,      
\end{equation}   
where $I$ is the image of $I(Y)$ in $R$.  

Passing to sheaves gives an exact sequence of coherent sheaves,    


\begin{equation}   
0\ \longrightarrow\ {\cal I}_{_Y}\ \longrightarrow\ {\cal O}_{_X}\ \longrightarrow\ {\cal O}_{_Y}\ \longrightarrow\ 0,         
\end{equation}  
with ${\cal I}_{_Y}$ denoting the ideal sheaf of $Y$. ${\cal I}_{_Y}(U)$ are regular functions on $U$ vanishing on $Y\cap U$. The sheaf ${\cal O}_{_Y}$ is the sheaf of regular functions on $Y$ extended to $X$. So, ${\cal O}_{_Y}(U)$ are the ring regular functions on $Y\cap U$.  

\medskip 

\underline{Theorem}  

\medskip 

Let $X$ be a complex manifold, then, the sheaf of holomorphic functions ${\cal O}_{_X}$ is coherent as an ${\cal O}_{_X}$-module. 

For example, if $Y\subset X$ is a complex submanifold, define the ideal sheaf, ${\cal I}_{_Y}$, as above, namely as the collection of holomorphic functions vanishing on $Y$. Since $Y$ is locally defined by finitely-many equations, ${\cal I}_{_Y}$ is of finite type.   

\section*{Locally-free sheaves}  

An $R$-module, $M$, is said to be locally-free (of rank\footnote{If $X$ is disconnected, in principle, the ranks can be variable. } $n$) if there exists an open cover $\{U_{_i}\}$ such that   

\begin{equation}  
M\bigg|_{_{U_{_i}}}\ \simeq\ R\bigg|_{_{U_{_i}}}^{^{n_{_i}}},     
\end{equation}    
with $n\equiv n_{_i}$.    







\subsection*{Complex manifolds}  

A complex manifold is a manifold holomorphically modelled on polydisks $D$ in $\mathbb{C}^{^n}$. It is a smooth manifold locally isomorphic to $D\hookrightarrow\mathbb{C}^{^n}$ whose transition functions are holomorphic functions.

A smooth manifold equipped with an integrable almost complex structure. A smooth complex analytic space. 

For example, a 1-dimensional manifold, is a Riemann surface. In $\mathbb{C}^{^2}$, this is a K3-surface.

\subsection{Skyscraper sheaves}    

A skyscraper sheaf is a sheaf supported at a single point. For $X$ a topological space, $x\in X$ a point in $X$, and a set $S\ \in \ \text{Set}$, the skyscraper sheaf  

\begin{equation}  
\text{skyscr}_{_x}(S)\ \in \text{Sh}(X)  
\end{equation}   
in the category of sheaves, $\text{Sh}(X)$ on the category of open subsets $\text{Op}(X)$ of $X$ supported at $x$ with value $S$ is teh sheaf of sets given by the assignment  

\begin{equation}  
\text{skyscr}_{_x}(S):\ (U\subset x)\ \mapsto\ \begin{cases} & S\ \ \ \ \text{if}\ x\in U\\
&* \ \ \ \ \ \ \ \text{otherwise} . 
\end{cases}  
\end{equation}


\subsection{Ext-groups}  

Consider an abelian category ${\cal A}$ (with enough projections). Let $A\in{\cal A}$ be any object. Consider the contravariant hom function

\begin{equation}   
\text{Hom}_{_{\cal A}}(-,A):\ {\cal A}^{^{op}}\ \rightarrow\ \text{Ab}  
\end{equation}
(notice that this is a left-exact functor). To derive it by resolutions, we need to consider injective resolutions in the opposite category, ${\cal A}^{^{op}}$. 

For any object $X\in{\cal A}$, and projective resolution

\begin{equation}  
((QX)\ \rightarrow\ X)\ \in\ \text{Ch}_{_{\bullet\ge 0}}({\cal A}),  
\end{equation}   
the n$^{^{th}}$ Ext-group of $X$ with coefficients in $A$ is the degree-n cochain cohomology  

\begin{equation}  
\text{Ext}^{^n}(X,A)\ \overset{def.}{=}\ H^{^n}\left(\text{Hom}_{_{\cal A}}((QH)_{_{\bullet}},A)\right)  
\end{equation}
of the cochain complex Hom $((QH)_{_{\bullet}},A)$.

Denoting with 

\begin{equation}  
[-,-]\ :\ \text{Ch}_{_{\bullet}}({\cal A})^{^{op}}\times\text{Ch}_{_{\bullet}}({\cal A})\ \rightarrow\ \text{Ch}_{_{\bullet}}(\text{Ab})  
\end{equation}
the enriched Hom of chain complexes, the $n^{^{th}}$-Ext-group is canonically identified with the 0$^{^{th}}$ homology of $[,]$ as follows:  


\begin{equation}  
\text{Ext}^{^n}(X,A)\ \simeq\ H_{_o}\left[(QX),A[n]\right]  
\end{equation}
from the resolution $QX$ of $X$ to the $n$-fold delooping/suspensions chain complex of $A$  

\begin{equation}  
B^{^n}A\ \overset{def.}{=}\ A[n].
\end{equation}

Ext$^{^n}(X,A)$ is identified with the group of extensions of $X$ by  
\begin{equation} 
B^{^{n-1}}A\ =\ A[n-1]  
\end{equation}

In particular, for $n=1$, and ${\cal A}$ an abstract category, Ext $^{^1}(X,A)$ corresponds to the ordinary group extension of $X$ by $A$.


\section*{Examples of calculations of Ext groups}  

Given two $R$-modules $A$ and $C$, an extension of $C$ by $A$ is a short exact sequence  

\begin{equation}  
0\ \longrightarrow\ A\ \longrightarrow\ B\ \longrightarrow\ C\ \longrightarrow\ 0.  
\end{equation}  

Another extension is  

\begin{equation}  
0\ \longrightarrow\ A\ \longrightarrow\ B^{^{\prime}} 
\ \longrightarrow\ C\ \longrightarrow\ 0.  
\end{equation}  

\underline{Example}   

Let $R\equiv\mathbb{Z}$. Consider the exact sequence  

\begin{equation}  
0\ \longrightarrow\ \mathbb{Z}\ \xrightarrow{n}\ \mathbb{Z}\ \longrightarrow\ \mathbb{Z}/n\mathbb{Z}\ \longrightarrow\ 0.  
\end{equation}   

Then,    

\begin{equation}  
\text{Ext}(\mathbb{Z}/n\mathbb{Z},A)\ \simeq\ A/nA  
\end{equation}  

This calculation can be upgraded to calculate Ext $(B,A)$ for any finitely-generated abelian group, writing  

\begin{equation}  
B\ \equiv\ \bigoplus\ \mathbb{Z}/n\mathbb{Z}\oplus\ \mathbb{Z}^{^N}  
\end{equation}  

\begin{equation}  
\text{Ext}(\mathbb{Z}/n\mathbb{Z},A)\ \simeq\ \bigoplus_{_i}A/n_{_i}A  
\end{equation}










\section{$\mathbb{C}^*$} \label{sec:2}   


\subsection{A-side} 


$X=\mathbb{R}\times S^{^1}\ \simeq\ \mathbb{C}^*$, with symplectic structure, \cite{2},  

\begin{equation}   
\omega\ =\ dr\wedge\ d\theta\ =\ d(rd\theta)  
\end{equation}  

If $\omega=d\alpha$, $\alpha$ a 1-form, then $(X,\omega)$ is exact. If $L\ \subset\ X$ is Lagrangian, $\omega|_{_L}=0$, and dim$L$\ =\ $\frac{1}{2}$\ dim $X$, then 

\begin{equation}  
d\left(\alpha|_{_L}\right)\ =\ 0   
\end{equation}  

If   

\begin{equation}  
\alpha|_{_L}\ =\ dh|_{_L},        
\end{equation}  
then $L$ is said to be exact. For the purpose of this example, the setting is that of exact Lagrangian submanifolds.  

The Fukaya category associated to $(X,\omega)$, Fuk$(X\omega)$, is an $A_{_{\infty}}$-category with objects given by Lagrangian submanifolds $L\subset X$ equipped with an additional brane structure.    

Morphisms are given by   

\begin{equation}  
\text{Hom}(L_{_i},L_{_j}) \ =\ \mathbb{k}<L_{_i}\cap L_{_j}>\ =\ \bigoplus_{_{p\in L_{_i}\cap L_{_j}}}\mathbb{k}\cdot p,   
\end{equation}  
with $\mathbb{k}$ a suitable field.  

In turn, the composition of these morphisms reads as follows  

\begin{equation}  
\mu_{_k}\ :\  \text{Hom}(L_{_o},L_{_1})\ \otimes\ \text{Hom}(L_{_1},L_{_2})\ \otimes\ ...\otimes\ \text{Hom}(L_{_{k-1}},L_{_k})\ \rightarrow\ \text{Hom}(L_{_o},L_{_k})
\end{equation}  

\begin{equation}  
\mu_{_k}(p_{_1},...,p_{_k})\ =\ \sum_{_{p_{_o}, u\in {\cal M}_{_o}(p_{_o},...,p_{_k})}}\  e^{^{-2\pi\omega(u)}}p_{_o},    
\end{equation}  
where ${\cal M}_{_o}$ is the 0-dimensional component of ${\cal M}$

\begin{equation}  
{\cal M}(p_{_o},...,p_{_k})\ \overset{def.}{=}\ \left\{\ \color{white}\bigg]\color{black}u:\Sigma\ \rightarrow\ X\ \text{holom.}\ \right\}\bigg/\sim    
\end{equation}  
and $\Sigma$ the disk with $k+1$ marked boundary points $z_{_i}$, and $u(z_{_i})=p_{_i}, u(z)\in L_{_i}$ for $z\in\partial \Sigma$ between $z_{_i}, z_{_{i+1}}$.     


\begin{figure}[ht!]  
\begin{center}  
\includegraphics[scale=0.67]{holdisk.pdf}   
\caption{\small}  
\label{fig:holddisk}  
\end{center}  
\end{figure}

However, in principle, ${\cal M}_{_o}$ could be infinite. To avoid divergence issues, we need to use Gromov's compactness theorem, and introduce the Novikov field   

\begin{equation}  
\Lambda\ \overset{def.}{=}\ \left\{\sum_{_i=0}^{^{\infty}} a_{_i}T^{^i}\ |\ a_{_i}\in\mathbb{C}, \lambda_{-i}\in\mathbb{R}, \underset{i\rightarrow\infty}{\lim}\ \lambda_{_i}=+\infty\ \right\}   
\end{equation}    
to serve as the coefficient field of Fuk$(X,\omega)$ instead of $\mathbb{C}$, and set   

\begin{equation}  
\text{Hom}(L_{_i},L_{_j}) \ =\ \Lambda<L_{_i}\cap L_{_j}>,   
\end{equation}  
with   

\begin{equation}  
\mu_{_k}(p_{_1},...,p_{_k})\ =\ \sum_{_{p_{_o}, u\in {\cal M}_{_o}(p_{_o},...,p_{_k})}}\  T^{^{\omega(u)}}p_{_o}.     
\label{eq:product}   
\end{equation} 


\subsection{The exact Fukaya category}  

The same as the definition provided above, but with the following additional requirements:   

\begin{enumerate}  
\item Objects are exact Lagrangians.  

\item \begin{equation}  
\text{Hom}(L_{_i},L_{_j}) \ =\ \mathbb{C} <L_{_i}\cap L_{_j}>. 
\end{equation}     

\item  The composition of morphisms are as before, \eqref{eq:product}, except that now $T=1$.  

\end{enumerate}     

The reason why we can replace $\Lambda\mapsto\mathbb{C}$ and $T\mapsto 1$ is that the Lagrangian submanifolds are exact.    

Given that $p\in L_{_o}\cap L_{_1}$ and $h_{_{L_{_i}}}\in C^{^{\infty}}(L_{_i},\mathbb{R})$, let us define 


   \begin{equation}  
   A(p)\ \overset{def.}{=}\ h_{_{L_{_o}}}-h_{_{L_{_1}}}.     
   \end{equation}



\underline{Lemma}   
If $u\in{\cal M}(p_{_o},...,p_{_k})$, then 

\begin{equation}  
\omega(u)\ =\ A(p_{_o})-\sum_{_i=1}^{k}A(p_{_i})  
\end{equation}  

\underline{Proof}  

Recall that $u:\Sigma\rightarrow X$, so the pullback $u^*$ brings $\omega$ to the setting of the marked disk. Using Stokes's Theorem  

\begin{equation}  
\int_{_{\partial X}}\omega=\int_{_X}d\omega  
\end{equation}   


\begin{equation}  
\begin{aligned}
\omega(u)\ &\equiv\ \int_{_{\Sigma}}u^*\omega\\
&=\int_{_{\Sigma}}u^*(d\alpha)\\
&=\int_{_{\Sigma}}d(u^*\alpha)\\
&=\int_{_{\partial\Sigma}}u^*\alpha\\
&=\int_{_{L_o}}u^*\alpha\bigg|_{_{L_o}}+...+\int_{_{L_k}}u^*\alpha\bigg|_{_{L_k}}\\
&=\int_{_{L_o}}u^*dh_{_{L_o}}+...+\int_{_{L_k}}u^*dh_{_{L_k}}\\
&=\int_{_{\partial L_o}}u^*h_{_{L_o}}+...+\int_{_{\partial L_k}}u^*h_{_{L_k}}\\  
&=h_{_{L_o}}(p_{_1})-h_{_{L_o}}(p_{_o})+h_{_{L_1}}(p_{_2})-h_{_{L_1}}(p_{_1})+...+h_{_{L_k}}(p_{_o})-h_{_{L_k}}(p_{_k})\\
&=A(p_{_o})-\sum_{_{i=1}}^{^k}A(p_{_i}).
\end{aligned}
\end{equation}  

Upshot: in the exact case, $\omega(u)$ is independent w.r.t. $u$, hence, only one power of $T$ appears in the definition of $\mu_{_k}$, and we can set $T=1$.  

Given that we know the exact Fukaya category to be $\mathbb{C}$-linear, this means we can compare it with 

\begin{equation}  
D^{^b}(Y)\ =\ D^{^b}(\mathbb{C}^{^*}),     
\end{equation}    
since $D^{^b}(Y)$ is in turn a $\mathbb{C}$-linear category.  

\subsection{Compact Lagrangian case}  

The only compact exact Lagrangian in $X$ up to Hamiltonian isotopy is the circle $S^{^1}$ (which we write as the set $\{r=0\}$ on the cylinder). It is important to note that we must consider $S^{^1}$ at 0 on the cylinder, otherwise, it will not be exact.   

\subsubsection{Local systems}   

Objects in a compact Fukaya category consist of pairs 

\begin{equation}  
(L,\xi)\ \in\ \text{Obj}(\text{Fuk}(X)),  
\end{equation}
where $\xi$ is a $\mathbb{C}$-local system, specifically, flat vector bundles $\xi\rightarrow L$ with unitary holonomy over $\mathbb{C}$. $\xi$ is also referred to as the \emph{brane structure} of the Lagrangian in question.  Adding it to the objects of Fuk$(X)$ in turn, leads to a modification of the product formula, \eqref{eq:product}, which we are about to describe.   


Consider the following isomorphisms  

\begin{equation}  
\gamma_{_i}:\ \xi_{_i}\bigg|_{_{p_{_i}}}\ \rightarrow\ \xi_{_i}\bigg|_{_{p_{_{i+1}}}}   
\end{equation}  

\begin{equation}  
\rho_{_i}:\ \xi_{_{i-1}}\bigg|_{_{p_{_i}}}\ \rightarrow\ \xi_{_i}\bigg|_{_{p_{_{i}}}}.    
\end{equation}  

Then, defining the composition  

\begin{equation}  
\eta_{_{u,\rho_{_1},...,\rho_{_k}}}\ \overset{def.}{=}\ \gamma_{_k}\circ\rho_{_k}\circ...\circ\gamma_{_1}\circ\rho_{_1}\circ\gamma_{_o}  
\end{equation}
\eqref{eq:product} now becomes   

\begin{equation}  
\mu_{_k}(p_{_1},...,p_{_k})\ =\ \sum_{_{p_{_o}, u\in {\cal M}_{_o}(p_{_o},...,p_{_k})}}\  T^{^{\omega(u)}}p_{_o}\eta_{_{u,\rho_{_1},...,\rho_{_k}}}        
\label{eq:newproduct}   
\end{equation}   
with $\eta$ adding a monodromy contribution while moving on the boundary of a holomorphic disk.  



