By taking the universal cover of $X$< in this case $\mathbb{R}^{^2}$, we see that 

\begin{equation}  
x_{_i}\ \cdot\ x_{_j}\ =\ x_{_{i+j}}  
\end{equation}   
thereby signalling that the structure of Hom${^{\bullet}}(L,L)$ is the same as that of $\mathbb{C}\left[z^{^{\pm 1}}\right]$, where 

\begin{equation}  
z^{^i}\cdot\ z^{^j}\ =\ z^{^{i+j}} \ \ \ \ \ \ , \ \ \ \ \ \ \ \ \ x_{_i}\ \mapsto\ z^{^i}.   
\end{equation}  

Hence, 


\begin{equation}  
\text{Hom}^{^{\bullet}}(L,L)\ \simeq\ \mathbb{C}\left[z^{^{\pm 1}}\right]  
\end{equation}  
thereby implying $L=\mathbb{R}$ is mirror to ${\cal O}$.


A further relation to consider in the HMS construction is the following  


\begin{equation}  
\text{Hom}^{^{\bullet}}(\mathbb{R},\mathbb{R})\ \otimes\ \text{Hom}^{^{\bullet}}\left(\mathbb{R},S_{_a}^{^1}\right)\ \simeq\ \text{Hom}^{^{\bullet}}\left(\mathbb{R},S_{_a}^{^1}\right). 
\label{eq:lastcomp}    
\end{equation}  

Once more, working on the universal cover of $X$, \eqref{eq:lastcomp} reduces to the following map  


\begin{equation}  
x_{_i}\ \cdot\ a\ =\ a.      
\end{equation}

This argument extends straightforwardly to the case in which   

\begin{equation}    
X\ = \ \left(\mathbb{C}^{^*}\right)^{^n}\ \simeq\ T^{^*}T^{^n}
\end{equation}  
whose wrapped Fukaya category is generated by   

\begin{equation}  
L_{_0}\ = \ \left(\mathbb{R}_{_+}\right)^{^n}.  
\end{equation} 

Upon introducing a Hamiltonian perturbation of the kind  

\begin{equation}  
H\ = \ \frac{1}{2}\ \sum_{_i}r _{_i}^{^2}  \ \ \ \ , \ \ \ \ r_{_i}\ =\ \log |z_{_i}|  
\end{equation}    
the resulting wrapped cohomology reads as follows  

\begin{equation}  
HW^{^{\bullet}}\left(L_{_0}, L_{_0}\right) \ =\ CW^{^{\bullet}}\left(L_{_0},L_{_0}\right)\ \simeq\ \mathbb{C}\left[x_{_1}^{^{\pm}},...,x_{_n}^{^{\pm}}\right]  
\end{equation}
which agrees with the ring of functions of the mirror  $X^{^{\text{V}}}=\left(\mathbb{C}^{^*}\right)^{^n}$. 



\subsection{B-side}

\underline{Notation:}  
\begin{equation}
    Y\ \equiv\ \text{Spec}\left[z^{^{\pm 1}}\right]\ =\ \mathbb{C}^{^*},
\end{equation}
with structure sheaf ${\cal O}_{_Y}$ and skyscraper sheaves ${\cal O}_{_a}$.

On the B-side, objects are skyscraper sheaves, ${\cal O}_{_a}$, corresponding to Lagrangian submanifolds equipped with local brane structure. Homoeomorphisms are 

\begin{equation}  
\text{Hom}^{^{\bullet}}_{_{D(R)}}\left({\cal O}_{_a},{\cal O}_{_b}\right)\ \simeq\ \text{Ext}^{^{\bullet}}_{_R}\left({\cal O}_{_a},{\cal O}_{_b}\right)\ \simeq\ \begin{cases}&0\ \ \ , \ \ \text{if}\ \ a\neq b\\
&\mathbb{C}[\theta]/\theta^{^2}\ \ , \ \ \text{if}\ \ a=b
\end{cases}
\end{equation}

\underline{Proposition}  
For ${\cal F}$ a coherent sheaf on a variety, $X$, we have 

\begin{equation} 
\text{Ext}^{^i}\left({\cal O}_{_X},{\cal F}\right)\ \simeq\ H^{^i}(X,{\cal F})\ \ \ \ \ \forall i\ge 0.  
\end{equation}  

\underline{Theorem [Serre]}  (Part of a cohomology-vanishing theorem)  

\begin{equation}  
\text{Hom}^{^{\bullet}}({\cal O},{\cal O})\ \simeq\ \text{Ext}^{^{\bullet}}({\cal O},{\cal O})\ \simeq\ H^{^{\bullet}}(Y,{\cal O})\ =\ \mathbb{C}\left[z^{^{\pm1}}\right]
\label{eq:firstline}
\end{equation}

\begin{equation}  
\text{Hom}^{^{\bullet}}({\cal O},{\cal O}_{_a})\ \simeq\ \text{Ext}^{^{\bullet}}({\cal O},{\cal O}_{_a})\ \simeq\ H^{^{\bullet}}(Y,{\cal O}_{_a})\ =\ \mathbb{C}\left[0\right]
\label{eq:secondline}
\end{equation}

\begin{equation}  
\text{Hom}^{^{\bullet}}({\cal O}_{_a},{\cal O})\ \simeq\ \text{Ext}^{^{\bullet}}({\cal O}_{_a},{\cal O})\ =\ \mathbb{C}\left[1\right]
\label{eq:thirdline}
\end{equation}
where [0], [1] denote the degree that $\mathbb{C}$ is in. \eqref{eq:firstline} follows from the general fact that 

\begin{equation}  
{\cal O}_{_{\text{Spec} R}}(\text{Spec} R)\ \simeq\ R  
\end{equation}
and cohomology vanishes for $\bullet>0$.

\eqref{eq:secondline} follows from skyscraper sheaves are flasque, namely have vanishing cohomology for $\bullet>1$. In such case, $\mathbb{C}$ is degree-0 since ${\cal O}$ has a stalk only at $a$. 

For \eqref{eq:thirdline}, let's calculate the Ext group by taking a resolution. First note that, under the equivalence of categories, we have  


\begin{equation}   
\text{Ext}^{^{\bullet}}_{_{\mathbb{C}^{^{*}}}}\left({\cal O}_{_a},{\cal O}\right)\ \simeq\ \text{Ext}^{^{\bullet}}_{_R}\left(\frac{R}{z-a},R\right)
\end{equation}  
where $R=\mathbb{C}\left[z^{^{\pm1}}\right]$. Computing a projective resolution of $\frac{R}{z-a}$, we have  

\begin{equation}  
0\ \longrightarrow\ R\ \xrightarrow{\cdot(z-a)}\ R\ \longrightarrow\ R/(z-a)\ \longrightarrow\ 0.  
\end{equation}

Taking Hom$_{_R}(-,R)$, we get   

