\section{Orientation of moduli space}  

Let $(\tilde L_{_o},\tilde L_{_1})$ such that $L_{_o}, L_{_1}$ intersect transversally. In the tangent space to $(M,\phi_{_M},\theta_{_M},I_{_M})$, namely  

\begin{equation}   
\left(TM_{_y},\phi_{_{M,y}}, I_{_{M,y}}, \eta^{^2}_{_{M,y}}\right)  
\end{equation}
at every internal point $y\in L_{_o}\cap L_{_1}$, there is an obvious pair of linear Lagrangian branes  

\begin{equation}  
\tilde\Lambda_{_{K,y}}\ =\ \left(\Lambda, \tilde \alpha, \tilde P_{_{K,y}}\right)  
\end{equation}   
with index and orientation spaces  

\begin{equation}  
i(y)\ \overset{def.}{=}\ i\left(\tilde\Lambda_{_{K,y}},\tilde\Lambda_{_{K,y}}\right)  
\ \ \ \ , \ \ \ \ o(y)\ \overset{def.}{=}\ o\left(\tilde\Lambda_{_{K,y}},\tilde\Lambda_{_{K,y}}\right).    
\label{eq:io}   
\end{equation}   

\eqref{eq:io} are defined as follows: choose a path $\tilde\lambda$ in $\tilde{\text{Gr}}(V)$ connecting the two points, whose projection $\lambda$ lies in ${\cal P}^{^-}\text{Gr}(V)$, and set 

\begin{equation}  
i\left(\tilde\Lambda_{_{K,y}},\tilde\Lambda_{_{K,y}}\right)\ =\ I_{_H}(\lambda)\ \ \ \ \ \ \ , \ \ \ \ \ \ o\left(\tilde\Lambda_{_{K,y}},\tilde\Lambda_{_{K,y}}\right)\ =\ \left(\delta_{_H}\right)_{_{\lambda}}. 
\end{equation}

In principle, one should prove that these are independent of the choice of $\tilde\lambda$ (up to canonical isomorphism). Denoting by    


\begin{equation}  
\Omega^{^-}\left(\text{Gr}(V), \Lambda_{_o},\Lambda_{1}\right)  
\end{equation}  
the subspace of ${\cal P}^{^-}\text{Gr}(V)$ consisting of all paths from $\Lambda_{_o}$ to $\Lambda_{_1}$, and by 

\begin{equation}  
\Omega^{^-}\left(\tilde{\text{Gr}}(V), \tilde\Lambda_{_o},\tilde\Lambda_{1}\right)  
\end{equation}    
the corresponding space of paths $\tilde\lambda$ in $\tilde{\text{Gr}}(V)$, these spaces are homotopy equivalent to the ordinary loop spaces $\Omega\text{Gr}(V)$ and $\tilde{\Omega\text{Gr}}(V)$, respectively.  

For $n\ge 2$, $\tilde{\Omega\text{Gr}}(V)$ is simply-connected, thereby implying uniqueness. However, for $n=1$, there are two distinct homotopy classes, both of which lead to the same $i$, but, for the orientation space, there are two different possibilities, corresponding to the automorphism responsible for change of orientation.  

We declare that there is a change in homotopy class of $\tilde\lambda$ giving rise to an orientation-reversing automorphism of $\left(\delta_{_H}\right)_{_{\lambda}}$.


Suppose $S$ is a $(d+1)$-dimensional disk equipped with strip-like ends and brane labels $\tilde L_{_0},...,\tilde L_{_d}$. Choose Floer data for the pairs $\left(L_{_o},L_{_d}\right)$, and $\left(L_{_{k-1}},L_{_k}\right)$, $k=1,...,d$, and a compatible perturbation datum on $S$. At a regular point $u\in{\cal M}_{_S}\left(y_{_o},...,y_{_d}\right)$ one has  

\begin{equation}  
\text{dim}_{_{\cal U}}\left({\cal M}_{_s}\left(y_{_o},...,y_{_d}\right)\right)\ =\ i\left(y_{_o}\right)-i\left(y_{_1}\right)-...-i\left(y_{_d}\right)  
\end{equation}  

\begin{equation}  
\begin{aligned}
\left(\lambda^{^{top}}T{\cal M}_{_S}\left(y_{_o},...,y_{_d}\right)\right)_{_n}\ &\simeq\ \lambda^{^{top}}\text{Ker}\left(D_{_{S,u}}\right)\\
&\simeq\ o\left(y_{_o}\right)\ \otimes\ o\left(y_{_1}\right)^{^{\text{V}}}\ \otimes\ ...\ \otimes\ o\left(y_{_d}\right)^{^{\text{V}}},      
\end{aligned}  
\end{equation}
with ${\cal M}_{_S}$ canonically oriented relative to the orientation space at the ends.  


\subsection{More general Riemann surfaces}   

Enlarging the class of Riemann surfaces $S$. Assuming the compactification $\hat S$ has the property that each boundary circle contains exactly one incoming point at infinity. Then, for $u$ a regular point of a suitable moduli space ${\cal M}_{_S}\left(\{y_{_{\xi}}\}\right)$, 


\begin{equation}  
\text{dim}_{_u}\left({\cal M}_{_S}\left(\{y_{_{\xi}}\}\right)\right)\ =\ u\left(\chi(S)-|\Sigma^{^-}|\right)+\sum_{_{\xi\in\Sigma^{^{\pm}}}}\mp i\left(y_{_{\xi}}\right)  
\end{equation}   

\begin{equation}  
\left(\lambda^{^{top}}T{\cal M}_{_S}\left(y_{_o},...,y_{_d}\right)\right)_{_n}\ \simeq\ \bigoplus_{_{\xi\in\Sigma^{^{\pm}}}} o\left(y_{_{\xi}}\right)^{^{\mp 1}}. 
\end{equation}  




\subsection{Floer cohomology of branes}   

Fix a coefficient field, $\mathbb{k}$. If $\delta$ is any 1D real vector space, $|\delta|_{_{\mathbb{k}}}$ is the 1D $\mathbb{k}$-vector space generated by the two orientations of $\delta$, such that their sum is 0.   

The upgraded version of Floer cohomology associated to any pair $\left(\tilde L_{_o}, \tilde L_{_1}\right)$ of exact Lagrangian branes in $M$, $HF^{^{\bullet}}\left(\tilde L_{_o}, \tilde L_{_1}\right)$ with the following properties:  

\begin{enumerate}  

\item Triangle product   

\begin{equation}  
HF^{^{\bullet}}\left(\tilde L_{_1}\tilde L_{_2}\right)\ \otimes\ HF^{^{\bullet}}\left(\tilde L_{_o},\tilde L_{_1}\right)\ \longrightarrow\ HF^{^{\bullet}}\left(\tilde L_{_o}\tilde L_{_2}\right).  
\end{equation}

\item  Change of brane structure. Applying the same operation to all the branes involved, the Floer cohomology group remains unchanged. Operations could be, either, a change of grading by a constant in $\mathbb{Z}$, or to tensor the Pin structures by the restriction of a common line bundle $\beta\rightarrow M$.



\item Duality. $\forall \tilde L$, Poincare' duality and the PSS isomorphism give rise to a map  

\begin{equation}    
\int_{_{\tilde L}}:\ HF^{^n}\left(\tilde L, \tilde\otimes \lambda^{^{top}}(TL)\ \simeq\ H^{^n}\left(L;|\lambda^{^{top}}TL|_{_{\mathbb{k}}}\right)\ \simeq\ H_{_{_o}}(L;\mathbb{k}\right)\ \longrightarrow\ \mathbb{k}.
\end{equation}

\end{enumerate}

\subsection{Determining the grading and signs} 

Choose a regular Floer datum and define the graded Floer cochain group by setting, $\forall k\in\mathbb{Z}$, 

\begin{equation}  
CF^{^k}\left(\tilde L_{_o}, \tilde L_{_1}\right)\ \overset{def.}{=}\ \bigoplus_{_{i(y)=k}}\left|o(y)\right|_{_{\mathbb{k}}} 
\end{equation}      

Let $u\in{\cal M}_{_z}\left(y_{_o},y_{_1}\right)$ be a non-stationary solution of Floer's equation. Then, there is a short-exact sequence 

\begin{equation}    
\mathbb{R}\ \rightarrow\ T{\cal M}_{_z}\left(y_{_o},y_{_1}\right)_{_u}\ \rightarrow\ T{\cal M}_{_z}^{^{\bullet}}\left(y_{_o},y_{_1}\right)_{_u}  
\end{equation}
where $\mathbb{R}$ corresponds to the translation direction. This allows one to identify the top exterior powers of $T_{_u}{\cal M}_{_z}\left(y_{_o},y_{_1}\right)_{_u}$ and $T_{_u}{\cal M}_{_z}^{^{\bullet}}\left(y_{_o},y_{_1}\right)_{_u}$, hence, by  

\begin{equation}  
\left(\lambda^{^{top}}T{\cal M}_{_S}\left(y_{_o},...,y_{_d}\right)\right)_{_u}\ \simeq\ \lambda^{^{top}}\text{Ker}\left(D_{_{S,u}}\right)\ \simeq\ o\left(y_{_o}\right)\otimes o\left(y_{_1}\right)^{^{\text{V}}}\otimes...\otimes o\left(y_{_d}\right)^{^{\text{V}}}  
\label{eq:relor}   
\end{equation}
yields a preferred orientation of ${\cal M}_{_z}\left(y_{_o},y_{_1}\right)$ relative to $o\left(y_{_o}\right)\otimes o\left(y_{_1}\right)^{^{\text{V}}}$. In particular, if $u$ is an isolated point of ${\cal M}_{_z}^{^{\bullet}}\left(y_{_o},y_{_1}\right)$, we get an isomorphism  

\begin{equation}  
c_{_u}:\ o\left(y_{_1}\right)\ \longrightarrow\ o\left(y_{_o}\right).  
\end{equation}   

The $\left(y_{_o},y_{_1}\right)$-coefficient of the boundary operator $\partial$ is defined as the sum over $\mathbb{k}$-normalisations of all such $c_{_u}$,  

\begin{equation}  
\partial^{^{y_{_o},y_{_1}}}\ =\ \sum_{_u}|c_{_n}|_{_{\mathbb{k}}}:\left|o\left(y_{_1}\right)\right|_{_{\mathbb{k}}}\ \rightarrow\ \left|o\left(y_{_o}\right)\right|_{_{\mathbb{k}}}.  
\label{eq:newpartial}
\end{equation} 

\eqref{eq:newpartial} corresponds to saying that each $u$ contributes with $\pm 1$. The Floer cohomology is therefore redefined as follows  

\begin{equation}  
HF^{^{\bullet}}\left(\tilde L_{_o}, \tilde L_{_1}\right)\ \overset{def.}{=}\ H^{^{\bullet}}\left(CF^{^{\bullet}}\left(\tilde L_{_o}, \tilde L_{_1}\right),\partial\right).    
\end{equation}  

Then, take a $(d+1)$-pointed disk $S$, with brane labels $\left(\tilde L_{_o},...,\tilde L_{-d}\right)$; choose regular Floer data and perturbation data. At every isolated point $u\in{\cal M}_{_S}\left(y_{_o},...,y_{_d}\right)$, the relative orientation \eqref{eq:relor} gives rise to an isomorphism  

\begin{equation}  
c_{_n}:\ o\left(y_{_d}\right)\ \otimes ... \otimes\ o\left(y_{_1}\right)\ \longrightarrow\ o\left(y_{_o}\right).  
\end{equation}  

We use these to define a chain map  

\begin{equation}  
C\Phi_{_S}:\ CF^{^{\bullet}}\left(\tilde L_{_{d-1}},\tilde L_{_d}\right)\ \otimes\ ...\ \otimes\ CF^{^{\bullet}}\left(\tilde L_{_0},\tilde L_{_1}\right)\ \longrightarrow\ CF^{^{\bullet}}\left(\tilde L_{_0},\tilde L_{_d}\right).    
\end{equation}   

\subsection*{Some generalities}  

Given an arbitrary symplectic manifold $(M,\phi)$ with an almost complex structure $I_{_M}$ and quadratic complex volume form $\eta_{_M}^{^2}$, a graded automorphism of $M$ is a pair $(\phi,\tilde\gamma)$ consisting of a symplectic automorphism $\phi$ and a map $\tilde\gamma:\text{Gr}(TM)\rightarrow\mathbb{R}$ satisfying 

\begin{equation}  
\text{exp}\left(2\pi i \tilde\gamma(\Lambda)\right)\ =\ \frac{\alpha_{_M}\left(D\phi(\Lambda)\right)}{\alpha_{_M}(\Lambda)}  \ \ \ \ \ \ \ \ \ \ \ \ \ \Lambda\in\text{Gr}(TM).
\end{equation}  

Composition of such automorphisms is defined by 

\begin{equation}  
\tilde\phi_{_2}\circ\tilde\phi_{_1}\ =\ \left(\phi_{_2}\circ\phi_{_1},\tilde\gamma_{_2}\circ D\phi_{_1}+\tilde\gamma_{_1}\right).  
\end{equation}   

Graded automorphisms act naturally on the set of Lagrangian branes: if $\left(L, \tilde\alpha,\tilde P\right)$ is a brane, the image $\phi(L)$ inherits the grading  

\begin{equation}  
x\ \mapsto\ \tilde\gamma\left(TL_{_{\phi^{^{-1}}(x)}}\right)+\tilde\alpha\left(\phi^{^{-1}}(x)\right)  
\end{equation}
as well as the pushforward Pin structure  $\left(\phi^{^{-1}}\right)^{^*}\tilde P$. This can be further generalised as follows:  define a brane automorphism to be a triple $\phi=(\phi,\tilde\gamma,\beta)$, where $(\phi,\tilde\gamma)$ is as before, and $\beta\rightarrow M$ is a real line bundle. The action of such automorphisms on branes includes a twist of the Pin-structure, 

\begin{equation}  
\tilde P\ \mapsto\ \left(\phi^{^{-1}}\right)^{^{\bullet}}\left(\tilde P\otimes\beta|_{_L}\right).  
\end{equation}


\section{HMS for Fano varieties}   


\subsection{LG model}   

LG model are used as models for 2D QFT in String Theory. They are defined from the action    

\begin{equation}  
S_{_{LG}}\ :\ \left(\phi:\ \Sigma\rightarrow\ X\right)\ \mapsto\int_{_{\Sigma}}\left(\left|\nabla\phi\right|^{^2}+\left|g_{_{ij}}\frac{\partial{\cal W}(\phi)}{\partial \phi_{_i}}\frac{\partial{\cal W}(\phi)}{\partial \phi_{_j}}\right|^{^2}+\text{ferm. d.o.f.}\right)\ d\mu  
\end{equation}   
where $\Sigma$ is the 2D worldsheet, and a holomorphic function

\begin{equation}  
{\cal W}:\ X\ \longrightarrow\ \mathbb{C}  
\end{equation}
referred to as the \emph{superpotential}. Kontsevich understood that such a theory provides a type of QFTs that can be used on one side of the HMS correspondence.  Specifically, if $X$ is a Fano variety, the usual B-model does not exist, since the corresponding SUSY sigma model is not conformally-invariant. The LG B-branes are the HMS duals to the A-model on a Fano variety. Kontsevich provided the mathematical formulation of this by noticing that, the B-branes are not given by chain complexes of coherent sheaves as in the usual B-model encounered in the first instances of the HMS correspondence. But, rather, by \emph{twisted complexes}. The latter essentially means that the differential is nonvanishing 

\begin{equation}  
\text{d}^{^2}\ =\ a{\cal W},  
\label{eq:nonvan}   
\end{equation}  
with $a$ a constant. \eqref{eq:nonvan} being nonvanishing supplies a way of twisting $D^{^b}$Coh$(X)$.




\subsection{The case of Fano varieties}

Given an algebraic hypersurface,    

\begin{equation}  
H\ =\ {\cal W}^{^{-1}} (0)  \ \ \ \ \subset\ \ \ \ \left(\mathbb{C}^{^*}\right)^{^n},
\end{equation}  
HMS relates the wrapped Fukaya category of $H$ to the derived category of singularities of the mirror Landau-Ginzburg (LG) model. 

Furthermore, one can enrich this by using wrapped Fukaya categories of the complement 

\begin{equation}  
\left(\mathbb{C}^{^*}\right)^{^n}\ \backslash\ H  
\end{equation}  
and the Fukaya-Seidel category of the LG model 

\begin{equation}  
\left(\left(\mathbb{C}^{^*}\right)^{^n},{\cal W}\right). 
\end{equation}  

Let $H$ be a smooth algebraic hypersurface, whose defining equation is a Laurent polynomial  

\begin{equation}  
f\left(x_{_1},...,x_{_n}\right)\ =\ \sum_{_{\alpha\in A}}c_{_{\alpha}}\tau^{^{\rho(\alpha)}}x_{_1}^{^{\alpha_{_1}}}...x_{_n}^{^{\alpha_{_n}}}.
\end{equation}   

Take $A$ to be a finite subset of $\mathbb{Z}^{^n}, c_{_{\alpha}}\in\mathbb{C}^{^*}, \tau\in\mathbb{R}_{_+}$ sufficiently small, then 

\begin{equation}  
\rho:\ A\ \rightarrow\ \mathbb{R} 
\end{equation}
is a convex function.   
Requiring $\rho$ to be the restriction to $A$ of a convex piecewise linear function $\hat\rho$, define the convex hull to be  
\begin{equation}  
\text{Conv}(\Lambda)\ \subset\ \mathbb{R}^{^n}.  
\end{equation}
The maximal domains of linearity of $\hat \rho$ define a polyhedral decomposition ${\cal P}$ of $\text{Conv}(A)$ whose set of vertices is required to be exactly $A$. Hori and Vafa conjectured that $H$ should arise as a mirror to a toric CY manifold, $Y$, specifically, a toric LG model $(Y,{\cal W})$. The outcome of this is as follows:  
consider the piecewise linear function  

\begin{equation}  
\varphi:\ \mathbb{R}^{^n}\ \rightarrow\ \mathbb{R}  
\end{equation}   
obtained by tropicalising ${\cal W}$, and the noncompact polytope  

\begin{equation}  
\Delta_{_Y}\ \overset{def.}{=}\ \left\{\left(\xi,\eta\right)\ \in\ \mathbb{R}^{^n}\oplus\ \mathbb{R}\ \bigg|\  \eta\ge\varphi(\xi)\right\}  \ \ \ \subseteq\ \ \ \mathbb{R}^{^{n+1}}.
\end{equation}   

Let $Y$ be the noncompact $(n+1)$-dimensional toric variety defined by the moment polytope $\Delta_{_Y}$. $Y$ is also described by the vectors 

\begin{equation}  
(-\alpha,1)\ ,\ \alpha\in A
\end{equation} 
and in which the vectors  

\begin{equation}  
(-\alpha_{_1},1), ..., (-\alpha_{_k},1)  
\end{equation}   
span a cone iff  $\alpha_{_1}, ..., \alpha_{_k}$ span a cell of ${\cal P}$.  

Also, defining 

\begin{equation}  
{\cal W}\ =\ -z^{^{(0,...,0,1)}}\ \in\ {\cal O}(Y). 
\end{equation}

The irreducible toric divisors of $Y$ are indexed by the elements of $A$; denoting by $Z_{_{\alpha}}$ the divisor corresponding to the ray $(\alpha,1)$ of $\Sigma_{_Y}$, i.e. the facet of $\Delta_{_Y}$ given by the graph of $\varphi$ over the region where the maximum in $\varphi(\xi)$ is achieved by $\alpha$. The superpotential, ${\cal W}$, is then the toric monomial that vanishes to order 1 on each toric divisor $Z_{_{\alpha}}$, namely  

\begin{equation}  
{\cal W}^{^{-1}}(0)\ =\ \bigcup_{_{\alpha\in A}}Z_{_{\alpha}}  
\end{equation}  
as the union of all toric strata. 

The HMS direction being used here predicts an equivalence between the derived wrapped Fukaya category of $H$ and the derived category of singularities of the LG model $(Y,{\cal W})$, 


\begin{equation}  
WFuk(H)\ \simeq\ D_{_{sg}}^{^b}(Z),   
\end{equation}  
where 

\begin{equation}  
D_{_{sg}}^{^b}(Z)\ \equiv\ D^{^b}\text{Coh}(Z)/\text{Perf}(Z)  
\end{equation}    
on the regular fiber  

\begin{equation}  
Z\ \equiv\ {\cal W}^{^{-1}}(0)\ =\ \bigcup_{_{\alpha\in A}} Z_{_A}.    
\end{equation}    

$WFuk(H)$ only depends of the set $A\subset\mathbb{Z}^{^n}$, not on the coefficients $c_{_{\alpha}}$, nor on $\rho$, since hypersurfaces corresponding to different choices are deformation equivalent Liouville (or Stein) submanifolds of $\left(\mathbb{C}^{^*}\right)^{^n}$. On the other hand, $Y$ depends on the polyhedral decomposition ${\cal P}$ of Conv$(A)$, hence, different choices of $\rho$ can yield different mirrors. However, these mirrors are birational to each other (related by flops), and therefore, the resulting derived categories of singularities are expected to be equivalent. 

\medskip  

\underline{Conjecture}  

\medskip  


\begin{equation}  
Z\ =\ \bigcup_{_{\alpha}}Z_{_{\alpha}}\ \subset\ Y  
\end{equation}   
is mirror to the complement  

\begin{equation}  
\left(\mathbb{C}^{^*}\right)^{^n}\ \backslash\ H,    
\end{equation}   
and there is a commutative diagram  

