\begin{equation}  
<e^{^1},\partial\beta_{_1}>\ =\ 1\ \ \ ,\ \ \ \ \omega(\beta_{_2})\ =\ 2\pi\ (1-u)\ \ \ ,\ \ \ \partial\beta_{_2}\ =\ -\partial\beta_{_1}.  
