and define  

\begin{equation}  
c_{_o}\ \overset{def.}{=}\ e^{^<\mathfrak{b}_{_o},\partial\beta_{_1}>}\ \in\ \mathbb{C}\ \ \ \ \ \ ,\ \ \ \ \ \ 1+c_{_+}\ \overset{def.}{=}\ e^{^<\mathfrak{b}_{_+},\partial\beta_{_1}>}\ \in\ \Lambda_{_+}.  
\label{eq:redef}   
\end{equation}  

Upon calculating the index in terms of the equivariant Floer $A_{_{\infty}}$-algebra, we get 

\begin{equation}  
\mu_{_o}^{^{\mathfrak{b}}}(1)\ =\ T^{^{\omega(\beta_{_1})/2\pi}} e^{^{<\mathfrak{b},\partial\beta_{_1}>}}+ T^{^{\omega(\beta_{_2})/2\pi}} e^{^{<\mathfrak{b},\partial\beta_{_2}>}}.  
\label{eq:index}   
\end{equation}   

Making use of \eqref{eq:redef}, \eqref{eq:index} becomes  


\begin{equation}  
\mu_{_o}^{^{\mathfrak{b}}}(1)\ =\ T^{^u} c_{_o}(1+c_{_+})\ +\ T^{^{1-u}} c_{_o}^{^{-1}}(1+c_{_+})^{^{-1}}. 
\end{equation}   

Next, the differential is calculated as   

\begin{equation}  
\begin{aligned}   
\mu_{_1}^{^{\mathfrak{b}}}(e^{^1})\ &=\ \sum_{_{\beta}}T^{^{\omega(\beta)/2\pi}} e^{^{<\mathfrak{b}_{_o},\partial\beta>}}\sum_{_{l_{_o}+l_{_1}=l}} \mu_{_{l+1,\beta}}\left(\mathfrak{b}_{_+},...,\mathfrak{b}_{_+},e^{^1},\mathfrak{b}_{_+},...,\mathfrak{b}_{_+}\right) \ +\ < \lambda, e^{^1}>\\
&=\ T^{^u} c_{_o}(1+c_{_+})\ -\ T^{^{1-u}} c_{_o}^{^{-1}}(1+c_{_+})^{^{-1}}\ +\ < \lambda, e^{^1}>.
\label{eq:differential}   
\end{aligned}
\end{equation}   

Givental's potential function for $\mathbb{CP}^{^1}$  


\begin{equation}  
{\cal F}\ =\ X+\frac{T}{X}\ +\ \lambda\log{X}  
\label{eq:potential}   
\end{equation}     
is recovered from \eqref{eq:index} by introducing the variable  

\begin{equation}  
X\ \overset{def.}{=}\ T^{^u} c_{_o}(1+c_{_+}).  
\label{eq:rel}
\end{equation}   

In this reformulation, \eqref{eq:differential} can thus be redefined in the following way   

\begin{equation}  
\partial{\cal F}\ =\ X-\frac{T}{X}\ -\ \lambda\ =\ 0  
\label{eq:fp}   
\end{equation}  
corresponding to the equation for the critical points of the potential \eqref{eq:potential}, where $\partial\overset{def.}{=}\partial/\partial X$.  We associate an equivariant Lagrangian brane to a solution $X$ of $\partial F=0$ satisfying 

\begin{equation}  
0\ <\ \text{val}(X)\ <\ 1  
\end{equation}   
as follows: take the moment fibre $L\equiv L_{_u}$, where $u\equiv\text{val}(X)$, take $c_{_o}\in \mathbb{C}^*$, and $c_{_+}\in \Lambda_{_+}$ such that \eqref{eq:rel} is satisfied.  The positive valuation part of the bounding cochain, $\mathfrak{b}_{_+}$ is given by 

\begin{equation}  
\mathfrak{b}_{_+}\ =\ \log\ (1+c_{_+})e^{^1}.     
\end{equation}

The leading term 

\begin{equation}  
\mathfrak{b}_{_o}\ =\ b_{_o}e^{^1}  
\end{equation}  
is taken such that 

\begin{equation}  
e^{^{b_{_o}}}\ =\ c_{_o},
\end{equation}
and gives a local system on $L_{_u}$ with monodromy $c_{_o}$. 

Then, $\mathfrak{b}=\mathfrak{b}_{_o}+\mathfrak{b}_{_+}$ gives a bounding cochain since $e^{^1}$ is an invariant form, and the resulting equivariant Lagrangian brane therefore consists of the triple  

\begin{equation}  
{\cal L}\ \overset{def.}{=}\ (L_{_u},\rho,\mathfrak{b}_{_+}).  
\end{equation} 

Solutions to \eqref{eq:fp} can be classified in 2 types according to the valuation of $\lambda$:  

\begin{enumerate}   
\item  If $\text{val}(\lambda)\ge\frac{1}{2}$, both solutions have valuation in $u_{_1}=u_{_2}=\frac{1}{2}$, i.e. consider two Lagrangian branes with the same underlying Lagrangian submanifold $L_{_{\frac{1}{2}}}$, but different bounding cochains.   

\item If $0\le\text{val}(\lambda)<\frac{1}{2}$, then the solutions have $u_{_1}=\text{val}(\lambda)$, $u_{_2}=1-\text{val}(\lambda)$, corresponding to two disjoint underlying Lagrangians $L_{_{u_{_1}}}, L_{_{u_{_2}}}$.   


\end{enumerate}     

Note that, for $\text{val}(\lambda)=0$, the Lagrangians collapse to points. We thereby restrict to the $\text{val}(\lambda)>0$ case.  

Denote the corresponding maximal ideals by $\mathfrak{m}_{_1},\mathfrak{m}_{_2}\in\text{Crit}{\cal F}$, and the corresponding bounding cochains by     

\begin{equation}  
\mathfrak{b}_{_i}\ =\ \mathfrak{b}_{_{o,i}}+\mathfrak{b}_{_{+,i}}.     
\end{equation}    

Since $\mu_{_1}^{^{\mathfrak{b}_{_i},\lambda}}=0$, the cohomology algebra reads as follows  

\begin{equation}  
H\left(\Omega^{^{\bullet}}\left(L_{_{u_{_{i}}}}\right)^{^{\mathfrak{g}}}\underset{\mathbb{C}}{\hat\otimes}\ \Lambda,\mu_{_1}^{^{\mathfrak{b}_{_i},\lambda}}\right)\ \simeq\ H^{^{\bullet}}\left(L_{_{u_{_{i}}}}\right)\otimes_{_{\mathbb{C}}}\Lambda.        
\end{equation}    
as a $\mathbb{Z}/2\mathbb{Z}$-graded $\Lambda$-vector spaces.  

