\subsubsection{The Grothendieck-Riemann-Roch Theorem} 

A deep result in Algebraic Geometry relating the Euler characteristic of vector bundles to characteristic classes. In turn, it is a generalisation to the relative setting of other theorems. 

\medskip

\underline{Theorem [Riemann-Roch]}  

\medskip 

Let $X$ be a complete nonsingular curve of genus $g$. For any divisor $D$ on $X$, 

\begin{equation}  
h^{^0}(D)\ -\ h^{^0}(K-D)\ =\ \text{deg}(D)+1-g  
\end{equation}  
where $K$ is a canonical divisor, and  

\begin{equation} 
h^{^0}(D)\ \overset{def.}{=}\ \text{dim}_{_{\mathbb{K}}}H^{^0}(D)  
\end{equation}  
over a base field $\mathbb{k}$.  


\medskip


\underline{Theorem [Riemann-Roch for Surfaces]} 


\medskip

Let $X$ be a complete nonsingular surface. For any divisor $D$ on $X$, 

\begin{equation}  
\chi(D)\ =\ \chi({\cal O}_{_X})\ +\ \frac{1}{2}(D^{^2}-D-K) 
\end{equation}

\medskip

\underline{Theorem [Hirzebruch-Riemann-Roch]}  

\medskip 

Let $X$ be a complete nonsingular variety. For any vector bundle $E$ on $X$, 

\begin{equation}  
\chi(X,E)\ =\ \int_{_X}\text{ch}(E)\ \cdot\ \text{td}(T_{_X})   
\end{equation}
with ch$(E)$ the Chern character, and td$T_{_X})$ the Todd class. 
This is a complex analysis result translated into Algebraic Geometry.  


\medskip


\underline{Theorem [Grothendieck-Riemann-Roch]} 


\medskip   

Let $f: X\rightarrow Y$ be a proper morphism of nonsingular varieties with $X$ quasi-projective. Then, for any $\alpha\in K(X)$, 

\begin{equation}  
\text{ch}(f_{_*}\alpha)\cdot \text{td}(T_{_Y})\ =\ f_{_*}\left(\text{ch}(\alpha)\cdot\text{td}(T_{_X})\right).  
\end{equation}

For $Y=\text{Spec}(\mathbb{k})$, it reduces to the HRR Theorem. 

The Chern and Todd class are defined as follows. 

\medskip


\underline{Chern classes} For a given scheme, $X$, Chern classes associate to each vector bundle $E$ on $X$ a collection of classes $c_{_k}(E)\ \in\ A^{^k}(X)$ reflecting the geometry of $E$. This is succinctly denoted as follows:  

\begin{equation}  
c(E)\ =\ 1+c_{_1}(E)+...  
\end{equation}  

\medskip

\underline{Todd class}  
Suppose $E$ admits a complete filtration  

\begin{equation}  
E\ =\ E_{_r}\ \supset\ E_{_{r-1}}\ \supset\ ...\ \supset E_{_1}\ \supset\ E_{_0}\ =\ 0  
\end{equation}   
of subbundles, such that rank $E_{_K}=k$. 
Let 

\begin{equation}  
L_{_k}\ =\ E_{_k}/E_{_{k-1}}\ \ \ \ \ , \ \ \ \ \text{for}\ \ \ 1\le k\le r.    
\end{equation}  

Then, by the Whitney sum formula, 

\begin{equation}   
c(E)\ =\ \prod_{_{k=1}}^{^r}c(L_{_k})\ =\ \prod_{_{k=1}}^{^r}(1+\alpha_{_k}) 
\end{equation}  
where $\alpha_{_k}=c_{_1}(L_{_k})$. $\alpha_{_k}$ are referred to as the Chern roots of $E$. The Chern character then reads  

\begin{equation}  
\begin{aligned}
\text{ch}(E)\ &=\ \sum_{_{k=1}}^{^r}\text{exp}(\alpha_{_k})\\
&=\ r+c_{_1}+\frac{1}{2}(c_{_1}^{^2}-2c_{_2})+\frac{1}{6}(c_{_1}^{^3}-3c_{_1}c_{_2}+c_{_3})+...  
\end{aligned}  
\end{equation}
where $r$ denotes the rank of $K$.  
The Todd class is then defined as 

\begin{equation}
\text{td}(E)\ =\ \prod_{_{i=1}}^{^r} Q(\alpha_{_i}),   
\end{equation}
where   

\begin{equation}  
Q(\alpha)\ =\ \frac{\alpha}{1-e^{^{-\alpha}}}\ =\ 1+\frac{1}{2}\alpha+\sum_{_{k=1}}^{^{\infty}}(-1)^{^{k-1}}\frac{B_{_k}}{(2k)!}\alpha^{^{2k}}  
\end{equation}  
with $B_{_k}$ denoting the Bernoulli numbers. 

The Todd class therefore reads  

\begin{equation}  
\text{td}(E)\ =\ 1+\frac{1}{2}c_{_1}+\frac{1}{12}(c_{_1}^{^2}+c_{_2})+\frac{1}{24}c_{_1}c_{_2}+... 
\end{equation}


\subsubsection{Mirror symmetry considerations}

On a CY manifold, $X$, The GRR Theorem reads as follows  

\begin{equation}
\chi(H)\ =\ \frac{H^{^3}}{6}+\frac{1}{12}c_{_2}(X)H  
\end{equation}   

For $H$ a divisor on $X$, 


\begin{equation}  
\chi(H)\ =\ \chi({\cal O}_{_H}(H))  
.
\end{equation}  

\underline{Example} 
A linear section of a quintic is a surface in 3D projective space. The 2$^{nd}$ Betti number is 53, hence, the Euler characteristic is 55. Therefore, we get 

\begin{equation} 
\chi({\cal O}_{_H}(H))\ =\ 5  \ \ \ 
\Rightarrow\ \ \ 5\ =\ \frac{H^{^3}}{6}+\frac{1}{12}c_{_2}(X)H\ \ \ \Rightarrow\ \ \ c_{_2}(X)H=50  
\end{equation} 

Therefore, the pair $(X,H)$ belongs to the space $M_{_{5,50}}$ where $X$ is a quintic in $\mathbb{P}^{^4}$ and $H$ is a hyperplane section. The Hodge numbers of $X$ are given by $(a,b)=(1,101)$. For its mirror, $\tilde X$, $(a,b)=(101,1)$.  

\underline{Proposition}  
Given a pair $(X,H)$ as previously defined, there is a primitive ample divisor $D$ on $X^{^{\prime}}$ such that $(\tilde X, D)$ belongs to $M_{_{5,50}}$.  

\underline{Example}  
For the generic quintic threefold, $X$, in $\mathbb{P}^{^4}$, $a=1, b=101, m=5, c=50$, satisfying the previous conditions, \eqref{eq:constr}. Therefore, $X$ lies in the space  

\begin{equation}  
M_{_{5,50}}\ =\ \{(X,H)|H^{^3}=5, c_{_2}(X)\cdot H=50\}  
\end{equation} \cal
The mirror $\tilde X$ of $X$ is a smooth CY threefold with $a=101, b=1, m=5, c=50$. So, it lies in the same space $M_{_{5,50}}$, but the Hodge numbers are exchanged, implying $X, \tilde X$ are, neither, diffeomorphic nor deformation equivalent.  



\section{Kapustin-Orlov branes: further details}     



To any complex torus equipped with a flat K$\ddot{\text{a}}$hler metric and a closed 2-form, they associate an ${\cal N}=2$ superconfromal vertex algebra (SCVA)\footnote{See \cite{VOA}.}.  

\subsection{Bockstein homomorphism}   

A Bockstein homomorphism is a connecting homomorphism associated with a short exact sequence  of abelian groups

\begin{equation}  
0\ \longrightarrow\ P\ \longrightarrow\ R \ \longrightarrow\ 0, 
\end{equation}
introduced as coefficients into a chain complex, $C$,   

\begin{equation}   
\beta:\ H_{_i}(C,R)\ \longrightarrow\ H_{_{i-1}}(C,P),  
\end{equation}
such that  

\begin{equation}  
\beta\beta\ =\ 0  \ \ \ \ , \ \ \ \ \beta(a\cup b)\ = \beta(a)\ \cup\ b+(-1)^{^{\text{dim} a}}a\cup \beta(b).  
\end{equation}   


\subsection{Grothendieck group}   

The Grothendieck group of an additive category is an Abelian group that is assigned to it by a universal additive mapping property. 

Let $C$ be a small additive category with set objects, Ob$(C)$, and let $G$ be an Abelian group. A mapping  

\begin{equation}  
\phi:\ \text{Ob}(C)\ \longrightarrow\ G    
\end{equation}  
is said to be additive if for any exact sequence  

\begin{equation}  
0\ \longrightarrow\ L\ \longrightarrow\ M\ \longrightarrow\ N\ \longrightarrow\ 0  
\end{equation}  
in $C$, the relation  

\begin{equation}  
\phi(M)\ =\ \phi(L)+\phi(N)  
\end{equation}    
is valid.  

There exists a group $K_{_o}(C)$, called the Grothendieck group of $C$, and an additive mapping     


\begin{equation}   
K_{_o}:\ \text{Ob}(C)\ \longrightarrow\ G  
\end{equation}   
a.k.a. the universal mapping, such that, for any additive mapping   

\begin{equation}  
\text{Ob}(C)\ \longrightarrow\ G  
\end{equation}  
there exists a unique homomorphism  

\begin{equation}    
\xi:\ K_{_o}(C)\ \longrightarrow\ G  
\end{equation}  
such that  

\begin{equation}  
\phi\ = \ \xi\circ K_{_o}  
\end{equation}  

This construction was first studied by Grothendieck for categories of coherent and locally free sheaves on schemes in proving the Riemann-Roch Theorem.    

The group $K_{_o}(C)$ is uniquely defined (up to isomorphism) and can be given by generators, $[L]$, one for each object $L\subset C$, and by the following relations  

\begin{equation}  
[L]\ -\ [N] \ - \ [M]\ = \ 0  
\end{equation}  
for each exact sequence  

\begin{equation}  
0\ \longrightarrow\ L\ \longrightarrow\ M \ \longrightarrow\ N\ \longrightarrow\ 0.  
\end{equation}   

\subsection{Picard group}     

A Picard group is an Abelian group defined for a symmetric monoidal category as the group of its isomorphism classes of objects which are invertible w.r.t. the tensor product.  

Most often, Pic$(X)$ is a space of invertible objects in a monoidal category of vector bundles over $X$. For the case in which $X$ is a complex manifold, these objects are holomorphic vector bundles, thereby implying Pic$(X)$ is an isomorphism class of holomorphic line bundles.


\subsection{Physicist's Mirror Symmetry}  

A CY triple is defined by the following   


\begin{equation}  
(X,G,{\cal B}),    
\label{eq:triple}   
\end{equation}  
where $X$ is a compact complex manifold with a trivial canonical bundle, $G$ is a Ricci-flat K$\ddot{\text{a}}$hler metric on $X$, ${\cal B}$ is a class in $H^{^2}(X,\mathbb{R}/\mathbb{Z})$ is the kernel of the Bockstein homomorphism 

\begin{equation}  
H^{^2}(X, \mathbb{R}/\mathbb{Z})\ \longrightarrow\ H^{^3}(X, \mathbb{Z}).   
\end{equation}    

The class ${\cal B}$ can be lifted to a class $b\in H^{^2}(X, \mathbb{R})$, and a closed 2-form $B$ representing it, conventionally referred to as the B-field.  

Kapustin and Orlov understood that to each such triple, \eqref{eq:triple}, one can associate an ${\cal N}=2$ superconformal vertex algebra (SCVA), which we now turn to describing.

\subsubsection{SCVAs}  

Vertex algebras play a crucial role in a Physicist's formulation of HMS [Kapustin, Orlov]. A vertex algebra is an algebraic counterpart of a 2D CFT.  

A chiral algebra is a vector superspace, $V$,  together with a map  

\begin{equation}  
Y:\ V\ \longrightarrow\ \text{End}\ V\left[\left[z,z^{^{-1}}\right]\right]  
\end{equation}  
satisfying certain properties. Specifically, $Y$ maps states to quantum fields. Chiral algebras are CFTs such that all fields are meromorphic (i.e. independent w.r.t. $\overline z$). Only a very special class of CFTs have this property. 

2 different quadruples $(\Gamma, I, G, B)$, and $(\Gamma^{^{\prime}}, I^{^{\prime}}, G^{^{\prime}}, B^{^{\prime}})$ yield isomorphic ${\cal N}=2$ superconformal vertex algebras (SCVAs).  

Denoting by 

\begin{equation}  
\Gamma^{^*}\ = \ \text{Hom}(\Gamma,\mathbb{Z})  
\end{equation} 
the dual lattice in $U^{^*}$, and with $T^{^*}$ the dual torus $U^{^*}/\Gamma^{^*}$, there is a natural pairing 

\begin{equation}  
l:\ \Gamma\ \oplus\ \Gamma^{^*}\ \longrightarrow\ \mathbb{Z}.  
\end{equation}   

There is also a natural $\mathbb{Z}$-valued symmetric bilinear form $q$ on $\Gamma\ \oplus\ \Gamma^{^*}$ defined as follows  

\begin{equation}  
q((w_{_1},m_{_1}),(w_{_2},m_{_2}))\ = \ l(w_{_1},m_{_2})+l(w_{_2},m_{1})  ,
\end{equation}
with $w_{_{1,2}}\in\Gamma$ and $m_{_{1,2}}\in\Gamma^{^*}$. Given $G, I< B$, we can define two complex structures on $T\times T^{^*}$  

\begin{equation}  
{\cal I}(I,B)\ = \ \left(\begin{matrix}  
&I \ \ \ \ \ \ \  \ \ \ \ \ \ \  \ \ \  0 \\   
&BI+I^{^t}B\ \ \ \ \ -I^{^t} \\     
\end{matrix}  
 \right)
\end{equation}   

\begin{equation}  
{\cal J}(G,I,B)\ = \ \left(\begin{matrix}  
&-IG^{^{-1}}B \ \ \ \ \ \ \  \ \ \ \ \ \ \  \ \ \  IG^{^{-1}} \\   
&GI-BIG^{^{-1}}B\ \ \ \ \ \ BIG^{^{-1}} \\     
\end{matrix}  
 \right),   
\end{equation}   
where 


\begin{equation}  
{\cal I\ ,\ J}\ \ \ \in\ \ \ \text{End}\left(U\oplus U^{^*}\right)  ,
\end{equation}

\begin{equation}  
G\ ,\ B\ \ \ \in\ \ \ \text{Hom}\left(U, U^{^*}\right) \ \ \  ,  \ \ \ I^{^t}\ =\ \text{End}\left(U^{^*} \text{conj. to} I\right).    
\end{equation}


${\cal J}$ depends on $G,I$ only by means of the combination $\omega=GI$, and therefore only depends on the symplectic structure on $T$ and the $B$-field.  

Two main theorems stated by Kapustin and Orlov are presented for completeness.

\medskip 

\medskip 


\underline{Theorem 2.1} [Kapustin, Orlov]  



\medskip 


Vert$(\Gamma, I, G, B)$ is isomorphic to Vert$(\Gamma^{^{\prime}}, I^{^{\prime}}, G^{^{\prime}}, B^{^{\prime}})$ if and only if there exists an isomorphism of lattices $\Gamma\oplus\Gamma^{^*}$, and $\Gamma^{^{\prime}}\oplus\Gamma^{^{*\prime}}$, which takes $q$ to $q^{^{\prime}}$, ${\cal I}$ to ${\cal I}^{^{\prime}}$ and ${\cal J}$ to ${\cal J}^{^{\prime}}$.   

\medskip 

\medskip 




\underline{Theorem 2.2} [Kapustin, Orlov]  

\medskip 
Vert$(\Gamma, I, G, B)$ is mirror to Vert$(\Gamma^{^{\prime}}, I^{^{\prime}}, G^{^{\prime}}, B^{^{\prime}})$ if and only if there is an isomorphism of lattices $\Gamma\oplus\Gamma^{^*}$ and $\Gamma^{^{\prime}}\oplus\Gamma^{^{\prime*}}$, which takes $q$ to $q^{^{\prime}}$, ${\cal I}$ to ${\cal J}^{^{\prime}}$ and ${\cal J}$ to ${\cal I}^{^{\prime}}$.    





\subsubsection{Kapustin-Orlov branes: non-Lagrangians}

Given the Grothendieck group of $D^{^b}(X)$, the Chern character reads 

\begin{equation}  
\text{ch}:\ K_{_{o}}\left(D^{^b}(X)\right)\otimes\mathbb{Q}\ \rightarrow\ H^{^{\bullet}}(X,\mathbb{Q}).  
\end{equation}

Its image is contained in 

\begin{equation}  
H^{^{\bullet}}(X,\mathbb{Q})\cap \left(\bigoplus_{_p}H^{^{p,p}}(X)\right)  \ \ \ \subset\ \ \ H^{^{\bullet}}(X,\mathbb{C}).
\end{equation}

In particular, dim Im(ch) can jump. For the case of abelian varieties, this is particularly manifest. 

\begin{equation}  
\text{Im(ch)}\otimes\mathbb{C}\ =\ \bigoplus_{_p}H^{^{p,p}}\ \ \ \Rightarrow\ \ \ \text{dim}_{_{\mathbb{Q}}}\text{Im(ch)}\ =\ \left(\begin{matrix} &2n\\
&n \end{matrix}\right).  
\end{equation}

In particular, there exists a functor  

\begin{equation}  
\Phi:\ K_{_o}\left(D{\cal F}\left(A,\omega_{_A}\right)\right)\otimes\mathbb{Q}\ \rightarrow\ H^{^{\bullet}}(A,\mathbb{Q})  
\end{equation}
closing the following commutative diagram 

