p\ &\downarrow\\   
&A   
\end{aligned}
\end{equation}

Let $P$ be a complex line bundle on $T$ defined by its first Chern class  

\begin{equation}  
c_{_1}(P)\ = \ \sum_{_{i=1}}^{^n}x_{_i}\cdot l_{_i}  
\end{equation}   

\begin{equation}  
\text{ch}(P)\ =\ \exp\left(c_{_1}(P)\right)\ \in\ H^{^{\bullet}}(T, \mathbb{Q})  
\end{equation}     

\begin{equation}    
H^{^{\bullet}}(B,\mathbb{Q})\ \xrightarrow{\beta}\ H^{^{\bullet}}(A,\mathbb{Q})    
\end{equation}   
is given by   

\begin{equation}    
\beta(a)\ \overset{def.}{=}\ p_{_*}\left(\text{ch}(P)\cdot q^{^*}(a)\right)  
\end{equation}   
using this for calculating the subspace $\beta\left(\text{Im}(\text{ch})\right)$. To prove the existence of objects in the mirror of $D^{^b}(B)$ that are not Lagrangian submanifolds, we let $n=2$ for simplicity and consider a holomorphic line bundle $L$ on $A$ whose first Chern class is equal to   

\begin{equation}    
c_{_1}\ = \ x_{_1}\cdot x_{_2}+y_{_1}\cdot y_{_2}.    
\end{equation}  


Such a holomorphic line bundle exists because $c_{_1}\in H^{^{1,1}}(B)$. The moduli space of such holomorphic line bundles is a homogeneous space over $\text{Pic}^{^0}(A)$. More explicitly, $L$ is of the form  

\begin{equation} 
L\ = \ {\cal O}(-D)\ \otimes\ N    
\end{equation}  
where 

\begin{equation}  
N\ \in\ \text{Pic}^{^0}(A) \ \ \ \ ,\ \ \ \ D\ =\ \Gamma-\{\text{pt}\}\times E- E\times\{\text{pt}\}  \end{equation}    
and $\Gamma$ is the graph of automorphism of $E$ given by multiplication by $i$. A direct calculation shows that    

\begin{equation}  
\beta(\text{ch}(L))\ =\ \left(1; y_{_1}\cdot y_{_2}-l_{_1}\cdot l_{_2}; -y_{_1}\cdot y_{_2}\cdot l_{_1}\cdot l_{_2}\right)\ \in \ H^{^{2k}}(A, \mathbb{Q})\ \ \ \ \ \ , \ \ \ \ k\in\mathbb{N}    
\end{equation}  
is equal to the Chern character of a complex line bundle, $L$, on $B$ with   

\begin{equation}  
c_{_1}(M)\ = \ y_{_1}\cdot y_{_2}\ -\ l_{_1}\cdot l_{_2}.     
\end{equation}

The complex line bundle is therefore expected to be an object in the mirror of $D^{^b}(B)$ and the invertible coherent sheaf $L$ goes to an object in $D^{^b}(B)$ under Mirror Symmetry.   

The subspace $\beta\left(\text{Im}(\text{ch})\right)$ consists of elements  

\begin{equation}  
(r,c,s)\ \in\ H^{^{2k}}(A,\mathbb{Q})   \ \ \ \ \ \ , \ \ \ \ k\in\mathbb{N}    
\end{equation}  
such that     

\begin{equation}  
c\cdot\omega_{_A}\ =\ 0 \ \ \ \ ,\ \ \ \ s\ =\ \frac{1}{2}r\omega_{_A}^{^2}. 
\end{equation}

Likewise, for all $n>2$, we can find elements of $\beta\left(\text{Im}(\text{ch})\right)$ which do not belong to the middle cohomology group of $A$, and therefore corresponds to non-Lagrangian objects of the mirror of $D^{^b}(B)$.  

Such phenomenon, in general, does not occur for odd-dimensional Calabi-Yau manifolds that are complete intersections in projective spaces. However, for even-dimensional CYs (e.g. K3-surfaces) or more general odd-dimensional CYs, the situation is similar to that of abelian varieties, namely non-Lagrangian A-branes feature at special points in the moduli space of symplectic structures.  




\section{HMS for elliptic curves}    

An elliptic curve is the Riemann surface given by the quotient $\mathbb{C}/\Lambda$ and its inherited complex structure, for $\Gamma$ a $\mathbb{Z}^{^2}$-lattice, \cite{5,6}.  

Choosing 

\begin{equation}  
\Lambda\ = \ <1,\tau>,      
\end{equation}    
we get a bijective relationship between elliptic curves and choices of $\tau$ with Image$(\tau)>0$ up to modular transformations.   

Conventional notation:  

\begin{equation}  
E_{_{\tau}}\ \overset{def.}{=}\ \mathbb{C}/<1,\tau>  
\end{equation}    


\subsection{Additive and pre-additive categories}     


A category is said to be additive if:  

\begin{enumerate}   

\item   Ab-enriched.  

\item    Admits finite coproducts.   

\end{enumerate}   

An Ab-enriched category, ${\cal C}$, is one such that for any pair of objects, $a,b$, the Hom-set, Hom$_{_{\cal C}}$(a,b), is equipped with the structure of an abelian group, implying for any triple of objects   

\begin{equation}  
a,b,c,\ \in\ \text{Obj}({\cal C})  
\end{equation}  

\begin{equation}  
\circ_{_{a,b,c,}}:\ \text{Hom}_{_{\cal C}}(a,b)\ \times\ \text{Hom}_{_{\cal C}}(b,c)\ \longrightarrow\ \text{Hom}_{_{\cal C}}(a,c)   
\label{eq:comp}
\end{equation}   
is bilinear.  


\medskip  


A pre-additive category is one such that each morphism set $\text{Hom}_{_{\cal A}}(x,y)$ is endowed with the structure of an abelian group such that any composition \eqref{eq:comp} is bilinear. A functor of pre-additive categories  

\begin{equation}  
{\cal F}:\ {\cal A}\ \longrightarrow\ {\cal B}  
\end{equation}  
is additive if and only if  

\begin{equation}   
{\cal F}:\ \text{Hom}(x,y)\  \longrightarrow\ \text{Hom}({\cal F}(x),{\cal F}(y))  
\end{equation}  
is a Hom of abelian groups for any pair $x,y\in$ Ob$({\cal A})$.

\subsection{Serre duality}    


In complex analytic geometry, Serre duality is the duality induced by the Hodge star operator on the Dolbeault complex.  

This generalises to suitable non-singular projective algebraic varieties over the base rings.  

Let $X$ be a Hamiltonian manifold of complex dimension  


\begin{equation}  
\text{dim}_{_{\mathbb{C}}}(\Sigma)\ =\ n.      
\end{equation}    

Its Riemann metric induces a Hodge star operator on the Dolbeault complex   


\begin{equation}    
\star:\ \Omega^{^{p,q}}(X)\ \longrightarrow\ \Omega^{^{n-q,n-p}}(X).     
\end{equation}    


For $X$ a compact Hermitian manifold, a bilinear form is defined as follows  


\begin{equation}    
\int_{_X}(-)\wedge\star(-):\ \Omega^{^{p,q}}(X)\ \otimes\ \Omega^{^{n-p, n-q}}(X)\ \longrightarrow\ \mathbb{C}    
\label{eq:intxpair}     
\end{equation}   
as the integral of differential forms   


\begin{equation}  
(\alpha, \beta)\ \mapsto\ \int_{_X}\alpha\wedge\star\ \beta.   
\end{equation}    

\medskip   

\underline{Proposition}\ (Serre duality)    

\medskip       

The pairing \eqref{eq:intxpair} induces a non-degenerate sesquilinear form on Dolbeault cohomology   

\begin{equation}    
\int_{_X}(-)\wedge\star(-):\ H^{^{p,q}}(X)\ \otimes\ H^{^{n-p, n-q}}(X)\ \longrightarrow\ \mathbb{C}.    
\label{eq:intxpair1}     
\end{equation}  

Relation to Poincare' duality follows from the Hodge Decomposition Theorem  


\begin{equation}   
H^{^k}(X,\mathbb{C})\ \simeq\ \bigoplus_{_{p+q=k}}H^{^{p,q}}(X).     
\end{equation}   


In practice, if  



\begin{equation}  
\text{dim}_{_{\mathbb{C}}}(\Sigma)\ = \ n.  
\end{equation}

Serre duality induces an isomorphism in ordinary cohomology of the form   


\begin{equation}  
H^{^k}(X,\mathbb{C})\ \xrightarrow{\simeq}\ H^{^{2n-k}}(X,\mathbb{C}).  
\end{equation}






