and considering the moduli space $\overline{\cal M}_{_k}(L;\beta)$ of stable maps from genus-0 bordered Riemann surfaces with connected boundary and $k$-boundary marked points respecting the cyclic order represented by the class $\beta$. This moduli space is a stable map compactification of the space of holomorphic disks,namely of the holomorphic embeddings    

\begin{equation}   
\left(D^{^2},\partial D^{^2}\right)\ \hookrightarrow\ (X,L).    
\end{equation}      

$\overline{\cal M}_{_k}(L;\beta)$ admits a Kunaishi structure with virtual dimension  

\begin{equation}  
\text{vir\ dim}_{_{\mathbb{R}}}\ \overline{\cal M}_{_k}(L;\beta)\ =\ n+ \ \mu(\beta)\ + \ k\
 -\ 3,     
\end{equation}     
with $\mu(\beta)$ denoting the Maslov index.    

The genus-0 Gromov-Witten invariant is defined as follows   

\begin{equation}  
n_{_{\beta}}\ \overset{def.}{=}\ \text{ev}_{_*}\left(\left[\overline{\cal M}_{_k}(L;\beta)\right]^{^{\text{vir}}}\right)\ \in\ H_{_n}(L;\mathbb{Q})\ \simeq\ \mathbb{Q},      
\end{equation}    
where   

\begin{equation}  
\text{ev}:\ \overline{\cal M}_{_k}(L;\beta)\ \longrightarrow\ L  
\end{equation}  
is the evaluation at the unique boundary marked point. The numbers $n_{_{\beta}}$ are independent w.r.t. the choice of perturbations, and are therefore invariants for the pair $(X,L)$, reason why they are usually referred to as Gromov-Witten invariants.    


The Lagrangian Floer superpotential is defined as   

\begin{equation}  
{\cal W}_{_q}^{^{\text{LF}}}\ \overset{def.}{=}\ \underset{\mu(\beta)=2}{\sum_{_{\beta\in \pi_{_2}(X,L)}}}n_{_{\beta}}Z_{_{\beta}},    
\label{eq:wlf}  
\end{equation}     
where   

\begin{equation}   
Z_{_{\beta}}(L,\nabla)\ = \ \text{exp}\left(-\int_{_{\beta}}\omega_{_q}\right)\ \text{hol}_{_{\nabla}}(\partial\beta).     
\end{equation}


In general, \eqref{eq:wlf} involves infinitely-many terms.  

The semi-flat SYZ-transform    


\begin{equation}   
{\cal F}^{^{\text{semi-flat}}}:\ \Omega^{^o}(T)\ \longrightarrow\ \Omega^{^n}\left(T^{^*}\right)  
\end{equation}  
is given by   


\begin{equation}  
{\cal F}^{^{\text{semi-flat}}}(\phi):\ \int_{_T}\phi\left(y^{^1},...,y^{^n}\right)\ e^{^{i\sum_{_j}\text{d}y_{_j}\wedge\text{d}y^{^j}}}  
\end{equation}  
while the usual Fourier transform gives a function  


\begin{equation}  
\hat\phi:\ \Lambda^{^{\text{V}}}\ \longrightarrow\ \mathbb{C}  
\end{equation}   
on the dual lattice $\Lambda^{^{\text{V}}}$ by   

\begin{equation}  
\hat\phi\left(m_{_1},...,m_{_n}\right)\ =\ \int_{_T}\phi\left(y_{_1},...,y_{_n}\right)\ e^{^{i\sum_{_j}m_{_j}y^{^j}}}\text{d}y_{_1}\wedge...\wedge\text{d}y_{_n}.     
\end{equation}   


Combining the two transformations to define the SYZ transformation, ${\cal F}^{^{\text{SYZ}}}$, turning differential forms on $T\times\Lambda$ to those in $T^{^*}\times\Lambda^{^{\text{V}}}$.  Here, $T\times\Lambda$ denotes the space of geodesics or affine loops in $T$ sitting inside the loop space of $T$  

\begin{equation}    
T\times\Lambda\ = \ {\cal L}_{_{\text{geo}}}T\ \subset\ {\cal L}T.  
\end{equation}  

For the case of compact toric Fano varieties, ${\cal F}^{^{\text{SYZ}}}$ interchanges the symplectic and complex geometries, with quantum corrections included.      



Consider the open dense subset   


\begin{equation}   
U_{_o}\ \overset{def.}{=}\ X\backslash D,  
\end{equation}  
which is the union of all Lagrangian torus fibers of the moment map. 

\begin{equation}   
U_{_o}\ \simeq\ T^{^*}\Delta^{^o}/\Lambda^{^{\text{V}}}  
\end{equation} 
as symplectic manifolds.   

\begin{equation}   
\tilde X\ \overset{def}{=}\ U_{_o}\times\Lambda\ \subset\ {\cal L}X  
\end{equation}  

On $\tilde X$, we have the quantum corrected symplectic structure   

\begin{equation}   
\tilde\omega\ = \ \omega+\Phi   
\end{equation}   
implying ${\cal F}^{^{\text{SYZ}}}$ can be constructed by composing ${\cal F}^{^{\text{semi-flat}}}$ with fiberwise Fourier series.   



\medskip 

\medskip   

\underline{Theorem}   

\medskip  

\medskip  

\begin{enumerate}   


\item The SYZ transforms interchange the quantum-corrected symplectic structure on $\tilde X$ with the holomorphic volume form of the pair $(\hat X, {\cal W})$, i.e. we have  

\begin{equation}   
{\cal F}^{^{\text{SYZ}}}\left(e^{^{i(\omega+\Phi)}}\right)\ =\ e^{^{\cal W}}\tilde\Omega\ \ \ \ \ \ \ \ \ \ \ , \ \ \ \ \ \ \ \ \ \ \ \ \left({\cal F}^{^{\text{SYZ}}}\right)^{^{-1}}\ \left(e^{^{\cal W}}\tilde\Omega \right)\ = \  e^{^{i(\omega+\Phi)}}.        
\end{equation}  

\item   The SYZ transformation induces an isomorphism  

\begin{equation}   
{\cal F}^{^{\text{SYZ}}}:\ {\cal Q}H^{^{\bullet}}\left(X, \omega_{_q}\right)\ \xrightarrow\ \text{Jac}\left({\cal W}_{_q}^{^{\text{LF}}}\right)  
\end{equation}   
between the small quantum cohomology ring of $X$ and the Jacobian ring of the Lagriangian Floer superpotential ${\cal W}_{_q}^{^{\text{LF}}}$.     

\end{enumerate}


\subsection{Open Mirror Theorems}    

For semi-Fano toric Fano varieties, the mirror theorems of Givental and Lian-Liu-Yau imply the existence of the following isomorphism \cite{12}       

\begin{equation}   
{\cal Q}H^{^{\bullet}}\left(X, \omega_{_q}\right)\ \simeq\ \text{Jac}\left({\cal W}_{_{t(q)}}^{^{\text{LF}}}\right),      
\end{equation}    
where $t(q)=\psi^{^{-1}}(q)$ is the inverse of the toric mirror map  

\begin{equation}  
\begin{aligned}   
&\psi:\ \hat{\cal M}_{_B}\ \longrightarrow\ {\cal M}_{_A}\\
&\\ 
&t\ = \ \left(t_{_1}, ..., t_{_r}\right)\ \mapsto\ \psi(t)\ =\ \left(q_{_1}(t), ..., q_{_r}(t)\right)  
\end{aligned}
\end{equation}   


Instanton corrections can be realised using the genus 0 open Gromov-Witten invariants, $n_{_{\beta}}$. In terms of the Lagrangian Floer superpotential  



\begin{equation}   
{\cal W}_{_q}^{^{\text{LF}}}\ =\ \underset{\mu(\beta)=2}{\sum_{_{\beta\in\pi_{_2}(X,L)}}}\ n_{_{\beta}}Z_{_{\beta}}.  
\end{equation}




\medskip 

\medskip   

\underline{Conjecture}   

\medskip  

\medskip  

Let $X$ be a semi-Fano toric manifold, namely, its anticanonical divisor, $-K_{_X}$ is nef. Then,    

\begin{equation}   
{\cal W}_{_{t(q)}}^{^{\text{HV}}}\ =\ {\cal W}_{_q}^{^{\text{LF}}}   
\end{equation}   
via the inverse mirror map $t(q)=\psi^{^{-1}}(q)$.  

The semi-Fano varieties, $n_{_{\beta}}\neq0$  iff  


\begin{equation}    
\beta\ = \ \beta_{_i}+d,     
\end{equation}   
with $\beta_{_i}$ denoting a basic disk class, and $d\in H_{_2}^{^{\text{eff}}}(X;\mathbb{Z})$ an effective curve class such that   

\begin{equation}   
c_{_1}(d)\ = \ c_{_1}(X)\cdot d\ = \ 0.   
\end{equation}   


In particular, the Lagrangian Floer superpotential is a Laurent polynomial that can be expressed as  


\begin{equation}  
{\cal W}_{_q}^{^{\text{LF}}}\ =\ \sum_{_{i=1}}^{^n}\ C_{_i}\left(1+\delta_{_i}(q)\right)\ z^{^{v_{_i}}},      
\end{equation}   
where    


\begin{equation}  
1+\delta_{_i}(q)\ =\ \underset{c_{_1}(\alpha)=0}{\sum_{_{\beta\in H_{_2}^{^{\text{eff}}}(X;\mathbb{Z})}}}\ \ n_{_{\beta_{_i}+\alpha}}q^{^{\alpha}}  
\end{equation}  
is a generic function of genus 0 open GW invariants, with $C_{_i}\in\mathbb{C}$ constants such that    


\begin{equation} 
\begin{aligned}
&q_{_{a}}\ =\ \prod_{_{i=1}}^{^m}C_{_i}^{^{D_{_i}\cdot\gamma_{_a}}}\ \ \ \ \ , \ \ \ \ \ a=1,...,r  \\   
&\\  
&q\ =\ \left(q_{_1},...,q_{_r}\right)\ \in\ {\cal M}_{_A},     
\end{aligned}
\end{equation}   
with $q$ denoting the complexified K$\ddot{\text{a}}$hler parameters.  

The SYZ map  

\begin{equation}   
\begin{aligned}
     &\phi:\ {\cal M}_{_A}\ \longrightarrow\ \hat{\cal M}_{_B}\\  
     &\\   
     &q=\left(q_{_1},...,q_{_r}\right)\ \mapsto\ \phi(q)\ =\ \left(t_{_1}(q),...,t_{_r}(q)\right)
\end{aligned}    
\end{equation}   




\subsection{Mirror Symmetry for Toric CY varieties}    

Let $X=X_{_{\Sigma}}$ be a toric CY variety of complex dimension $n$. By choosing a suitable basis of $N=\mathbb{Z}^{^n}$. One may then write  

\begin{equation}  
v_{_i}\ =\ \left(w_{_i},1\right)\ \in\ N\ =\ \mathbb{Z}^{^{n-1}}\oplus \mathbb{Z}  \ \ \ \ , \ \ \ \ w_{_i}\ \in\ \mathbb{Z}^{^{n-1}}.  
\end{equation}  

Assuming $X$ is smooth and the fan $\Sigma$ has convex support. In such case, the CY is a crepant resolution of an affine toric variety (defined by the cone $|\Sigma|$) with Gorenstein canonical singularities, making $X$ semi-projective.  


\subsubsection{Crepant resolutions of CY orbifolds}    

To construct a CY\footnote{A complex Kaehler manifold with trivial canonical bundle.}, one can start from a singular CY. Among the simplest singularities to be considered, we could use orbifold singularities, where an orbifold is a quotinet of a smooth CY manifold by a discrete group action featuring fixed points. Locally modelled on $\mathbb{C}^{^n}/G$, with $G$ a finite subgroup of $SL(n,\mathbb{C})$.   

A resolution $(X,\pi)$ of $\mathbb{C}^{^n}/G$ is a nonsignular complex manifold $X$ of dimension $n$ with proper biholomorphic map  

\begin{equation}  
\pi:\ x\ \longrightarrow\ \mathbb{C}^{^n}/G  
\end{equation}  
inducing a biholomorphism between dense open sets. 

$X$ is said to be a \emph{crepant resolution} if the canonical bundles are isomorphic   


\begin{equation}   
K_{_X}\ \simeq\ \pi^{^*}\left(K_{_{\mathbb{C}^{^n}/G}}\right).     
\end{equation}     

To obtain a CY structure on $X$, one must choose a crepant resolution of singularities. 

The amount of information we can access about a crepant resolution of singularities of $\mathbb{C}^{^n}/G$ heavily depends on the dimension $n$ of the orbifold:  


\begin{itemize} 

\item  $\boxed{n=2}$  There is a unique crepant resolution. In this case, the Topology of the manifold is completely described by the finite group $G$.

\item   $\boxed{n=3}$  A crepant resolution exists, but is not unique. The different possible resolutions are related by flops, and share the same Euler and Betti numbers.

\item   $\boxed{n\ge 4}$  Very little is known in this case.  

\end{itemize}

\subsubsection{Example: $K_{_{\mathbb{P}^{^2}}}$}  


Take $X=K_{_{\mathbb{P}^{^2}}}$, a toric CY 3-fold, whose fan $\Sigma$ has rays generated by the lattice points  


\begin{equation}  
v_{_0}\ =\ (0,0,1)\ \ \ \ \  , \ \ \ \ \ v_{_1}\ =\ (1,0,1)\ \ \ \ \  , \ \ \ \ \ v_{_2}\ =\ (0,1,1)\ \ \ \ \  , \ \ \ \ \ v_{_3}\ =\ (-1,-1,1)   
\end{equation}   

\begin{equation}   
v_{_i}\ \in\ N\ = \ \mathbb{Z}^{^3}.  
\end{equation}  

Mirror symmetry, in this setting is called local mirror symmetry since it originates from mirror symmetry techniques applied to Fano surfaces, such as $\mathbb{P}^{^2}$, contained inside compact CY manifolds, and could be recovered by using physical arguments from mirror symmetry for compact CY hypersurfaces in toric varieties by taking certain limits in the complexified K$\ddot{\text{a}}$hler and complex moduli spaces.   

The mirror of $X$ defined as above is a family of affine hypersurfaces in  

\begin{equation}   
\hat X_{_t}\ =\ \left\{\left(u,v,z_{_1},...,z_{_{n-1}}\right)\ \in \ \mathbb{C}^{^2}\times\left(\mathbb{C}^{^{\times}}\right)^{^{n-1}}:\ uv\ =\ \sum_{_{i=1}}^{^m}\hat C_{_i}z^{^{w_{_i}}}\right\},     
\label{eq:dualkp2}   
\end{equation}   
where $\hat C_{_i}\ \in\ \mathbb{C}$ are constants subject to constraints  


\begin{equation}  
t_{_a}\ =\ \prod_{_{i=1}}^{^m}\ \ \hat C_{_i}^{^{D_{_i}\cdot\gamma_{_a}}}\ \ \ \ , \ \ \ \ a=1,...,r  ,
\end{equation}  
with   


\begin{equation}  
t\ =\ \left(t_{_1},...,t_{_r}\right)  
\end{equation}  
are coordinates on the mirror complex moduli   

\begin{equation}  
\hat{\cal M}_{_B}\ \overset{def.}{=}\ \mathbb{K}^{^{\text{V}}}\underset{\mathbb{Z}}{\otimes}\mathbb{C}^{^{\times}}\ \simeq\ \left(\mathbb{C}^{^{\times}}\right)^{^r}.  
\end{equation}  

The mirror dual $\hat X_{_t}$ is noncompact with nowhere vanishing volume form  

\begin{equation}  
\hat\Omega_{_t}\ \overset{def.}{=}\ \text{Res}\left(\frac{\text{d}u\wedge \text{d}v\wedge \text{d}\log z_{_1}\ \wedge\ ...\ \wedge \text{d}\log z_{_{n-1}}}{uv-\sum_{_{i=1}}^{^m}\hat C_{_i}z^{^{w_{_i}}}}\right).     
\end{equation}   

\eqref{eq:dualkp2} for $X=K_{_{\mathbb{P}^{^2}}}$ reads as follows   

\begin{equation}   
\hat X_{_t}\ =\ \left\{\left(u,v,z_{_1},z_{_2}\right)\ \in \ \mathbb{C}^{^2}\times\left(\mathbb{C}^{^{\times}}\right)^{^2}:\ uv\ =\ 1+z_{_1}+z_{_2}+\frac{t}{z_{_1}z_{_2}}\right\},     
\label{eq:dualkp21}   
\end{equation}   
with $t$ being a coordinate on the mirror complex moduli space $\hat{\cal M}_{_B}\simeq\mathbb{C}^{^{\times}}$.   

Recalling the definition of local GW-invariants  


\begin{equation}  
N_{_{g,d}}(X)\ \overset{def.}{=}\ \int_{_{\left[\overline{\cal M}_{_{g,0}}(X,d)\right]^{^{\text{vir}}}}}\mathbf{1}.
\end{equation}    

These invariants are, in general, hard to compute due to nontrivial obstructions. However, mirror symmetry can be used to calculate, at least, genus 0 invariants.     

As previously outlined, performing such calculations requires a mirror map   

\begin{equation}  
\psi:\ \hat{\cal M}_{_B}\ \longrightarrow\ {\cal M}_{_A}  
\end{equation}  
which is a local isomorphism from the complex moduli $\hat{\cal M}_{_B}$ of the mirror $\hat X$ to the complexified K$\ddot{\text{a}}$hler moduli ${\cal M}_{_A}$ of $X$. Traditionally, mirror maps are defined as quotients of period integrals   


\begin{equation}  
\int_{_{\Gamma}}\ \ \hat\Omega,      
\end{equation}  
with $\Gamma\in H_{_3}\left(\hat X;\mathbb{Z}\right)$ a middle-dimensional integral cocyle. Such integrals satisfy a system of Picard-Fuchs PDEs, whose solutions are explicit hypergeometric-type functions (this is the usual procedure through which mirror maps are usually calculated). For the specifics of the example in question, the PF system reduces to a single ODE  


\begin{equation} 
\left[\left(t\ \frac{\text{d}}{\text{d}t}\right)^{^3}+3t^{^2}\frac{\text{d}}{\text{d}t}\left(3+t\ \frac{\text{d}}{\text{d}t}+1\right)\left(3t\ \frac{\text{d}}{\text{d}t}+2\right)\right]\ \Phi\ =\ = 0   
\end{equation}   

A basis of solutions to this equation is explicitly given by    

\begin{equation}  
\begin{aligned}
&\Phi_{_0}(t)\ = \ 1\\     
&\Phi_{_1}(t)\ =\ \log t + \sum_{_{k=1}}^{^{\infty}}\frac{(-1)^{^k}}{k}\frac{(3k)!}{(k!)^{^3}}\ t^{^k}\\   
&\Phi_{_1}(t)\ =\ \left(\log t\right)^{^2} + ...\\     
\end{aligned}  
\end{equation}   


The mirror map is    

\begin{equation}  
q\ =\ \psi(t)\ = \ \text{exp}\left(\frac{\Phi_{_1}(t)}{\Phi_{_0}(t)}\right)\ =\ t\ (1+...)   
\end{equation}  
and genus 0 GW-invariants $N_{_{0,d}}(X)$ are predicted to appear as the coefficients of the Taylor series expansion of $\Phi_{_2}\left(\psi^{^{-1}}(q)\right)$ around $q=0$.      


Via the inverse mirror map  

\begin{equation}   
q\ \mapsto\ \psi^{^{-1}}(q)         
\end{equation}   
and a coordinate change, the mirror of $K_{_{\mathbb{P}^{^2}}}$ is   

\begin{equation}   
\hat X_{_t}\ =\ \left\{\left(u,v,z_{_1},z_{_2}\right)\ \in \ \mathbb{C}^{^2}\times\left(\mathbb{C}^{^{\times}}\right)^{^2}:\ uv\ =\ f(q)+z_{_1}+z_{_2}+\frac{q}{z_{_1}z_{_2}}\right\},     
\label{eq:dualkp22}   
\end{equation}    
with   

\begin{equation}  
f(q)\ =\ \left(\frac{\psi(t)}{t}\right)^{^{\frac{1}{3}}}\ = \ 1-2q+5q^{^2}-32q^{^3}+286q^{^4}-3038 q^{^5}+...  
\label{eq:fq}   
\end{equation}    

Later on, we will see that the coefficients featuring in $f(q)$ constitute virtual counts of holomorphic disks.   

\subsubsection*{SYZ construction}   

For the case of a toric CY manifold (or, more generically, an orbifold), $X$, a special Lagrangian torus fibration on $X$ is needed, [Goldstein] [Gross].  

\medskip   

\medskip   

\underline{Setup}  

\medskip   

\medskip    


Take a lattice point $u$, defining the hyperplane containing all the generators $v_{_i}$, corresponding to the holomorphic function  

\begin{equation}  
\chi^{^u}:\ X\ \longrightarrow\ \mathbb{C}  
\end{equation}   
with simple zeros along each toric prime divisor $D_{_i}\subset X$.  Equipping $X$ by a K$\ddot{\text{a}}$hler structure $\omega$, and considering the action by the subtorus  


\begin{equation}   
T^{^{n-1}}\ \subset\ T_{_N}\ \simeq\ T^{^n}  
\end{equation}    
preserving $\chi^{^u}$, therefore also  preserving the canonical holomorphic volume form $\Omega$ on $X$.    



Let    

\begin{equation}   
\rho_{_o}:\ X\ \longrightarrow\ \mathbb{R}^{^{n-1}}  
\end{equation}  
be the corresponding moment map which is given by composing the $T_{_N}$-moment map with the projection along the ray in $M_{_{\mathbb{R}}}$ spanned by $u$.    

\medskip   

\medskip 

\underline{Proposition} [Goldstein] [Gross]   For any nonzero constant $\epsilon\ \in\ \mathbb{C}^{^{\times}}$, the map defined by    



\begin{equation}  
\rho\ \overset{def.}{=}\ \left(\rho_{_o},\left|\chi^{^u}-\epsilon\right|\right):\ X\ \longrightarrow\ B\ \overset{def.}{=}\ \mathbb{R}^{^{n-1}}\times\mathbb{R}_{_{\ge0}}.  
\end{equation}  

The base of the Gross fibration on $K_{_{\mathbb{P}^{^2}}}$, is an upper-half space in $\mathbb{R}^{^3}$. $\rho$ is a special Lagrangian torus fibration, where the fibers are special w.r.t. themeromorphic volume form   

\begin{equation}  
\Omega_{_{\epsilon}}\ \overset{def.}{=}\ \frac{\Omega}{\chi^{^u}-\epsilon}  
\end{equation}   
with $\rho$ the Gross fibration, which is non-toric due to the lack of a $T_{_N}$-moment map. A fiber of $\rho$ is non-regular iff, either:   




\begin{enumerate}   

\item  When it intersects nontrivially with the hypersurface $D_{_{\epsilon}}\subset X$ defined by 


\begin{equation}  
\chi^{^u}\ =\ \epsilon  
\end{equation}   
is then mapped to the boundary   


\begin{equation}   
\partial B\ =\ \mathbb{R}^{^{n-1}}\times\{0\}.      
\end{equation}  

\item Or, when it contains a point where the $T^{^{n-1}}$-action is not free, i.e. if when at least two of the homogeneous coordinates on $X$ vanish, in which case the fiber is mapped to the image $\Gamma$ of the codimension-2 subvariety  

\begin{equation}   
\bigcup_{_{i\neq j}}\ \ D_{_i}\ \cap\ D_{_j}  
\end{equation}     
under $\rho$.  

\end{enumerate}

In the above, $B$ denotes a tropical affine manifold with boundary $\partial B$ and singularities $\Gamma$, the latter being a codimension-2 surface in $B$.  



\medskip   

\medskip    


$\bullet \text{\textbf{\ \ \ STEPS (STZ prescription) [Auroux]}} $      


\medskip   

\medskip 

Starting with a special Lagrangian torus fibration  

\begin{equation}   
\rho:\ X\ \longrightarrow\ B     
\end{equation}    
on a CY manifold, the SYZ mirror construction proceeds in several steps:   



\medskip   

\medskip 



\underline{\textbf{Step 1}} \ \ \  Over the smooth locus  


\begin{equation}  
B_{_o}\ \equiv\ B\backslash(\partial B\cup\ \Gamma),      
\end{equation}   
the pre-image   

\begin{equation}  
X_{_o}\ \equiv\ \rho^{^{-1}}(B_{_o})   
\end{equation}  
can be identified with the quotient   


\begin{equation}   
T^{^*}B_{_o}/\Lambda^{^{\text{V}}}.  
\end{equation}


\medskip   

\medskip 

\underline{\textbf{Step 2}} \ \ \  Define the semi-flat mirror, $\hat X_{_o}$ as $TB_{_o}/\Lambda$ (not the correct mirror since the complex structure on $\hat X_{_o}$ cannot be extended further to any (partial) compactification as the monodromy of the tropical affine structure around the discriminant locus $\Gamma$ is nontrivial).     

\medskip   

\medskip 

\underline{\textbf{Step 3}} \ \ \ To obtain the correct and (partially) compactified mirror $\hat X$, we need to modify the complex structure on $\hat X_{_o}$ by instanton corrections, which should come from holomorphic disks in $X$ bounded by Lagrangian torus fibers on the fibration $\rho$.    



Inside a base $B$, one can define a \emph{wall}, $H$, inside the base of a Lagrangian torus fibration to be the union of the loci of regular fibers which nonconstant holomorphic or stable disks of Maslov index 0 in $X$. 

For the Gross fibration on a toric CY manifold, there is only one wall given by the hyperplane   


\begin{equation}
    H\ = \ \mathbb{R}^{^{n-1}}\times\left\{|\epsilon|\right\}\ \subset\ B\ \ \ \ , \ \ \ \ H\ //\ \partial B,     
\end{equation}    
containing the discriminant locus $\Gamma$ as a tropical hypersurface, and it divides the base $B$ into two chambers:   


\begin{equation}  
B_{_+}\ \equiv\ \mathbb{R}^{^{n-1}}\times\left(|\epsilon|, +\infty\right)\ \ \ \ \ , \ \ \ \ B_{_-}\ \equiv\ \mathbb{R}^{^{n-1}}\times\left(0,|\epsilon|\right)   
\end{equation}    
over which the Lagrangian torus fibers behave differently in a Floer-theoretic sense.    


\begin{figure}[ht!]  
\begin{center}  
\includegraphics[scale=1]{Gross.pdf}  
\caption{\small $H$ is the wall between $B_{_+}$ and $B_{_-}$, whereas the graph $\Gamma$ is the discriminant locus, contained in the hyperplane $H//\partial B$. The base of the Gross fibration on $K_{_{\mathbb{P}^{^2}}}$ is an upper-half space in $\mathbb{R}^{^3}$.}
\label{fig:Gross}  
\end{center}  
\end{figure}


Genus 0 open GW-invariants correspond to the virtual counts of Maslov index 2 stable disks\footnote{The geometric meaning of the Maslov index 2 here means that the stable disks intersect with the hypersurface $D_{_{\epsilon}}$ at only 1 point with multiplicity 1.} in $X$ bounded by fibers of $\rho$. As one moves from one chamber to the other by crossing the wall $H$, the virtual counts of Maslov index 2 disks bounded by the corresponding Lagrangian torus fiber would jump, exhibiting a wall-crossing phenomenon. Fibers over the chamber $B_{_-}$ bound only one family of Maslov index 2 disks, such that the corresponding generating function of open GW-invariants has just one term with coefficient 1.    

On the other hand, fibers over $B_{_+}$ bound as many Maslov index 2 disks as a moment map Lagrangian torus fiber, such that the corresponding generating function of open GW-invariants has (possibly) infinitely-many terms.  

The resulting wall-crossing factor is exactly what we need to get the correct mirror   

\begin{equation}   
{\cal W}_{_q}^{^{\text{LF}}}\ =\ \begin{cases}    
&z_{_o}\sum_{_{i=1}}^{^m}\ \left(1+\delta_{_i}(q)\right)\ C_{_i}z^{^{w_{_i}}}, \ \text{over} \ \ B_{_+}\\   
&u \ \ \ \ , \ \text{over} \ \ B_{_-}\\   
\end{cases}  
\end{equation}    
where   


\begin{equation}  
1+\delta_{_i}(q)\ =\ \sum_{_{\alpha\in H_{_2}^{^{eff}}(X;\mathbb{Z})}}n_{_{\beta_{_i}+d}}q^{^d}  
\end{equation}    
is a generating function of genus-0 GW-invariants.   





$z_{_o}, u$ denote the coordinates associated to the lattice point  

\begin{equation}  
(0,...,0,1)\ \in\ \mathbb{Z}^{^{n-1}}\oplus \mathbb{Z}  
\end{equation}   
over $B_{_+}$ and $B_{_-}$, respectively, and  

\begin{equation}  
    z^{^w}\ =\ z_{_1}^{^{w^{^1}}}...z_{_{n-1}}^{^{w^{^{n-1}}}}\ \ \ \ \ \ , \ \ \ \ \ \ w\ = \ \left(w^{^1},...,w^{^{n-1}}\right)\ \in\ \mathbb{Z}^{^{n-1}} 
    \end{equation}   



    \begin{equation}   
    q^{^d}\ =\ \exp\left(-\int_{_d}\omega_{_{\mathbb{C}}}\right).  
    \end{equation}   

    The semi-flat mirror   

    \begin{equation}  
    \hat X_{_o}\ = \ TB_{_o}/\Lambda  
    \end{equation}   
    can be viewed as the gluing of two complex charts  

    \begin{equation}  
    \hat X_{_+}\ =\ TB_{_+}/\Lambda\ \ \ , \ \ \ \hat X_{_-}\ = \ TB_{_-}/\Lambda  
    \end{equation}  
    associated to the chambers $B_{_+}$ and $B_{_-}$, respectively. Nontrivial monodromy of the topological affine structure on $B_{_o}$ around the discriminant locus $\Gamma$ prevents the complex structure on $\hat X$ from extending any further. 


    [Auroux] showed that, following Floer theory, ${\cal W}_{_q}^{^{\text{LF}}}$ is an analytic function, hence one should modify the gluing between the complex charts, $\hat X_{_{\pm}}$ by the wall-crossing factors   

    \begin{equation}  
    \sum_{_{1=1}}^{^m}\left(1+\delta_{_i}(q)\right)C_{_i}z^{^{w_{_i}}}  
    \end{equation}   
    which cancels the nontrivial monodromy of the complex structure around $\Gamma\subset B$, and gives an analytic superpotential on the corrected mirror, $\hat X$, leading to the following  

    \medskip 

    \underline{Theorem}  

    \medskip  

    The SYZ mirror for the toric CY manifold, $X$ is given by the family of affine hypersurfaces  

    \begin{equation}  
    \hat X_{_q}\ = \ \left\{\left(u, v, z_{_1},...,z_{_{n-1}}\right)\ \in\ \mathbb{C}^{^2}\times\left(\mathbb{C}^{^{\times}}\right)^{^{n-1}}:\ uv\ =\  \sum_{_{1=1}}^{^m}\left(1+\delta_{_i}(q)\right)C_{_i}z^{^{w_{_i}}}  \right\}
    \end{equation}  
    entirely written in terms of the complexified K$\ddot{\text{a}}$hler parameters and disk-counting invariants of $X$.    











\subsection*{Application of the Theorem}    


The SYZ mirror of $X=K_{_{\mathbb{P}^{^2}}}$ is given by     


\begin{equation}  
\hat X\ = \ \left\{\left(u, v, z_{_1},...,z_{_{n-1}}\right)\ \in\ \mathbb{C}^{^2}\times\left(\mathbb{C}^{^{\times}}\right)^{^{n-1}}:\ uv\ =\  1+\delta_{_o}(q)+z_{_1}+z_{_2}+\frac{q}{z_{_1}z_{_2}}  \right\},    
    \end{equation}  
    where $q$ is the K$\ddot{\text{a}}$hler parameter measuring the symplectic area of a projective line contained inside the nonzero section of $K_{_{\mathbb{P}^{^2}}}$ over $\mathbb{P}^{^2}$, and   

    \begin{equation}   
    1+\delta_{_o}(q)\ =\ \sum_{_{k=0}}^{^{\infty}}n_{_{\beta_{_o}+kl}}q^{^k}  
    \end{equation}  
    being the generating function of genus-0 open GW-invariants,  


    \begin{equation}  
    l\ \in\ H_{_2}\left(K_{_{\mathbb{P}^{^2}}};\mathbb{Z}\right)\ =\ H_{_2}\left(\mathbb{P}^{^2};\mathbb{Z}\right)  
    \end{equation}  
    denotes the hyperplane class in $\mathbb{P}^{^2}$,  

\begin{equation}   
q\ =\ \exp(-t)  
\end{equation}  
$\beta_{_o}$ is the basic disk class, corresponding to the 0-section   

\begin{equation}  
\mathbb{P}^{^2}\ \subset\ K_{_{\mathbb{P}^{^2}}},  
\end{equation}
which is the only compact toric divisor in $K_{_{\mathbb{P}^{^2}}}$.  


Applying the open/closed formula and a flop formula for closed GW-invariants, the genus-0 open GW-invariants $n_{_{\beta_{_o}+kl}}q^{^k}$ can be expressed in terms of local BPS invariants of $K_{_{\mathbb{F}}}$, where $\mathbb{F}_{_1}$ is the blowup of $\mathbb{P}^{^2}$ at a point. If  

\begin{equation}   
e,f\ \in\ H_{_2}\left(K_{_{\mathbb{F}_{_1}}};\mathbb{Z}\right)\ =\ H_{_2}\left(\mathbb{F}_{_1};\mathbb{Z}\right)  
\end{equation}  
are the classes represented by the exceptional divisor and fiber of the blowup  


\begin{equation}  
\mathbb{F}_{_1}\ \longrightarrow\ \mathbb{P}^{^2}  
\end{equation}  
respectively, then  

\begin{equation}  
n_{_{\beta_{_o}+kl}}q^{^k}\ =\ N^{^{K_{_{\mathbb{F}_{_1}}}}}_{_{0,0,kf+(k-1)e}}  
\end{equation}   
where the RHS denotes the local BPS invariants for the class  


\begin{equation}  
kf+(k-1)e\ \in\ H_{_2}\left(K_{_{\mathbb{F}_{_1}}};\mathbb{Z}\right).  
\end{equation}  

Direct calculation of the latter was performed by [Chiang, Klemm, Yau, Zaslow].  


The first explicit values read   

\begin{equation}  
\begin{aligned}   
n_{_{\beta_{_o}+l}}\ =\ &-2\ \ \ , \ \ \ n_{_{\beta_{_o}+2l}}\ =\ 5\ \ \ , \ \ \ n_{_{\beta_{_o}+3l}}\ = \ -32\\   
&n_{_{\beta_{_o}+4l}}\ = \ 286\ \ \ , \ \ \ n_{_{\beta_{_o}+5l}}\ =\ -3038\ \ \ , \ \ \ .\ .\ .\\  
\end{aligned}  
\end{equation}

Upon substituting them in the generating function, we get  


\begin{equation}  
1+\delta_{_o}(q)\ =\ 1-2q+5q^{^2}-32q^{^3}+286 q^{^4}-3038 q^{^5} +\ ... 
\end{equation}

When compared with the expression for $f(q)$, \eqref{eq:fq}, 

\begin{equation}  
f(q)\ = \ \left(\frac{\psi(t)}{t}\right)^{^{1/3}},       
\end{equation}    
it follows that the coefficients of $f(q)$ are exactly the virtual counts $n_{_{\beta_{_o}+kl}}$ of holomorphic disks.  

Note that one could also perform the inverse construction, namely starting from a conic bundle to construct a Lagrangian torus fibration, thereby proving the involutive property of the SYZ mirror construction.   


