\subsubsection{$\mathbb{F}_{_2}$}     


Take a family of smooth quadratic surfaces   


\begin{equation}  
\chi\ \subset\ \mathbb{CP}^{^3}\ \times\ \mathbb{C}   
\end{equation}  


\begin{equation}   
\chi\ \overset{def.}{=}\ \{x_{_0}x_{_1}\ =\ x_{_2}^{^2}-t^{^2}x_{_3}^{^2}\}.  
\end{equation}      


\begin{enumerate}  

\item   For $t\neq 0$

\begin{equation}  
X_{_t}\ =\ \left\{x_{_0}x_{_1}\ =\ (x_{_2}+tx_{_3})(x_{_2}-tx_{_3})\right\}\ \subset\ \mathbb{CP}^{^3}
\end{equation}  
is a smooth quadric, and can be identified with the image of the embedding of  

\begin{equation}  
\mathbb{CP}^{^1}\ \times\ \mathbb{CP}^{^1}.    
\end{equation}

\item  For $t= 0$     

\begin{equation}  
X_{_t}\ =\ \left\{x_{_0}x_{_1}\ =\ x_{_2}^{^2}\right\}\ \subset\ \mathbb{CP}^{^3}
\end{equation}  
is a cone with vertex at the point   

\begin{equation}  
(0:0:0:1)  
\end{equation}
where the 3-fold, $\chi$, presents as an ordinary double point singularity. Denote by   

\begin{equation}  
\pi:\ \chi^{^{\prime}}\ \longrightarrow\ \chi       
\end{equation}  
a small resolution. Composing it with the projection to $\mathbb{C}$, we obtain a family of surfaces $X_{_t}^{^{\prime}}$, such that 

\begin{equation}  
X_{_t}^{^{\prime}}\ \simeq\ X_{_t}
\end{equation}
for $t\neq 0$, while $X_{_o}^{^{\prime}}$ is the blowup of $X_{_o}$, namely 

\begin{equation}  
X_{_o}^{^{\prime}}\ \simeq\ \mathbb{F}_{_2}.  
\end{equation}    

\end{enumerate}   

Consider the family of anticanonical divisors  

\begin{equation}  
D_{_t}\ =\ \{x_{_0}=0\ , \ x_{_2}=tx_{_3}\}\ \cup\ \{x_{_1}=0\ ,\ x_{_2}=tx_{_3}\}\ \cup\ \{x_{_3}\ =\ -tx_{_2}\}\ \subset\ X_{_t},  
\end{equation}
and equip $X_{_t}$ with a holomorphic volume form $\Omega_{_t}$ with poles along $D_{_t}$. 

For $t=1$, the pair $(X_{_t}, D_{_t})$ corresponds to the toric anticanonical divisors in $\mathbb{CP}^{^1}\times CP^{^1}$, whereas for arbitrary $t$, the geometry of 

\begin{equation}  
(X_{_t}, D_{_t}, \Omega_{_t})  
\end{equation}  
closely resembles that of 

\begin{equation}  
X\ =\ \mathbb{C}^{^2}\ \ \ , \ \ \ \Omega\ =\ \frac{dx\wedge dy}{xy-\epsilon} \ \ \ , \ \ \  d=\{xy=\epsilon\} 
\end{equation}  
with corresponding torus fibration  

\begin{equation}  
T_{_{r,\lambda}}\ =\ \{(x,y)\ \in\ \mathbb{C}^{^2},\ |xy-\epsilon|=r,\mu_{_{S^{^1}}}(x,y)\ =\ \lambda\}  
\end{equation} 

The only difference being that $\mathbb{C}^{^2}$ is now compactified to $\mathbb{CP}^{^1}\times CP^{^1}$.  

$D_{_o}\ \subset\ X_{_o}$ is the toric anticanonical divisor consisting of the lines  



\begin{equation}  
x_{_o}=0\ \ \ ,\ \ \ x_{_1}=0\  \ \ ,\ \ \ x_{_3}=0.  
\end{equation}

\begin{equation}  
(X_{_t}, D_{_t}, \Omega_{_t})  
\end{equation}    
are preserved under the $S^{^1}$-action:  

\begin{equation}  
(x_{_o}:x_{_1}:x_{_2}:x_{_3})\ \mapsto\ \left(x_{_o}e^{^{i\theta}}:x_{_1}e^{^{-i\theta}}:x_{_2}:x_{_3}\right).  
\end{equation}

The $S^{^1}$-action lifts to the small resolution, and the lifted divisor  

\begin{equation}  
D_{_t}^{^{\prime}}\ =\ \pi^{^{-1}}\left(D_{_t}\right)\ \subset\ X_{_t}^{^{\prime}}    
\end{equation}
and holomorphic volume form  

\begin{equation}  
\Omega_{_t}^{^{\prime}}\ \pi^{^*}\Omega_{_t}  
\end{equation}
that are also $S^{^1}$-invariant.     


At $t=1$ and $t=0$, the anticanonical divisors are the toric ones for $\mathbb{F}_{_0}$ and $\mathbb{F}_{_2}$, respectively. Deforming away from these values, one partially smooths the toric anticanonical divisor, which, in the case of $\mathbb{F}_{_2}$ requires a simultaneous deformation of the complex structure because the exceptional curve is rigid. The deformation from $t=1$ to $t=0$ is depicted in Figure \ref{fig:f2}.    

\begin{figure}[ht!]  
\begin{center}  
\includegraphics[scale=0.45]{f2.pdf}  \ \ \ \ 
\includegraphics[scale=0.5]{f21.pdf}  
\caption{\small Deforming $\mathbb{F}_{_0}$ to $\mathbb{F}_{_2}$.}
\label{fig:f2}  
\end{center}  
\end{figure}

For $t=1$, the mirror superpotential is that of the mirror dual to a Fano variety (namely an $\mathbb{F}_{_0}$), and simply reads  

\begin{equation}  
{\cal W}\ =\ z_{_1}+z_{_2}+e^{^{-A}}z_{_1}^{^{-1}}+e^{^{-B}}z_{_2}^{^{-1}},  
\label{eq:toric}
\end{equation}   
with $A$ and $B$ denoting the symplectic area of the two $\mathbb{CP}^{^1}$-factors. In particular, the first two terms correspond to the disks contained in the affine chart, whereas the remaining terms correspond to the disks hitting the lines at $\infty$.     

Deforming to generic $t$  

\begin{equation}  
X_{_t}^{^{\prime}}\left\backslash D_{_t}^{^{\prime}} \right.\ \simeq\ \mathbb{C}^{^2}\left\backslash\left\{xy\  =\ \frac{1-t^{^2}}{1+t^{^2}}\right\}\right.    
\label{eq:deft}
\end{equation}   

Even though the K$\ddot{\text{a}}$hler form $\omega_{_t}^{^{\prime}}$ is not toric, the construction of an $S^{^1}$-invariant special Lagrangian fibration proceeds as in the Fano case with one modification. 

\begin{equation}  
T_{_{r,\lambda}}\ \subset\  \mathbb{CP}^{^1}\times\mathbb{CP}^{^1}  \
\end{equation}  
with $T_{_{r,\lambda}}$ now being a submanifold bounding additional families of Maslov index-2 holomorphic disks (intersecting the lines at $\infty$).   

From \eqref{eq:deft}, it follows that there are two main chambers  

 \begin{itemize}

 \item In the chamber  $r>\left|\frac{1-t^{^2}}{1+t^{^2}}\right|$, deforming $T_{_{r,\lambda}}$ to a product torus shows that it bounds 4 families of Maslov index-2 disks, and the superpotential is given by \eqref{eq:toric}.

 \item On the other hand, in the chamber  $r<\left|\frac{1-t^{^2}}{1+t^{^2}}\right|$, deforming $T_{_{r,\lambda}}$ to the Chekarov torus shows that it bounds 5 families of Maslov index-2 holomorphic disks. The superpotential now reads  

\begin{equation}  
{\cal W}\ = \ u+\frac{e^{^{-A}}}{uw}+\frac{e^{^{-B}}(1+w)}{u},   
\label{eq:nont}
\end{equation}  
where the first term comes from the disks passing through the conic $xy=\frac{1-t^{^2}}{1+t^{^2}}$ and avoiding all toric divisors, whereas the remaining terms correspond to sections intersecting exactly one of the two lines at $\infty$. There are four different possibilities, giving rise to one of the following families  

 \begin{equation}  
\left[\mathbb{CP}^{^1}\times\{\text{pt}\}\right]-\beta_{_o}-\alpha\ \ \ , \ \ \ \left[\mathbb{CP}^{^1}\times\{\text{pt}\}\right]-\beta_{_o}\ \ \ , \ \ \ \left[\{\text{pt}\}\times\mathbb{CP}^{^1}\right]-\beta_{_o}\ \ \ , \ \ \ \left[\{\text{pt}\}\times\mathbb{CP}^{^1}\right]-\beta_{_o}+\alpha,  
\end{equation}   
where $\beta_{_o}, \alpha$ are classes in $\pi_{_2}\left(\mathbb{C}^{^2}, T_{_{r,\lambda}}\right)$.   


 \end{itemize}



The two expressions \eqref{eq:toric} and \eqref{eq:nont} are related by the following change of variables  

\begin{equation}  
w\ \overset{def.}{=}\ \frac{z_{_1}}{z_{_2}}\ \ \ , \ \ \ u\ \overset{def.}{=}\ z_{_1}+z_{_2},      
\end{equation}    
thereby leading to the instanton-corrected gluing between the two chambers.



