\subsection{The G-construction}    


Given an abelian variety, $A$, of complex dimension $n$.   The multiplication morphism, \cite{9},   

\begin{equation}  
m:\ A\ \times\ A\ \longrightarrow\ A  
\end{equation}  
the multiplication morphism $\forall a\ \in \ A$, the translation morphism   

\begin{equation}  
T_{_a}\ \overset{def.}{=}\ m(.,a):\ A\ \longrightarrow\ A. 
\end{equation}   

Denoting by $\hat A$ the dual abelian variety, which is canonically isomorphic to Pic$^{^{0}}(A)$, there is a unique line bundle, $P$, (the Poincare' line bundle) on the product $A\times\hat A$ such that, for every point $\alpha\in \hat A$, the restriction $P_{_{\alpha}}$ on $A\times\{\alpha\}$ represents an element of Pic$^{^0}(A)$, and the restriction $P\bigg|_{_{\{0\}\times\hat A}}$ should be trivial. Notice that $A$ can be identified with $\hat{\hat A}$.    


Considering the projections  

\begin{equation}   
A\ \overset{p}{\longleftarrow}\ A\times \hat A\ \overset{q}{\longrightarrow}\ \hat A  
\end{equation}   
and the functor  

\begin{equation}  
\Phi_{_p}:\ D^{^b}(A)\ \longrightarrow\ D^{^b}\left(\hat A\right)  
\end{equation}    


\begin{equation}   
\Rightarrow\ \ \ \ \Phi_{_p}(.)\ =\ Rq_{_*}\left(P\otimes p^{^*}(.)\right).     
\end{equation}  

\medskip   

\medskip   

\underline{Proposition}   

\medskip   

\medskip   

Let $P$ be a Poincare' line bundle on $A\times\hat A$. Then, the functor  

\begin{equation}  
\Phi_{_p}:\ D^{^b}(A)\ \longrightarrow\ D^{^b}\left(\hat A\right)  
\end{equation}   
is an exact equivalence, and there is an isomorphism of functors  

\begin{equation}  
\Psi_{_p}\ \circ\ \Phi_{_p}\ \simeq\ \left(-1_{_A}\right)^{^*}[n],     
\end{equation}  
where $\left(-1_{_A}\right)$ denotes the inverse map on the group $A$. Let $x_{_1},...,x_{_{2n}}$ be a basis of $H^{^1}(A,\mathbb{Z})$. Let $l_{_1},...,l_{_{2n}}$ be the dual basis of $H^{^1}(\hat A,\mathbb{Z})$. Then, 


\begin{equation}  
p^{^*}(x_{_1}),...,p^{^*}(x_{_{2n}}), q^{^*}(l_{_1}),...,q^{^*}(l_{_{2n}})  
\end{equation}  
is the dual basis of $H^{^1}(A\times\hat A,\mathbb{Z})$.

\medskip   

\medskip   

\underline{Lemma}   

\medskip   

\medskip   

The first Chern class of the Poincare' line bundle $P$ on $A\times\hat A$ satisfies the equality  

\begin{equation} 
c_{_1}(P)\ =\ \sum_{_{i=1}}^{^{2n}}p^{^*}(x_{_i})\cup q^{^*}(l_{_i}).    
\end{equation}    

Then, consider the map  

\begin{equation}  
\phi_{_p}:\ H^{^{\bullet}}(A,\mathbb{Q})\ \longrightarrow\ H^{^{\bullet}}(\hat A, \mathbb{Q})   
\end{equation}    
(essentially the $\phi_{_{\cal E}}$'s previously defined.   

\medskip   

\medskip   

\underline{Lemma}   

\medskip   

\medskip   


For all $k$, the map $\phi_{_p}$ sends the $k^{^{th}}$-cohomology to the $(2n-k)^{^{th}}$-cohomology, and induces isomorphisms   

\begin{equation}  
H^{^k}(A, \mathbb{Z})\ \overset{\ \ \sim\ \ }\ H^{^{2n-k}}(\hat A, \mathbb{Q})   
\end{equation}    
under which the monomial     


\begin{equation}   
x_{_{i_{_1}}}\ \cup\ ...\ \cup\ x_{_{i_{_k}}}  
\end{equation}   
goes to   
\begin{equation}   
(-1)^{^{\epsilon}}l_{_{j_{_1}}}\ \cup\ ...\ \cup\ l_{_{j_{_{2n-k}}}},    
\end{equation}   
where 

\begin{equation}   
j_{_1}\ <\ ...\ <\ j_{_{2n-k}}        
\end{equation}
is the complement of 

\begin{equation}   
i_{_1}\ <\ ...\ <\ i_{_k}        
\end{equation}   
in the set  $(1,...,2n)$, and   


\begin{equation}   
\epsilon\ =\ \sum_{_t}j_{_t}.       
\end{equation}     

For any point $(a,\alpha)\ \in\ A\times\hat A$, one can introduce a functor from $D^{^b}(A)$ to itself, defined as follows  

\begin{equation}  
\Phi_{_{(a,\alpha)}}(.)\ \overset{def.}{=}\ T_{_a}^{^*}(.)\otimes p_{_{\alpha}}.  
\end{equation}    

$\Phi_{_{(a,\alpha)}}$ is represented by a sheaf  

\begin{equation}  
S_{_{(a,\alpha)}}\ =\ {\cal O}_{_{\Gamma_{_a}}}\otimes p_{_2}^{^*}\left(p_{_{\alpha}}\right)  
\end{equation}  
on $A\times A$, where $\Gamma_{_{\alpha}}$ is the graph of the automorphism  

\begin{equation}  
T_{_a}:\ A\ \longrightarrow\ A.     
\end{equation}    

The functor  $\Phi_{_{(a,\alpha)}}$ is an equivalence. An automorphism $T_{_a}$ acts identically on the cohomology group, and   

\begin{equation}  
\text{ch}\left(P_{_{\alpha}}\right)\ =\ 1,  
\end{equation}   
$\Phi_{_{(a,\alpha)}}$ belonging to the kernel of the homeomorphism $\rho$ defined earlier above.   

The collection of functors   

\begin{equation}  
\{\Phi_{_{(a,\alpha)}}\}  
\end{equation}  
can therefore be unified into a unique functor  

\begin{equation}  
\begin{aligned}    
&D^{^b}(A\times\hat A)\ \longrightarrow\ D^{^b}(A\times A)\\  
&\ \ \ \ \ \ {\cal O}_{_{(a,\alpha)}}\ \ \ \mapsto\ \ \ \ \ \ S_{_{(a,\alpha)}}.  
\end{aligned}  
\end{equation}    

Given  

\begin{equation}  
S_{_A}\ =\ \left(m\cdot p_{_{13}},P_{_4}\right)^{^*}{\cal O}_{_{\Delta}}\otimes p_{_{23}}P_{_4}  
\end{equation}    
one can define the functor 

\begin{equation}  
\Phi_{_{S_{_A}}}:\ D^{^b}(A\times \hat A)\ \longrightarrow\ D^{^b}(A\times A)  \end{equation}  
on the product   

\begin{equation}  
(A\times\hat A)\times (A\times A),    
\end{equation}  
where

\begin{equation}  
\left(m\cdot p_{_{13}},P_{_4}\right)  
\end{equation}  
is a morphism onto $A\times A$ that takes  

\begin{equation}  
\left(a_{_1},\alpha, a_{_3}, a_{_4}\right)
\end{equation}    
to   


\begin{equation}  
\left(m(a_{_1},a_{_3}), a_{_4}\right)  
\end{equation}  


$\Phi_{_{S_{_A}}}$ takes skyscraper sheaves ${\cal O}_{_{(\alpha,\alpha)}}$ to $S_{_{(a,\alpha)}}$. In particular, $\Phi_{_{S_{_A}}}$ can be thought of as a composition of two functors.  





\medskip   

\medskip   

\underline{Lemma}   

\medskip   

\medskip  

\begin{equation}  
\Phi_{_{S_{_A}}}:\ \simeq\ R_{_{\mu_{_A}}}\ \circ\ \Phi_{_{R_{_A}}} \end{equation}   
where 


\begin{equation}  
R_{_A}\ \overset{def.}{=}\ p_{_14}^{^*}{\cal O}_{_{\Delta}}\otimes p_{_{23}}^{^*}P\ \in\ D^{^b}\left((A\times\hat A)\times (A\times A)\right)  
\end{equation}    
and  

\begin{equation}    
\begin{aligned}
\mu_{_A}:\ &A\ \times\ A\ \longrightarrow\ A \   \times\ A \\ 
&(a_{_1}, a_{_2})\ \ \ \mapsto\ (a_{_1}, m(a_{_1},a_{_2})) 
\end{aligned}
\end{equation}


\begin{equation}  
\Phi_{_{R_{_A}}}:\  D^{^b}\left(A\times\hat A\right)\ \longrightarrow\ D^{^b}\left(A\times A \right)
\end{equation}     



\begin{equation}   
R_{_{\mu_{_A}}}:\ D^{^b}\left(A\times A\right)\ \longrightarrow\ D^{^b}\left(A\times A \right)
\end{equation}     


\medskip   

\medskip   

\underline{Lemma}   

\medskip   

\medskip    

$\Phi_{_{S_{_A}}}$ is an equivalence\footnote{This follows from the fact that $\Phi_{_{R_{_A}}}$ is an equivalence. $\mu_{_A}$ is an automorphism of $A\times A$, so too $R_{_{\mu_{_A}}}$.}.   

Let $A, B$ be two abelian varieties. Fix an equivalence  

\begin{equation}  
\Phi_{_{\cal E}}:\ D^{^b}(A)\ \xrightarrow{\ \ \sim\  \ }\ D^{^b}(B).
\end{equation}   

Consider the functor   

\begin{equation}  
\Phi_{_{S_{_B}}}\text{Ad}_{_{\cal E}}\Phi_{_{S_{_A}}}\ : \ D^{^b}(A\times\hat A)\ \longrightarrow\ D^{^b}(B\times\hat B)  
\end{equation}   

To describe an object in $\Phi_{_{S_{_B}}}\text{Ad}_{_{\cal E}}\Phi_{_{S_{_A}}}$, say ${\cal J}({\cal E})$. There exists a commutative diagram  


\begin{equation}   
\begin{aligned}  
&D^{^b}(A\times \hat A)\ \ \ \ \ \ \ \ \xrightarrow{\ \ \Phi_{_{S_{_A}}}\ \ }\ \ \ \ \ \ D^{^b}(A\times  A) \\ 
&\\
&\Phi_{_{{\cal J}({\cal E})}}\ \downarrow\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \  \ \ \ \ \  \ \ \ \downarrow\text{Ad}_{_{\cal E}}\ \\  
&D^{^b}(B\times \hat B)\ \ \ \ \ \ \ \ \ \xrightarrow{\Phi_{_{S_{_B}}}}\ \ \ \ \  \ \ \ \ \  D^{^b}(B\times  B)  
\end{aligned}
\end{equation}

\medskip   

\medskip   

\underline{Theorem}   

\medskip   

\medskip    

There is a group isomorphism   

\begin{equation}    
f_{_{\cal E}}:\ A\ \times\ \hat A\ \longrightarrow\ B\ \times\ \hat B  
\end{equation}  
and the line bundle $L_{_{\cal E}}$ on $A\times\hat A$ such that ${\cal J}({\cal E})$ is isomorphic to $i_{_*}(L_{_\epsilon})$, where $i$ denotes the embedding of $A\times\hat A$ in   


\begin{equation}  
(A\times\hat A)\times (B\times \hat B)  
\end{equation}  
as the graph $\Gamma(f_{_{\cal E}})$ of the isomorphism $f_{_{\cal E}}$.   


\medskip   

\medskip   

\underline{Corollary}   

\medskip   

\medskip     


An isomorphism $f_{_{\cal E}}$ takes a point $(a,\alpha)\in A\times\ \hat A$ to a point $(b,\beta)| \in\ B\ \times\ \hat B$, iff the equivalences  

\begin{equation}  
\Phi_{_{(a,\alpha)}}:\ D^{^b}(A)\ \xrightarrow{\ \ \sim\ \ }\ D^{^b}(A)  
\end{equation}  

\begin{equation}  
\Phi_{_{(b,\beta)}}:\ D^{^b}(B)\ \xrightarrow{\ \ \sim\ \ }\ D^{^b}(B)  
\end{equation}   
are connected by the relation  


\begin{equation}   
\Phi_{_{(b,\beta)}}\ \simeq\ \Phi_{_{{\cal E}}}\Phi_{_{(a,\alpha)}}\Phi_{_{{\cal E}}}^{^{-1}}  
\end{equation}  



\medskip   

\medskip   

\underline{Proposition}   

\medskip   

\medskip 

Let $B\simeq A$. The correspondence  

\begin{equation}  
\Phi_{_{\cal E}}\ \mapsto\ f_{_{\cal E}}  
\end{equation}    
induces a group homomorphism  

\begin{equation}  
\gamma_{_A}:\ \text{Auteq}\left(D^{^b}(A)\right)\ \longrightarrow\ \text{Aut}(A\times \hat A)  
\end{equation}


\subsubsection{The Mukai-Polishchuk group and the Spinorial group }    


[Mukai] defined a discrete group $U(A\times\hat A)$, as the group of autoequivalences $\text{Auteq}(D^{^b}(A))$ an abelian variety $A$.  [Polishchuk] considered the same group, SL$_{_2}(A)$, and proved that it acts naturally on $D^{^b}(A)$ up to the shift functor. For the case of the complex tori, $A$, the Mukai-Polishchuk group, $U(A)$, reads    


\begin{equation}  
U(A)\ \overset{def.}{=}\ \left\{g=\left(\begin{matrix} &a\ \ b\\ 
&c\ \ d\\ \end{matrix}\right)\ \in\ \left(\begin{matrix} &\text{End}(A)\ \ \text{Hom}(\hat A,A)\\ 
&\text{Hom}(\hat A,A)\ \ \text{End}(\hat A)\\ \end{matrix}\ \right)\bigg| \ g^{^{-1}}\ =\ \left(\begin{matrix} &a\ \ b\\ 
&c\ \ d\\ \end{matrix}\ \right)\right\}  
\end{equation}  
where   

\begin{equation}  
U(A)\ \subseteq\ \text{GL}\left(\Gamma_{_A}\oplus\hat\Gamma_{_A}\right). 
\end{equation}   

Consider the canonical bilinear form $Q$ on   

\begin{equation} 
\Lambda\ \overset{def.}{=}\ \Gamma_{_A}\oplus\Gamma_{_{\hat A}}.  
\end{equation}


Then, we can equivalently describe the group $U(A)$ as follows   

\begin{equation}   
U(A)\ =\ O(\Lambda, Q)\ \cap\ \text{Aut}(A\times\hat A)\ =\ SO(\Lambda, Q)\ \cap\ \text{Aut}(A\times\hat A)   
\end{equation}   
of subgroups of GL$(\Lambda)$.


\medskip   

\medskip   

\underline{Proposition}   

\medskip   

\medskip   

The image of the homomorphism 

\begin{equation}  
\gamma_{_A}:\ \text{Auteq}\left(D^{^b}(A)\right)\ \longrightarrow\ \text{Aut}(A\times \hat A)  
\end{equation}  
coincides with the Mukai-Polishchuk group $U(A)$. Moreover, there is an exact sequence of groups   

\begin{equation}    
0\ \longrightarrow\ \mathbb{Z}\times A\hat A\ \longrightarrow\ \text{Auteq}\left(D^{^b}(A)\right)\ \longrightarrow\ U(A)\ \longrightarrow\ 1.  
\end{equation}

The correspondence   

\begin{equation}  
\Phi_{_{\cal E}}\ \mapsto\ \phi_{_{\cal E}}  
\end{equation}  
induces a homomorphism   

\begin{equation}   
\rho_{_A}:\ \text{Auteq}\left(D^{^b}(A)\right)\ \longrightarrow\ \text{GL}(H^{^{\bullet}}(A,\mathbb{Q}))  
\end{equation}   
preserving the integral cohomology lattice.  


\medskip   

\medskip   

\underline{Proposition}   

\medskip   

\medskip    

For any equivalence  

\begin{equation}  
\Phi_{_{\cal E}}:\ D^{^b}(A)\  \xrightarrow{\ \ \sim\ \ }\ D^{^b}(B)  
\end{equation}  
the linear map $\phi_{_{\cal E}}$ preserves the integral cohomology, i.e.   

\begin{equation}    
\phi_{_{\cal E}}(H^{^{\bullet}}(A,\mathbb{Z}))\ =\ H^{^{\bullet}}(B,\mathbb{Z})  
\end{equation}  

\medskip   

\medskip   

\underline{Lemma}   

\medskip   

\medskip    

For every line bundle, $L$, on an abelian variety, $A$, the Chern character ch$(L)$ is integral, i.e. it belongs to $H^{^{\bullet}}(A,\mathbb{Q})$.   


The, the correspondence  

\begin{equation}  
\Phi_{_{\cal E}}\ \mapsto\ \phi_{_{\cal E}} 
\end{equation}  
gives the homomorphism  


\begin{equation}
    \rho_{_A}:\ \text{Auteq}(D^{^b}(A))\ \longrightarrow\ \text{GL}(H^{^{\bullet}}(A,\mathbb{Z})).   
\end{equation}  

The subgroup of $\text{GL}(H^{^{\bullet}}(A,\mathbb{Z}))  $ that is the image of $\rho_{_A}$ will bereferred to as the spinor group of $A$, Spin$(A)$. This follows from the fact that the Clifford algebra $Cl(\Lambda, Q)$ and the algebra homomorphism   

\begin{equation}  
\text{cor}_{_A}:\ Cl(\Lambda, Q)\ \longrightarrow\ (H^{^{\bullet}}(A,\mathbb{Z}))\ \simeq\ (H^{^{\bullet}}(A\times A,\mathbb{Z}).    
\end{equation}    

Define on $\Lambda\ \subset\ Cl(\Lambda, Q)$ by   


\begin{equation}  
\text{cor}_{_A}((l,x))(.)\ =\ l(.)+x\cup (.)    
\end{equation}   


\begin{equation}  
(l,x)\ \in\ \Gamma_{_A}\oplus\Gamma_{_A}^{^*}\ =\ \Lambda   
\end{equation}  
where $l(.)$ denotes the convolution with $l$  

\begin{equation}  
l(\alpha)\ =\ \sum(-1)^{^{i-1}}l(x_{_i})x_{_1}\cup...\cup x_{_{i-1}}\cup x_{_{i+1}}\cup... \cup x_{_k}
\end{equation}   
whereas cor$_{_A}$ sends $Cl^{^+}(\Lambda,Q)$ to $H^{^{ev}}(A\times A,\mathbb{Z})$ and induces the action of the group Spin$(\Lambda, Q)$ on the cohomology lattice $H^{^{\bullet}}(A, \mathbb{Z})$, implying that   

\begin{equation}  
\text{Spin}(\Lambda, Q)\ \subseteq\ \text{GL}(H^{^{\bullet}}(A, \mathbb{Z}))  
\end{equation}  
w.r.t. cor$_{_A}$.


\subsection{Mirror pair construction}    



Given an algebraic pair $(A, \omega_{_A})$, we can use the following two Lemmas:  

\medskip  

\medskip 


\underline{Lemma 1}     

\medskip  

\medskip 
Let $(A,\omega_{_A})$ be an algebraic pair, and $B$ a complex torus. Let   


\begin{equation}  
\alpha:\ \Gamma_{_A}\ \oplus\ \Gamma_{_{\hat A}}\ \xrightarrow{\ \ \sim\ \ }\ \Gamma_{_B}\ \oplus\ \Gamma_{_{\hat B}}  
\end{equation}  
be an isomorphism which identifies the forms $Q_{_A}$ and $Q_{_B}$, and   

\begin{equation}  
\alpha_{_{\mathbb{R}}}\circ I_{_{\omega_{_A}}}\ =\ J_{_{B\times\hat B}}\ \circ \alpha_{_{\mathbb{R}}}  
\end{equation}   
implying there exists $\omega_{_B}\ \in\ C_{_B}$ such that   

\begin{equation}  
\alpha_{_{\mathbb{R}}}\ \circ I_{_{\omega_{_A}}}\ =\ J_{_{B\times\hat B}}\ \circ\ \alpha_{_{\mathbb{R}}}  
\end{equation}  

$\alpha$ therefore established the mirror symmetry of algebraic pairs  $(A,\omega_{_A}), (B,\omega_{_B})$.  

\medskip  

\medskip 


\underline{Lemma 2}     

\medskip  

\medskip 

Let    

\begin{equation}  
\Lambda\ =\ \Gamma\ \oplus\ \Gamma^{^*}  
\end{equation}  
be a lattice with canonical symmetric bilinear form $Q$. Let there be an isotropic decomposition   

\begin{equation}  
\Lambda\ = \ \Lambda_{_1}\ \oplus\ \Lambda_{_2}.     
\end{equation}  

Suppose $I\ \in\ \text{GL}\left(\Lambda_{_{\mathbb{R}}}\right)$ is a complex structure on $\Lambda_{_{\mathbb{R}}}$, i.e. $I^{^2}=-1$, such that  


\begin{itemize}  

\item  $I(\Lambda_{_i},\mathbb{R})\ = \ \Lambda_{_{i,\mathbb{R}}}, i=1,2 $ 

\item  $I\in O(\Lambda_{_{\mathbb{R}}}, Q_{_{\mathbb{R}}})$   

\end{itemize}   

Then, the complex tori  

\begin{equation}  
B_{_1}\ \overset{def.}{=}\ \left(\Lambda_{_{1,\mathbb{R}}}/\Lambda_{_1}, I_{_1}\right)  \ \ \ \ ,\ \ \ \ B_{_2}\ \overset{def.}{=}\ \left(\Lambda_{_{2,\mathbb{R}}}/\Lambda_{_2}, I_{_2}\right)  
\end{equation}   
where $I_{_i}$ denotes the restriction of $I$ on $\Lambda_{_{i,\mathbb{R}}}$, and are dual to each other, namely  

\begin{equation}  
B_{_2}\ \simeq\ \hat{B}_{_1}.  
\end{equation}   

Putting Lemma 1 and 2 together, 

\begin{equation}  
\Lambda\ =\ \Gamma_{_A}\ \oplus\ \Gamma_{_{\hat A}} 
\end{equation}  
it suffices to find a $Q_{_A}$-isotropic decomposition   

\begin{equation}  
\Lambda\ =\ \Lambda_{_1}\ \oplus\ \Lambda_{_2}  
\end{equation}  
such that $\Lambda_{_{1,\mathbb{R}}}, \Lambda_{_{2,\mathbb{R}}}$ are preserved by $I_{_{\omega_{_A}}}$. Then, by Lemma 2, the tori  

\begin{equation}  
B\ \overset{def.}{=}\ \left(\Lambda_{_{1,\mathbb{R}}}/\Lambda_{_1}, I_{_{\omega_{_A}}}\right)  \ \ \ \ ,\ \ \ \ B_{_2}\ \overset{def.}{=}\ \left(\Lambda_{_{2,\mathbb{R}}}/\Lambda_{_2}, I_{_{\omega_{_A}}}\right)  
\end{equation}   
are dual to each other.   

Moreover,  


\begin{equation}  
\alpha\ =\ \text{id}:\ \Gamma_{_A}\ \oplus\ \Gamma_{_{\hat A}}\ \xrightarrow{\ \ \sim\ \ }\ \Gamma_{_B}\ \oplus\ \Gamma_{_{\hat B}},    
\end{equation}  
($\Gamma_{_B}=\Lambda_{_1}, \Gamma_{_{\hat B}}=\Lambda_{_2}$), identifying the forms $Q_{_A}$ and $Q_{_B}$, thereby implying\footnote{By means of Lemma 1.} that there exists $\omega_{_B}\subset C_{_B}$ such that $(A,\omega_{_A})$ and $(B,\omega_{_B})$ are mirror pairs.   

Note that not every pair $(A,\omega_{_A})$ admits a mirror pair. In particular, there might not be a mirror dual if the group $U_{_{A,\mathbb{Q}}}$ is too big and $\omega_{_A}\ \in\ C_{_A}$ is too general.  

\medskip  

\medskip 




\underline{The G-construction}     

\medskip  

\medskip   

A weak pair $A_{_{J(q),\omega}})$ is obtained by G-construction if the complex torus $A_{_{J(q)}}$ is  

\begin{equation}  
\left(\Gamma_{_{\mathbb{R}}}/\Gamma, J(q)\right)  
\end{equation}  
where $\Gamma$ satisfies a set of conditions, specified in what follows,   

\begin{equation}  
q\ \in\ S(C)\ \otimes\ C  
\end{equation}   
and the form of $omega$ belongs to  

\begin{equation}  
i_{_S}(S(D))\ \otimes\ \mathbb{C}.    
\end{equation}     

A weak pair $(A,\omega_{_A})$ is well-becoming iff it can be obtained by the G-construction. 

\underline{Claim:} Any well-becoming pair has a mirror symmetric pair.  

Properties that $\Gamma$ should satisfy for a weak pair to be obtained by G-construction:  


\begin{enumerate}  

\item  $\Gamma$ is a lattice of even dimension, i.e.  

\begin{equation}  
\Gamma\ =\ \mathbb{Z}^{^{2n}}  
\end{equation}  
is an abelian group.  

\item  $\Gamma$ is a faithful module, namely 

\begin{equation}  
R\ \longrightarrow\ \text{End}_{_{\mathbb{Z}}}(\Gamma)   
\end{equation}
is an embedding.

\item  The order 

\begin{equation}  
O(\Gamma)\ =\ \{a\in D| a(\Gamma)\subset \Gamma\}  
\end{equation}  
coincides with $R$.

\item  $\Gamma$ is a direct sum of $R$-modules $\Gamma_{-1}$ and $\Gamma_{_2}$ such that there is an isomorphism  

\begin{equation}  
e:\ M_{_1}\ \xrightarrow{\sim}\ M_{-2}  
\end{equation}   
of D-modules  

\begin{equation}  
M_{_i}\ = \ \Gamma_{_i}\underset{\mathbb{Z}}{\otimes}\mathbb{Q}   \ \ \ \ ,\ \ \ \ i=1,2.
\end{equation}

\item  There is a rational symmetric form   

\begin{equation}  
g:\ M\times M\ \longrightarrow\ \mathbb{Q}  
\end{equation}  
such that the algebra $D$ is invariant w.r.t. an anti-involution, $\sim$, on End$_{_{\mathbb{Q}}}(M)$, defined as follows  

\begin{equation}  
\tilde \alpha\ =\ g^{^{-1}}\alpha^{^t}g.  
\end{equation}

\end{enumerate}  



Let $\Gamma\simeq \mathbb{Z}^{^{2n}}$ be a lattice,  

\begin{equation}  
V\ =\ \Gamma\ \otimes\ \mathbb{R}\ \simeq\ \mathbb{R}^{^{2n}}  
\end{equation} 
and complex structure 

\begin{equation}  
J\ \in\ \text{End}(V)\ \ \ , \ \ \ J^{^2}= -1.  
\end{equation}  

This way, we obtain an n-dimensional complex torus  

\begin{equation}  
A\ =\ \left(V_{_A}/\Gamma_{_A}, J_{_A}\right).  
\end{equation}  

Consider the canonical isomorphisms     

\begin{equation}  
\Gamma_{_A}\ =\ H_{_1}(A,\mathbb{Z})\ \ \ , \ \ \ V_{_A}\ =\ H_{_1}(A,\mathbb{R}).      
\end{equation}    
Given another complex torus   

\begin{equation}  
B\ =\ \left(V_{_B}/\Gamma_{_B}, J_{_B}\right),       
\end{equation}    
the group Hom$(A,B)$ consists of homorphisms 

\begin{equation}  
f:\ \Gamma_{_A}\ \longrightarrow\ \Gamma_{_B}  
\end{equation}  
such that   

\begin{equation}  
J_{_B}\cdot f_{_{\mathbb{R}}}\ =\ f_{_{\mathbb{R}}}\cdot J_{_A}:\ V_{_A}\ \longrightarrow\ V_{_B}  
\end{equation}   

\begin{equation}  
\Rightarrow\ \ \ \text{Hom}(A,B)\ \subset\ \text{Hom}\left(\Gamma_{_A},\Gamma_{_B}\right).  
\end{equation}







\subsection{The Hodge group, Hdg$_{_{A,\mathbb{Q}}}$}    

Let $A=(V/\Gamma, J)$ be a complex torus. Consider the homomorphism of algebraic $\mathbb{R}$-groups  

\begin{equation}  
h_{_A}:\ S^{^1}\ \longrightarrow\ \text{GL}(V)\ \ \ \ ,\ \ \ \ h_{_A}\left(e^{^{i\theta}}\right)\ =\ \cos\theta \mathbb{1}+\sin\theta J  
\end{equation}  
such that   

\begin{equation}  
h_{_A}\left(e^{^{i\pi/2}}\right)\ =\ J.         
\end{equation}     

This defines a representation of $S^{^1}$ on the exterior algebra $\bigwedge H_{_1}(A,\mathbb{R})$, which is, in turn, inherited by the (co)-homology of $A$. Decomposing the representation of $S^{^1}$ on the k$^{^{th}}$-cohomology space w.r.t. the characteristics of $S^{^1}$  

\begin{equation}  
\begin{aligned}
&S^{^1}\ \longrightarrow\ \mathbb{C}^{^*}\\
&e^{^{i\theta}}\ \mapsto\ e^{^{i(q-p)\theta}}\ \ \ \ \ \ , \ \ \ \ \ \ p+q=k
\end{aligned} 
\end{equation}  
the Hodge decomposition reads  

\begin{equation}  
H^{^k}(A,\mathbb{C})\ =\ \bigoplus_{_{p+q=k}}H^{^{p,q}}(A,\mathbb{C}).  
\end{equation}  

The Hodge group (a.k.a. the special Mumford-Tate group), Hdg$_{_{A,\mathbb{Q}}}$ of $A$ is defined as a minimal algebraic $\mathbb{Q}$-subgroup $G$ of GL$(H_{_1}(A,\mathbb{Q}))$, such that   

\begin{equation}  
h_{_A}\left(S^{^1}\right)\ \subset\ G(\mathbb{R}).  
\end{equation}

The group Hdg$_{_{A,\mathbb{Q}}}$ acts naturally on $H_{_k}(A,\mathbb{Q})$, and trivially on $H^{^{p,p}}(A,\mathbb{Q})$.  

Considering the dual torus, $\hat A$,   

\begin{equation}  
\text{Hdg}_{_{A,\mathbb{Q}}} \ =\ \text{Hdg}_{_{\hat A,\mathbb{Q}}} \ = \ \text{Hdg}_{_{A\times \hat A,\mathbb{Q}}}   
\end{equation}

\subsection{Comparison with Kontsevich and SYZ}    


\subsubsection{Comparison with Kontsevich}    

Assume that the algebraic pairs $\left(A,\omega_{_A}\right)$ and $\left(B,\omega_{_B}\right)$ are mirror symmetric. Let  

\begin{equation}  
\omega_{_A}\ =\ \eta_{_1}+i\eta_{_2}\ \in\ C_{_A}  
\end{equation}  

Then, $\eta_{_2}$ is a K$\ddot{\text{a}}$hler form. The Hodge group $\text{Hdg}_{_{\hat A,\mathbb{Q}}}$ acts on $H_{_1}(A)$ preserving the form $\eta_{_2}$.   

\begin{equation}  
\text{Hdg}_{_A}(\mathbb{Z}) \ \overset{def.}{=}\ \left\{g\in \text{Hdg}_{_{A,\mathbb{Q}}}\bigg|\ g\left(\Lambda_{_A}\right)\ \subset\ \Lambda_{_A}\right\}
\end{equation}  
acting by symplectomorphisms on the symplectic manifold $\left(A,\eta_{_2}\right)$, implying  

\begin{equation}  
\text{Hdg}_{_{A,\mathbb{Q}}}\ \subset\ \text{Auteq} F\left(A,\eta_{_2}\right).     
\end{equation}    

But    


\begin{equation}  
\text{Hdg}_{_A}(\mathbb{Z})\ \subset\ U(B),     
\end{equation}    
with $U(B)$ denoting the group encoding the essential part of Auteq$D^{^b}(B)$, implying the original categorical equivalence by Kontsevich 

\begin{equation}  
F\left(A,\eta_{_2}\right)\ \simeq\ D^{^b}(B)  
\end{equation}  
cannot be recovered.

\subsubsection{Comparison with SYZ}  

Assume that the pair $\left(A, \omega_{_A}\right)$ is obtained by the $G$-construction. Then, there is a real subtorus  

\begin{equation}  
T\ \subset\ A\times B \ \ \ \ \ , \ \ \ \ \ n\ =\ \text{dim}_{_{\mathbb{C}}}A\ = \  \text{dim}_{_{\mathbb{C}}}B 
\end{equation}   
of dimension $3n$, such that:   

\begin{enumerate}  

\item  The fibers of the projection of $T$ onto $B$ are special Lagrangian subtori of $A$ of dimension $n$.  

\item  The existence of such a correspondence is part of the geometric mirror symmetry by [Morrison].   

\item  There is a natural complex line bundle, $L$ on $T$ such that its Chern class, $c_{_1}(L)$ considered as an element in  

\begin{equation}   
H^{^{\bullet}}(A\times B)\ \simeq\ \text{Hom}\left(H^{^{\bullet}}(A), H^{^{\bullet}}(B)\right)  
\end{equation}
is the aforementioned isomorphism    



\begin{equation}  
\beta:\ H^{^1}(A,\mathbb{Z})\ \xrightarrow{\ \ \sim\ \ }\ H^{^0}(B,\mathbb{Z})\oplus H^{^2}(B,\mathbb{Z})   
\end{equation}   

\begin{equation}  
\beta:\ H^{^0}(A,\mathbb{Z})\oplus H^{^2}(A,\mathbb{Z})   \ \xrightarrow{\ \ \sim\ \ }\ H^{^1}(B,\mathbb{Z}).
\end{equation}

\end{enumerate}  



\section{Comparison of mirror functors}   

Two different kinds of HMS for the elliptic curve, \cite{10}:  

\begin{enumerate}  


\item  Categorical MS of POlishchuk-Zaslow, comparing $D^{^b}\text{Coh}(X)$ and $D^{^b}F\left(T^{^2}\right)$, with $E$ denoting the elliptic curve and $T^{^2}$ the symplectic torus, respectively.  

\item  Cho-Hong-Lau compared the symplectic torus $T^{^2}$ (with $\mathbb{Z}/3$-symmetry), and its $\mathbb{Z}/3$-quotient orbifold, $\mathbb{P}_{_{3,3,3}}^{^1}$. The immersed Lagrangian in the orbifold, a.k.a. the Seidel Lagrangian, defines a LG mirror $\left(\Lambda^{^3},{\cal W}\right)$ with an $A_{_{\infty}}$-functor from the Fukaya category of $\mathbb{P}_{_{3,3,3}}^{^1}$ to thedg-category of Matrix Factorisations.  

\end{enumerate}  

To recover MS for the original symplectic torus, $T^{^2}$, one needs to take the $\mathbb{Z}$-graded version of this functor from the graded Fukaya category of the $T^{^2}$ to the graded MF of MF$\mathbb{Z}({\cal W})$, implying there are 2 different ways of constructing the B-model of HMS of elliptic curves, namely as $D^{^b}$ and as a MF.  

BY Orlov's Theorem, these two categories are equivalent. SPecifically, if ${\cal W}$ is a (quasi)-homogeneous polynomial defining a smooth projective CY hypersurface $X$, then, 

\begin{equation}  
D^{^b}\text{Coh}(X)\ \simeq\ \text{HMF}_{_{\mathbb{Z}}}({\cal W})  
\end{equation}  
also referred to as the LG/CY correspondence.  

We now turn to explaining how to relate these exact functors between triangulated categories to each other.   

\underline{Theorem} [Sangwook Lee]     

There is a commutative diagram of exact functors  

\begin{equation}  
\begin{aligned}
&D^{^{\pi}}F\left(T^{^2}\right)\ \xrightarrow{S_{_i}}\ D^{^{\pi}}F\left(T^{^2}\right)\\  
&\Phi\ \downarrow\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \downarrow\ {\cal LM}^{^{\mathbb{L}}}\\
&D^{^b}\text{Coh}(X)\  \xrightarrow{{\cal G}_{_i}}\ \text{HMF}_{_{\mathbb{Z}}}({\cal W})  
\end{aligned}  
\end{equation}
where $\Phi$ is the mirror functor, and    

\begin{equation}  
S_{_i}\ = \ [-j]\circ\ \tau^{^d}\circ t_{_{(0,\frac{1}{2})}}\circ\left(\begin{matrix}  &1\ \ 0\\
&-3i+2\ \ 1\\ \end{matrix} \right)   
\end{equation}  
where   

\begin{equation}   
j=\lfloor-\frac{i}{3}\rfloor\ \ \ ,  \ \ \ d=-i-3j,   
\end{equation}   
$\tau$ denotes a rotation by $-\frac{2\pi}{3}$, whereas $t_{_{(0,\frac{1}{2})}}$ denotes parallel transport by $\left(0,\frac{1}{2}\right)$.   

${\cal LM}^{^\mathbb{L}}$ requires the choice of a character  

\begin{equation}  
\gamma:\ \mathbb{Z}/3\ \longrightarrow\ U(1)  
\end{equation}  

Varying the choice of $\gamma$, the functors $S_{_i}$ may also vary. The commuting diagram aboveassumes a choice has been made. Essentially, this Theorem states that two HMSs are equivalent after suitable geometric transformation $S_{_i}$ and shift.   


\subsection{Graded Matrix Factorisation}  


Recap from the case of $\mathbb{CP}^{^1}$.. Let   

\begin{equation}  
R\ =\ \Lambda\left[x_{_o},...,x_{_n}\right]  
\end{equation}  
be a graded ring with   

\begin{equation}  
\text{deg}(x_{_i})\ = \ d_{_i}.  
\end{equation}    
Let ${\cal W}\ \in\ R$ be a (quasi)-homogeneous polynomial of degree $d$. MF$_{_{\mathbb{Z}}}({\cal W})$ is a dg-category whose object $(P,d_{_P})$ is represented as a pair of global  morphisms  

\begin{equation}  
p_{_o}:\ P_{_0}\ \longrightarrow\ P_{_1}  
\ \ \ \ \ \ 
p_{_1}:\ P_{_1}\ \longrightarrow\ P_{_o}(d),  
\end{equation}  
with $P_{_0,}P_{_1}$ graded free $R$-modules, and  

\begin{equation}   
\begin{aligned}
&p_{_0}(d)\circ p_{_1}\ =\ {\cal W}\circ\text{id}\ :\ P_{_1}\ \longrightarrow\ P_{_1}(d)   \\  
&p_{_1}\circ p_{_0}\ =\ {\cal W}\ \circ\ \text{id}\ :\ P_{_0}\ \longrightarrow\ P_{_0}(d).     
\end{aligned}  
\end{equation}   


Equivalently, one such object can also be expressed as a quasi-periodic $\infty$-sequence:  

\begin{equation}  
K^{^{\bullet}}:...\ \longrightarrow\ K^{^i}\ \xrightarrow{k^{^i}}\ K^{^{i+1}}\ \xrightarrow{k^{^{i+1}}}\ K^{^{i+2}}\ ...   
\end{equation}   
where  

\begin{equation}  
K^{^{2i+1}}\ =\ P_{_1}(i\cdot d)\ \ , \ \ K^{^{2i}}\ =\ P_{_0}(i\cdot d)  
\end{equation}   

\begin{equation}  
k^{^{2i}}\ =\ p_{_0}(i\cdot d)\ \ , \ \ k^{^{2i+1}}\ =\ p_{_1}(i\cdot d).  
\end{equation}  

Then,   


\begin{equation}   
\text{Hom}_{_{\text{MF}_{_{\mathbb{Z}(\cal W)}}}}^{^i}\left(K^{^{\bullet}},L^{^{\bullet}}\right)\ \overset{def.}{=}\ \left\{f^{^{\bullet}}: K^{^{\bullet}}\ \longrightarrow\ L^{^{\bullet+j}}, \text{graded}\  \ | f^{^{i+2}}\ = \ f^{^i}(d)\right\}  
\end{equation}  
and

\begin{equation}   
\text{d}:\ \text{Hom}_{_{\text{MF}_{_{\mathbb{Z}(\cal W)}}}}^{^j}\left(K^{^{\bullet}},L^{^{\bullet}}\right)\ \longrightarrow\ \text{Hom}_{_{\text{MF}_{_{\mathbb{Z}(\cal W)}}}}^{^{j+1}}\left(K^{^{\bullet}},L^{^{\bullet}}\right)  
\end{equation}  
is defined by    

\begin{equation}   
(d(f^{^{\bullet}}))^{^i}\ \equiv\ l^{^{i+j}}\circ f^{^i}+(-1)^{^j}f^{^{i+1}}\circ k^{^i}  
\end{equation}   
where   


\begin{equation}  
l^{^n}:\ L^{^n} \ \longrightarrow\ L^{^{n+1}}.  
\end{equation}  

Given a MF, $K^{^{\bullet}}$, it is natural to define the shift, $K^{^{\bullet}}[1]$ such that  

\begin{equation}  
K^{^{\bullet}}[1]^{^i}\ =\ K^{^{\bullet\  i+1}} \ \ \ \ \ \ \ \ \ \text{and}\ \ \ \ \ \ \ \ \   k^{^{\bullet}}[1]^{^i}\ =\ -k^{^{\bullet\  i+1}}.   
\end{equation}    

Given a dg-category, ${\cal C}$, its cohomology category, $H^{^0}({\cal C})$, is defined by the same objects as those of ${\cal C}$, and morphism spaces are the 0$^{th}$-cohomologies of  

\begin{equation}  
\text{d}:\ \text{Hom}^{^j}\ \longrightarrow\ \text{Hom}^{^{j+1}}.  
\end{equation}   


\underline{Proposition}  

The cohomology category $H^{^0}\left(\text{MF}_{_{\mathbb{Z}}}({\cal W})\right)$ is a triangulated category with exact triangles    


\begin{equation}   
K^{^{\bullet}}\ \xrightarrow{f}\ L^{^{\bullet}}\ \longrightarrow\ C^{^{\bullet}}(f)\ \longrightarrow\ K^{^{\bullet}}[1],  
\end{equation}  
where the mapping cone of $f$ is defiend as follows  

\begin{equation}  
C^{^{\bullet}}(f):\ ...\  \longrightarrow\ L^{^i}\oplus K^{^{i+1}}\ \xrightarrow{c^{^i}}\ L^{^{i+1}}\oplus K^{^{i+2}}\\ \xrightarrow{c^{^{i+1}}}\ L^{^{i+2}}\oplus K^{^{i+3}}   
\end{equation}  
such that   

\begin{equation}   
c^{^i}\ = \ \left(\begin{matrix} &l^{^i}\ \ \ \ \ \ f^{^{i+1}}\\ &0\ \ -k^{^{i+1}}\end{matrix}\right).      
\end{equation}    


The category of graded MFs of ${\cal W}$ is tehreforedefiend as follows 

\begin{equation}  
\text{HMF}_{_{\mathbb{Z}}}({\cal W})\ \overset{def.}{=}\ H^{^0}\left(\text{MF}_{_{\mathbb{Z}}}({\cal W})\right).  
\end{equation}  



Take $A=R/{\cal W}$. Given that ${\cal W}$ is homogeneous, then $A$ is a graded ring. Then, the category gr-$A$ of finitely-generated graded $A$-modules is an abelian category. Defining Perf$-A$ as the full subcategory of chain complexes of $A$-modules, then  

\underline{Lemma}  


\begin{equation}    
\text{HMF}_{_{\mathbb{Z}}}({\cal W})\ \simeq\  D_{_{sg}}^{^{gr}}(A) \ \simeq\ D^{^b}(\text{gr}-A)/\text{Perf}-A\ \ \ \ \ \ .   
\end{equation}  


\subsection{The LG/CY correspondence}   

Between $\text{HMF}_{_{\mathbb{Z}}}({\cal W})$ and $D^{^b}\text{Coh}(X)$.  

The idea of this correspondence comes from the fact that the two categories are both Verdier quotients of $D^{^b}(\text{gr}-A)$.   

Let tors-$A$ be the subcategory of gr-$A$ of torsion modules that are finite-dimensional over $\Lambda$. From Serre's Theorem,  

\begin{equation}  
D^{^b}\text{Coh}(X) \ \simeq\ D^{^b}(\text{qgr}-A)\ \equiv\ D^{^b}(\text{gr}-A)/D^{^b}(\text{tors}-A)  
\end{equation}   

\begin{equation} 
\text{HMF}_{_{\mathbb{Z}}}({\cal W})\ \simeq\ D^{^b}(\text{gr}-A)/\text{Perf}-A  \ \ \ \ \ . 
\end{equation}   


If the quotient functors

\begin{equation}  
\begin{aligned}  
&\pi:\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^b}(\text{qgr}-A)\\
&q:\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^{gr}}_{_{sg}}(A)  
\end{aligned}
\end{equation}   
had adjoint functors, then we could lift objects and morphisms in a quotient category to those in $D^{^b}(\text{gr}-A)$, and project them to the other quotient, thereby obtaining functors between two quotient categories. However, $q$ does not admit ant adjoint functor, whereas $\pi$ admits a right-adjoint. Considering the restrictions:  

\begin{equation}   
\begin{aligned}
&\pi_{_i}:\ D^{^b}(\text{gr}-A_{_{\ge i}})\ \hookrightarrow\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^b}(\text{qgr}-A)\\  
&q_{_i}:\ D^{^b}(\text{gr}-A_{_{\ge i}})\ \hookrightarrow\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^{gr}}_{_{sg}}(A) \ \ \ \ \ \ .  
\end{aligned}  
\end{equation}    


Here, $\text{gr}-A_{_{\ge i}}$ denote modules, $M$,  such that  

\begin{equation}  
M_{_p}\ =\ 0\ \ \ \ \ \ \text{for} \ \ \ \ p<i  \ \ \ \ \ \ \ .
\end{equation}   

Now, $\pi_{_i}$ admits right-adjoints, whereas $q_{_i}$ admits left-adjoints.    

\underline{Lemma}  
Defining   

\begin{equation}  
\mathbb{R}\omega_{_i}:\ D^{^b}(\text{qgr}-A)\ \longrightarrow\ D^{^b}(\text{gr}-A_{_{\ge i}})  
\end{equation}    
by   

\begin{equation}   
\mathbb{R}\omega_{_i}(M)\ \overset{def.}{=}\ \bigoplus_{_{k=1}}^{^{\infty}}\ \mathbb{R}\text{Hom}_{_{D^{^b}(\text{qgr}-A)}}(\pi A, M(k)).   
\end{equation}   

Then, $\mathbb{R}\omega_{_i}$ is fully-faithful, and $\mathbb{R}\omega_{_i}$ is the right-adjoint of $\pi_{_i}$. All cohomologies $\mathbb{R}^{^j}\omega_{_i}(M)$ are contained in tors-$A$ for $j>0$.  

Similarly,   

\begin{equation}  
\begin{aligned}  
&\mathbb{R}\omega_{_i}(M)\ :\ D^{^b}\text{Coh}(X)\ \longrightarrow\ D^{^b}(\text{gr}-A_{_{\ge i}})\\  
&\mathbb{R}\omega_{_i}(M)({\cal E})\ \overset{def.}{=}\ \bigoplus_{_{k=1}}^{^{\infty}}\ \mathbb{R}\text{Hom}_{_{D^{^b}\text{Coh}(X)}}({\cal O}_{_X}, {\cal E}(k))\ \ \ \ \ \ .   
\end{aligned}
\end{equation}   

A Gorenstein algebra, $A$, has finite injective dimension, $n$. If   

\begin{equation}  
D(K)\ \overset{def.}{=}\ \mathbb{R}\text{Hom}_{_{A}}(K,A), 
\end{equation}   
where
\begin{equation}   
K\ \simeq\ A/(x_{_o},...,x_{_n}),    
\end{equation}  
then, it is isomorphic to    


\begin{equation}  
K(a)[-n]  
\end{equation}    
for some integer, $a$, called the Gorenstein parameter. If 


\begin{equation}  
A\ =\ R/{\cal W}  
\end{equation}  
and ${\cal W}$ defines a CY, then $a=0$.  = 

For later purposes, we now introduce the notion of \emph{semiorthogonal decomposition}. Given a triangulated category, ${\cal C}$,   

\begin{equation}  
{\cal C}\ =\ <{\cal A},{\cal B}>  
\end{equation}  
is a semi-orthogonal decomposition if:   

\begin{enumerate}  

\item   ${\cal A, B}$ are full triangulated subcategories    

\item   $\forall C\ \in\text{Ob}({\cal C})$, there is an exact triangle    

\begin{equation}   
\begin{aligned}  
&A\ \xrightarrow{[1]}\ B  \\
&\\
&\ \ \ \ \  C  
\end{aligned}  
\end{equation}    
for some $A\ \in\text{Ob}({\cal A}), B\ \in\text{Ob}({\cal B})$. In such case, $A,B$ are referred to as orthoginal projections of $C$ onto ${\cal A}$ and ${\cal B}$, respectively. 

\item    

\begin{equation}  
\text{Hom}_{_{\cal C}}({\cal B},{\cal A})\ =\ 0\ \ \ , \ \ \ \forall B\ \in\text{Ob}({\cal B}),  A\ \in\text{Ob}({\cal A})\ \ \ \ \ .     
\end{equation}

\end{enumerate}   



\underline{Lemma}   

Let $S_{_{\ge i}}$ be the triangular subcategory generated by $K(e)$, with $e\le-i$, and ${\cal P}_{_{\ge i}}$ the triangulated subcategory generated by $A(e)$, $e\le-i$. Then, $\forall i\in\mathbb{Z}$, there are semi-orthogonal decompositions  

\begin{equation}   
D^{^b}(\text{gr}-A_{_{\ge i}})\ =\ <D_{_i}, S_{_{\ge i}}>\ =\ <{\cal P}_{_{\ge i}}, {\cal T}_{_i}>  
\end{equation}  
where $D_{_i}$ is equivalent to $D^{^b}(\text{qgr}-A_{_{\ge i}})$ under the function $\mathbb{R}\omega_{_i}$, and ${\cal T}_{_i}$ is equivalent to $D_{_{sg}}^{^{gr}}(A)$.  

\underline{Main Theorem} [Orlov]  

Let $a$ be the Gorenstein parameter of $A$. Then, $D_{_{sg}}^{^{gr}}(A)$ and $D^{^b}(\text{qgr}-A)$ are related as follows:  

\begin{enumerate}  

\item   If $a>0$, $\forall i\in\mathbb{Z}$ fully-faithful functors    

\begin{equation}   
\Phi_{_i}:\ D_{_{sg}}^{^{gr}}(A)\ \longrightarrow\ D^{^b}(\text{qgr}-A)  
\end{equation}  
and semi-orthogonal decomposition  

\begin{equation}  
D^{^b}(\text{gr}-A)\ =\ \left<\pi(A(-i-a+1),...,\pi A(-i),\Phi_{_i}D_{_{sg}}^{^{gr}}(A)\right>  
\end{equation}    
where  

\begin{equation}  
\pi:\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^b}(\text{qgr}-A)  
\end{equation}  
is the natural projection, and   

\begin{equation}   
\Phi_{_i}:\ D_{_{sg}}^{^{gr}}(A)\ \simeq\ {\cal T}_{_i}\ \hookrightarrow\ D^{^b}(\text{gr}-A)\ \longrightarrow\ D^{^b}(\text{qgr}-A)  \ \ \ \ .   
\end{equation}


\item If $a<0, \forall i\in \mathbb{Z}$ there are fully-faithful functors  

\begin{equation}  
{\cal G}_{_i}:\ D^{^b}(\text{qgr}-A)\ \longrightarrow\ D_{_{sg}}^{^{gr}}(A)  
\end{equation}  
and semi-orthogonal decomposition  

\begin{equation}  
D_{_{sg}}^{^{gr}}(A)\ = \ \left<qk(-i),...,qk(-i+a+1),{\cal G}_{_i}D^{^b}(\text{qgr}-A) \right>, 
\end{equation}   
with   

\begin{equation}  
q:\ D^{^b}(\text{gr}-A) \ \longrightarrow\ D_{_{sg}}^{^{gr}}(A)  
\end{equation}   
is the natural projection, and    

\begin{equation}  
{\cal G}_{_i}:\ D^{^b}(\text{qgr}-A)\ \simeq\ D_{_{i-a}}\ \hookrightarrow\ D^{^b}(\text{gr}-A)\ \xrightarrow{q}\ D_{_{sg}}^{^{gr}}(A)  \ \ \ \ .
\end{equation}   


\item   If $a=0$, $D_{_{sg}}^{^{gr}}(A)$ and $D^{^b}(\text{qgr}-A)$ are equivalent under $\Phi_{_i}$ combined with ${\cal G}_{_i}$.  

For the case in which $X=\text{Proj}(A)$ is a CY variety, $a=0$, implying   

\begin{equation}
    D^{^b}(\text{qgr}-A)\ \simeq\ D^{^b}\text{Coh}(X)
\end{equation}  
and   

\begin{equation}
    D_{_{sg}}^{^{gr}}(A)\ \simeq\ \text{HMF}_{_{\mathbb{Z}}}({\cal W})
\end{equation}   
are equivalent.   


\end{enumerate}  

\subsection{Polishchuk-Zaslow Mirror Symmetry: a brief recap}  

Given  $T^{^2}$ a symplectic torus, 

\begin{equation}  
T^{^2}\ \equiv\ \mathbb{C}/\left(\mathbb{Z}\oplus e^{^{2\pi i/3}}\mathbb{Z}\right)  .
\end{equation}    

Let $\alpha$ be its symplectic area, and $q=T^{^{\alpha}}$ in $\Lambda$.  

Any unobstructed Lagrangian circle, $L$, is described by a straight line  

\begin{equation}  
(c,0)+t\vec{v}\ \ \ , \ \ \ t\in\mathbb{R}  
\vec{v}\ =\ a+e^{^{2\pi i/3}}b,  \ \ \ \ a,b\in\mathbb{Z}, c\in[0,1)  .
\end{equation}    

\begin{equation}  
L\ =\ L_{_{(a,b),c}}  
\end{equation}  

Then, the categorical mirror symmetry formulation of [PL] is succinctly expressed in the following    

\underline{Theorem}  

\begin{equation}   
{\cal F}:\ D^{^b}\text{Coh}(X)\ \simeq\ D^{^{\pi}}F(E)  
\end{equation}    
such that 

\begin{equation} 
\Phi\left({\cal O}_{_X}(np_{_o})\right)\ =\ L_{_{(1,-n)}}\ \ \ , \ \ \ \Phi\left({\cal O}_{_X}(p_{_o})\right)\ =\ L_{_{(0,-1),\frac{1}{2}}}\ \ \ \ ,  
\end{equation}   
where $X$ is a mirror elliptic curve, and $p_{_o}$ is a point in $X$. The construction of ${\cal F}$ follows from the identification of theta identities and morphisms between Lagrangians.      

\subsection{Localised mirror functors} 

Two versions:  

\begin{enumerate}  
\item Ungraded.  
\item Graded. 
\end{enumerate}  

Take $T^{^2}$ equipped with $\mathbb{Z}/3$-action. A parallelogram whose sides are solid lines is a fundamental domain of $T^{^2}$. Let $\Omega=dz$ be the holomorphic volume form on $T^{^2}$, with $z$ being the complex coordinate of $\mathbb{C}$. The grading structure on $E$ is not preserved under the $\mathbb{Z}/3$-action, thereby implying such action does not induce an action on the graded Fukaya category either, but there is an action up to shifts, i.e. a homeomorphism  

\begin{equation}  
\mathbb{Z}/3\ \longrightarrow\ \text{Auteq}\left(D^{^{\pi}}F(T^{^2})\right)/\mathbb{Z},  
\end{equation}  
with $\mathbb{Z}$ denoting the shift functor. For example, an oriented Lagrangian, $L$, is a line defined as follows 

\begin{equation}  
\frac{1+\xi}{2}+\sqrt{-1}\ t.  
\end{equation}  

Constructing an immersed Lagrangian  



\begin{equation}    
\mathbb{L}\ \overset{def.}{=}\ L\ \cup\ \tau(L)\ \cup\ \tau^{^2}(L),  
\end{equation}   
equipping each constituent with a pin structure. The phase of $\tau(L)$ is $\frac{\pi}{2}-\frac{2\pi}{3}$, and that of $\tau^{^2}(L)$ is $\frac{\pi}{2}-\frac{4\pi}{3}$, i.e. $\tau$ is a rotation by $-\frac{2\pi}{3}$.   

The union of 3 dashed lines (add picture here) is $\mathbb{L}$. $e_{_1},e_{_2},e_{_3}$ represents fundamental classes of $L, \tau(L), \tau^{^2}(L)$., respectively, and  

\begin{equation}   
e\ =\ e_{_1}+e_{_2}+e_{_3}  
\end{equation}   
is the unit in $\mathbb{L}$. 

\subsubsection{Ungraded localised mirror functor}  

\underline{Theorem} [Cho-Hong-Lau], 2015  

Let $x,\ y,\ z$ be immersed generators of $\overline{\mathbb{L}}\subset T^{^2}/(\mathbb{Z}/3)$, $X_{_i}, Y_{_i}, Z_{_i}, i=1,2,3$ be their lifting. Then,   

\begin{equation}   
b\ = \ x\left(X_{_1}+X_{_2}+X_{_3}\right)+y\left(Y_{_1}+Y_{_2}+Y_{_3}\right)+z\left(Z_{_1}+Z_{_2}+Z_{_3}\right)\ \ \ \ , \ \ \ \ \forall x, \ y, \ z\ \in\ \Lambda  
\end{equation}   
is a weak bounding cochain of $\mathbb{L}$.     

Let   


\begin{equation}  
{\cal W}\ =\ \phi(x^{^3}-y^{^3}+z^{^3})-\psi xyz\ \equiv\ {\cal W}(\mathbb{L}, b)  
\end{equation}  
where $\phi,\psi$ are power series of $q_{_{\alpha}}=T^{^{\Delta_{_{xyz}}}}$.   

Suppose $L^{^{\prime}}$ is an unobstructed Lagrangian submanifold. $CF((\mathbb{L},b),L^{^{\prime}}))$ is generated by even and odd intersections. The number of strips lying between even and odd generators, $\mu_{_1}$, are such that  

\begin{equation}  
\mu_{_1}^{^2}\ =\ {\cal W}\ \cdot\ \text{id}_{_{n\times n}},    
\end{equation}  
with $n$ denoting the number of even and odd generators. The resulting matrix factorisation therefore reads  

\begin{equation}  
\text{MF}({\cal W})\ =\ \left(CF((\mathbb{L}, b),\ \mu_{_1}), L^{^{\prime}}\right),  
\end{equation}  
where    


\begin{equation}  
\text{rank}(\text{MF}({\cal W}))\ =\ n.  
\end{equation}     


\underline{Theorem} [Cho-Hong-Lan], 2015  

Let ${\cal C}$ be an $A_{_{\infty}}$-category, and $(A,b)$ a weakly-unobstructed object with weak bounding cochain $b$. Let ${\cal C}_{_o}$ be the $A_{_{\infty}}$-subcategory of unobstructed objects. Define a collection of maps    

\begin{equation}  
\left\{{\cal LM}_{_{\bullet}}^{^{(A,b)}}\right\}   
\end{equation}   
with ${\cal C}_{_o}$ as source category, such that:  


\begin{itemize}  

\item  ${\cal LM}_{_0}^{^{(A,b)}}$ sends an object $B$ to    

\begin{equation}  
\text{MF}\ =\ \left(\text{Hom}((A,b), B), \mu_{_1}\right)\ \ \ \ .     
\end{equation}

\item  ${\cal LM}_{_1}^{^{(A,b)}}(x)$ is defined as follows  

\begin{equation}  
{\cal LM}_{_1}^{^{(A,b)}}(x)\ \overset{def.}{=}\ (-1)^{^{\bullet}}\mu_{_2}^{^{b,0}}(.,x):\ \left(\text{Hom}((A,b), B), \mu_{_1}\right)\ \longrightarrow\ \left(\text{Hom}((A,b), B), \mu_{_1}\right)\ \ \ \ ,     
\end{equation}  
with 

\begin{equation}  
x\ \in\ \text{Hom}\left(B_{_1}, B_{_2}\right)\ \ \ .   
\end{equation}

\item  \begin{equation}  
{\cal LM}_{_k}^{^{(A,b)}}(x_{_1},...,x_{_k})\ \overset{def.}{=}\ (-1)^{^{\bullet}}\mu_{_{k+1}}^{^{b,0,...,0}}(y, x_{_1},...,x_{_k})   
\end{equation}

\end{itemize}    

Then,    

\begin{equation}   
\left\{{\cal LM}_{_{\bullet}}^{^{(A,b)}}\right\}  :\ {\cal C}_{_o}\ \longrightarrow\ \text{MF}({\cal W}(a,b))   
\label{eq:ulmf}   
\end{equation}   
is an $A_{_{\infty}}$-functor where MF is the differential $\mathbb{Z}/2$-graded category of MFs of ${\cal W}(A,b)$. \eqref{eq:ulmf} is therefore referred to as the \emph{ungraded local} mirror functor.



\subsubsection{Graded localised mirror functor}    

Adding a cyclic group action, 

\begin{equation}  
(M,\omega, \Omega)  
\end{equation}  
defining a Cy manifold, with $\mathbb{Z}/d\mathbb{Z}$. Consider a $\frac{1}{d}$-grading on an immersed Lagrangian, i.e. defining a phase function  

\begin{equation}  
\theta_{_L}^{^{1/d}}:\ L\ \longrightarrow\ \mathbb{R}\ \ \ \ \ \  \ \ \ \ \  \text{s.t.}\ \ \  \ \ \ \ \ \ \ \ \Omega^{^{\otimes d}}(T_{_p}L)\ =\ e^{^{\pi i\theta_{_L}^{^{1/d}}(p)}} \ \ \ .  
\end{equation}   

If such a phase function exists, then $L$ is said to be $\frac{1}{d}$-graded. If the phase is constant, it is special Lagrangian.   

\underline{Proposition}  
On the full $A_{_{\infty}}$-subcategory of $\frac{1}{d}$-graded Lagrangians, the $A_{_{\infty}}$-multiplication has degree $2-k$ under $\frac{1}{d}$-grading.  

The degree of a Lagrangian intersection, $p$, between $\frac{1}{d}$-graded Lagrangians is defined as follows  



\begin{equation}  
\text{deg}^{^{1/d}}(p)\ \overset{def.}{=}\ \frac{1}{d}\left(\theta_{_{L_{_2}}}^{^{1/d}}(p)-\theta_{_{L_{_1}}}^{^{1/d}}(p)+\theta^{^d}\left(\hat{L_{_1}L_{_2}}\right)\bigg|_{_p}\right)\ \in\ \frac{1}{d}\mathbb{Z}  
\end{equation}    
where $p$ is considered as a morphism   

\begin{equation}  
p:\ L_{_1}\ \longrightarrow\ L_{_2}  
\end{equation}  
and  

\begin{equation}  
\pi\theta^{^d}\left(\hat{L_{_1}L_{_2}}\right)\bigg|_{_p}  
\end{equation}    
is the phase angle of the positive-definite path from $TL_{_2}$ to $TL_{_1}$ measured by $\Omega^{^{\otimes d}}(p)$. 


Going back to the example of $T^{^2}$ with $\mathbb{Z}/3$-action, the Seidel Lagrangian, $\mathbb{L}$ can be turned into a special Lagrangian w.r.t. $\frac{1}{3}$-grading by defining a possible phase as  

\begin{equation}  
\theta_{_{\mathbb{L}}}^{^{1/3}}\ =\ -\frac{1}{2}   \ \ \ .
\end{equation}  

Then, each immersed point that is a morphism between any of $L, \tau(L), \tau^{^2}(L)$, has degree $\frac{1}{3}$.  

Upon further fixing a character  

\begin{equation}  
\begin{aligned} 
&\mathbb{Z}/3\ \longrightarrow\ U(1)  \\  
&-j\ \  \mapsto\ \ e^{^{-\pi i 2 j/3}},    
\end{aligned}
\end{equation}    
we can define a pair   

\begin{equation}  
\left(\bigoplus_{_{p_{_i}\in CF((\mathbb{L},b),L)}} A_{_{g_{_i}}}[\text{deg} p_{_i}],\ \ \mu_{_1}^{^{(\mathbb{L},b),L}}\right)   \ \ \ ,  
\label{eq:obj}   
\end{equation}  
where   

\begin{equation}  
p_{_i}\ \in\ L^{^{g_{_i}}}\ \cap \ L^{^{\prime}}  
\end{equation}  
and deg$ p_{_i}$ denotes the $\mathbb{Z}$-grading by $\Omega$.  

\underline{Theorem}  
The category whose ojects are of the form \eqref{eq:obj} is equivalent to the category of graded matrix factorisations of ${\cal W}$ under the following correspondence  

\begin{equation}  
\left(\bigoplus_{_i}A_{_{g_{_i}}}[k_{_i}],\ \ \delta\right)  \ \ \ \ \mapsto\ \ \ \left(...\ \rightarrow\ E_{_0}\ \rightarrow\ E_{_1}\ \rightarrow\ ...\right) \ \ \ ,  
\label{eq:obj1}   
\end{equation} 
where   

\begin{equation}  
E_{_0}\ =\ \bigoplus_{_{K_{_i}:\text{even}}}\ R\left(-\frac{k_{_i}d}{2}-\frac{d}{2}\alpha_{_{g_{_i}}}\right)  
\end{equation}  

\begin{equation}  
E_{_1}\ =\ \bigoplus_{_{K_{_i}:\text{odd}}}\ R\left(-\frac{(1-k_{_i})d}{2}-\frac{d}{2}\alpha_{_{g_{_i}}}\right)  
\end{equation}  
and structure maps  

\begin{equation}  
p_{_i}:\ E_{_i}\ \longrightarrow\ E_{_{i+1}}.    
\end{equation}    

\underline{Proposition}  

The collection of maps   

\begin{equation}  
\left\{{\cal F}_{_{bullet}}^{^{\mathbb{L},b}}\right\}
\end{equation} 
becomes an $A_{_{\infty}}$-functor,  

\begin{equation}  
{\cal LM}^{^{\mathbb{L,b}}}_{_{\text{gr}}}:\ \ \ Fu^{^{\mathbb{Z}}}(T^{^2})\ \longrightarrow\ TW_{_{\mathbb{Z}}}\left(R_{_{\cal W}}\mathbb{Z}/3\right),  
\end{equation}  
called the \emph{graded localised} mirror functor.  


Importantly, this Proposition, has been shown to hold in more general setups, involving noncommutative Matrix Factorisations.


