\subsection{Noncommutative Mirror from multiple Lagrangians}    

Starting from a reference Lagrangian immersion  

\begin{equation}  
\mathbb{L}\ \overset{def.}{=}\ \left(L_{_1},...,L_{_k}\right)  
\end{equation}   
e.g, $\mathbb{L}$ could be a set of generators of the Fukaya category. The construction leads to a quiver $Q$ with relations $R$, together with a central element ${\cal W}$ of the quiver algebra with relations  $\Lambda Q/R$.  

Under certain conditions, $R$ can be obtained as partial derivatives of a cyclic element $\Phi$ in the path algebra $\Lambda Q$. Regarding 

\begin{equation}  
(\Lambda Q/{\cal W})  
\end{equation}  
as a generalised mirror of $X$, in the sense that there exists a natural functor  

\begin{equation}  
\text{Fuk}(X)\ \longrightarrow\ \text{MF}(\Lambda Q/{\cal W})  
\end{equation}   

The quiver $Q\equiv Q^{^{\mathbb{L}}}$ is a finite oriented graph, whose varieties correspond to elements in $\mathbb{L}$, and whose arrows correspond to odd-degree immersed generators of $\mathbb{L}$.     


The path algebra of $Q$ can be taken to be the base of the Fukaya subcategory, $\mathbb{L}$. The counting of holomorphic disks passing through a generic marked point on each member of $\mathbb{L}$ defines $\{{\cal W}_{_i}\}$  

\begin{equation}  
{\cal W}_{_{\mathbb{L}}}\ \overset{def.}{=}\ \sum_{_i}{\cal W}_{_i}\ \in\ \Lambda Q/R  
\end{equation}  

As we will see, ${\cal W}_{_{\mathbb{L}}}$ lies in the center of $\Lambda Q/R$.      

\subsubsection*{Path algebra and the semi-simple ring} 


Assuming any two Lagrangians intersect transversally, and that  

\begin{equation}  
\bigcup_{_{1\le i\le\ k}}\ L_{_i}  
\end{equation}
to be an immersed Lagrangian. 

Denoting by   

\begin{equation}  
Q\ =\ Q^{^{\mathbb{L}}}  
\end{equation}  
a graph such that each vertex $v_{_i}$ of $Q$ corresponds to a Lagrangian $L_{_i}\in\mathbb{L}$,  

\begin{equation}  
Q_{_0}^{^{\mathbb{L}}}\ \equiv\ \{v_{_1},...,v_{_k}\}  
\end{equation}     
defines the vertex set.   

Each arrow $v_{_i}\rightarrow v_{_j}$ corresponds to odd-degree Floer generator in $CF^{^{\bullet}}(L_{_i},L_{_j})$, namely an intersection point between $L_{_i}$ and $L_{_j}$. If $i=j$, we get loops at $v_{_i}$ corresponding t oodd-degree immersed generators of $L_{_i}$. From the construction above, $Q$ corresponds to the endomorphism quiver of $\mathbb{L}$. 


For a quiver $Q$ with a given set of vertices, $Q_{_0}$, andd arrows, $Q_{_1}$,    we have maps  

\begin{equation}  
h,t:\ Q_{_1}\ \longrightarrow\ Q_{_0}  
\end{equation}  
assigning head and tail vertices to each arrow, respectively. 

Each vertex $v$ corresponds to a trivial path $\pi_{_v}$ of length 0. A sequence of arrows   

\begin{equation}  
p\ =\ a_{_{k-1}}a_{_{k-2}}...a_{_1}a_{_0}  
\end{equation}  
is said to be a path of length $k$ if  


\begin{equation}  
h(a_{_i})\ =\ t(a_{_{i+1}})\ \ \forall i  
\end{equation}  

Setting 


\begin{equation}  
h\ \overset{def.}{=}\ h(a_{_{k-1}})\ \ \ \ , \ \ \ \ t(p)\ \overset{def.}{=}\ t(a_{_0})  
\end{equation}  

$p$ is said to be a cyclic path if   

\begin{equation}  
h(p)\ =\ t(p)  
\end{equation}  


Two paths, $p,q$, can be concatenated if  

\begin{equation}  
t(q)\ =\ h(p)   
\end{equation}  
to get the path $pq$. Otherwise  

\begin{equation}  
pq\ =\ 0  
\end{equation}  



A path algebra $\Lambda_{_0} Q$ over the ring $\Lambda_{_0}$ for a quiver $Q$Q is a $\Lambda_{_0}$-module spanned by paths in $Q$. The product is defined by linear extension of the concatenation of path.  

We can set  

\begin{equation}  
\Lambda \ \overset{def.}{=}\ \Lambda\ \underset{\Lambda_{_0}}{\otimes}\ \Lambda_{_0}Q  
\end{equation}   

Each vertex, $v$, corresponds to a trivial path, $\pi_{_v}$, of 0-length.    

For a vertex $v$, $\pi_{_v}$ is an idempotent in $\Lambda Q^{^{\mathbb{L}}}$. It generates a semi-simple ring $\Lambda^{^{\oplus}}$ defined as follows  

\begin{equation}  
\Lambda^{^{\oplus}}\ =\ \Lambda\pi_{_1}\ \oplus\ ...\ \oplus\ \Lambda\ \pi_{_k}  
\end{equation}  
with    

\begin{equation}  
\pi_{_i}\cdot\ \pi_{_i}\ = \ \pi_{_i}\ \ \ , \ \ \ \pi_{_i}\cdot\ \pi_{_j}\ = \ 0 \ \  \text{if}\ \ i\neq j  
\end{equation}    


Since an $A_{_{\infty}}$-category is an $A_{_{\infty}}$-algebra over $\Lambda^{^{\oplus}}$,   

\begin{equation}  
{\cal C}\ = \ {\cal F}(\mathbb{L, L})\ \overset{def.}{=}\ \bigoplus_{_{i,j}}{\cal F}(L_{_i},L_{_j})  
\end{equation}
where   



\begin{equation}   
{\cal F}(L_{_i},L_{_j})\ =\ \begin{cases} 
&CF^{^{\bullet}}(L_{_i}\underset{\iota}{\times}L_{_i})\ \ \ \text{if}\ \ \ i=j\\
&\text{Span}_{_{\Lambda}}(L_{_i}\cap L_{_j})  \ \ \ \text{if}\ \ \ i\neq j\\
\end{cases}  
\end{equation}   
and module structure given by  

\begin{equation}  
\pi_{_i}\ \cdot\ {\cal C}\ \cdot\ \pi_{_j}\ =\ {\cal F}(L_{_i},L_{_j})   
\end{equation}   


\begin{equation}  
\Rightarrow\ \ \ {\cal C}^{^{\otimes r}}\ =\ \bigoplus_{_{i_{_1},...,i_{_k}}}{\cal F}\left(L_{_{i_{_1}}},L_{_{i_{_2}}}\right)\ \underset{\Lambda}{\otimes}...\underset{\Lambda}{\otimes}{\cal F}\left(L_{_{i_{_{k-1}}}},L_{_{i_{_k}}}\right)  
\end{equation}  

${\cal C}$ is said to be unital if each $CF^{^{\bullet}}(L_{_i},L_{_i})$ has a unit $\mathbb{1}_{_{L_{_i}}}$, and   

\begin{equation}   
\mathbb{1}_{_{\mathbb{L}}}\ \overset{def.}{=}\ \bigoplus_{_i}\ \mathbb{1}_{_{L_{_i}}}   
\end{equation}  
is a unit of ${\cal C}$.   


\subsubsection*{Mirror construction}   


Take the obstruction to be    

\begin{equation}  
b\ =\ \sum_{_e}x_{_e} X_{_e}\ \ \in\ \ \tilde A^{^{\mathbb{L}}}  
\end{equation}     
where 


\begin{equation}    
\tilde A^{^{\mathbb{L}}}\ \overset{def.}{=}\ \Lambda Q^{^{\mathbb{L}}}\ \underset{\Lambda^{^{\oplus}}}{\hat\otimes}\ CF(\mathbb{L,L}) 
\end{equation}     
$x_{_e}$ is the formal variable in $\Lambda Q$ associated to each arrow $e$ of $Q$, whereas $X_{_e}$ denotes the corresponding odd-degree immersed generators in $CF(\mathbb{L,L})$. Assuming  

\begin{equation}  
\text{deg} x_{_e}\ =\ 1-\ \text{deg} X_{_e}  
\end{equation}  
such that deg$b$=1.  Then, the Maurer-Cartan relations read  



\begin{equation}  
\mu_{_0}^{^b}\ = \ \mu(e^{^b})\ =\ \sum_{_i}{\cal W}_{_i}\mathbf{1}_{_{L_{_i}}}+\sum_{_f}P_{_f}X_{_f}  
\end{equation}  
where  the coefficients $P_{_f}$ are associated to the even-degree generators $X_{_f}$ of $CF(\mathbb{L,L})$.  

The generalised mirror of $X$ reads    

\begin{equation}  
\left({\cal A}, {\cal W}_{_{\mathbb{L}}}\right)  
\end{equation}. 

Analogously to the case of the single Lagrangian immersion, ${\cal W}_{_{\mathbb{L}}}$ is central to ${\cal A}$.

Under suitable conditions,  

\begin{equation}  
{\cal A}\ =\ \text{Jac}(Q,\Phi)\ =\ \frac{\Lambda Q}{(\partial_{_{x_{_e}}}\Phi:\ e\in E)}  
\end{equation}    
with $\Phi$ the spacetime superpotential.    


The mirror functor reads   

\begin{equation}   
{\cal F}\ =\ {\cal F}_{_{\mathbb{L}}}:\ \text{Fuk}(X)\ \longrightarrow\ \text{MF}\left(\text{Jac}\left(Q^{^{\mathbb{L}}},\Phi_{_{\mathbb{L}}}\right);{\cal W}_{_{\mathbb{L}}}\right)  
\end{equation}   

The construction of such $A_{_{\infty}}$-functor follows in a very similar way to that of a single Lagrangian immersion, apart from the fact that now we work over the semi-simple ring $\Lambda^{^{\oplus}}$. Taking an unobstructed Lagrangian $U$  

\begin{equation}  
{\cal F}(U)\ \overset{def.}{=}\ \left({\cal A}\underset{\Lambda^{^{\oplus}}}{\otimes}\ CF(\mathbb{L},U),\delta\right)\ \simeq\ \left(\bigoplus_{_i}\bigoplus_{_{v\in L_{_i}\cap U}}{\cal A}\cdot \pi_{_i},\delta\right)  
\end{equation}   


\medskip 

\medskip  



\underline{Proposition} [CHL]  

${\cal F}(U)$ as defined above is a MF of $({\cal A},{\cal W}_{_{\mathbb{L}}})$, namely  

\begin{equation}  
\delta^{^2}\ =\ {\cal W}\ \cdot\ \text{Id}  
\end{equation}  

\medskip 

\medskip  



\underline{Theorem} [CHL]  


If the $A_{_{\infty}}$-category is unital, then ${\cal F}_{_{\mathbb{L}}}$ is injective on $H^{^{\bullet}}(\text{Hom}(\mathbb{L},U))\ \ \ \ \ \ \ \ \forall U$.







