\keywords{ Grothendieck group, complete intersections, minimal resolutions, stable category, support varieties }

 \begin{abstract}
Let $(Q,\n)$ be a regular local ring of dimension $c \geq 2$ with algebraically closed residue field $k = Q/\n$.
 Let $f_1, f_2, \ldots f_{c-1}, g$ be a regular sequence in $Q$ such that $ f_i \in \n^2$ for all $i$ and $g \in \n$.
 Set $A = Q/(f_1,\ldots, f_{c-1}, g^r)$ with $r \geq 2$.  Notice $A$ is an Artinian complete intersection of codimension $c$.
   We show that there exists $\alpha_A \in \Pb^{c-1}(k)$  such that there exists integer $m_A \geq 2$ (depending only on $A$) with  $m_A$ dividing $\ell(M)$ for every finitely generated $A$-module $M$  with $\alpha_A \notin \Vc(M)$ (here $\ell(M)$ denotes the length of $M$ and $\Vc(M)$ denotes the support variety of $M$). As an application we prove that  if $k$ be a field and  $R = k[X_1, \ldots, X_c]/(X_1^{a_1}, \ldots, X_c^{a_c})$ with $a_i \geq 2$ and $c \geq 2$. Let $p$ be a prime number and assume $p$ divides two of the $a_i$. Then $p$ divides $\ell(E)$
for any $A$-module with bounded betti numbers.
\end{abstract}
 \maketitle
\section{introduction}
Let $(A,\m)$ be an Artinian local complete intersection of complexity $c \geq 2$. For simplicity we assume that the residue field $k$ of $A$ is algebraically closed. Let $\ell(M)$ denote length of an $A$-module and let $\mu(M)$ denote the number of its minimal generators. If $c = 2$ and if the Hilbert series of $A$ is $1 + 2z + z^2$ then it is not difficult to prove that the length of any module with complexity $\leq 1$ is even. Note that complexity $\leq 1$ is a homological notion having to do with boundedness of betti-numbers. However length is a decidedly a non-homological notion. The purpose of this paper is to investigate whether analogues of this  result holds to complete intersections of higher codimension.

It turns out that the theory of support varieties of  modules is very fruitful for us. This notion was introduced by Avramov \cite{LLAV} and extended to pairs of modules by Avramov and Buchweitz, see \cite{AB}.
Basically to every module $M$ an algebraic variety $\Vc(M) \subseteq \Pb^{c-1}(k)$ is attached. Support varieties encode homological information  of a module.
It also turns out  (when $A$ is Artinian) that existence of an indecomposable module $H$ with $\Omega(H) \cong H$ and $\mu(H)$ odd is also important (here $\Omega(H)$ denotes the first syzygy of $H$ and $\mu(H)$ is the minimal number of generators of $H$). We note that support variety of an indecomposable periodic module is $\{ a \}$ for some $a \in \Pb(k)^{c-1}$, see \cite[3.2]{B}.   Our first result is the following:
\begin{theorem}\label{main}
Let $(A,\m)$ be an Artin local complete intersection of complexity $c \geq 2$ with algebraically closed residue field $k$. Assume $\ell(A)$ is even. Also assume that there exists an indecomposable $A$-module $H$ with $\Omega(H) \cong H$ and $\mu(H)$ odd. Let $\{ \alpha \} = \Vc(H)$.   Then there exists integer $m_A \geq 2$ (depending only on $A$) such that  $m_A$ divides $\ell(M)$ for every $M$ with  $\alpha \notin \Vc(M)$.
\end{theorem}







Next we turn to  the question,
 whether there exists complete intersection rings satisfying hypothesis of Theorem \ref{main}. It turns out there is a very large family of complete intersections which satisfy the hypothesis of Theorem \ref{main}.
\s\label{hyp}\emph{Example:} Let $(Q,\n)$ be a regular local ring of dimension $c \geq 2$ with algebraically closed residue field $k = Q/\n$.
 Let $f_1, f_2, \ldots f_{c-1}, g$ be a regular sequence in $Q$ such that $ f_i \in \n^2$ for all $i$ and $g \in \n$.
 Set $A = Q/(f_1,\ldots, f_{c-1}, g^2)$.
Notice $A$ is an Artin complete intersection of complexity $c$. Set $H = A/(g) = Q/(f_1, \ldots, f_{c-1}, g)$.
Clearly $H$ is an $A$-module. It is indecomposable since $\mu(H) = 1$.
Set $B = Q/(f_1, \ldots, f_{c-1})$. Then note that $g$ is $B$-regular. We have an exact sequence
$$ 0 \rt B/(g) \rt B/(g^2) \rt B/(g) \rt 0. $$
Notice $B/(g) = H$ and $B/(g^2) = A$. It follows that $\Omega_A(H) \cong H$. Also $\ell(A) = 2\ell(H)$ is even.  Thus $A$ satisfies the conditions of Theorem \ref{main}.

We might wonder about complete intersection rings $A = Q/(f_1,\ldots, f_{c-1}, g^r)$ where $r \geq 3$ is odd. It turns out we can prove a similar result.
\begin{theorem} \label{m2}
 Let $(Q,\n)$ be a regular local ring of dimension $c \geq 2$ with algebraically closed residue field $k = Q/\n$.
 Let $f_1, f_2, \ldots f_{c-1}, g$ be a regular sequence in $Q$ such that $ f_i \in \n^2$ for all $i$ and $g \in \n$.
 Set $A = Q/(f_1,\ldots, f_{c-1}, g^r)$ where $r \geq 2$. Set $H = Q/(f_1,\ldots, f_{c-1}, g)$. Then $H$ is an indecomposable periodic $A$-module.  Let $\{ \alpha \} = \Vc(H)$.   Then there exists integer $m_A \geq 2$ (depending only on $A$) such that  $m_A$ divides $\ell(M)$ for every $M$ with  $\alpha \notin \Vc(M)$.
\end{theorem}
\begin{remark}
Theorem \ref{m2} implies the assertion for the example following Theorem \ref{main}. However Theorem \ref{m2} is considerably harder to prove than Theorem \ref{main}.
\end{remark}
The original question which motivated me was whether there exists a number $s$ such that $s$ divides $\ell(N)$ for all $N$ with bounded betti numbers (equivalently $\cx N \leq 1$). In this regard we prove
\begin{theorem}\label{m3}
Let $k$ be a field and let $A = k[X_1, \ldots, X_c]/(X_1^{a_1}, \ldots, X_c^{a_c})$ with $a_i \geq 2$ and $c \geq 2$. Let $p$ be a prime number and assume $p$ divides two of the $a_i$. Then $p$ divides $\ell(E)$
for any $A$-module with $\cx_A E \leq 1$.
\end{theorem}
\s \label{Thom}\emph{Technique used to prove our result:} \\
The technique to prove our result, to the best of our knowledge has not been used earlier in commutative algebra.
Let $\CMS(A)$ denote the stable category of $A$-modules.  Let  $\alpha \in \Pb^{c-1}(k)$. We let $\Sc_\alpha(A)$ denote the subset of $\CMS(A)$ consisting of all modules $M$ with $\alpha \notin \Vc(M)$. It is easily shown that $\Sc_\alpha(A)$ is a thick subcategory  of $\CMS(A)$, see \ref{thick-a}. Let $\T$ denote the Verdier quotient $\CMS(A)/\Sc_\alpha(A)$.
We have an exact sequence of Grothendieck groups
\[
G_0(\Sc_\alpha(A)) \xrightarrow{\xi} G_0(\CMS(A)) \rt G_0(\T) \rt 0.
\]
 Now  we have $ \epsilon \colon G_0(\CMS(A)) \cong \Z/\ell(A) \Z$ where $\epsilon ([M]) = \ell(M) \mod \ell(A)$. It suffices to show $\xi$ is NOT surjective. Equivalently we have to prove $G_0(\T) \neq 0$. We recall a result due to Thomason \cite{T}. Let $\C$ be a skeletally small triangulated category. Recall a subcategory $\D$ is dense in $\C$ if the smallest thick subcategory of $\C$ containing $\D$ is $\C$ itself. In \cite{T} a one-to one correspondence between dense subcategories of $\C$ and subgroups of the Grothendieck group $G_0(\C)$ is given. In particular if $G_0(\C) = 0$ then any dense subcategory of $\C$ is $\C$ itself. Let $\A$ be the dense subcategory of $\CMS(A)$ corresponding to the subgroup $\{ 0\}$ of $G_0(\CMS(A))$. By a general construction  we construct a dense subcategory $\A^*$ in $\T$ which is closely related to $\A$, see section \ref{dense-set}. So if $G_0(\T) = 0$ then $\A^* = \T$. In particular $k \in \A^*$. We use this fact to get a contradiction.

We now describe in brief the contents of this paper. In section two we discuss some preliminaries  that we need.
In section three we describe a dense category of a Verdier quotient  of $\C$ corresponding to a dense sub category of $\C$ (here $\C$ is a triangulated category).
In section four we prove Theorem \ref{main} following the strategy discussed in
\ref{Thom}. In section five we prove Theorem \ref{m2}. Finally in section six we prove Theorem \ref{m3}.
\section{Preliminaries}
Throughout this paper all rings are Noetherian and all modules considered are finitely generated.

\s \emph{Triangulated categories:}\\
We use \cite{N} for notation on triangulated categories. However we will assume that if $\C$ is a triangulated category then $\Hom_\C(X, Y)$ is a set for any objects $X, Y$ of $\C$.

 \s \label{sub-tri} Let $\C$ be a triangulated category with shift functor $\sum$. A full subcategory $\D$ of $\C$ is called a \emph{triangulated subcategory} of $\C$ if
 \begin{enumerate}
   \item  $X \in \D$ then $\sum X, \sum^{-1}X\in \D$.
   \item If $X \rt Y \rt Z \rt \sum X$ is a triangle in $\C$ then if $X, Y \in \D$ then so does $Z$.
   \item If $X \cong Y$ in $\C$ and $Y \in \D$ then $X \in \D$.
 \end{enumerate}

  \s A triangulated subcategory $\D$ of $\C$ is said to be \emph{thick} if $U \oplus V \in \D$ then $U, V \in \D$.
  A triangulated subcategory $\D$ of $\C$ is \emph{dense} if for any $U \in \C$ there exists $V \in \C$  such that $U \oplus V  \in \D$.

 \s\label{Groth} Let $\C$ be a skeletally small triangulated category. The \emph{Grothendieck group}  $G_0(\C)$ is the quotient group of the free abelian group
on the set of isomorphism classes of objects of $\C$ by the Euler relations: $[Y]  = [X] + [Z] $ whenever $X \rt Y \rt Z \rt \sum X$ is a triangle in $\C$.
We always have a triangle $X \rt 0 \rt \sum X \xrightarrow{1} \sum X$. So we have $[X] + [\sum X] = [0] = 0 $ in $G_0(\C)$. Therefore $[\sum X] = - [X]$ in $G_0(\C)$. It follows that \emph{every}
element of $G_0(\C)$ is of the form $[X]$ for some $X \in \C$.

\s Let $\C$ be skeletally small triangulated category and let $\D$ be a thick subcategory of $\C$. Set $\T = \C/\D$  be the Verdier quotient. There exists an exact sequence (see \cite[VIII, 3.1]{I}),
$$ G_0(\D) \rt G_0(\C) \rt G_0(\T) \rt 0. $$

\s (with setup as in \ref{Groth}). Thomason \cite[2.1]{T} constructs a one-to-one correspondence between dense subcategories of $\C$ and subgroups of $G_0(\C)$ as follows:

To $\D$ a dense subcategory of $\C$ corresponds the subgroup which is the image of $G_0(\D)$ in $G_0(\C)$. To  $H$ a subgroup of $G_0(\C)$
corresponds the full subcategory $\D_H$ whose objects are those $X$ in $\C$ such that
$[X] \in H$.



\s Let $(A,\m)$ be  Gorenstein local ring. Let $\CMS(A)$ be the stable category of maximal  \CM \ $A$-modules. Then $\CMS(A)$ is a triangulated category with shift functor as $\Omega^{-1}$ (the co-syzygy functor), see \cite[4.4.7]{Buch}. We will need the following fact that if $M \rt N \rt  L \rt \Omega^{-1}(M)$ is a triangle then we have an exact sequence $0 \rt N \rt L \oplus G \rt \Omega^{-1}(M) \rt 0$ where $G$ is free, see  \cite[4.4.7(2)]{Buch}. As the rotation $\Omega(L) \rt M \rt N \rt  L $ is also a triangle there exists an exact sequence $0 \rt M \rt F\oplus N \rt L \rt 0$, where $F$ is a free $A$-module.

\s Let $(A,\m)$ be Artinian Gorenstein local ring. Let $\CMS(A)$ be the stable category of $A$-modules. Then we have an isomorphism  $\epsilon \colon G_0(\CMS(A)) \rt \Z/\ell(A)\Z$
with $\epsilon([M]) = \ell(M) + \ell(A)\Z$; see \cite[4.4.9]{Buch}.



\s \label{supp} \emph{Support Varieties of modules over  complete intersections:}\\
Let $(Q,\n)$ be a regular local ring and let $A = Q/(f_1, \ldots,f_c)$ where $f_1, \ldots, f_c \in \n^2$ is a $Q$-regular sequence. Assume  $k = Q/\n$ is algebraically closed.
 Gulliksen, \cite[3.1]{Gull},  proved that $\Ext^*(M,k)$ is a finitely generated graded module over $T = k[t_1,\ldots, t_c]$. Here $t_1, \ldots, t_c$ can be taken to be the Eisenbud operators acting on a minimal free resolution of $M$, see \cite{E}. Define
$\Vc(M) = Z(\ann_T(\Ext^*(M,k))$ in the projective space $\mathbb{P}^{c-1}$. We call
$\Vc(M)$ the support variety of a module $M$. \emph{Note that in \cite{AB} support varieties are defined as $Z(\ann_T(\Ext^*(M,k)))$ in
$k^c$ which is a cone  as the ideal involved is homogeneous. Thus our notion of support variety is equivalent to that in \cite{AB}}.
In our case $A$ is also Artinian. The following facts follow:
\begin{enumerate}
  \item (see \cite[5.6 (6), (8), (9)]{AB}) If $ 0\rt M \rt N \rt L \rt 0$ is a short exact sequence of $A$-modules then
  $$\Vc(N) \subseteq \Vc(M)\cup \Vc(N).$$
  \item  $\Vc(M)\cap \Vc(N) = \emptyset$ if and only if  $\Tor^A_i(M, N) = 0$ for all $i \geq 1$. This follows from the fact that $A$ is Artin and \cite[Theorem IV, 4.9(iii)]{AB}.
  \item $\Vc(\Omega(M)) = \Vc(M)$ and if $M$ is MCM $A$-module then $\Vc(\Omega^{-1}(M)) = \Vc(M)$, see \cite[5.6(5), (9)]{AB}.
\end{enumerate}
We will need the following result:
\begin{proposition}\label{thick-a}
Let $(A, \m)$ be an Artin local complete intersection of codimension $c \geq 2$ and with algebraically closed residue field $k$. Let $\alpha \in \Pb^{c-1}(k)$. Let $\Sc_\alpha(A)$ denote the subset of $\CMS(A)$ consisting of all modules $M$ with $\alpha \notin \Vc(M)$. Then $\Sc_\alpha(A)$ is a thick subcategory  of $\CMS(A)$.
\end{proposition}
\begin{proof}
We first show that $\Sc = \Sc_\alpha(A)$ is a triangulated sub-category of $\CMS(A)$. See \ref{sub-tri} for the definition of a triangulated sub-category. Conditions (1), (3) are trivially satisfied by $\Sc$.
Let $M \rt N \rt L \rt \Omega^{-1}(M)$ be a triangle in $\CMS(A)$  with $M, N \in \Sc$. Then we have an exact sequence $0 \rt N \rt L \oplus F \rt \Omega^{-1}(M) \rt 0$ where $F$ is a free $A$-module. Then $$\Vc(L) = \Vc(L \oplus F) \subseteq \Vc(N) \cup \Vc(\Omega^{-1}(M)). $$
Therefore $\alpha \notin \Vc(L)$. So $L \in \Sc$. Thus $\Sc$ is a triangulated subcategory of $\CMS(A)$.
Let $M = U\oplus V \in \Sc$. Then by \cite[5.6 (7), (9)]{AB} we get
\[
\Vc(M) = \Vc(U) \cup \Vc(V).
\]
So $\alpha \notin \Vc(U)$ and $\alpha \notin \Vc(V)$. Therefore $U, V \in \Sc$. Thus $\Sc$ is thick.
\end{proof}

\section{A subcategory associated to a Verdier quotient}\label{dense-set}
In this section $\C$ is a  triangulated category with shift functor $[1]$, $\T$ is a thick subcategory of $\C$ and $\D = \C/\T$ is the Verdier quotient.
