\ar@{->}[r]
& \cone(g\circ \delta)
    \ar@{->}[r]
    & \wh{X}[1]
\
 }
\]
We note that $ t\cong \widetilde{r} \cong l $ in $\D$.
We have  a triangle
$$ \wh{L} \xrightarrow{w} T \rt C \rt \wh{L}[1] \ \quad \text{where $C = \cone(w) \in \T$.}$$
As $\A$ is dense in $\C$ we get that $C\oplus C[1] \in \A$, see \cite[4.5.12]{N}.
Taking the direct sum of the above triangle with the triangle $h \colon 0 \rt C[1] \xrightarrow{1} C[1] \rt 0$ we obtain that $T\oplus C[1] \in \A$.
We take the direct sum of $h$ and $l$ to obtain the triangle
$$\widetilde{l} \colon  \wh{X} \rt T\oplus C[1] \rt \cone(g\circ \delta)\oplus C[1] \rt \wh{X}[1].$$
Note  $\cone(g\circ \delta)\oplus C[1] \in \A$. As $h = 0$ in $\D$ it follows that $\widetilde{l} \cong l \cong t$ in $\D$. The result follows.
\end{proof}

\section{Proof of Theorem \ref{main}}
In this section we give
\begin{proof}[Proof of Theorem \ref{main}]
Set $\T = \CMS(A)/\Sc_\alpha(A)$. As discussed in \ref{Thom} it suffices to show $G_0(\T) \neq \{ 0 \}$.
 Suppose if possible $G_0(\T) = 0$. Let $\A$ be Thomason dense subcategory corresponding to the zero subgroup of $G_0(\CMS(A))$. Consider the full subcategory $\A^*$  of $\T$ whose objects are
$$\{ X \mid X \cong Y \ \text{in $\T$ for some $Y$ in $\A$} \}.$$
Then by Theorem \ref{dense}, $\A^*$ is a dense triangulated subcategory of $\T$. But $G_0(\T) = 0$. It follows that $\A^* = \T$. So there exists $X \in \A$ such that $X \cong k$ in $\T$.
Let $\phi \colon X \cong k$ be an isomorphism in $\T$.
We have a left fraction
\[
\xymatrix{
\
&L
\ar@{->}[dl]_{u}
\ar@{->}[dr]^{f}
 \\
X
\ar@{->}[rr]_{\phi = fu^{-1}}
&\
&k
}
\]
where $\cone(u) \in \Sc_\alpha(A)$.  As $\phi$ is an isomorphism we also get
$\cone(f) \in \Sc_\alpha(A)$.  Notice
$$\alpha \notin \Vc(\cone(f)) \cup \Vc(\cone(u)).$$
As $\Vc(H) = \{\alpha \}$, it follows from \ref{supp}(2)  that
for $j \geq 1$ we have
$$ \Tor^A_j(H, \cone(u)) = \Tor^A_j(H, \cone(f)) = 0. $$

We have a short exact sequence of $A$-modules
$$ 0 \rt L \rt F \oplus k \rt \cone(f) \rt 0, \quad \text{where $F$ is a free $A$-module}.$$
It follows that
$$\Tor^A_1(L, H)  \cong \Tor^A_1(k, H). $$
Similarly we obtain
$$\Tor^A_1(L, H)  \cong \Tor^A_1(X, H). $$
Let $r = \mu(H)$.  As $H$ is indecomposable it has no free summands. So \\ $\Tor^A_1(k, H) = k^r$. Therefore   $\Tor^A_1(X, H) = k^r$.
As $H \cong  \Omega(H)$, we have an exact sequence
\begin{equation*}
 0 \rt H \rt A^r \rt H \rt 0.
\end{equation*}

So we have an exact sequence
$$ 0 \rt \Tor^A_1(X, H) \rt H\otimes X  \rt X^r \rt  H\otimes X \rt 0.$$
Therefore
\[
r + r\ell(X) = 2 \ell(H\otimes X).
\]
As $\ell(X) = 0 \mod(\ell(A))$ we get that $\ell(X)$ is even. So by the above equation we get $r = \mu(H)$ is even. This is a contradiction.
 Thus $G_0(\T) \neq 0$ and the result follows.
\end{proof}

\section{Proof of Theorem \ref{m2}}
