\section{Technical Lemmas for MC}\label{app:MC}
In order to control the truncation error, we modify the approach taken in Lemma C.1 from the supplement of \cite{tang2021laplace}. 
\begin{lemma} 
    \label{lemma:A-trunc}
    Under Assumption \ref{assn:hess}, for $\gamma^2_n = t(n)/(\eta_1n)$, for any sequence $t(n)\rightarrow \infty$ and any fixed $p$, we have
    \*[
        \int_{ B^C_{\maximizer}(\gamma_n) \cap B_{\maximizer}(\delta_{n,p}) }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta &= O(n^{-p/2}\exp\{pt(n)/(2 + \epsilon)\})\\
    \frac{\int_{ B^C_{\maximizer}(\gamma_n) \cap B_{\maximizer}(\delta_{n,p}) }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta}{\int_{ \mathbb{R}^d }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta}  &=
    O(\exp\{pt(n)/(2 + \epsilon)\}),
    \]
    for every $\epsilon > 0$.
    Under the same assumptions with $p \rightarrow \infty$, and $(\gamma^\prime_n)^2 = t(n)p/(\eta_1n)$
    \*[
        \int_{ B^C_{\maximizer}(\gamma_n) \cap B_{\maximizer}(\delta_{n,p}) }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta &= O(n^{-p/2}\exp\{pt(n)/(2 + \epsilon)\})\\
    \frac{\int_{ B^C_{\maximizer}(\gamma_n) \cap B_{\maximizer}(\delta_{n,p}) }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta}{\int_{ \mathbb{R}^d }  \exp\{  l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta}  &=
    O\left\{ \left(\frac{\eta_1}{\eta_2}\right)^p \exp\{pt(n)/(2 + \epsilon)\right\}.
    \]
    \end{lemma}
\begin{proof}
    We first upper bound the numerator. Let $A = B_{\zerop}(\delta_{n,p})$, and $D = B_{\zerop}(\gamma_n)$
    \[
    & \int_{ B^C_{\maximizer}(\gamma_n) \cap B_{\maximizer}(\delta_{n,p}) }  \exp\{ l_n(\theta' ; X_n)  - l_n(\maximizer ; X_n)  \} d\theta' \nonumber \\
    &\leq \int_{ D^C \cap A }  \exp\left\{-\frac{1}{2}\theta^\top l_n^{(2)}(\tilde{\theta}) \theta   \right\} d\theta \label{eq:lemma1_lp},
    \]
    by a change of variable $\theta = \theta' - \maximizer$ and where $\tilde{\theta} = \tau(\theta)\theta + \{1 - \tau(\theta) \} \maximizer$, for $0 \leq \tau(\theta) \leq 1$. By Assumption \ref{assn:hess}, 
    \*[
    (\ref{eq:lemma1_lp})  &\leq    \int_{A \cap D^C}  \exp\left(-\frac{\eta_1 n}{2} \theta^\top \theta   \right)  d\theta \\
    &\leq\int_{D^C} (2\pi)^{p/2}  \det\{ \eta_1 I_p/n \}^{1/2}  \phi(\theta ; 0, \eta_1 I_p/n)  d\theta \\
    &= \left(\frac{2\pi\eta_1}{n} \right)^{p/2} \mathbb{P} \left[\chi^2_p \geq n \eta_1 \gamma_n^2  \right] =  \left(\frac{2\pi\eta_1}{n} \right)^{p/2} P\left[\chi^2_p/p \geq 1+ \zeta_n \right],
    \]
    where $\zeta_n = n\gamma^2_n \eta_1/p - 1$, and the region of integration was changed to a larger one by using $D^C$ instead of $A \cap D^C$. By Lemma 3 in \cite{Fan},
    \begin{align*}
        P\left[\chi^2_p/p \geq 1+ \zeta_n \right] \leq \exp\left[ \frac{p}{2} \{ \log(1 +\zeta_n) - \zeta_n \}  \right].
    \end{align*}
    Now, $n\gamma_n^2\eta_1/p = \log(n) \rightarrow \infty$, 
    so there exists $\epsilon > 0$ and $N_0$ such that $ \log(1 +\zeta_n) - \zeta_n  \leq - t(n)/(1+\epsilon) $ for all $n > N_0$ which implies
    \begin{align*}
         P\left[\chi^2_p/p \geq 1+ \zeta_n \right] \leq  \exp\{ -pt(n)/2(1 + \epsilon) \},
    \end{align*}
    for an $\epsilon > 0$ which can be made arbitrarily small.
    The same argument holds for $\gamma^\prime_n$.

    We now lower bound the denominator:
    \begin{align}
        &\int_{ \mathbb{R}^d }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta \nonumber\\
        &\geq \int_{ B_{\hat\theta_n}(\delta_{n,p}) }  \exp\{ l_n(\theta; X_n)  - l_n(\maximizer ; X_n)  \} d\theta \nonumber\\
        &\geq \int_{B_{\hat\theta_n}(\delta_{n,p})}  \exp\left(-\frac{\eta_2 n}{2} \theta^\top \theta   \right)  d\theta\nonumber\\
        &\geq \int_{B_{\hat\theta_n}(\delta_{n,p})} (2\pi)^{p/2}  \det\{ \eta_1 I_p/n \}^{1/2}  \phi(\theta ; 0, \eta_2 I_p/n) d\theta \geq \frac{1}{2} \left(\frac{2\pi\eta_2}{n} \right)^{p/2}. \label{eq:lower_bound}
    \end{align}
    Combining this lower bound with the upper bound gives the desired result.
\end{proof}    

We bound the Lipschitz constant of the likelihood function within the truncated region:

\begin{lemma}\label{lem:lip}
    For $\gamma^2_n = t(n)/(\eta_1n)$ and $(\gamma^\prime_n)^2 = t(n)p/(\eta_1n)$ the Lipschitz constant of the function $\exp\{ l_n(\theta; Y_n) - l_n(\hat\theta_n; Y_n)\}$ is upper bounded by $\eta_2 (t(n) p /\eta_1)^{1/2}$ and $ p \eta_2 (t(n)/\eta_1)^{1/2}$ respectively on the grid $[\hat\theta_n -\gamma_n, \hat\theta_n +\gamma_n]^p$.
\end{lemma}

\begin{proof}
    For all values of $\theta, \theta^\prime \in B^\infty_{\hat\theta_n}(\gamma_n) $ by a first-order Taylor expansion and noting that the operator norm for a scalar and vector is simply its $L^2$ norm,
    \[
        &\norm{\exp\{ l_n(\theta; Y_n) - l_n(\hat\theta_n; Y_n)\} - \exp\{ l_n(\theta^\prime; Y_n) - l_n(\hat\theta_n; Y_n)\}}_{op} \nonumber\\
        &= \norm{ (\theta - \theta^\prime)^\top \frac{\partial}{\partial\theta} l_n(\tilde{\theta}; Y_n) \exp\{ l_n(\tilde{\theta}; Y_n) - l_n(\hat\theta_n; Y_n)\}}_{op}\nonumber\\
        &=\norm{(\theta - \theta^\prime)^\top \frac{\partial^2}{\partial\theta\partial\theta^T} l_n(\tilde{\theta}^\prime; Y_n) (\tilde\theta - \hat\theta_n) \exp\{ l_n(\tilde{\theta}; Y_n) - l_n(\hat\theta_n; Y_n)\}}_{op}\nonumber\\
        &\leq \norm{\theta - \theta^\prime}_2 \norm{\tilde\theta - \hat{\theta}_n}_2 \norm{\frac{\partial^2}{\partial\theta\partial\theta^T} l_n(\tilde{\theta}^\prime; Y_n)}_{op} \exp\{ l_n(\tilde{\theta}; Y_n) - l_n(\hat\theta_n; Y_n)\} \label{eq:lemma_lip1}.
    \]
    We now bound each term in \eqref{eq:lemma_lip1} separately. Note that $\theta, \theta^\prime, \tilde\theta, \tilde\theta^\prime$ all lie within $B^\infty_{\hat\theta_n}(\gamma_n)$ hence
    \[
         \norm{\tilde\theta - \hat{\theta}_n}_2 \leq p^{1/2}\gamma_n \label{eq:lemma_lip2}\\
        \norm{\frac{\partial^2}{\partial\theta\partial\theta^T} l_n(\tilde{\theta}^\prime; Y_n)}_{op} \leq \eta_2 n,\label{eq:lemma_lip3}\\
        \exp\{ l_n(\tilde{\theta}; Y_n) - l_n(\hat\theta_n; Y_n)\} \leq 1 \label{eq:lemma_lip4}
    \]
    combining \cref{eq:lemma_lip2,eq:lemma_lip3,eq:lemma_lip4} gives
    \*[
    \cref{eq:lemma_lip1} \leq \norm{\theta - \theta^\prime}_2 \frac{ \eta_2\{npt(n)\}^{1/2} }{\sqrt{\eta_1}},
    \]
    for $\gamma_n$ while for $\gamma_n^\prime$ we can repeat the argument to obtain
    \*[
    \cref{eq:lemma_lip1} \leq \norm{\theta - \theta^\prime}_2 \frac{ \eta_2\{nt(n)\}^{1/2} p }{\sqrt{\eta_1}}.
    \]
\end{proof}

\section{Technical lemmas for QMC}\label{app:QMC}

\begin{lemma}\label{lem:hk-var}
    Under Assumptions \ref{assn:hess} and \ref{assn:partial}, using $\gamma_n^\prime$ with $t(n) = \eta_1 \log(n)/\eta_2$ and $p\geq 3$, then there exists an $N_0$ such that for every $n \geq N_0$
    \*[
        V_{HK}(L_n(\theta)) &\leq (2\gamma_n^\prime)^p \left\{ \frac{D \sqrt{\eta_2p^3\log(n)} }{n^{p(p-1)-1/2} } + B_{p} \frac{D^{(p-1)} (\eta_2\pi p)^{(p+2)/2} }{2^{(p-1)/2}n}+(D\sqrt{\pi})^p \prod_{i = \lfloor p/2 \rfloor}^{p} i \right\},
    \] 
    when the likelihood function is restricted on the grid $[\hat\theta_n -\gamma_n, \hat\theta_n + \gamma_n]^p$. For $p$-fixed, this implies that:
    \*[
        V_{HK}(L_n(\theta)) = O(\log(n)^{p/2} n^{-p/2}),
    \]
    whereas if we allow $p \rightarrow \infty$
    \*[
        V_{HK}(L_n(\theta)) = O\left( \frac{(C')^{(p -1)/2} p^{ (3p + 2)/2 }}{n\log(p+1)^p} \right),
    \]
    for some constant $C > 0$.
\end{lemma}

\begin{proof}
    We bound the HK variation using 
    \*[
    V_{HK}(f) \leq (2\gamma_n^\prime)^p \sum_{\alpha \subset \mathcal{P}\{1,2,\dots, p\}-  \emptyset} \int_{[0,1]^p} \frac{\partial^{|\alpha|}}{\partial x_{\alpha}} f(x_\alpha, 1_{-\alpha}) dx_{\alpha}.
    \]
    We bound the terms in the sum on case-by-case basis based on the cardinality of $\alpha$. 
    \\
    \textbf{Case 1:} First consider if $|\alpha| = 1$, by the chain rule
    \*[
        &\sum_{i = 1}^p \int_{[0,1]} \frac{\partial}{\partial x_i} f(x_i, 1_{-i}) dx_{i} \\
        &= \sum_{i = 1}^p \gamma_n \int_{[0,1]} \frac{\partial l_n\{2\gamma_n(x_i -1/2), \gamma_n\dot1_{-i}\}}{\partial x_i} \\
        \quad &\times \exp\{ l_n\{2\gamma_n(x_i -1/2) + \hat\theta_{n,i}, \gamma_n\dot1_{-i}+ \hat\theta_n\} - l_n\{\hat\theta_{n,i}, \hat\theta_n\}\} dx_{i}\\
        &\leq \sum_{i = 1}^p \gamma_n \exp\left\{ -p(p - 1)\log(n)  \right\} \int_{[0,1]} \frac{\partial l_n\{2\gamma_n(x_i -1/2), \gamma_n\dot1_{-i}\}}{\partial x_i} dx_{i}\\
        &\leq D p^{3/2}n^{1/2}\eta_2^{1/2}\log(n)^{1/2} \exp\left\{ -p(p - 1)\log(n)  \right\}\\
        &= \frac{D \sqrt{\eta_2p^3\log(n)} }{n^{p(p-1)-1/2} },
    \]
    by Lemma \ref{lemma:exp_diff} and Assumption \ref{assn:partial}.

    \textbf{Case 2:} Should $p \geq 3$, consider any $\alpha$ such that $|\alpha| = k$ and $1 < |\alpha| \leq p - 1$ ,
    \*[
        \sum_{|\alpha| = k} \int_{[0,1]^k} \frac{\partial^{|\alpha|}}{\partial x_{\alpha}} f(x_\alpha, 1_{-\alpha}) dx_{\alpha} \leq {{p}\choose{|\alpha|}} \max_{|\alpha| = k} \int_{[0,1]^k} \frac{\partial^{|\alpha|}}{\partial x_{\alpha}} f(x_\alpha, 1_{-\alpha}) dx_{\alpha}.
    \]
    From the multivariate Faa di Bruno formula for every $k < p$
    \begin{align*}
        \frac{\partial^k }{\partial\theta_{i_1}\cdots \partial\theta_{i_k} } f(x_\alpha, 1_{-\alpha}) &= (\gamma_n^\prime)^{k} \sum_{A \in \Pi} \exp\{l_n(x_\alpha, 1_{-\alpha}) - l_n(x_\alpha, 1_{-\alpha})\} \prod_{B \in A} \frac{\partial^{|B|}l_n(x_\alpha, 1_{-\alpha})}{\prod_{j \in B} \partial\theta_{j} }\\
        &\leq (\gamma_n^\prime)^{k} \exp\left\{ -\frac{\eta_2t(n)(p - |\alpha|)}{\eta_1}  \right\} \sum_{A \in \Pi} \prod_{B \in A} \frac{\partial^{|B|}l_n(x_\alpha, 1_{-\alpha})}{\prod_{j \in B} \partial\theta_{j} } ,
    \end{align*}
    where $\Pi$ is the collection of all possible partitions over the set $(i_1,\dots, i_k)$, $B$ is the collection of all blocks of a partition $A$, and the inequality follows from Lemma \ref{lemma:exp_diff}. Noting the order of the product term increases as the number of blocks increases, we have
    \[\label{eq:case2}
        \left| \sum_{A \in \Pi} \prod_{B \in A} \frac{\partial^{|b|}l_n(x_\alpha, 1_{-\alpha})}{\prod_{j \in B} \partial\theta_{j} } \right| \leq  B_k D^k n^{k},
    \]
    where $B_k$ is the $k$-th Bell number, which counts the number of total of possible partitions of a set of size $k$. Meaning that
    \[\label{eq:case2-final}
    &\sum_{|\alpha| = k} \int_{[0,1]^k} \frac{\partial^{|\alpha|}}{\partial x_{\alpha}} f(x_\alpha, 1_{-\alpha}) dx_{\alpha} \\
    &\leq {{p}\choose{k}} (\gamma_n^\prime)^{k} \exp\left\{ -p(p - k)\log(n)  \right\} 
     B_k (Dn)^{k} \int_{[0,1]^k} \exp\left( - 2\log(n) \left\lVert x_\alpha - \frac{1}{2} \right\rVert_2^2 \right) d X_\alpha\nonumber\\
    &\leq {{p}\choose{k}} \frac{D^k n^k (\eta_2\log(n) p)^{k/2} B_k}{n^{p(p - k)}} \left(\frac{\pi}{2\log(n)} \right)^{k/2} = {{p}\choose{k}} \frac{ D^k p^{k/2} B_k (\eta_2\pi)^{k/2} }{2^{k/2}n^{p(p - k) - k}},\nonumber
    \]
    therefore
    \*[
       \sum_{k = 2}^{p-1} \sum_{|\alpha| = k} \int_{[0,1]^k} \frac{\partial^{|\alpha|}}{\partial x_{\alpha}} f(x_\alpha, 1_{-\alpha}) dx_{\alpha} &\leq \sum_{k = 2}^{p-1} {{p}\choose{k}} \frac{D^k B_k (\eta_2 p\pi)^{k/2} }{2^{k/2}n^{p(p - k) - k}}\\
       &\leq  B_{p} \frac{D^k (\eta_2\pi p)^{(p+2)/2} }{2^{(p-1)/2}n},
    \]
    where the last inequality follows from the identity:
    \*[
       \sum_{k = 2}^{p-1} {{p}\choose{k}} B_k \leq p \sum_{k = 1}^{p - 1} {{p-1}\choose{k}} B_k = p B_{p}.
    \]
    \textbf{Case 3:} Finally for $\alpha = \{1,2,\dots, p\}$
    \*[
        &\int_{[0,1]^p}  \frac{\partial^{p}}{\partial x_1 \partial x_2 \cdots x_p} f(\bold{x}) d\bold{x} \\
        &= \int_{[0,1]^p} \gamma_n^{p}  \exp\{l_n(2\gamma_n( x -1/2) + \hat\theta_n) - l_n(\hat\theta_n)\} \sum_{A \in \Pi} \prod_{B \in A} \frac{\partial^{|b|}l_n(x_\alpha, 1_{-\alpha})}{\prod_{j \in B} \partial\theta_{j}}     d\bold{x}
        \]
    where the term with the largest order is the partition which separates every variable into its own block:
    \[
         &\left|\int_{[0,1]^p} \prod_{i = 1}^p \frac{\partial l_n(2\gamma_n(x - 1/2 ) + \hat\theta_n)}{\partial x_i} \exp\left\{ l_n\{2\gamma_n(x -1/2) + \hat\theta_{n}\} - l_n(\hat\theta_{n}) \right\} d\bold{x} \right|\nonumber \\
         &\leq \int_{[0,1]^p} \left(2D \eta_2 p\log(n)  \right)^{p}  \left\lVert(x - 1/2) \right\rVert_2^p \exp\left\{ -2p\log(n)\lVert x - 1/2 \rVert_2^2  \right\} d\bold{x}\nonumber \]
         \newpage
         \[
         &\leq  \frac{\{\sqrt{\pi} 2D p\log(n)\eta_2\}^{p} }{\{4p\log(n) \}^{p/2}} \int_{[0,1]^p} \left\lVert(x - 1/2) \right\rVert_2^p \frac{\{4p\log(n) \}^{p/2}}{\pi^{p/2} } \exp\left\{ -2p\log(n)\lVert x - 1/2 \rVert_2^2  \right\} d\bold{x}\nonumber \\ \label{eq:case3}
         &\leq  \left( D\sqrt{\pi \eta_2 p\log(n)} \right)^p E_{X \sim N(1/2, 4p\log(n)I_p)}\left[\lVert X - 1/2 \rVert_2^p \cdot I\{X \in ([0,1]^p)^C\} \right]\nonumber \\
         &\leq (D\sqrt{\pi})^p \prod_{i = \lfloor p/2 \rfloor}^{p} i ,
    \]
    where we used Lemma \ref{lemma:chisqured} and the fact that
    \*[
        \left\lVert \frac{\partial l_n(2\gamma_n(x - 1/2 ) + \hat\theta_n)}{\partial x_i} \right\rVert_2 &= \left\lVert\gamma_n^\prime \frac{\partial l_n( \hat\theta_n)}{\partial \theta_i} + 2(\gamma_n^\prime)^{2} \frac{\partial^2 l_n( \tilde{x}+\hat\theta_n)}{\partial\bold{x}\partial x_i} (x - 1/2)\right\rVert_2 \\
        &\leq \left\lVert 2(\gamma_n^\prime)^{2}\right\rVert_2 \left\lVert \frac{\partial^2 l_n( \tilde{x}+\hat\theta_n)}{\partial\bold{x}\partial x_i}\right\rVert_2 \left\lVert(x - 1/2) \right\rVert_2 \leq 2D\eta_2 p\log(n)\left\lVert(x - 1/2) \right\rVert_2,
    \]
    since the derivative when evaluated at the posterior mode is $0$, meaning that
    \[
        \int_{[0,1]^p}  \frac{\partial^{p}}{\partial x_1 \partial x_2 \cdots x_p} f(\bold{x}) d\bold{x} \leq  B_p \left\{ (D\sqrt{\pi})^p \prod_{i = \lfloor p/2 \rfloor}^{p} i \right\} .
    \]
    Combining all these terms together produces 
    \[
        V_{HK}(L_n(\theta)) & \leq (2\gamma_n^\prime)^p \left\{ \frac{D \sqrt{\eta_2p^3\log(n)} }{n^{p(p-1)-1/2} } + B_{p} \frac{D^{(p-1)} (\eta_2\pi p)^{(p+2)/2} }{2^{(p-1)/2}n}+ B_p (D\sqrt{\pi})^p \prod_{i = \lfloor p/2 \rfloor}^{p} i \right\},
    \]
    which gives the desired bound.
    If $p$ is fixed, then this function is $O(1)$.
    As for the order of this function as $p\rightarrow \infty$, noting that $B_{p} < (p/\log(p+1))^p$ and that the falling factorial
    \*[
        \prod_{i = \lfloor p/2 \rfloor}^{p} i &\leq p^{\lfloor p/2 \rfloor}\exp\left(- \frac{\lfloor p/2 \rfloor(\lfloor p/2 \rfloor - 1)}{2p} \right)\\
        &\leq p^{ p/2 }\exp\left(- \frac{ (p/2 - 1) ( p/2  - 2)}{2p} \right)
    \]
    these facts imply
    \*[
       &B_{p } \frac{C^{(p-1)}  p^{(p+2)/2} }{n}+B_p (D\sqrt{\pi})^p \prod_{i = \lfloor p/2 \rfloor}^{p} i \\
        &\leq \frac{p^{p}}{n \log(p+1)^p}C^{(p-1)}  p^{(p+2)/2} +\frac{(D\sqrt{\pi})^p p^{ 3p/2 }}{\log(p+1)^p} \exp\left(- \frac{ (p/2 - 1) ( p/2  - 2)}{2p} \right)  \\
        &\leq \frac{(C')^{(p -1)/2} p^{ 3p/2 +1 }}{\log(p+1)^p} \left\{\frac{1}{n} + p^{-1}\exp\left(- \frac{ (p/2 - 1) ( p/2  - 2)}{2p} \right) \right\}\\
 &=O\left( \frac{(C')^{(p -1)/2} p^{ (3p + 2)/2 }}{n\log(p+1)^p} \right),
    \]
    for some $C^\prime > 0$, the result now follows.
\end{proof}

