\begin{lemma}\label{lemma:exp_diff}
    Under Assumptions \ref{assn:hess} and \ref{assn:partial} for $|\alpha| < p$
    \*[
    \exp\{ l_n\{2\gamma_n(x_\alpha -1/2) + \hat\theta_{n,\alpha}, \gamma_n\dot1_{-\alpha}+ \hat\theta_{-\alpha}\} - l_n(\hat\theta_{n})\} \leq \exp\left\{ -\frac{\eta_2 t(n)(p - |\alpha|)}{\eta_1}  \right\} .
    \]
\end{lemma}

\begin{proof}
    By a second-order Taylor expansion:
    \*[
        &l_n\{2\gamma_n(x_\alpha -1/2) + \hat\theta_{n,\alpha}, \gamma_n\dot1_{-\alpha}+ \hat\theta_{-\alpha}\} - l_n(\hat\theta_{n}) \\
        &\leq(2\gamma_n(x_\alpha -1/2), \gamma_n \cdot 1_{-\alpha})^\top \frac{\partial^2 l_n\{\tilde{\theta} \}}{\partial\theta^\top \partial\theta} (2\gamma_n(x_\alpha -1/2), \gamma_n \cdot 1_{-\alpha})\\
