def removeElement_pre (s : Array Int) (k : Nat) : Prop :=
  k < s.size -- the index must be smaller than the array size

-- Post-condition
def removeElement_post (s : Array Int) (k : Nat) (result: Array Int) (h_precond : removeElement_pre s k) : Prop :=
